INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit', 'vakit-sahin-erturk-23s8l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonbahar''a Vakit mi Var

Ölüm yaşam arası dar 

Nerde kaldın vefasız yar 

Hani mart ta gelecektin 

Sonbahar''a vakit mi var? 

Kaçıyorsun köşe bucak 

Bir dargınız bir barışık 

Hasret beni öldürecek 

Sonbahar''a vakit mi var? 

İlkbahar yaz sonbahar kış 

Soldu yüzüm buruş buruş 

El tutmuyor göz görmüyor 

Sonbahar''a vakit mi var? 

Sensiz geçti yine bu ay 

İşin yoksa ayları say 

Saça yağdı zamansız kar 

Sonbahar''a vakit mi var? 

Beyin yorgun kalp tekliyor 

Ölüm yaşam arası dar 

Nerde kaldın vefasız yar 

Sonbahar''a vakit mi var? 

BOYALI DÜŞLER 

ADLI ŞİİR KİTABIMDAN', 'Sonbahar''a Vakit mi Var Ölüm yaşam arası dar  Nerde kaldın vefasız yar  Hani mart ta gelecektin  Sonbahar''a vakit mi var?  Kaçıyorsun köşe b...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sonbahar-a-vakit-mi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya''''', 'ruya-ali-riza-unal-zs2u0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen karanlık dünyama nur olursun.

Bazende çölde, hülyaya dür olursun.

Bazende zalım sevgiliye, hür olursun.

Ne cilveyi sırsın. bilmişim seni rüya.

Bazen en kötü zanıma şen olursun.

Bazende bin ömre bir an olursun

Bazende harama helâl dem olursun.

Bu nedir, kahır ile cümbüşe haz rüya.

Bazen yiğidi civana bayram, zifaf olursun.

Bazende ne ettiğin belirsiz tuhaf olursun

Bazende garip şeytana iftira olursun..

Hiç yoktan iyidir, uykuya yoldaşsın rüya.

Yatanmıyım yatakta? , gezenmiyim ayakta? .

Gâh seyranım. arş’tanda öte semâvatta.

Gah üç beş akçe için dilenciyim sokakta.

Vurmuşum teline mızrabı, hazzım’sın rüya

Bazen züğürt ağaya, sultan olursun.

Bazende hain sultana külhan olursun.

Ali Rıza sen bu rüyaya, çok laf bulursun,

Kalmadı zahirden farkın,ayığım sana rüya', 'Bazen karanlık dünyama nur olursun. Bazende çölde, hülyaya dür olursun. Bazende zalım sevgiliye, hür olursun. Ne cilveyi sırsın. bilmişim se...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ruya-164-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyi Bilmiyorsun', 'sevmeyi-bilmiyorsun-sahin-erturk-dujcn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daldan,dala konuyorsun

Gördüğüne söylüyorsun

Hiç ciddiye almıyorsun

Sen sevmeyi bilmiyorsun

Ahte vefa göstermedin

Dudağınla zehir saçtın

Aşkımıza mezar kazdın

Sen sevmeyi bilmiyorsun

Seninkisi reklam aşkı

Aşkta olmaz kural dışı

Yine yaptın bak yanlışı

Sen sevmeyi bilmiyorsun', 'Daldan,dala konuyorsun Gördüğüne söylüyorsun Hiç ciddiye almıyorsun Sen sevmeyi bilmiyorsun Ahte vefa göstermedin Dudağınla zehir saçtın Aşk...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmeyi-bilmiyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akan Yaşımda', 'akan-yasimda-huseyin-sigirtmac-yw9dz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yare ulaşmaya yetmedi hızım.

Yine hayaldeyim, yol çeker gözüm.

Engeller çoğaldı, umutsuz arzum.

Düştüm efkarına hasret başımda.

Hüznüm neşe olsun tüm sevenlere.

Mutluluklar olsun yar diyenlere.

Kavuşmak isterken dost, yarenlere.

Düştüğüm yollarda engel karşımda.

Ayrılık rüzgarı savurdu beni.

Gurbete sürerek ayırdı beni.

İçimdeki hasret kavurdu beni.

Tutuşur arzular alev döşümde.

Sığırtmaç’ı eş, dost bıraktı yalnız.

Kararan duygumda ışıksız yıldız.

Hasret yüreğimi tüketir sessiz.

Dost hayali yaşar akan yaşımda.

Bursa 18/02/2005', 'Yare ulaşmaya yetmedi hızım. Yine hayaldeyim, yol çeker gözüm. Engeller çoğaldı, umutsuz arzum. Düştüm efkarına hasret başımda. Hüznüm neşe ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/akan-yasimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yıkanıyor', 'gece-yikaniyor-kemal-cakir-oe4p1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ay karanlık bir gün ve yalnız bir gece

Meltem bir şeyler söylüyordu sahile

Deniz durgundu, şimdi sarhoş gibice

Gecenin saçlarını ıslatıyor gizlice.

Dayanamayıp gece, yarı çıplak bir halde

Bulutların altından indi gizlice sahile

Güzel yerlerini gizleyip elleriyle, ilerledi 

Sarmaş dolaş oluverdi, az sonra denizle.

Sonra, pişman olduğunu söyleyerek

Yavaş yavaş büründü görünmezliğe

Meltem durdu, deniz duş alıp çekildi köşesine

Gece ise ıslak bir halde diz çöktü gündüze.', 'Ay karanlık bir gün ve yalnız bir gece Meltem bir şeyler söylüyordu sahile Deniz durgundu, şimdi sarhoş gibice Gecenin saçlarını ıslatıyor g...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gece-yikaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayıp Ettin', 'ayip-ettin-mustafa-bilgic-1lcla', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayıp ettin! 

Delikanlılık dedin mi dur orda.

Erkekliğin kitabını yazmışız,

Dürüstlük boyun farzı, 

Yedirmeyiz kuşa kurda! 

Ayıp ettin! 

Girmez boğazımızdan haram lokma.

Alın teri dökeriz kazanmak için,

Az da olsa alırız üç beş kuruş,

Kahvehane, lokal, barlarda...

Ayıp ettin! 

Konuşuruz aramızda sizli bizli.

İşimiz gayet normal ve o kadar da sakin,

Ne gasp, ne soygun, ne de dolandırıcılık,

Devletten para çekeriz gizli gizli...

Ayıp ettin! 

Bakmayız elalemin namusuna falan.

Söz namus demektir anladın mı? 

Belki birkaç yıl gecikebilir,

Ama yoktur yalan dolan...

Ayıp ettin! 

Sayılmazki yaptığımız iş faiz.

Bankaya para yatırırız sadece.

Çekeriz günü geldimi

Olursa kriz mriz...

Ayıp ettin! 

Boşuna arama bizi uzaklarda.

Bazen sosyetenin en güzel yerinde,

Bazense devletin kanatları altında! 

Hep koruruz kendimizi buralarda...

23.06.2002', 'Ayıp ettin!  Delikanlılık dedin mi dur orda. Erkekliğin kitabını yazmışız, Dürüstlük boyun farzı,  Yedirmeyiz kuşa kurda!  Ayıp ettin!  Girm...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgiç']::text[], 8.5, '{"poet":"Mustafa Bilgiç","poet_slug":"mustafa-bilgic","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ayip-ettin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demokrasiyi Öldürmek', 'demokrasiyi-oldurmek-kemal-cakir-oqmv2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimimize göre hala bizde demokrasi yok,

Bu nedenle devamlı ezilip duruyoruz.

Kimimize göre ise bu demokrasi bize çok,

Bu nedenle her an öldürmeye çalışıyoruz.', 'Kimimize göre hala bizde demokrasi yok, Bu nedenle devamlı ezilip duruyoruz. Kimimize göre ise bu demokrasi bize çok, Bu nedenle her an öldü...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/demokrasiyi-oldurmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç', 'hic-ozgur-kokturk-qkpxv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceye esir edersin düşlerini

Düşlerin sonsuzluğuna savrulursun

Bir hiç olur bir gün sevdan

Sevdanın hiçliğinde kaybolursun

Her anı sürükler gizleri

Zamansız yağmurlar boşanır bulutsuz göklerden

Sen olursun bulutsuz yağmur içindeki

Yataksız nehir,

Yanmamış kül gibi

Senden sıyrılan ben kalır gizin özündeki

Yarıda kalır bütün öykülerin

Bütün kitapların okunmamış

Yazılmamış hiç şiirin

Resmin hiç çizilmemiş

Bir tek gecen yok ki dile gelmemiş

Bir çığlık kaplar ıssız adımlarını

Neşede bile hüzünlere boğulursun

Sıcak ezgilerin ağıtlara gömülür

Susarsın, suskunluğundan kovulursun

İçten içe ürperirsin

Titrersin derinden derine

İnatlaşırsın geceyle, günle

Çağırmaz ki gece kimseyi

Gün doğmaz ki şafaksız

Tenhası kalmaz hiçbir serseri limanın

Başıboş deniz de kucaklamaz seni

Boğamaz...

Yorgun düşer kederin, çaresizliğin

El değmemiş hayallerin gezer ayaklar altında

Yırtılır gözkapakların isyanından

Çıldırır gözbebeklerin usancından

Son bir nefesle solursun

Üç kelime dökülür dudaklarından

Neyse o olsun!', 'Geceye esir edersin düşlerini Düşlerin sonsuzluğuna savrulursun Bir hiç olur bir gün sevdan Sevdanın hiçliğinde kaybolursun Her anı sürükler...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/hic-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtimal Hesabı', 'i-htimal-hesabi-cigdem-bir-genc-13jzf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bulut değilim

yağamam  yağmur olup evrenine

sen koca bir dev...

ben çayırların arasına gizlenmiş cüce...   

ne kadar anlamsız olduğunu bile bile

zaferleri düşledim 

her seferde 

öznesiz tümceler gibi başıboş

ve yelesiz bir tay gibi çırçıplak

kalabilirim

aşk bu

bir şiir yazarım en nihayetinde...', 'bulut değilim yağamam  yağmur olup evrenine sen koca bir dev... ben çayırların arasına gizlenmiş cüce...    ne kadar anlamsız olduğunu bile ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ihtimal-hesabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Hayaliyle Yaşanır', 'dost-hayaliyle-yasanir-mehmet-yucel-karaciga-xr0ia', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen uzaklarda, bense yalnız başıma burda

oysaki  olmak isterdim her an yanında.

ama nafile aramızda 100 lerce km

Sana ulaşmak seninle yan yana olmak,

İstanbul sokaklarında dolaşmak

bir lokantada beraberce yemek yemek

bir pastanede saatlerce sohbet etmek

dertleri paylaşmak,

hüzünlerimizle hüzünlenmek,

gül açan gülücüklerimizle beraber gülmek

Üsküdar da tam kız kulesi karşısında

oturup o parkın banklarına

seyretmek saatlerce...

Gülhane parkında oturup,

o tarihi surlarla kaplı çay ocağına,

deniz manzarasında semaver sohbetine dalmak, 

ordan buradan laflarla.

Yada Eminönün de balık ekmek yemek

Yanında bir bardak turşu suyuyla...

Dedim ya 

Dost hayaliyle yaşanır diye,

Dostların ne çok paylaşacakları şey var

Değilmi dünyada,

Arada mesafeler uzak olsa da,

ne isterdim biliyor musun? bu yazıyı yazdığım şu 

yalnızlığımda,

orda olabilmek, yazı yerine 

seninle hep sözle muhabbet edebilmek.

Dedim ya

Dost hayaliyle yaşanır diye.', 'Sen uzaklarda, bense yalnız başıma burda oysaki  olmak isterdim her an yanında. ama nafile aramızda 100 lerce km Sana ulaşmak seninle yan ya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel Karaciğa']::text[], 8.5, '{"poet":"Mehmet Yücel Karaciğa","poet_slug":"mehmet-yucel-karaciga","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dost-hayaliyle-yasanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Benim', 'gece-benim-mehmet-yucel-karaciga-0satc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin derin karanlığında

Dikmişim gözlerimi yıldızlara

Bin bir türlü düşünceler

Dolaşırken duygularımda

Gece benim

Ben geceyim

Ya sen gel geceye

Ya da izin ver 

Gece gece ben geleyim sana', 'Gecenin derin karanlığında Dikmişim gözlerimi yıldızlara Bin bir türlü düşünceler Dolaşırken duygularımda Gece benim Ben geceyim Ya sen gel ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel Karaciğa']::text[], 8.5, '{"poet":"Mehmet Yücel Karaciğa","poet_slug":"mehmet-yucel-karaciga","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gece-benim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Riya ''', 'riya-ali-riza-unal-lcxp9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç dürüst işin, olmazmı acı kendine riya.

Kul yesede yutmuyor Allah bilmezmi riya.

Sende bu takıntı, hiç bitmezmi be riya.

Ayranın yok içmeye, paytondur bineğin riya.

İpek göynek ile donun, bit pazarında riya,

Merkebin sömeri değişir ama merkeptir riya

Düşmana göster haddini her sıkıdan riya.

Dosta bu halin garip ihanet ayıptır riya.

Sana bu laflar faydasız, zaten riyasın riya.

Kandırırsın güzeli, ucuz makyaja riya.

Sıska leylânın gönlü güzel, teni deyil riya.

Kudret üstüne çektin sürmeyi, yetmzemi riya.

Gezdim şu alemi, açtada varsın, toktada riya.

Bu abdi aciz Rızaya, bilirim çok tavsın riya.

İki çıplağın halini hamamda gördüm riya.

Hiç sulanma boşuna avucunu yalarsın riya.', 'Hiç dürüst işin, olmazmı acı kendine riya. Kul yesede yutmuyor Allah bilmezmi riya. Sende bu takıntı, hiç bitmezmi be riya. Ayranın yok içme...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/riya-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BoŞLuKTaN DoĞaR GeRÇeKLeR...!', 'bosluktan-dogar-gercekler-utku-demir-adz7f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boşluğun devingen derinliği

Kayıp zamanlar içine yaymıştır kendini

Gökten yere çakılırcasına

Engellenemez bu uğultunun çekimi

Hayatın göreli sakinliği

Dönüşmektedir sürekli dalgalı bir denize

Kesilmez bir düşünce akımı

Saç telinden parmaklara gelgittedir

Kramplar girerken tüm organlarınıza

Ritmik atamaz olur hasarlı kalbiniz

Yeterince beslenemez çatlak damarlarla

Kapatırsınız kendinizi fare deliklerine

Akıp gitmektedir durağan sandığınız zaman

Gerçek kendinizi oluşturursunuz boşlukta

Hiçlikten kurtulma yolunda

Anne karnında gibisinizdir aslında

Çıkmak sizin elinizdedir oysa burdan

Baş aşağı kalırsınız dönüp durdukça

Kurtulmak umuduyla,yıllardır bunaldığınız sığınaktan

Kimse anlamaz sizin sessiz agularınızı

Duyuramazsınız içinizde yankılanan ıngalarınızı

Kıvranır durursunuz yapışkan sancılarda

Farklılıklarla donatılır bütün kimliğiniz

Algılanmayanlar vakumdan çeker sizi içine

Seslerin titreşimlerini hissedersiniz, girerken kulaklarınıza

Cisimlerin donuk halleri,canlanır göz bebeklerinizde

Paylaşabilirsiniz duygularınızı cansız varlıklarla bile

Su sadece akmaz oysa eşlik eder yalnızlığınıza

Toprak fokur fokur kaynamaktadır yer kabuğunda

Hava kabarcıklarıyla sürekli alışveriş gün boyunca

Maskeleri düşer insanların sizin bakışlarınızda

Anlaşılmazlıklar toz olmuştur ruhunuzdan

Acılar sevgiye dönüşür kalbinizde

Kurnaz düşman korkular, firar etmiştir aklınızdan

Gelen dökülür olur dürüstlük abidesi dudaklardan

Aynalarla kurulmuştur göbek bağınız 

Asık suretli karanlık gölgeniz, gülümsemektedir ışıldayarak

Gözünüzden yansımaktadır dumansız duru gönlünüz

Layık olan herkesi düşünür yitmekten dönen bu can

Örümcek ağı sağlamlığında dokuduğunuz benliğiniz

Sabırla direnmektedir yılmaz fırtınalara

Kaya kadar sert ve pamuk kadar yumuşaksınızdır

Yitirirken tüm sahteleri başucunuzdan

Duygu ve değerlerinizle yalnız kalırsınız bir zaman

Gerçekler girebilecektir süzgeç liflerin arasından

Hayalsi güzellikler ortasına da yerleşseniz

Özümser boşluktan çıkan doluluk sizi

Kalbin yayından çıkan sevgi dolu ok

Işık hızında güdümlenmişcesine ulaşır size

Yanağınızdan manidarca okşar geçer

Dokunmak için geri döndüğünde

Açılmış bulmalı kalbinizden küçük bir pencereyi...', 'Boşluğun devingen derinliği Kayıp zamanlar içine yaymıştır kendini Gökten yere çakılırcasına Engellenemez bu uğultunun çekimi Hayatın göreli...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/bosluktan-dogar-gercekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boyalı Düşler', 'boyali-dusler-sahin-erturk-41nin', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beyaz gelinlik giyiyorsun

Evime gelin geliyorsun

Beni sevince boğuyorsun

Boyalı düşler kuruyorum

Yokluğu yendik,paramız var

Güller içinde,evimiz var

Limuzinimiz,yatımız var

Boyalı düşler kuruyorum

Mavi turlara çıkıyoruz

Bodrum,marmaris geziyoruz

Düş gibi yaşam sürüyoruz

Boyalı düşler kuruyorum

Bir oğlumuz var,adı Ozan

Bir kızımız var,adı Özlem

Sözleri mazi yapmıyoruz

Boyalı düşler kuruyorum

Arayanım yok,soranım yok

Elimde kalem yazıyorum

Kara yazgımı boyuyorum

Boyalı düşler kuruyorum', 'Beyaz gelinlik giyiyorsun Evime gelin geliyorsun Beni sevince boğuyorsun Boyalı düşler kuruyorum Yokluğu yendik,paramız var Güller içinde,ev...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/boyali-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmekten Ne Anlarsın', 'sevmekten-ne-anlarsin-sahin-erturk-866vi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aynı dili konuşmadık

Aynı kalpte buluşmadık

Aynı şeyler düşlemedik

Sen sevmekten ne anlarsın

Mutlu birgün yaşamadık

Ömür boyu koklaşmadık

Bir yastıkta yaşlanmadık

Sen sevmekten ne anlarsın

Bıktığında terketmiştin

Olur,olmaz konuşmuştun

Aşka diyet ödetmiştin

Sen sevmekten ne anlarsın

(Boyalı Düşler adlı şiir kitabımdan) 

(29.10.2003-Takvim Gazetesi)', 'Aynı dili konuşmadık Aynı kalpte buluşmadık Aynı şeyler düşlemedik Sen sevmekten ne anlarsın Mutlu birgün yaşamadık Ömür boyu koklaşmadık Bi...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevmekten-ne-anlarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceset', 'ceset-ozgur-kokturk-5ovb9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kin türüküsü dudaklarımda

Dizelerimden kan damlar

Açık bir mezar gibi sırıtır sevdam

Ayaklarım kendiliğinden götürür

Kendine akan sulara inat...

Solar sevdaya çağıran bakışların

Râyihası kalmamış artık özleminin

Bir ceset gibi geçersin yanımdan

Küflenmiş, çürümüş toprak kokar 

Uğruna yaşanası gözlerin

Yüzüme bakacak kadar küstah

Adımların yere basacak kadar utanmaz! ..

Ürkekliğin yas renginde gecelerin

Yaşamsız bir hücreden çıkmışsın

Yorulsan da pişmanlıktan

Dalga dalga suç yayılır çevrene

Tutsak gibisin ihanetin ağına

Pençesine takılmışsın tatminsiz tükenişlerin...

Yürürsün paranoyak mağaralarına unutulmuşluğun

Amatör bir rastlantı olur yaşama sevincin

Ruhun gömütleşir durgunlaşan benliğine

Aramak,

Bulmak

Tasarımı bile değil hayallerinin

Hayallerin soyut bir girdap...

Somut bir serap...

Çıkamazsın sevmelerin bulvarına

Bulvar tehditkâr...

Islah olmaz şaşkınlıklar sarar gecelerini

Geceden bıkmış bir yıldız gibi düşersin

Sen şimdi ne kadar fazla,

Ne kadar eksiksin...

Varlığın onulmaz bir boşluk

Bembeyaz bir kumsalda

Simsiyah bir kumsun

Öldün! 

Unutulmaya mahkumsun! ! ! 

23 / 04 / 2003     23:49', 'Kin türüküsü dudaklarımda Dizelerimden kan damlar Açık bir mezar gibi sırıtır sevdam Ayaklarım kendiliğinden götürür Kendine akan sulara ina...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ceset-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler 1', 'dusler-1-zafer-yazici-6y2mr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşlerim olmalı benim “Sen” ile ilgili! ... 

Hayallerim olmalı geleceğe dair, yine seninle! ...

Sonra kuşlara anlatmalıyım seni

İlk önce beni sevdiğinden bahsetmeliyim

Sonra da nasıl tanıştığımızı anlatmalıyım

ki onlarda bilsinler sevgimizin boyutunu

Sonra bir de seni nasıl özlediğimi anlatayım 

ki bu asabiliğimin sebebini anlasınlar

Anlasınlar ki üstüme gelmesin hiç kimse! ....

Sonra en güzel rüyaları görmeliyim düşlerinde

ve eklemeliyim seni de rüyalarımın en gizli, 

en tatlı ve en bana özel kısımlarına

Sonra sevgin ile avunmayı öğrendiğim gibi

hasret kalmayı da öğrenmeliyim. 

Öğrenmeliyim ki her sabah uyanışlarımda

seni yanımda bulamayışımın sebebini anlayabileyim, 

anlayabileyim ki kendimi kedere ve yasa boğmayayım! ...', 'Düşlerim olmalı benim “Sen” ile ilgili! ...  Hayallerim olmalı geleceğe dair, yine seninle! ... Sonra kuşlara anlatmalıyım seni İlk önce ben...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dusler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler 2', 'dusler-2-zafer-yazici-q0p5i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşlerim olmalı benim “Sana” dair! ... 

En özel saatlerimde seninle olabilmeliyim. 

Gecenin koynunda, kimsecikler yokken ortalıkta 

Ben, sana sarılabilmeliyim içten gelen samimi duygularımla 

Ve öpmeliyim, öpebilmeliyim seni sıcacık! 

Sonra en samimi şeklinle, sen bana sarılmalısın ki 

sevdiğini anlayabileyim beni. 

Ve uğruna nice sevdaları tüketebileyim

Sırf senin için...

Ben sana anlatabilmeliyim özellerimi

ve seninle yaşabilmeliyim ki tanıyabilesin beni, 

Sen bana özellerini anlatmalısın 

ve benimle yaşayabilesin ki ben de seni tanıyabileyim, 

nelerin senin için önemli olduğunu bilebileyim… 

gece seni düşünmeliyim, sen de beni 

ve her anımızın nasıl da güzel geçeceğini hesaplamalıyız. 

Bir ömrün nasıl güzel geçirilebileceğini insanlara anlatabilmeliyiz....

Birlikte, beraberce, bizce! ...', 'Düşlerim olmalı benim “Sana” dair! ...  En özel saatlerimde seninle olabilmeliyim.  Gecenin koynunda, kimsecikler yokken ortalıkta  Ben, san...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dusler-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler 3', 'dusler-3-zafer-yazici-42r1t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşlerim olmalı benim “Senden” yana! ... 

Yan yana uzandığımızda yatağa 

şehrin parlak ışıklarına dalarak hayal kurmalıyız

seninle gelecek üstüne! ...

En parlak ışık bizim olmalı şehirde 

ve biz ona bir isim vermeliyiz geleceğe dair! 

Sonra uyuyakalmalıyız koyun koyuna. 

Sabah gözlerimizi açtığımızda birbirimizi görmeliyiz ilkin. 

Sonra dilersek çıkmalıyız yataktan 

Dilersek, sabah kahvaltısını hazırlamalıyız 

En sade ama en renkli kahvaltıyı! ..

güneşin ilk doğuş anında yapmalıyız 

ki hayatı o yalınlığı ile yaşayabilelim.

Sonra güzel ve demli bir çay ile tellendirmeliyiz sigaramızı.

güzel bir sohbet ve yine gelecek üzerine güzel düşler kurmalıyız seninle. 

Belki gelecekteki aile yaşantımızdan

Olacak çocuklarımızdan  bahsetmeliyiz! ...

Sonra sen şımarmalısın kendince ve

Ben şımarmalıyım yaramaz bir çocuk gibi. 

Her şeyimiz biz olmalı, biz kendimiz olmalıyız, 

bozmamalıyız ne kendimizi, ne düşüncelerimizi, 

ne benliğimizi, ne de sevgimizi! ...', 'Düşlerim olmalı benim “Senden” yana! ...  Yan yana uzandığımızda yatağa  şehrin parlak ışıklarına dalarak hayal kurmalıyız seninle gelecek ü...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dusler-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nu''m', 'nu-m-hediye-cinar-saplr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '...........................

...................................

yüzünde çocuk izleri kalmış, üşümüş bir

tavrın meleği.

kavurgan yel eser savunması muzdarip 

düşmüş... ellerinde

yorgun bakışlar, bir mevt-i sefanın

salınması bedeninde.

bakınıp korkuyla uyandığında

sarılıp sevincine

sadece; esnek bir düşmüş.

.....................

............................

-------', '........................... ................................... yüzünde çocuk izleri kalmış, üşümüş bir tavrın meleği. kavurgan yel eser sav...', ARRAY['Türk Edebiyatı','Şiir','Hediye Çınar']::text[], 8.5, '{"poet":"Hediye Çınar","poet_slug":"hediye-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nu-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madam Geberdin', 'madam-geberdin-hediye-cinar-4w8d7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '..

.........

Madam geberdin! 

Hani hayvani sevgilin? 

Bir boşluğun, bir doldur-muş-luğun,

Alev olmuş

Un ufak olmuş

/havalar iyi olmuş/

her şey görünür olmuş: kör kör

o pencereden....

.............

..................', '.. ......... Madam geberdin!  Hani hayvani sevgilin?  Bir boşluğun, bir doldur-muş-luğun, Alev olmuş Un ufak olmuş /havalar iyi olmuş/ her ş...', ARRAY['Türk Edebiyatı','Şiir','Hediye Çınar']::text[], 8.5, '{"poet":"Hediye Çınar","poet_slug":"hediye-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/madam-geberdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı', 'sari-hediye-cinar-aqack', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerini birbirine hiç değdirmemiş

Kalın gözlü, siyah dilli.. üçüncü sahıs

Bir kargıştan arta kalan, izlenimi:

Asil, mağrur dalgınlıklar.

Ensemde görünmez karanlıkla sever,

karanlıkta öldürür sevgililerini..

........................

.......................................', 'Ellerini birbirine hiç değdirmemiş Kalın gözlü, siyah dilli.. üçüncü sahıs Bir kargıştan arta kalan, izlenimi: Asil, mağrur dalgınlıklar. En...', ARRAY['Türk Edebiyatı','Şiir','Hediye Çınar']::text[], 8.5, '{"poet":"Hediye Çınar","poet_slug":"hediye-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sari-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-deniz-onderoglu-oas7n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ay kadar yalnızım 

Şu yeryüzünde

Ay''ın etrafını milyonlarca yıldız kaplamış

Benim bir tek yıldızım nerede!', 'Ay kadar yalnızım  Şu yeryüzünde Ay''ın etrafını milyonlarca yıldız kaplamış Benim bir tek yıldızım nerede!...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalnizim-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Günaydın Mesajı', 'bir-gunaydin-mesaji-deniz-onderoglu-ol54p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yere düşen yağmur damlaları

Kalbine inecek güneşi engellemesin

Güneş bulutların arasından

Hep sana doğru baksın

Güneş güzellikler getirsin

Günaydın!', 'Yere düşen yağmur damlaları Kalbine inecek güneşi engellemesin Güneş bulutların arasından Hep sana doğru baksın Güneş güzellikler getirsin G...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-gunaydin-mesaji-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-deniz-onderoglu-9dba3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deniz aşktır

Sonunun ne olduğunu bilmediğimiz

Kapılırız sularına

Nereye götüreceğini bilmeden

Bir sahile veya

Bir ıssız adaya bırakır bizi

Plansız hayatımızdır!', 'Deniz aşktır Sonunun ne olduğunu bilmediğimiz Kapılırız sularına Nereye götüreceğini bilmeden Bir sahile veya Bir ıssız adaya bırakır bizi P...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/deniz-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağı', 'gokkusagi-deniz-onderoglu-ug6wk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yedi renk var derler gökkuşağında

Yalan! 

Seninle hergün 

Ayrı gökkuşağı gördüm

Her birinde binlerce renk

Gözlerinde ışıldadı

Baktım gözlerine

Kendimi gördüm', 'Yedi renk var derler gökkuşağında Yalan!  Seninle hergün  Ayrı gökkuşağı gördüm Her birinde binlerce renk Gözlerinde ışıldadı Baktım gözleri...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gokkusagi-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığı', 'ay-isigi-deniz-onderoglu-nwzoz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay ışığı odanı aydınlatsın

Sevgi nehirleri kalbine aksın

Rüzgar kalbine aşk fısıldasın

Mutluluk bir çiçek gibi

Her sabah sana açsın!', 'Ay ışığı odanı aydınlatsın Sevgi nehirleri kalbine aksın Rüzgar kalbine aşk fısıldasın Mutluluk bir çiçek gibi Her sabah sana açsın!...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ay-isigi-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İyi Geceler Mesajı', 'bir-i-yi-geceler-mesaji-deniz-onderoglu-g2vxk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbinin ışığı

Gecenin karanlığını bastırsın

Rüyaların mutluluk yağmurlarında geçsin

Gecen mutlu

Kalbin huzur dolu olsun

İyi geceler!', 'Kalbinin ışığı Gecenin karanlığını bastırsın Rüyaların mutluluk yağmurlarında geçsin Gecen mutlu Kalbin huzur dolu olsun İyi geceler!...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-iyi-geceler-mesaji-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-deniz-onderoglu-5ca7g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Korkunun ülkesinde yarım kalmış bir romandır aşk

Sayfalarının arasında

Hüzün ve yalnızlık olan

Korku hükmeder 

Ve bitiremez kalpler bu romanı

Ürkekliğinden!', 'Korkunun ülkesinde yarım kalmış bir romandır aşk Sayfalarının arasında Hüzün ve yalnızlık olan Korku hükmeder  Ve bitiremez kalpler bu roman...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-336-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin-lik-ler', 'derin-lik-ler-utku-demir-ji1ws', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Derinliklerin çekimiyle kımıldar insan

I.

Kendi derinliklerinden bir uğultu yükselir

Cansız ruhun hayata dönüş çırpınışı

Kırar çelikten kelepçeleri

İlerlemek ister gelen sese doğru

Bir damla kan olur girer damarına

Dolaşır vücudun bütün hücrelerinde

Onlardan taşan duygularla doldurur kendini

II.

Hayatın derinlerine yönelme vaktidir artık

Atlar zaman gemisine didik didik eder her yanı

Okyanusların derinliklerindeki planktonlardan

En ücra yaylalardaki çiçeklere uçar gider

Hiç ayırmaz yıldızlardan gözlerini

Onlara da ulaşma hevesiyle

Takılır kimi zaman bir noktada

Doğanın melodik ezgisine 

Ya da esrarengiz sessizliğine

Derin düşünceler eşliğinde yalnız başına

III.

Gerçeklerin derinliğidir kendini bulmayanları yutan

Oysa ona doğru koşar bir zamanlar ölüme yaklaşan

Delip geçer tüm kalkanları sonsuza uzanan ışınlar

Akıldan geçenleri duyar masum bakışlar

Hiç bir şeyden kaçmayan cesur tavırlar

I.

Kendi derinliklerinden çıkardığı duygularla

II.

Mutluluğa uzanan hayatın kısacık yolunda

III.

Tüm gerçeklerin yanındadır bütün endamıyla

Derinliklerin çekimiyle yaşamalı insan...', 'Derinliklerin çekimiyle kımıldar insan I. Kendi derinliklerinden bir uğultu yükselir Cansız ruhun hayata dönüş çırpınışı Kırar çelikten kele...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/derin-lik-ler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz (Akrostiş)', 'deniz-akrostis-deniz-onderoglu-tmw7e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Denizi seyrederken kaybolmak güzeldir

Etraf yokolur

Nerede olduğunu bilmezsin

İzlersin uzaktaki ışıkları

Zaman kaçı göstersede o vardır yanında', 'Denizi seyrederken kaybolmak güzeldir Etraf yokolur Nerede olduğunu bilmezsin İzlersin uzaktaki ışıkları Zaman kaçı göstersede o vardır yanı...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/deniz-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşlikde dinlemiş yağmur', 'guneslikde-dinlemis-yagmur-nigin-nevaderezi-t1v9h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneşligimi silkemirim daha

Yağmur yoxdur bayirda

Bir sakiza yapişir

Yağmur, başim ve sanci

Ve bir ''türke mesel''*e nece böluşer bunlar? 

Geçen neysannan kalmiş yağmur,

Tavan deye güneşliye yürüyecek

Ve tirnagdan olan, sevda KAKTÜSLERI! 

Azdir? budur benim.

----------------------

*Ata baba sözleri.

Tebriz-2003', 'Güneşligimi silkemirim daha Yağmur yoxdur bayirda Bir sakiza yapişir Yağmur, başim ve sanci Ve bir ''türke mesel''*e nece böluşer bunlar?  Geç...', ARRAY['Türk Edebiyatı','Şiir','Nigin Nevaderezi']::text[], 8.5, '{"poet":"Nigin Nevaderezi","poet_slug":"nigin-nevaderezi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guneslikde-dinlemis-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kederde ve Sevinçte', 'kederde-ve-sevincte-hikmet-kavas-kucsb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne cepte eşitim seninle

ne cephede

bilmeyen de yoktur zaten

neden senin cennetin peşin

benimki veresiye

buradan tutup diyorum ki

ortak değiliz asla

kederde ve sevinçte

hayır/ ne münasebet

paylaşmıyorum ikiz kuleli üzüncünü

masum değil çünkü

hitler ruhunu kuşanarak

insan etini çelik paletlerle ezen

o başkan (mı)

kıçkan (mı)

bush kan''ı yeniden seçenler

ahh ıraklılar filistinliler çeçenler

onuru için canından geçenler

işte sizinle ortağım ben

hudutlar ötesi bir duyguyla

sizinle ortağız kederde ve sevinçte

yüreklerimizdeki zülm çentiklerince', 'ne cepte eşitim seninle ne cephede bilmeyen de yoktur zaten neden senin cennetin peşin benimki veresiye buradan tutup diyorum ki ortak değil...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Kavas']::text[], 8.5, '{"poet":"Hikmet Kavas","poet_slug":"hikmet-kavas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kederde-ve-sevincte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidene Ağıt', 'gidene-agit-tulay-sustam-llbul', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerim senden ötesini görmezken

aldın benden kendini gittin

beni; bana bırakarak! ....

gözlerin gözlerimde kaldı, ellerin ellerimde

kapı eşiğinde kaldı ayak izin

bir şehir yıkandı gözyaşlarımla...

yokluğunda uç veren yalnızlığım

zamansız batan güneş misali

şimdi kızıla gömüyorum anılarımı...', 'gözlerim senden ötesini görmezken aldın benden kendini gittin beni; bana bırakarak! .... gözlerin gözlerimde kaldı, ellerin ellerimde kapı e...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gidene-agit-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heç olmasa', 'hec-olmasa-sair-nadirezheri-ku94l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanri baqqal deyil, bu nisye* yaşamaq

Meni hirslendirecek**

Qara buludlar qeder

(Heç olmasa bir sigara aliştir***)  

Evler kobud

Xiyabanlar**** keder

Tarix çaqqal deyil,dar ağaclari

Meni güllendirecek

Elvan bahar qeder

Qanimi qirmizi şarap kimi***** süzeceyem

Tarix müellim******lerini keflendireceyem! *******

(Heç olmasa bir sigara aliştir...!)  

------------------------------------

*Parasiz ve sonra ödenilecek müamile

**Huylandiracak

***Yak

****Cadalar

*****Gibi

******Öyretmen

*******Serhoş edeceyim

Erdebil-2001', 'Tanri baqqal deyil, bu nisye* yaşamaq Meni hirslendirecek** Qara buludlar qeder (Heç olmasa bir sigara aliştir***)   Evler kobud Xiyabanlar*...', ARRAY['Türk Edebiyatı','Şiir','Şair Nadirezheri']::text[], 8.5, '{"poet":"Şair Nadirezheri","poet_slug":"sair-nadirezheri","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hec-olmasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-mahmut-gider-jqrnu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umut güzel şey,

Bilirim.

Yaşatır beni ve benzerleri

Anlamaz yabangülleri, güzelliğinden umudun.

Ben anlarım,

Çileyim dedim ya

Ecelim,dağ çiçeğim,

Umudum,sevdiceğim.', 'Umut güzel şey, Bilirim. Yaşatır beni ve benzerleri Anlamaz yabangülleri, güzelliğinden umudun. Ben anlarım, Çileyim dedim ya Ecelim,dağ çiç...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Gider']::text[], 8.5, '{"poet":"Mahmut Gider","poet_slug":"mahmut-gider","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umut-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin Hepsi', 'senin-i-cin-hepsi-mustafa-kemal-mut-4m706', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Salkım salkım olan bulut

Sen beni unut

Sevmiyorsun zaten beni

Ben ne seveyim ki seni

Gökten düşen damlalar 

Bir bir senin için

Yaparmısın ki bunu benim için 

Gelirmisin gelirmisin yanıma

Rıhtımda esen rüzgar

Dalgalandırıyor saçlarını aheste aheste

Senin için senin için bu yaptıklarımın hepsi

Yok bu dünyada senin gibisi

Yüzünde hep bir gülümseme 

Bu kimin eseri

Seviyorsun değilmi sende beni 

Benim seni sevgiğim gibi', 'Salkım salkım olan bulut Sen beni unut Sevmiyorsun zaten beni Ben ne seveyim ki seni Gökten düşen damlalar  Bir bir senin için Yaparmısın ki...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kemal Mut']::text[], 8.5, '{"poet":"Mustafa Kemal Mut","poet_slug":"mustafa-kemal-mut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-icin-hepsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hayat Hikayesi', 'bir-hayat-hikayesi-mahmut-gider-1v3m7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kanatlandı ızdırap düşünce kar tanesi,

Yaktı sevda düşünü ayrılık düşüncesi.

Revnak gök kuşağını, geçince tüm umutlar,

Seraba dönüştü, bir aşk viranhanesi.

Tenhalara gömüldü, tüm kimliksiz ölümler,

Adem oldu onlarla,yasaklı düşünceler.

Yitirilen insanlık, yüklendi limanlardan,

Derya mahilerine azık oldu erdemler...

....................', 'Kanatlandı ızdırap düşünce kar tanesi, Yaktı sevda düşünü ayrılık düşüncesi. Revnak gök kuşağını, geçince tüm umutlar, Seraba dönüştü, bir a...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Gider']::text[], 8.5, '{"poet":"Mahmut Gider","poet_slug":"mahmut-gider","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-hayat-hikayesi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse ağlamasın', 'kimse-aglamasin-meryem-i-sler-pc1mh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne sen ağla ne de ben

ağladık zaten doğarken

insana gülmek yakışırken 

yaşlar akmasın ğözlerimizden

hüzünleri atalım denizlere

sevgi tohumları ekelim kalbimize

mola yok ömür geçiyor gündüz ve gece

hiç kimse  ağlamasın  bir an bile', 'ne sen ağla ne de ben ağladık zaten doğarken insana gülmek yakışırken  yaşlar akmasın ğözlerimizden hüzünleri atalım denizlere sevgi tohumla...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kimse-aglamasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgin olmasa', 'sevgin-olmasa-i-shak-ozlu-s82u2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rüzğara eş''tin akardın gönüllere.

Kanadın mı kırıldı,döndün durgun göle.

Kardeştin güneşe dogardın yüreklere,

Yediverenken döndün kaktüslü çöle.

Konuştunmu öten bülbüller susardı,

Dört bi yanın kalbi senle atardı,

Susmuş dillerin,yorgun gözlerin,

Bahardı,kış olmuş günlerin.

Seninle esen rüzgar esmez olmuş,

Yanagında açan güller solmuş,

Ay karanlık,güneş tutulmuş,

Sanki hayat seninle birlikte durmuş.

Rüzgar esmesin,güneş dogmasın,

Bülbül ötmesin,yaz gelmesin farketmez.

Dilin konuşmasa,yüzün gülmese,

Bu yürek atar mı,sevgin olmasa.', 'Rüzğara eş''tin akardın gönüllere. Kanadın mı kırıldı,döndün durgun göle. Kardeştin güneşe dogardın yüreklere, Yediverenken döndün kaktüslü ç...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgin-olmasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayamadan', 'yasayamadan-zeki-ergin-zexvk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'umudu unutup

hayallerini yüklediler beynimize

sevdayı kitaplarda okuduk 

kalabalık olduk

düştük

sevgisiz  yollara

yalnızdık

varoşlardan aktık kentin caddelerine

umutsuz bedenlerimizle

yabancı

ürkek ve korkak

ve de hoyrat 

çaresiz 

harcadık güzellikleri

gençliğmizi

biz olamadan sonladık

hayatımızı

_beyoğlu 18şub05

_dağlara ver sırtını yt:haz09', 'umudu unutup hayallerini yüklediler beynimize sevdayı kitaplarda okuduk  kalabalık olduk düştük sevgisiz  yollara yalnızdık varoşlardan aktı...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yasayamadan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doktor Osman Karabaçak', 'doktor-osman-karabacak-doner-ozeke-vnfhp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bak hastayım geldim senin başına 

Zehir katma doktor benim aşıma 

Hele bi bakıver böbrek taşıma 

Acı doktor acı benim yaşıma 

Daha cok genç idim bunu bilmedin 

Zalim Doktor çiğerlerime elledin 

İyi olursun diye beni eve yolladın 

Bu gün git yarın gel deme Doktor bey

İşte geldim Doktor İlaç veriver 

Derdim nedir Doktor hele deyiver 

Kanser mi verem mi adını koyuver 

Liste yapıp bir bir bana sayıver 

Acılar içinde ölüyorum ben her gün 

Aman yokmu Doktor geliyorum ben 

Ne acılar gördün biliyorum sen 

Kederler içinde koyma Doktor bey

Aman Doktor bana ömür biçiver 

İlaçları bırak bana röntgen çekiver 

Yaram derin ise orda hemen kesiver 

Susma Doktor hadi derdim deyiver 

Hemşireni gönder beni bir görsün 

Damar yollarımdan serumu versin 

Şu garip hastayın yüzü bir gülsün 

Kuzularım küçük daha ne olsun

Hastaneye vardım revir dediler 

İlacı iğneyi burda devir dediler 

Uyutmak için bana narkoz verdiler 

Ölüyorum Doktar derdim deyiver

İstersen peri ol  istersen fani 

Sana teslim ettim Doktor bu canı 

Sen beni unutma kalsın bu anı 

Selam olsun Doktor ömrün var olsun 

Aman  gülüm doktor canın sağ olsun 

Anayın Babayın ömrü var olsun 

Ağlamasın gözlerin  umutla dolsun 

Selam olsun Doktor ömrün var olsun   

Dr.Osman Karabacak iyi ki varsın

           DÖNER TEMÜR 

              18.02.200

                ANKARA', 'Bak hastayım geldim senin başına  Zehir katma doktor benim aşıma  Hele bi bakıver böbrek taşıma  Acı doktor acı benim yaşıma  Daha cok genç ...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/doktor-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AYILTAK Sevgi''yi! ...', 'ayiltak-sevgi-yi-ozan-sah-turna-agdasan-98gk1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AYILTAK SEVGİYİ! ... 

Çağımız uzaya füze gönderdi 

Amma yumruk kadar kalbe inmedi 

Yüzyıllardır kin ve savaş dinmedi 

Barışı estiren YELE gidelim! .... 

Nakarat: Ayıltak segiyi, bayıltak kini 

Dostluk, sevgi-sarış insanlık günü 

Hak, Paylaşım, barış kıblemin yönü 

Sevgiyi şakıyan DİLE gidelim! 

Haydutlar çıkmışlar insan avına 

Kimi boş hayale, kimi savına 

Kardeşlik kınası düğün evine 

Hep el ele, Güle GÜLE gidelim 

Ay güneşin herkesin, niye sam yeller? 

Kararmış gönüller, el vermez eller 

Barut kokusundan kararmış güller 

Dost figan eden BÜLBÜLE gidelim 

Nakarat:... 

ŞahTurna’yım Ferhat-Şirin elinden 

Anadolum nakış nakış gülümden 

Şiar can çok çektik riya zulümden 

Dikenleri Yola YOLA gidelim! 

Ayıltak sevgiyi, bayıltak kini 

Dostluk-sevgi-sarış insanlık günü 

Hak-paylaşım,barış kıblemin yönü! ... 

Sevgiyi şakıyan DİLE gidelim! ... 

Söz: Ozan ŞİAR Ağdaşan ve Ozan ŞAH TURNA (Kadın Halk Ozanı)  

Müzik:Ozan ŞİAR www.siarcan.com 

Vokaller, Almanca Çeviri: ŞAFAK&ŞİRİN Müzik grubu 

Sevgili Dostlar, sizleri gerçek sevgiyi, dostluğu işleyen bir eserimizle selamlamak istedim...Sevgilerin aşındığı, yüreklerin soğuduğu, dostluk bahçesinin solmağa yüz tuttuğu dünyamıza, memleketimize, sevgi, dostluk, esenlik güllerinin katmer açtığı yaşama merhaba...! 

Sevgiyle kalın, umudunuz solmasın efendim... 

Ozan ŞİAR Can 

www.siarcan.com', 'AYILTAK SEVGİYİ! ...  Çağımız uzaya füze gönderdi  Amma yumruk kadar kalbe inmedi  Yüzyıllardır kin ve savaş dinmedi  Barışı estiren YELE gi...', ARRAY['Türk Edebiyatı','Şiir','Ozan Şah Turna Ağdaşan']::text[], 8.5, '{"poet":"Ozan Şah Turna Ağdaşan","poet_slug":"ozan-sah-turna-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ayiltak-sevgi-yi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığı kalem çizer mi? ...', 'ayriligi-kalem-cizer-mi-omer-faruk-girgin-30jwm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşündün mü bir gün sevebileceğini

Hiç olmadık bir sevdanın çarmıhına gerilip de

Sana küçükken söylenen bir masalın hissettirdiği

Tuhaf bir duygunun ekseninde çırpınabileceğini? 

Sevip de söyleyemediğin oldu mu 

''Keşken'' çekmecendeki kelimelerin hala canlı mı yoksa

Unutup da yarını şimdiyi hiç düşünmediğin günlerini 

Ahh şimdi orada hep onunla kalsaydım dediğin gibi…

Acıdın mı  kendine kederli bir tebessümle

Hiç unutamadığın bir şarkıyı bugün söyledin mi? 

Şiirini sakladığın yüreğine  cesaret geldiğinde

Ayrılığını  hiç  kalemle  çizebildin mi? ...', 'Düşündün mü bir gün sevebileceğini Hiç olmadık bir sevdanın çarmıhına gerilip de Sana küçükken söylenen bir masalın hissettirdiği Tuhaf bir ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayriligi-kalem-cizer-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miras', 'miras-ozkan-sahin-dvu3g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'koca koyun

başı çeken yaşlı koyun

yol bilen yordam bilen

otlak bilen sulak bilen

gideceği yeri önceden sezen

çobanın çok sevmişti seni

kuyruğun olan koca sürü

bırakmazdı seni

tutmazdı hiçbir koyun yerini

ne kurban oldun

ne kasaplık

ot için et için yaşamadın

yas tutmazmı sürü

yas tutmazmı çoban

yaşlı koyun

eceliyle yüzleşen koyun

hangi koyun  alır senin yerini? 

hangi yaşlı koyun alır

paslı çivini? 

seninde aldığın gibi.

              27-01-2005', 'koca koyun başı çeken yaşlı koyun yol bilen yordam bilen otlak bilen sulak bilen gideceği yeri önceden sezen çobanın çok sevmişti seni kuyru...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/miras-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevsem Yani', 'sevsem-yani-huseyin-mustafa-guvendag-5ng29', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni bana katsam

ya da yansam seninle

ya da hasta olsam sana

ya da bansam seni bana

ya da sensiz yaşayamazsam

ya da sarsam seni, içime çekmek için kokunu

ya da sararsam bir yaprak gibi sen yoksun diye

hepsi aynı yola çıkar

29.09.2004', 'seni bana katsam ya da yansam seninle ya da hasta olsam sana ya da bansam seni bana ya da sensiz yaşayamazsam ya da sarsam seni, içime çekme...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Mustafa Güvendağ']::text[], 8.5, '{"poet":"Hüseyin Mustafa Güvendağ","poet_slug":"huseyin-mustafa-guvendag","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevsem-yani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadık mı biz', 'yasadik-mi-biz-huseyin-mustafa-guvendag-n0s08', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bakarken aya

yüreğim seni taşır

sana bakarken

ay darılır

bir sabır işi bu

dalgalara yenilmeyeceksin

kıyametler kopmadı daha

ufak sarsıntılar var

geçici

yaşam ezbere değil

bir kitapta değil

ya da bir kitap

ama yazan sen

oynayan da

kuş ayında buluşalım

düş kurup uçalım

balık ayında dolaşalım

derinlerde yüzmek için

yok ayında varlığımız ıslık çalar

sır gibi herşey

anlaşılmaz yokluğumuz

belki de hiç olmadık biz

02.12.2004', 'bakarken aya yüreğim seni taşır sana bakarken ay darılır bir sabır işi bu dalgalara yenilmeyeceksin kıyametler kopmadı daha ufak sarsıntılar...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Mustafa Güvendağ']::text[], 8.5, '{"poet":"Hüseyin Mustafa Güvendağ","poet_slug":"huseyin-mustafa-guvendag","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasadik-mi-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane', 'efsane-suleyman-yavuz-8li2c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Durdu kalbim durdu hayatım

Seni gördüğüm an

Sen güzel ne afet 

Sen ne hurisin ne de melek

Sen benim hayatım

Sen benim canım

Kanımsın ey yar

Duysun yüreğimin sesini

Duysun sevdamı 

Cümle alem

Dursun dünya dursun zaman

Anlasın bizi bilmeyenler 

Bilsinler 

Anlasınlar 

Bu bizdekini

Bu bizim ki 

Aşk değil sevda değil

Efsane ey sevgilim', 'Durdu kalbim durdu hayatım Seni gördüğüm an Sen güzel ne afet  Sen ne hurisin ne de melek Sen benim hayatım Sen benim canım Kanımsın ey yar ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/efsane-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irak''ta Ölen Babalara Ağıt', 'irak-ta-olen-babalara-agit-bulent-kalayci-h2q5j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çocuk ve baba

Köşe başında kaygulu

Temkinli yürüyorlar

Geçen arabaların sesini

Bomba sanıyorlar

Duvarların ardında özgürlük

Bu yanda esaret

Bir lokma ekmek

Sarıyor içini

Islık sesiyle beraber

Bir göz bir de el

Yerde bakarken birbirlerine

Gözyaşı bulutu donuyor

El avuç açmış göğe

Çocuk, el, göz

Yüz yüze bakıyor

Anımsıyorlar

Bakıyor çocuk göze

Gülümsüyor göz çocuğa

El okşarmış gibi başı

Baba!', 'Bir çocuk ve baba Köşe başında kaygulu Temkinli yürüyorlar Geçen arabaların sesini Bomba sanıyorlar Duvarların ardında özgürlük Bu yanda esa...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kalaycı']::text[], 8.5, '{"poet":"Bülent Kalaycı","poet_slug":"bulent-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/irak-ta-olen-babalara-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yola kendim çıkmadım! ! !', 'yola-kendim-cikmadim-hikmet-feridun-demir-de1pf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelenin benim olacağından,

hiç kimsenin haberi yoktu...

Gele gele yaşamdan habersız,

bilgisız, öğrenmeye susamış

öğrendiklerini öğretmeye hazır

beni buldular karşılarında ve

şaşırdılar…

Seni dünden tanıyorduk..

Ne köy ne kasaba,

olur senden dediler…

Kendileri büyük şehirdiler....

Ve sonunda küçüldüler, 

küçüldüler ayaklarımın altında,

çamurlu bir yol oldular...

Yine üzülen ben,

üzen onlar oldular...

10.01.2005

Wermelskirchen/Almanya', 'Gelenin benim olacağından, hiç kimsenin haberi yoktu... Gele gele yaşamdan habersız, bilgisız, öğrenmeye susamış öğrendiklerini öğretmeye ha...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yola-kendim-cikmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerim Seni', 'beklerim-seni-cihan-coskun-ink6k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana olan aşkım dillere düşse

Ayrılık hasreti içime çökse

Kavuşmamız için yıllar gerekse

Sevgilim yıllarca beklerim seni

Sevda yollarında ömrüm tükense

Gönül defterinden ismim silinse

Ağlayan kaderim bana gülmese

Gülünceye kadar beklerim seni

Gözlerimde yaşlar dinmek bilmese

Af dilesem senden fayda etmese

Beni sevmen için ölmem gerekse

Ölürüm mahşerde beklerim seni', 'Sana olan aşkım dillere düşse Ayrılık hasreti içime çökse Kavuşmamız için yıllar gerekse Sevgilim yıllarca beklerim seni Sevda yollarında öm...', ARRAY['Türk Edebiyatı','Şiir','Cihan Coşkun']::text[], 8.5, '{"poet":"Cihan Coşkun","poet_slug":"cihan-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beklerim-seni-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de Senden de çok bir Sen', 'sen-de-senden-de-cok-bir-sen-seda-atasoy-4o7b9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensizliğimi yaşıyorum  bu sabah 

Buruk bir merhaba ile başlıyorum güne

Gözlerim birşeyler arıyor birden

Ellerim  kalemime gidiyor aniden

Yokluğun dökülüyor şiirlerime

Yalnızlığımın verdiği  sessizlikte

Sensizliğimdeki beni duymanı istiyorum.

Bir başka yazıyorum sözcükleri  bu sabah mısralarıma

Canhıraç  boğuşurken  yalnızlığımla

Sensizliğimde kaybolup  adeta  Sen den daha çok bir Sen oluyorum...

Yokluğunda bile seni yudumluyorum 

Gözlerin karanlıklardaki ışığım oluyor

Seninle her anım bir ömre  bedelmiş diyorum

Sensiz her dakikam ölümden de betermiş

Bunu şimdi daha iyi biliyorum.

Bu sabah  çaresizlikler  içinde lanet ediyorum tüm mesafelere

İsyan ediyorum beni senizliğime mahkum eden herşeye...

Ama  birden hayalin geliyor gözlerimin önüne

Bu  işte diyorum  sevmek birtanem,sensizkende seni yaşayabilmek...

Ömrümün en harlı meşalesi parlıyor o an içimde

Ve yaşadıklarımız geliyor aklıma sonra 

İçimde dayanılması imkansız  bir özlem

Yüreğim yanıyor içim acıyor...

Arzunun ötesinde birşey bu birtanem

Dudaklarının yokluğunda bile gözlerim kapanıyor

Gülüşün damlıyor yüzüme, ürperen  tenimi  bedenin sarıyor

Sözlerimi unutuyorum gözlerinde  susuyorum

Sessizliğimde  avaz avaz bağırıyorum 

Ama  kimselere duyuramıyorum

Herşeyin ötesinde bir his bu  birtanem 

Yokluğunda bile seninle olabilmek...

Hayatta en acı şey yalnızlığımda sensizliği yaşamakmış...

Gitgide aratan sessizliğimde

Yalnızlığım sen,sensizliğim ben oluyor aniden

Yalnızlıkla sensizlik eşit  oluyor sanki  yeniden

Birbaşka yaşıyorum yalnızlığımı bu sabah

İliklerime kadar  heryerim seninle doluyor

Yokluğunda öylesine  eriyor öylesine bitiyorum ki

Sensizliğimin şahidi beyaz bir kağıtla sadece kalemim oluyor.

Ama üzülme birtanem,yokluğun dayanılmaz olsa da

Bedenim  yine dönüşünü  düşleyerek güç buluyor

Bir başka yaşıyorum sensizliğimi  bu sabah

Yalnızlık rüzgarları acımasızca eserken içimde

Sana doğru savruluyor seni senden daha çok soluyor,

Sen de Senden de çok  bir Sen oluyorum....', 'Sensizliğimi yaşıyorum  bu sabah  Buruk bir merhaba ile başlıyorum güne Gözlerim birşeyler arıyor birden Ellerim  kalemime gidiyor aniden Yo...', ARRAY['Türk Edebiyatı','Şiir','Seda Atasoy']::text[], 8.5, '{"poet":"Seda Atasoy","poet_slug":"seda-atasoy","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sen-de-senden-de-cok-bir-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Son...', 'bu-gece-son-canan-motorcu-r0snn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Azınlıklar arasından sesleniyorum yar...

Az önce göz yaşlarımı senin için sarfettiysem

Gece vakti bir bayan olarak sokaklarda seni aradıysam

Her motor sesine acaba bu mu diye dönüp baktıysam

Sadece kapının arkasından yanlışmı duydum kuşkusuydu

Ama artık iyice inanıyorum hak edene ağlayacaksın,

Sevdiğin her kişiyi caddelerde aramayacaksın,

Acaba gelirmi diye dönüp dönüpte arkana bakmayacaksın

Sen seviyorsun hala diye onun sevgisine de inanmayacaksın

Kızım sil artık göz yaşlarını giden gitsin 

Arkasına bakmadan çekipte gitsin

Kapımda bana yalvarmazsa sevgimi neylesin

    Annasima Can

   (18.02.2005)    saat:  23:02', 'Azınlıklar arasından sesleniyorum yar... Az önce göz yaşlarımı senin için sarfettiysem Gece vakti bir bayan olarak sokaklarda seni aradıysam...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-gece-son-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Uğruna', 'senin-ugruna-kemal-cakir-3ewhn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin sevdan yüzünden düşemem çöllere sevgilim

Çünkü çöller yakıp bitirir, sonra sana nasıl dönerim.', 'Senin sevdan yüzünden düşemem çöllere sevgilim Çünkü çöller yakıp bitirir, sonra sana nasıl dönerim....', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/senin-ugruna-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Çiçekleri Severim', 'butun-cicekleri-severim-kemal-cakir-kgey3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünyadaki bütün çiçekler benim olmalı

Sevgi bahçemde görmeliyim her birini

Gül, lale, yasemin, menekşe, papatya...

Her saniye birini sevip koklamalıyım

Çünkü ben bütün çiçekleri severim.

Hiç bir tercihim yok, yeşil, mavi, ela...gözlü

Kumral, sarışın, uzun yada kısa boylu

Salınıp açmalılar renk renk

Dallarını, çiçeklerini, yapraklarını okşamalıyım

Çünkü ben bütün çiçekleri severim.

Bahar rüzgarıyla ılık ılık ısınıp,

Yaz güneşiyle buram buram terlemeliler.

Sonbahar yağmurlarıyla serinleyip

Gönül sıcaklığımda kışı bilmemeliler

Çünkü ben bütün çiçekleri severim.

Solmamalı bir tanesi bile, ben yaşarken

Üzülüp ağlamamalı, kahrolmamalıyım

Hep neşe ve sevgi dolu bakıp durmalıyım

Servi boylusuna kara gözlüsüne

Çünkü ben bütün çiçekleri severim.

Başka hiçbir bahçede açmasınlar isterim

Biri bile olmazsa bahçem olur tarumar

Kimseye de şikayet etsinler istemem

Buna dayanamam doğrusu, yemin ederim

Çünkü ben bütün çiçekleri severim.', 'Dünyadaki bütün çiçekler benim olmalı Sevgi bahçemde görmeliyim her birini Gül, lale, yasemin, menekşe, papatya... Her saniye birini sevip k...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/butun-cicekleri-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Z i r v e', 'z-i-r-v-e-kemal-cakir-iks0k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zirveye: 

