INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldönümü', 'yildonumu-asli-yildiran-alfdl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '15 Temmuz 2000  anısına

Yıldönümü geçti mutluluğun 

Aynı zamanda en büyük mutsuzluğun

En güzel gün ilan edilmişti belkide

Kimbilir kaç sene önce

Şimdi hatırlıyorum o mutlu, o aydınlık, o en güzel günü

Yüreğimde derin bir sızı ile...', '15 Temmuz 2000  anısına Yıldönümü geçti mutluluğun  Aynı zamanda en büyük mutsuzluğun En güzel gün ilan edilmişti belkide Kimbilir kaç sene ...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yildonumu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Taneler', 'i-ki-taneler-abdulhamit-kanca-h80sv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevsimin soğuğuna inat

Örtememişim üstüme

Geceden başkasını

Bir sazın tıngırtısına takılmışım ben,

Uymuşum çağrısına

Uçmuş gitmişim ben...

Şimdi; 

Geçmişin uğraşlarına unutkan,

Sabaha ve ışığına umarsız kalmışım,

Bitirememişim geceyi

Yıldızları dizime oturtmuşken ben...

Bakakaldırmışım feleğe

beni anlamaya uğraşta,

Habire geceyi başa sarmakta,

“Bu nasıl oldu” diye de,

Tanrısına sormakta...

Zulümlere abone zalimlere

Bu anı anlatmışım ben

Kelebek ömründe yaşanmış

Sevda mevsimlerini duyurmuşum; 

Zor gelsede zebanilere

Cennetleri zıplatacak

Sevgi cehennemi

Kurdurmuşum  ben..

Bir şişenin kucağına düşmüşlere,

Bir mezarın başında bekleyenlere

Ya da yakaladığım Yakaran yüreklere

Diz çökmüşüm ben.

Araladığım yüreğimde onlara; 

Geceleri örtü

gündüzleri kucak

Boşlukları zemin etmişim,

Bir karagözde yok olmayı

İnsanda bitmeyi anlatmışım ben...

Şimdi sayılara, metalik seslere inat

Milyarlar içinde tek yürekle dolaşan

Alemlere bedel,

Birbirlerine sunulmuş

Birkaç iki taneleri  görmekteyim Ben...', 'Mevsimin soğuğuna inat Örtememişim üstüme Geceden başkasını Bir sazın tıngırtısına takılmışım ben, Uymuşum çağrısına Uçmuş gitmişim ben... Ş...', ARRAY['Türk Edebiyatı','Şiir','Abdülhamit Kanca']::text[], 8.5, '{"poet":"Abdülhamit Kanca","poet_slug":"abdulhamit-kanca","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/iki-taneler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra', 'senden-sonra-asli-yildiran-bfoqg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senden sonra gülmek çok zor

Gülüşler yalan oldu senden sonra

Senden sonra günler boş, günler renksiz, günler ışıksız kaldı

Güller soldu senden sonra,güller kurudu

Yüreğimin kıyameti koptu senden sonra

Ve ağlamasın, bitmesin istediğin ben 

Çoktan bittim senden sonra...', 'Senden sonra gülmek çok zor Gülüşler yalan oldu senden sonra Senden sonra günler boş, günler renksiz, günler ışıksız kaldı Güller soldu send...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/senden-sonra-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sarı kız. Türküsü **', 'bir-sari-kiz-turkusu-ali-riza-unal-aljhz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elleri kolları kınalımısın.

?        ?      ?    yaralımısın.

//         //            //        //

Gel barışalım sarı kız.

 ?      ?      ?    alımısın.

//          //               //

saçları beline sarılımısın.

?         ?     ?   dolalımısın.

//     //            //     //

Sen ne güzelsin sarı kız.

  ?     ?         ?     balısın.

//         //      //      //     //

sen bağımın bağısın.

?       ?      ? dağısın.

//       //     //     //     //

Gel sarılalım sarı kız.

S                      ağısın.

//         //             //

gözleri zülfüne salkımısın.

?           ?       ? haklımısın.

//       //       //          //     /

Gel sarılalım sarı kız.

?      ?        ? aklımısın.

  güftenin tamamı değildir

  söz ve beste fakirullah ali Rıza Ünal', 'Elleri kolları kınalımısın. ?        ?      ?    yaralımısın. //         //            //        // Gel barışalım sarı kız.  ?      ?      ?...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-sari-kiz-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce sesleri yitireceğiz....', 'once-sesleri-yitirecegiz-huseyin-tanrikulu-nntz3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Önce sesleri yitireceğiz, ardından yüzleri

Sonra ne kalmışsa yitirilmedik, hepsini üçer-beşer

Birimize birimizi hatırlatan ne varsa

Acıtan, güldüren

Bütün yaşanılamayanlar unutulacak

Unutturulacak başka sarmalar tarafından

Bir şeyler kırılacak

Ve en büyük kırık saplanacak küçücük bir yüreğe

Ne kadar acırsa, o hızla mı unutulur acaba adına sevda dediğimiz bu insanlık hastalığı,

Yoksa belirli belirsiz gülmelerle mi kapatılır, taze bir yaranın henüz kabuk bağlayamamış sancısı. 

Nedir ki şimdi, onca gülmelerden arta kalan keder,

Yada neyin günahıdır çekilen bu platonik acı,

Ve hangimiz ödeyebiliriz bir damla gözyaşının bedelini böyle hoyratlıklarla. 

03.01.2004                                                                        Hüseyin TANRIKULU', 'Önce sesleri yitireceğiz, ardından yüzleri Sonra ne kalmışsa yitirilmedik, hepsini üçer-beşer Birimize birimizi hatırlatan ne varsa Acıtan, ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/once-sesleri-yitirecegiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Rüyamda Gördüm Seni', 'dun-ruyamda-gordum-seni-asli-yildiran-xku1z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün rüyamda gördüm seni

İstanbul''daydın

İstanbul ben İstanbul''u tanıdığımdan beri

hiç bu kadar güzel olmamıştı

Güneş hiç böyle parlamamıştı bence

Dün rüyamda gördüm seni

Ellerimi tutmuştun sıcacık

Ellerim hiç böyle bir sıcaklık hissetmemişti

Dün rüyamda gördüm seni

Boynuna sarıldım yılların özlemiyle

Kollarım hiç kimseyi böylesine sıkı sarmamıştı

Dün rüyamda gördüm seni

Yanımda kalmaya söz verdin bir ömür boyu

Yüreğim hiç böyle mutlulukla dolmamıştı

Yüreğim kanatlanıp uçmamıştı hiç

Dün rüyamda gördüm seni

Hayatımda hiçbir gün 

O rüya kadar güzel olmamıştı...', 'Dün rüyamda gördüm seni İstanbul''daydın İstanbul ben İstanbul''u tanıdığımdan beri hiç bu kadar güzel olmamıştı Güneş hiç böyle parlamamıştı ...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dun-ruyamda-gordum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Gitti Yıllarım', 'kayip-gitti-yillarim-asli-yildiran-pgo5b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Avuçlarımdan akıp giden bir su damlası gibi 

Kayıp gitti yıllarım,saçlarımda aklar, bu çizgiler 

ben miyim bu aynadaki yitik insan 

oysa nasılda har vurup harman savurmuştum günleri hatta yılları

nasıl olsa önümde uzun yıllar var diyerek

ben miyim bu umutsuzca yarını bekleyen insan

benim mi bu kırışmış ve Tanrı’ya çok geç açılmış eller

Şimdi hatırlamakta güçlük çekiyorum 

neydi ilk sevgilimin ismi,saçları,gözleri ne renkti

hani  ikimizin bir şarkısı vardı nasıldı sözleri

ben gökyüzünden kayıp gitmeye hazır yıldız,

ben duvarlara çarparak geri dönen bir aşkla bir ömür geçiren

ben bu aynada  gördüğüm gözleri yorgun bakan insanım

ben geç kalmış dualarının hepsini bir çırpıda okuyan

ve herşeye rağmen yüreği sevgi dolu o şımarık kadınım...', 'Avuçlarımdan akıp giden bir su damlası gibi  Kayıp gitti yıllarım,saçlarımda aklar, bu çizgiler  ben miyim bu aynadaki yitik insan  oysa nas...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kayip-gitti-yillarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakıpta Gidemem', 'birakipta-gidemem-sahin-erturk-zpx57', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şehrimde yaşıyorsun

Ekmeğini yiyorsun

Havayı soluyorsun

Bırakıpta gidemem

Belki biraz nazlısın

Başkasıyla sözlüsün

Beklemeye değmezsin

Bırakıpta gidemem

Sensiz alamam soluk

Derdim harbiden büyük

Kanımı emen sülük

Bırakıpta gidemem

Düğün günün yaklaştı

Bende telaş başladı

Bırakıpta gidemem

Bırakıpta gidemem', 'Şehrimde yaşıyorsun Ekmeğini yiyorsun Havayı soluyorsun Bırakıpta gidemem Belki biraz nazlısın Başkasıyla sözlüsün Beklemeye değmezsin Bırak...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birakipta-gidemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel Şeydi', 'ne-guzel-seydi-asli-yildiran-469wq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YASEMİN ve ENVER''e   Şahit olduğum en güzel aşkın anısına...

Ne güzel şeydi yollarını beklemek ve her gelişinde aynı heyecanı hissetmek

Ağlamak ayrılıklara ve barışmak ne güzel şeydi

Ellerini tutmak,gözlerinde kaybolmak ve yüreğine indiğimde

Orada kendimi bulmak ne güzeldi.

Oysa şimdi sensiz, benli ama bensiz bir dünyada,

Sensiz ama sen dolu bir ömrü yaşıyorum

Gülüşlerim yalan,heyecanlar sahte

Özlemlerim çok uzak günlere….

(Bu ayrılığa veda yakışmazdı,varolduğum sürece yüreğim hep seninle)', 'YASEMİN ve ENVER''e   Şahit olduğum en güzel aşkın anısına... Ne güzel şeydi yollarını beklemek ve her gelişinde aynı heyecanı hissetmek Ağla...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-guzel-seydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-zafer-yazici-tvv99', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“Keşke” demeden daha

Kaç keşkeler tükettik,

Kaç “keşkelere” vurduk kendimizi

Biz, sen ile! ..

Keşkeler içinde boğulduk çaresiz! 

Kaç pişmanlık arifesinde

Ölümün ucundan döndük! 

Uğultulu kulaklarla

Nasıl duyabilirdik ki 

“kal” demeleri

keşke

kulaklarımızı daha iyi açsaydık değil mi? 

Yada gözlerimizi! ..

Yada sıkı tutsaydı

Ellerimiz birbirini,

Keşke! ...

sevdiğimiz hep yanımızda olsa da,

biz ona hasret kalsak! 

istediğimiz an

kavuşup, 

göz yaşı ile 

sel olsaydık,

keşke! ...', '“Keşke” demeden daha Kaç keşkeler tükettik, Kaç “keşkelere” vurduk kendimizi Biz, sen ile! .. Keşkeler içinde boğulduk çaresiz!  Kaç pişmanl...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/keske-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okyanus', 'okyanus-asli-yildiran-3m2cv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu sabah yağmuru seyrettim ilk kez 

Ilk kez çünkü  yağmuru hiç sevmem, karanlıkları da

Düşen her damlanın bir önemi vardı,

Yol kenarlarındaki su birikintilerinin oluşması için gerekliydi damlalar

Tıpkı bizlerin olgunlaşması için her damla kederin gerekliliği gibi

Her damlada biraz daha büyüyen bir göl var yüreğimizde

Ve her bir damla önemli hayatımızda

Bazen ölüm, bazen ayrılık,vefasızlık yada

Bizler büyüyoruz büyümesine de ne gözyaşları,ne acılarla

Hep böyle miydi yoksa bize mi böyle denk geldi bilmiyorum

Neden çocuk düşlerimden geriye sadece bir tebessüm kaldı

Bu kadar zor bir şey miydi güçlü olmak, mutlu olmak

Umut dolu olmak bu kadar zor muydu

Büyüyoruz ve büyütüyoruz yüreğimizdeki gölü

Hatta bazen bir okyanusa dönüşüyor

Ve o göl büyüdükçe belki de biz küçülüyoruz,eziliyoruz

Her insan için kurulmuş olan kimi uzun kimi kısa cümle ansızın noktalanıyor

Bizler yüreğimizde büyüttüğümüz okyanusla gömülüyoruz.', 'Bu sabah yağmuru seyrettim ilk kez  Ilk kez çünkü  yağmuru hiç sevmem, karanlıkları da Düşen her damlanın bir önemi vardı, Yol kenarlarındak...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/okyanus-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vitrindeki Manken', 'vitrindeki-manken-sahin-erturk-vjxj2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Takmışsın,yakıştırmışsın

Boyamış,boyalanmışsın

Çok güzel görünüyorsun

Vitrindeki manken misin? 

Burun,göğüs kalça tamam

İşini biliyormuş onaran

Güzel huy vermemiş mevlam

Vitrindeki manken misin? 

Kulağı sağırlardan mı? 

Bakan görmeyenlerden mi? 

Kalbi olmayanlardan mı? 

Vitrindeki manken misin? 

Duygusuz yosmalardan mı? 

Aşkını satanlardan mı? 

Şıpsevdi olanlardan mı? 

Vitrindeki manken misin? 

Can çıkmayınca huy çıkmaz

Fizikle güzellik olmaz

Kalpler boyayla aklanmaz

Vitrindeki manken misin? 

İşte veriyorum,bu notum

Fizik geçtin,kimyan bozuk

Acıyorum sana yazık

Vitrindeki manken misin?', 'Takmışsın,yakıştırmışsın Boyamış,boyalanmışsın Çok güzel görünüyorsun Vitrindeki manken misin?  Burun,göğüs kalça tamam İşini biliyormuş ona...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vitrindeki-manken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Elini Çeksin', 'ay-elini-ceksin-sevtap-ozkahraman-trrxv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimden düşen sevdam

Şaşkın..

Ürkek..

Bir başına ahenksiz dansını seyrediyor

Kelimelerin...

Tersyüz olması ondandır

Söylenemeyen son cümlemin! 

Ve

Sımsıkı tutunması '' seyyah cümlelerine''

Ki

Ay elini çeksin kapattığı güneşin gözünden...

(18/02/2004 Ankara)', 'Yüreğimden düşen sevdam Şaşkın.. Ürkek.. Bir başına ahenksiz dansını seyrediyor Kelimelerin... Tersyüz olması ondandır Söylenemeyen son cüml...', ARRAY['Türk Edebiyatı','Şiir','Sevtap Özkahraman']::text[], 8.5, '{"poet":"Sevtap Özkahraman","poet_slug":"sevtap-ozkahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ay-elini-ceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa ve Öz', 'kisa-ve-oz-adnan-mehmet-tufekci-gz648', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir çiçekti 

gönül bahçemde,

sararıp soldu.,

döküldü yaprakları,

rüzgarlarla savruldu.', 'bir çiçekti  gönül bahçemde, sararıp soldu., döküldü yaprakları, rüzgarlarla savruldu....', ARRAY['Türk Edebiyatı','Şiir','Adnan Mehmet Tüfekci']::text[], 8.5, '{"poet":"Adnan Mehmet Tüfekci","poet_slug":"adnan-mehmet-tufekci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kisa-ve-oz-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-cetin-erdogdu-4gpy2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevdam vardı

Dağların doruklarında erişilmeyen

Bir sevdam vardı

Okyanusların derinliklerinde gidilemeyen

Bir sevdam vardı

Dünyanın bir ucunda memleket kadar hasret

Bir sevdam vardı

Ela gözlerinde yaz yağmuru kadar sıcak

Bir sevdam vardı

Kokusunu hissettiğim bir gülün kızıllığında

Bir sevdam vardı

Etimi yakan güneşin sıcaklığında

Bir sevdam vardı

Tenimi yakan meltem rüzgarlarında

Bir sevdam vardı

Düşlerimin bittiği an uyandığımda', 'Bir sevdam vardı Dağların doruklarında erişilmeyen Bir sevdam vardı Okyanusların derinliklerinde gidilemeyen Bir sevdam vardı Dünyanın bir u...', ARRAY['Türk Edebiyatı','Şiir','Çetin Erdoğdu']::text[], 8.5, '{"poet":"Çetin Erdoğdu","poet_slug":"cetin-erdogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdam-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Gidişin', 'son-gidisin-cetin-erdogdu-g2o6h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyorum  bugünde gelmeyeceksin

Geçen Cuma olduğu gibi

Biliyorum açmayacaksın radyonu

Bozmayacak suskunluğunu 

Sen dönene kadar

Çalmayacak o klasik müziği

Biliyorum çizmeyeceksin

Rulo, rulo proje kağıtlarına çizgini

Duracak masanın üzerinde rapido kalemlerin

Dökülecek mürekkebi beyazlığına

Bir kara sevda gibi

Karartacak üzerini benek benek

Kalacak yüreğimde silinmeyen bir ben gibi

Biliyorum içmeyeceksin bir demli çay fincanınla

Dem tutmayacak demlikteki çayım

Açmayacak bahçedeki güller

Kıpırdatmayacak koca çınar yapraklarını

Uçmayacak dalındaki kuşlar

Biliyorum bugünde gelmeyeceksin

Ya ben 

Beni hiç sorma

Bildiğin gibi hep aynı tantana

Yine kör sabahlar

Yine uzayıp giden tren rayları

Belli olmayan duraklar

Selamsız sabahsız gelip gitmeler

Art arda biten sigara paketleri

Bardaktan taşan anason kokusu

İşte hepsi böyle 

Bildiğin gibi hep aynı tantana

Ve oynadığımız hep aynı oyunlar

Yüreğimdeki isyanla boğuşuyorum

Dışarıdaki suskunluğa rağmen

Hissederken bir şeylerin eksikliğini

Aramıza giren o demir kapıyı

Kaç kez açıp kapadığımı hatırlamıyorum

Seyrederken karşımda duran yalnızlığı

Ve kirli camları

Hatırladığım tek şey son gidişin

Geçen Cuma olduğu gibi.', 'Biliyorum  bugünde gelmeyeceksin Geçen Cuma olduğu gibi Biliyorum açmayacaksın radyonu Bozmayacak suskunluğunu  Sen dönene kadar Çalmayacak ...', ARRAY['Türk Edebiyatı','Şiir','Çetin Erdoğdu']::text[], 8.5, '{"poet":"Çetin Erdoğdu","poet_slug":"cetin-erdogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/son-gidisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gene Bir...', 'gene-bir-bir-mim-kemal-ertugrul-31i2k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elde bir 

Avuçta birdi...

Elde avuçta bir...

Altı üstü

Bir idi

Altı üstü bir...

Artı eksi

Bir idi

Artı eksi bir...

Hangi birini yedi? 

Artı mı eksi mi

Hangi hangini? 

Ki; 

Ne bir arttı

Ne eksildi

Şehrin yalnızlığı...', 'Elde bir  Avuçta birdi... Elde avuçta bir... Altı üstü Bir idi Altı üstü bir... Artı eksi Bir idi Artı eksi bir... Hangi birini yedi?  Artı ...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gene-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gümüş el aynası... Bir beyaz mendil', 'bir-gumus-el-aynasi-bir-beyaz-mendil-hasan-akin-vim1l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kan adı yüreğim

                  kanadı...

uzak diyarların türküsüne ağladı.

beyaz merhametin kızıl nehrine akan...

bir gümüş el aynası...

bir beyaz mendil...

nazlı iğde kokusuna savrulan.

-nasıl desem-

öyle kokmalı ki bahçelerin güle sargılı rengi...

dilek ağaçlarına bağlı yüzüne bakmalısın -öyle saf-

günahlarım çok siyah gelemem yollarına

anlasanda geçit yok eşiğine sevdanın

bilsen nasıl dağlıyım nasıl...darmadağın...

yan kuzu yüreğim...öyle yan ki...dayan

çöl yağmuru umuduna mahkum adımla...

sen hep kal orda bünyan...

kan adı gözlerimde ağlayan...', 'kan adı yüreğim                   kanadı... uzak diyarların türküsüne ağladı. beyaz merhametin kızıl nehrine akan... bir gümüş el aynası... ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akın']::text[], 8.5, '{"poet":"Hasan Akın","poet_slug":"hasan-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-gumus-el-aynasi-bir-beyaz-mendil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-seda-calisir-nbu0g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımı yazıyorum bu ilk mısralarıma

En sevdiğim çiçekler soluyor sırayla

Ve ben büyüyorum büyürken bu acıyla

Gözyaşlarımda güneşin pırıltısıyla

Tüm ışıkları kapamak geliyor bazen içimden

Hiç ummadığım bir an güneşi doldurmak odama

Dönmek istiyorum son tren olsada dönmek

Haykırmak istiyorum tüm gerçekleri 

Geri dönmemecesine haykırmak

Tüm herşeyi içime çekmek ve gülümsemek', 'Yalnızlığımı yazıyorum bu ilk mısralarıma En sevdiğim çiçekler soluyor sırayla Ve ben büyüyorum büyürken bu acıyla Gözyaşlarımda güneşin pır...', ARRAY['Türk Edebiyatı','Şiir','Seda Çalışır']::text[], 8.5, '{"poet":"Seda Çalışır","poet_slug":"seda-calisir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalnizligim-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla be gülüm', 'anla-be-gulum-hilal-sayil-de2f2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seninle karşılaşmayı o kadar çok istiyorum ki...

Belki bir gün karşılaşırız, karşılaştığımızda

Gözlerine bakacağım

Nedenine gelince ben 

Gözlerinden ilk başta çok etkilenmiştim.

Çünkü gözlerin beni sevdiğini söylemişti 

Çünkü gözlerin bana birşeyler anlatmak istiyordu,

Çünkü beni görünce gözlerinin içi gülüyordu.

Şimdi anladın mı? 

Neden ilk gözlerine bakmak istememi 

Gözlerine baktıktan sonra 

Yüzümde hafif tatlı bir gülümseme belirecek 

Bunun nedenine gelince; 

Seni görmek bana o kadar mutluluk veriyor ki 

Hatırlar mısın bilmiyorum ama 

Seni ilk gördüğümde seni iyi ki görmüşüm diye düşünerek gülümsemiştim. 

Tabiki bu düşündüğüm şeyi açıklayamadan gülümsemiştim 

Daha sonra güzel anlamlı bir şekilde merhaba diyeceğim 

Bunun nedenine gelince 

O zamanda sana aynı şekilde merhaba demiştim. 

Hani derler ya öyle bir merhaba diyorsun ki altından 

her kelime çıkar 

Şimdi anladın mı bu merhabanın benim için ne kadar önemli 

olduğunu. 

Daha sonra senden merhabanın karşılığını bekleyeceğim. 

Bunun nedenine gelince; 

Ben bunun için ne kadar sabrettim.

Ne kadar Allah''a yalvarıp dualar ettim. 

Daha sonra senin yüzüne birşeyler demeni bekler gibi bakacağım. 

Sevdiğini söyle artık 

Sabrım kalmadı.

ANLA BE GÜLÜM.......! ! ! ! !        

(Hilal Sayıl-2005)', 'Seninle karşılaşmayı o kadar çok istiyorum ki... Belki bir gün karşılaşırız, karşılaştığımızda Gözlerine bakacağım Nedenine gelince ben  Göz...', ARRAY['Türk Edebiyatı','Şiir','Hilal Sayıl']::text[], 8.5, '{"poet":"Hilal Sayıl","poet_slug":"hilal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/anla-be-gulum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pes Doğrusu', 'pes-dogrusu-murat-demir-yfn3f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatın ince ayarı

Birtürlü düzen tutmuyor

Kahrolası şu dünyanın

Derdi çilesi bitmiyor

Bazımız uçar havada

Bazımız yetim,yuvada

Bazımız ki bu ovada

Gününü akşam etmiyor

Bazımızın başı eğri

Bazımızın başka seyri

Bazımız ki çok değerli

Gününe güneş yetmiyor

Yıllardır ki tekerimiz

Bir santim doğru gitmiyor

Sarılıpta adam gibi

Kimse ileri itmiyor

Kimimiz der adam sende

Kimi duymaz ne desende

Kimimiz ki öldürsende

Dünden bugüne geçmiyor

Kimimizin gözü kara

Kimimizin içi yara

Kimimiz ki tam fukara

Gözü güzeli seçmiyor', 'Hayatın ince ayarı Birtürlü düzen tutmuyor Kahrolası şu dünyanın Derdi çilesi bitmiyor Bazımız uçar havada Bazımız yetim,yuvada Bazımız ki b...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/pes-dogrusu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-saban-bektas-rvx4y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah geceler ah geceler ah geceler

Yakar beni yıkar beni ah geceler

Dinmek bilmez umutlarım

Hayallerim gözyaşlarım

Atar beni uzaklara 

Tuzaklara yarınlara

Ben umutsuz bahtı kara

Gecelerim paramparça

Bir vurgundan daha beter

Vurur beni ah geceler

Ah geceler ah geceler ah geceler

Hep hüzünlü hep çileli ah geceler

Dinmek bilmez acılarım

Hayellerim gözyaşlarım

Atar beni çıkmazlara 

Kör karanlık kuyulara

Ben umutsuz bahtı kara

gecelerim paramparça

Bir sürgünden daha beter

Sürer beni ah geceler', 'Ah geceler ah geceler ah geceler Yakar beni yıkar beni ah geceler Dinmek bilmez umutlarım Hayallerim gözyaşlarım Atar beni uzaklara  Tuzakla...', ARRAY['Türk Edebiyatı','Şiir','Şaban Bektaş']::text[], 8.5, '{"poet":"Şaban Bektaş","poet_slug":"saban-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/geceler-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Bininci Mektup', 'bes-bininci-mektup-sahin-erturk-8hqaw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yığınla mektubun var önümde

Kimi 1975 tarihli,kuruş damgalı

Artık zar,zor okuyabiliyorum

Kimi,taptaze

Hani,cillop gibi yesyeni

Kokun üzerinden gitmemiş gibi

Sanki ellerinin izi öylece duruyor

Tarih 2005''i gösteriyor

Tam altıyüz bin lira

Bir mektuba bu para

Deli para bu? 

Bu para 1975''de bizde olsaydı

Ev,araba alır

Yuva kurardık...

Aşkımız

Yokluğa,yoksulluğa yenilmezdi

Resimlerin

Hep siyah,beyaz

Sararmışlar,solmuşlar

Hala gülümsüyorsun

Sıkı,sıkıya sarılmışsın bana

Bırakmam seni der gibi? 

Benimle dalga geçer gibi...? 

Güzelliğin aynı duruor

Eminim bundan eminim

Şimdilerde olsa

Sen dünya güzeli seçilirdin? 

Yığınla mektup,resim var

Yığınla dert var

Dertler kafesinde gibiyim

Acıların Şairi oldum çıktım

Dün duygularımı kaybetmiştim

Bugün

NÖBETÇİ ŞAİRİM

Acılarla,ayrılıkları anlatıyorum

Bıkmadan,usanmadan

Hamasi şiirler yazıyorum

Sevenimde var

Sevmeyenimde? 

Bazıları şiirlerimle ağlıyor

Bazıları ise gülüp geçiyor

Ammada saçmalamış diyorlar

Sevgimin dozajını tutturamadım

Biraz abartılı yazıyorum galiba? 

Zaman hızla akıp gidiyor

Ben KAĞNI bile olamadım

Hiç yol katedemedim

Mutluluk trenine binemedim

Hala bıraktığın yerdeyim

Duygularım aynı

Sevgim aynı''da

Umutlarım küf tuttu

Dün tarihli mektubunda

Yine geleceğim

Bekle yazmışsın

Bayatladı bu sözlerin

Artık inanmıyorum geleceğine

Sahi hiç düşündün mü? 

Gelsen neyi değiştirebileceksin? 

Herşey eskisi gibi olacak mı? 

Çocukların,kocan ne olacak? 

Bu kadar kolay mı gelebilmek

Kolay mı bir yuvayı yıkabilmek? 

Ben,zaten gelmeni istemiyorum

Mektupların yetiyor bana

Resimlerinle avunuyorum ben? 

Yığınla mektubun var önümde

Hangi mektubunu açsam

Hangi mektubuna baksam

Hep seni seviyorum yazmışsın

Dün,böyle yazmışsın

Bugün,böyle yazıyorsun

Peki ama neden? 

Neden biz ayrıldık? 

Herneyse,boşver

Yarın yine mektubunu bekliyorum

Aklına hiç geldimi bilmem

Kaç mektup yazdın bana

Bilmiyorsun

Saymadın değil mi? 

Allah nasip ederse,yarın

5000''inci mektubunu alacağım

Dile kolay 5000 mektup

Say,say oku,oku bitmiyor

Amma ben memnunum

Bıkmıyor,usanmıyorum

Hergün mektuplarını okuyorum

Resimlerine bakıyorum

Nice 5000''nci mektuplarda

Hasret gidermek dileğimle

Hoşçakal sevdiceğim,hoşçakal

Sen mutlu ol,bu yeter bana

Sen mutlu ol,bu yeter bana', 'Yığınla mektubun var önümde Kimi 1975 tarihli,kuruş damgalı Artık zar,zor okuyabiliyorum Kimi,taptaze Hani,cillop gibi yesyeni Kokun üzerind...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":93,"source_url":"https://www.antoloji.com/bes-bininci-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-aysun-erat-aawbh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşi ne gecenin? 

Seni getirsin bana yeter.

El ayak çekilince dünyadan,

Bir ben olurum, bir de sen.

Şu koskoca evren, dar gelir o zaman.

En sevdiğin oyun hangisi?  söyle bana…

Sek sek mi? 

Elim sende mi? 

Yoksa…

Uçurtma mı yapalım Çoban Yıldızı’na  bağlayıp ipi? 

Gel…

En iyisi mi..

Gizlice….

Anneler de uyuyor nasılsa,

Evcilik oynayalım.

Ne dersin? 

02/2005', 'İşi ne gecenin?  Seni getirsin bana yeter. El ayak çekilince dünyadan, Bir ben olurum, bir de sen. Şu koskoca evren, dar gelir o zaman. En s...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oyun-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ferhat''a Mektup', 'ferhat-a-mektup-sahin-erturk-0y4ck', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalancı aşklar var şimdi

Şıpsevdilik moda oldu çıktı

Günlük ilişkilere aşk deniliyor

Göz boyamalar,reklam aşkları

Çıkar ilişkileri

Say,say bitmiyor

Gerçek aşk yerlerde sürünüyor

Mecnun''un kemikleri sızlıyor

Nerede Aslı gibi sevenler

Hani nerede? 

Arzu''nun adı ihtirasa karıştı

Birşey almadan kimse vermiyor

Herkes bir hesabın içinde

Hülya şöhreti böyle yakaladı

Gamze fiziğiyle köşeyi döndü

Sibel sanki elbise değiştiriyor

Hergün bir başkasıyla beraber

Cem aynı yolun yolcusu

Sevgi trenini ilk terkedenlerden

Sevmediği dulun kollarında? 

Rahatlık aklını başından aldı

Tanınmaz biri olup çıktı...

Hızla azalıyoruz FERHAT dostum

İnan bana hızla azalıyoruz

Sana bu mektubu

Asırlar ötesinden yazıyorum

Aşk treninde üç,beş kişi kaldık

Senin gibi dağları delmeye çalışan

Benim gibi DON-KİŞOT olan yok

Yok dostum yok

21''nci yüzyıldan

Öylesine sana yazacak kadar

Destansı,büyük,görkemli aşklar

Malasef yok dostum

Yok,yok işte...', 'Yalancı aşklar var şimdi Şıpsevdilik moda oldu çıktı Günlük ilişkilere aşk deniliyor Göz boyamalar,reklam aşkları Çıkar ilişkileri Say,say b...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ferhat-a-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazap', 'gazap-hekim-coskun-woax6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni unutmam

sen uzun solukta bitiremediğim

günlerce etkisinde kaldığım

gazap üzümleri gibi sürükleyicisin

iticisin yaşama beni

daralıp sıkıldığımda

mistik bir kurtarıcının

yukarılardan bir yerde beni gözetlemesine hapsettim

korkularımı

isyanım hem kendime hem sana

hem kendim

çaresiz anlatımlarım

belirli-belirsiz soluk alışlarım

bir an soluksuz kalışlarım

dur gitme diyemediğim

diyeceğim tuttuysa da demediğim

belki döner diye beklemediğim

günlerce aç susuz direndiğim

sonuçta bir hiç elde ettiğim

tüm istem ve dileklerim

yeniden doğarsam diyedir...

………..

……….

……….', 'seni unutmam sen uzun solukta bitiremediğim günlerce etkisinde kaldığım gazap üzümleri gibi sürükleyicisin iticisin yaşama beni daralıp sıkı...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gazap-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilsen', 'bir-bilsen-meral-yagcioglu-63ni2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni ne çok sevdiğimi ah bir bilsen

Her gece çalan sessiz telefonların

Ardında ben varım hissedebilsen

Bir gün değil, bir saniye bile 

Duramazdın yerinde

Koşardın kollarıma

Sarardım seni

Yüreğime gömerdim

İşte o zaman mutluluk gömleğini

Ateşten olsa bile giyerdim.

Yeter ki sen yanımda olsan daima

Sessiz telefonların ardında değil.

28/06/1997', 'Seni ne çok sevdiğimi ah bir bilsen Her gece çalan sessiz telefonların Ardında ben varım hissedebilsen Bir gün değil, bir saniye bile  Duram...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-bilsen-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '’’’’’Hoşça kalın şairler.’’’’’', 'hosca-kalin-sairler-ali-riza-unal-wywyt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu pazarda alıcı yok.

Toplandı küfemiz  gider oldu

Okkası bir tebessüm oda burada yok

Malımız  meydanda kokar oldu.

Sel oldu bu sözler şükür hasar yok.

Taştı bu dil bendini,tufan oldu.

Bilki Ikrar vedik karar ile sükûta.

Belki zarar bağa bahçeye akar oldu.

Bakır çarşısında altına hacet yok.

Haklıdır sarraf hased ile küfran oldu.

Ehli gönüle, kapanırmı gönül.

Bu fakir sinenizde mihman oldu.', 'Bu pazarda alıcı yok. Toplandı küfemiz  gider oldu Okkası bir tebessüm oda burada yok Malımız  meydanda kokar oldu. Sel oldu bu sözler şükür...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hosca-kalin-sairler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-seref-karakulah-h7ely', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saat bir otuz.

Ay küsmüş sanki.

Korkunç gece başlıyor.

Herkes  uykuda mutlu.

Ben yapayalnızım bu kentte.

Aldığım her nefeste seni soluyorum.

Seni yaşıyorum,yudum yudum.

Sonsuz hayallere kapılıyorum.

Evimiz çocuklarımız oluyor.

Bizim için çalıyor tüm bakire şarkılar.

Pembe dünyalara uçuyoruz.

Kayboluyor ansızın herşey.

Kurduğum hayaller,evimiz,çocuklarımız.

Ansızın kayboluyor,teker teker.

Şimdi zifiri karanlığın ortasındayım.

Yalnızım,yapayalnızım Fatoş.

Gece bir türlü bitmek bilmiyor.

İçim daralıyor,paramparçayım artık.

Ağlamak geliyor içimden,delice.

Simsiyah bir güneş doğuyor.

Sensizliğe,yalnızlığa,çaresizliğe.

Ve geceye ağlıyorum Fatoş.

1974 Ankara', 'Saat bir otuz. Ay küsmüş sanki. Korkunç gece başlıyor. Herkes  uykuda mutlu. Ben yapayalnızım bu kentte. Aldığım her nefeste seni soluyorum....', ARRAY['Türk Edebiyatı','Şiir','Şeref Karakülah']::text[], 8.5, '{"poet":"Şeref Karakülah","poet_slug":"seref-karakulah","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gece-143-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülsen (akrostiş)', 'gulsen-akrostis-muzaffer-erdogan-ymgn9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'G ülersen,gülerim.ağlarsan ağlarım

Ü zülme bitanem bilki yanında ben varım

L ütfedip duyarsan yüregimdeki sesi eğer

S evgim büyür, bütünleşir arşa değer

E zdirme kendini haydi sevgine sahip çık

N e söyleyen olursa olsun gel tabuları yık', 'G ülersen,gülerim.ağlarsan ağlarım Ü zülme bitanem bilki yanında ben varım L ütfedip duyarsan yüregimdeki sesi eğer S evgim büyür, bütünleşi...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Erdoğan']::text[], 8.5, '{"poet":"Muzaffer Erdoğan","poet_slug":"muzaffer-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gulsen-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrep yelkovana inat bu gece', 'akrep-yelkovana-inat-bu-gece-seref-karakulah-gelzi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece,

Okyanuslarda arayacağım seni.

Mutluluklara doğru sürükleyeceğim hayallerimi.

Düşlerimi,pas tutmuş gözlerinde kuracağım.

Nasırlı ellerim.

Bundan böyle gökyüzüne uzanacak.

Bu gece. 

Hislerimin yükünü anlatacağım.

Utanmıyorum sası sası kokmaktan.

Sevmekten,sevilmek çamura bulanmış.

Zaman akıp gitmekte çaresiz.

Gözlerim son yağmurunu çiselerken.

Bu gece.

Pembelere boyuyorum anılarımı.

Zamanı kucaklıyorum,okşuyorum.

Karanlığı öpüyorum dudaklarından.

Umut dolu bakışlarla düşlüyorum seni.

Geçmişi kandırıyorum kaçmasın diye.

Bu gece.

Damarlarımda dolaşıyorsun,alev alev.

Çığrından çıkıyor dudaklar.

Tüm yıldızları çatlatıyoruz,bir bir.

Bir tek vücut gibi yatıyoruz yatağımda.

Akrep yelkovana inat bu gece.

Ankara     1974.', 'Bu gece, Okyanuslarda arayacağım seni. Mutluluklara doğru sürükleyeceğim hayallerimi. Düşlerimi,pas tutmuş gözlerinde kuracağım. Nasırlı ell...', ARRAY['Türk Edebiyatı','Şiir','Şeref Karakülah']::text[], 8.5, '{"poet":"Şeref Karakülah","poet_slug":"seref-karakulah","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/akrep-yelkovana-inat-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kontrolsüz Sevgi/2', 'kontrolsuz-sevgi-2-sahin-erturk-zw6lp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hız sınırlarını aştı

Radar tesbit edemiyor

Dur,durak nedir bilmiyor

Bendeki,Kontrolsüz sevgi

Dağda,bayırda,rampada

Hız kesmez,beşinci vites

Sanki son model mercedes

Bendeki,Kontrolsüz sevgi

Sesten hızlı uçak gibi

Pist''te otomobil gibi

Dizginsiz vahşi at gibi

Bendeki,Kontrolsüz sevgi

Doktor teşhis koyamadı

Hastalığım pek çok farklı

Mümkün değil,karar çıkmaz

Bendeki,Kontrolsüz sevgi

Metre,kumpas çok yetersiz

Ölçülmez,uçsuz buçaksız

Ne yazsam belki faydasız

Bendeki,Kontrolsüz sevgi', 'Hız sınırlarını aştı Radar tesbit edemiyor Dur,durak nedir bilmiyor Bendeki,Kontrolsüz sevgi Dağda,bayırda,rampada Hız kesmez,beşinci vites ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kontrolsuz-sevgi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnkıbaz', 'i-nkibaz-mucahit-gozutok-crexa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ruhum, esaretiyle kıvranır depremlerin

Yüreğimi volkanlar istila etmiş bu gün

Savurmakta narını beynime, cehennemin

Fırtınalar, katlime zira ant içmiş bugün

Siyah gözlerindeki cellâtvari bakışla

Bulutlar mahzeninden beni dikizlemekte 

Zebani narasını andıran bir çıkışla

Ateş mızraklarıyla, hep beni izlemekte

Sıkıştırdı yer ve gök, kapana döndü âlem

Katranlaşan ufuklar, ümitleri kararttı

İnkıbaz  deryasına saplanıp kaldı çarem

Çırpındıkça çıkmaya, daha derine battı

Şaha kalkmış denizler dağlara meydan okur

Feryat sedalarıyla yutarak nehirleri

Tufan zincirini de ‘Yüce  Tezgâhtar’ dokur

İstese, âb-ı hayat eder, tüm zehirleri

					27.07.2002

İnkıbaz:sıkıntı, keder', 'Ruhum, esaretiyle kıvranır depremlerin Yüreğimi volkanlar istila etmiş bu gün Savurmakta narını beynime, cehennemin Fırtınalar, katlime zira...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Gözütok']::text[], 8.5, '{"poet":"Mücahit Gözütok","poet_slug":"mucahit-gozutok","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/inkibaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadehler Kaldırırım', 'kadehler-kaldiririm-i-smet-barlioglu-e6yyn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önümde eski bir meyhane masası olsa; 

Masamda bir şişe şarap,

Biraz öte-beri, bir-iki mum,

Nereden geldiği belli bile olmayan bir hüzünlü şarkı,

Biraz renk, biraz karanlık

Ve biraz da senin hayalin olsa; 

Değmesinler artık keyfime; 

Kıl çadıra çöreklenmiş dört keçili köylü misali

Kadehler kaldırırım kendime.

Az mı hüzünlendim eski masalarda

Karasevdadan ötürü? 

Az mı süzüldü gözyaşlarım yanaklarıma,

Az mı yudumladım kadehime karanlıkları doldurup

Meyhane masalarına az mı yüz sürdüm

Hıçkırıp? 

Yüreğimden çıkmayan bir sensin,

Bir de bu hüzünlü sevda şarkıları,

Şarap mı içtiğimi sanıyorsun kadehlerden? 

Ben seni içiyorum,

Kaderi, nasibi içiyorum; 

Ferman

Yükseklerden.

Ecel kütüğünden farksız bana eski masalar,

Zehirden-zakkumdan farksız şaraplar,

Kadehler birer ağu kadehi,

Bir karasevdandır beni zehirleyip gitmiş,

Kendimi bildim

Bileli.

(BİR ESİNTİLİ KUŞLUK VAKTİ isimli Serbest Şiirler înden >9-10 /100)', 'Önümde eski bir meyhane masası olsa;  Masamda bir şişe şarap, Biraz öte-beri, bir-iki mum, Nereden geldiği belli bile olmayan bir hüzünlü şa...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kadehler-kaldiririm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yarısı', 'gece-yarisi-mehmed-sari-vn11b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece yarıyı çoktan geçti

Söndü tüm evlerde ışıklar

Çerçevede asılı resmin

Bakıyor gözlerimin içine

Kalk gidelim der gibi.

Gece yarıyı çoktan geçti

Ay dolandı dagğarı, ovaları

Kuşlar sabah sarkısına başladı bile

Soldu vazoda sana aldığım çiçek

Bahtına kahreder gibi.

Gece yarıyı çoktan geçti

Bir yıldız kaydı aramızdan

Uçtu kalbim çırpınarak

Gün burnuna vurulup düştü

Kızardı şafakta laleler gibi.', 'Gece yarıyı çoktan geçti Söndü tüm evlerde ışıklar Çerçevede asılı resmin Bakıyor gözlerimin içine Kalk gidelim der gibi. Gece yarıyı çoktan...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Sarı']::text[], 8.5, '{"poet":"Mehmed Sarı","poet_slug":"mehmed-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gece-yarisi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevi Şiiri...', 'sevi-siiri-sezen-coban-kvpsf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yurdumun üstünde uçan kuşlar

Duyun bu sesleri

Bu kadar ağırsa bu sevi şiiri; 

Gitsin o,görmeyeyim

Kapalı bir kutuda saklansın,

Ben ne zaman istersem o zaman çıksın

Yada külleri kalsın bana,uçurayım size doğru

Göç etsin yanınızda..

Bir daha ki mevsime,siz geldiğiniz de

Bir haber uçurun ona

Uğrasın memleketime..

''Her gelen mevsim yeni güzelliklerle gelir''

Kim bilir

Belki ben de 

Ona akar

Onunla taşarım.

Yurdumun üstünde uçan kuşlar

Varın gidin

Söyleyin sevgiliye

Bu kadar ağırsa bu sevi şiiri

Gelsin,eksik öznelerimi tamamlasın

Cümlelerime noktalar koysun.

Birşey yapsın,birşey olsun

Gelsin..

Yine de gelsin! 

Sezen Çoban / İst.23/02/2005', 'Yurdumun üstünde uçan kuşlar Duyun bu sesleri Bu kadar ağırsa bu sevi şiiri;  Gitsin o,görmeyeyim Kapalı bir kutuda saklansın, Ben ne zaman ...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevi-siiri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşındım', 'asindim-celalettin-koz-gdh0g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşındım

Suyundum,ekmeğindim

Aşındım.

Hem damla oldum

Hem de taş

Zaman geçti aşındım.

Taşındım

Sabır taşındım.

Temeline taşındım.

Mezar olsan başucunda taşındım.

Sevgi yol oldu

Sen yol aldın.

Sen sevgiden

Ben kendimden taşındım.', 'Aşındım Suyundum,ekmeğindim Aşındım. Hem damla oldum Hem de taş Zaman geçti aşındım. Taşındım Sabır taşındım. Temeline taşındım. Mezar olsan...', ARRAY['Türk Edebiyatı','Şiir','Celalettin Koz']::text[], 8.5, '{"poet":"Celalettin Koz","poet_slug":"celalettin-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/asindim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Agop un Meyhanesi', 'agop-un-meyhanesi-adulera-ayza-3f4lk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçerde çalan saz ince

İçerdekilerde  ki hastalıkta ince

Saz ve hastalık ince

Bu kadar dert üst üste

Eskilerden bir şarkı g ı r a m a fonda

Bu şarkı hal mi koyar adamda

İçen de söyleyen de komada

Bu şarkılar adamlık mı koyar adamda

İçerde hava mistik

Sorsanız içerdekilerin hepsi aşık

Adınız ney deseniz

Hepsi bir ağızdan m ı s tık

Bir kadeh daha ver

Burada herkes limitin üstünde içer

Peşin para yok borca der

Haftaya al der sahip güler geçer

Havası ince kendisi kalın

Dertlerden istediğinizi alın

Burası hayat öğrenildiği yer

Umut yok hep keder

İçenler söyler

Hizmetkarlar hizmet eder

Aradan yıllar geçer

İçeriye bir cumhurbaşkanı girer

A ğ o p  bir duble rakı der

A g o p hoş geldin cumhurbaşkanım der

Mı s tık kızar

A g o o o o p der! ! ! ! ! ! ! 

M ı s tık hoş geldin der

Mı s t ı k gönül rahatlığı ile içer

Bu şiirde böylece biter……', 'İçerde çalan saz ince İçerdekilerde  ki hastalıkta ince Saz ve hastalık ince Bu kadar dert üst üste Eskilerden bir şarkı g ı r a m a fonda B...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/agop-un-meyhanesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Don-Kişot', 'don-kisot-sahin-erturk-oxanz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biliyorum

Senin gözünde hiçbir şeyim

Bir çakıl taşı kadar

Değerim yok yanında

Ele gelir

Göze görünür birşey yapmadım

Faso,fiso

Ufak,tefek şeylerdi yaptıklarım

Mesala,

Duraklara ismini yazmam

Otobüslere

Boy,boy posterlerini asmam

Sokak serserileriyle

Kanlı,bıçaklı olmam

Bir sonradan görmenin

Kafasını kırmam

Yıllar yılı

Gönüllü kovboyluğunu yapmam

KÜTAHYA''ya

Zorla ismini ezberletmem

Sen iyi giyinesin diye

Çift vardiya çalışmam

Mutlu olasın diye

Seksen kenti dolaşmam

Bin şiirimi

Yalnız senin için yazmam

Bir ömrü

Bir serveti yolunda harcamam

Faso,fiso

Ufak,tefek basit şeylerdi? 

Boşver unut gitsin

Yorma kafanı

Değmez

Bir DON-KİŞOT için

Kafa yormana

Ben senin için

Hiçbir şey yapmadım

Neyimi,neden,niçin seveceksin

Yaşanmamış

Olmamış farzet tüm olanları

Değmez

Bir DON-KİŞOT için

Kafa yormana

Değmez GÖK GÖZLÜM

İnan değmez

Bir DON-KİŞOT için

Kafa yormana değmez,değmez', 'Biliyorum Senin gözünde hiçbir şeyim Bir çakıl taşı kadar Değerim yok yanında Ele gelir Göze görünür birşey yapmadım Faso,fiso Ufak,tefek şe...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/don-kisot-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskitse de Seneler...', 'eskitse-de-seneler-muammer-celik-6mzx1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çoğaldı sayısı 

geride bıraktığım senelerin 

tenimdeki izlerin çok derin...

Yüreğimi sorma

o hala senin 

heyecanım var ya! 

işte o, 

henüz duvağı açılmamış 

bir gelin! 

BirDeli

20.02.2005', 'Çoğaldı sayısı  geride bıraktığım senelerin  tenimdeki izlerin çok derin... Yüreğimi sorma o hala senin  heyecanım var ya!  işte o,  henüz d...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/eskitse-de-seneler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''a Bereket', 'i-stanbul-a-bereket-sahin-erturk-96d7o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbul''a bereket getirdim

İki gündür yağmur yağıyor

Barajlar doldu,taştı

İnsanlar sokağa çıkamıyor

Beşiktaş sular altında

Levent''te göz,gözü görmüyor

Emirgan da ağaçlar yıkıldı

Sarıyer yolu trafiğe kapandı

Yıl ikibin bir

Ağustos''un yirmisi

Hayat durdu

Trafik kilitlendi

İstanbul''a yağmur yağıyor

İstanbul''a bereket getirdim', 'İstanbul''a bereket getirdim İki gündür yağmur yağıyor Barajlar doldu,taştı İnsanlar sokağa çıkamıyor Beşiktaş sular altında Levent''te göz,gö...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istanbul-a-bereket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskançlık Krizi', 'kiskanclik-krizi-sahin-erturk-8y9tc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Körfez krizi değil

Ekonomik kriz değil

Aşkımızın üstüne

Bir kabus gibi

Kıskançlık krizi çöktü

Şimdi biz

Toz duman arasında

Kıskançlık krizini

Yenme uğraşındayız', 'Körfez krizi değil Ekonomik kriz değil Aşkımızın üstüne Bir kabus gibi Kıskançlık krizi çöktü Şimdi biz Toz duman arasında Kıskançlık krizin...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kiskanclik-krizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su sesinde yok olup gittin mi?', 'su-sesinde-yok-olup-gittin-mi-gul-ozp-gqtw6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Su sesinde yok olup gittin mi? 

Sisli sevda sokaklarinda, cam cam üstünde

			Yok olmakta uzak ışık...

Kaç yürek var olmuş suyla akarken? 

Dolu taneleri bombardıman – yüreklerde...

Kemikleri mi delmiş? 

Kanyolu, canyolu seslenmiş mı? 

Çığlıklar koparmakta dolu taneleri,

Su zerreciklerine dönüşüp

Işıklar kırılmış kğbizmle-

Yerbiçimsel çiyimler kavramlaşmakta

Ne yerzüzü katmanları sarmal 

Ne boşalmış bulutlardan su doğrusal

Koşun, kaçın, bagırın! 

Yükselsin ayak sesleriniz...

Gökyüzüne giden yolda, çaresizliğin berisinde

Uzayın boğazı yankılasın

Karanlığın ötesinde ışık serpilsin su zerrecikleriyle

Teker teker...

Uzayın yıldızları,

Sizleri sevmesem aramazdım

Işıksu kanyolunda

Devinimle gelen öncesiz-sonrasız yaşam

Canyolu çıplak sessizliğinde,

Gözler kapalı...

Var olup gittin mi sarmal ya da doğrusal? 

08.11.1990 Ankara GÖ', 'Su sesinde yok olup gittin mi?  Sisli sevda sokaklarinda, cam cam üstünde 			Yok olmakta uzak ışık... Kaç yürek var olmuş suyla akarken?  Do...', ARRAY['Türk Edebiyatı','Şiir','Gül Özp']::text[], 8.5, '{"poet":"Gül Özp","poet_slug":"gul-ozp","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/su-sesinde-yok-olup-gittin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olan', 'sen-olan-ozgur-kokturk-g35il', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şiir düştü kalemimden

İçinde sen olan bir şiir

Yokluğun olmayan

Herşeye rağmen solmayan bir şiir

Yalnızca sen olan...

Gözlerimden uykuyu silen

Seni

Tek seni

Hep seni bilen bir şiir

Bütün bir geceye saran

Saatler boyu sen olan...

Usanmadan

Bıkmadan

Adını haykıran boş duvarlara

Yalnız ellerin

Yalnız gözlerin

Yalnız sen olan bir şiir

Kitaplar dolusu sen olan...

Koşarak giden sana

Koşarak geri gelen

Sıcaklığını getiren

Umudunu getiren

Korkularını yitiren

Bir şiirde binlerce şiir

Dizeleri hep sen olan...

Bir şiir düştü kalemimden

İçinde sen olan bir şiir

Yalanı olmayan

Sözünü yutmayan

Öldürmeyen

Yaralamayan

Her zerresi tek sen olan...

23 / 05 / 2002     02:58', 'Bir şiir düştü kalemimden İçinde sen olan bir şiir Yokluğun olmayan Herşeye rağmen solmayan bir şiir Yalnızca sen olan... Gözlerimden uykuyu...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk İnsanlar İçin Var', 'ask-i-nsanlar-i-cin-var-melih-coskun-2ugtz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk insanlar için var elbette

İnsanlık aşk için değil

Öyleyse ölmekten daha güç değil midir yaşamak? 

Acı çekmek daha zor değil midir? 

Kayıtsızca teslim olmaktan karanlık geceye.

Hırpalanıyor ve hor görülüyorsak

Sevebildiğimiz içindir elbette

Karanlığı korkuttuğu için aydınlık gözlerimizin ışıltısı

Aşk mücadele etmektir

Ateşler içinde kıvrandırırken seni illet bir hastalık

Ayağa kalkıp deliler gibi koşacağın günleri hayal etmek gibi

Yahut sabahlara kadar uykusuz kalıp 

Kendi yüreğinle yarışırcasına şiir yazmak.

Kör olmaktır belki de aşk

Herşeye yüreğinin gözleriyle bakmak

Kendi benliğini unutup

Başka bir bedende varolmak

Birazda acılardı onu anlamlı kılan

Uğruna kan dökülen bayraklar gibi

Yani feda etmek uğruna 

Belki en güzel baharlarını

En güzel yazlarını hiç yaşayamamak

Ancak bunun için en ufak pişmanlık duymamak

Kısaca aşk; 

Teslim olmamak asla...

24.12.2004

ŞIRNAK', 'Aşk insanlar için var elbette İnsanlık aşk için değil Öyleyse ölmekten daha güç değil midir yaşamak?  Acı çekmek daha zor değil midir?  Kayı...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ask-insanlar-icin-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen Ki', 'bir-sen-ki-ozgur-kokturk-8ydb3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sen yaşardı içimde

İçimdeki en kuytu köşede

Bir sen ki; ulaşılmaz

Erişilmezdi

Bir sen ki; 

Parça parça olsa bedenim

Yine dokunulmaz

Bir sen yaşardı içimde

Ölümsüz...

En tenha yerinde

En ıssız sahranın...

Bir sen ki; güleç

Sevgilere sevda dolu

Tükenmez, bitmez güneş

Bir sen ki; binlerce ömüre eş...

Bir sen yaşardı içimde

En güzel şiirlerde

En narin çiçekti

En deli kasırgalara dayandı

Yılları bir bakışa sığdırdı

Bir sen ki; 

Kök salmışken yüreğimin toprağına

Seni kökünden söküp attı...

19 / 05 / 2002     23:38', 'Bir sen yaşardı içimde İçimdeki en kuytu köşede Bir sen ki; ulaşılmaz Erişilmezdi Bir sen ki;  Parça parça olsa bedenim Yine dokunulmaz Bir ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-sen-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ned Kelly', 'ned-kelly-mehmed-sari-6l9kt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bizim Köroğlu gerçek bir kişi miydi

yoksa bir efsane mi? 

Ama yaşatıp getirdi onu günümüze dek

ülkenin ezilenleri,

Yüz yıllar boyu güzelleştirip çoğaltarak,

kendi umudu ve özlemini ona katarak.

Avustralyalı Ned Kelly daha dünkü çocuk,

Ne efsane, ne düş

yani sapa sağlam gerçek kişi

ve yiğit bir döğüşçü.

Çapulcu beylerin bağrında

keskin bir hançer gibi,

Şerif eşkiyasının korkulu düşü...

Ned Kelly isyan demektir

Ned Kelly Avustralya yoksullarının direnci,

Ned Kelly koca bir orman

Ned Kelly tek bir kahraman...

Muzafferin tablosunda dinledim ben bu ezgiyi

Ned Keli ormanlarin eşi,

Ned Kelly bir değil binlerce kişi,

Ned Kelly bir isyan ateşi

''ala çamın, mor meşenin altında

silah çatıp yatmağa''

tıpkı bizim Köroğlu gibi...

Haksızlığa uğrayan mazlumun

onurudur Ned Kelly,

Geleceği karartılan yoksulun 

umududur Ned Kelly.

Okaliptüs ormanlarınca derin,

Okaliptüs ağaçlarınca güçlü

Her ağacın altında bir Ned Kelly yatar

Her ağacın gövdesinde bir Ned Kelly,

Bakışları devlet eşkiyasının üstünde

Çapulcu beylerin göğsünde saplı hançeri...', 'Bizim Köroğlu gerçek bir kişi miydi yoksa bir efsane mi?  Ama yaşatıp getirdi onu günümüze dek ülkenin ezilenleri, Yüz yıllar boyu güzelleşt...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Sarı']::text[], 8.5, '{"poet":"Mehmed Sarı","poet_slug":"mehmed-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ned-kelly-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anlık Özgürlük', 'bir-anlik-ozgurluk-esra-aksu-zfy9h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİR ANLIK ÖZGÜRLÜK

Üç beş kere geçtim kalbinden

Ne akşamını gördüm ne de sefasını

Sebepsiz büyülendim laciverdinden

Oysa her yerde aynıydı şehrin yalnızlığı

Çoraplarımı çıkarıp yürümeliydim

Belki de dansetmeliydim erguvanlarıyla

Geç kalınmış sevginin ilk günüyle sevmeliydim

Adı o olmamalıydı adı başka

Sonrası balık kokulu bir restoran

Şair yürekte güvercinimsi çırpınış

Gecikmiş gençlik,terkedilmiş bir surat

Güneşin kızıllığıyla gecede bir tatlanış

Kimse sormuyor saat kaç,kaçıncı paket

Deniz kaynayıp içten içe bizi kıskanmakta

Yosunları kanıyor,üşüyen omuzlarında ceket

Güneş İstanbul''un cebinde sereserpe uzanmakta

Kanlıca’da kalmayı reddeden yalnızlık

Geç kalmışlığımla denizi koklayıverdi

                                                  avuç içlerimden

Gecenin bir vakti kimsenin umursamadığı/bir anlık

Özgürlüktü yaşanan Kanlıca yolunda 

                           tüm çalınmış güzelliğiyle felekten...

esra aksu/esir düştüm gözlerinde/akis kitap', 'BİR ANLIK ÖZGÜRLÜK Üç beş kere geçtim kalbinden Ne akşamını gördüm ne de sefasını Sebepsiz büyülendim laciverdinden Oysa her yerde aynıydı ş...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-anlik-ozgurluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmek...', 'donmek-ertugrul-sakar-9jycv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonsuz denizde kürekleri bırakıyorum 

Dönmek diye bir arzum yok...

Ne girdaplardan korkuyorum 

Ne akıntılardan 

Artık yönsüzüm 

Yüzüm 

Küreksiz teknemin götürdüğü yerde 

Boş mavice bir ufuk 

Varmak diye bir kaygım yok 

Zamanı kancama takıyorum 

Bakıyorum boşalmış gözlerle 

Dönmek seni görmektir belki 

İşte sensiz uçsuz bucaksız su 

Ölüm altımda bir yorgan 

Belki bu bir aşk uykusu 

Pusu 

Kendime kurduğum bu akış 

Tutunduğum dalı bırakış 

Umutsuzluğu duysun istiyorum bu kan 

Deniz gibi damarlarımda akan 

An 

Demiyeceğim beni,niye anasın 

Bırak denizler akşamlara kanasın 

Söz sözcüklerini uçurdu kuşlar gibi 

Bulutlar hayallerimi kirletmeden asın 

Yasın 

Anlamı yok 

Kürek ayrı, kol ayrı 

Dönmek seni tanımaktır haritada 

Olmaz hiç kimseye hayrı 

Dalgalar akın karanlığa 

Örtün varlıkların görüntüsünü 

Örtün hayallerimin nefesini 

Örtün örtülecek ne varsa 

Bitirin sahiplenmenin sesini 

Dal 

Dalga 

Dalgalandır 

Dalgakıranımı 

Kır...', 'Sonsuz denizde kürekleri bırakıyorum  Dönmek diye bir arzum yok... Ne girdaplardan korkuyorum  Ne akıntılardan  Artık yönsüzüm  Yüzüm  Kürek...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/donmek-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şikayetname 3 / Bıçak! ...', 'sikayetname-3-bicak-naime-erlacin-dx2y0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hayalet bir kent onarılıyor bozkırda

aynalar ruhumun mihenktaşı 

yeşilin özlendiği 

maviye sığınılan kara gün bu

düş imgeler tutuşuyor parmak uçlarımda

dağlık bir yaylada kalmıştı küheylânım

uçamıyoruz ah! 

yüzleşmesi bitmedi ulu dağ zirvesiyle hâlâ

habersizdi 

son keşişten ünlenen duaya kişnerken

atlas divanlarda 

çığlık derleyen harem ağasından

tunçtan heykeller yontarak göğün ak yüzüne 

talan ediyorum belleğimde ne varsa

lanet olsun! 

bedbaht bir gonca düşüyor bağbozumundan 

ne tartıyor terazim ah bilsen! 

nasıl tartıyor 

şirazesi bozuk şu dünyada

bir kefe ağır çekerken 

her şeyin tükendiği kentte çocuklar ağlıyor 

derinleşiyor atardamarımdaki uçurum 

çürüyor kanayan dilim ey yar 

yüreğim çatlıyor 

karanfil kokulu şiirler çakıyorum alnına

sonrası anarşi

-aşk gibi bir şey- 

dahası ne ola! 

böğrümdeki bıçaktan gayrı

(23 Şubat 2005)

(''ŞİKÂYETNAME'', Hayal Yay. Temmuz 2010, Sayfa 50)', 'hayalet bir kent onarılıyor bozkırda aynalar ruhumun mihenktaşı  yeşilin özlendiği  maviye sığınılan kara gün bu düş imgeler tutuşuyor parma...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sikayetname-3-bicak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şikayetname 4 / Kilit', 'sikayetname-4-kilit-naime-erlacin-h0wuk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir vakitte çekilir mandalı

yürek

açılmayan kapı

kilitler kendini öyle

susarım sonra 

acıya giderim

yoldaş olur gözyaşım

bir yudum kahve gibi hatırlı

küller savrulur ateşimden

sessiz bir infilâkı izlerim

hangi mayın tarlası bu

hangi yamaç 

nerede yitirilir 

en hayati organımız

söylenmez hiç

taşa kilit vurur dil 

çözüm değil lâkin kaçmak 

yok edemez kimse izlerini

(23 Şubat 2005) 

(''ŞİKÂYETNAME'', Hayal Yay. Temmuz 2010, Sayfa 76)', 'bir vakitte çekilir mandalı yürek açılmayan kapı kilitler kendini öyle susarım sonra  acıya giderim yoldaş olur gözyaşım bir yudum kahve gib...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sikayetname-4-kilit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-ozgur-kokturk-g41kq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kar yağıyor tipi halinde

Üşüyorum

Taş duvarlarda yankılanırken

Fırtınanın korkunç sesi

Seni düşünüyorum...

Buz kesti elim ayağım

Bembeyaz oldu yemyeşil ağaçlar

Kar kapladı her yeri

Zemheri ayazı hükmünü sürdü

Üşüyorum

Ve bir kuytu köşede gizlenmeye çalışırken

Kar fırtınasından

Seni düşünüyorum...

Dışarıda kalmış zavallı bir kedi yavrusu

Bir de ben

O annesini arıyor, ben seni

Nefesim dondu soğuktan

Ve o zavallı kedi yavrusu sokulurken yanıma

Bir parça ekmek uğruna

Seni düşünüyorum...

26 / 01 / 1997     12:28

ERBAA', 'Kar yağıyor tipi halinde Üşüyorum Taş duvarlarda yankılanırken Fırtınanın korkunç sesi Seni düşünüyorum... Buz kesti elim ayağım Bembeyaz ol...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/usuyorum-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Sözcükleri 9 / Buz Nefes', 'ask-sozcukleri-9-buz-nefes-naime-erlacin-yfl2q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşk emzirirdi bizi

sonra 

un-ufaktık hayata

kaç kapıdan geçemedik 

saydın mı hiç

tuz tutmadı tenimiz

aynaya yazılırdı mektuplar

ne zarf 

ne pul

ne adres vardı

ışık kadar doğup 

ışığa söndük

aşkın büyüttüğü cesetlerdik biz

dudağımızda çoğalan bir duayla 

buza yatırılan nefesler gibi dirildik

ömürler kısa düşer sevdaya bazen

çoğalır ki mazruf buz içinde

çoğalır aşka dair

(23 Şubat 2005)', 'aşk emzirirdi bizi sonra  un-ufaktık hayata kaç kapıdan geçemedik  saydın mı hiç tuz tutmadı tenimiz aynaya yazılırdı mektuplar ne zarf  ne ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ask-sozcukleri-9-buz-nefes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemedim', 'sevemedim-ozgur-kokturk-qalt4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutma demiştin en güzel günlerini

Seninle olan bir anı silemedim

Yalnız seni sevdim dilbeste gibi

Senden başkası ne mümkün! sevemedim

Yıllar yorgun düştü, yollar biçare

Geceler aylak gezer, günler avare

Her yaranın ilacı var, ilacım sende

Sensiz geldi çattı ölüm, ölemedim

Ayrılıklar türkülerde gelir dile

Akar türküm çağlar, döner sele

Sen yokken ölmeyeceğimi bile bile

Bir gün çekip gideceğini sezemedim

Öyle susuz, öyle açken yana yana

Sevdim seni doyasıya, kana kana

Kim aldı ve kim vermişti ki seni bana

Sır oldum kendimde, kendimi de çözemedim

01 / 08 / 2002     03:18', 'Unutma demiştin en güzel günlerini Seninle olan bir anı silemedim Yalnız seni sevdim dilbeste gibi Senden başkası ne mümkün! sevemedim Yılla...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevemedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Eder Ümitler', 'ah-eder-umitler-sadik-softa-tma1j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah eder ümitler, hüzün dolaşır; 

Ellerim  eline, ulaşmayınca.

Sanki ruhum hüzünlerle anlaşır; 

Avuntular benle anlaşmayınca.

Sıcak bakışların, kalbimde özlem; 

Şiire yüklenir, dilimde özlem; 

Artık benle yaşar,benimle özlem; 

Avuntular benle anlaşmayınca.

Şefkatin sesinde, dilin şakırdı; 

Sanki bir kanarya sevda okurdu; 

Gönlüm aşkı ilmik ilmik dokurdu; 

Avuntular benle anlaşmayınca.

Arzular uzanır, ruhuma dolar; 

Bakışın kaybolur,hislerim solar; 

Sıkıntılı sezsem, kaygular dolar; 

Avuntular benle anlaşmayınca.

Gözlerin kapanır,bensiz uykuya; 

Geceler uzanır, sensiz uykuya; 

Hayallerim dalar,tensiz uykuya; 

Avuntular benle anlaşmayınca.

Çankırı-21.02.2005', 'Ah eder ümitler, hüzün dolaşır;  Ellerim  eline, ulaşmayınca. Sanki ruhum hüzünlerle anlaşır;  Avuntular benle anlaşmayınca. Sıcak bakışları...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ah-eder-umitler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatsız Şiir', 'tatsiz-siir-zafer-yazici-4iwi6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasret içine, ayrılık konulsa da

Anlatımında var 

Şairin,

Sertlik ve şirinsizlik! 

ikindi vakti demli çay 

tadında bir şiire hasret

kalmış okur! 

Öyle ki; 

Tanımda kendinde gizli

Tatlı mı? tatlı! 

Şeker mi? 

şeker bittabi! 

hoş, hasretlerin ve ayrılığın 

tadı da olmaz ya! 

neyse, içten ağlamaklı gözlerle

bakmanın ne sırası

ne de vakti şimdi

değil mi? ! 

Öyleyse yum gözlerini! 

Tatlı bir şiirin koynuna doğru

Ey başını, korkma, yaslan

Gitsin! ...', 'Hasret içine, ayrılık konulsa da Anlatımında var  Şairin, Sertlik ve şirinsizlik!  ikindi vakti demli çay  tadında bir şiire hasret kalmış o...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tatsiz-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk dilencisiyim', 'ask-dilencisiyim-mehmet-ekici-8a84o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi Leylalar,aslılar iki yüzlüler 

Mecnunlar,keremler de artık sahte sözlüler 

Aşkı anlamayan,anlatamayan kömür özlüler 

Duyun sesimi neredesiniz kara gözlüler

Öldü mü ne bilmem aşk ve mutluluk 

Hoş geldiniz dertlerim siz oluk, oluk 

Bakın benim aşkımda oldu karakolluk

Verinde gideyim artık bir yolluk', 'Şimdi Leylalar,aslılar iki yüzlüler  Mecnunlar,keremler de artık sahte sözlüler  Aşkı anlamayan,anlatamayan kömür özlüler  Duyun sesimi nere...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ekici']::text[], 8.5, '{"poet":"Mehmet Ekici","poet_slug":"mehmet-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-dilencisiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıdıka', 'sidika-ali-gencay-jbgea', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuşlar sana ne söyledi Sıdıka 

Rüzgar hangi mahrem yerlerine değdi 

Kaç kez ıslandı dudakların yağmurlarla 

Daha kaç kez terk edecek uykular seni 

Aşk haram meyveydi,yedin mi 

Kovuldun mu,terk ettin mi 

Yüreğindeki cenneti 

Bak sevgililer çiçek açmış 

Dışarıda çatır ayaz,zemheri 

Sıdıka,üşüyor musun,al ceketimi 

Ellerin yine yumuşacık mı 

Gözlerine aldığın yeşil 

Baksam,bahar uyanır mı 

Düşsem tenine çise vakti 

Aşk mutluluksa,söyle 

Söyle Sıdıka ağlanır mı 

Şarkılar sana ne söyledi Sıdıka 

Keman at kılında inim,inim inledi mi 

Baktığın gözlerde kim var 

Besteler sana beni söyledi mi 

Gidemiyorum,mıhlı ayaklarım 

Yazamıyorum titrek ellerim 

Sıdıka üşüyorum ver ceketimi', 'Kuşlar sana ne söyledi Sıdıka  Rüzgar hangi mahrem yerlerine değdi  Kaç kez ıslandı dudakların yağmurlarla  Daha kaç kez terk edecek uykular...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sidika-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toy Genç', 'toy-genc-volkan-yoruc-cmmlq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir toy genç varmış vakti zamanında

Mevsimleri güzmüş onun namında

Oysa güller açmış bir bahçedeymiş

Yürürmüş sessizcesine ardına bakmamacasına

Başı eğik yüreği ezik kalırcasına

Çentikler kaplamış yumruklarında

Bir toy gençki yaşarmış gavur zamanında

Deli divane sevmiş oysa 

Cihanı sarmalarmış aşkı boylu boyunca

Dere tepe demeden yürürde varırmış sevdasına

Bilmezmiş ki sevdası başka ateşlere düşmüş

Yanan mumun yalanı olmazcasına 

Bir toy genç vardı yalana kurban gitmiş

Gün dönmüş gece doğmuş

Baykuşlar öterken bülbülleri suskun olmuş

Yaşamadığı yıllarıyla bilinmezliğe karışırken

Bir toy genç varmış ki yüreğine artık toprak dolmuş', 'Bir toy genç varmış vakti zamanında Mevsimleri güzmüş onun namında Oysa güller açmış bir bahçedeymiş Yürürmüş sessizcesine ardına bakmamacas...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/toy-genc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-i-smail-hakki-i-zmir-r5ne9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni görememek,

Beni kör ediyor.

Seni duyamamak,

Beni sağır ediyor.

Sensizlik,

Beni yok ediyor.', 'Seni görememek, Beni kör ediyor. Seni duyamamak, Beni sağır ediyor. Sensizlik, Beni yok ediyor....', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı İzmir']::text[], 8.5, '{"poet":"İsmail Hakkı İzmir","poet_slug":"i-smail-hakki-i-zmir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sensizlik-161-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninim', 'seninim-ozgur-kokturk-yetqi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda gözlerinde gizliydi

Gecenin gölgesi gözlerinde

Yaşamak

Bir yudum suyun hasretiyle

Sensizliğe yanar gibi yaşamak...

Ve yıldırımlar

Kasırgalar

Boranlar

Engin denizler boyu uzanan dalgalar

Vurdumduymaz acılarıma inat

Direncimi harmanlayan çaresizliğim

Ellerinle kurduğum düşlerimdeki

Özlenmemiş özlemlere duyduğum özlemlerim

Gecenin bu vaktinde beni alıp götüren

En güzel diyarların uçsuz bucaksızlığına...

Ve sen

Yine sen! ..

Rüyalarımda bile riyâsız

En koyu karanlığında en parlak ziyânın

Yaşam kalıntılarım

Umarsız...

Derinliğine savrulan sonsuzluğa uzaklığım

Günüm, gecem

Dilimde hecem

İçimdeki kıpırdanışları savsaklayan

Esrarengiz dokunuşlarım

Hiç bir zaman olmamış hayâline...

Acılara serzenişim

Her ne varsa içimde ve dışımda

Sana ait olan benliğim

Ben hep seninim...

27 / 12 / 2000     02:32', 'Sevda gözlerinde gizliydi Gecenin gölgesi gözlerinde Yaşamak Bir yudum suyun hasretiyle Sensizliğe yanar gibi yaşamak... Ve yıldırımlar Kası...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/seninim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiraz Ağacı ve Nenemin Donu', 'kiraz-agaci-ve-nenemin-donu-hikmet-kavas-rt1xg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'evimizin avlusunda

her bahar serpilerek

köyü kırmızıyla kuşatan

sevgili kiraz ağacı

üzülme kuruduğun için

bitmedi ki işin

güneş unutmadıkça seni

daha işe yarayacak dalların

nenemin donunu kurutacaksın 

öyle çekip gitmek yok

kollarını öyle germişsin ki hayata

daha çok yeniyetme

ders alacak duruşundan', 'evimizin avlusunda her bahar serpilerek köyü kırmızıyla kuşatan sevgili kiraz ağacı üzülme kuruduğun için bitmedi ki işin güneş unutmadıkça ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Kavas']::text[], 8.5, '{"poet":"Hikmet Kavas","poet_slug":"hikmet-kavas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kiraz-agaci-ve-nenemin-donu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Geldi', 'zaman-geldi-erdogan-ergin-rooig', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman geldi,

Kapıları çekip gideceğim

Dönüp arkama baktığımda

Ağlayanım çoksa, senden başka

Dinmeyecek, bahara hasretim

Ne açan çiçek umrumda olacak

Ne taze tomurcuk

İçimde derinleşen ağrı olacak

Binlerce fidan dikilecek,

Ama hiçbiri sen kokmayacak

Sen gibi açmayacak yüreğime

Seni düşüneceğim, sebepsizce

Belki ağlayacağım, sözlerime inat

Yokluğunu hissedeceğim, nedense

Nedeni olmayan, uzun günlere

Saydıkça uzayacak hasretim

Belki böylesi daha iyi

Uzadıkça hasret, düşeceksin koynuma

Yüreğime çizdiğim senle

En güzeliyle

Zaman geldi,

Ayrılık vakti

Ellerim havada, beklemekte senin mendilini', 'Zaman geldi, Kapıları çekip gideceğim Dönüp arkama baktığımda Ağlayanım çoksa, senden başka Dinmeyecek, bahara hasretim Ne açan çiçek umrumd...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/zaman-geldi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykır Umudunu', 'haykir-umudunu-ozgur-kokturk-yl1xi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kopuyorsa gülüşlerin rüzgârın alevinden

Tutuyorsa saçların özlemlerin elinden

Düşüyorsa güneşin gecelerin selinden

Haykır umudunu solan çığlıklara

Gizlenme kuytusunda açık denizlerin

Tan vaktidir senin telaşlı gözlerin

Bilsen nelere çare biçâre sözlerin

Haykır umudunu solan çığlıklara

Yalancı sevgilerle, gelenlerle, gidenlerle

Göz yaşlarının tuzuna terkedilsen de

Yalnız düşlerinde boğulsan bile

Haykır umudunu solan çığlıklara

29 / 06 / 2002     04:30', 'Kopuyorsa gülüşlerin rüzgârın alevinden Tutuyorsa saçların özlemlerin elinden Düşüyorsa güneşin gecelerin selinden Haykır umudunu solan çığl...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/haykir-umudunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-erdogan-ergin-452rq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşün,

Ben yokum hayatında,

Belki gördüğün en güzel düşün

Şimdi yaşayabilirsin doya doya

Saklamadan hiç bir şeyi,

Çıkartabilirsin yazdıklarını

Ne de olsa yoksun yazgımda

Oku bulduğun herkese

Göz göze gel, şimdi benden uzakta

Benim olmayan bakışlarla

Korkusuzca....

Düşün,

Ben varım hayatında

Ne kadar da güç değil mi? 

Ben varken, aşkın olması hayatında', 'Düşün, Ben yokum hayatında, Belki gördüğün en güzel düşün Şimdi yaşayabilirsin doya doya Saklamadan hiç bir şeyi, Çıkartabilirsin yazdıkları...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dus-107-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Camçiçeği', 'camcicegi-ozgur-kokturk-y72tx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kısrak değil

Tay gibisin

Okşadıkça sever gibiyim

Sürdükçe yeşil kırlara

Savurur gibisin yeleni

Bir damlasın

Bir çiğ tanesi

Sen suskun gönlümün

Açmamış camçiçeği...

16 / 10 / 1997     20:03', 'Bir kısrak değil Tay gibisin Okşadıkça sever gibiyim Sürdükçe yeşil kırlara Savurur gibisin yeleni Bir damlasın Bir çiğ tanesi Sen suskun gö...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/camcicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklıma Geldiçe', 'aklima-geldice-mustafa-gultekin-bdmcp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'AKLIMA GELDİKÇE					

	Çok özledim Arguvan’ım ben seni				

	Aklıma geldikçe eritti beni		

	Bahçede açardı beyaz gülleri			

	Aklıma geldikçe eritti beni			

	Merkeple katırla dağa giderdim 				

	Koyun güdenlerle sohbet ederdim				

	Öten keklikleri seyir ederdim				

	Aklıma geldikçe eritti beni				

	Gurbet ellerinde artık tükendim		

	Bana sensin diyen dostu görmedim 	

	GÜLTEKİN’im geçen günü bilmedim	

	Aklıma geldikçe eritti beni', 'AKLIMA GELDİKÇE					 	Çok özledim Arguvan’ım ben seni				 	Aklıma geldikçe eritti beni		 	Bahçede açardı beyaz gülleri			 	Aklıma geldikçe e...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gültekin']::text[], 8.5, '{"poet":"Mustafa Gültekin","poet_slug":"mustafa-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aklima-geldice-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alan Olmadı', 'alan-olmadi-mustafa-gultekin-58cwu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ALAN OLMADI                                                

Dağlar kadar bana verdin bu derdi                 

Ne kağnısı çeker nede devesi                        

Satam dedim derdi çektim pazara                  

Benden başka derdi allan olmadı                   

 	

Haktan gelmiş ben bu derde şükre dem         

Mevla’m böyle demiş kime ne diyem              

Dilerim mevladan murada eren                       

Benden başka derdi alan olmadı                    

GÜLTEKİN in başı dertden kurtulmaz            

Mevla’m sabırını hiç eksik etmez                    

Kulun kusurunu Mevla’m çok görmez              

Benden başka derdi alan olmadı', 'ALAN OLMADI                                                 Dağlar kadar bana verdin bu derdi                  Ne kağnısı çeker nede devesi ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gültekin']::text[], 8.5, '{"poet":"Mustafa Gültekin","poet_slug":"mustafa-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/alan-olmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-mustafa-gultekin-h4t60', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ANAM	

	Beni bu dünyaya anam getirdi

                Dokuz ay karnında beni gezdirdi

	Yemedi içmedi beni yetirdi

	Sen benim başımın tacısın anam

	Çalıştın çırpındın beni doyurdun

	Neni çalıp yavrum deyip uyuttun

	Geceleri yatmaz üstümü örttün

	Sen benim başımın tacısın anam

	GÜLTEKİN’e kanat açıp kol gerdin

                Üşümesin diye kundağa sardın

	Karanfil gül gibi beni kokladın

	Sen benim başımın tacısın', 'ANAM	 	Beni bu dünyaya anam getirdi                 Dokuz ay karnında beni gezdirdi 	Yemedi içmedi beni yetirdi 	Sen benim başımın tacısın a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gültekin']::text[], 8.5, '{"poet":"Mustafa Gültekin","poet_slug":"mustafa-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anam-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Çiçekleri', 'kan-cicekleri-nurhan-gokturk-xnd5m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son dakikalarını geçirdiğin o teknede,

Benim nefretimdi, biliyordun,

Sakin denizi kudurtan,

Biliyordun hiç yoktan,

Köpüren dalgalar, içimdeki acılardı.

Biliyorum orada, elimde bıçaklarla,

Seni sonsuzluğa gömdüm,

Biliyordum orada seni değil,

Kendimi öldürdüm.

Öğrendim ölenler kalanlardan daha mutlu.

Vicdan kapılarında boşuna bekleyiş

Boşuna o umuttu. 

Ben istedim böyle bir sonu.

Gözlerime bakanların gözlerinden anlıyordum,

Ne hicranlı bir hayattı bu.

Kendi kendimi bu parmaklıklar arasına ben ittim.

Biliyorum artık  bu kaderi ben çizdim.

Ne seni bana anlatanların.

Ne de beni aldatan senin,

Ne senin, ne onların suçu var,,

Ne kadar zalimsiniz diyemem size,

Ey! bana benzeyen insanlar! ! ! 

Ben ve benim gibiler bu yurdun,

Kan çiçekleriyiz,

Biz  hepimiz bize benzeyenleriz.! ! ! ! ! ! 

Nurhan Göktürk

15.Haziran 1978,Niğde', 'Son dakikalarını geçirdiğin o teknede, Benim nefretimdi, biliyordun, Sakin denizi kudurtan, Biliyordun hiç yoktan, Köpüren dalgalar, içimdek...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kan-cicekleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuyruk Acısı', 'kuyruk-acisi-mustafa-gultekin-yhwq7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KUYRUK ACISI	

Türkiye’nin huzurunu kaçıran

Amerika,İngiltere,Fransa

Yakamıza sülük gibi yapışan

Amerika,İngiltere,Fransa 	

Bunlar soktu içimize ajanı

Edirne’den Karsa kadar vatanı

Emmek için  Türkiye’nin kanını

Amerika,İngiltere,Fransa 	

Türkiye’de yetmiş iki millet var

Hepsi bir arada kardeşçe yaşar

Türkü bölmek için fitnelik sokar

Amerika,İngiltere,Fransa 	

Atamızdır  Türkiye’ye can veren

İzmir’de Yunanı denize döken

Kuyruk acısını daha çok çeken

Amerika,İngiltere,Fransa 	

Toprak namusumuz bayrak kanımız	

GÜLTEKİN’im feda olsun canımız	

Yetmiş iki millet etle tırnağız

Amerika,İngiltere,Fransa', 'KUYRUK ACISI	 Türkiye’nin huzurunu kaçıran Amerika,İngiltere,Fransa Yakamıza sülük gibi yapışan Amerika,İngiltere,Fransa 	 Bunlar soktu içim...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gültekin']::text[], 8.5, '{"poet":"Mustafa Gültekin","poet_slug":"mustafa-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kuyruk-acisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlikte Sen', 'sensizlikte-sen-hasan-can-swlnn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hergün hem acı hem keder,

Canımı alır sanki beni benden eder,

Birde aklıma gelir  o unutulmaz günler,

İşte o an kalbim seni ister.

Sen gittin, ama bırak sen yüreğimde kalsın,

Sensizlikte sen, ölüme bir adım kalansın,

Bırak boşver bütün acılar beni sarsın,

Ama yinede sen yoksan sen neye yararsın.', 'Hergün hem acı hem keder, Canımı alır sanki beni benden eder, Birde aklıma gelir  o unutulmaz günler, İşte o an kalbim seni ister. Sen gitti...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensizlikte-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyarbakırlim yetti.', 'diyarbakirlim-yetti-mehmet-selim-tolay-drkl2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceye özetledim gözlerini medcezirler eşliğinde

bilinmezlikler içerisinde...

özlem çıkmazlarıyla hoyrat savruldum,

gecenin bahar dehlizlerine.

Nerdesin,sensizlik orucunda ben yalnız bir muammayım

nerdesin,bak! bahar geliyor ben gözlerinsizim

yollarda ıslak adımlar kalbim seni heceliyor...

bir sigara yakıyorum,dumanı nefesin oluyor

ben çekiyorum,gülüşlerin kanıma bulaşıyor

bir özlem bir kayboluş başlıyor

dilim seni öğütlüyor...

Of çekiyorum,ahlar eşliğinde

hasretin bir yalaz ateş içerimde

seni seviyorum ki yaşıyorum

gurbet türküleri çığırıyorum

seni istiyor seninle varoluyorum

anla ne olur anla artık beni

ben kimsesiz çocuğu anadolunun

ben güngörmüş gördüğü kadar

ben mahçup çocuğu sevdaların

Sen bir gel ben on gelirim sana doğru

ben anlarım ben bilirim aşktan yoksunluğu

bir kırık hayal oldun yaşatımın mavi sularında

bir karabasansın rüyalarımda,çık gel ne olur artık

gelmezsen gençliğim eskiyecek

baharlar gelmeyecek

adın silinecek balıklar yüzgecinde

sen gel ben beklerim 

bir hayal olur yollarını gözlerim

çık gel artık yetti gayri sensizlik

yetti diyarbakırlım 

yetti sensizlik

23.02.2005', 'Geceye özetledim gözlerini medcezirler eşliğinde bilinmezlikler içerisinde... özlem çıkmazlarıyla hoyrat savruldum, gecenin bahar dehlizleri...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Tolay']::text[], 8.5, '{"poet":"Mehmet Selim Tolay","poet_slug":"mehmet-selim-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/diyarbakirlim-yetti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
