INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Suç*', 'suc-riza-turan-uxbr3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hem, size ne oldu,

Ben sevdim suç,oldu', 'Hem, size ne oldu, Ben sevdim suç,oldu...', ARRAY['Türk Edebiyatı','Şiir','Rıza Turan']::text[], 8.5, '{"poet":"Rıza Turan","poet_slug":"riza-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/suc-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-mustafa-gultekin-l4ghh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YORULDUM		

							Yobazlarla çok uğraştım

							Yaşlandım artık yoruldum

							Bin bir dertlerle tanıştım

						           Yaşlandım artık yoruldum

							Çok dolaştım gurbet eli

							Paslandı sazımın teli	

							Bu gidişin sonu belli

				Yaşlandım artık yoruldum

		

							GÜLTEKİN’im durma çalış

							Tüm insanlar olsun barış

							Gurbet eli karış karış

							Dolaştım artık yoruldum', 'YORULDUM		 							Yobazlarla çok uğraştım 							Yaşlandım artık yoruldum 							Bin bir dertlerle tanıştım 						           Yaşlandım artık...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gültekin']::text[], 8.5, '{"poet":"Mustafa Gültekin","poet_slug":"mustafa-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yoruldum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Çekemezler', 'niye-cekemezler-mustafa-gultekin-si8re', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'NİYE ÇEKEMEZLER

	İnsan ayırmadık sınıf gütmedik  	

	İnsanları insan gibi gözledik

	Mezhebimiz Caferi’dir söyledik

	Niye çekemezler yobazlar bizi

	Çektirdiler bize her türlü zulüm

	Durmadan kan ağlıyor her iki gözüm

	Söylenecek çok sözümüz var bizim

	Niye çekemezler yobazlar bizi

	GÜLTEKİN ağlama kör olur gözün

	Dövüne dövüne tutmuyor dizim

	Edirne’den Kars’sa memleket bizim

	Niye çekemezler yobazlar bizi', 'NİYE ÇEKEMEZLER 	İnsan ayırmadık sınıf gütmedik  	 	İnsanları insan gibi gözledik 	Mezhebimiz Caferi’dir söyledik 	Niye çekemezler yobazlar ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gültekin']::text[], 8.5, '{"poet":"Mustafa Gültekin","poet_slug":"mustafa-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/niye-cekemezler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan Bizim', 'vatan-bizim-mustafa-gultekin-evp6w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'VATAN BİZİM		                    

		Vatan bizim ülke bizim 		 

		El malında yoktur gözüm		 

		Cahilleredir bu sözüm			 

		Et tırnaktan ayrılamaz			

		Vatan bizim satılamaz		

		İnsan ayrımı yapılamaz		 

		Her gördüğün dost sanılmaz		

		Et tırnaktan ayrılamaz		

	

		Çok şehit verdik vatana		

		Canım kurbandır Atama		

		Anıtkabirde yatana 			

		Et tırnaktan ayrılamaz		

		

		Türke ayrım yapmak gelmez		

	                Ülke bütün bölünemez		

		Haksızlığa boyun eğmez		

		Et tırnaktan ayrılamaz		

                                 Doğudan batıya bizim	

	                 Kuzeyden güneye bizim

		GÜLTEKİN im budur sözüm	

		Et tırnaktan ayrılamaz', 'VATAN BİZİM		                     		Vatan bizim ülke bizim 		  		El malında yoktur gözüm		  		Cahilleredir bu sözüm			  		Et tırnaktan ayrıl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gültekin']::text[], 8.5, '{"poet":"Mustafa Gültekin","poet_slug":"mustafa-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vatan-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İş İşten Geçer', 'i-s-i-sten-gecer-ali-kilic-kakiz-zd9x9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pişmanlıklar vicdanları rahatsız eder.

Gözler şaş, kalpler taş, bu ölümden de beter. 

Kahredici azap gelince,iş işten geçer.

Kalbin dili yok, iki zıt şey bir arada bulunmaz.

Ne olur! arsızı huysuzu,dost edinmeseydin. 

Bir avuç pula minnet ettin, sen böyle değildin.

Gönül olgunluğuna,dolgunluğuna erişseydin,

Kalbin dili yok, iki zıt şey bir arada bulunmaz. 

Çevirme Ondan dayanılmaz elâ gözünü.

Gönül okşayıcı ol, ekşitme ak yüzünü.

Onlar hastadır, Hak’tan ayırma kalb gözünü.

Kalbin dili yok,iki zıt şey bir arada bulunmaz.

Lessines / 2001', 'Pişmanlıklar vicdanları rahatsız eder. Gözler şaş, kalpler taş, bu ölümden de beter.  Kahredici azap gelince,iş işten geçer. Kalbin dili yok...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/is-isten-gecer-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-fatih-guzel-8p2m5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önsöz bu şiirin kaderine yazılmış

bakarsan göz ucuyla bulursun aynada

son söz başlamadan bakıver aynaya

                 AYNA

Her insan diğerinin aynasıdır

Bir bakarsın kıyasla kendine varırsın

Bir bakarsın eksiğin gediğinle kendini tanırsın

İnsan insanın aynasıdır.

Seni sevene bakarsın ne bakış

Bi bakmışsın dev aynasındasın

Bilmeden-önemsemeden 

Karınca misali seni seveni ezersin

Seni sevmeyene bakarsın kaşın çatılır.

Bi bakmışsın yan yanasın

Bu bakışla nefreti sezersin

Aynayı anlamaya başladığında

Sevmeyene ne çok benzersin....

şimdi son sözü söylemeli mi? 

daha önce yapacak çok daha işim var

hemen baktım aynaya 

haksızlık etmeyeyim içinizden geçenlere

yazdıklarıma şiir demeyenlere', 'Önsöz bu şiirin kaderine yazılmış bakarsan göz ucuyla bulursun aynada son söz başlamadan bakıver aynaya                  AYNA Her insan diğe...', ARRAY['Türk Edebiyatı','Şiir','Fatih Güzel']::text[], 8.5, '{"poet":"Fatih Güzel","poet_slug":"fatih-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ayna-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Evlat Edindim', 'kendimi-evlat-edindim-umut-ulbegi-euihu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mavi koltuğunu 

evlat edindim bugün

sensizliğe dayanamıyordu

benim gibi

meydan okuyamıyordu

suskun ve mavi geceye

Yedi buçuk metrekare odanı

evlat edindim bugün

kokunu özlüyordu

benim gibi

büyüyemiyordu

acı ve karanlık içinde

Minderlerini

evlat edindim bugün

bizi özlüyordu

benim gibi

uyuyamıyordu

tutku ve aşkla biz sevişmeyince

Kendimi 

evlat edindim bugün

seni duymak, okumak yetmiyordu

bugün kendi yaşamım saydım

seni yaşamayı

Seni

Eylülden

Ekimden

Kasımdan

daha çok sevdim

Bugün kendimi evlat edindim.', 'Mavi koltuğunu  evlat edindim bugün sensizliğe dayanamıyordu benim gibi meydan okuyamıyordu suskun ve mavi geceye Yedi buçuk metrekare odanı...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kendimi-evlat-edindim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokakların Yar Kokuyor Erzurum', 'sokaklarin-yar-kokuyor-erzurum-bican-veysel-yildiz-eab2f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şükrüpaşa''da bir esmer,

Vurdu yüreğime hançer.

Beni Mecnun eyledi; 

Kendisi Leyla''dan beter

Sokakların yar kokuyor Erzurum.', 'Şükrüpaşa''da bir esmer, Vurdu yüreğime hançer. Beni Mecnun eyledi;  Kendisi Leyla''dan beter Sokakların yar kokuyor Erzurum....', ARRAY['Türk Edebiyatı','Şiir','Bican Veysel Yıldız']::text[], 8.5, '{"poet":"Bican Veysel Yıldız","poet_slug":"bican-veysel-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sokaklarin-yar-kokuyor-erzurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deymez Artık', 'deymez-artik-ozkan-sahin-tohxm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'başladım karalamaya,

deymez asla,

allamaya pullamaya,

benimlede olmaya,

dünyada bana göresi

daha belli değil,

şimdiyekadar,

dost ve arkadaşlar,

samimi olarak sevdiklerim,

iyiniyeti kullanmayı bildiğiniz için,

başladım karalamaya,

çıkmayın birdaha karşıma,

deymez artık...

sizin için varolmaya.', 'başladım karalamaya, deymez asla, allamaya pullamaya, benimlede olmaya, dünyada bana göresi daha belli değil, şimdiyekadar, dost ve arkadaşl...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/deymez-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su''ya Bak! ..', 'su-ya-bak-ugur-deniz-ulkegul-h2mmd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu aşk’ mı usta? 

“Bu Aşk deli oğlan”

Öyleyse neden canım yanıyor? 

İçim daralıyor, yüreğim usta, yüreğim…

İçin için kanıyor…

“Seviyorsun da ondan..”

Yok be usta..Sevmek kim, biz kim ola..Gaflet-i hal bizim ki işte..İyi adamız ya görünüşte, rahat battı..Vakitsiz çıktık yola..Neyine gerek ulan bu yaştan sonra sevmek..Kazık kadar adam olduk, aklımız oynaşta..Ne oldu

Usta..Hayrola? Bu gün pek keyiflisin..Bakıp bakıp gülüyorsun..Söyle şu garibe de, o da anlasın..Yine ne düşünüyorsun…

“Sen zaten biliyorsun...”

Neyi biliyorum,

Yahu ben

Okkalı bir yumruk yemiş gibi

Yola seriliyorum..

Durduk yerde kasılıyor

Kastıkça geriliyorum,

Sen bana ne diyorsun..

Allah aşkına söyle usta

Dalga mı geçiyorsun? 

Çok canını yaktım..Ağır söyledim..Ama suç onundu..O başlattı usta..Ben önce sustum..

“Sen mi sustun? ”

Usta gelme üstüme..Zaten kötüyüm..Bana bir “söz” dedi..Menzili yok ki kelamın, deldi geçti..Sonra..Sonrası işte..Sen misin deşen! 

Yaramı dağla dediydim..

Dağımı yaraladı..

Ne kadar kaya varsa zirvelerimde,

Hepsini yuvarladı..

Ben de düşerken ezdim geçtim..Yani şimdi ikimizde birer enkaz..Hadi diyelim ki o yaptı..Ben neden yaptım? 

“Korkuyorsun da ondan..”

………..? 

Usta yapma..Bilirsin beni..Neden korkacakmışım? Nesi varmış korkacak..Bir başımız var verecek,onu da zaten geçtik..

“Başını verirsin de, sırrını kolay kolay verir misin bilmem..”

“Usta ne ilgisi var ya..”

“Düşün evlat düşün..Silah yok..Kalkan yok..Kavga yok..En önemlisi bu bir savaş değil..Orta da kan yok..Ama yüreğini esir alıyor..Nasıl? Ne ile? Neden? Eh nefis bu..Onun da sende payı var..O da vermekten korkuyor..

Hadi itiraf et..Sen korkuyorsun! “

İyice daraldım usta..Darlandım..Kafam karışık..Yüreğim karışık…Sustuğum, söylediğim karışık..

“Suya bak! 

İyi gelir..

Uzun uzun bak..

Seni sakinleştirir..

Ben şu çayı koyayım..

Git hadi git! 

Yeni ısınıyorsun daha.. 

Aşk dediğin ne sandın..

Aşk adamı pişirir..”

Pişirir! Ne bu? Kuzu çevirme mi? Oh olsun..Usta da kovdu seni..Suya bakacakmışım…Ne varsa suda..Suda ne olacak? Balık olur..Yosun olur..Su olur…Ya usta dur! Sana yardım edeyim..

“Git lan kerata! Git demedim mi sana..Hadi git, suya bak…”

Allah allaaaah! Çattık ha..Kıvır şu paçaları hadi kıvır! Söylenip durma! Diyorsa vardır bi bildiği oğlum..Sen kalk altı saatlik yoldan gel, üstüne bi ton fırça..Bi sopamız eksik kaldı..Onu da yedik mi..Yarabbi şükür! İş tamam..Eh be oğlum..Ahmak kafam..Sana o kadar söylemedik mi? 

“Evlaaat..Su nasıl? ”

Derin usta! 

“Sen nasılsın? ”

Serin usta! 

“Sol yanın? ”

.....? 

“Sol yanın dedim oğul

Sol yanın..”

Senin usta! 

“Olmadı! ”

Benim usta! 

“Sorsana be oğlum

Ne konuşursun..”

.......? 

Onun usta! 

Haaah! 

Şimdi oldu…

Çay on dakkaya hazır

Haberin ola! 

Olur usta! 

Olur usta..Olur..Çay da olur, şekerde bulunur..Ben nasıl adam olurum, beni nasıl bulurum..İşte o biraz zor mesel..

Suya bak, su sana baksın, suya bak, sen bir ahmaksın, suya bak, ulan ne salaksın, suya bak,…….

Neden…

Seni düşünmeden

Bir an geçmiyor kadın..

Ne gün..Ne gece….

Bu nasıl bir işkence

Gönül vazgeçmiyor kadın…

Kızgınım sana çok kızgın,

İçimin okyanusları boran,

Dalgalar azgın…

Öfkem yanardağ,

Kelam kurşun ağızlarda

Hedef seçmiyor kadın…

Nasıl gider kervan böyle,

Çöl serabı seyran böyle,

Döner mi bu devran böyle,

Gönül işte..Gel sen söyle,

Senden öte,

Geçmiyor kadın……

Suya bak..Onu düşün..Suya bak..Onda aşın..Suya bak..Odur eşin..Suya bak..Görüşün..Suya bak..Konuşun..

Suya bak..Sevişin..

Hooop! Deve..! 

Sululaşma lan..Yuh! sana..Yuh utanmaz! Arlanmaz! Atarım bak suya seni..Atarım dinime imanıma..Höst! 

Kendine gel…

Ama gözleri..Sahi..Gözleri nasıl da güzel..

Suya bak..Anlaşın..Suya bak..Dinleşin…Suya bak..Barışın…Barışın..Barışın..Barışın…Barışın…

“Evlaaaat! “

Hıh! 

Buyur ustaaa! 

“Suyu unutma! ’”

Suya barıştım usta! ............? ! ! ! ! ! 

“Haaaaah haaah haaa! ! ! ” Allah iyiliğini versin emi.Gel hadi gel..Baka baka sırılsıklam olmuşsun sen orda..Gel hadi çay hazır…İç de ısın, kendine gel biraz..Ha ha ha..”

Ne oluyor yahu..Ne alaka? İyice uçtuk..Kesin sıyırdık! …

Geldim usta..

“Baktın mı? ”

Baktım..

“Gördün mü? ”

Gördüm..

“Bildin mi? ”

Bildim

mi? Neyi? 

Kendini evlat..Kendini..

Hani soruyordun ya iki de bir..

Arayıp duruyordun ya..Aşk nedir? 

Nerdedir diye..

Sen Aşk oldun artık..

Aşk sendedir…

Suya bak evlat..

Suya bak..

Ha ha ha…

……………………………', 'Bu aşk’ mı usta?  “Bu Aşk deli oğlan” Öyleyse neden canım yanıyor?  İçim daralıyor, yüreğim usta, yüreğim… İçin için kanıyor… “Seviyorsun da...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":118,"source_url":"https://www.antoloji.com/su-ya-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Az''da Boş', 'az-da-bos-ozkan-sahin-17a26', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Az''da Boş 

Yaşamak? 

mutlu olmak değil, 

karın ağrısı, 

başağrısı, 

dişağrısı, 

romatizma, 

kalpağrısı, 

bunlarla bitmez 

birde aşk ağrısı. 

başa gelenler, 

öncedenmi yazıldı? 

öyle olsa 

doğmamıza ne gerek. 

ben istemezsen, 

sen arzu etmezsen, 

kader yönlenmez! 

istersen değişirim deli gibi; 

ama ben buyum; 

az deli, 

az dolu, 

az ''da boş.', 'Az''da Boş  Yaşamak?  mutlu olmak değil,  karın ağrısı,  başağrısı,  dişağrısı,  romatizma,  kalpağrısı,  bunlarla bitmez  birde aşk ağrısı. ...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/az-da-bos-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyümü Özlüyorum', 'koyumu-ozluyorum-mustafa-zincirkiran-a25xf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Köyümü özlüyorum.

    Elli altı yılında doğmuş olduğum

    Gözlerimi açınca

    Daha kimseyi tanımadan

    Sadece ben ve anacığımdan 

    Meydana geldiğini sandığım

    O küçücük; ama bambaşka olan 

    Çocukluk  dünyamı tanıdığım

    Köyümü özlüyorum.

    Yaylalarda kar kaplıyken

    Bizim köyde çiçek açar.

    Onbeş tatilde merada

    Oynayan çocuklarla beraber

    Doğan kuzular da kaçar.

    Saçaklarda yuva yapan

    Kırlangıçlara inat sanki

    Çatılara leylek göçer.

    Elbistan’dan doğup kıbleye doğru

    Giderken çaylarla beslenen

    Bağa bahçeye can katan

    Baraj  gerdanlıkla süslenen

    Ceyhan nehri bile selam verip

    Bizim köyün ordan geçer.

    Yazın sıcakmış önemli değil

    Gölgesi de serinletmesin isterse.

    Esen rüzgar yaksa yüzlerimi

    Çatlasa dudaklarım

         Ya da hiç esmese.

         Ceyhan yolçatında inince, 

         Köye gidecek bir araba

         Hemen bulamasam

         Ya da hiç gelmese.

         Köyün  yolunda da

         Yürüsem yirmi dakika.

         Türkü söyleyerek

         Hendeklerdeki kurbağalar 

         Beni dinlese.

         Eğer yolda yalnızsam ve

             Vakit akşamsa daha iyi

             Yalnızlık korkum da azalır.

             Göçmenlerin bal arıları

             Köpekler gibi korkutsa.

             Kanalla yol arasındaki sahada 

             Yine top oynuyor mu acaba 

             Köyümün gençleri? ..

            

              İlk karşılaştığım insan

              Tanır mı ki,  köyünün yetiştirdiği

              Toprağının evladını? 

              Yaşlıysa rahmetli babamı

              Genç ise yaşıtı olan yeğenlerimi

              Söyleyerek anlatsam kendimi.

              Herşeye rağmen yine de bilmese

              Hiç üzülmem inanın...

              Tanır beni yaşıtım olan ağaçlar,

              Yapılırken çocukluğumu yaşadığım

              Çeşmeler, şadırvan ve dikenli teller.

              Değişmiş her şey; kör kuyu neresi? 

              Yayarken koyunları kaçırdığım

              Ekin tarlaları ve çepelce deresi? ..

              Muhacir mahallesindeki evimiz

              Derken sadece otlar var yerinde.

              Haberim vardı söküldüğünden

              Ama yine bakıyorum o tarafa.                                           

             O evimiz ki herşeydi, 

             Bir aileydik biz de herkes gibi.

             İneğimiz oldu bazan 

             Bazan da sürüyle koyunumuz

             Biz de  tarlaya gittik çapa yapmaya,

             Sonra topladık pamuğunu

             Çektik kökünden çatallı küncüsünü.

             Terledikçe aktı terimiz iki kaş arasından

             Hem de lastik gibi uzayarak.

             Ahh bir rüyâ da olsam,

   Herkes varolsa orda.

             Hâlâ en küçüğü olsam evimizin

             Bu rüya hiç bitmese.

             Yine yağmur yağınca

             Biriken sularda koşarken

             Lastikli pantolonum ıslansa.

             Çamur olan sırtım için azar işitsem

             Rahmetli  anacığımdan.

             Bana yeterdi

             Tahta makaralarım ve

             Tellerden yaptığım taksiler.

              Elimle iterdim pil istemezdi.

              İki beyaz yirmibeş kuruşumu

              Kendim harcardım.

              Ne hızlı giderdi bindiğim

              Uzun kamış atım

              Çatalhöyük yolunda. 

              Bana oyuncak olarak gemboy, robot

              Ya da cep telefonunu 

              Kimse vermesin.

              Hiçbir şey istemiyorum...

              Düşünüyorum ve diyorum ki; 

              Eski günlerimiz, yani çocukluk günlerim

              Geri gelse, ahh bir gelse,

              Bir daha gitmese.         

            Hiç gitmese... 

              Hiç...                      

              Gitmese diyorum...', 'Köyümü özlüyorum.     Elli altı yılında doğmuş olduğum     Gözlerimi açınca     Daha kimseyi tanımadan     Sadece ben ve anacığımdan      Me...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Zincirkiran']::text[], 8.5, '{"poet":"Mustafa Zincirkiran","poet_slug":"mustafa-zincirkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/koyumu-ozluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hümeyra''ya mektup/....bitmemesi makuldür', 'humeyra-ya-mektup-bitmemesi-makuldur-mehmet-fatih-uqg1f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hümeyra öğrendim sırrını bu gün

Sevda bir güvercin,örümcek ve ağ

Gerçek sevgilinin ellerindeymiş

Bütün masalların sonundaki dağ...

...........................................', 'Hümeyra öğrendim sırrını bu gün Sevda bir güvercin,örümcek ve ağ Gerçek sevgilinin ellerindeymiş Bütün masalların sonundaki dağ... ............', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/humeyra-ya-mektup-bitmemesi-makuldur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara bulutlar ordusu', 'kara-bulutlar-ordusu-dursun-onal-r2ljo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine başladı çalıyor sevgi şarkısı

Ha kesildi kesilecek korkusu

Bu güzel sevginin üstüne düşen

Sanki kapkara bulutlar ordusu

Hoş başlayan sevgiler bitmek zorundamı

Kaderimde hep bu kötü sonmu olmalı

Yine zifiri karanlıklar gibi

Ufkumda doğan güneş karamı doğmalı

Ölüm sessizliği bürüdü benliğimi

Sanki bu dünyadan çektim elimi

Karabasanlarla uyanır oldum

Bu can yaşıyormu yoksa ölümü', 'Yine başladı çalıyor sevgi şarkısı Ha kesildi kesilecek korkusu Bu güzel sevginin üstüne düşen Sanki kapkara bulutlar ordusu Hoş başlayan se...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kara-bulutlar-ordusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarlık Kapısının iç kısmındaki yazı', 'mezarlik-kapisinin-ic-kismindaki-yazi-mustafa-zincirkiran-l2q1k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kardeş bugün şansın varmış, 

                Şimdi burdan çıkacaksın.

  	Bir gün ikâmet alırsan, 

                Çıkanlara bakacaksın.

                Ölüm gerçek, değil masal,

                Bak bizlere sen de ders al.

                İster hoca ister Gassal 

               Gezenlere bakacaksın.

                Sevinç keder geçicidir,

                Nefesler hep uçucudur,

                Azrailse seçicidir.

                Acınla dost yakacaksın.

                Allah’ın emriyle doğduk,

                Yuvayı sevince boğduk.

                Behlül düşün biz de sağdık,

                Send’ölümü tadacaksın.

                                                  Şubat 2001', 'Kardeş bugün şansın varmış,                  Şimdi burdan çıkacaksın.   	Bir gün ikâmet alırsan,                  Çıkanlara bakacaksın.     ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Zincirkiran']::text[], 8.5, '{"poet":"Mustafa Zincirkiran","poet_slug":"mustafa-zincirkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mezarlik-kapisinin-ic-kismindaki-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenler Günü''ne Hoş Geldiniz', 'ogretmenler-gunu-ne-hos-geldiniz-mustafa-zincirkiran-kuxjt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1996 Yılı Öğretmenler günü için protokole  yazılmıştı.      

Bekledik şu ânı geçmezdi aylar

Günümüze hoş geldiniz efendim.

Muhterem hanımlar, muhterem beyler

Günümüze hoş geldiniz efendim.

Âmirlerin amiridir illerde

Yardım eder felakette sellerde

Karşılanır uğurlanır yollarda

Sayın Valim hoş geldiniz efendim.

Vatan için taşır damarda al kan

Patlamaya görsün olur bir volkan

Düşmana silahtır askere kalkan

Komutanım hoş geldiniz efendim.

Madalyalı şehre biçilmez paha

Maraş büyük şehir olmaz mı daha

Ali SEZAL başkan gelmişler aha

Sayın başkan hoş geldiniz efendim.

Hakemlerle zıtlığı var onların

Hesabını sorar akan kanların

Teminatı onlar bütün canların

Baş Savcı beyim hoş geldiniz efendim.

			

Dert edinir okulları bizleri

Güven verir konuşurken sözleri

İmkân varsa boş döndermez sizleri

Millî Eğitim Müdürüm hoş geldiniz efendim 

		

Eğitimde üniversite övgümüz

Verimli çalışmadandır sevgimiz

O da öğretmendir vardır saygımız

Rektör beyim hoş geldiniz efendim.

Ödeme emriyle ödeme yapar

Emir olmayınca zorluklar çıkar

Rakamlar rakamlar usanır bıkar

Defterdar bey hoş geldiniz efendim. 

Suçlunun düşmanı suçsuzun dostu

Kimselere karşı olamaz kasdı

Cefakar polisin amiri üstü

Emniyet Müdürüm hoş geldiniz efendim.

Ağrırsa başımız o dert babamız

Hasta yatsak yorganımız abamız

Onların da gönlünü almak çabamız

Sağlık Müdürüm hoş geldiniz efendim.

Yurt dışına gidip geleni

Eskiyen kimliği zayi olanı

Yazar hem doğanı hem de öleni

Nüfus Müdürüm hoş geldiniz efendim.

Kanununa akıl yetmez sır yetmez

Taşlık dağ başında fidan mı bitmez

İnşallah ormanda dumanlar tütmez

Orman bölge müdürüm hoşgeldiniz efendim.        

Doğsak ezan, kamet, talkın var ölsek

Yanımızda olur ağlasak gülsek

Hocaların kıymetini bir bilsek

Müftü beyim hoş geldiniz efendim.

Yıllık ünite ve günlük plana

Okey dense görülene olana

Teftişlerde zorlanmasa yalana

Müfettiş beyler hoş geldiniz efendim.

Öğrenciye hem babadır anadır

Okulları araçlarla donatır

İşte okulları onlar yönetir

Okul Müdürlerim hoş geldiniz efendim.

Olmayınca yürütülmez törenler

Saygı duyar tedrisini görenler

Biraz düşünseler maaş’az verenler

Öğretmenim hoş geldiniz efendim.

Mezun olur stajyerdir kurs görür

Hoca olur mumlar gibi o erir

Emekli olurken bir hüzün bürür

Öğretmenim hoş geldiniz efendim.

Bitmedi sözlerim ey adsız nefer

Bakın beraberiz yine bu sefer

Yarın yine ders var başlasın sefer

Öğretmenim hoş geldiniz efendim

Yetişince hizmet eden ellerim

Sevgi dostluk sergileyen dillerim

Emeğimle yeşerttiğim güllerim

Öğrenciler (yavrularım)   hoş geldiniz efendim.

Mesai harcayan hakkı geçenler

Konuşma ve şiirleri seçenler

Bir alkışla mutluluktan uçanlar

Hoş geldiniz teşekkürler efendim.

İsmini saydığım sayamadığım

Hoş geldiniz derken doyamadığım 

Unutup üzmeye kıyamadığım

Hoş geldiniz bağışlayın efendim.

Çok laf edenlerde kusur olurmuş

Dinleyenler o kusuru bulurmuş

Behlül’ü de affedenler olurmuş

Hoş geldiniz bağışlayın efendim.', '1996 Yılı Öğretmenler günü için protokole  yazılmıştı.       Bekledik şu ânı geçmezdi aylar Günümüze hoş geldiniz efendim. Muhterem hanımlar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Zincirkiran']::text[], 8.5, '{"poet":"Mustafa Zincirkiran","poet_slug":"mustafa-zincirkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/ogretmenler-gunu-ne-hos-geldiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '....Kaybetmelere Dair....', 'kaybetmelere-dair-murat-dogan-41gwu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kaybetmelere dair bir şiir yazdım dün gece

ve adına ''SEN'' dedim...

içim yandı seni satırlara dökerken

ve ellerim titredi ismini özenle yazarken

derin bir nefes aldım anladım ki sadece oksijen

kokun olmadan nefes almak niye dedim kendime

yaşam denilen oyunun kurallarından biri oysa sadece

nefes almak gibi,su içmek gibi,

zamanı gelince ölmek gibiydi SeNi SeVmek...! 

sensizlik zamansız ölüm şimdi...

kaybetmelere dair bir şiir yazdım dün gece 

ve adına ''ÖLÜM'' dedim.

sakın üzülme ben artık sensiz değilim.........

OnLy TiMe

19-02-05', 'kaybetmelere dair bir şiir yazdım dün gece ve adına ''SEN'' dedim... içim yandı seni satırlara dökerken ve ellerim titredi ismini özenle yazar...', ARRAY['Türk Edebiyatı','Şiir','Murat Doğan']::text[], 8.5, '{"poet":"Murat Doğan","poet_slug":"murat-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kaybetmelere-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladın mı', 'anladin-mi-nurten-altinok-nq3nk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben, ben değilim o ben

Sen, seni aradığın sende

Öyle diyorsan öyledir / öyle olsun

Sen, sen misin  bendeki o sen

Ne diyorsun

Yargısız 

Sorgusuz

İnfaz derler bunun adına

Ağır gelir kelimeler

Suçlamalar agir 

B i l m i y o r d u m 

Anlatabildim mi? 

'''' Anladın mı''''

Şimdi beni

Anlatabildim mi? 

Sen yine O sen''sin 

Birşey değişmedi.

Hamuru sevgiyle yogrulmus yuregin...

13.08.2012



Ben, ben değilim o ben

Sen, seni aradığın sende

Öyle diyorsan öyledir / öyle olsun

Sen, sen misin  bendeki o sen

Ne diyorsun

Yargısız 

Sorgusuz

İnfaz derler bunun adına

''''Anladın mı''''

..............dediğinde

Çok ağır geldi kelimelerin

Suçlama beni

B i l m i y o r d u m öyle olduğunu

Anlatabildim mi

'''' Anladın mı''''

Şimdi beni

Anlatabildim mi

Sen yine O sen''sin bende

Birşey değişmedi ki

Hamuruna sevgi karışmış bir kere yüreğin...', 'Ben, ben değilim o ben Sen, seni aradığın sende Öyle diyorsan öyledir / öyle olsun Sen, sen misin  bendeki o sen Ne diyorsun Yargısız  Sorgu...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/anladin-mi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaban-cı', 'yaban-ci-umut-dag-qnoz7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çek git yabancı,gözlerimden süzülen yaşlarla beraber,

Yüreğindeki yılan; vefadan,sevgiden bihaber,

Dostlarım,hep yüzümü okşar,sever,

Kara kuytulara saklanmış sırtlanlar,bu halime güler.

Geçse de gözümün önünden Kızılırmak gibi seneler,

Senden tek hatırlayacağım şey; o yaban gözler...', 'Çek git yabancı,gözlerimden süzülen yaşlarla beraber, Yüreğindeki yılan; vefadan,sevgiden bihaber, Dostlarım,hep yüzümü okşar,sever, Kara ku...', ARRAY['Türk Edebiyatı','Şiir','Umut Dağ']::text[], 8.5, '{"poet":"Umut Dağ","poet_slug":"umut-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yaban-ci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bebeğin Çilesi', 'bir-bebegin-cilesi-yetkin-tekin-3496o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoldayım 

Geliyorum dünyaya işte bir sebepten 

Çıkıyorum anamın karnından 

Ebeme çekme ayağımı diyerekten 

Çıktım baktım ne göreyim 

Bir hemşire başımda salakça gülerekten 

Sardılar bedenime kalınca bir bez 

Hapsetti beni geniş bir küvez 

Yanımdaki beş aylık 

Diyor hoş geldin kardeşim çömez 

Bende oldum beş aylık 

Kurtuldum çömezlikten 

Bu kez de başka bir dert 

Süt istiyorum, bıktım sulu yemekten 

Tam emekliyordum 

Annem aldı çekerekten 

Sıyırdı donumu bir güzel 

Sinsice gülerekten 

Üşüyorum dedim anne kapa şu donumu 

Baktım bana mısın demiyor 

Bağırdım avaz avaz artırarak ses tonumu 

Meğer altıma etmişim 

Büktüm utanarak o nazik boynumu 

Biraz daha büyüdüm 

Taktım ayağıma bir pabuç 

Yürüyorum düşe kalka 

Elimde de bir havuç

Yürüme faslı geçince 

Başladım tabii koşturmaya 

Baktım iyice sakarlaştım 

Ulan dedim nerden geldim dünyaya', 'Yoldayım  Geliyorum dünyaya işte bir sebepten  Çıkıyorum anamın karnından  Ebeme çekme ayağımı diyerekten  Çıktım baktım ne göreyim  Bir hem...', ARRAY['Türk Edebiyatı','Şiir','Yetkin Tekin']::text[], 8.5, '{"poet":"Yetkin Tekin","poet_slug":"yetkin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-bebegin-cilesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan Kelimeler', 'kaybolan-kelimeler-berk-gulen-wyauw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana sevgi sözcüğünün içinde saklı olduğunu söylediler, 

Öyle bir dalmışım ki aramaya diğer sözcükler unutulmuş,

Bana umut sözcüğüne saklandığını söylediklerinde öyle bir hırsla bakmışım ki,

Diğer kelimeler küskün kalmış bana,

Bana sabır kelimesinde saklı olduğunu söylediler ve öyle bir sabırla beklemişim ki seni,

Başka hiçbirşeyi beklemeden,

Bana  kader sözcüğünde saklı olduğunu söylediler,

Öyle inandımki kadere,

İnanıcak başka şey bulamadım,

Bana hayat sözcüğünü söylediklerinde,

Karşımda tüm küskün kelimeleri buldum,

Barıştım hepsiyle yanlız birisine çok kızgındım,

O da bana hatırlatılmayan birtanesiydi,

Yalandı, senin gibi...', 'Bana sevgi sözcüğünün içinde saklı olduğunu söylediler,  Öyle bir dalmışım ki aramaya diğer sözcükler unutulmuş, Bana umut sözcüğüne sakland...', ARRAY['Türk Edebiyatı','Şiir','Berk Gülen']::text[], 8.5, '{"poet":"Berk Gülen","poet_slug":"berk-gulen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kaybolan-kelimeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzanamadığım Çocukluk Pastalarım', 'uzanamadigim-cocukluk-pastalarim-umut-dag-5i51e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kekeme bakışlar öperken yüzünü,

Dudaklar mı yaptı sana bunca zulmü? 

Hiç korkma helal sana ananın sütü! 

Verme sakın geri dönmenin sözünü! 

Gurbetsin sen artık,hasretsin,dağlarsın.

Raflardaki pasta kadar uzaktasın.

Üzenlere gül vermektir senin işin,

Kim dedi nefret dolduğunu hayatın?', 'Kekeme bakışlar öperken yüzünü, Dudaklar mı yaptı sana bunca zulmü?  Hiç korkma helal sana ananın sütü!  Verme sakın geri dönmenin sözünü!  ...', ARRAY['Türk Edebiyatı','Şiir','Umut Dağ']::text[], 8.5, '{"poet":"Umut Dağ","poet_slug":"umut-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzanamadigim-cocukluk-pastalarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Yalan', 'koca-yalan-umut-dag-k2ixs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşin yağmurunda ıslandım bugün,

Bir çıkmazda solladım hüzünlerimi.

Kargalarla uçup gittiğin kara gün,

Sığ sularda boğdum ben sevişlerimi! 

Böyle sevme kimseyi sen; kara yılan.

Beddua yok,asla yıkılmasın dünyan.

Şafak vakti,yarasalarla beraber,

Git artık,çık kalbimden,sen; koca yalan!', 'Güneşin yağmurunda ıslandım bugün, Bir çıkmazda solladım hüzünlerimi. Kargalarla uçup gittiğin kara gün, Sığ sularda boğdum ben sevişlerimi!...', ARRAY['Türk Edebiyatı','Şiir','Umut Dağ']::text[], 8.5, '{"poet":"Umut Dağ","poet_slug":"umut-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/koca-yalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Duygu', 'en-guzel-duygu-umut-dag-p6b4s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman yürüsem bir başıma gece,

Bir soru düşer aklıma,bir bilmece.

Umut ve huzur veren duygu hangisi? 

Aşk çıkar ki,dilde tüy bitti tek hece! 

Her bir boğa böğürüyor aşk aşk diye,

Şehvet anladığın,bu cahillik niye? 

Aşık olunacak mutlak varlık ALLAH! 

Gel sen,çekip gidenleri hiç deneme! 

Güzel sev ama duy aşkı bir ALLAH''A,

Bırakıp gitmeyen tek O seni yaya.

Eğer bellersen Peygamber''in yolunu,

Gönlün huzur dolu,yolun açık ola!', 'Ne zaman yürüsem bir başıma gece, Bir soru düşer aklıma,bir bilmece. Umut ve huzur veren duygu hangisi?  Aşk çıkar ki,dilde tüy bitti tek he...', ARRAY['Türk Edebiyatı','Şiir','Umut Dağ']::text[], 8.5, '{"poet":"Umut Dağ","poet_slug":"umut-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/en-guzel-duygu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Puslu Gece(Don Kişot)', 'puslu-gece-don-kisot-umut-dag-t2vj8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çek kürekleri puslu zihnimde sandalcı,

Açıklara git,orada gönlün ilacı.

Korkma,aydınlatır bizi fenerin tacı,

Bilemezsin ne derin,kalpdeki şu acı...

Temizlemekle bitmez bu yosun çöplüğü,

Nerde kim bilir,verdiği sözün yüzüğü? 

Bulsak da gömsem artık baş döndüren hüznü,

O zaman sararım,kanayan yaslı gönlü.

Vurun dalgalar,vurun! Gelin üzerime,

Korkmuyorum sizden,vurun çıplak göğsüme! 

Ejderlersiniz,aslında değirmen olan,

Bir yardımcım sandalcı var bana inanan.

Sandal aydınlandı,doğan ayla beraber.

Yok artık bana,çaresiz inanan nefer.

Ne düşman ejderler,ne değirmenler biter.

Yalnızlıkla kazanılır elbette zafer! ..', 'Çek kürekleri puslu zihnimde sandalcı, Açıklara git,orada gönlün ilacı. Korkma,aydınlatır bizi fenerin tacı, Bilemezsin ne derin,kalpdeki şu...', ARRAY['Türk Edebiyatı','Şiir','Umut Dağ']::text[], 8.5, '{"poet":"Umut Dağ","poet_slug":"umut-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/puslu-gece-don-kisot-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Başkası', 'senden-baskasi-umut-dag-1znun', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Allah''ım Senden başkası gölge,karanlık.

Sensin hasta gönlümün odasına ışık.

Bazısı perdeyi bile bile kapatır,

Seni görmeyen kör göze,bin kere yazık! 

Allah''ım Senden başkası susuzluk açlık.

Sensin veren,çölde gezen bedene azık.

Sağır olup,sanıp Pınar suyunu ılık,

İçer kanarak denizi,anlamaz alık! 

Allah''ım Senden başkası yara,hep kesik,

Seni arzular,baktığın bu et,ruh,kemik! 

Kiracıyım bu dünyada hayatı ezik,

Kalp umut dolu,geleceğim sana yenik!', 'Allah''ım Senden başkası gölge,karanlık. Sensin hasta gönlümün odasına ışık. Bazısı perdeyi bile bile kapatır, Seni görmeyen kör göze,bin ker...', ARRAY['Türk Edebiyatı','Şiir','Umut Dağ']::text[], 8.5, '{"poet":"Umut Dağ","poet_slug":"umut-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senden-baskasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimi Kapasam Her Yer Akşam', 'gozlerimi-kapasam-her-yer-aksam-umut-yalim-zwcjb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerimi kapasam her yer akşam

Gözlerimi kapasam bilmiyorum nerdeyim

Belki Londra sanki Sidibar ihtimal Velingtın

Her yerler akşamsa nerdeyim bilmiyorum

Sanki Rio ihtimal Kiev belki Madagaskar

Ana avrat dalgalara söven bir şilepteyim

Çin Tayvan ve yurdumdan Şiliye kadar

Sırtımda ağır işçi Dünyayı taşıyorum

Altı milyar insana hamileyim

Kalbimde altı milyar can taşıyorum

20''de şarapnel ve bebek vardı kağnılarda

İneboludan Ankaraya ve Akdenize kadar

Şimdi kağnılara yenilen kamyon sürüyorum*

İçinde buğday şeker biraz tuz biraz da insan

Az dursam başım dönüyor Dünya dönüyor

Kendimde değilim çünkü senleyim

Gözlerimi kapasam nerdeyim bilmiyorum

Gözlerimi kapasam her yer akşam.

Ama on parmağınla elimden tutsan bir

Böyle uçsuz bucaksız kaybolmasam

İstanbulda olacam belki

Sanki İstanbul bende olacak

En azından nerde olduğmu bilecem

Yere insan damlayan kan gibi

Kalbimi en son burda bırakmıştım

Şimdi tekrar kalbimi bulmam gerek

Ona buna sorup belki ilk o beni bulacak

Tedavülden kalkan iki eski sevgili gibi

Birbirimizden tam sarılırken ayrılacaz

Çünkü kalbimi yanıma alamam artık

İçremde başka yer yok

Kalbim yokken bir yürek naklettim kendime

Toroslardan tokat tokat bir yürek

Gayrı gene de nerdeyim bilmiyorum

Sanki Samsuna gidiyorum

Sonra Erzurum sonra Sıvas sonra sen

Gözlerimi kapasam bilmiyorum nerdeyim

Kendimle değilim sanki senleyim

Gözlerimi kapasam her yer sen.

Şimdi o bıraktığım kalbimi sen

Sevdiğin bir kitap gibi elinde taşısan

Beni kalbimden tutsan sevecem seni

Muhtemel sen de beni seveceksin

Sen bende olacaksın ben sende olacam

En azından nerde olduğmu bilecem

Ben sende olacam sen bende olacaksın

Ölsem öleceksin yaşasam yaşayacak

Kalbimden tutsan Kıraç çalarak

En sensiz anımda seni ısıtacam

Sensizliğ en sen yerinden ısıracam

Istırap ısırganlar gibi beni ısıracak

Sen bende yaşayacaksın ben sende ölecem

En azından nerde olduğmu bilecem.

Gözlerimi kapasam her yer akşam

Belki Bakü sanki Marsilya ihtimal Maldiv

Virjinya tükürüp Bir Bitlis sarıyorum

Gözlerimi kapasam bilmiyorum nerdeyim

Sanki Sicilya ihtimal Krakov belki İzmir

Ellerim pamuk pamuk kanıyor Iğdırda

Analardan her hangi bir ana saçları kesik

İzmitte deprem ölen oğlunu anıyor

Beni oğlu sanıyor gözleri iyice miyop

Ellerim pirinç pirinç Meriç boyunda

Ve her hangi bir sınırda nöbetlerken

Şimdi sen kalbimden tutsan beni

Uzun uzun ağır ve kalın beni düşünsen

Çünkü senle değilim sevdanlayım

Gözlerimi kapasam sevdan her yer.

Şimdi sen beni kalbimden tutsan

Senle değilim sevdanlayım çünkü

Hem senle hem sevdanla olamıyorum

Aynı anda olamıyorum ölemiyorum

Beni kalbimden tut bilmiyorum nerdeyim

Belki Hatay sanki Hamburg ihtimal Bişkek

Yorulmuşum terimi kömürle siliyorum

Beni kalbimden tut bilmiyorum nerdeyim

Sanki Lizbon ihtimal Pekin belki Bağdat

Yazgıma kefen sarmışlar ölüyorum

Gözlerimi kapasam nerdeyim bilmiyorum

Ama kalbimle değilim çünkü sensizim

Senle değilim çünkü sevdanlayım

Sırtımda Dünyayı taşıyorum artı seni

Kalbimde altı milyar can artı sen

Ama senle değilim bilmem nerdeyim

Gözlerimi kapasam şimdi akşam

Gözlerimi kapasam her yer ben.



* Fransız gazeteci Bay Buyyon iletilen görev nedeniyle, İnebolu- Ankara yolunu kendisine M. Kemal tarafından gönderilen kişi eşliğinde gidiyordu. Birden yan tarafında giden taşıtın adını sordu. Eşlik eden adam: ''Kağnı'' dedi. Bay Buyyon ne işe yaradığını ve böyle yüzlercesinin başında erkek dahi bulunmadan kadınlı bebeli nereye gittiğini sordu. Adam: ''Aslında günlük yük taşımacılığında kullanılan bir araçtır ama şimdi Ankara''ya cephane taşıyorlar, erkeklerin çoğu da cephede olduğundan bu iş kadınlarımıza düştü. Hatta bazısı çocuklarını yolda doğurdu. biz bu yola Hürriyet Yolu diyoruz. Savaşı da böyle kazanacağız'' diye yanıtladı. Bay Buyyon: '' Ha güldürmeyin beni, çok zor bir iş. Karşınızdakilerin uçağı var, kamyonu var. Dostum bana kızmayın ama kağnı kamyonu yenemez.'' dedi. Adam sessiz kaldı.

Sonrası herkesçe bilinir ama şu bilinmeyebilir ki Mudanya Barış Antlaşması''ndan sonra gazetesinde Bay Buyyon günlük yazısını şöyle noktalar: '' Şaşılacak şey Türkler savaşı kazandı ve itiraf etmeliyim ki kağnı kamyonu yendi.''', 'Gözlerimi kapasam her yer akşam Gözlerimi kapasam bilmiyorum nerdeyim Belki Londra sanki Sidibar ihtimal Velingtın Her yerler akşamsa nerdey...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/gozlerimi-kapasam-her-yer-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz''e', 'deniz-e-aysegul-colak-kalayci-1ymx8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir ummanım 

Görebilene

Ben bir kalemim

Yazabilene

Bir ömrü feda ettim

Gönülden sevenine', 'Ben bir ummanım  Görebilene Ben bir kalemim Yazabilene Bir ömrü feda ettim Gönülden sevenine...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Çolak Kalaycı']::text[], 8.5, '{"poet":"Ayşegül Çolak Kalaycı","poet_slug":"aysegul-colak-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/deniz-e-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut Ellerimi', 'tut-ellerimi-cemal-ekren-8gijh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yolum  uzun,

Yolum mayın tarlası.

titrek bir mum ışığı  gibi  adımlarım.

yorgunluğumu  alan,

sigara  kağıdına sardığım lice tütünü.

Bakışlarında  saklı kalan bahar kokusu

Sonrası,

Daracık sokaklara döktüğüm gözyaşlarım.

Esmerleşen yüzümün dip notu; 

Gürleşmeye yüz tutan sakalım,

Kırık aynanın son melodisi.

Virgülünü unuttuğum  acılarım.

Seni demlerken geceye,

Dilime dolaşan komşu kızının fahişeliği,

Yada kaçamak sevişmelerin asansör fantazisi

Şakaklarımdaki kömür karası,

Nefsimizin,

Erkekliğimizin yüz karası

Yada mezesiz

Kırmızı şarabın  sarhoşluğu

Kırmızıya çalan geceye türkü söylemek

Ağlamaklı oluyor  be sevgili

Korkuyorum yaşmaktan tut ellerimi', 'Yolum  uzun, Yolum mayın tarlası. titrek bir mum ışığı  gibi  adımlarım. yorgunluğumu  alan, sigara  kağıdına sardığım lice tütünü. Bakışlar...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tut-ellerimi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Anazili', 'olumun-anazili-kemal-cakir-x5xhr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeni bir yolcu

	Yaşlı gözler

		Boğulmuş sesler

			Minarede salâ.

Salınan haberler

	Gelen taziyeler

		Toplanan eş dost

			Dilenen baş sağlığı

Kılınan namaz

	Alınan yol

		Hazır bir çukur

			Son bir bakış

Taş-toprak

	Kazma ve kürek.	

		Biraz su 

			Biraz çiçek

Son defa ona bakış

	Oradan uzaklaşış

                                 Yeniden yaşama dönüş

			İşte bu korktuğumuz 

	                                                       Ölüm.', 'Yeni bir yolcu 	Yaşlı gözler 		Boğulmuş sesler 			Minarede salâ. Salınan haberler 	Gelen taziyeler 		Toplanan eş dost 			Dilenen baş sağlığı...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olumun-anazili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudaklarımdan...ayak parmaklarıma', 'dudaklarimdan-ayak-parmaklarima-leyla-isik-qknz9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşamın yangını pencerelerde...

 tutkuyla kollarına alırken beni,

 ellerim ellerinde çocuklaşır,

 gökyüzünün tüm yıldızları

 gözlerime inerdi...

 soluksuz yaşadığımız o gecelerde

 ay ışığı

 saçlarına tutunurdu perdelerin,

 dudaklarımdan...ayak parmaklarıma

 meş''aleleriyle inen ateşböcekleriydin..

 dağların eğilip eteklerine

 kır çiçeklerini öpmesi  gibi...

 günün

 en güzel saatleriydin', 'Akşamın yangını pencerelerde...  tutkuyla kollarına alırken beni,  ellerim ellerinde çocuklaşır,  gökyüzünün tüm yıldızları  gözlerime inerd...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dudaklarimdan-ayak-parmaklarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misal,', 'misal-aysun-erat-yjf7h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceyi dost edinir insan,

Bir de siyahsa, en koyusundan…

Değilmez keyfine.

O saklar çünkü, tüm sırları herkesten çok,

Hem sonra, yüzüne de vurmaz adamın, yerli yersiz.

Sırtından da bıçaklamaz, en mühimi…

İyidir gece…

İyi..

Hele de simsiyahsa..

Can dost edinir insan kendine.

Misal,

Ben….

02/2005', 'Geceyi dost edinir insan, Bir de siyahsa, en koyusundan… Değilmez keyfine. O saklar çünkü, tüm sırları herkesten çok, Hem sonra, yüzüne de v...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/misal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanak', 'dayanak-aysegul-colak-kalayci-8zmzy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dayanağımdın

Gidince

Çabuk yıkıldım

Umudumdun

Sönünce

Çabuk kırıldım

Hayalimdin

Gerçek olunca

Çabuk ayrıldım

Zamanımdın

Birlikteyken

Çabuk geçerdin

Gülümdün

Açınca 

çabuk soldun

Sevdiğimdin

Ayrılınca

Çabuk el oldun

Benimdin

Bensiz olunca

Çabuk ellerin oldum

19/04/1995', 'Dayanağımdın Gidince Çabuk yıkıldım Umudumdun Sönünce Çabuk kırıldım Hayalimdin Gerçek olunca Çabuk ayrıldım Zamanımdın Birlikteyken Çabuk g...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Çolak Kalaycı']::text[], 8.5, '{"poet":"Ayşegül Çolak Kalaycı","poet_slug":"aysegul-colak-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dayanak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-kemal-cakir-iktyw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kadeh rakıyım bu akşam

Sarhoşlar masasında.

Beklemekten ateş bastı

Bir ayık çıkıp da

Yavaş- yavaş yudumlasa  diyorum.

Aklım fikrim hep o şişede

O da benden dolu nedense

İçenim yok, içenimiz yok

Bu yüzden; 

Ne olur bu şişe bitse de

Gitsem arınacağım yere diyorum.

Çöksün masa 

Kırılsın şişe

Parçalasın kadehler

Sönsün ışıklar

Uyuşsun rakı 

Bitsin artık bu işkence

Hep birden kaybolup gitsinler

Alkolün yok olduğu bir boşlukta.', 'Bir kadeh rakıyım bu akşam Sarhoşlar masasında. Beklemekten ateş bastı Bir ayık çıkıp da Yavaş- yavaş yudumlasa  diyorum. Aklım fikrim hep o...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yalnizlik-228-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsun..', 'olsun-evren-dalgic-t86g3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'olsun,

dön sen yine de.

belki vazgeçip,

belki de oyun olsun diye.

olsun be.

ağlayışlarım son bulsun.

yeter ki

çamurdan olsun 

sen olsun..

sen dön,

belki de değişirsin.

belki de 

olmaz dediklerin,

bir gün oluverir.

ya da olmasın.

yeter ki bu gönlüme,

artık gam dolmasın.

bak,

yüzümü tükettim işte.

geceleri vesile ettim,

dualarımı,

yanlışlarımı,

yangınlarımı.

sen de yüzünü ekşit,

hiç gülme belki de,

ama bir gün olsun,

bak yüzüme.

olmuyor böyle,

hergün başkasından,

her gün ellerden duyup,

ellerin olmanı.

olsun be.

bir gün karşıma dikilip de,

'' senin olamam '' de.

bir ''sen '' kullan sözcüklerinin içinde.

ben ona da razıyım.

gözlerimde yaşlarla,

o sözü hep içimde taşıyıp,

her gece sabahı onunla yapayım.

ve gözlerinle içmeye başlayayım hüzün içkisini.

olsun.

sen sabah ol da,

ben akşamdan sana sızıyım.

(Ankara 2005)', 'olsun, dön sen yine de. belki vazgeçip, belki de oyun olsun diye. olsun be. ağlayışlarım son bulsun. yeter ki çamurdan olsun  sen olsun.. se...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/olsun-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İ k i Y ü z l ü', 'i-k-i-y-u-z-l-u-kemal-cakir-o402y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tutarsızlığını gördükçe konuşuyorum

Kendi kendime	

Kızgın, üzgün ve dargınca.

Ama dostum olduğun gelince aklıma

Unutup her şeyi, susuyorum 

Birden bire.

Susuyor, düşünüyor ve görüyorum.

O güzel anılar geçiyor

Hafızamın en saygın yollarından, 

Ardı ardına,

Sevgi seline dönüştükçe 

Sevinçle seyrediyorum 

Teşekkür ederek her birine.

Ama, bir müddet sonra

Diğer yüzünü görüyor, aklımın diğer yüzü.

İstesem de istemesem de dinliyor kalbim

Aklımın akıl almaz emirlerini.

Güzel denizleri kirleten atıklardan 

Çöplük olmuş duygulardan takılıyorsun oltama bir- bir.

Hayretle, öfkeyle, üzüntüyle bakıyorum

Görünmezliğinde sana.

Yay gibi gergin sinirlerimle vuruyorum

Kadersizliğe, çirkinliğe, ikiyüzlülüğe

Lanet çizgisinde gidip geliyorum.

Düşünceleri  titrek, elleri korkak,

Aklı karmakarışık beynimin.

Neyi görmek, neyi duymak istediğinin

Bilmezliğini yaşıyor.

Şaşırıyor bu durumuna sevginin

Kar yağıyor  gönlümün enginlerine

İki yüzlü duygular onu üşütüyor

Biliyor musun?', 'Tutarsızlığını gördükçe konuşuyorum Kendi kendime	 Kızgın, üzgün ve dargınca. Ama dostum olduğun gelince aklıma Unutup her şeyi, susuyorum  ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/i-k-i-y-u-z-l-u-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Söyle...', 'sen-soyle-i-brahim-ethem-bingul-scnhg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saçların

Büklüm büklüm

Yanağın

Pempe güldü

Konuştuk

Ayak üstü

Yıllar önce bu yerde...

O gün hep hayalimde

Çiçek açmış dal gibi

Gözlerimin önünde

Silinmedi, gitmedi

Desem ki

Sanki dündü...

Hâlâ canlı

Dün gibi

Gözlerimin önünde...

O gün

Gözlerim gözlerinde

Kulağım sözlerinde

Her şey yerli yerinde

Ve karşılaştığımız an

Önce

Bakışların üstümden

Yere doğru süzüldü...

Sorarım hep kendime

Sen

Tatlı rüya mıydın

Görüp de bilmediğim

Yoksa bana yepyeni

Bambaşka dünya mıydın

Ayak basıp üstüne

Henüz yürümediğim...

Dostluk

Birkaç dakika

Konuşma üç-beş satır

Fakat sonuç harika

Bir anı, geçse asır

İzleri var şuurda...

Yoksa, yoksa

Sen söyle

Bu hakiki aşk mıdır? ..

Antalya 12:10', 'Saçların Büklüm büklüm Yanağın Pempe güldü Konuştuk Ayak üstü Yıllar önce bu yerde... O gün hep hayalimde Çiçek açmış dal gibi Gözlerimin ön...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sen-soyle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gündüz Müslümanım Gece Kafir', 'gunduz-muslumanim-gece-kafir-aysegul-colak-kalayci-xvn2p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gönül varki bende

Sormayın gitsin

Anlatılmaz dil ile

Yazılmaz kalemle

Bir yanım Sakarya''da

Kurulu çilingir sofrasında

Efkar dağıtmaktayım kendime karşı

Bir yanım Kabe''dedir

Tavaf etmekteyim kıbleme karşı

Bürünmüşüm ihrama

Şükür duasındayım yaradana

Bir yanım solcudur

Baş kaldırırım düzene

Ezilmişlik yalnızlık,horlanmak olmasın derim

Adalet dağıtırım aklımca

Adam gibi adamlık olsun isterim

Bir yanım sağcıdır 

Uyum sağlarım herkesle

Ne kavgadan yanayım nede barıştan

Herşey kafama göre olsun isterim

Bir yanım hocadır

Beş vakit namazda

Elimi eteğimi çekmişim tüm şerlerden

Sabah akşam niyazdayım

Ekmek elden su gölden

Bir yanım hovardadır

Aklım güzel olan herşeyde

Yenilsin içilsin isterim

Birşey kalmasın sabaha

Bir yanım alenidir

Bir yanım sır küpü

Akşam

Aklıma düşer ''Hayyam''

Badelerde sefa süreriz

Yar doldursa biz içeriz

Sabah ezanla uyanırım

Tüm gövdem ter içinde

Ayılmışım hesap sorarım kendime

Bu gönül,bu kahrolası

Çok taraflı gönül 

Nasıl edecek bilmemki

Gündüz Müslümanım gece kafir', 'Bir gönül varki bende Sormayın gitsin Anlatılmaz dil ile Yazılmaz kalemle Bir yanım Sakarya''da Kurulu çilingir sofrasında Efkar dağıtmaktayı...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Çolak Kalaycı']::text[], 8.5, '{"poet":"Ayşegül Çolak Kalaycı","poet_slug":"aysegul-colak-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/gunduz-muslumanim-gece-kafir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Sevdalandığım', 'ah-sevdalandigim-ozan-kiratli-xqqpz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzelin sevdasıdır aşığa hayat veren

Ah sevdalandığım

Neden bu kadar güzelsin

Yarin gülüşü güzelse aşığın derdi bitermiş

Ah sevdalandığım

Neden en güzel sen gülersin

Bir şansım olsa neler vermezdim

Ah sevdalandığım

Bilirim bir şans vermezsin

Umut yitince bir gönülde

Gitmek gerekir sessizce

Sevmek aşk olur mu iki gönül birleşmedikçe

Ah sevdalandığım

Yine de katlanır tek gönül sevgisizliğe

Ve anlar ki

Bazen sevmek vazgeçmektir

Vazgeçip kendinde sevmektir', 'Güzelin sevdasıdır aşığa hayat veren Ah sevdalandığım Neden bu kadar güzelsin Yarin gülüşü güzelse aşığın derdi bitermiş Ah sevdalandığım Ne...', ARRAY['Türk Edebiyatı','Şiir','Ozan Kıratlı']::text[], 8.5, '{"poet":"Ozan Kıratlı","poet_slug":"ozan-kiratli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ah-sevdalandigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Yükü', 'yasam-yuku-kemal-cakir-yrqyp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adımları gitgide ağırlaştı,

Omuzlarındaki yükü 

Taşıyamaz bir haldeydi.

Bir iki adım daha attı ve durdu

Etrafına bakınıp oraya çöktü; 

İki kitap çıkardı gönül kütüphanesinden

Koydu avuçlarının ortasına,

Dikkatli- dikkatli okudu sağ avucundaki 

''Yaşam Yükü'' isimli olanını.

Sonra terledi yüzü, avuçları da

Çünkü içindeki köprüden geçiyordu 

Onca ağır yükü ile birlikte

Dayanamayıp kapattı bu kitabı 

Asla bulamamıştı anlamlı tek bir kelime.

Diğerini açtı, ''Sadakat'' idi 

Yaprak -yaprak gözleri önüne serilen.

''Oh be! '' dedi ve rahatladı; 

Saçları savruldu sayfaları çevirdikçe 

Gözleri daha bir umutla gezindi

Sadakat satırları arasında ve

Sordu kendi kendine:

''Neydi, yaşamın onca yüküne rağmen,

Kime ve ne için idi bu sadakat? '' 

Bir türlü cevap bulamadı,

Bunu da kapattı,  biraz da kızgınca.

Sonra; 

Elleri ile yüzünü,

Nefret ile sevgisini,

Cesareti ile korkusunu...

ve

Sonra da; 

Hatasıyla, sevabıyla 

Ömrünün kitabını kapattı.', 'Adımları gitgide ağırlaştı, Omuzlarındaki yükü  Taşıyamaz bir haldeydi. Bir iki adım daha attı ve durdu Etrafına bakınıp oraya çöktü;  İki k...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yasam-yuku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuzluğun Yenilgisi', 'umutsuzlugun-yenilgisi-kemal-cakir-trwb6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mavi göklerin serin yalnızlığı var gözlerinde

Üşüyor ve korkuyorsun

Yıldız yıldız düşse de aklının ambarlarına umut

Umutsuzluk yağıyor sözlerinde 

Sağanak sağanak, durduramıyorsun.

Umutsuzluğa düşmek için sebep arama:

İster hızlı ve bulanık aksın dereler

Kapkara baksın deniz

İsterse kırıp yıksın rüzgarlar 

Bağı bahçeyi

Yas tutsun bülbüller.

İster kuşkulu baksın yıldızlar

Gözlerinin önündeki aydınlığa

İsterse haksız haklı olsun bir ara

Önemi yok

Onca haklının yanında.

Umutsuzluğa teslim olma sakın; 

O temiz, dürüst duygularınla 

Zafere hazırlan! 

Kısa sürede onu bozguna uğrat,

Hem de tek  bir  vuruşla...

Sonra, sonra duyacaksın ki! 

Mutluluğun sesi ulu orta  yankılanmakta', 'Mavi göklerin serin yalnızlığı var gözlerinde Üşüyor ve korkuyorsun Yıldız yıldız düşse de aklının ambarlarına umut Umutsuzluk yağıyor sözle...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/umutsuzlugun-yenilgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler (45) '' Bahar Gelmiş Neyime...''', 'maniler-45-bahar-gelmis-neyime-abdullah-atay-zusod', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gönül bir kez sevdi mi

unutulur mu o yar

o yarin kirpikleri

ok olur sinem oyar....

beni saran o yardı

gönül sesim duyardı

sevdamızın yoluna

gonca güller yayardı...

sesimi dağ taş duyar

bir kerede ‘gel ‘ de yar

aşkınla mecnun oldum 

gezerim diyar diyar...

bahar gelmiş neyime

kavuşsam sevdiğime

sevdiğimi görünce

ay doğar yüreğime...

yarim çember oyalar

kaşın gözün boyalar

yıllarca  peşindeyim

o yar beni oyalar...

yarim kahve pişirir

köpüğünü taşırır

gönül yari görünce

neden böyle şaşırır...

balla kaymak ezelim

badeleri süzelim

vuslatın bağlarında

sarmaş dolaş gezelim...

neden gittin nedensiz

nasıl olurum sensiz

deli divane gönlüm

ağlar sensiz çaresiz....

abdullah atay der ki; 

herkese sırrın açma

haramı yiyip içme

dostlarını görünce

hatır sormadan geçme....', 'gönül bir kez sevdi mi unutulur mu o yar o yarin kirpikleri ok olur sinem oyar.... beni saran o yardı gönül sesim duyardı sevdamızın yoluna ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/maniler-45-bahar-gelmis-neyime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Şahidim', 'zaman-sahidim-bayram-simsekoglu-2juj3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yarınsız, yalnız ve de kravatsız.

Adam yaşımdayım.

Biraz üzülüyorum geçmişe.

Biraz da korkuyorum gelecekten.

Her şeyin kıyısında,

yarınsız, yalnız ve de kravatsız.', 'Yarınsız, yalnız ve de kravatsız. Adam yaşımdayım. Biraz üzülüyorum geçmişe. Biraz da korkuyorum gelecekten. Her şeyin kıyısında, yarınsız, ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Şimşekoğlu']::text[], 8.5, '{"poet":"Bayram Şimşekoğlu","poet_slug":"bayram-simsekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zaman-sahidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Gitmedin(ö l m e d i n)', 'hic-gitmedin-o-l-m-e-d-i-n-birsen-ates-jpgnb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'doğum günün

ama sen yoksun

uzaklardan

belki de gülümsüyorsun

yıl oldu acı bulutları hala üstümde

yüreğim acıyor

yaşam durdu zaman yok

yok artık zaman

her şey boşlukta

saksıdaki çiçekler soldu

yüzümde gülüşler dondu

buz gibi ayazdayım

üşüyorum

hissizleşti duygular

ölüm karşısında çaresiz

ölüm /sensiz

içimde şiirler var 

tamamlanmamış

o gün bugündür yazıyorum

seni yazıyorum

yaşamı acıyı

zor geçen günleri

hayalleri geleceği

yazıyorum yaşıyorum

sanki hiç gitmedin

benimlesin

Rahmetli eşime', 'doğum günün ama sen yoksun uzaklardan belki de gülümsüyorsun yıl oldu acı bulutları hala üstümde yüreğim acıyor yaşam durdu zaman yok yok ar...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hic-gitmedin-o-l-m-e-d-i-n-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-bayram-simsekoglu-egagx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben derdimi susuyorum,

ondan bütün yalnızlığım.

Benim derdim yalnızlığım,

ondan bütün suskunluğum.', 'Ben derdimi susuyorum, ondan bütün yalnızlığım. Benim derdim yalnızlığım, ondan bütün suskunluğum....', ARRAY['Türk Edebiyatı','Şiir','Bayram Şimşekoğlu']::text[], 8.5, '{"poet":"Bayram Şimşekoğlu","poet_slug":"bayram-simsekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalnizlik-229-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Geleceksin', 'yine-geleceksin-hatice-bediroglu-do2x7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gittin…

Sensiz kaldım.

Ev öylesine boş ki! şimdi.

Meğer varlığınla,

Sen doldurmuşsun,

Her bir köşesini.

Diş fırçan ile birlikte,

Parfümünü gördüm.

Rengarenk açmış,

Bahar çiçekleri gibi durmakta,

Aynanın önünde.

Açıp kokladım.

Sen kokuyordu.

Koklamaya doyamadım.

Arzular doluştu bedenime..

Ellerimle dokundum.

Sanki! senmişsin gibi,

Sevdim…

Geride bıraktıklarını.

Sana ait olduklarını bilmek,

İçimi huzurla doldurdu.

Sıcacık oldu yüreğim. 

Kendime…

Aynada gülümsedim.

Biliyorum ki! 

Yine geleceksin.

Başın kucağım da,

Anlattıklarımı dinlerken,

Gözlerin gözlerime takılı,

Sarsılarak…

Kahkahalarla  güleceksin.

www.haticebediroglu.net

(Şiirlerimin hepsi Noter tasdiklidir)', 'Gittin… Sensiz kaldım. Ev öylesine boş ki! şimdi. Meğer varlığınla, Sen doldurmuşsun, Her bir köşesini. Diş fırçan ile birlikte, Parfümünü g...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yine-geleceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünemezdim', 'dusunemezdim-i-smet-barlioglu-p0yvp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşünemezdim

Yüreğimin bu viran bağlara döneceğini,

Yağmursuz havada bağrına yıldırımlar düşeceğini,

Böylesine sahipsiz kalacağını düşünemezdim.

Kader öyle bir koydu ki; önüme hesabımı,

Nasip öyle bir kapattı ki; defterimi,

Bir anda viranelerde buluverdim

Kendimi.

Ah, bu alevler içinde yanası yürek, ah…

Ah bu gördüğüne güvenen,

Ah bu gördüğünü seven yürek…

Ben seni nasıl cezalandırsam? 

Nerelere sürsem seni? 

Ömür boyu uslanamadığını

Sana nasıl

Bildirsem? 

Aklıma mı gelirdi yüreğimin onunla işbirliği yapacağı? 

El ele verip kanıma ekmek doğrayacakları? 

Gecemi-gündüzümü zehir-zemberek edecekleri? 

Aklıma mı gelirdi peşlerine düşeceğim? 

Aklıma mı gelirdi

Mum ışığına hasret dehlizlerde

Ölümlerden ölüm

Beğeneceğim? 

Anladım ki; rüzgarı avuçlamışım sevda yerine,

Akarsuları tutmaya çalışmışım avuçlarımda,

Her gün yeni bir tufan,

Her gün bir yeni deprem

Umutlarımda,

Her gün bir başka yara gönlümde,

Ben ona ne kadar yaklaşırsam yaklaşayım,

O benden çok

Ötelerde.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

BİR ESİNTİLİ KUŞLUK VAKTİ isimli Serbest Şiirler înden > 11-12/100)', 'Düşünemezdim Yüreğimin bu viran bağlara döneceğini, Yağmursuz havada bağrına yıldırımlar düşeceğini, Böylesine sahipsiz kalacağını düşünemez...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/dusunemezdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çare', 'care-sair-shimalwest-o2vcf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ah bu biçareye gösterin bir çare

olacak mı herşey virane

ne gerek şimdi düzeltmeye

taşları aynı yere yerleştirmeye

sarsılınca yeryerinden birden

taş taş üzerinde kalmıyor aniden

düşünmek lazım bitirmeden

arkanı dönüp gitmeden

gözlerim daha bir kısık bakıyor

sanki daha derinleri görüyor

ama yine de bilemiyor

öyle mi böyle mi çözemiyor

yutkunurken boğazımda düğümlenir gibi

dilimin ucundan dışarı çıkamaz gibi

yapmak isteyipde yapamaz gibi

içinden hiç çıkılmaz gibi

zaman neleri değiştirebilir

istemek neye yetebilir

istemesede insan gidebilir

dur diyen nasıl durdurabilir

şimdi yeniden çaba harcamak için

kaybedileni kazanmak için

durdum bir yere gitmemek için

kımıldamadan eskiye dönmek için..', 'ah bu biçareye gösterin bir çare olacak mı herşey virane ne gerek şimdi düzeltmeye taşları aynı yere yerleştirmeye sarsılınca yeryerinden bi...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/care-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolunay', 'dolunay-sair-shimalwest-g0z49', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu gece dolunay var bulutlar arasında

farketmez ama bulutlar olsada

değişim vakti kurt olana

kendi kendini ısırmaya

sadece bir gecelik saltanat belki

ömür boyu olsa ne farkederki

ya hep ya hiç demek vakti

gelmeyecek gibi sanki

gün ağırıp ay kaybolduğunda

bekleyiş sonraki dolunaya

öylesi bir döngü burada

haklı haksız yok illa

herkes beni karşısına aldı şimdi

nefret ettim kendimden sanki

olsun yine alıştığım gibi

olmadı ki hiç yanımda biri

ateşlesin herkes silahını şafakta

yoksa kaybolacak kurt sabahla

şansı kalmayacak kimsenin vurmaya

bitirin şimdi işimi burada

mennun mu herkes artık yokum şimdi

ne kolay oldu değil mi dinlemeden beni

zaten ne fark eder ki sonum belli

boşver işte geldi ölmek vakti', 'bu gece dolunay var bulutlar arasında farketmez ama bulutlar olsada değişim vakti kurt olana kendi kendini ısırmaya sadece bir gecelik salta...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dolunay-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski halim', 'eski-halim-sair-shimalwest-lm0up', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gecelerim gündüzüme karıştı

uykusuzluk sanırım bana alıştı

üzerime anlamsız bir ifade yapıştı

eski halim beni böyle bıraktı

saçım sakalım birbirine girdi

koyvermişlik içime işledi

bu halime sigara paketleri yetmedi

eski halim beni böyle terk etti

yürüdüğüm yollar şimdi yabancı bana

gittiğim yerler daha bir başka

olmak istemiyorum artık burada

eski halim beni böyle.........

kelimeler bile beni terk etti

yazacak birşey bulamadım gitti

galiba artık burada bitti....', 'gecelerim gündüzüme karıştı uykusuzluk sanırım bana alıştı üzerime anlamsız bir ifade yapıştı eski halim beni böyle bıraktı saçım sakalım bi...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eski-halim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mermi', 'mermi-sair-shimalwest-wn61r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'öyle kolay ki o mermiyi bulmak 

soğuk demirin içine sokmak 

bir parmak darbesiyle yok olmak 

ama bu sadece gerçekten kaçmak 

halbuki yapman gereken savaşmak 

savaşın sonunda zafer kazanmak', 'öyle kolay ki o mermiyi bulmak  soğuk demirin içine sokmak  bir parmak darbesiyle yok olmak  ama bu sadece gerçekten kaçmak  halbuki yapman ...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mermi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hülyalı Düşler.!', 'hulyali-dusler-zulfikar-yapar-kaleli-ejrmt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'NOT: Bu Leb değmez şiirdir         

Hülyaya seslenir çağın kuşları

Duyan insan dilde sözü unutur.

Gönülden gönderir göze yaşları

İçer azar azar tuzu unutur.

Ne deniyor dinle hele kalender

Cahilde izan yok, nasihat eder

İki gözden ılgıt ılgıt yaş gider

Yanı yara yaslar, düzü unutur.

Hoş görün aşığı kavrulsun, yansın

Küllerini görsün Aslı, uyansın

Aşık her saniye aşkını ansın

Hayaline dalar yüzü unutur.

Sakin gölde sessiz çalkanır kuğu

Şu ayın on dördü, şu yakışığı

Leylaların şirin, arsız aşığı

Atar tezeneyi, sazı unutur.

İki gönül yakın eder ırağı

Asaletin sır sultanı çırağı

Gülün her dalına düşer kırağı

Hararet yükselir, közü unutur.

Şu aşkın hatırı olsaydı şayet

Ödenirdi, candan aziz şu diyet

O gönül de hoşnut olurdu gayet

Ki, çoğu arzular, azı unutur.

İnsan, insanlıktan azınca çıkar

Düşkününe kuyu kazınca çıkar

Şair, ruhsuz şiir yazınca çıkar

Sana aşık olur, nazı unutur.

O çağları hasret ile anarsın

Ağustosta ayaz vurur, donarsın

Sen kendini kuldan evla sanarsın

Seni kışın gören, yazı unutur.

Sır okyanusunda inciyse erek

Hayaller çoğalır arzu diyerek

Lakin Kaleli’ye Hülyası Gerek

Hülya der, gelini, kızı unutur.

23.02.2005 Trabzon', 'NOT: Bu Leb değmez şiirdir          Hülyaya seslenir çağın kuşları Duyan insan dilde sözü unutur. Gönülden gönderir göze yaşları İçer azar a...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hulyali-dusler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peki ya', 'peki-ya-sair-shimalwest-uo91z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'realist yaklaşımlar

mantıksal uyarlamalar

planlanmış hayatlar

peki ya

nerede ruh

nerede duygu

istem dışı hareketler

refleksleşmiş yaşantılar

monotonlaşmış ilişkiler

peki ya

nerede his

nerede vicdan

kontrolsüz saldırılar

yozlaşmış yakınlıklar

örselenmiş hissiyatlar

peki ya

nerede insanlık', 'realist yaklaşımlar mantıksal uyarlamalar planlanmış hayatlar peki ya nerede ruh nerede duygu istem dışı hareketler refleksleşmiş yaşantılar...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/peki-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece bir ömürlük sevgi', 'sadece-bir-omurluk-sevgi-sair-shimalwest-h7cmv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'birgün gelir de inkar edersem seni

sevgimi..

yüzüme vurmak için kendimi

sana verdim şimdi herşeyimi

haykırmıyorum artık içimi

biliyorum sardın tamamen bedenimi

istesende bırakamazsın sen beni

en çok kim sevdi diğerini

sen mi beni ben mi seni

ne önemi varki şimdi

biliyorsun tükenmeyen sevgimi

beklentiler kaplasa da bellekleri

beklemeden sevmek en güzeli

öyleyse varsın böyle olsun dünya düzeni

seveceğim hep seni

zamanla değişmeyen nedir ki

kim ne olacağını bilebilir ki

ama zaten merak değil benimki

sadece bir ömür sürecek sevgi

haydi gideyim ben şimdi

nasıl olsa dönerim geri

yaşatdıkca içimde özlemi

saniyeler aylar gibi sanki', 'birgün gelir de inkar edersem seni sevgimi.. yüzüme vurmak için kendimi sana verdim şimdi herşeyimi haykırmıyorum artık içimi biliyorum sard...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sadece-bir-omurluk-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı dünya', 'sakli-dunya-sair-shimalwest-sq7v1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bırakın beni peşimden gelmeyin

kendimi iyi hissettiğim yeri bilmeyin

orada yarattığım dünyayı görmeyin

kendimi böyle iyi hissedeyim

orası gerçeklerden kaçtığım tek yer

belki de gerçeği yaşadığım biryer

şimdi biraz düşünmek istiyorum

nerede olmak istediğimi bilmiyorum

gerçeğe dönmek mi

hayalde kalmak mı

yoksa

hayali gerçek yapabilmek mi

hayal kurmayı sevmiyorum

çünkü çok bekleyemiyorum

istiyorum ve alıyorum

sabrım yüzünden kendimle çelişiyorum

çoğunun hayalini anı olarak bırakıyorum

ama birtek hayalimi

bir türlü yaşatamıyorum

isyan değil bu yazdığım

bezmişlik hiç değil

sadece şunu söylüyorum

anı olarak arkamda kalacağına

bu hayali ölene kadar görmek istiyorum', 'bırakın beni peşimden gelmeyin kendimi iyi hissettiğim yeri bilmeyin orada yarattığım dünyayı görmeyin kendimi böyle iyi hissedeyim orası ge...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sakli-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz konuşma', 'sessiz-konusma-sair-shimalwest-tarlg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kalbimle doğrudan konuşabiliyorsun benim de yaptığım gibi

bir tek söz söylemeden karanlıklar gündüz oluyor

yapacakmışım gibi deniyorum açıklayamadıklarımı

sen sesini çıkartmadan ne kadar çok şey duyduğumu

sanki benimle yüzündeki gülümseme yerleşiyor

artık seni hiç terk etmeyecek şekilde yapışıyor

gözlerin hiç gitmeyeceğim der gibi bakıyor

ellerim seni her tökezlediğinde tutmak için bekliyor

hiç konuşmadığımız zamanlar en çok şey anlattığımız zamanlar

en gürültülü yerler bile senin sessizliğini bastıramıyor

kalbinle kalbim arasındaki konuşmalar

en keyifli sohbetlerden daha çok ısıtıyor

artık bu hep böyle sürüp gitsin

hiçbirşey kalplerimizin arasına giremesin

dudaklarımız kilitlensin

ellerimiz kenetlensin

gözlerimiz ileriye yönelsin....', 'kalbimle doğrudan konuşabiliyorsun benim de yaptığım gibi bir tek söz söylemeden karanlıklar gündüz oluyor yapacakmışım gibi deniyorum açıkl...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sessiz-konusma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahardan bahara', 'sonbahardan-bahara-sair-shimalwest-u4crs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sonbahar yapraklarının döküldüğü yolda

hayatının sonbaharında

hışırtılar çıkardıkca yapraklar ayağının altında

sanki parçalanıyor birşeyler onlarla

omuzları sarkık sırtında kamburuyla

umutsuzluk değil onun yaşadığı

yorgunluk sadece senelerin verdiği

atmak istercesine üzerinden ağırlığı

hızlanıyor adımları

işte geldi yapraklarla dolu yolun sonuna

yeşermeye başladı yapraklar yavaşca

bahar çiçekleri rengarenk açtıkca

yeniden sarıldı hayata sıkıca

tecrübe

mücadele

hırs

tutku

yoğurdukca bunları beyninde

birşeyler olacak dedi hevesle

artık yapraklar tamamen yeşerdikce

hışırtılar kesildi ayağının altında

dik olarak yürüyor artık yolda

gözlerinde farklı bir ışıltıyla', 'sonbahar yapraklarının döküldüğü yolda hayatının sonbaharında hışırtılar çıkardıkca yapraklar ayağının altında sanki parçalanıyor birşeyler ...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sonbahardan-bahara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tufan', 'tufan-sair-shimalwest-8cful', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'boran bozan kurt borazan

yağarak hırpalar tufan

dindimi kalmaz yerinden oynamayan

usulca beklemek lazım ses çıkartmadan

dayanır bedenler fırtınaya tufana

tutunursa sevgiye aşka

sessizce beklemek erdemdir hayatta

kendi suskunluğunda ruhunu kaybetmek olmasa

erdemli olmak hep zor da olsa

boşver dünya ne umurunda

koyver kendini zamana

düzelir herşey nasıl olsa

geçiyor yıllar uçarcasına

değmezmiş hır güre inan bana

gün gelip de yaşlandığında

hak vereceksin geç de olsa

kaçmış mıdır tren o anda

yakalanır mı acaba başka istasyonda

döndürebilir misin zamanı en başa

hiç durma eğer gücün varsa

gerekmez almak zamanı başa

yaşananlar hayatın parçası sonuçta

insan yürekten isterse neler yapar hayatta

ve o yürekten kaçamaz hiçbir tren nasılsa

arada istasyon atlasa da', 'boran bozan kurt borazan yağarak hırpalar tufan dindimi kalmaz yerinden oynamayan usulca beklemek lazım ses çıkartmadan dayanır bedenler fır...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tufan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Aklı', 'cocuk-akli-cafer-yilmaz-548v2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', ''' kalk oğlum! 

sana şudur sorum...

kaça ayrılır canlılar? ''

bildik tanıdık soru,

cevaplamakta ne var! 

''4''e ayrılır öğretmenim...''

'' söyle o zaman

yanlış olduğuna eminim...''

'' bitkiler, hayvanlar,

insanlar,çocuklar...''

'' çocuklar da insan değil mi? ''

'' o zaman 3''e ayrılır öğretmenim...''

'' şimdi say yeniden, doğruyu görelim...

''bitkiler, hayvanlar,

çocuklar...''

'' oğlum! 

insanlara ne oldu? ''

''düşünebilenleri hep çocuk kaldılar.

düşünemeyenleri hayvanlaştılar

öğretmenim...''', ''' kalk oğlum!  sana şudur sorum... kaça ayrılır canlılar? '' bildik tanıdık soru, cevaplamakta ne var!  ''4''e ayrılır öğretmenim...'' '' söyle o...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cocuk-akli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
