INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Gün Dostları', 'i-yi-gun-dostlari-nuray-zarali-mywkq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hastayım yatıyorum yatağımda,

Aradıklarımı bulamıyorum yanında.

İyi günümde yanımda olanlar,

Neredesiniz kötü günümde! 

Dostluğuna inandığım kişiler,

Boş kaldı size uzanan eller.

Gözlerim kapıda takılı duruyor,

Kalbim dostların gelmesini bekliyor,

Ama  açılmıyor kapalı kapı,

Kapıdan bile bakmıyor 

İyi gün dostları.', 'Hastayım yatıyorum yatağımda, Aradıklarımı bulamıyorum yanında. İyi günümde yanımda olanlar, Neredesiniz kötü günümde!  Dostluğuna inandığım...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iyi-gun-dostlari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Olmuş Hayatımız', 'masal-olmus-hayatimiz-nuray-zarali-t2eei', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Küçük,küçücüktük,ana kuzusuyduk,

Her akşam masal dinliyorduk.

Sonra büyüdük,unuttuk masalları.

Karşımıza çıkan herkesi dost bildik,

Gerçekler konuşuluyor sandık.

Dinledik usanmadık(!) 

Çünkü kaçamadık.

Bir zamanlar geldi erdi yaşımız,

Geçti boş yere yıllarımız.

Yıllardır kendimizi yaşar sanıyoruz.

Meğer masal olmuş hayatımız.', 'Küçük,küçücüktük,ana kuzusuyduk, Her akşam masal dinliyorduk. Sonra büyüdük,unuttuk masalları. Karşımıza çıkan herkesi dost bildik, Gerçekle...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/masal-olmus-hayatimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum', 'i-stiyorum-nuray-zarali-qqgwm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çiçek dolu bir bahçe,

Kitap dolu bir  kütüphane,

Tertemiz bir çevre istiyorum.

Yalanın girmediği,

Yalanın,nefretin bilinmediği,

Sevmeyi bilenlerle dolu

Bir yer istiyorum.

Çocuklar koşsun,oynasın.

Çocuklar 

Yarış atı olmaktan çıkarılsın.

Çocuklar

Çocukluklarını yaşasın istiyorum.

Doğru yoldan ayrılmadan,

Savaş yerine barışı yeğleyen,

Atatürk''ün izinden giden

Gençler istiyorum.

Neşeyi paylaşarak çoğaltan,

Acıyı paylaşarak azaltan

Gerçek dostlar istiyorum.

Herkes birbiri ile dostça selamlaşsın.

Herkes aşını,işini sevsin.

Tüm insanlar özgür,

Özgür ve mutlu olsun.

Mutlu...

Mutlu olsun.', 'Çiçek dolu bir bahçe, Kitap dolu bir  kütüphane, Tertemiz bir çevre istiyorum. Yalanın girmediği, Yalanın,nefretin bilinmediği, Sevmeyi bile...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/istiyorum-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Dost', 'gercek-dost-nuray-zarali-7bj0g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanımdasın uykusuz gecelerinde,

Okurum sayfalarını dilediğimce.

Uykumun kaçtığını anlar gibi,

Geri getirirsin uykumu.

Uzun yolculuklarda hep sen varsın yanımda

Ne gerek var yalancı dosta! 

İçim sıkılır,daralır bazen

Hemen başvururum sana.

Arasam da bulamam ki 

Gerçek dost senden başka.

İyi günümde yanımda olanlar 

Arayıp,sormazlar  kötü günümde..

Ama sen hep yanımdasın.

Onun için sen,

Sen benim gerçek dostumsun.

Dilin yok beni kıracak,

Elin yok bana vuracak,

Horlasam bile seni,

Yine de üzmezsin beni.

Bilgimi senden aldım,

Geçmişimi senden öğrendim,

Gelecekte niye ayrı kalalım.

Sen benim dostum,

Ben de kitap dostuyum.', 'Yanımdasın uykusuz gecelerinde, Okurum sayfalarını dilediğimce. Uykumun kaçtığını anlar gibi, Geri getirirsin uykumu. Uzun yolculuklarda hep...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gercek-dost-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş ve Kitap', 'gunes-ve-kitap-nuray-zarali-uf35s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneş Dünya''yı

Kitap insanı aydınlatır.

Güneş yeryüzünü,

Kitap insan yüreğini ısıtır.

Güneş geceyi yok eder,

Kitap kara düşünceyi.

Güneş ''siz tohum,çiçek,

Kitapsız gelecek olmaz.

Gelecekte hapishanelerin azalması

Kütüphanelerin çoğalması dileği ile

Okuyalım,

Okumayı sevelim,diyorum.', 'Güneş Dünya''yı Kitap insanı aydınlatır. Güneş yeryüzünü, Kitap insan yüreğini ısıtır. Güneş geceyi yok eder, Kitap kara düşünceyi. Güneş ''si...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunes-ve-kitap-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürk', 'ataturk-nuray-zarali-wm6ij', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Atatürk önderimiz

Onunla dolu kalbimiz.

Seninle ilgili,

Silinmez hiçbir iz.

Üstün bir öğretmendin! 

Öğretmenliğin sayesinde

Halkının önünde gidebildin.

Hedefine varmak için,

Engelleri kaldırdın birer birer.

Kısacık ömründe neler başardın,neler! 

''Ya istiklal,ya ölüm''dü parolan,

Türk halkıydı yüreği kanayan.

Sen baş,onlar gövde,

Kurtardınız bu vatanı birlikte.

Seni anıyor,

Sana saygı duyuyoruz

Büyük,küçük.

İzindeyiz her zaman,

Türklerin atasısın sen ATATÜRK!', 'Atatürk önderimiz Onunla dolu kalbimiz. Seninle ilgili, Silinmez hiçbir iz. Üstün bir öğretmendin!  Öğretmenliğin sayesinde Halkının önünde ...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ataturk-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anket', 'anket-nuray-zarali-lmjlc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbinin aynası mı yüzün? 

Az ı çatılır kaşın? 

Kırmasını bilmez mi dilin? 

Sevmesini bilir mi kalbin? 

Yanında yüksek sesle düşünebilir miyim? 

Sırrım beraberine mezara gider mi? 

Uğrunda ölümü göze alabilir miyim? 

Cevapların evet ise...

Sen aradığım kişisin.', 'Kalbinin aynası mı yüzün?  Az ı çatılır kaşın?  Kırmasını bilmez mi dilin?  Sevmesini bilir mi kalbin?  Yanında yüksek sesle düşünebilir miy...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anket-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Gücü', 'sevginin-gucu-nuray-zarali-2y4s0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgi yoksa,başarı arama işinde.

Sevgi yoksa.mutluluk arama evlilikte.

Sevgi yoksa,içtenlik arama arkadaşlıkta.

Sevgi yoksa,iletişim yoktur insanlar arasında.

Sevgin yoksa insanlara,git dağ başında yaşa!', 'Sevgi yoksa,başarı arama işinde. Sevgi yoksa.mutluluk arama evlilikte. Sevgi yoksa,içtenlik arama arkadaşlıkta. Sevgi yoksa,iletişim yoktur ...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevginin-gucu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-nuray-zarali-mrhni', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çoğu keser gibi

Durmadan,usanmadan

Hep''bana! bana! ''Der.

''Hiç biri'' rende gibi

Hep''Sana,sana.''Der.

Çok azı testere gibi

''Bir sana! bir bana! ''Der.

Ben (?)  derim ki:

''Kimi sana,kimi bana.

Karşılıksız,çıkarsız.''

Ama en büyük mesele

Galiba insan olmada.', 'Çoğu keser gibi Durmadan,usanmadan Hep''bana! bana! ''Der. ''Hiç biri'' rende gibi Hep''Sana,sana.''Der. Çok azı testere gibi ''Bir sana! bir bana!...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insanlar-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Analar', 'analar-nuray-zarali-t3z9y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağrın mı var,sızın mı var? 

Uyuyamaz analar! 

Üzülse de,kırılsa da

Kıyamaz analar! 

Sever koşulsuz,

Verir karşılıksız.

Kötü de olsa evlatlar,

İyi der analar.

Kardeş kardeşi ayırır,

Birbirini kıskanır,

Analara evlatları birdir.

Evlatlar bunu bilmez! 

Karnında kanını,

Sağlığında canını,

Ölümünde malını verir analar.

Ah analar,analar! 

Kıymet bilmez evlatlar.

Bir ana on evlada bakar da,

On evlat bir anaya bakamaz.

Ben Nuray derim ki:

Baş tacı olmalı analar.

Öldükten sonra 

İşe yaramaz ahlar! Vahlar

(Analarını saymayan evlatlara...)', 'Ağrın mı var,sızın mı var?  Uyuyamaz analar!  Üzülse de,kırılsa da Kıyamaz analar!  Sever koşulsuz, Verir karşılıksız. Kötü de olsa evlatlar...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/analar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-nuray-zarali-0jsjm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En büyük zevkim okumak,

İlham geldikçe de yazmak.

Başarmaya çalıştığım,

Çocuklarımla arkadaş olmak.

Arkadaşlığı severim,

Dostluğu daha çok.

Her anne gibi,

Evlatlarımı her şeyden çok.

Bir insanın yemin,ne değil,

İsterim karakterine güvenmek.

Hiç beceremediğim şey ise

Yalan söylemek.

Sırsa bana söylenen

Onu sır bellemeliyi,

Mezara gitmeliyim

O söylenen ile ben.

Beni en çok üzen ne midir? 

Saatliğine,günlüğüne arkadaşlık,

İçte dışta başkalık,

Bencillik,sorumsuzluk,haksızlık.

Yardımı severim,yardımlaşmayı.

Severim insanlara güvenmeyi.

Ama iyi niyet,

Kötüye kullanılmamalı! 

Zandan uzak dururum,

Kul hakkı yiyemem.

Hakkım olanı bilirim,

Hakkım olmayana el süremem.

Kini nefreti değil,

Sevgiyi barındırır kalbim.

Çocukla çocuk,büyükle büyük olmak

Zevk verir bana,mutlu olurum.

Ailemden böyle gördüm,

Büyüğümü saydım,küçüğümü sevdim.

Bana verdiklerini Allahım

Çocuklarım için de diliyorum!', 'En büyük zevkim okumak, İlham geldikçe de yazmak. Başarmaya çalıştığım, Çocuklarımla arkadaş olmak. Arkadaşlığı severim, Dostluğu daha çok. ...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ben-152-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçeğim', 'gercegim-nuray-zarali-ab1bn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünya''nın yuvarlak olduğu doğru,döndüğü de.

Ay''ın keşfedildiği doğru,

İki kere ikinin dört ettiği de.

Ölüm gerçek

Yaşamak da.

Daha çok doğru var 

Bitmez saymakla.

Ben kendi gerçeğimi 

Söylemek istiyorum.

Tüm insanları tek tek

Çok seviyorum!', 'Dünya''nın yuvarlak olduğu doğru,döndüğü de. Ay''ın keşfedildiği doğru, İki kere ikinin dört ettiği de. Ölüm gerçek Yaşamak da. Daha çok doğru...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gercegim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Üzerine', 'sevgi-uzerine-nuray-zarali-n9wpz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi çıkarsa yürekten

İnsan kuru kabuktur inan! 

İnsanın mayası sevgi,

Sevgisiz insan olunmaz ki.

Sevgi bir yapıştırıcı

Yaşamın her dalına.

Sevgi yoksa söyle bana 

Ne zevk verir insana? 

Ne ekersen onu biçersin.

Sevgi ek sevgi yeşersin.

Senin,onun,hepimizin

Sevgi bahçeleri olsun.

Sevgi bahçeleri olsun...', 'Sevgi çıkarsa yürekten İnsan kuru kabuktur inan!  İnsanın mayası sevgi, Sevgisiz insan olunmaz ki. Sevgi bir yapıştırıcı Yaşamın her dalına....', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgi-uzerine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mantıksal', 'mantiksal-nuray-zarali-0lril', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Paylaşılanca azalır her şey

Mantıksal olarak.

Ama paylaşılınca çoğalan

Mantığı da aşan bir şey var.

Sevgi,bilgi.

Paylaşalım,diyorum 

Paylaşalım sevgilerimizi...

Bilgilerimizi...', 'Paylaşılanca azalır her şey Mantıksal olarak. Ama paylaşılınca çoğalan Mantığı da aşan bir şey var. Sevgi,bilgi. Paylaşalım,diyorum  Paylaşa...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mantiksal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakışır', 'yakisir-nuray-zarali-ujayd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüze tebessüm,

Yüreğe sevgi yakışır.

Acıya bölüşmek,

Neşeye karışmak yakışır.

İyiye hatır sorma,

Hastaya ziyaret yakışır.

Buluta yağmur,

Çalışmaya başarı yakışır.

İyiye,güzele uymak,

Kötüye uzak durmak yakışır.

Hataya ders alma,

Doğruya katılmak yakışır.

Kine uzaklaşmak,

Sevgiye yaklaşmak yakışır.

Doğaya saygı,

Tüm insanlara sevgi yakışır.

Ne halde olursan ol,

Allah''a şükretmek yakışır.', 'Yüze tebessüm, Yüreğe sevgi yakışır. Acıya bölüşmek, Neşeye karışmak yakışır. İyiye hatır sorma, Hastaya ziyaret yakışır. Buluta yağmur, Çal...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yakisir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla', 'beni-hatirla-nuray-zarali-t1fwr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutluluğunda

Paylaşmak için insan aradığında

Beni hatırla..

Mutsuzluğunda

Azaltacak birini aradığında 

Beni hatırla.

Ben,

Hatırlandığım her anında,

Seninle olacağım bilmeni isterim.', 'Mutluluğunda Paylaşmak için insan aradığında Beni hatırla.. Mutsuzluğunda Azaltacak birini aradığında  Beni hatırla. Ben, Hatırlandığım her ...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beni-hatirla-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorsam', 'ariyorsam-nuray-zarali-b9brq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnız olurum bazen

Yanımda olsa da insan.

Yalnızımdır bazen

Yanımda isterim insan.

Sıkar bazı insanlar

Bazıları aranırken.

Arıyorsam,

Ben de olmalıyım aranan.', 'Yalnız olurum bazen Yanımda olsa da insan. Yalnızımdır bazen Yanımda isterim insan. Sıkar bazı insanlar Bazıları aranırken. Arıyorsam, Ben d...', ARRAY['Türk Edebiyatı','Şiir','Nuray Zaralı']::text[], 8.5, '{"poet":"Nuray Zaralı","poet_slug":"nuray-zarali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ariyorsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgidir Yolum', 'sevgidir-yolum-nuray-zarali-gl57n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yollar

Bağlar köyleri,şehirleri,ülkeleri

Yollar birleştirir,ayırır insanları.

Kimi düz,kimi engebeli

