INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayboldu Gözlerim', 'kayboldu-gozlerim-hatice-bediroglu-hlg7a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Resmini koydum karşıma,

Seyrettim uzun uzun.

Gülücüklerin,

Sanki bana uzanıyordu.

Aldım hepsini,

Öptüm birer birer,

Özümsedim beynimde.

O kadar tatlıydılar ki! 

Sevdanın sıcaklığı,

Alıp götürdü…

Uykusuz geçen gecenin,

Sabahında oluşan,

Tüm ağrılarımı.

İçimde…

Dinmeyen bir özlemle,

Gözlerinin mavisinde,

Kayboldu gözlerim.

www.haticebediroglu.net

(Şiirlerimin hepsi Noter tasdiklidir)', 'Resmini koydum karşıma, Seyrettim uzun uzun. Gülücüklerin, Sanki bana uzanıyordu. Aldım hepsini, Öptüm birer birer, Özümsedim beynimde. O ka...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kayboldu-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni seviyorsan babamdan iste', 'beni-seviyorsan-babamdan-iste-yusuf-ziya-leblebici-fds37', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sokak arasında yolumu kesme

Kaytan bıyıklı yar gelme üstüme

Görürlerse dünya döner tersine

Beni seviyorsan babamdan iste

Kapının önünde mendil mi buldun

Pencere önüne mektup mu koydun

Sağa sola gidip beni mi sordun

Beni seviyorsan babamdan iste

Bizim mahalleye demir mi attın

Güzel kızlar sana gelir mi sandın

Düğün dernek varken niye kaçarsın

Beni seviyorsan babamdan iste

Evimizin tahta merdiveninde

Karanfil dikili penceresinde

Bekliyorum seni gelecek diye

Beni seviyorsan babamdan iste

Beni gördüğünü annene söyle

İlla ki bu kızı isteyelim de

Buyrun gelin bize acı kahveye

Beni seviyorsan babamdan iste', 'Sokak arasında yolumu kesme Kaytan bıyıklı yar gelme üstüme Görürlerse dünya döner tersine Beni seviyorsan babamdan iste Kapının önünde mend...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beni-seviyorsan-babamdan-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-kadir-yasar-j1f8f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlamı yok artık tekrar tekrar söylemenin

 Her mısrasında acı olan,

 Her nağmesinde hasret kokan türküleri..

 Gel hele Suna boylum 

 Gel be Umudum Öznesi 

 Taş olsa dayanmaz bu yürek ayrılığa...', 'Anlamı yok artık tekrar tekrar söylemenin  Her mısrasında acı olan,  Her nağmesinde hasret kokan türküleri..  Gel hele Suna boylum   Gel be ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yaşar']::text[], 8.5, '{"poet":"Kadir Yaşar","poet_slug":"kadir-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayrilik-225-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yüzlü İşçi Kadın.......Dosya', 'gul-yuzlu-i-sci-kadin-dosya-mehmed-sari-cgzb0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gül yüzlü 

işçi kadın 

  ONUN ÖYKÜSÜ

Gül yüzlü bir çocuktun

Açmamış tomurcuktun

Henüz ondört yaşında

Ahu gözlü yavrucuktun

Başını bağladılar

Ardından ağladılar

Bir cahilin elinde

Ömrünü dağladılar

Evin işi, hayvan, toprak

Koca keyfi, azar- dayak

Meyve bile vermeden

Kurudu dalda yaprak

Gül yüzüne elem düştü

Ekmek uzaklara kaçtı

Omuzlayıp bavulunu

Uzak bir diyara göçtü

Karanlıkta gider işe

Karanlıkta döner eve

Umut yakalanmaz oldu

Yoksul yerde sürünmekte

Ekmek makina ağzında

Derman bırakmaz kolunda

Tabanların sızım sızım

Bin bir problem kafanda

Acıdır, ağlar çocuklar

Yüreği dağlar çocuklar

Sevgisiz- dirliksiz eve

İnsanı bağlar çocuklar

Fabrika, tarla, dükkan

Koştun yaşamın ardından

Köleliğin değişmedi

Göçmekle eski yurdundan

Evde, işte, her alanda

Dertler çoğaldı kafanda

Tutsaklığın ağırlaştı

Kocan gardiyan kapında

Töreler yaktı seni

Acılar yıktı seni

Tüydün diye kölelikten

Toplum ayıpladı seni

Yapayalnız kaldın orda

Yem olmadın kuşa- kurda

Kol gücünü silah gibi

Kuşanıp çıktın ortaya

Mehmet alkışladı seni

Yobazlar taşladı seni

Yıldızlar elin uzattı

Güneş kucakladı seni

            Mart 2002 

           Melbourne

        

hafta sonu güzellemeleri 

İNCECİKTEN BİR YEL ESTİ

         1 

Ekmek gibi ellerin

sıcak,

     doyurucu.

Buram buram alınteri kokuyor

emek kokuyor burcu burcu...

Gülende

güller açıyor yüzünde,

Gözlerin tılsımlı, derin

Bir sevda pınarı sanki

Binlerce gül içinde

alımlı bir tomurcuk

           gül endamın.

Ceylanlarca ürkek,

Selvilerce narin,

Gül yüzlü

ceylan gözlü

işçi kadın...

Ellerim sana 

    ulaşamasa da

maceramda bir abide gibi

            yaşayacak adın! 

        2 

Kalbimi çaldırdım sana

kaşla göz arasında ansızın,

Beynim takılıp gitti ardından

oyarak göbeğini karanlığın,

Donup kaldı

gül yüzünde bakışlarım,

Ve derinliklerinde yüreğimin

bir türkmen kilimi gibi nakışlandın.

Ekmek gibi sıcak,

İpek gibi yumuşak

                   ortamına

sürükle götür beni işçi kadın...

               3 

Vurdu bağrıma bir incecik yel

depreşir acısı günden güne

parıldar ışıltısı uzaklarda

                seraba benzer.

Erişilmez bir umut mudur benimki

yoksa bir karasevda mı

ya da bir çocuksu hayal belki? 

Belki de kim bilir

bir ihtimal de olsa

milyonlar içinde

gönlün kuraklığına çiseleyen,

Ve kararan gözbebeklerime gülen

Mutluluk güneşinden

         yüreğime müjdelenen

bir küçücük ışık sinyali

şirin ve renkli bir düş gibi.

             4 

Seni görünce gözlerim

gül yüzlü işçi kadın

sarsıldı bütün hislerim,

Seni görünce gözlerim

ahu bakışlı güzel kadın

sarsıldı bedenim,

        sarsıldı beynim...

Kanat çırptı bağrımdaki kuşlar

uçmak için sevda ufuklarında,

Kanadı kalbimin damarları

içime aktı kanım,

Sessiz sedasız ağladım

Allı gülüm

zincirli benim kanatlarım! 

             5 

Güneş

ışınlarını alıp giderken

         benden uzaklara,

Sağınıp gelirken karanlık

         dalga dalga üstüme,

Gelip oturdu

anlamsız gözlerimin merkezine

                 kıvılcımlı gözlerin.

Isındı hücreleri beynimin

Çağladı damarlarımda kan

Gözbebeklerime ışık indi

Çiçeklendi yüreğimde bir filiz

Yeşerdi kalbimde bir ince sevda

................

Ne olur çekip gitme bir daha

yanan yüreğimden habersiz,

Bir damla

           sevgi yolla

annesiz bebe gibi bakınışıma,

Karışıp karanlıklara

yok olmasın gümanlı umutlarım,

Kurumasın bağrımda

sevginle yeşeren tomurcuk,

Götür onu mutluluk pınarlarına...

               6 

Seni o yerde terkedip

gelmedim gülüm,

güneş gözlü

Akdeniz güzeli.

İnan bana,

gövdemi sürükleyip

getirdim buralara,

Orada kaldı

beynim ve yüreğim,

Orada parlıyor

gözlerimin ışığı,

Ben hep seninleyim...

         7 

Hava serin ve bulanık

İnce bir yağmur yağıyor

sabahın mahmurluğuna,

Yalnız yatakta üşüyorum.

Yanımda biri yatıyor

Yıllar yılı

sırtı bana dönük,

Ben seni düşünüyorum...

           8 

Televizyona baktım canım

senin oralarda

sıcaklık 36,

23 burada...

Cayır cayır yanıyordur şimdi

Griffith''de soğan tarlaları.

Ve sen çalışıyorsundur

             şu anda

             o ateş harmanı tarlalarda,

Elinde keski aleti

alnında boncuk boncuk ter damlaları...

Hemen ateş bastı gövdemi 

Boşandı tepemden ter

akıyor sızım sızım alnımdan,

Avustralyanın vahşi güneşi

Kavuruyor gözlerimi...

Oysa sıcaklık 23 burada

Ve üstelik 

serin bir gölgedeyim,

Ama sen oradasınya gülüm

36 derecede

sarı sıcağın alevinde

Kalbim ve beynimle

ben senimleyim...

          9 

Hergün yeniden koşuyorum

Western şosesini nefes nefese

başından sonuna dek,

Hergün yeniden yüzüyorum

Murray nehrini

boş verip timsahların

             sivri dişlerine

başından sonuna

ve sonundan başına yine.

Deli bir fırtınada yürek

Sana kavuşmak için

püren balı,

sana kavuşmak için

bütün bu çılgınca emek.! 

          10 

Sen bir ceylansın Sunraysia çölünde

bense bir garip avcı,

Her kum zerresinde ahu gözlerin,

Sürüyorum çalı çalı izini

Birleştirip gündüzümü gecemi

koşuyorum çılgınca

ardınsıra senin...

Sen bir serapsın Sunraysia çölünde

bense bir garip yolcu,

Gözlerim deli gözü

ellerim dost kıtlığı,

Kurumuş dilim damağım

kanıyor elim ayağım,

Susuzum çöller gibi

yanarım yalım yalım,

Sürünürüm yollarında

dizimde kalmadı derman

Kavuşmak olası değil mi sana...

            11 

Ben gözlerini güzelim

yedi renkli görüyorum senin,

Yüzün de öyle.

Dudakların al al elmalar gibi

kirpiklerin hercai menekşe.

Gözlerin üzüm üzüm bakıyor

Yanakların  yabani gül bahçesi

Nefesin pür-ü mis kokuyor.

.......................

Alnında rengarenk gün ışığı

Sen bir çiçek bahçesisin,

Alı, moru, göğü, sarısı

yedi renkli görüyorum her yerini

Mutluluğun varı yoğu

yaşamın akçesisin.

Bir sonsuz güzellikte 

seyrediyorum sesini

aydınlık, berrak,

ve ışıl ışıl yüzünü, gözünü

ve yapıp yaratan ellerini...

Ömrümün yağmur ormanı

Sabahımda şakıyan kuş

Özlemin sürünüyor ayaklarımda

İpek bir örtü gibi bürünüyorum düşlerini...

           12 

Yolda seni 

     düşünüyorum

           evde seni,

Gecemde sen varsın yalnızca

gündüzümde sen,

İş yerinde seni çiziyorum

rengarenk duvarlara.

Ve ulaşmak için zamana,

Uzaklaşmak için

geçmiş gecelerin

ağır karanlıklarından,

seni fırlatıyorum

gelecek zamanın ufuklarına.

Nasıl sökülmez bir güçle

          işgal ettin beynimi,

Nasıl dizginlenmez bir duyguyla

                  doldurdun yüreğimi,

Dilimden hiç düşmüyor adın

Hayalin gözülerimin önünde

Sen bende yaşıyorsun hep

gül yüzlü işçi kadın...

            13 

Seherde seni kokluyorum

seni soluyorum rüzgarla,

İçtiğim suda gözlerin

iki ab-u hayat damlası,

Yediğim ekmekte ellerin

doyumsuz bir yaşam sofrası.

Sen doldurdun peteklerimi

balına yetmiyor kovanım,

Sen dokudun yüreğimi

ateşine dayanmıyor canım.

Sen dolaşıyorsun damarlarımda

çağlayıp akıyor kanım,

Çok yönlü işgalin altındayım

gönüllü tutsak ediyorum

            kalbimi sana.

Ne güzel şey

tutulup kalmak sevdana,

Ne güzel şey

yürümek yollarında sevdanın,

Beni yaşatan da

       öldüren de

             sen olacaksın

gül yüzlü işçi kadın...

           14 

Ellerin ellerimde olaydı şimdi

gözlerin gözlerimde,

Gözlerinde seyredeydim

yer yüzünün tüm güzelliklerini,

Ellerinde duyaydım

                 aşkın kor ateşini.

Yaşayaydım

gözlerinin derinliklerinde

bir anlık bir mutluluğu

         bin yıllık ömür kadar,

Karışaydı

terin terime

kanıma kanın,

Kopaydı kalplerde fırtınalar...

Aydınlanırdı kararan dünyam o zaman

Göğerirdi ruhumun viran olmuş bağları

Çiçek yağardı kar

Gönenirdi yaşam baharı

Elverirdi gönlümdeki eşkiyaya dağlar.

Ellerin ellerimde olaydı şimdi

Gözlerin gözlerimde,

Yaşam bir meltem mevsimi

Dolaydı nefesin ciğerlerime...

             15 

Bütün çiçekleri sensin

       gönül bahçemin,

Çimenleri sen; 

Kırk yıllık sevgimin hüneri

Kırk yıllık hevesim,

Ben kalbimin içine

        seni fideledim,

Ve seni ektim

yanık yüreğim üstüne

          mevsim, mevsim...

Kızıl kadife gül tomurcuğusun

Yaz güneşi gibi sıcak

Ateşli aşkım gibi yakıcı

Ve yaşamın rahmi kadar ılıman.

Hoyrat rüzgarlarında kışımın

açar ela gözlü nergislerin

ısıtır yüreğini tutkularımın,

Dağıtır sevgisizlik bulutlarını

yeşerir kırları yaşamın...

Mor menevşe olursun sonra

Mor sümbül olursun,

Yayılır sevdama dalga dalga

Binbir türlü renkle

         binbir türlü kokun...

Ballanır güzelliğin ağaçlarda

Meyveler doğurur tılsımlı, leziz

Ağlayan ayvam

          gülen narımsın.

Bütün güzellerin dudağındaki

          alevli kirazımsın.

Misk ü amber kokulu otağım

Ve Eros bağından damıtılan

kan kızıl şarabımsın...

         16 

Oyarak göğüs kafesimi

kopartıp gövdemden

kanayan kalbimi

avuçlayarak

attım önüne.

Çırpınıyor şimdi

başı kesik bir kuş gibi

ayaklarının dibinde

zavallı Mehmet.

Her şey senin elinde

İster yaşat onu

kollarını kendine

mesken eyleyip,

İstersen yok et...

         17 

Sıcakta bulut olsam üstünde

Soğuk sulardan esen meltem olsam

Okşayıp serinletsem seni.

Soğukta giysi olsam üstüne

Güneş olsam sevdalı, sıcak

Sarsam, ısıtsam seni...

        18 

Ben bir sevda işçisiyim

sevgi ekip, sevgi deren

Al, işe koş beni.

Yüreğim bir ak kelebek

salınır sevgi sevgi,

dolaşır çimen çimen,

konup kalkar kuytularda

eker sevda tohumunu...

Ben bir sevda işçisiyim

sevgi yüklü  başak başak,

Al yola vur beni.

Gönlüm benim bir arıdır

Dolaşır çiçek çiçek

Toplar balı petek petek

Karar sevda hamurunu...

        19 

Gül yüzlü işçi kadın,

Yüreğimden

fırtınalarla kopup gelen

sarsıntıları anlatıyorum sana,

İster gücen

ister kız bana,

İstersen döv beni

istersen söv bana.

Ama inan buna:

Gelmiyor benim elimden

bir başka seçenek

seni çılgınca sevmekten başka.

Gül yüzlü işçi kadın,

Kalbime kör bıçak gibi

          saplandı aşkın...

          20 

Yokluğundan 

yangın yerine döndü yüreğim

Karardı beynim

      kara dağlar gibi

ve kurudu çölden beter.

Dayanmak

zor geliyor artık,

Yetsin bunca zulüm,

yetsin bunca çile

bunca keder...

Gel! 

Bulutların üstünden

               gelir gibi.

Gel! 

Dağların ötesinden

               gelir gibi.

Tıkıyor nefesimi geçen zaman,

Tut ellerimi

ve çıkar beni

bu karanlık kuyulardan...

      21 

Kazısam ismini

keskin bir bıçakla

göğüs kafesimin ortasına,

Resmetsem seni

usta bir ressam gibi

kalbimin duvarlarına.

Ve açıp yüreğimi sana

acı bir hatıra gibi 

döksem önüne

kırk yıllık hasretimi.

Gel desem,

Bahar güneşi 

             gibi

             doğsan üstüme,

Ve gözlerin

sarı güneşin

ilk çiy düşmüş 

kehribar üzümleri gibi

ıslak ıslak baksa gözlerime.

Yalasa ak alnını

bir kızıl gün ışığı

güz sonu sevdasında yaşamın,

Savrulsa saçların şarap renginde

Yalım yalım tutuşsa dudakların.

Sürsem seni

hoyrat aşkımın

sonsuz bozkırlarına

al yeleli

    akıtma alınlı

          bir yaban kısrağınca.

Tepsem

çiğnesem

kara toprağın sinesini

ölümsüz sevgiler yetiştirmeye,

Kapatsam kötülükleri

kara derinliklerine

dipsiz bir kuyunun,

Sarsılsa dağlar

Çınlasa yalılar

Toz olsa önümde

bütün engelleri mutluluğun...

         22 

Evi- barkı terkedip

      geldim kapına,

Kapatma yüzüme ne olur

             aç kollarını bana,

