INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin', 'sensin-mehmet-sakir-karatas-1uvoj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensin

Gönül sarayıma hoş geldin güzel 

Yıllardır beklenen o ece sensin

Sanaymış şarkımız türkü ve gazel

Şiirde boy veren her hece sensin

Seninle doldurdum tüm boşluğumu 

Bir nura gark ettin o loşluğumu

Bağışla bağışla sarhoşluğumu

Her şeyimi çözen bilmece sensin

                                           1992', 'Sensin Gönül sarayıma hoş geldin güzel  Yıllardır beklenen o ece sensin Sanaymış şarkımız türkü ve gazel Şiirde boy veren her hece sensin Se...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şakir Karataş']::text[], 8.5, '{"poet":"Mehmet Şakir Karataş","poet_slug":"mehmet-sakir-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensin-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Peygamber', 'son-peygamber-mehmet-sakir-karatas-p369s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Son Peygamber

Hala mayamızı ham mı sanırsın

Piştik o dertlerle gelsene beri

Aşinayız sana bizi tanırsın

Şairiz şiirden al bu haberi

İşte bu kapımız durmayın vurun

Kurunuz sofraya baş yeri kurun

Şairler geliniz el pençe durun

Bu doğan şiirin son peygamberi

                                    1990', 'Son Peygamber Hala mayamızı ham mı sanırsın Piştik o dertlerle gelsene beri Aşinayız sana bizi tanırsın Şairiz şiirden al bu haberi İşte bu ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şakir Karataş']::text[], 8.5, '{"poet":"Mehmet Şakir Karataş","poet_slug":"mehmet-sakir-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/son-peygamber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Sevdiğim *', 'sevdigim-hasan-tosun-s74dq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yokluğa düşerken bedenlerimiz,

bir hançer saplanır yarin gözlerinden.

ve yıkık bir dünya kurarız kendimize 

üzerinde hasret yazan 

geceler bir perde olur ömrümüzde 

                  ve

aydınlık son savaşımızdır artık

ölüme giderken bile tek kelime yüreğimizde; 

*______sevdiğim______*', 'yokluğa düşerken bedenlerimiz, bir hançer saplanır yarin gözlerinden. ve yıkık bir dünya kurarız kendimize  üzerinde hasret yazan  geceler b...', ARRAY['Türk Edebiyatı','Şiir','Hasan Tosun']::text[], 8.5, '{"poet":"Hasan Tosun","poet_slug":"hasan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdigim-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Biterken', 'umut-biterken-mehmet-sakir-karatas-m3ctz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'UMUT BİTERKEN

Delen geceyi delen

Hoyrat bir rüzgardır duyguların

Büzülür köşesinde yorgun umutlar

Dört köşe olmuştur bak yalnızlık

Gelen seherle gelen

Kapkara bir ufuktur yarın

Ağlayınız bulutlar 

Koptu kopacak çığlık

                              1989', 'UMUT BİTERKEN Delen geceyi delen Hoyrat bir rüzgardır duyguların Büzülür köşesinde yorgun umutlar Dört köşe olmuştur bak yalnızlık Gelen seh...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şakir Karataş']::text[], 8.5, '{"poet":"Mehmet Şakir Karataş","poet_slug":"mehmet-sakir-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/umut-biterken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varan', 'varan-mehmet-sakir-karatas-vxrul', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varan

Gecenin bu vaktinde bilmem ne arıyorum

Bütün bütünler şimdi dünyamız kadar bölük

Cehennemin körüğü gibi kararıyorum

Olgun meyvelerde mi başlıyordu çürüklük

Bir dem geldi az bulup içimdeki acımı

Son hızımla indirdim gönlüme kırbacımı

Tanrıların elinden giydim o an tacımı 

Baktım ki yastığımın altında ölümsüzlük

                                                  1991', 'Varan Gecenin bu vaktinde bilmem ne arıyorum Bütün bütünler şimdi dünyamız kadar bölük Cehennemin körüğü gibi kararıyorum Olgun meyvelerde m...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şakir Karataş']::text[], 8.5, '{"poet":"Mehmet Şakir Karataş","poet_slug":"mehmet-sakir-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/varan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Ucuz bir roman yazıyorum kendimce *', 'ucuz-bir-roman-yaziyorum-kendimce-hasan-tosun-smkl5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ucuz bir roman yazıyorum kendimce

içinde sen 

anlatmak ne zor bebeğim seni kelimelerde

belki bir bahar günü dersin ya 

bu kalbe

işte o nu yaşıyorum kendimde

düşünmek ne zor meleğim isyanlar içinde

acıyı tatmak sevinç içinde ve,

sen olmak bende,kadere inat

son damlasını tutmak hayatın,

gözlerinde

            ve 

yaşamak seni bir ömür boyu benliğimde.......', 'ucuz bir roman yazıyorum kendimce içinde sen  anlatmak ne zor bebeğim seni kelimelerde belki bir bahar günü dersin ya  bu kalbe işte o nu ya...', ARRAY['Türk Edebiyatı','Şiir','Hasan Tosun']::text[], 8.5, '{"poet":"Hasan Tosun","poet_slug":"hasan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ucuz-bir-roman-yaziyorum-kendimce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneye Gazel', 'anneye-gazel-mehmet-sakir-karatas-tr4ja', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ANNEYE GAZEL

   ............................anneme.....,                           

Dağılsa varlığım hep lime lime

Hangi yöne gitsem sağım-solumsun

Yeter elin yakın olsun elime

Bütün çıkmazlardan çıkar yolumsun

Sensin ilk aklıma gelen kelime 

Daha ne diyeyim ANAdolumsun

                        1991

     

	Mehmet  Şakir  KARATAŞ', 'ANNEYE GAZEL    ............................anneme.....,                            Dağılsa varlığım hep lime lime Hangi yöne gitsem sağım-s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şakir Karataş']::text[], 8.5, '{"poet":"Mehmet Şakir Karataş","poet_slug":"mehmet-sakir-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anneye-gazel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haikular-1', 'haikular-1-adnan-durmaz-vw26q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1

