INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kacik', 'kacik-deniz-turan-e0l1y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kafamdaki solucan cikacak yer ariyor.

Kacik kücük gülmelerle bedenimi sariyor,

Bir kösede boza satsam alakasiz güpegündüz,

Kafdaginin yollari ucurumsuz bende dümdüz.

Seni senden alirim bilmem kime satarim,

Yatina binemezsem gölgesinde yatarim.

Ben annemin hem catlak hem akilli kiziyim,

Siseler arasinda kollarinda sizayim.', 'Kafamdaki solucan cikacak yer ariyor. Kacik kücük gülmelerle bedenimi sariyor, Bir kösede boza satsam alakasiz güpegündüz, Kafdaginin yollar...', ARRAY['Türk Edebiyatı','Şiir','Deniz Turan']::text[], 8.5, '{"poet":"Deniz Turan","poet_slug":"deniz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kacik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat (1)', 'hayat-1-deniz-turan-ivtem', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben birinin yüregini izledim.

Ben birinden yüregimi gizledim,

Ben geceyle sarmas dolas karanliga asina,

Gözlerim keskinlesir yarasa kanadinda.

Sabah olur sevgi kokar buram buram vazodan,

Sari güller boynu bükük, kirmizilar korodan,

Körelir yarasalar, durulur ucusmalar,

Yeni güne seslenis yepyeni bir cag baslar.', 'Ben birinin yüregini izledim. Ben birinden yüregimi gizledim, Ben geceyle sarmas dolas karanliga asina, Gözlerim keskinlesir yarasa kanadind...', ARRAY['Türk Edebiyatı','Şiir','Deniz Turan']::text[], 8.5, '{"poet":"Deniz Turan","poet_slug":"deniz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayat-1-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavrayış', 'kavrayis-gokhan-oflazoglu-3isg4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kısa kavrayışların ölümcül tuzağında,

bir de kavrayanların kötü niyeti olmasa; 

eksik kalanı başkası tamamlasa.

Açılırdı kilitli duran, ortada kalmazdık.

Hayır böyle olmuyor, doğruyu 

göstermek de yetmiyor; izleyen de yok.

Aklımız tamam dese, güdülerden rahat yok.

14/03/2005', 'Kısa kavrayışların ölümcül tuzağında, bir de kavrayanların kötü niyeti olmasa;  eksik kalanı başkası tamamlasa. Açılırdı kilitli duran, orta...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kavrayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapkaranlık arz-ı sema', 'kapkaranlik-arz-i-sema-mikdat-bal-dlxfj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kabkaranlık arz-ı sema

Sultan sağır vezir, ama

Ağzı mühürlü ulema

Gaflete daldı gidiyor

Ufuklarda bulut kara

Düşman atar her dem nara

Kan kövdeyi sokaklara

Dehşete saldı gidiyor

Akraba bağları gergin

Fakiri eziyor zengin

Türk milleti çok tedirgin

Haşyete daldı gidiyor

Yurttaş aman nidasında

Liderler ben kavgasında

Herkes koltuk sevdasında

Vahşete daldı gidiyor

Mikdat der ki bu halimiz

Hakkadır arzu hâlimiz

Sonu erdi mecâlimiz

Nusrete daldı gidiyor

Ufuklarda bulut kara

Dü; man atar her dem nara

Kan kövdeyi sokaklara

Dehşete saldı gidiyor

Akraba bağları gergin

Fakiri eziyor zengin

Türk milleti çok tedirgin

Haşyete daldı gidiyor

Yurttaş aman nidasında

Liderler ben kavgasında

Herkes koltuk sevdasında

Vahşete daldı gidiyor

Mikdat der ki bu hâlimiz

Hakkadır arzu hâlimiz

Sonu erdi mecâlimiz

Nusrete daldı gidiyor', 'Kabkaranlık arz-ı sema Sultan sağır vezir, ama Ağzı mühürlü ulema Gaflete daldı gidiyor Ufuklarda bulut kara Düşman atar her dem nara Kan kö...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kapkaranlik-arz-i-sema-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz gümüşse suküt altındır! ! !', 'soz-gumusse-sukut-altindir-mikdat-bal-8rh2z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söz gümüşse suküt altın denilir

Bu tabirle bir çok nane yenilir

Manasını anlamayan yanılır

Haksızlığa susan şeytandır şeytan... 

Dilimizi dilim dilim eyleyip

Kelimeyi başka çeşit söyleyip

Her susuşu bir fazilet anlayıp

Haksızlığa susan şeytandır şeytan

Susmak altın büyüklerin yanında

Gerçeklerin diz çökülür önünde

Ancak şu ki bir haksızlık anında

Susanların tümü şeytandır şeytan

Mikdat Bal der artık yeter sustuğun

Susmandandır bu hallere düştüğün

Haksızları men etmeyip,küstüğün

Bu ancak en zayif imandır iman.....', 'Söz gümüşse suküt altın denilir Bu tabirle bir çok nane yenilir Manasını anlamayan yanılır Haksızlığa susan şeytandır şeytan...  Dilimizi di...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soz-gumusse-sukut-altindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dİlekce', 'di-lekce-mikdat-bal-kn7db', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hürmet,selam ederim

Değerli büyüklerim

Ne olur kulak verin 

Gurbetten gelen sese

Burda ne olacağız? 

Sanmayın kalacağız

Elbette varacağız

Ordadır bizim hisse

İstikbali bilmeyiz

Çok dertliyiz, gülmeyiz

Ya gelir ya gelmeyiz

Bitmeli bu vesvese

Artık uyanın beyler

Sahipsiz olan neyler

Bülbül vatanım söyler

Girse altın kafese

Vurdular bize nişan

Bu mu bize yakışan

Gençler hali perişan

Hepsi bu kadar ise

Unuttular heceyi

Görmediler Türkçeyi

Az bilirler Frenkçeyi

Sizin için dil ise

Mechuldür ikbalimiz

Büyüktür vebaliniz

Bizim arz-ı halimiz

Getirilsin meclise', 'Hürmet,selam ederim Değerli büyüklerim Ne olur kulak verin  Gurbetten gelen sese Burda ne olacağız?  Sanmayın kalacağız Elbette varacağız Or...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dilekce-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu haller bu yaşda gelir başa.dinle aşkım', 'bu-haller-bu-yasda-gelir-basa-dinle-askim-galip-kemali-gunay-ohfe7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrık otunum bağbahçenin

Ezsen de ezilsem de orada mıyım.

Ketenotları mı deva sana, 

Lokmanım,kokla,

Kaç, gel, gitmedik mi....

....................................

Ellibirsen, elliüçüm...

Kaçırırım, seni senden

Ayrık

Bu zamanlar da güzel aşkım', 'Ayrık otunum bağbahçenin Ezsen de ezilsem de orada mıyım. Ketenotları mı deva sana,  Lokmanım,kokla, Kaç, gel, gitmedik mi.... ................', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-haller-bu-yasda-gelir-basa-dinle-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Elma', 'yasak-elma-meral-vurgun-0tdr6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'usulca uzanıp dalından

yasak bir elmayı koparır gibi 

dokunup teninin ısısına

benlerini sayamadığım yar

avuç icinde parmak uçlarım 

kül kavrusu dudaklarımdan düşürüp

ateşten bir buse bırakaydım bıyık ucuna

kor düşerdi bağrıma

yanardım...

parmak uçlarım ki

ellerinden yüreğine uzanan körüdür

sus bencileyin

anlamı yok kelimelerin 

ben gülüşlerinden öpeyim

sus bencleyin

sakla sözlerini

“taş düştüğü yerde ağırdır”

kaçırma gözlerini....', 'usulca uzanıp dalından yasak bir elmayı koparır gibi  dokunup teninin ısısına benlerini sayamadığım yar avuç icinde parmak uçlarım  kül kavr...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasak-elma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amigo', 'amigo-mikdat-bal-0wim9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Trabzonspor seyirçisi

Çok gürültü ederdi

Olur olmaz her anda

Bravo derdi yuh derdi

Her ağızdan ses çıkar

Hiç bir şey anlaşılmaz

Dendi ki bu kargaşa

Amigosuz aşılmaz

Artık amigo geldi

Davul zurna çalarak

Trabzon seyirçisini

Karşısına alarak

Dedi sağ elim ''bravo''

''Ya, ya, ya,'' ve ''şa, şa, şa''

Ondan sonra dersiniz

''Bizim takım çok yaşa''

Karşı ki tarafa `''yuh''`

Sol eli kaldırınca

Eğer atağa geçip

Bastırıp saldırınca

İşaretime bakın

Yerime gidiyorum

İki elim kalkınca

“sessizlik” istiyorum

Maç başladı amigo

Sağ elini kaldırdı

Ya, ya, ya, söylemenin

Zamanını bildirdi

Sonra solu kaldırdı

''Yuh'' denildi rakip''e

Seyirçiler bir anda

Benzedi bir ekip''e

Hakem düdük çalınca

İki elini açtı

Amigo afalladı

Duyduklarına şaştı

Herkes koro halinde

“sessizlik sessizlik” der

Amigo hikayesi

Trabzonspor için biter

Mikdat bal der bu fikra

Ne gerçektir ne yalan

Buna espiri derler

Kardeşim gül,oyalan', 'Trabzonspor seyirçisi Çok gürültü ederdi Olur olmaz her anda Bravo derdi yuh derdi Her ağızdan ses çıkar Hiç bir şey anlaşılmaz Dendi ki bu ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/amigo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam', 'tam-gokhan-oflazoglu-zg026', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acılar, keder, hüzün

bunlar tattırır gerçek

dünyayı diyor eskiler.

Daha azına razı olmayın,

mutluluk talebinde ödün

aymazlık. Mevcut durumda

tek yol yetkinlik, tamlık.

Dünya değişmiyorsa,

siz değişin hiç olmazsa.

Zor olsa da.

14/03/2005', 'Acılar, keder, hüzün bunlar tattırır gerçek dünyayı diyor eskiler. Daha azına razı olmayın, mutluluk talebinde ödün aymazlık. Mevcut durumda...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evrim ile Selahattin', 'evrim-ile-selahattin-bulent-kalayci-8hn4x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mutluluk ateşten bir gömlek olduğunda

Sevmişti onu

Sevgi kefen,sevgili melek olmuştu

Yüreğinde sevgiyi kanatanlar

Kıyamadı, aşkı vuramadı

Sevgi ateşinde buluşmaksa umuttu

Bir kurşun sıksada umuda ölüm

Umuda kurşun işlemez'' demişti

Umudu vurdular gülüm

Umudu vurdular

13/03/2005

HÜRRİYET GAZATESİ

SEVDİLER DİYE YAŞATMADILAR', 'Mutluluk ateşten bir gömlek olduğunda Sevmişti onu Sevgi kefen,sevgili melek olmuştu Yüreğinde sevgiyi kanatanlar Kıyamadı, aşkı vuramadı Se...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kalaycı']::text[], 8.5, '{"poet":"Bülent Kalaycı","poet_slug":"bulent-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/evrim-ile-selahattin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen gün yarın,yakın değil mi?', 'beklenen-gun-yarin-yakin-degil-mi-mikdat-bal-kn210', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İsyana dalmışsın,nisyanın perde

Ömrün heder oldu günahta şerde

Herşeyin hesabı vardır mahşerde

Beklenen gün yarın,yakın değil mi? 

Kendi kitabını oku denince

Hâlin nice olur bu istenince

Artık geç kalmışsın vakit gelince

Beklenen gün yarın,yakın değil mi? 

Susarsan konuşur eller ayaklar

Ödenir hesaplar,alınır haklar

İflas edenleri cehennem paklar

Beklenen gün yarın,yakın değil mi? 

O gün kaçacaksın öz kardeşinden

Annen baban koşar senin peşinden

Kaçarsın evlattan,hem de eşinden

Beklenen gün yarın,yakın değil mi

Melekler yakandan tutup sürükler

Zebaniler cehennemi körükler

O dehşete dayanır mı yürekler? 

Beklenen gün yarın,yakın değil mi? 

Bunlar hep söylendi duyup ta geçtin

İnandığın halde gafleti seçtin

Vaktim var sanarak aniden göçtün

Beklenen gün yarın,yakın değil mi? 

Mikdat der kendimi anlattım durdum

Sen derken,aslında kendime sordum

Nasıl olur bilmem ebedi yurdum? 

Beklenen gün yarın,yakın değil mi?', 'İsyana dalmışsın,nisyanın perde Ömrün heder oldu günahta şerde Herşeyin hesabı vardır mahşerde Beklenen gün yarın,yakın değil mi?  Kendi kit...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/beklenen-gun-yarin-yakin-degil-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyler bu gidişin sonu hüsrandır!', 'beyler-bu-gidisin-sonu-husrandir-mikdat-bal-09ema', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyarsak ta şu millet bir uyansa

Eğitime, üretime dayansa

İlk etapta buna çare aransa

Beyler bu gidişin sonu hüsrandır! 

Hiç düzelmez deyip öte geçmeyin

Omuz silkip, kolay yolu seçmeyin

Zaten dert çok, bir dert daha açmayım

Beyler bu gidişin sonu hüsrandır! 

Yok mudur bir çare bulacak derde? 

Hani nerde,nutuk atanlar nerde? 

Bolluk, barış olacaktı her yerde

Beyler bu gidişin sonu hüsrandır! 

Ne olmuş da böyle olmuş bizlere? 

Güvenen yok her verilen sözlere

Sevdiğimden diyorum ki sizlere

Beyler bu gidişin sonu hüsrandır! 

Zengin olan her engeli aşıyor

Fakirler ekmek peşinde koşuyor

Yokluk, sıkıntı içinde yaşıyor

Beyler bu gidişin sonu hüsrandır! 

Demeyin, kokmuş ete tuz kâr etmez

Demeyin, ahmaklara söz kâr etmez

Demeyin, Mikdat Bal’a yaz kâr etmez

Yoksa bu gidişin sonu hüsrandır!', 'Uyarsak ta şu millet bir uyansa Eğitime, üretime dayansa İlk etapta buna çare aransa Beyler bu gidişin sonu hüsrandır!  Hiç düzelmez deyip ö...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/beyler-bu-gidisin-sonu-husrandir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine gel kendine', 'kendine-gel-kendine-mikdat-bal-mwtob', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adam gibi laf dersin

Her sefer gaf edersin

Bu ne tuhaf gidersin

Kendine gel kendine

Öğüt verme öğüt tut

İnce öğüt öyle yut

Başkalarını unut

Kendine gel kendine

Gördüm nane yemeni

Halin şok eder beni

İslam değil temenni

Kendine gel kendine

Her şey başlar kendinde

Ara bulırsun dinde

Olma elin derdinde

Kendine gel kendine

Nefsin kul etti seni

Yarsiz, dul etti seni

Geçmez pul etti seni

Kendine gel kendine

Mikdat der beni dinle

Dalga geçme bu dinle

Çok işin var kendinle

Kendine dön kendine', 'Adam gibi laf dersin Her sefer gaf edersin Bu ne tuhaf gidersin Kendine gel kendine Öğüt verme öğüt tut İnce öğüt öyle yut Başkalarını unut ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kendine-gel-kendine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtulur', 'kurtulur-mikdat-bal-lfa9u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya da ne varsa,hayır ve şerri

Bitkisi, hayvanı, cini, beşeri

Niçin, kim yarattı bütün şeyleri? 

Bunun cevabını bulan kurtulur! 

Ol dedi de oldu, bütün kainat

Her şeyde zahirdir ilahi sanat

Ey cahil inkarcı eyleme inat

İman edip teslim olan kurtulur! 

Binlerce ayet var her hünerinde

Sayısız hikmetler var her birinde

Nasıl oldu herşey yerli yerinde? 

Bunun cevabını bulan kurtulur! 

Bu dünya kitaptır başlı başına

Herşeyde hikmet var değil boşuna

Huvel bakı yazar mezar taşına

Bunun nedeni ni bulan kurtulur! 

Mürekkep olsaydı bütün denizler

Hepsi yazar olsa cinler ve bizler

Nihayet bulmazdı ilahi sözler

Bu gerçeği bilen,bulan kurtulur

Mikdat der ki aklın çok azdır artmaz

Aklına güvenme seni kurtarmaz

Terazin küçüktür tonları tartmaz

Aczini keşfedip bilen kurtulur', 'Dünya da ne varsa,hayır ve şerri Bitkisi, hayvanı, cini, beşeri Niçin, kim yarattı bütün şeyleri?  Bunun cevabını bulan kurtulur!  Ol dedi d...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kurtulur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede o eskigünler', 'nerede-o-eskigunler-mikdat-bal-e4hs5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nerede o hatırladığın günler

Onlarla mı avunuyorsun

Artık zenginim diyorsun

Bununla mı övünüyorsun

Nerede o eskigünler

Anıp anıp dövünüyorsun

Sen artık yok oldun

Neyini savunuyorsun

Sen yaşayan bir ölüsün

Dünyaya mı seviniyorsun

Ne dünyayı anladın

Ne der dünya seni

Neyine güvenüyorsun?', 'Nerede o hatırladığın günler Onlarla mı avunuyorsun Artık zenginim diyorsun Bununla mı övünüyorsun Nerede o eskigünler Anıp anıp dövünüyorsu...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nerede-o-eskigunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep sacımızı yolduk', 'hep-sacimizi-yolduk-mikdat-bal-hxf9x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hep sacımızı yolduk

Artık saradık solduk

Bir avuç kemik olduk

Eridi yağlarımız

Selam kalktı aradan

Kim anlar merhabadan

Komşudan akrabadan

Kesildi bağlarımız

Güller konca açıyor

Kuşlar gelip göçüyor

Yabanelde geçiyor

Hep gençlik çağlarımız

Alır bize bir merak

Vatandan kaldık irak

Oldu bize elfirak

Yaylamız dağlarımız

Kaybettik güçümüzü

Kim duyar acımızı

Ağarttı sacımızı

Varımız yoğlarımız

Yazıldı bizim ferman

Dizde kalmadı derman

Artık oldular orman

Yemyeşil bağlarımız

Yaşımız elli oldu

İstikbal belli oldu

Yarım bir deli oldu

Gurbette çoğlarımız

Beklenen aylık ise

İşsizlik beylik ise

İstikbal balık ise

Yırtıdı ağlarımız

Dert sayılmaz, pek çoktur

Her biri sivri oktur.

Ölüden farkı yoktur

Burda ki sağlarımız

Aşığım ağlıyorum

Sözümü bağlıyorum

Eriyip çağlıyorum

Sel oldu çığlarımız', 'Hep sacımızı yolduk Artık saradık solduk Bir avuç kemik olduk Eridi yağlarımız Selam kalktı aradan Kim anlar merhabadan Komşudan akrabadan K...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hep-sacimizi-yolduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen insan olamazsın', 'sen-insan-olamazsin-mikdat-bal-9n7me', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Komşunu üzer isen

Kibirli gezer isen

Zayıfı ezer isen

Sen insan olamazsın

Zengini çok översen

Sözde onu seversen

Güçsüzleri döversen

Sen insan olamazsın

Farzet düşüncen hacsa

Biri sana muhtaçsa

Uyursan komşun açsa

Sen insan olamazsın

Doğru konuşmaz isen

Söz verip tutmaz isen

Güvenli olmaz isen

Sen insan olamazsın

Yetim malını yersen

Bunda beis yok dersen

Eğer zülüm edersen

Sen insan olamazsın

Mikdat der darılırsan

Kuvvete sarılırsan

Bu yoldan ayrılırsan

Sen insan olamazsın', 'Komşunu üzer isen Kibirli gezer isen Zayıfı ezer isen Sen insan olamazsın Zengini çok översen Sözde onu seversen Güçsüzleri döversen Sen ins...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-insan-olamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdenizli', 'akdenizli-nevin-kalafatoglu-ehecm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Olimposun dibine dibine bir yol

Çavuş köyün sakin limanı

gönlü deniz

sessiz sesiz

bir arya tuturmuş gider

suların renginde menevişler

gözlerin

üstünde dağların tozu

cebinde metelik yoktu

herşeyi umursayan serserim

bir somun ekmek ve aşk

ile doydu

nevin kalafatoğlu', 'Olimposun dibine dibine bir yol Çavuş köyün sakin limanı gönlü deniz sessiz sesiz bir arya tuturmuş gider suların renginde menevişler gözler...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/akdenizli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben kalemi aldım ele', 'ben-kalemi-aldim-ele-mikdat-bal-5rxkj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben kalemi aldım ele

Kağıtımı vermem yele

Haşa bu vatanım sele

Gider iken durur muyum

Sahtekarlar kol geziyor

Kardeş kardeşi eziyor

Bu fitne dıştan sızıyor

Buna razı olur muyum

Türk gencini kandırdılar

Fesat fitneye saldılar

Polislere saldırttılar

Artık emin uyur muyum

Yoktur uyuyacak halim

Düşman olsa bile zalim

Olmasaydım akliselim

Gerçekleri bulur muyum

Mikdat şehitleri anar

Düşündükce içim yanar

Damarımda kanım kaynar

Artık passif durur muyum', 'Ben kalemi aldım ele Kağıtımı vermem yele Haşa bu vatanım sele Gider iken durur muyum Sahtekarlar kol geziyor Kardeş kardeşi eziyor Bu fitne...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-kalemi-aldim-ele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''um', 'i-stanbul-um-mikdat-bal-fu9qf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstanbul''u dünü ile

Tarihte ki ünü ile

Kıyas ettim günü ile

Gördüm de inanamadım

Aradım da bulamadım

Saha vardı alan vardı

Haksızca alana kaldı

Çilen var daha dolmadı

Seni koruyan olmadı

Hiç eski neş''en kalmadı

Niçin zalime eğildin

Eskiden böyle değildin

Fatih''inden yılan vardı

Şimdiyse yilan''a kaldı

Ayasofyam niçin mahzun? 

Dört minaren uzun uzun

Bakanlara verir hüzün

Camiye teptil olmadan

Fatih ilk cum''an kılmadan

Üzerinde çalan vardı

Şimdiyse çalana kaldı

Ecdat''ımın eserleri

Belli olmuyor yerleri

Sarayları mabetleri

Vakıflar yağma oldular

Camiler yanlız kaldılar

Mâbetlerde kılan vardı

Bakımı kılana kaldı', 'İstanbul''u dünü ile Tarihte ki ünü ile Kıyas ettim günü ile Gördüm de inanamadım Aradım da bulamadım Saha vardı alan vardı Haksızca alana ka...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/istanbul-um-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar geçti aradan', 'yillar-gecti-aradan-mikdat-bal-yut7q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllar geçti aradan

Uzağım çaykaradan

Nasip olsa da gelsem

Bir kurtulsam buradan

Hasretlik beni yakar

Akar göz yaşım akar

Doslarım ahbablarım

Her gün yoluma bakar

Özlerim köyümüzü

Akraba soyumuzu

Allahım şu gurbetten

Sen kaldır suyumuzu

Yalvarırıum mevlaya

Bir kavuşsam sılaya

Bir avuç kemik oldum

Ben ağlaya ağlaya

Çoluk çocuk burdadır

Aklımız hep yurdadır

Burda yaþ asak bile

Her şeyimiz ordadır', 'Yıllar geçti aradan Uzağım çaykaradan Nasip olsa da gelsem Bir kurtulsam buradan Hasretlik beni yakar Akar göz yaşım akar Doslarım ahbabları...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yillar-gecti-aradan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlerim', 'ozlerim-mikdat-bal-8b3aj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçer günler ah ile

Kalkarım sabah ile

Köyümü vah vah ile

Gece gündüz özlerim

İlkbahar yaz güz ile

Dağ tepeyi düz ile

Geceyi gündüz ile

Her şeyini özlerim

Çakalların sesini

Tavuğun kümesini

Horozun nefesini

Her şeyini özlerim

Hiç bitmeyen işini

Dört mevsimi,kışını

Yemeğini aşını

Her şeyini özlerim

Türlü eğlenceleri

Yaz kış imeceleri

Seyirli geceleri

Her şeyini özlerim

İhtiyar nineleri

Ah yavrum demeleri

Bastonlu dedeleri

Her şeyini özlerim

Mikdatın bitti lafı

Bu kadar türkü kafi

Mahalleyi etrafı

Her şeyini özlerim', 'Geçer günler ah ile Kalkarım sabah ile Köyümü vah vah ile Gece gündüz özlerim İlkbahar yaz güz ile Dağ tepeyi düz ile Geceyi gündüz ile Her ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ozlerim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köylü kızı', 'koylu-kizi-i-shak-ozlu-vxwrw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kekik kokulu köyümün,

Elleri kınalı güzeli.

Güncel dergileri okuyalı,

Kınaların oje''mi oldu senin.

Hediyem güllü yaşmagından,

Siyah perçemin görünürdü.

Kuaförle tanıştın tanışalı,

Saçların kızıl mı oldu senin.

Güneşe hasret sinen,

İnciden daha beyazdı.

Ben''lerden geçilmiyor gayri,

Plajlar mekanın mı oldu senin.

Çeyizinde sandık dolusu,

Pazen elbisen vardı.

Terzilere gide gele,

Etek mi doldu gardrobun senin.

Gönlümün sultanı köylü kızı,

Evden dışarı çıkmazdın,

Büyük şehre geleli,

Mekanın cafeler mi oldu senin.

Sevdam deyince yanagın kızarır,

Başın öne düşerdi.

Sosyal faaliyetlere gideli,

Arkadaşların erkek mi oldu senin.', 'Kekik kokulu köyümün, Elleri kınalı güzeli. Güncel dergileri okuyalı, Kınaların oje''mi oldu senin. Hediyem güllü yaşmagından, Siyah perçemin...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/koylu-kizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok bize yan bakacak', 'yok-bize-yan-bakacak-mikdat-bal-o0xr6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yok bize yan bakacak

Bakarsa kan akacak

Milyonla can çıkacak

Yakarız dağı taşı

Birlik her şeyin başı

Solcusu ülküdaşı

Hep vermişiz el ele

Kim olur o hergele

Sosyetesi dindarı

Kavgalısı kindarı

Hepsi Türk alemdarı

Yurtseverdir her kişi

Birbirinin kardeşi

Beş parmağın her beşi

Birleşince gör hele

Yumruğu yer hergele

Bir elin yok mu sesi

Ya ne elimin tersi? 

Sangi demirci örsü

Patlatır gözü kaşı

Kalsam dahi bir kişi

Zordur onların işi

Kim imiş o hergele

Güvenmesin tek ele

Kahramandır ırkımız

Kimseden yok korkumuz

Eğer varsa farkımız

İyi biliriz işi

Biz açmayız savaşı

Sabır herşeyin başı

Bunda olmaz acele

Onlar denesin hele

Türkün ölü dirisi

Kahraman her birisi

Yok gencin serserisi

Hepsi Türk vatandaşı

Budur herşeyin başı

Yıkarız dağı taşı

Boyun eğmeyiz ele

Vatan için el ele

Mikdat der yazdığımız

Burada dizdiğimiz

Aldını çizdiğimiz

Olsun kardeş barışı

Kazanırız savaşı

Vermeyiz tek karışı

Biz verince el ele

Duysun bizi hergele', 'Yok bize yan bakacak Bakarsa kan akacak Milyonla can çıkacak Yakarız dağı taşı Birlik her şeyin başı Solcusu ülküdaşı Hep vermişiz el ele Ki...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/yok-bize-yan-bakacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnternet', 'i-nternet-gokhan-oflazoglu-7hpi4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uykunun dermansız bıraktığı,

gecenin örtüsünü açmadığı.

Gene de insanlar internette.

Ulaşabildiği kadar boşalıyor; 

yükünden azat, sakinleşmiş

biraz. Saklıyı açığa vuran.

Özgürlüğe bir adım; daha rahat.

İmkan olmuş yakınlıkta. Soluğun 

biraz daha uzak.

14/03/2005', 'Uykunun dermansız bıraktığı, gecenin örtüsünü açmadığı. Gene de insanlar internette. Ulaşabildiği kadar boşalıyor;  yükünden azat, sakinleşm...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/internet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört mevsim', 'dort-mevsim-i-shak-ozlu-ccvng', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçük dünyamdan büyügüne geçtim,

Mevsimlerden ilkbaharı  seçtim.

Her gülün özündeki sevgiyi,

Ailemin yanında doyasıya içtim.

Bahara doydum yaza geçtim,

Aldıgım sevgileri çevreme saçtım.

Kavak yelleri esti başımda,

Hayatı yaşadım genç yaşımda.

Baharı yaşıyan görmeli güzü,

Zormuş ihtiyarlık unuttum yazı.

Zaman galip kesildi hızım,

Kalmadı yanımda oglum kızım.

Kış gelmiş kapıdan bakar,

Ruhum sonsuz dünyaya akar.

Dört mevsim bir ömür yapar,

Kimi birini kimi dördünü yaşar.', 'Küçük dünyamdan büyügüne geçtim, Mevsimlerden ilkbaharı  seçtim. Her gülün özündeki sevgiyi, Ailemin yanında doyasıya içtim. Bahara doydum y...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dort-mevsim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık Değil mi?', 'yazik-degil-mi-kadir-soyturk-auyfp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uçuruma doğru hızla gidiyorsun,

Sen kendi canına kıymak istiyorsun.! 

Unutma her derdin ilacı vardır

En büyük cinayet intihardır! 

Eşin dul, çocukların öksüz kalacak; 

Anan, baban, komşuların...sevenlerin  perişan olacak.! 

Yazıktır yapma, etme, vaz geç istiyorum; 

Akıl sahibine bu yakışmaz diyorum! 

Gel yaratana teslim ol, vazgeç, dön bu pis ölümden

Eşref-i mahluk olarak yaratılmış bir varlıksın sen! 

Diyorsun ki: Tutma beni giderim istediğim yöne

Can benim değil mi, sana, kime ne? 

Unutma, bu can, bu hayat  emanet verildi

Bir de kullanma kılavuzu, Kur''an gönderildi.

-Çok uzattın, bana kimse karışamaz tanrı bile! 

-Anlaşıldı, sana söz kar etmez, tüm emekler nafile! 

-Ben kimseye kulak asmam, uçuruma doğru giderim böyle! 

-Ne diyebilirim arkadaş, sen bildiğin türküyü söyle! 

Akıl sahibine bu kadar kelam yeter,

Allah''ı tanımadan yaşamak, intihardan bin beter!', 'Uçuruma doğru hızla gidiyorsun, Sen kendi canına kıymak istiyorsun.!  Unutma her derdin ilacı vardır En büyük cinayet intihardır!  Eşin dul,...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yazik-degil-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta', 'usta-i-shak-ozlu-zm9ca', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilirim kızarsın için için,

Begenmezsin yaptıklarımı.

Ama sormazsın niçin.

Sende bilirsinki,

Çok veren maldan,

Az veren candan.

Bizimkide candan be usta.

Yolunda giden ne var.

Ölümler sıralıydı eskiden,

Şimdi karıştı be usta.

Sevdalar ölümüne yaşanırdı,

Şimdi günübirlik degil mi.

Sütten bile erken kesildik,

Sonrakine kalsın diye.

Ana baba yüzüne,

Hasret büyümedik mi,

Bir lokma ekmek ugruna.

Egitimi hızlandırdık,

Yetmedi be usta.

Rüşvetle daha da hızlı,

Ulaşmadık mı ehliyete.

Sen sevdayı yaşamışsın usta,

Kitabını yazıyorsun.

Biz kenarından gördük.

Bilmeyiz püf noktasını.

Halimiz budur usta,

Bir çorba pişiyor ocakta,

Bir tuzumuz bulunsun dedik,

Amaç budur kızma be usta.', 'Bilirim kızarsın için için, Begenmezsin yaptıklarımı. Ama sormazsın niçin. Sende bilirsinki, Çok veren maldan, Az veren candan. Bizimkide ca...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/usta-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekçi.! ! !', 'bekci-zulfikar-yapar-kaleli-n029m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '*

Bir gün garip köye geldi birisi

''''Muhtar ben, aza ben, bekçi ben'''' dedi

Yavruları yedi sansar çerisi

''''Kanun ben, ceza ben, bekçi ben'''' dedi

Dedi ki: ''''Size ne vatanı sevmek

Size mi kalmıştı Fatih''i övmek? 

Ne demek be, milli devlet, ne demek! 

Şehir ben, kaza ben, bekçi ben'''' dedi

''''Var mı, daha var mı, bir şey diyecek? 

Söyleyin, kaldı mı baş eğmeyecek? 

Yavruların eti varken yiyecek

Başlarım tuza ben, bekçi ben'''' dedi.

''''Evinizi, barkınızı yakarım

Sizi tutar hücrelere tıkarım

Sanmayın ki yaşınıza bakarım

Beklemem yaza ben, bekçi ben'''' dedi

''''Muradı gözünde olanlar varmış

Açmadan, zamansız solanlar varmış

Aldırmam, muratsız kalanlar varmış

Geline, kıza ben, bekçi ben'''' dedi

Bir taraf çakırkeyf bir taraf ah ah

Bir yanda toy düğün  bir yanda eyvah

''''Devleti seveni öldürün mubah

Aldırmam naza ben, bekçi ben'''' dedi.', '* Bir gün garip köye geldi birisi ''''Muhtar ben, aza ben, bekçi ben'''' dedi Yavruları yedi sansar çerisi ''''Kanun ben, ceza ben, bekçi ben'''' de...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bekci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adaleti Vurdular.! !', 'adaleti-vurdular-zulfikar-yapar-kaleli-f46hh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Reva mıydı acep sorulan sual? 

Güneşler arından terledi al al

Hakka doğru değil bu gidiş, bu hal

İşkence ettiler, çile verdiler  

Mazlumların günahına girdiler

Yıllar geçer, aylar geçer, gün geçer

Çokları var, aş yerine, su içer

Neler var, neler var, ikişer üçer

Garipleri tutup ipe gerdiler

Kirli ellerini güne serdiler      

Uymuş hevesine alem nesine

Kulaklar tıkalı hukuk sesine

Kartalı koymuşlar kuş kafesine

Çevresine haki duvar ördüler

Seyrettiler, muratlara erdiler! 

Severdi milleti, sevdi devleti

Yükledi sırtına bunca mihneti

Nur-a nur, ilâhi her hareketi

Kirli basın ile boy boy yerdiler

Budadılar, boy atmasın, dediler

Bu yol haklı mıdır sorulmaz niyet? 

Caniler can içti, işte cinayet

Nerede adalet, hani hürriyet

Kardeş oldu köpeklerle kediler 

Memleketi parselledi, yediler', 'Reva mıydı acep sorulan sual?  Güneşler arından terledi al al Hakka doğru değil bu gidiş, bu hal İşkence ettiler, çile verdiler   Mazlumları...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/adaleti-vurdular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzüstü...', 'yuzustu-zulfikar-yapar-kaleli-mfcw7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hele davran, işte meydan işte sen

Buyurun aslanlar cenge yüzüstü...

Önce seni alt eden şu nefsi yen

Cehaleti düşür ringe yüz üstü...

Yiğit o ki meydanda yüz ak ede

Zengin fakir tuta aynı dengede

Zamanın donduğu yerden ötede

Destanlar yazılmış cönge yüzüstü...

Sarmaşık gül, ısırgan dal verende

Muhannet kul mecnuna hal verende

Birisi can, birisi mal verende

Hem adalet, hem de denge yüzüstü...

Deryadan habersiz deredesiniz

Hakkın ağladığı yöredesiniz

Ey yitik sevdalar neredesiniz

İşte abla, bacı, yenge yüzüstü...', 'Hele davran, işte meydan işte sen Buyurun aslanlar cenge yüzüstü... Önce seni alt eden şu nefsi yen Cehaleti düşür ringe yüz üstü... Yiğit o...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuzustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağ Atlamak...!', 'cag-atlamak-zulfikar-yapar-kaleli-3y3qh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Evde ekmeği yok, çoktandır işsiz

İşte çağ atlama teraneleri.! 

Minareler sessiz, camiler ıssız

Hizmete açarız put haneleri.! 

Bir zamanlar dilde hep -izm -izm

Milli devlet için etmedik azim...

Çalışmak, yükselmek nemize bizim

Her gün doldururuz meyhaneleri.! 

Zamane uşağı, devrin alığı

Hiç ayık bulunmaz nefsin gölüğü

Asrilik sayıyor kepazeliği

Zamanın akıllı divaneleri.! ! 

Zengine eğilir, mazlumu yerer

Her şeyi bilirim pozuna girer

Bıkmaz ikide bir ileri sürer

Seksenden önceki efsaneleri! 

Ölsen umursanmaz, o hep gülüyor

Söylenmeyin, o her şeyi biliyor

Enflasyon- menflasyon millet ölüyor

Bırakın eskimiş bahaneleri.! 

Zalim ah çekmeli, mazlum gülmeli

Mazlum ağlıyorsa zalim ölmeli...

İnsan vazifeyi namus bilmeli

Yediğin yetmez mi şu naneleri?', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Evde ekmeği yok, çoktandır işsiz İşte çağ atlama teraneleri.!  Minareler sessiz, camiler ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cag-atlamak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlar', 'karlar-caglar-akarsu-qbknj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '..

Genc adam,yollarda yürüdü,yorgun,

Ayaklarında, karla kaplı sokaklar,

Yüreğinde bir hüzünKARLAR..

...

Genc adam,yollarda yürüdü,yorgun,

Ayaklarında, karla kaplı sokaklar,

Yüreğinde bir hüzün,

Daldı gitti gözleri, çok uzaklara,

Gurbet çilesi, bağrında bitmez bir acı,

...

''oy daglar'''' dedi,

Derin bir nefes,çekti.

Karşidaki tepeler,karla kaplanmıştı,

Gökyüzünden süzülen,beyaz yapraklar,

Uçuşarak,yeryüzüne dogru iniyordu,

Dayanamadı,genç adam! ! 

Yavaşça yerinden doğruldu,

Biliyordu ki, her mevsim,

Bir başka güzel,olurdu,

Uzak ülkelerin,üzerine doğan,

Güneşler.

Bazen, sıçak ülkelerden gelen,

Göçmen kuşlar gibi,

Her evin bacasına, yuva yaparlardı,

Bazen de, soğuk ülkelerin,

Buzla kaplı görüntüsünden,

Beyaz kristallerin güneşte,

Dans  etmesini,, seyr ederlerdi.

...

Hüzünlü mevsimleri,taşırdı gurbet! 

Daldı gitti gözleri, 

Yeni doğacak, güneşlerin ardından,

Kar mıydı, içindeki çoşkuyu uyandıran,? ? 

Yoksa. sarı benizli insanların, yalnızlığında,

Doğmak ve ölmek arasında,

Sıkışmış kalmış.

Yaşamın içinde, hep kaybettiği,

Dost sanıp da, kucakladığı,

Arkasından koştuğu, karlar gibi,

Eriyip yok olup,giden karlar gibi,

Sevgiler miydi? ,

Daldı gitti gözleri, çok uzaklara,

Gurbet çilesi, bağrında bitmez bir acı,

...

''oy daglar'''' dedi,

Derin bir nefes,çekti.

Karşidaki tepeler,karla kaplanmıştı,

Gökyüzünden süzülen,beyaz yapraklar,

Uçuşarak,yeryüzüne dogru iniyordu,

Dayanamadı,genç adam! ! 

Yavaşça yerinden doğruldu,

Biliyordu ki, her mevsim,

Bir başka güzel,olurdu,

Uzak ülkelerin,üzerine doğan,

Güneşler.

Bazen, sıçak ülkelerden gelen,

Göçmen kuşlar gibi,

Her evin bacasına, yuva yaparlardı,

Bazen de, soğuk ülkelerin,

Buzla kaplı görüntüsünden,

Beyaz kristallerin güneşte,

Dans  etmesini,, seyr ederlerdi.

...

Hüzünlü mevsimleri,taşırdı gurbet! 

Daldı gitti gözleri, 

Yeni doğacak, güneşlerin ardından,

Kar mıydı, içindeki çoşkuyu uyandıran,? ? 

Yoksa. sarı benizli insanların, yalnızlığında,

Doğmak ve ölmek arasında,

Sıkışmış kalmış.

Yaşamın içinde, hep kaybettiği,

Dost sanıp da, kucakladığı,

Arkasından koştuğu, karlar gibi,

Eriyip yok olup,giden karlar gibi,

Sevgiler miydi?', '.. Genc adam,yollarda yürüdü,yorgun, Ayaklarında, karla kaplı sokaklar, Yüreğinde bir hüzünKARLAR.. ... Genc adam,yollarda yürüdü,yorgun, Ay...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/karlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Şekillendirir Geceyi', 'ay-sekillendirir-geceyi-oguzkan-bolukbasi-glbsh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ay şekillendirir geceyi

bir çizgi yakamoz su üzerinde

bir deli çığlık senin sevişmelerinde

sabah eteklerinde gelincikler açtırır dağların

ay şekillendirir geceyi', 'ay şekillendirir geceyi bir çizgi yakamoz su üzerinde bir deli çığlık senin sevişmelerinde sabah eteklerinde gelincikler açtırır dağların ay...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ay-sekillendirir-geceyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neçar', 'necar-duken-kolan-lyb6a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'min destê xwe dirêjê 

çend deman kir

li her demê birînek 

şîn bû

di tilîyen min penûs revîya

û 

zengalorka min de payîz

bi tirk û bê yelkowan

fetisîm

geremola di wextê da', 'min destê xwe dirêjê  çend deman kir li her demê birînek  şîn bû di tilîyen min penûs revîya û  zengalorka min de payîz bi tirk û bê yelkowa...', ARRAY['Türk Edebiyatı','Şiir','Duken Kolan']::text[], 8.5, '{"poet":"Duken Kolan","poet_slug":"duken-kolan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/necar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstikamet - Meçhul Kitabından', 'i-stikamet-mechul-kitabindan-omer-ekinci-micingirt-a6u75', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fatiha yol istikamet 

Nefsle başlar her hıyanet

Nehye sıdktır secde kamet 

Maslahatım istikamet 

Dosdoğru ol tek keramet 

Hud suresi hak adalet 

İman sıdktır hâl marifet 

Maslahatım istikamet 

İhlas sebat “Hizmet Nimet” 

Gayret et ki sevsin Ahmet 

Muamelat muamelat

Maslahatım istikamet 

İstikamet  istikamet 

İstikamet uy Micingirt 

“Dosdoğru olunuz” âyet

Maslahatım istikamet', 'Fatiha yol istikamet  Nefsle başlar her hıyanet Nehye sıdktır secde kamet  Maslahatım istikamet  Dosdoğru ol tek keramet  Hud suresi hak ada...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istikamet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-huseyin-erdogan-3rtsw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'artık,sevgi denen duygu

hiç kalmamış sende

gönül pınarından

neden içirmiyorsun? 

inan ki sen bu alemde

bir çiçek bahçesi gibisin

kokunu rüzgarlara

niye vermiyorsun? 

keşke senin gecelerin

ben olsaydım

sıcacık sevgimle

seni sarsaydım

her sabah bir güneş gibi

dünyana doğsaydım

hiç batmadan ömrünce

sende kalsaydım

keşke keşke keşke

sen benim olsaydın

            14.03.2005', 'artık,sevgi denen duygu hiç kalmamış sende gönül pınarından neden içirmiyorsun?  inan ki sen bu alemde bir çiçek bahçesi gibisin kokunu rüzg...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/keske-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Gel', 'kendine-gel-nur-demirciler-q51xc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün ben ben değilim,

dün de değildim,

kimbilir kaç gün hatta aydan beri

belkide. 

Hani söylemiştim ya,

tutunacak bir dalım vardı da,

kırıldı gitti ansızın,

o daldan düşen yaprak misali

savrulup durdum belki de...

Kulağım hep bir seste,

gözüm yine aynı dertte,

bir deli yürek işte,

düştü sevda peşine... 

30/11/1994

Ankara', 'Bugün ben ben değilim, dün de değildim, kimbilir kaç gün hatta aydan beri belkide.  Hani söylemiştim ya, tutunacak bir dalım vardı da, kırıl...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kendine-gel-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Aşk', 'bu-ask-ender-altinisik-1sdd8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Suskunluğumu kattım aşkıma

Aşkımı yalnızlığıma...

Şiirlerim 

suskunluğumu taşır sana.

Okuduğunda sen

dudaklarım değer dudaklarına...

Özlesem,ağlasam,kal desem

binlerce şiir yazsam daha

binlerce kez dokunsam yalnızlığına

Yine gidermisin uzaklara...

Bu 

Gün

Bu

Gece

Bu

Aşk

Bu

Şiirler

getirirmi seni bana...', 'Suskunluğumu kattım aşkıma Aşkımı yalnızlığıma... Şiirlerim  suskunluğumu taşır sana. Okuduğunda sen dudaklarım değer dudaklarına... Özlesem...', ARRAY['Türk Edebiyatı','Şiir','Ender Altınışık']::text[], 8.5, '{"poet":"Ender Altınışık","poet_slug":"ender-altinisik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bu-ask-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cigara', 'cigara-ender-altinisik-8zn8s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kallavi bir cigaralık bile

en fazla iki saniye 

unutturabiliyor seni...

Yani hiç bir şey

dindirmiyor içimdeki

hasreti...', 'Kallavi bir cigaralık bile en fazla iki saniye  unutturabiliyor seni... Yani hiç bir şey dindirmiyor içimdeki hasreti......', ARRAY['Türk Edebiyatı','Şiir','Ender Altınışık']::text[], 8.5, '{"poet":"Ender Altınışık","poet_slug":"ender-altinisik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cigara-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Sofrası', 'yasam-sofrasi-adnan-mehmet-tufekci-hgos1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'daha muhabbet

yeni başlıyor dostlar.,

bir elimizde kadeh,

bir elimizde lanet duman.

geçmişten dem vurup,

sevdalardan konuşacağız.

çekilen acıları,

yaşanılan mutsuzlukları

şu kadehlerde boğacağız.

soframızdan

nice güzeller gelip geçecek,

bıraktıkları izlerle,

yaşattıkları hislerle

kâh üzülecek,

kâh güleceğiz.

mezeye gerek yok dostlar,

muhabbetlerimiz bize,

en zengin meze.

geçmiş bitip de,

geldikmi günümüze,

belki de hüzün çökecek

bilinmez gelecekle.

bu sofra; 

yaşam sofrası dostlar.,

nice kez kuracak,

meze diye

yaşamlarımızı sunacağız.

haydi birlikte,

sevginin,

dostluğun şerefine.', 'daha muhabbet yeni başlıyor dostlar., bir elimizde kadeh, bir elimizde lanet duman. geçmişten dem vurup, sevdalardan konuşacağız. çekilen ac...', ARRAY['Türk Edebiyatı','Şiir','Adnan Mehmet Tüfekci']::text[], 8.5, '{"poet":"Adnan Mehmet Tüfekci","poet_slug":"adnan-mehmet-tufekci","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yasam-sofrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-ender-altinisik-yrcra', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yalnızlık

iki kişiye yetmez...

İki kişi

bir yalnızlık bile etmez...', 'Bir yalnızlık iki kişiye yetmez... İki kişi bir yalnızlık bile etmez......', ARRAY['Türk Edebiyatı','Şiir','Ender Altınışık']::text[], 8.5, '{"poet":"Ender Altınışık","poet_slug":"ender-altinisik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalnizlik-234-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-muhammet-yagcioglu-0l7qb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar yılı susan kalp, bu akşam dile geldi

Yalnızlığın bağrında yine sensiz inlerken

Gökyüzü ve yıldızlar sırrımı ele verdi

Karanlıkta ağlayıp gözyaşımı gizlerken

Bir çivi çakılıyor ömrümüze her akşam

Gönlümüz delik deşik ellerimiz yaralı

Sevişirken yağmurla, düşüp kırılıyor cam

Penceremde ne kendin, ne hayalin kalalı

Sonu dersen hasretin bu umutsuz bekleyiş

Başlangıcı ne zaman bilir misin sevgilim

Kendimizi kadere sessizce teslim ediş

Ölüm değil de nedir söyler misin', 'Yıllar yılı susan kalp, bu akşam dile geldi Yalnızlığın bağrında yine sensiz inlerken Gökyüzü ve yıldızlar sırrımı ele verdi Karanlıkta ağla...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Yağcıoğlu']::text[], 8.5, '{"poet":"Muhammet Yağcıoğlu","poet_slug":"muhammet-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekleyis-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar', 'anilar-zati-erbas-iad6n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Camdan yansıyan  yüz sendin

iki adımdı aramız,

masanın iki yanında bile; hayat

bu kadar yalnız 

bu kadar anlamsız olmadı

bana ne istediğimi bile sormadı-n

eskici kılıklı hayatımda atmam gereken tek şeyi

atmadım 

bakmadım bile kaç numara olduğuna 

kaç giyerdin 

çorabı

sonra-sı 

hiç bitmeyen bir gece

birde kulüp rakısı', 'Camdan yansıyan  yüz sendin iki adımdı aramız, masanın iki yanında bile; hayat bu kadar yalnız  bu kadar anlamsız olmadı bana ne istediğimi ...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anilar-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşin İzi', 'atesin-i-zi-i-lknur-cekici-qngsb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rüzgarların deliliği

Gözlerinin rengini

Yanan ateşin izi

Gittiğin o geceyi

Yokluğunun eseri

Gölgelerdeki sevgi

Hatırlatırdı bazen

Neşeli o günleri

Ruhumdaki yakarış

Bitmek bilmez haykırış

Ölümünle netleşti

Hayatımdaki batış

Bilmezdim ben ateşi

Gönüldeki yerini

Çok uzun zaman geçti

Sildirmedi izini', 'Rüzgarların deliliği Gözlerinin rengini Yanan ateşin izi Gittiğin o geceyi Yokluğunun eseri Gölgelerdeki sevgi Hatırlatırdı bazen Neşeli o g...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/atesin-izi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına Gözlü Yarim', 'firtina-gozlu-yarim-mehmet-cetinkaya-lc1js', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana sesleniyorum çözüldü dillerim

Yıllarımı ağlatan fırtına gözlü yarim

Yeşil gözler bakar kumral saçların arasından 

Yandı yüreğim geçeceğim şimdi dünyamdan

Sanki gelip geçecekmiş gibi içimde yatan

Yıllarımı ağlatan aşkındır beni yakan

Sana sesleniyorum çözüldü dillerim

Yıllarımı ağlatan fırtına gözlü yarim

Yaşamak istiyorum en güzel sevdaları

Koparmadan koklamak gülleri ıtırları

Kalemim kırılsa yazmasam bu satırları

Seninle paylaşmak en güzel aşkları

Sana sesleniyorum çözüldü dillerim

Yıllarımı ağlatan fırtına gözlü yarim

Her yağmur yağışında ıslanır gözlerim

Boş kaldı titriyor ve üşüyor ellerim 

Acıyla aşkın en güzelini yaşar yüreğim

Ağlamadan gel fırtına gözlü yarim

(13.05.2001 TAVŞANLI)', 'Sana sesleniyorum çözüldü dillerim Yıllarımı ağlatan fırtına gözlü yarim Yeşil gözler bakar kumral saçların arasından  Yandı yüreğim geçeceğ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çetinkaya']::text[], 8.5, '{"poet":"Mehmet Çetinkaya","poet_slug":"mehmet-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/firtina-gozlu-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günün', 'dogum-gunun-gokhan-sahin-0lrzo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'doğum günün

doğduğum gündür

hayattır

hayatımı

mühürleyen 

gözlerin

sevdaya 

yazılmış

şiirdir

tertemiz 

yemyeşil

hayatı anlatan

katran karası

yalnız 

gecelerde

duyduğum

sevda melodilerinin

annesi

doğum günün

doğduğum gündür

geleceğimi

martı

ellerine bırakan

sevdandır

iki kapılı gökyüzünde

simurga

beraber

uçarken

hayatıma güç katan

doğduğun gün

doğduğum gündür

her gün

yeni sevdalara

gebe

hayatımızın

miladı

doğum günün

kutlu

olsun.', 'doğum günün doğduğum gündür hayattır hayatımı mühürleyen  gözlerin sevdaya  yazılmış şiirdir tertemiz  yemyeşil hayatı anlatan katran karası...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Şahin']::text[], 8.5, '{"poet":"Gökhan Şahin","poet_slug":"gokhan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/dogum-gunun-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost''a Gidiyorum', 'dost-a-gidiyorum-mehmet-cetinkaya-8a2u8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ele gelmez ömür sürdüm dünyada

Dost elini tutanları gördüm rüyada

Size veda ediyorum musallada

Hak terazini kurmuşlar meydanda

Ben sizin için ibret gidiyorum 

Arkamdan söylenmeyin biliyorum

Bir hırka ile bir lokma istiyorum

Yolda beni ne bulur bilmiyorum

Heyecanım  büyük, Dost’ a gidiyorum

Ben sizin için ibret gidiyorum

26.09.2002', 'Ele gelmez ömür sürdüm dünyada Dost elini tutanları gördüm rüyada Size veda ediyorum musallada Hak terazini kurmuşlar meydanda Ben sizin içi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çetinkaya']::text[], 8.5, '{"poet":"Mehmet Çetinkaya","poet_slug":"mehmet-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dost-a-gidiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mustafa Ceylan''a...', 'mustafa-ceylan-a-i-brahim-ethem-bingul-qp98s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostluğun kitabı

Aşkın notası

Bir gönül avazı

Her mısrası bir dünya

Olur tercüman

Her hülyaya...

Sustursalar cümle âşığı

Susmaz o,

Âşıkların canda canı

Bir dost kokusuna

Saatlerce yollara koşan

Yüreği, bileği adam gibi adam...

Bir edebiyat tahlil ustası

Ama üstünde Anadolu hırkası

Yunus, Veysel âşığı

Antalya''nın gül kokan

Şair- yazarı...

Saygıyla selamlarım

Ağabeyim Mustafa Ceylan''ı...

www.iebingul.com', 'Dostluğun kitabı Aşkın notası Bir gönül avazı Her mısrası bir dünya Olur tercüman Her hülyaya... Sustursalar cümle âşığı Susmaz o, Âşıkların...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mustafa-ceylan-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Galiba', 'galiba-sitki-gokmen-phu4o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sıkımlık portakal gibiyim.

Sı

kı

lı

Yorum.

Ama suyum yok.

Olsaydı da tuzlu olurdur sanırım.

(ANKARA 14 MART 2005)', 'Sıkımlık portakal gibiyim. Sı kı lı Yorum. Ama suyum yok. Olsaydı da tuzlu olurdur sanırım. (ANKARA 14 MART 2005)...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/galiba-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttuğum Ayrılık', 'unuttugum-ayrilik-mehmet-cetinkaya-pgega', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar aşk nedir diye yaşadım

Aşkı yaşayanlara hep gıpta ile baktım

Yalnızlığın kucağında yıllarca avundum 

Bir akşam üstü bir güzele rastladım

Sanki kalbim; işte bu işte bu diyordu

Sevdim seni hemde vazgeçilmez tutkuyla

Sonrasını biliyorsun, yıllarımız geçti

Hep aynı tazelikte hep aynı sevdayla

Mutluluğun saltanatını sürdük

Sana gülüm dedikçe gülen gözlerin

Canım dedikçe tebessümlerin

Beni her gün yeniden aşık ettiler sana

Bahar yorgunu çiçekler şahit aşkımıza

Hatırlar mısın bana verdiğin ilk karanfili

Heyecanlandırmıştı yürek kırmızısı rengi 

Şiir defterimin arasında hala duruyor

Zavallının yaprakları kurumuş 

Seni seviyorum dediğimi unutmamış

İnan sevdiğim hala rengi kırmızı, solmamış

Bir karanfilin aşka saygısı böyle olurmuş

Tam on yedi yıl geçmiş aradan

Ölüm hariç ayrılık nedir hiç tanımadım

Ve gittin  sanki yeniden gelecek gibi

Bana unuttuğum ayrılık aşkını öğrettin 

Allah’ım nedir bu ayrılık denen hasret

Sen yokken sana daha çok aşık oldum

Keşke giden sen değil ben olsaydım

Ayrılığın aşkını canım, sen yaşasaydın

Ah o hasret yokluğunun hasreti

Sana kavuşmanın hasreti

Seni sevmekten daha lezzetli

(12.04.2002  Tavşanlı)', 'Bir zamanlar aşk nedir diye yaşadım Aşkı yaşayanlara hep gıpta ile baktım Yalnızlığın kucağında yıllarca avundum  Bir akşam üstü bir güzele ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çetinkaya']::text[], 8.5, '{"poet":"Mehmet Çetinkaya","poet_slug":"mehmet-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/unuttugum-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Şu Sevgi Kurşunumu', 'al-su-sevgi-kursunumu-atil-kesmen-9sqi9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tek bir kalp atışı, sızıdır yüreğimde				

Sığmıyor, ne yapsam, ne etsem				

Ne gündüzler, ne geceler gönlüme				

Zindan soğukluğu sarmış, yüreğimi				

Kaderin acımasız yaşları damlıyor				

Boş kalmış ellerime				

				

Çaresiz duygularım, yörünge olmuş hislerime				

Ağlamak yetmiyor,sahipsiz kalmış gönlüme				

Yel olmuş sevgim, kayboluyorum gözlerimde				

Bedenim tanımıyor artık beni, bu anlamsız nefesimle				

				

Sevgiyi yıllardır sen diye ördüm kalbime				

Sensizlik bir boşluktur, kayboluyorum benliğimde			

Yaktın, kavurdun yok ettin beni				

Sana akan sevgi selimde				

				

Al şu sevgi kurşunumu				

Vur öldür beni, kendinde				

Artık ne gözlerim, ne kalbim kaldı sen''de				

Ağlayan, kanayan ben değil				

Sen olacaksın, bir gün bu sevgi denizinde', 'Tek bir kalp atışı, sızıdır yüreğimde				 Sığmıyor, ne yapsam, ne etsem				 Ne gündüzler, ne geceler gönlüme				 Zindan soğukluğu sarmış, yü...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/al-su-sevgi-kursunumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-huseyin-sigirtmac-bfyqw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hangi yüce dağa ses versem anlar.

Derdimi sizlere yazayım dağlar.

Düşünceye saldı beni insanlar.

Kime kahredip de kızayım dağlar.

Koca Erciyes’in çıksam başına.

Seyredip de doysam toprak taşına.

Hasretliği gömsem karlı döşüne.

Yar ile kaygısız gezeyim dağlar.

Uludağ’a çıkıp yeşili sarsam.

Yar ile buluşup vuslata ersem.

Sığırtmaç der gamı zirvene sürsem.

Bağrında neşeyi sezeyim dağlar.', 'Hangi yüce dağa ses versem anlar. Derdimi sizlere yazayım dağlar. Düşünceye saldı beni insanlar. Kime kahredip de kızayım dağlar. Koca Erciy...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/daglar-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meyhaneci', 'meyhaneci-zeynep-nilgun-gokceoz-clo5e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu akşam efkarlıyım,

Bu akşam yastayım meyhaneci,

Sabaha kadar misafir et,

Usulca dinle beni.

Kuytu bir masa olsun,

Kadehler,

Sabaha kadar dolsun, boşalsın.

Damarlarımda benim kanım değil,

Onun kanı dolaşsın,

Haydi artık başlasam,

Çırılçıplak kalmış,

Bir sevdayı anlatsam.

Karşındaki,

Dibe çökmüş biri meyhaneci,

Getir kadehleri,

Akıt içimdeki zehirleri,

Sen içme yalnız beni dinle,

Biraz bekleyelim

Belki girecek bu kapıdan içeriye.

Bak meyhaneci,

Gülerken ağladığımı sanma,

Yine de güldüğüme aldanma,

Bu gün yada yarın

Ne derlerse desinler

Dildir bu, 

Terk edenin ben olduğuna inanma.

Söylesem mi  sevdiğimi acaba,

Ne sevinçler, ne hüzünler umurumda,

Bir tek düşüncem var,

Ölmeden söylemeliyim ona.

Dayandım işte gücümün sonu,

İlk ve son yakarışım bu,

İstesem de vazgeçemem ondan,

İstesem de vazgeçemem bu yoldan,

Yüreğim onunla dağlandı,

Onunla gideceğim bu dünyadan.

Kalkmalıyım artık meyhaneci,

Gelir belki

Benim gibi bir dilenci,

Sorarlarsa bir gün sana,

Çekinme anlat onlara.

Dipsiz bir uçurumun kenarında

Güneşin yeniden doğmasını,

Mutluluklar dilediğim

Kayıp yollarda,

Açmayı unutmuş 

Solgun umutlarda

Onu beklediğimi söyle.

Bulut olup 

Kaybettiğim yağmuru,

Sevgi olup

Yaşadığım yoksulluğu,

Aşk olup

Sevenlerin bedeninde kaldığımı

Sevişenlerde onu bulduğumu

Senden bile medet umduğumu

Anlat artık onlara,

Anlat meyhaneci beni soranlara.', 'Bu akşam efkarlıyım, Bu akşam yastayım meyhaneci, Sabaha kadar misafir et, Usulca dinle beni. Kuytu bir masa olsun, Kadehler, Sabaha kadar d...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/meyhaneci-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Kan Gülleri', 'kirmizi-kan-gulleri-tevfik-tas-wv0mt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Türkiye’de F Tipi hapishanelere karşı başlayan ölüm oruçlarında bir çok insan can verdi. Yaşamayı sürdürebilenler ölümcül, sakat.

Söylesene köhneliklerin bastığı dünya, söylesene hangi yüzyıl sona erdi, başlayan hangisi? 



Eğik başımız. Kurumuş gözlerimiz toprakta

Yıl boyunca zihinde işledi burgu

Durmaksızın yağdı ölümün kırmızı karı



Fırat havzasının tarihsiz taş baltaları gibi

Ufalanmış bedenler için inip kalktı kazmalar

Zindan içre zindan istemeyenlere

Karanfiller

Adsız  çiçekler

Edirne’de

Tunceli’de, İstanbul’da

Merzifon’da, Sivas’ta

Tokat’ta  kadınlardan biri

Bir kucak selvi dalıyla, sessizce mezara indi

Ölümle toprak arasına

Yosunlu dallardan

Turhal işi bir yazma dokurken

“Kızım...” diyordu. “Kızım

Erimiş kemiklerin dayanmaz bu ağırlığa”

Ateşte dövülen bakırdı sesi

Nâr üstünde dönen Hubyar semahı

Diyemem, diyemem ki ağlıyordu

Bütün yıl toprağa baktık

Soframız sisli. Bakışlarımız çukur

Çorum’a güz iniyordu. Sarı, rüzgârlı

Küreklerin ve Kuran’ın sesi

Aynı yanıtsız soruyla dönüyordu

Adam, avuçladığı ıslak toprağa gömdü yüzünü

Çorum’un eski uygarlıklarına sesleniyordu

–Paflagonyalılara, Hititlere

 “Duyuyor musun yavrum

Kanlı düşmanıma vermesin Mevla

Yerin yedi katı duydu

Duymuyor bu dünya”

Duymuyor', 'Türkiye’de F Tipi hapishanelere karşı başlayan ölüm oruçlarında bir çok insan can verdi. Yaşamayı sürdürebilenler ölümcül, sakat. Söylesene ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Taş']::text[], 8.5, '{"poet":"Tevfik Taş","poet_slug":"tevfik-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kirmizi-kan-gulleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler (59) '' Mudurnu''da Konak Var...''', 'maniler-59-mudurnu-da-konak-var-abdullah-atay-nwdng', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mudurnu''da konak var 

yar da elma yanak var 

seyyah olmuş şu gönlüm 

yar bağrında konaklar... 

tütün ince kıyılır 

gönül yare bayılır 

bu ölümlü dünyada 

nasıl cana kıyılır... 

sevda gözde okunur 

yarsız gönül yakınır 

şakıyan bülbül dilim 

kalb kırmaktan sakınır... 

güllerim mor açıyor 

hep benden yar kaçıyor 

yardan ayrı kalınca 

günlerim zor geçiyor... 

kireç katarken kuma 

yarim düştü aklıma 

nazlı yarim üstüne 

alır mıyım hiç kuma... 

gülüm var deste deste 

dağıttım eşe dosta 

yarimden haber gelmiş 

derdimden olmuş hasta... 

bağda gülüm goncadır 

yarin beli incedir 

yarimi eller aldı 

benim halim nicedir... 

küp içinde bulgurum 

yar ben sana vurgunum 

nazlı yarim gelince 

uykulara dargınım... 

abdullah atay der ki: 

ata''sız hiç olurduk 

yolsul ve aç kalırdık 

uygarlık yarışında 

bu günü güç bulurduk...', 'mudurnu''da konak var  yar da elma yanak var  seyyah olmuş şu gönlüm  yar bağrında konaklar...  tütün ince kıyılır  gönül yare bayılır  bu öl...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/maniler-59-mudurnu-da-konak-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair', 'aska-dair-zeynep-nilgun-gokceoz-n6xf4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutluluğu denedi

Olmadı,

Fırtınalarda ölümü bekledi,

Gelmedi,

Rüzgarlardan bir fısıltı istedi,

Duymadı,

Sevdi, sevgi oldu,

Aşk dedi,

Sevişenlerde onu buldu,

Vazgeçecekken

Aşkın gücünü unutmadı,

Hep yeniden başlayan,

Yalanlarla dolu yoldan

Daha aşık,

Daha kederli,

Geldi geçti.', 'Mutluluğu denedi Olmadı, Fırtınalarda ölümü bekledi, Gelmedi, Rüzgarlardan bir fısıltı istedi, Duymadı, Sevdi, sevgi oldu, Aşk dedi, Sevişen...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aska-dair-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışamadım Anne', 'alisamadim-anne-zeynep-nilgun-gokceoz-h1bc6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gittiğinden beri

Boynu bükük kaldık,

Uğurladığımız güne

Yine gözyaşlarıyla yaklaştık.

Bak gideli bir sene oldu

Çiçeklerin hala canlı,

Resimlerin bize gülümsüyor,

Zaman unutturamadı bize seni anne.

Beni affet,

Yeni evine gelemiyorum,

Geldiğim zaman dönemiyorum,

Küçük bir çocuk gibi

Seni bırakmak istemiyorum.

Gücenme bana

Bu unutmak değil

Sensizlik içimi sızlatıyor anne.

Düşlerime geliyorsun bazen,

Her geldiğinde 

Şefkatle öpüyorsun,

Sana muhtaçlığımı anlayıp

Sımsıcak kollarınla sarıyorsun,

Sarmazsan üşüyorum anne.

Seni güzelliklerle hatırlıyoruz,

Haberlerini ulu çınarların

Esintisinden alıyoruz.

Özlemini

Seni anlatarak, seni yaşayarak unutuyoruz.

Hiç gitmemiş, bir gün dönecek gibi

Yüreğimizin köşeciklerinde

Ve bembeyaz bulutların üzerinde

Seni yaşatıyoruz.

Kızma bize anne

Bugün yine ağlıyoruz,

İsyan değil,

Tanrıdan bu biliyoruz,

Yarın sana geliyoruz,

Dualarımızı sana bırakıp

Yanından ayrılacağız 

Ayrılırken yine ağlayacağız,

Çünkü biz hala çocuğuz anne,

Çünkü sana muhtacız anne.', 'Sen gittiğinden beri Boynu bükük kaldık, Uğurladığımız güne Yine gözyaşlarıyla yaklaştık. Bak gideli bir sene oldu Çiçeklerin hala canlı, Re...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/alisamadim-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç', 'agac-yusuf-ter-gwf82', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çiçek dalında bir garip

Böcek yer yaprağı sarıp

Kuşlar yaşar grup grup

Ne güzeldir yeşil  ağaç 

Kökünü  salmış derine

Oturur insan serine 

Bayılır insan gür üne

Ne güzeldir yeşil,ağaç

Bahar çiçek yazın meyve

Elma  armut  yürür ayva

Dedem ona diyor hayva

Ne güzeldir yeşil ağaç

Kağıt odur kitap odur

Ozanın kelamı budur

Cahil kalma öğren nedir

Ne güzeldir yeşil ağaç

Yusuf’um sılama  selam

Hep yazıyor elde  kalem

Sıla kokar buram buram

Ne güzeldir yeşil,ağaç

          Yusuf Ter 14.03.05

           Saat 00:43 İsviçre', 'Çiçek dalında bir garip Böcek yer yaprağı sarıp Kuşlar yaşar grup grup Ne güzeldir yeşil  ağaç  Kökünü  salmış derine Oturur insan serine  B...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/agac-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğrusu Çok Sevdik Biz Seni Hayat', 'dogrusu-cok-sevdik-biz-seni-hayat-bekir-mutlu-gokcesu-bnubc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözümün önünde her an

Gönlümün görmeyi reddettiği

Sütunlara manşet çirkinliklerin

İnkar etmiyorum az okşamadı ruhumu meltemin

Fakat sana sınırsız açtığım şu bağrıma

Feryadı, figanı ve dahi her şeyi sen öğrettin

Her kimin ve her neyin kılığına girdinse

Şu zamana kadar hayat, şükürler olsun ki

Aklımın ermediğine eyvallah demeyi öğretemedin...

Kocaman

Ve yerinden kıpırdamaz

Ruhsuz ve ağır

Haykırışlarca sağır

Bir o kadar kaçak

Kaçamak ve kaypak

Acımasız bir çığsın

Yok sayan çığlıkları

Ve yok eden 

Çiğsin, sığsın sen hayat...

Mevsim bir başka mevsim

Zaman yanlış bir zaman sanki

Aslında, ne bileyim değildir belki de

Biz biraz eskiyoruz herhalde

Biraz da moralsiziz ya işte

Ondandır susmamız, pusmamız

Çabuk parlamamız bazen de...

Doğrusu çok sevdik biz seni hayat

Fakat gördük, duyduk, anladık

Bildik, tattık ve hatta sattık

Bir tatlı tebessüme, geçtik biz senden

Keşke masumu sefil etmesen...', 'Gözümün önünde her an Gönlümün görmeyi reddettiği Sütunlara manşet çirkinliklerin İnkar etmiyorum az okşamadı ruhumu meltemin Fakat sana sın...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dogrusu-cok-sevdik-biz-seni-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardından', 'ardindan-hakan-yasar-yzvhc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Korkuyla fırlıyorum hüzünlü dalmışlığımdan

Umutsuzluğumun terleri basmış her yanımı

Benden uzakta,oldukça uzaktasın

Devasa inançlarla çağırıyorsun beni.

Ayaklarım kalbinin peşinde birer köle

Beni çağıran sevginin izinde gözlerim çalınmış

Oysa sadece ben bilirim seni nasıl bulduğumu

Ama burada değilsin bu yaşadığım şehirde.

Kaçarcasına atıyorum kendimi şaraplara

Bulduğum inançsızlığımın savaş alanı...

Ölüm garip bir kırmızı,ağda vurmuş hava

Kutsal Topraklar özlem olmuş içinde sevgili Lina.

Buradan bir damla gözyaşı ile gidersin Medina''ya

Bense gözlerinin çekiminde cennetteymişim gibi

Her sesinde,her kıpırdanışında izin var İstanbul''da

Gülüşün,çapkın bakışın,belinin ince kıvrımı.

Varolmanın umudu ile aşıyorum yalnızlığımı

Saçlarını kaburgama sermişsin güneş gibi, belli

Yoksa bu kadar yumuşak ve şefkatli olmazdı

İstanbul''un ve Medina''nın şafakları.

Irkının tüm güzelliğiyle gülümsüyorsun

İçimde karabasan gibi bırakılıp gitme duygusu

Soruyorum! Gözünün bebeğinde yanan imkansızlık

Yüzüne yayılan umutsuzluk susuyor...

Ekim''95 İstanbul', 'Korkuyla fırlıyorum hüzünlü dalmışlığımdan Umutsuzluğumun terleri basmış her yanımı Benden uzakta,oldukça uzaktasın Devasa inançlarla çağırı...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yaşar']::text[], 8.5, '{"poet":"Hakan Yaşar","poet_slug":"hakan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ardindan-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Aşkları Satın Almak', 'eski-asklari-satin-almak-halil-pazarli-4bkxc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok mu zor

Kan güllerinin titreyişine ağıt yakmak

Ve közleri alevsiz sonbahar yangınlarına

Tutup bir kucak dolusu odun atmak

El yordamsız dokunuşlarda kanasın bırak

Beyaz çarşafların kündesiz debelenişlerinde

Seninde bütün derdin be gülüm

Sevdasız yolsuzlukların peşinde koşmak

Bak aynada delimtrak onun gözbebekleri

Uçurumlu utanışların dibinde çiçekler açtı

Yalvarsan ne çıkar zifirden gecelere

Kehribar insaflara bir tutam yol kaldı

Bak dün koşanlarda yine yeniden

Limiti sınırsız kredi kartlarıyla

Eski aşklarını satın aldı', 'Çok mu zor Kan güllerinin titreyişine ağıt yakmak Ve közleri alevsiz sonbahar yangınlarına Tutup bir kucak dolusu odun atmak El yordamsız do...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eski-asklari-satin-almak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fer', 'fer-huseyin-cayikli-nf1yk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hatırlarmısın bilmem

gökkubelerine bakıyorduk şehrin

bir çaybahçesinde sen elini tutsak kalmış elime sıkıştırmıştın...

hiç utanmadan öpmüştün

dudaklarıma değmişti tenin...

bir dua gibi kulağıma seslenmiştin

beni terketme...

oysa Tanrı''nın işi çoktu 

kabul edilmemişti o sıradaki cenup duamız...

sen gittiğinde ismin gibi gözlerinde ki fer kalmıştı sadece...

seni terketmedim hiçbir zaman...

Ama o şehirde sensiz gökkubbe aramayacağımı biliyordun....

belki bu nedenle gittin...

terketmen sebepsiz değildi 

ismin gibi gözlerinde ki fer''i o şehirde kaybetmeyeyim diye...', 'hatırlarmısın bilmem gökkubelerine bakıyorduk şehrin bir çaybahçesinde sen elini tutsak kalmış elime sıkıştırmıştın... hiç utanmadan öpmüştü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/fer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahırdan Öte', 'kahirdan-ote-ferit-yilmaz-b8fw6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sen varsın ki içimde

gün be gün derinlere inen

Ağır kurşun gibi

Yıkılası ve vurulası sevginle.

Göğsümde, hep sol yanımda

Ağırlaşan fenalaşan bir özlem

Ve hastalanmış bir çocuk

Hastalığımı ve ölümlerimi saklıyorum.

Bir gece, asıl bu gece

Şarkılar mı? 

Anılar mı bilmem

Bir başka acı, ağır kurşun gibi

Kahırdan öte.', 'Bir sen varsın ki içimde gün be gün derinlere inen Ağır kurşun gibi Yıkılası ve vurulası sevginle. Göğsümde, hep sol yanımda Ağırlaşan fenal...', ARRAY['Türk Edebiyatı','Şiir','Ferit Yılmaz']::text[], 8.5, '{"poet":"Ferit Yılmaz","poet_slug":"ferit-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kahirdan-ote-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamcı', 'aksamci-halil-pazarli-a5a0n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu dünyada herkes yolcu, ancak şiirlere hancıyız.

Gönül meyhanemize takılan her dosta eyyamcıyız.

Hoş sohbetiz, kalp kırmayız, hakkımıza hayhaycıyız.

İlham perimiz içmez fakat, fitil gibi akşamcıyız..', 'Bu dünyada herkes yolcu, ancak şiirlere hancıyız. Gönül meyhanemize takılan her dosta eyyamcıyız. Hoş sohbetiz, kalp kırmayız, hakkımıza hay...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aksamci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar Beni Hoş Görün', 'dostlar-beni-hos-gorun-hifzi-ozbekmez-x7y2b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Siz güzel dostlarıma dualarım böyledir

En sıkıntılı günde güzel rüya düş görün

Dert adamı ağlatır aşk adamı söyletir

Aklım başımda değil dostlar beni hoş görün

Bir sevdanın uğruna dağları aşıyorsam

Yokuşları geçip de düz yolda şaşıyorsam

Bir güzelin aşkıyla coştukça coşuyorsam 

Aklım başımda değil dostlar beni hoş görün

O benim bir tanemse başımdaki taç ise

Aldığım soluk bile hep ona muhtaç ise

O gönlümün sultanı derdime ilaç ise

Aklım başımda değil dostlar beni hoş görün

Derdime derman için kır bayır geziyorsam

Yaralı yüreğimi avcumda eziyorsam

Hata benimdir elbet sizleri üzüyorsam

Aklım başımda değil dostlar beni hoş görün

Ağlanacak halime ben bile gülüyorsam

Kaçınılmaz sonumu maalesef  biliyorsam

Latif gibi göz yaşım akıtıp siliyorsam

Aklım başımda değil dostlar beni hoş görün

MART 2005', 'Siz güzel dostlarıma dualarım böyledir En sıkıntılı günde güzel rüya düş görün Dert adamı ağlatır aşk adamı söyletir Aklım başımda değil dos...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dostlar-beni-hos-gorun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Olmasa', 'ayrilik-olmasa-hifzi-ozbekmez-boa8q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yinede dalarım boş hayallere

Umudum kalmadı vuslata aşka

Kokunu sorarım esen yellere

Ayrılık olmasa ölseydim keşke

İçimden özlemi atamıyorum

Lokmalar dizilir yutamıyorum

Yataklar batıyor yatamıyorum

Ayrılık olmasa ölseydim keşke

Aklıma o şirin gülüşün gelir

Gönlümü gönlüme verişin gelir

Sevenin halini sevenler bilir

Ayrılık olmasa ölseydim keşke

Sevdamız gönlümde sırça saraydı

Özlemin içimde onmaz yaraydı

İsterse cellatlar boynum vuraydı

Ayrılık olmasa ölseydim keşke

Latifim boynum hep bükük duruyor

Ayrılık acısı kalbe vuruyor

Umudum bitirip beni yoruyor

Ayrılık olmasa ölseydim keşke', 'Yinede dalarım boş hayallere Umudum kalmadı vuslata aşka Kokunu sorarım esen yellere Ayrılık olmasa ölseydim keşke İçimden özlemi atamıyorum...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayrilik-olmasa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Micingirt Ben - Tufan Yığıntıları Kitabından', 'micingirt-ben-tufan-yigintilari-kitabindan-omer-ekinci-micingirt-uaqin', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'rüyalarda dolaşırım 

solgun ışıklarla her gece 

dolaşırım bucak bucak devrik düşüncelerimle 

Micingirt ben ve uzun saplı bir dirgen 

ıssız ve yorgun harmanlar 

sessiz kuru yapayalnız 

renk ölü ses maşat yoruldum 

sarsık ve acılıdır hayallerim 

temaşa eder her giden yabancı 

cinni mağaradan aşağı 

kar yüzlü dereleri 

koyu bir sızı sarar zar zar bahtsız yürekleri 

ne kadar da fark ettirmesek de 

müthiş bir duygu taş duvarlar 

viran olan bir mâzi ve 

öldürülmüş eski evler 

çatılar tutuyor perdeliyor 

nasırlı elleri toprak bacaları 

yankılanıyor zigav’ın dere 

akbaba’nın gerdanından 

keder aysbergler gibi 

duygular enkaz 

amcalar yok bir nesil kayıp 

zaman dar dünya berduş

gece zifiri karanlık 

kümbet ayrı bir hendese 

çocuklar benden kaçıyordu 

şeherli gelmiş şeherli nidâlarıyla 

tıpkı dağılmış bir tesbih misali 

imamesi kayıp 

savrulmuştuk baş döndüren 

zamanın akışında 

biçare divane diyordum kendi kendime

sus ağlama sus 

mevsimin sonu kimse ses vermiyordu 

bir ara bir ses duyar gibi 

yosun serinliğinde 

şehirde ilham da yoktu duyguda 

hem yerimi şiir yazmanın

hasretin katılığında boğuluyorum 

hele “koruğa güneş vurunca 

kuzuları getir” 

ah işte bu cümle var ya 

derinden sarsıyor tüm hatırları 

gamda ıslanıyor 

kederde yıkanıyorum

ne zaman yeniden

ne zaman Micingirt ne zaman', 'rüyalarda dolaşırım  solgun ışıklarla her gece  dolaşırım bucak bucak devrik düşüncelerimle  Micingirt ben ve uzun saplı bir dirgen  ıssız v...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/micingirt-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Be Hayat', 'be-hayat-i-smail-dogan-a44t0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözümün önünden sıyrılıp gittin,

Seni nasıl görmedim be hayat! 

Gece uyutup, gündüz de ağlattın,

Su gibi akıp da gittin be hayat! 

Hiç unutmadım ilk adımda salladığını,

Düşüpde elimi kolumu kanattığını,

Ta o zaman gösterdin acımasızlığını,

Neden elimden tutmadın be hayat! 

Alnıma acıların yazısını yazdın,

Üç defa bıçak altına yatırdın,

İki yavruyla beni nasıl kandırdın,

Hiç öpmedin gözlerimden be hayat! 

Zehirle pişmiş aşı korsun önüme,

Senin isteğinle gitmem ölüme,

Bir şans daha versen şu nefesime,

Türkü söyler saz çalarım be hayat! 

Neden torpil geçersin zalımlara,

Dalga dalga çarptın beni taşlara,

Hasret kaldım gül kokulu bahara,

Bana da bir gül vermedin be hayat! 

Ölen olmasın, öldüren olmasın,

İnsanlar bacı gardaş gibi yaşasın,

Ver dünya nimetinden, aç kalmasın,

Hep bizlerden uzak kaldın be hayat! 

Bıktım usandım gülmeyen yüzümden,

Genç yaşımda utandım ak saçımdan,

DOĞANİ giderse fani dünyadan,

Dökme göz yaşı ardımdan be hayat!

14.3.2005', 'Gözümün önünden sıyrılıp gittin, Seni nasıl görmedim be hayat!  Gece uyutup, gündüz de ağlattın, Su gibi akıp da gittin be hayat!  Hiç unutm...', ARRAY['Türk Edebiyatı','Şiir','İsmail Doğan']::text[], 8.5, '{"poet":"İsmail Doğan","poet_slug":"i-smail-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/be-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutku', 'tutku-sitki-gokmen-uvaqo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaklarda olsam da bir hırsız gibi,

Dudaklarından öpücükler çalacağım.

Unuttum artık seni yoksun desen bile,

Gözlerini her açtığında karşında duracağım.

Yanında olacağım her gece bir gölge gibi,

Aldığın her nefeste içini kaplayacağım.

Teninde gezeceğim en kapalı isteklerimle,

Hiç ummadığın zamanda yanında olacağım.

Yorgun uyanırsan düşlerinden sarhoş gibi,

Bil ki düşlerinde yanında yatacağım.

Her gün unutmak için şişelerce içsen bile,

Aklının bir köşesinde saplanıp kalacağım.

DOĞUBAYAZIT 14 MART 1989 01:21 (Geçmişin Defterinden)', 'Uzaklarda olsam da bir hırsız gibi, Dudaklarından öpücükler çalacağım. Unuttum artık seni yoksun desen bile, Gözlerini her açtığında karşınd...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tutku-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asil Sevdam-1', 'asil-sevdam-1-hidayet-avsar-j09c8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aslında,

Bütün ateşi ben yakmıştım

Tenindeki...

Ve ateşe atan kendini,

Yine bendim sevdiğim...

Bir kadında ancak,

Asalet varsa uğruna ölünür..

Bilirim..

Uğruna ölmek değil de

Dermansız kalmak istedim.

Ve en asil türküleri

En asil notalarla yazdım adına “bencileyin”.

Bir yerlerde olmalıydın,

Yanımda değil.

Birileri olmalıydı hayatında,

Ben değil.

Ölmemeliydin,

Olmamalıydın da...

Ancak o zaman şiir olurdun...

Şiirini yazmak istedim,

“Seni kullandım! ” diyebilmek için.

Oysa, kelimelerin ihanet edeceği

Hiç aklıma gelmemişti...

Hiçbir vakit bu kadar geç değildi 

Martıları tutmak için...

Senin elbiseni ben giyiyorum

Ve senin ellerinle kirletiyorum artık.

En asil benim! 

Artık yoksan da varsın.

Ahh! Kelimeler... anlamadı anlamını,

İhanet ettiler bana.

Yazık değil hiçbir serçeye! 

Bedenim kirlenmiş,

Son sözüm söylenmiş artık...', 'Aslında, Bütün ateşi ben yakmıştım Tenindeki... Ve ateşe atan kendini, Yine bendim sevdiğim... Bir kadında ancak, Asalet varsa uğruna ölünür...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/asil-sevdam-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah! İstanbul Ah!', 'ah-i-stanbul-ah-nur-demirciler-m3vtb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nice aşklar yaşandı kimbilir koynunda,

Ya da nice hüzünler gizli her bir taşında.

Her yeni yıkıma,

her yeni acıya rağmen,

hala dimdik ayakta.

Nice aşklar doğacak,

nice acılara gebe olacak belki de,

sadece hayali yetecek kimilerine,

özlem dolu gözlerle resmine bakarken,

'' ah! İstanbul ah! 

bir ben mi sığamadım koynuna? 

bir ben mi bulamadım aradığım aşkı sende? ''

desen de inan,

bir sen değilsin özleyen,

bir sen değilsin yalnızlık çeken,

İstanbul''un koynunda,

bir başına....

30/11/2004

İstanbul', 'Nice aşklar yaşandı kimbilir koynunda, Ya da nice hüzünler gizli her bir taşında. Her yeni yıkıma, her yeni acıya rağmen, hala dimdik ayakta...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ah-istanbul-ah-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Patates', 'patates-bekir-gedikoglu-fri37', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duman kaplamış dağları

Rüzgar, buz gibi esiyor

Savuruyor tozu toprağı

Sıcacıktı heybemdeki patatesler

Yeni haşlanmış

Yiyordum onları teker teker

Yarabbim! Hemde bu havada

Küçücük bir kız duvar dibine çömelmiş? 

Duvarı siper eylemiş

Yaklaştım ağır, ağır

Minnacığın elleri morarmağa başlamış

Sık sık ağzına götürerek

Ellerini nefesiyle ısıtmağa çalışıyor

Ara sıra

Üşüyen ellerini

Göğsü ile bacakları arasına sıkıştırıyordu

“Ne arıyorsun burada, niye geldin? ”

Sadece..gözlerime diktiği naçar kalmış bakışlar

Heybemdeki patateslerden

Uzattım birini

Daha soymadan kaptığı gibi

Boğazından

Transit geçiriverdi

Çabucak soyuverdim

İkincisini

Vermeden! 

İkaz ettim 

Yavaş, yavaş yemesini

Arkasından üçüncüsü

…dördüncüsü

….bu çocuğun hali

derinden etkilemişti beni

…gözlerinde minnettarlık

Al yanaklarında gülücükler beliriverdi

Sorduğumda 

Bana adını söyledi; 

“Zeynep”

Kimin kızısın? 

Şevket Çoksever’in

Tanıdığım nalbant Şevket’in

Yukarı mahalleden

Görmediğim en küçük kızı

Şevket amcanın

Minicik üşümüş ellerini

Avuçlarıma aldım.

..Ovalayıp

Isıttım

Bir patates daha soydum

Eline verdim

..o yerken

Kalan patatesleri de

Entarisinin ceplerine

Koyuverdim.

“Ee arkadaş neden buradasın? ”

-Annemin çok sevdiği vazoyu kırdım

-Bilmeden oldu, çok korktum

-Kaçarak buraya saklandım

Cebimdeki eldivenleri ellerine takıverdim

Hemen yeleğimi de giydirdim

Kaşkol umuda başına sarınca..

Kızcağızın keyiflendiğini hissettim

..Nihayet

Küçük arkadaşımla birlikte yola koyuldum

Ankara 3 Şubat 2005', 'Duman kaplamış dağları Rüzgar, buz gibi esiyor Savuruyor tozu toprağı Sıcacıktı heybemdeki patatesler Yeni haşlanmış Yiyordum onları teker t...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/patates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Yakamdan', 'dus-yakamdan-mesut-alp-ktxu3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soldum yapraklar gibi

Üşüdüm yaz ayında

Seni beyazlar içinde gördüğüm anda

Doldu gözlerim doldu ağlayamadım

Bin kez kahrettim kadere dayanamadım

Seni zalim kader

Düş yakamdan yeter

Gülmeye hasret kaldım

Ağladığım yeter

Hayatta sevdiğim tek varlık

Ellerin oldu artık

Neyim kaldı hayatta

Alacaksan canımı al artık

Seni zalim kader

Düş yakamdan yeter

Gülmeye hasret kaldım

Ağladığım yeter', 'Soldum yapraklar gibi Üşüdüm yaz ayında Seni beyazlar içinde gördüğüm anda Doldu gözlerim doldu ağlayamadım Bin kez kahrettim kadere dayanam...', ARRAY['Türk Edebiyatı','Şiir','Mesut Alp']::text[], 8.5, '{"poet":"Mesut Alp","poet_slug":"mesut-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dus-yakamdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isa', 'isa-mahir-celik-o6l8t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çan sırtındayım 

raylar üzerinde -seyirde 

sapmak lüks 

oysa İsa gibi 

biri kısa 

biri uzun çıtalarla 

uçurtma olmuştum 

düşbakışlarımla bakıyordum 

serpildiğim toprağa 

çan sırtındayım 

yoldan çıkmak hâlâ lüks 

hem sen Antuan’ dasın 

caddede kardeşin 

umut gel paylaş benimle lokmanı 

çakılı avuçlarım 

haylaz uçurtmayım 

çan sırtındayım 

ölüm bitmekse 

mavi olsun adım', 'çan sırtındayım  raylar üzerinde -seyirde  sapmak lüks  oysa İsa gibi  biri kısa  biri uzun çıtalarla  uçurtma olmuştum  düşbakışlarımla bak...', ARRAY['Türk Edebiyatı','Şiir','Mahir Celik']::text[], 8.5, '{"poet":"Mahir Celik","poet_slug":"mahir-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/isa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senkolik', 'senkolik-sahin-erturk-5u43j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hülya olmuş Medyakolik

Selçuk olmuş Şiirkolik

Sevda olmuş Hasretkolik

Müslüm desen tam Alkolik

Ben se oldum bir SENKOLİK

Yüreğime yeni girdin

İnan orda ÖZEL yerin

Hiç kimseler olmaz dengin

Korkma artık solmaz rengin

Senkoliğim ben SENKOLİK

Sakın bana çıldırmışsın

Delirmişsin deme sakın

Dinlemiyor gönül ferman

Dertlerime oldun derman

Senkoliğim ben SENKOLİK

Son yazdığım şiir sensin

Okuduğum kitap sensin

Sensin güzel herşey sensin

Damardaki kanım sensin

Senkoliğim ben SENKOLİK

Güzel sözler sana artık

Şiirlerim sana artık

Öykülerim sana artık

Canım,kanım senin artık

Senkoliğim ben SENKOLİK

(14.03.2005-yENİ)', 'Hülya olmuş Medyakolik Selçuk olmuş Şiirkolik Sevda olmuş Hasretkolik Müslüm desen tam Alkolik Ben se oldum bir SENKOLİK Yüreğime yeni girdi...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/senkolik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-hidayet-avsar-r6vvi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerin aklıma düştü,

Deli oldum.

Hatırlasana hani

Kimseler görmemişti...

Ne de güzel bir düştü...

Düşümde seni buldum.

Saçların aklıma düştü,

Rüzgar oldum.

Estim yanına kadar,

Kasırga oldum.

Duruldum.

Yağmurun yere düştü,

Toprak idim, çamur oldum.

Bulut bulut gördüm seni,

Damla idim, deniz oldum.

Sonra hece, sonra cümle...

En sonunda şiir oldum.', 'Ellerin aklıma düştü, Deli oldum. Hatırlasana hani Kimseler görmemişti... Ne de güzel bir düştü... Düşümde seni buldum. Saçların aklıma düşt...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dus-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kürekçi', 'kurekci-hidayet-avsar-pyi01', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yok ettiğim günlerim,

Sebebin yalnız benim.

Kıymeti yok sevgimin,

Zarar eden hep benim.

Çektikçe bu sancıyı,

Yuttukça bu kaygıyı,

Unuttukça kavgayı,

Kürekçi yalnız benim.

Bir sevda yüreğinde,

Fırtınalı bir yerde,

Başka herşey dengede,

Dengesiz olan benim.

Katiliyim kendimin,

Yazısıyım künyemin,

Karasıyım gölgemin,

Divane yalnız benim.', 'Yok ettiğim günlerim, Sebebin yalnız benim. Kıymeti yok sevgimin, Zarar eden hep benim. Çektikçe bu sancıyı, Yuttukça bu kaygıyı, Unuttukça ...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kurekci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanç Sevgi', 'kiskanc-sevgi-mehmet-cetinkaya-aogi0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana verdiğim gülü koklarken, 

Hani rüzgar, gülün yapraklarını savurmuştu. 

Koklayamamıştın. Öylece bakıp kalmıştın. 

Sevgimi rüzgarla paylaştığın için, seni affedemiyorum. 

Ben, hala o kıskançlıkta duruyorum. 

Kalbimde saltanatını süren sen! 

Rızkımı kazanmak için çalışırken,

Beynimdeki hücrelerden bile kıskandığım sen.! 

Haber ver artık, bu çilem ne zaman bitecek. 

Leyla ile mecnun asırlar ötesinde kaldı. 

Yeni yüzyılda temsil etmek, bize mi kalmış. 

Ben seni kavuşmak için sevdim. 

Elinden tutup yağmur altında dolaşmak için sevdim. 

Islanmış elbiselerle ocak başında, 

Çıtırdayan çam odunlarının sesinden,

Senin sesini kıskanmak için sevdim. 

Ateşin gözlerine vuran ışığını kıskanmak için sevdim. 

Bir yudum çaydaki sıcaklığı, 

Sevgimin sıcaklığından kıskanmak için sevdim.

Sana olan sevgimden rahat olan vicdanım, 

Yokluğunda beni yargılar oldu. 

Ne olur bir gelsen. Bitse bu hasret. 

Sevgimizi, aşkımızı konuşmak güzel. 

Fakat geleceği  olmayan aşklar bitmeye mahkumdur. 

Ben, geleceğimizi aynı şiddetteki sevgimle, iyiyi, güzeli, 

Arada bir, çileli hayat yollarını konuşmak istiyorum. 

Alacağımız ekmekleri, evimizin boyasını, 

Ve nicelerini konuşmak istiyorum. 

Bekledikçe artan kıskançlığımdan bile seni kıskanır oldum. 

İçimi yakan bu bekleyiş,

Ya seni bana getirecek, ya da beni sana götürecek. 

Gel, tam ortada, kıskançlığı boğacağımız yerde buluşalım. 

Şah damarımın en sakin olduğu yerde. 

Kan hücrelerimin seni sayıkladığı yerde. 

Şu anda yediğim yemeğin gıdası, 

Mideme gidecek ve hücrelerime karışacak. 

Ve seninle tanışacaklar.

Seni onlardan bile kıskanmak için sevdim.

Sevgi kelimesini çerçeve yaptırıp odamdaki duvara astım.

O kelime yalnız senin için.

Kalbim hikmetinden sual olmasa sen diye çarpacak. 

Ve diyorum ki; 

BEN SEVERSEM EĞER 

         DERYALAR TAŞAR

 BEN SEVERSEM EĞER

        AKLIM BİLE ŞAŞAR

BEN SEVERSEM EĞER

       ÇİÇEKLER  AĞLAR

BEN SEVERSEM EĞER

        KALP KAPAKLARIM ÇARPAR

Ben seni bu yürekle seviyorum.

İşte gülüm  seni bunun için kıskanıyorum.

15.03.1997 Tavşanlı', 'Sana verdiğim gülü koklarken,  Hani rüzgar, gülün yapraklarını savurmuştu.  Koklayamamıştın. Öylece bakıp kalmıştın.  Sevgimi rüzgarla payla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çetinkaya']::text[], 8.5, '{"poet":"Mehmet Çetinkaya","poet_slug":"mehmet-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/kiskanc-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-hidayet-avsar-iba3s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakma güzel, boynu bükük durduğuma,

Bu yerlerin en adi serseriyim.

Acıyan gözlerle bakıp, aldanma solduğuma,

Islak yatakların en hızlı fahişesiyim.

Bazen, umut sarayının soytarısı,

Bazen, boş beşiklerin karartısı,

Bazen yeşil baharların sarartısı,

Dava ülkesinin en hain askeriyim.

Ben, sönmüş ocakların neşesi,

Ben, bitmiş aşkların çilesi,

Ben, vurulmuş kuşların kellesi,

Feleğin umutlara atılmış sillesiyim...', 'Bakma güzel, boynu bükük durduğuma, Bu yerlerin en adi serseriyim. Acıyan gözlerle bakıp, aldanma solduğuma, Islak yatakların en hızlı fahiş...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-156-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım! !', 'anladim-ali-gencay-3zfx1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soyundu hasretim, dokunamazlığıma

Avuçlarımda kor ateş

Yanmaktayım! 

Aşk bir kez daha vur hadi

Uzağı yakın eder yolar! 

İsyanım zamana

Iraklık neymiş, adını koymaktayım

Dikilirim karşına

Dudaklarımda bıçak kesmiş suskunluğum

Gözlerimde muhteşem hayal

Sana aşkımı anlatmaktayım

Nafile! 

Kayalara vuran dalgalar! 

Sizi şimdi daha iyi anlamaktayım

Yüreğim! 

Seni bitmişliklerle bitap bulmadım 

Avuçlarımda sönük yıldızlar hiç saymadım

Kuşlar terk eder elbet yurdu bilirim

Sen terk edemediğimsin

Anladım!', 'Soyundu hasretim, dokunamazlığıma Avuçlarımda kor ateş Yanmaktayım!  Aşk bir kez daha vur hadi Uzağı yakın eder yolar!  İsyanım zamana Irakl...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anladim-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kunduz Yuvası', 'kunduz-yuvasi-hidayet-avsar-ni3l0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duvarların üstündedir yazılar.

Duvarların ötesini anlatır, harf harf.

Sessiz, karanlık,

Biçare gecelerde baykuşlar öter,

Sıcacık bir yürek donar buzullarda,

Ölüm kokar ölümsüzlüğün anlamı

Ve sesler duyulur bir an.

Eller kurumuş, gözler toprakla dolmuş,

Karıncaları duyamazsın...

Oysa, kemirirler bütün zamanı.

Beste beste çalınırsın sazlıklarda,

Kunduz yuvasında uyur,rüyada uyanırsın mavilerle.

Nedense herşey yuvarlak, zamandan başka,

Başladığı yerde bitiyor hayat.

Oysa, anlamına yazılmıştı bütün şiirler...

Anlamadın anlamını...', 'Duvarların üstündedir yazılar. Duvarların ötesini anlatır, harf harf. Sessiz, karanlık, Biçare gecelerde baykuşlar öter, Sıcacık bir yürek d...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kunduz-yuvasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hallaca muhabbet.1', 'hallaca-muhabbet-1-ali-riza-unal-k27j4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hikmettir vel velen hicapta Mevlâ.

Dilersen gelir el ele hasımın Mevlâ

Sen yarattın ezelde hasleti haseti.

Habili Kâbile düşürdün Mevlâ.

Yerden yere vurdun dostun postunu.

Nesimiyi dâra düşürdün Mevlâ.

Hasm eyledin küfrü imana.

İbrahimi nara düşürdün Mevlâ.

Leylâ oldun sıska nigâra.

Mecnunu çöle düşürdün Mevlâ.

Sultan kıldın süleymenı fani cihana.

Düçâr ettin karıncaya üşürdün Mevlâ.

Döküldü fitneyi nifak zülfünden belâ.

Külhanı pinhana düşürdün Mevlâ.

Avaz eyledin kulundan enel hak diye.

Hallacı mollaya düşürdün Mevlâ.

bu dizenin tefsiri:  bir yanlış anlaşılmaya meydan vermemek için

açıklama yapma zorunluğu doğmuştur  dizede H.z ALLAHa kötülüklerin

faili gibi anlaşılma ve cenâbı HAKKA iftira gibi görülmesine fırsat vermemek

için Aşağıya tefsiri meal verilmiştir ehline zaten malümdur.sevgilerimle.

hadımul fukara Ali Rıza Ünal.

Tövbe haşa, Hz Allaha şeytan bile ALLHA kötülük isnad etmemiştir.

BU aciz fakirin ne haddine o Zatı Tealaya kötülük iftirası Atmak 

Cancağaz kardeşlerim  sizlerin kötülük olarak gördüğü fiillere biz.

Hikmet nuru ile bakarız, işte ihtilaf olarak görülen konuda bu bakış

Açısından kaynaklanmaktadır ve sizlerin eleştirilerini de bir hikmet

Olarak görmekteyiz ve Rahmet olarak kullanmaktayız.Hepinizden

ALLAHU tealâ Hazretleri razı olsun Bu söylemin dört mertebesi

Bulunmaktadır.

1	İlmel Yakin--Kelime’i Tevhit.

2	Aynel Yakin--sıfatı   Tevhit.

3	Hakkal yakin--ef-ali tevhit yani fiilleri tevhid.

4	Yakin ı fena--ZATI   tevhit. Burası aynı demde.

Şehadet mertebesidir. 

Tevhid ne derseniz? birlik  (bir)   o birde yok olmak değil.

O birde hiç olduğunu idrak etmektir  var olan yok olmaz yok 

Olanda var olmaz. Bunun aksi cehalet ve gafleten başka hiç

Bir şey değildir. Yetmişiki millete selam olsun! 

 SELÂMÜNALEYKÜM:  ;)))

Aman Allahım aman.

Medet ya Rabbi medet.', 'Hikmettir vel velen hicapta Mevlâ. Dilersen gelir el ele hasımın Mevlâ Sen yarattın ezelde hasleti haseti. Habili Kâbile düşürdün Mevlâ. Yer...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/hallaca-muhabbet-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allı Pullu', 'alli-pullu-hidayet-avsar-64ng4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neler yazsam, allı pullu,

Ne söylesem sıradan.

Kuşlar yine uçacak,

Batacak güneş yine.

Devran dönüyor gülüm,

Kime düşer durdurmak.

Hem Kaf Dağı zaten yok,

Sen de yoksun ardında.

Hepten verilmiş hüküm; 

“Bu çorba tuz istemez! ”

Ve bitemez bu kalem,

Yazar da allı pullu...', 'Neler yazsam, allı pullu, Ne söylesem sıradan. Kuşlar yine uçacak, Batacak güneş yine. Devran dönüyor gülüm, Kime düşer durdurmak. Hem Kaf D...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alli-pullu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İste', 'i-ste-hidayet-avsar-sl6qa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İste, 

Sevinçlerimi vereyim; 

Toprak, gül arkadaşım.

İste,

Dostun olayım.

Kimse bilmez dostluğu

Benim bildiğim kadar.

İste,

Al yüreğimi! 

Bir yanı mavi, yeşil

Bir yanı kapkaranlık...

Yüreğimi al,

Bende kal...', 'İste,  Sevinçlerimi vereyim;  Toprak, gül arkadaşım. İste, Dostun olayım. Kimse bilmez dostluğu Benim bildiğim kadar. İste, Al yüreğimi!  Bi...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iste-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Mektup', 'dosta-mektup-hidayet-avsar-9tvbl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Söyle dost! 

Hala renklerin en alasını mı

Özlüyorsun...

Yoksa yitip gitti mi sevdiğin,

İstasyondan ayrılan 

son trenin düdüğünde...

Sen ki yeşil bir tablo görsen

Yeşil olurdun,

Deniz görsen mavi,

Çocuk görsen umut...

Unut dostum! 

Yaşamayı, aşkı unut! 

Biz ki yorulduk, “part time” sevdalardan.

Biz ki, uçkur bildik “merhameti”,

“Artiz” yaptık hurileri...

Ve hala yaşıyoruz tencerenin kapağında...

Öyle bir haldeyiz ki dostum; 

Mum ışığı görsek, güneş sanıyoruz...', 'Söyle dost!  Hala renklerin en alasını mı Özlüyorsun... Yoksa yitip gitti mi sevdiğin, İstasyondan ayrılan  son trenin düdüğünde... Sen ki y...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dosta-mektup-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çorbacı', 'corbaci-sitki-gokmen-9kexs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çorbalar yapıyorum acı,

Çorbalar yapıyorum tatlı,

Çorbalar yapıyorum isteğe bağlı.

(ANKARA 14 MART 2005 15:35)', 'Çorbalar yapıyorum acı, Çorbalar yapıyorum tatlı, Çorbalar yapıyorum isteğe bağlı. (ANKARA 14 MART 2005 15:35)...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/corbaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Leblebi', 'beyaz-leblebi-hidayet-avsar-0n020', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaten sebebim yoktu içmeye,

İyi oldu gittiğin...

Beyaz leblebi ve sen,

Bir de bende erittiğin...

Kimbilir günü gelir

Gelişine içerim.

Tam da sebepsiz kalmışken,

Bittiğinde beyaz beyaz leblebilerim,

Ve en çok...

En çok ölmek isterken gelirsin de

Beyaz leblebilerin laneti sarar ikimizi...kimbilir...

Hey çocuk! 

Boşuna uğraşır, beyaz beyaz leblebiler...

Yazılmış, yazılacakmış...

Yazılıyor! 

Beyaz leblebilerin efsanesi...

Ne diyelim; 

Yalnızca beyaz değil,

Bütün leblebilerin laneti üzerine olsun.', 'Zaten sebebim yoktu içmeye, İyi oldu gittiğin... Beyaz leblebi ve sen, Bir de bende erittiğin... Kimbilir günü gelir Gelişine içerim. Tam da...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/beyaz-leblebi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek ve Sevilmek', 'sevmek-ve-sevilmek-huseyin-erdogan-phimy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sevmek ve sevilmek

iki güzel fiildir

bir başka güzeldir

gelince yan yana

her ikisi de

hitap eder

insan ruhuna

ben sevgisiz yapamam

gıdasız da kalamam

her türlü vitamin

her çeşit protein

bulunur onda

aç bırak beni amma

sakın sevgisiz bırakma

ya da

mezarımı hazırla

          14.03.2005', 'sevmek ve sevilmek iki güzel fiildir bir başka güzeldir gelince yan yana her ikisi de hitap eder insan ruhuna ben sevgisiz yapamam gıdasız d...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevmek-ve-sevilmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Böyle Bil', 'beni-boyle-bil-mehmet-cetinkaya-r404c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben kimi zaman bir sevgilinin beklediği

Kimi zamanda beklenip beklenip gelmediği

Kimi zaman ekmeksiz kalan garip

Bedava ekmek kuyruğundan muzdarip

Kimi zaman bir ailenin mutluluğu

Bir annenin yavrum dediği çocuğu

Bir genç kızın nikah masasındaki Evet ’i 

Nikah salonunda  kaybedilen sevgili

Kimi zaman gönül saltanatının tacı

Bazen bir sevgilinin en büyük muhtacı

(08.11.2002 Tavşanlı)', 'Ben kimi zaman bir sevgilinin beklediği Kimi zamanda beklenip beklenip gelmediği Kimi zaman ekmeksiz kalan garip Bedava ekmek kuyruğundan mu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çetinkaya']::text[], 8.5, '{"poet":"Mehmet Çetinkaya","poet_slug":"mehmet-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/beni-boyle-bil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlle de O!', 'i-lle-de-o-aysun-erat-5hpfn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine aklıma düştün, 

Durup dururken.

Sürprizlerle dolusun sen.

Her gelişin, başka güzel.

Canım seni çekiyor işte! 

Ne yapmalı? Bilmiyorum…

Söylüyorum canıma,

Unut onu gitsin, çaresizsin…

Başkasından kime ne? 

İlle de o! diyor,

İlle de onun gözleri,

Onun sözleri,

Onun elleri,

İlle de, o sarsın beni! 

Başka bir şey demiyor…

Beni hiç dinlemiyor…

Hiç dinlemiyor….

03/2005', 'Yine aklıma düştün,  Durup dururken. Sürprizlerle dolusun sen. Her gelişin, başka güzel. Canım seni çekiyor işte!  Ne yapmalı? Bilmiyorum… S...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ille-de-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sis Mektupları', 'sis-mektuplari-mehmet-cetinkaya-g26o2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz sevdik, aşkı yaşadık,

Ay parlak, güneş aydınlık

Gece gümüşten mehtap diye sevdik 

Bir bahar akşamı diye başlayan şarkılar

Kıskanırım seni ben derken

Artık seni sevmeyeceğim diye biterler

Biz ayrılamayız şarkısını bile unuttuk.

Kırılan kalpler boş kalan eller

Dost dediklerimiz hep güldüler

Uçup giden umutlar ve

Ebruli yakamozlar bir bir kayboldu gitti

Sis bulutları gibiymiş o yıllar

Gözlerim kurudu yüreğim ağlıyor yüreğim.

Çocuktum minicik ufacıktım

Beraber simit almaya giderdik 

Bir simidi İkiye bölüp 

Yarısı sen yarısı ben dediğim zaman

Neden bir masa ayırtamadım pastanede bilir misin

Gözü çıksın bu fakirliğin, param yoktu param...! 

Üç kuruşluk dondurma parasına gittin...! 

Sen mahallede olmadığın zaman

Tahtadan arabalarla çok oynadım

Bilirdim parayla oyuncak alınmayacak

Tıpkı parayla saadet olmaz şarkısı gibi..! 

Bilemediğim yalnızca senin bakışlarındı

Yüreğime inen merdiven basamaklı sözlerindi.

Ah..! akıp giden yıllarım nerede şimdi

Getir bana bir günümü 

Söz seni bekleyeceğim

Beni yakan gözlerinle bak bana

İçinde aşk dediğin ateş varsa

Yüreğinde cesaretin varsa

Bul beni beklediğim yerde sevdiceğim. 

Sis mürekkeplerinden seviyorum yazdım ufuklara

Gümüş den mehtaplarda 

Güneş doğmadan bul beni

(01.02.2001 Tavşanlı)', 'Biz sevdik, aşkı yaşadık, Ay parlak, güneş aydınlık Gece gümüşten mehtap diye sevdik  Bir bahar akşamı diye başlayan şarkılar Kıskanırım sen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çetinkaya']::text[], 8.5, '{"poet":"Mehmet Çetinkaya","poet_slug":"mehmet-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sis-mektuplari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Annem Afet Beni', 'canim-annem-afet-beni-doner-ozeke-4n9iz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir pazar günüydü öğlene yakın 

Gidin evine de anama bakın 

Havalar soğudu sobasın yakın 

Acı haberini vermeyin sakın 

Anam uyuyorsa üstünü örtün 

Anam uyku sever uyarman sakın 

Uyusun deymeyin uzaktan bakın

Susun sessiz olun korkmasın sakın 

S.S.K ya gittik hava verdiler 

Derdi nedir diye bana sordular 

Yaşlılıktan diye rapor verdiler 

Anam yokluğuna dayanamam ben 

Bir inat uğruna kırdım ben seni 

Ne olursun anam afet sen beni 

Nafile ne desem gelmezsin geri 

Canım anam afet ne olur beni 

Ecel gelmiş baş ucunda duruyor 

Yüreğim ağlıyor içim yanıyor

Anam bu dünyada kimse kalmıyor 

Etme felek etme alma anamı 

Gözlerin kapalı yüzün gülüyor 

Oğlun kızın peşin sıra geliyor 

Ateş düştü yüreklerim yanıyor 

Etme felek etme alma anamı

Cenazeler sıra sıra düzüldü

Duyan dostlar anam sana üzüldü 

Bellerim kırıldı boynum büküldü

Etme felek etme alma anamı 

                       DÖNER ÖZEKE

                          14.03.2005', 'Bir pazar günüydü öğlene yakın  Gidin evine de anama bakın  Havalar soğudu sobasın yakın  Acı haberini vermeyin sakın  Anam uyuyorsa üstünü ...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/canim-annem-afet-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asırların Nöbetçisine', 'asirlarin-nobetcisine-mehmet-cetinkaya-s0cw9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben, bir günün kısa saat nöbetçisi,

Sen, yorgun asırların nöbetçisi.

Düşman dayanmaz akıl heybetine,

Nöbet sıran geldi, kalk, asır nöbetine.

Kalk aslanım kalk, nöbetçi çavuşu gelecek,

Asır nöbetçisi hala kalkmadı mı diyecek.

Yatağında yoksun, not bile bırakmamışsın,

Yastığın ıslak aslanım, sel gibi ağlamışsın.

Utandım, seni yatağında aramaktan,

Uzaktan uzağa kalk diye bağırmaktan.

Bilmeliydim, ruhunun nerede olduğunu,

Hala o kutsal asır nöbetinde durduğunu.

Biz sözümüzdeyiz, tembihledin ve gittin,

İyi adamlar iyi atlara binip gittiler demiştin.

Rahata eren ömrüm saltanat kayığı,

Boş kalan meydanlar zevk sefa aşığı.

Düşündüm, toprak uğruna yatanı,

Tekmile geldim fikrimin komutanı.

(Tüm Şehitlerimiz ve Üstad Necip Fazıl Kısakürek'' e) 

(25.09.2004  Tavşanlı)', 'Ben, bir günün kısa saat nöbetçisi, Sen, yorgun asırların nöbetçisi. Düşman dayanmaz akıl heybetine, Nöbet sıran geldi, kalk, asır nöbetine....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çetinkaya']::text[], 8.5, '{"poet":"Mehmet Çetinkaya","poet_slug":"mehmet-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asirlarin-nobetcisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisiniz Polis Ne Demek', 'bilirmisiniz-polis-ne-demek-mehmet-cetinkaya-c2c40', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her sabah vedalaşıp çıktığımda

Dönüşü olmayan hizmet yolunda

Başım dik alnım açık ufukda

Evimde bıraktığım öksüz benim

Bilirmisiniz polis ne demek

Bildiği tek şey insanı sevmek

Bende sevdim, hemde delicesine

Aşık oldum, sabahladım gecelerce

Dolaşamadım parkta bahçelerde

Evimde bıraktığım öksüz benim

Bilirmisiniz polis ne demek

Bildiği tek şey insanı sevmek

Sevdiğime bir gül alıp veremedim

Özlemezmiyim göz göze geleyim

Bayrağım, toprağım benim şerefim

Evimde bıraktığım öksüz benim

Bilirmisiniz polis ne demek

Bildiği tek şey insanı sevmek

Ben ülkem için çileye talibim 

Acıya kedere tad veren can benim

Bende babayım, bende anneyim

Evimde bıraktığım öksüz benim

Bilirmisiniz polis ne demek

Bildiği tek şey insanı sevmek

(10.04.2002 Tavşanlı)', 'Her sabah vedalaşıp çıktığımda Dönüşü olmayan hizmet yolunda Başım dik alnım açık ufukda Evimde bıraktığım öksüz benim Bilirmisiniz polis ne...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çetinkaya']::text[], 8.5, '{"poet":"Mehmet Çetinkaya","poet_slug":"mehmet-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bilirmisiniz-polis-ne-demek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuregimde', 'yuregimde-leyla-isik-rxhq8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bin kahırla geçiyor günlerim, senden uzakta

 Yokluğundur içimi kanatan...

 Yalnızlığın ortasında bitmez bekleyişlerim

 Sevmemen korkusudur

 Beni ağlatan.

 Seni düşünmemek, imkansız.

Doyumsuz duygulardı paylaşılan.

Gecelerde....

 Sevgin yüreğimin en gizli yerinde,

 Unutulmaz dakikalardı,seninle yaşanan.

 Bir ben miyim böyle yalnız? 

 Düşündün mü? 

 Gecelerde sende beni....

 Duygularım yenik düştü

 Şimdi kararsız

 Beni tekrar sever misin? 

 Döner misin geri? 

 Bitmez aşkının ateşi...

 Yüreğimde yanar,

 Seni yaşamak,

 Seni arzulamak..... gecelerde var.

 Dudaklarım dudaklarını anar,

 Kalemim seni yazar.

 Üzülme! 

 Yasak aşkımızı 

 Sakladım  yüreğimde...', 'Bin kahırla geçiyor günlerim, senden uzakta  Yokluğundur içimi kanatan...  Yalnızlığın ortasında bitmez bekleyişlerim  Sevmemen korkusudur  ...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yuregimde-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Düşüşler...', 'kayip-dususler-mehmet-asim-a9weg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimde ızdıraba kürek çeker

Her yeni gün, 

Gitmelerinin ölümcül suskunluğu.

Tüm çırpınmalarıma rağmen,

Bir türlü yol alamam oysa...

İçimde umudu  iteleyen, 

İhanetinin geritepişleri,

Beni alıkoyar,

Tüm sen yollarından.

Bütün yüklerimden kurtulmayı denerim,

Ki nekadar faydasız,

Her şeyi atarım bir bir üzerimden

Ne kadar yalın ve yanlızsam

O, kadar kurtulamamışımdır,

Yüreğimin sargısı sen yanlarımdan.

Bunca dağılmışlığıma,

Kırılmışlığıma rağmen,

Çözemem kendimi bir türlü.

Yinede elim varmaz,

Bunca zaman varlığından

Devşirdiğim

Kayıp suretimi ayaklar altına almaya.

Ah...Kundağından çıkarılmış bir bebek 

Gibiyim,

Hiç bir kucakta sabitlenemeden,

Bedenime büyük gelen

Kollardan kayıveriyorum

Okyanus diplerine.

Kulaç atmayı öğreniyorum ilkin.

Yinede hazır değilim

Ne hayata

Ne senli hatıralara...

Bende ihanetini ört pas eden

Çalıntı duruşlar arama

Ki ben nereden bileyim,

Kentlerin ayrılıklarla 

Yoğrulan ve tren raylarında

Kırılan küskün insan kalıplarını.

Sızabilirdim,

Yüreğin dehlizlerine oysa.

Gönlünde, 

Bİr ben kalıbı taşısaydın,

Akabilirdim, dolabilirdim

Sana tüm varlığımla.

Her şeye rağmen gidemezdin o zaman

Yada ben bilebilirdim

Yaşamsallıklar ortasında yol alabilmeyi.

Yanlış zamanlarda

Yanlış adımlarla

Tutamazdım elbette eteklerimden.

Ah...Kundağından çıkarılmış,

Bir bebek gibiyim şimdi ben.

Bir kuçağa değişim kadar dünyalık,

Okayanuslara düşüşüm kadar senlik...

Zeyneb Günay

14/03/05

İstanbul', 'İçimde ızdıraba kürek çeker Her yeni gün,  Gitmelerinin ölümcül suskunluğu. Tüm çırpınmalarıma rağmen, Bir türlü yol alamam oysa... İçimde u...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/kayip-dususler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümden Korkarsan Adam Değilsin', 'olumden-korkarsan-adam-degilsin-tayyip-sag-s634d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölmek için borçlu geldik Dünya''ya,

Çıksanda farketmez uzaya, aya,

Sonunda dikerler başına kaya,

Ölümden korkarsan adam değilsin..

Sırattan kurtuluş yolu arama,

Hesaptan kaçıpta kurtuldum sanma,

Belki de koşarak geçersin ama,

Ölümden korkarsan adam değilsin.

Bir ömrün sonudur davetsiz ölüm,

Ölürsen ses vermez gönül bülbülün,

Bahçende solarsa zambağın, gülün,

Ölümden korkarsan adam değilsin.

Cenneti serseler ayaklarına,

Huriler gelsede iki yanına,

Ab-ı hayat can katsa da canına,

Ölümden korkarsan adam değilsin.

Tayyip der Dünya''ya baki değilsin,

Ömrün değerini herkes ne bilsin,

Ağlayarak doğar, ağlar gidersin,

Ölümden korkarsan adam değilsin.

     18.02.2005', 'Ölmek için borçlu geldik Dünya''ya, Çıksanda farketmez uzaya, aya, Sonunda dikerler başına kaya, Ölümden korkarsan adam değilsin.. Sırattan k...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olumden-korkarsan-adam-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Yaşamak İçin Bir Neden Yaratın', 'bana-yasamak-i-cin-bir-neden-yaratin-nijat-ayvaz-hiycv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karabulutlar dağılsın artık

Işığa hasretim.

Güneş ısıtsın tenimi

Üzerimdeki bu kan lekeleri üşütüyor! 

Üşütüyor savaş sözcüğü bile titretiyor yüreğimi

Çocuk dünyamdan kaldırın

Kaldırın bu savaş oyuncaklarını

Yakın silah, tank, tüfek ne varsa

Oyuncak ayım yeter düşler kurmama

Bana anlatılmamış masallar anlatın

Hani içinde cinler, periler, devler, cüceler olanlardan

Sevgiden bahseden masallar olsun

Duymak istemiyorum güç, iktidar sözlerinin geçtiği masalları

Kiralık, asık suratlı, koca adamlar savaşmayın artık

Silahlarınızı önce kendinizi yok etmekte kullanın 

Kulanınki temizlensin dünyam sizlerden

Belki üzerinizdeki cehennem kefeni böylelikle yok olur

Yok etmek üzerine düşleriniz sizin

Benimse var etmek, sevmek, kucaklamak

Çiçeklerini soldurdunuz dünyamın

Bana yaşamak için bir neden yaratın artık

Yaratın artık yeniden içimdeki saf insanı

Silah yerine bir demet çocuk sunun geleceğe…..

Kiralık, asık suratlı, koca adamlar

Biliniz ki,  ben yarınlarda doğacak çocuğunuzum sizin

Çoktan unuttuğunuz,

Vicdan göz yaşlarınızda aynı zamanda….

Bana yaşamak için bir neden yaratın artık.

Yaratın 

Yaratın artık.', 'Karabulutlar dağılsın artık Işığa hasretim. Güneş ısıtsın tenimi Üzerimdeki bu kan lekeleri üşütüyor!  Üşütüyor savaş sözcüğü bile titretiyo...', ARRAY['Türk Edebiyatı','Şiir','Nijat Ayvaz']::text[], 8.5, '{"poet":"Nijat Ayvaz","poet_slug":"nijat-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bana-yasamak-icin-bir-neden-yaratin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Adını Söyle', 'bana-adini-soyle-ferit-yilmaz-w5fsq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kesik kesik bakma öyle,

Adın ne senin

Bu keskinliğin bu kızgınlığın kime

Kimsin sen ne olur bana adını söyle.

Öyle yapayalnız öyle serin

Duruş mu direnmek mi bu

Kim incitti seni,

Kim kırdı kim ağlattı seni.

Küçük kız küçüksü, 

Bir oluş seninkisi

Söylenecek ne varsa

Söylüyorsun gözlerinle

Sakın gitme buralardan

Biz sensiz olamayız

Zaten başıboşum biraz sarhoşum yine

Bizi terketme

Sende kalsın bu asil duruş...', 'Kesik kesik bakma öyle, Adın ne senin Bu keskinliğin bu kızgınlığın kime Kimsin sen ne olur bana adını söyle. Öyle yapayalnız öyle serin Dur...', ARRAY['Türk Edebiyatı','Şiir','Ferit Yılmaz']::text[], 8.5, '{"poet":"Ferit Yılmaz","poet_slug":"ferit-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bana-adini-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgin Sevgim Ustune', 'sevgin-sevgim-ustune-leyla-isik-o18dd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne seninle...

 Ne sensiz olamadim

 Sevgin ag ordu sevgim ustune

 Kalbimi dolduran ozleminle beraber

 Bitmez umarsizligim ellerimde.

 O,

 Gelmeni bekledigim gecelerde...

 Icimde bitip tukenmezdi duygularim.

 Umarsizligima isyan ederdi tutkularim.

 Ne yapsam...

 Ne etsem

 Dinmezdi icimdeki sizi

 Sevgindi...

 Sevgimdi...belki en yalansizi

 O,

 Sevmeni bekledigim gecelerde...

 Ne zaman sesini duysam

 Kalbim ozlem atesinde yanardi

 Ne zaman gozlerimi yumsam

 Hayalin gozkapaklarima taht kurardi...

 O,

 Sensiz kaldigim gecelerde...

 Sanki bitmeyen bir sarkiydi

 Kulaklarimda sesin

 Bir meltem ruzgarinin esintisiydi

 Yuzumde nefesin.

 Bir baska olumsuzlugu yasamakti seninle

 Sevgin

 Seni sevip,

 Seni isteyip,

 Seni arzulamakti

 O,

 Sabahlara dek agladigim gecelerde....

 Ne yana baksam

 Her yerde umarsizlik saltanati

 Kalmadi belki bende

 Sevginin o eski tadi.

 Inan! 

 Sende sevgim dort mevsimi yasadi

 O,

 Umutlarimi bagladigim gecelerde....

 Ne seninle,

 Ne sensiz olamadim

 Sevgin ag ordu,

 Sevgim ustune...', 'Ne seninle...  Ne sensiz olamadim  Sevgin ag ordu sevgim ustune  Kalbimi dolduran ozleminle beraber  Bitmez umarsizligim ellerimde.  O,  Gel...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sevgin-sevgim-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümdeki Yara', 'gonlumdeki-yara-huseyin-ucak-gqum1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçen onca yıldan sonra

Yine düştüm bu hallere

Sevmem diyordum oysa

Düşmem diyordum bir daha

Böyle bir sevdaya

Şimdi ise

Geldi buldu beni kerbela

Yine başladı kanamaya

Gönlümdeki yara

Hiç gülmeyecek galiba yüzüm

Hiç sönmeyecek yaram

Kaderim hiç gülmeyecek

Ne yapacağımı bilmiyorum

Bir kez daha dayana bilirmiyim

Bilmiyorum

Neden kaderim yüzüme gülmüyor

Anlamıyorum

Feryadım var dınyaya

İsyanım var kadere

Tanrım dayanma gücü ver

Bu aciz kuluna

Sana sığınmaktan başka

Çıkaryolu bulamıyorum', 'Geçen onca yıldan sonra Yine düştüm bu hallere Sevmem diyordum oysa Düşmem diyordum bir daha Böyle bir sevdaya Şimdi ise Geldi buldu beni ke...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Uçak']::text[], 8.5, '{"poet":"Hüseyin Uçak","poet_slug":"huseyin-ucak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gonlumdeki-yara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağız Tadı *', 'agiz-tadi-zafer-yazici-fd7ul', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlünüz, hiç istemese de

O, meçhule gitmeyi,

Ne kadar kaçırsa da 

Ağzınızın tadını,

______Her canlı, mutlaka,

_________Ölümü tadacaktır! ...', 'Gönlünüz, hiç istemese de O, meçhule gitmeyi, Ne kadar kaçırsa da  Ağzınızın tadını, ______Her canlı, mutlaka, _________Ölümü tadacaktır! .....', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/agiz-tadi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Zor', 'daha-zor-leyla-isik-0wzou', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni düşünmek...

 Seni istemek...

 Seni özlemek ne zor.

 Seni yaşamak bir başka kentte sensiz.

 Yüreğime saplanmış bir bıçak gibi anılar

 Ağlarım...

 Kirpiklerimde gün doğuncaya kadar.

 Her gece

 Gözlerin gelir aklıma

 Sözlerin gelir aklıma

 Hayalin odama dolar.

 Sabahı olmayan gecelerde,uyku tutmaz gözlerimi

 Fırtınalar kopar sanki yüreğimde

 Savurur beni o dev dalgalar

 Olurum yatağında...

 Ürkek ama dişi

 Sevişiriz gölgesinde korkunun

 Çok özlemişçesine uzun uzun..

 Zaman akıp gider avuclarımızdan

 Sana doyamamışlığım kalır bende.

 Bir hüzün çöker de içime

 Sabahı olmayan gecelerde

 Kahrolmak birşey değil canım,

 Seni yaşamak,bir başka kentte sensiz

 Daha zor', 'Seni düşünmek...  Seni istemek...  Seni özlemek ne zor.  Seni yaşamak bir başka kentte sensiz.  Yüreğime saplanmış bir bıçak gibi anılar  Ağ...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/daha-zor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Yazdım..', 'adini-yazdim-vedat-gungorur-1ks5v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzak bir sahildeyim yine yapayalnız.

Seni seyrediyorum dalgalarda 

Gülüyorsun......Ağlıyorsun

Acın oturuyor.yüzümdeki halkalarda

Boğucu sıcağın günü boyunca

Duyar gibi oluyorum seslenişini

Belki sende beni düşünüyorsun

Çizerken kumlara binlerce defa ismini

Sevenlerin kitabında ayrılık yok.demiştin

Ölümsüzlüğe sen inandırdın beni

Sevgisi yüceltir seveni.....demiştim.

Farketmez..

ne yaşamak..

ne de ölmek..sensizken

Çizerken kumlara binlerce defa ismini

vedat GÜNGÖRÜR  ([email protected])', 'Uzak bir sahildeyim yine yapayalnız. Seni seyrediyorum dalgalarda  Gülüyorsun......Ağlıyorsun Acın oturuyor.yüzümdeki halkalarda Boğucu sıca...', ARRAY['Türk Edebiyatı','Şiir','Vedat Güngörür']::text[], 8.5, '{"poet":"Vedat Güngörür","poet_slug":"vedat-gungorur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adini-yazdim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazide', 'mazide-leyla-isik-i3t6o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hala kulaklarimda yakan buselerini unutamadim

 Kapatsam gozlerimi,yeniden yasarim dun gibi

 Ayrildik ayrilali ozlem gozyaslarimi kurutamadim

 Kalbim sevemedi,sevemeyecek kimseleri

 Sorma...anlatamam yuregimdeki siziyi

 Icimde gunlerdir biriken arzuyu

 Eksik degil gozyaslarim bugulu gozlerimde

 Sevgini de hasreti de gomdum,simdi mazide.', 'Hala kulaklarimda yakan buselerini unutamadim  Kapatsam gozlerimi,yeniden yasarim dun gibi  Ayrildik ayrilali ozlem gozyaslarimi kurutamadim...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mazide-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçan da Kuşlara Malûm Olsun', 'ucan-da-kuslara-mal-m-olsun-nal-n-yildiz-0zof9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acil’de bir kadın gördüm

Hayatı acele soyunmuş belli

Ölümü çabucak giyinmiş...

Sanki eskiden tanıdığım birine benziyor,

Saçsız, göğüssüz kendine bile benzemeyen bir kadın…

DNA''mız uymayacak boşuna bakılmasın

Birbirimizi tanımıyoruz,

Nefesi benzemiyor,

Gözleri yabancı,

Çürüyen bir gül gibi kokuyor, 

O ufalıyor

Ben utanıyorum

Sesi? ...

Galiba sesi…

Ne zaman, nereden, duydum ki bu sesi? ...

İkimizin üstünde çiçekli elbiseler mi vardı ne...

Dizinin dibinde oturuyorum,

Kırmızı kurdelelerle kelebekler yapıyor

Satenden öpücüklerle saçlarımı tarıyor,

Ne anlatıyor ki içim ısınıyor? 

Bu kadın yani kendisine bile benzemeyen bu yaralı kadın

Niye benzesin ki o sesin sahibine? 

O kadın taze çiçek kokardı

Ve gözleri daima kiraz zamanıymış gibi bakardı…

Kanı çekilmiş yabancı bir kadın

Acil’de yatıyor şimdi,

Dalları içinde kuruduğundan

Damarları bulunamıyor…

Acil; Ecel’in etimolojik kafiyesi

O ölüyor ben inanmadığım bir Tanrı''ya dua ediyorum.

Acil’de bir kadın gördüm

Beni hiç tanımıyor.

Ben annemi isterim.

Ben annemi şimdiden çok özledim…', 'Acil’de bir kadın gördüm Hayatı acele soyunmuş belli Ölümü çabucak giyinmiş... Sanki eskiden tanıdığım birine benziyor, Saçsız, göğüssüz ken...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ucan-da-kuslara-malum-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarim', 'umutlarim-leyla-isik-0jr7d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yoksun simdi....

 martilar var issiz koylarda.

 batip cikar anilar,

 kopuren dalgalarda.

 dusunurken gecmisi gumus rengi sularda

 takildi kaldi gozlerim,

 cook cok uzaklarda.

 kagittan gemi gibi suzulurken hayalin,

 gomduler derinlere acimasiz dalgalar.

 kayboldu,

 buz gibi sularda umutlarim.

 yuregimde basladi 

 o dinmez kasirgalar...', 'Sen yoksun simdi....  martilar var issiz koylarda.  batip cikar anilar,  kopuren dalgalarda.  dusunurken gecmisi gumus rengi sularda  takild...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umutlarim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıklar yerine', 'ayriliklar-yerine-mikdat-bal-9ptz7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir araya gelerek

Kavgaya son vererek

Bu gün barışmak gerek

Tüm dünya hayran olsun

Günümüz bayram olsun

Ayrılıklar yerine

Ziyaret seyran olsun

Hoş görü anlayışla

Bir birini alkışla

Candan kucaklayışla

Sevgi cereyan olsun

Her taraf her yan olsun

Ayrılıklar yerine

Dost dostu saran olsun

Biriz birdir ülkemiz

Bir bayraktan gölgemiz

Bizim dir her bölgemiz

Dağ olsun kayran olsun

İsterse üryan olsun

Doğusuyla batısı

Tüm ülke bir yan olsun

Bu ülke hepimizin 

Olmasın bizim sizin 

Vermeyin buna izin

Gün gelir devran olur

Bizi ayıran olur

Barış, sulhu arayan

Rehberi Kur’an olur

Mikdat der barışalım

El ele verişelim

Hayırda yarışalım

Yoksa kandıran olur

Haneler viran olur

Birliği yok olanın

Lideri tiran olur', 'Bir araya gelerek Kavgaya son vererek Bu gün barışmak gerek Tüm dünya hayran olsun Günümüz bayram olsun Ayrılıklar yerine Ziyaret seyran ols...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ayriliklar-yerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çay Saati', 'cay-saati-mustafa-gokcek-bhkvr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ÇAY SAATİ

Deniz manzaralı cumbada

Oturmuşum, yoldaşımı karşıma alıp

Vakit gelmiş, ayarlanmış kösteklim on yediye

Demlenmişse içelim şu çayı saat beşte…

Mutluluğu getirdi umuduyla

Güzellikleri çağrıştırdı buğulu

Yüreğimin mutluluk pınarı

Bir yudumdan sonra, nice hatıralarla çoğaldı

Ne mutlu ki  bana, çıktım ve indim

Yaşadım yine umutla beklediğim yoldan

İndim, ama buruşan dilim

Demini tattı ve elbet içilmeli huzurla beş çayı…

13.03.05                                  M.Gökçek', 'ÇAY SAATİ Deniz manzaralı cumbada Oturmuşum, yoldaşımı karşıma alıp Vakit gelmiş, ayarlanmış kösteklim on yediye Demlenmişse içelim şu çayı ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökçek']::text[], 8.5, '{"poet":"Mustafa Gökçek","poet_slug":"mustafa-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cay-saati-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçtim', 'vazgectim-mustafa-gokcek-xitb1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'VAZGEÇTİM

Vazgeçtim, vazgeçtim onurumdan avunmaya değmez

İnsanlığından çıkmış emekçi üç kuruşa talim eder olmuş

Değil mi ki kötüler iyi, iyi kötü olmuş

Vazgeçtim böyle yaşamaktan el-etek öpmekten

O kız oğlan kız, dağlara kaldırılmış

Erdem, erdemsizliği yaratmış

Yüreğimde sakladığım bir kurşunmuş

Değil mi ki kan, kansızlığı peşkeşlemiş

Vazgeçtim bu dünyadan, dünyamdan



14.03.05                                 M.Gökçek', 'VAZGEÇTİM Vazgeçtim, vazgeçtim onurumdan avunmaya değmez İnsanlığından çıkmış emekçi üç kuruşa talim eder olmuş Değil mi ki kötüler iyi, iyi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökçek']::text[], 8.5, '{"poet":"Mustafa Gökçek","poet_slug":"mustafa-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/vazgectim-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm', 'omrum-yavuz-agir-n568p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir pınara benzer ömrüm.

Zamana çağlar gider ömrüm.

Ucu bucağı bilinmez; 

Deryalara akar,gider ömrüm.

Bir selviye benzer ömrüm

Göklere uzar gider ömrüm.

Ucuna,erişilmez; 

Adımı semaya yazar ömrüm...

Ömrüm ömrüm yalan ömrüm

Yaşamağa doymaz ömrüm

Tıpki bir kuş misalı,

Uçar,konar göçer ömrüm...

Geh çoşarım,geh ağlarım.

Zamanı ömrüme bağlarım.

Sineme yürek dağlarım.

Beyhude geçer bu ömrüm....', 'Bir pınara benzer ömrüm. Zamana çağlar gider ömrüm. Ucu bucağı bilinmez;  Deryalara akar,gider ömrüm. Bir selviye benzer ömrüm Göklere uzar ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/omrum-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılsama (Mavi Ada''ya)', 'yanilsama-mavi-ada-ya-baran-baransel-jhmnq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yanım hep eksik; 

Çakmaksız bir çıra,

Bir yarım elmayım sanki.

Ama; 

Kusur aşkta değil,

Adım gibi biliyorum,

Aşka ayak diremekte.

Bir elmanın iki yarısı olabilmekte değil

Canım benim,

Kendini bütün bir elma zannetmekte.

Yani Sen''de.', 'Bir yanım hep eksik;  Çakmaksız bir çıra, Bir yarım elmayım sanki. Ama;  Kusur aşkta değil, Adım gibi biliyorum, Aşka ayak diremekte. Bir el...', ARRAY['Türk Edebiyatı','Şiir','Baran Baransel']::text[], 8.5, '{"poet":"Baran Baransel","poet_slug":"baran-baransel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yanilsama-mavi-ada-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm senin olsun', 'omrum-senin-olsun-meryem-i-sler-yd1se', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben senin meleğin 

Sen benim bebeğim

Canımı senin için veririm

Benim güzel bebeğim

Pamuk ellerini

Minik gözlerini

Gül kokan tenini

Seviyorum her şeyini

Canımdan cansın

Kanımdan kansın

Ömrüm sana kalsın

Aşkım ğülbaharımsın

Benim en kıymetlimsin

İste annen canını versin

Gülüşün bir ömre bedel

ALLAHIM ömrüne ömür versin', 'Ben senin meleğin  Sen benim bebeğim Canımı senin için veririm Benim güzel bebeğim Pamuk ellerini Minik gözlerini Gül kokan tenini Seviyorum...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/omrum-senin-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Seviyorsun?', 'neden-seviyorsun-songul-ucar-649jf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni neden seviyorsun ki? 

Kara kaşlarım beyazlamayacak mı sanıyorsun? 

Ela gözlerimde ki pırıltı hiç sönmeyecek mi? 

Gençliğim ve güzelliğim hep bende mi kalacak? 

Saçlarım hep böyle gür ve siyah mı olacak? 

Her şey bu gün ki gibi mi kalacak sanıyorsun? 

Sen beni neden seviyorsun..? 

Beni neden seviyorsun ki? 

İçindeki heyecan hiç bitmeyecek mi sanıyorsun? 

Beni gördüğünde hep dizlerin mi titreyecek? 

İçinde bir şeyler eriyip yakacak mı yüreğini hep? 

Bir dokunuş ömre bedel mi olacak? 

Her zaman zevkin doruklarında mı gezeceğiz sanıyorsun? 

Sen beni neden seviyorsun..? 

Zaman harcamayacak mı duygularımızı? 

..ve tabi bedenlerimizi? 

Hep bu gün ki kadar genç ve tutkulu mu olacağız? 

Sevecek sevilecek ve mutluluk mu bulacağız? 

Hep bu kadar kararlı ve umutlu? 

Sevgiye susamış ve de aç mı olacağız? 

Sen beni neden seviyorsun..? 

... biliyor musun?', 'Beni neden seviyorsun ki?  Kara kaşlarım beyazlamayacak mı sanıyorsun?  Ela gözlerimde ki pırıltı hiç sönmeyecek mi?  Gençliğim ve güzelliği...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/neden-seviyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkmam Ben', 'korkmam-ben-necmiye-sarpkaya-oxc9y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korkmam ben kartaldan

kargadan korktuğum kadar

Korkmam ben arslandan

Çakaldan ürktüğüm kadar

Korkmam ben ondan

Bundan şundan

Kendimden korktuğum

Kadarrr

Korkmam ben ölümden

Baş eğmekten korktuğum

Esaretten ürktüğüm kadar

Korkmam ben ondan

Bundan şundan', 'Korkmam ben kartaldan kargadan korktuğum kadar Korkmam ben arslandan Çakaldan ürktüğüm kadar Korkmam ben ondan Bundan şundan Kendimden korkt...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/korkmam-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Bir Tarif', 'oylesine-bir-tarif-songul-ucar-sztnu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle sevdalı sözler

Ya da buruk özlemler

Yazmak gelmiyor içimden

Gerçekler ortada

Kadın erkek iki dünya

Birde evrensel çekim kanunu

Dönecek bir tanesi elbet

Kütlesi büyük olanın etrafında :))', 'Öyle sevdalı sözler Ya da buruk özlemler Yazmak gelmiyor içimden Gerçekler ortada Kadın erkek iki dünya Birde evrensel çekim kanunu Dönecek ...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/oylesine-bir-tarif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıladan Uzakta Çanakkale''de Ölmek! ...', 'siladan-uzakta-canakkale-de-olmek-nihat-malkoc-jrf3a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sular yandı,tutuştu ateşinden

Öksüz kaldı ayrılanlar eşinden

Tez uyandı Ehl-i Salib düşünden

Çok şükür kesildi hızı zalimin

Bilmem Anzaklar’ın burda işi ne? 

Takılmışlar İngiliz’in peşine

Zehir doğradılar Türk’ün aşına

Hileyle örülmüş özü zalimin

Tabyalardan ateşler yükseliyor

Hakk’a koşan ruhlar huzur buluyor

Anafartalar’da ölüm ölüyor

Erimeye mahkûm buzu zalimin

Semaya yükselir bir yanık seda

Bir yanımız vuslat,öbürü veda

Göğe merdiven dayadı şühedâ

Nura hasret kalsın gözü zalimin

Ezelde böyle takdir etmişse Hakk

Kuş tüyü yataktır bizlere toprak

Yüreğimiz kefenimiz kadar ak

Kara kışa dönsün güzü zalimin

Çanakkale nurdan ruhlar mahşeri

Hepsi bir kahraman subayı,eri

Değiştirmek mümkün müdür kaderi

Güven vermez asla bezi zalimin

Nefsim İbrahim’in közünde yansın

Şühedâ vuslatın hazzına kansın

Türk’e pusu kuran cihan utansın

Yokuşa dönüşsün düzü zalimin

Bir kızılca kıyamet Çanakkale

Yeryüzüyle sema gelmişti dile

Sonunda bülbüller kavuştu güle

Mikrop yuvasıdır tozu zalimin

Vatan oldu Çanakkale’de kanlar

Cennet-i Âlâ’ya göç etti canlar

Gökyüzünden  yankılansın ezanlar

Çıkmaz olsun hiç avazı zalimin

Leyla için savaşmalı çöl ile

Şehit kanatlanır nurdan yel ile

Resulüm karşılar onu gül ile

Hüsrana götürür izi zalimin

Duyanlar titresin sesini Türk’ün

Bütün dünya görsün hasını Türk’ün

Kimse attırmasın tasını Türk’ün

Derler ki kurudur tuzu zalimin

Sıladan uzakta ölmek zor anne

Yüreğimi yakan kızgın kor anne

Gayri bu rüyayı hayra yor anne

Cihanda gülmesin yüzü zalimin', 'Sular yandı,tutuştu ateşinden Öksüz kaldı ayrılanlar eşinden Tez uyandı Ehl-i Salib düşünden Çok şükür kesildi hızı zalimin Bilmem Anzaklar’...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/siladan-uzakta-canakkale-de-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ver hakkımı ayrılalım', 'ver-hakkimi-ayrilalim-mikdat-bal-7inwj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Param ile bir yer açtın

Sağa sola bol bol saçtın

Beni gördükçe hep kaçtın

Ver hakkımı ayrılalım

İşte budur kalan deme

Ortak bana yalan deme

Saygılı ol ulan deme

Ver hakkımı ayrılalım

Daha dün ağabey derken

Saygı hürmet bitmiş ergen

Düşman mı olduk isterken? 

Ver hakkımı ayrılalım

Koyma enayi yerine

Battıkca batma derine

Ortaklığın değeri ne? 

Ver hakkımı ayrılalım

Bağırmaksa senin huyun

Sana asla eğmem boyun

Değilim kurbanlık koyun

Ver hakkımı ayrılalım

Elimde var koca senet

Gel şu borcunu temin et

Adama getirtme cinnet

Ver hakkımı ayrılalım

Mikdat der başımdan geçti

Ortak dedik yedi içti

Fakat yanlış adam seçti

Ver hakkımı ayrılalım', 'Param ile bir yer açtın Sağa sola bol bol saçtın Beni gördükçe hep kaçtın Ver hakkımı ayrılalım İşte budur kalan deme Ortak bana yalan deme ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ver-hakkimi-ayrilalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kinaye I', 'kinaye-i-zeynep-nilgun-gokceoz-1oqzx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakmışsın dünya çok büyük,

Kalmışsın içinde damladan küçük,

Etrafın insanla dolu ama

Bulamamışsın bir tek dürüst.

Alışmışız acımadan yermeye,

Düşene bir de sen vur demeye,

Yargılamadan infaz etmeye,

Dilimiz dönmüş testereye.

Yoldaş demiş yollarına düşmüşsün,

Kardeşten öte düşünmüşsün,

Kahpelik nedir bilmemişsin,

En büyük kazığı ondan yemişsin.

Söyleyin dost bildiklerim,

Her zaman sözüne güvendiklerim,

Ayağım takılıp düşerken

Bir tekme de sizden yediklerim.

Kimseleri kırıp üzmek istemem,

Dertlerini görmezlikten gelemem,

Nasıl olsa benim değil diyemem,

İyilikten başkasını veremem.

Dünya yalan deseler de inanma,

Gerçeklerin en alası burada,

Kurtlar koyun olsa ne fayda,

İnsan bitmiş çoğu dönmüş mahluka.

Derdim dersin söylemeye kalkarsın,

Çare bulsun diye boşa umarsın,

Bir sillede ondan alıp katarsın,

Derde değil, bu kez ona yanarsın.

Suyum soğuk, suyum sıcak kime ne,

Alışmışım her haline bir kere,

Yağmur yağmış, dolu yağmış farkı ne,

Zaten dönmüşüz bir bilmeceye.

Demeyin bize uğramaz keder,

İnsanız ya bir gün bize de değer.

İyisi kötüsüne bin çeker,

Hesabını verecek kadar yürekliyseniz eğer.', 'Bakmışsın dünya çok büyük, Kalmışsın içinde damladan küçük, Etrafın insanla dolu ama Bulamamışsın bir tek dürüst. Alışmışız acımadan yermeye...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kinaye-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Yalnızlık', 'adi-yalnizlik-bulent-ahmet-alp-gfyrv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dönüp dolaşıp yalnızlığıma tekrar kavuşuyorum...

O benim belki de vazgeçilmezim...

Belki de korkularımdan sığındığım,

En kuytu sığınağım,limanım...

Her çaresizliğimde koştuğum yer...

Şimdi herşey neden beni ağlatmak için diretiyor? 

Karanlık dumanaltı bir odada,

Hangi eski hatıra ağlatabilir beni? 

Hangi penceredeki güleryüz beni güldürebilir...

Tüylerim diken diken...

Asla olmayacak bir hayal...

Ve hiçbirşeyin önemi kalmadı.

Hiç kendim olamadım,hiç ağlayamadığım gibi... 

Kendim gibi...Hiç sevemedim...

Sevilemedim de...

Sadece daima ağlamak vardı...

Yalnızlıktı adı....

Kimin aklında kalabildim? 

Kimin ardında? 

Hangi dağ ardında sevgili bekledi beni? 

Kim beni ölümden kurtardı? Kim öldürdü beni? 

Bakakaldılar ardımdan...

Oysa onlar benim içimdeydi...

Her zaman yalnız  olacağımı sandılar.

Asla anlamadılar.

Anlaşılmadılar...

Güneş boşlukta sandılar...

Oysa çevresine bakamadılar kendi önlerine bakmaktan...

Şanslı değildim hiç...

Sadece fani bir şair...

Asla ölümsüz olamadım...

Asla ölümsüz olamayacağım...

Ölüm zor,yaşamak gibi...

Yaşamak dediğin doğum ile ölüm arasındaki...

Her zaman yalnız kalacağımı sandılar...', 'Dönüp dolaşıp yalnızlığıma tekrar kavuşuyorum... O benim belki de vazgeçilmezim... Belki de korkularımdan sığındığım, En kuytu sığınağım,lim...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ahmet Alp']::text[], 8.5, '{"poet":"Bülent Ahmet Alp","poet_slug":"bulent-ahmet-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/adi-yalnizlik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kat Çıkmak / Çıkma Kat', 'kat-cikmak-cikma-kat-selim-bayrak-docok', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“Kat çıkmak yasak kardeşim”

Yahu bina dikmiyorum ya buraya

Altı üstü bedenim beş on metre daha yükselecek

Gökdelenlerden hiç hoşlanmam zaten

İşim de düşmez oraya

Burası kamuya açık yer değil mi

Hem kim dikti seni kapıya

“Kat çıkmak serbest beyefendi”

Vakit geçti Abbas efendi

Eve dönmem gerek

İnşaat ustası gelecek

Malum çoluk çocuk çoğaldı

Bir kat daha dikilecek

“Kaçak kat çıkmışsın efendi”

Zabıtalar yine döşendi

Fayansı eksik kalmıştı

Hanım yine öfkelendi

Ranta davetiye çıkarılmamış

Yıkım kararı geldi

Davet edilmemiz icap edince

Kamuya açık mahallere

Belediye kat açtıracak dokümanterlere

Hiç enterese etmeyecek aslında

Kat inip çıkmak betonarmelerde

Nerede kaldı o gençlik günleri

Kuru simit bayat çay iskele bahçeleri

Sorumluluğunun sallantılı bir şekilde taşıdığın

Rüzgar gülü zayıf ince bedenli olduğunu tasavvur edebildiğin

Düzlüğe ait zaman süreleri

Kat çıkmak yasak kardeşim 

İnmek serbestti de sanki

Dört tarafı açık mekana

Çıplak ayağında humuslu toprağın ıslaklığı

Başında rengarenk sonbahar yaprakları

Kışı geçirmek belki zor amma

Baharın ayak başparmağımdan kelime kadar 

İtelenmemiş ötelenmemiş

İnce bir sıcaklık veren tomurcuk açışları

27 Şubat 2001 - İstanbul', '“Kat çıkmak yasak kardeşim” Yahu bina dikmiyorum ya buraya Altı üstü bedenim beş on metre daha yükselecek Gökdelenlerden hiç hoşlanmam zaten...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/kat-cikmak-cikma-kat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-mehmet-sogut-ft95z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şeyimsin, gözlerin özüm

al beni seyreyle sevgilim

gökyüzünde sarkan mavilik

bunu bir sen, bir de ben bilirim

Aşkın yangın, yangınlara sürükler

sevda çiçeğim sen gülüm

sevdiğimsin her şeye bedel

al beni ne olur yüreğine sar.', 'Her şeyimsin, gözlerin özüm al beni seyreyle sevgilim gökyüzünde sarkan mavilik bunu bir sen, bir de ben bilirim Aşkın yangın, yangınlara sü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Söğüt']::text[], 8.5, '{"poet":"Mehmet Söğüt","poet_slug":"mehmet-sogut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sitem-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz atma halk türküleri', 'karadeniz-atma-halk-turkuleri-muhammet-yagcioglu-3gm05', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deniz üstü üzerim

Sarı lira düzerim

Babamın sağlığına

Nazlı nazlı gezerim.    1

Kiz içluğun varmidur

Giy bakayum darmidur

Elim sığacak kadar

Koynuna yer varmidur   2

Duman deredekari

Götürür portikali

Kiz koynunda ne vardur

Sade vurur yukari              3

Arkeri dal üstünde

Pembe yelek dokirum

Kaybana sevdaluğun

Mektebunda okurum            4

Merdivenim kırk ayak

Kırkına vurdum dayak

Yar kapudan geçerken

Ne el tutar ne ayak                 5

Gül biteyi biteyi

Biteyide iteyi

Dedi urumun kizi

Namus elden gideyi                 6

Armudu budakladum

Dallarını sakladum

Annesinin yanunda

Kızını kucakladum                        7

Armut budaklanurmu

Dallaru saklanurmu

Annesinin yanunda

Kız kucaklanurmu                          8

Sevdaluk ede ede

Yandı yürek yandu

Ben daha dayanamam da

Can boğaza dayandu                     9

İn dim dereye durdum

Peştamaluni buldum

Senin olduğunu bileydum

Bi kevi sarilurdum                             10', 'Deniz üstü üzerim Sarı lira düzerim Babamın sağlığına Nazlı nazlı gezerim.    1 Kiz içluğun varmidur Giy bakayum darmidur Elim sığacak kadar...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Yağcıoğlu']::text[], 8.5, '{"poet":"Muhammet Yağcıoğlu","poet_slug":"muhammet-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/karadeniz-atma-halk-turkuleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-nurten-altinok-mhppr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimsenin eli uzanamaz artık

Uzanamaz içimdeki sen*e

Taşa tuttuğum kör gecelerde

Sıcacığımsın

Canımsın

Kanımsın 

Sardım sarmaladım seni ben’e

İçimdeki sesimsin / atamam

Özlediğimsin / bırakamam

Gecikme

Kır zincirlerini yolların

Akgüvercinler gönderiyorum bak sana

Hadi; atla diye kanatlarına

Gel diye bana

Kimsenin eli uzanmasın

Dokunmasın içimdeki sana

İzin verme

Öyle güzelsin ki benimle..', 'Kimsenin eli uzanamaz artık Uzanamaz içimdeki sen*e Taşa tuttuğum kör gecelerde Sıcacığımsın Canımsın Kanımsın  Sardım sarmaladım seni ben’e...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gel-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-mahmut-bugrul-02d8d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sende benim gibi sevsen be güzel,

Sevgi ne güzel olurdu? bilsen ne güzel? 

Sende benim gözümle görsen be güzel,

Sevgiliye bakması bilsen ne güzel? 

             04.06.2004

                Gölbaşı', 'Sende benim gibi sevsen be güzel, Sevgi ne güzel olurdu? bilsen ne güzel?  Sende benim gözümle görsen be güzel, Sevgiliye bakması bilsen ne ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Buğrul']::text[], 8.5, '{"poet":"Mahmut Buğrul","poet_slug":"mahmut-bugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/guzel-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olamaz', 'olamaz-kadir-soyturk-wtc63', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakmasını bilen, görür gerçeği

Güneş hep meydanda, saklı olamaz! 

İslama  Kur''ana dil uzatanın

Ağzı varsa bile, aklı olamaz! 

Sam yelidir, yöremizde esenler; 

Hukuk deyip, Ömerlere küsenler

Kendi bulunduğu dalı kesenler,

Hakka ta''n edenler farklı olamaz!', 'Bakmasını bilen, görür gerçeği Güneş hep meydanda, saklı olamaz!  İslama  Kur''ana dil uzatanın Ağzı varsa bile, aklı olamaz!  Sam yelidir, y...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olamaz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını koyamadım yalnızlığımın', 'adini-koyamadim-yalnizligimin-arif-baltaci-audw5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Islak ve dar sokaklarda yaşardım yalnızlığı

Ve o zaman aklıma gelmezdi ağaracağı saçlarımın.

Babamı kaybettiğimde yaşamıştım ilk acımı 

Daha sonra ise seni sevdiğimde. 

Bilmezdim ki ayrılık acısının

Ölümün yansıması olacağını yüreğimde.

Ben umutlarıma ip bağlayıp salmıştım gökyüzüne 

Küçük bir uçurtmanın kuyruğunda sana gelmiştim.

Rüzgarsız havalara alışıktım ben 

Fırtınana yenildim...

Sen deli bir kısrak, ben isimsiz kahraman 

Nasıl da sevmişim seni anlayamadım.

Bir bir kaybettim güzelliklerini 

Gözlerime yaşlar doldu ağlayamadım.

Sevdalarımı isimsiz bir limana boşalttım

Ve uğruna döktüğüm göz yaşlarımdan 

Küçük küçük denizler yaptım... 

Kulak asmadım yalnızlığıma 

Kulak asmadım acılarıma

Ben hep seni gözyaşımda yaşattım...

Adını koyamadım yalnızlığımın 

Sevda dedim ben bu karamsarlığa

Hiç bestelenmeyecek şiirler yazdım sana

Hiç söylenmeyecek şarkılar yaptım.

Bir tarafını aldırdım kalbimin 

Bir tarafını sana bıraktım...

Mühürlenmiş gözlerimin dermanı sendin.

Her nereye baksam seni görürüm.

Gözlerin idam sehpası olmuş 

Hasretin çöreklenmiş bağrımın ortasında 

Çek git sevdiğim ne olacak sonunda

Ya beni öldürürsün, yada ölürüm

Issız sokaklarda sabaha karşı

Ezanlar yükseliyor minarelerden.

Yüzüm kabeye dönük, dilimde dualarım

Rabbimden seni istiyorum ben 

Öksüz bıraktığın yüreğime dön

Gel ey gönlümün mihrabı yeniden...

                                                        14.03.2005

                                                        Saat 22:35 

                                                        İSTANBUL', 'Islak ve dar sokaklarda yaşardım yalnızlığı Ve o zaman aklıma gelmezdi ağaracağı saçlarımın. Babamı kaybettiğimde yaşamıştım ilk acımı  Daha...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/adini-koyamadim-yalnizligimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz', 'caresiz-burhan-cetin-zblk7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'güneş yetmiyor günümü aydınlatmaya

güneşim lanetlenmiş okyanuslarda şimdi

yani orda boğulmuş

karanlıkta düştüm yalnızlığın pençesine

yalnızlığıma gözyaşları döküyorum durmadan

yalnızlığımı gözyaşlarım çürütebilir mi bu kiş? 

koynuma aldığım yaşama ölü toprağı serpilmiş

süpürüp rüzgara savurmalı diyorum

el atıyorum gayretle,

ellerim tutsak,ellerim kimliksiz

görüntüsü yok iç çekişlerimin

kameralar kareleri çekmeye aciz

soluksuz haykırıyorum

avazım boşlukta bitiyor

çığlıklar çare olabilir mi kurtuluşuma? 

çığlıklarıma çığ düşmüş,çığlıklarım çaresiz...', 'güneş yetmiyor günümü aydınlatmaya güneşim lanetlenmiş okyanuslarda şimdi yani orda boğulmuş karanlıkta düştüm yalnızlığın pençesine yalnızl...', ARRAY['Türk Edebiyatı','Şiir','Burhan Çetin']::text[], 8.5, '{"poet":"Burhan Çetin","poet_slug":"burhan-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/caresiz-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Lokantası', 'hayat-lokantasi-galip-kemali-gunay-110qn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Lodos uçurmuşsa 

Dumanını,isini

Yatmadan ikindilerine

Yerin Hayat Lokantası.

İki çorba,biri bana. 

Ban ekmeğini,

Yakana damlasın.

Eksikse tuzu merhaba de,

Serpileyim', 'Lodos uçurmuşsa  Dumanını,isini Yatmadan ikindilerine Yerin Hayat Lokantası. İki çorba,biri bana.  Ban ekmeğini, Yakana damlasın. Eksikse tu...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayat-lokantasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor', 'zor-zeynep-nilgun-gokceoz-s9say', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanı anlamak kadar

Zor bir şey varmıdır,

İnanın yıldızları tutmaktan 

Daha uzaktır.

Gördüğüm zaman birini,

Düşünüyorum acaba

Bir dost yüzümü,

Hiç görmediğim çiçek mi,

Duymadığım şarkımı,

Bir türlü bulamıyorum,

İsmini koymaya korkuyorum.

Biraz önce bir çocuktu,

Daha sonra öfke oldu,

Akşam gördüm tanıyamadım,

İpekten bile yumuşak kaldı.

Sevgiyle bahçeler sürdüm,

Vefayla ağaçlar diktim,

Sefasını süreyim derken,

Cefayla tümünü kökünden söktüm.', 'İnsanı anlamak kadar Zor bir şey varmıdır, İnanın yıldızları tutmaktan  Daha uzaktır. Gördüğüm zaman birini, Düşünüyorum acaba Bir dost yüzü...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zor-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahpusluğum', 'mahpuslugum-aysun-erat-4mm54', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç düşmedim mahpuslara,

Doğrusu bilmem,

Gökyüzüne hasret kalmak, ne demek? 

Benim mahpusluğum senden ibaret.

Gökyüzüm de sensin sonra! 

Biraz uzaklaşsan benden,

Zincirlerim ağır gelir, taşıyamam.

Daracık bir hücrede, nefes alamam.

Gökyüzünü özlerim hemen.

Gözleri keskin martıları,

Kıskanırım deli gibi.

03/2005', 'Hiç düşmedim mahpuslara, Doğrusu bilmem, Gökyüzüne hasret kalmak, ne demek?  Benim mahpusluğum senden ibaret. Gökyüzüm de sensin sonra!  Bir...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mahpuslugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumar', 'kumar-baykal-kaanalp-9fsvf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anlatamam izin günlerimi

kumar mikrobuyla,nasıl öksürdüğümü

önce bir parça izin

ardından birkaç kuruş kopardım mı? 

gel keyfim gel

benim için tatlı stresli dakikalar

birbirini kovalar

bu beni mutlu eder mi? bilemem

önce damarlarımdaki kan

çekilir,nereye gider

hiç bilmem

sonra çılgınca düşler

beynimi tırmalar

kaçıp giden onca oyun

aklımı kurcalar

ha şimdi,ha birazdan

izinde biter,parada

korkunç bir baş ağrısı

boş bir cüzdan

beni kovalar

geceler sabah olmaz

uykular beni bulmaz

ama hep umudum vardır

onu kaybetmem asla

çekiciliğini hiç yitirmez

sigara dumanı

küllükler,izmaritler

sanki bir gıda

akşamdan kalmış

kançanağı gözlerime', 'anlatamam izin günlerimi kumar mikrobuyla,nasıl öksürdüğümü önce bir parça izin ardından birkaç kuruş kopardım mı?  gel keyfim gel benim içi...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kumar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bomboş', 'bombos-baykal-kaanalp-dx9sx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'boşa gider ağıt

gözyaşları silinmeli

fark edemeyiz asla

boşluk boşluktur

doldurmak imkansız

zamanlar mekansız

akşamlar kansız

yıldırım hızıyla

yanımdan akar

bulaştığımız bütün küller

bize ait,sorma

temizlemeli ama

küf kokulu bayat

tasmalar gergin

çıkmaz sevgin

denizler engin

her doldurduğum tas

aslında bomboş

aslında sevgimde yalan

kapıldığımı söylediğim

peşinden koştuğum

durum vahim

ayrıntılar çok gizli

karalar beyaz izli

neşe şen şakrak,sizli bizli

durulmalı bu sözcükler

çamaşır makinası solgun

kurgular eksik

yetersiz imkanlar

yazılanlar anlamsız

gülücükler çapalı

koridorlar karanlık

aşklar boş,anlık

sana yanık bu samanlık

ilişkiler yetersiz

gemiler mi? onlar kayıp', 'boşa gider ağıt gözyaşları silinmeli fark edemeyiz asla boşluk boşluktur doldurmak imkansız zamanlar mekansız akşamlar kansız yıldırım hızıy...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bombos-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bİr şEy mi? yaptık,bİr hata mı?', 'bi-r-sey-mi-yaptik-bi-r-hata-mi-baykal-kaanalp-p6ugo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'düşmanca bakışlar arasındaki gülüşmelerimiz

değişmeyen birbirine yabancı seçkinliğimiz

aralarda beraber çışlarımız,kolkola

niye hala anlaşılmaz bu çabalar

niye hala çirkin bu görüntü

bir şey mi? yaptık bir hata mı? 

tutunabilmek için yarınımıza

aldığımız bütün kötü

duyumlardan sonra

çıkardığımız sonuçlar

kendi çapımızda bizi aşmışken

bir şey mi? yaptık bir hata mı? 

aldattığımız herbir yemiş tanesi

yaksın içimizi,boşa yenmiş

onca adet içinde kalan

bir goncagül,değilse ki

kopardığımı9z kendi halinden

bir şey mi? yaptık bir hata mı? 

kopan kuyruğun yerine

yenisi gelmiş,daha sağlıklı

yeni bir bakış,yeni bir heyecan

çekilmişken geri kınına kılıçlar

küflenmişse yeni yerinde aşkımız

bir şey mi? yaptık bir hata mı?', 'düşmanca bakışlar arasındaki gülüşmelerimiz değişmeyen birbirine yabancı seçkinliğimiz aralarda beraber çışlarımız,kolkola niye hala anlaşıl...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-sey-mi-yaptik-bir-hata-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğreti', 'ogreti-ahmet-volkan-2hboi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geri de gelirim desem, yalan

Doydum artık, anlıyor musun? 

Kırık kalemlerinle yazdığın

Süslü infazlarına da

Ömür törpüsü açık yalanlarına da,

Bu kahrolası şehrin soğuk çarklarına da,

Sana da, 

Ve aşkına da doydum! 

Sen sen olacaktın ki içimde

Geldiğimde sevecektim seni! 

Hasretinle kavrulup

Ruhunla yandığım günler,

Hüzünlü sesini melodilerde,

Ve kalpsiz notalarda 

Aşk’ı duyduğum saatler,

Sensiz ve kimsesizken

Seni öyle büyüttüm ki içimde,

Ve öyle sevdim ki hasretini

Çıkma artık karşıma! 

Ben Aşk’ı şimdi öğrendim! 

(2004 - Viyana)', 'Geri de gelirim desem, yalan Doydum artık, anlıyor musun?  Kırık kalemlerinle yazdığın Süslü infazlarına da Ömür törpüsü açık yalanlarına da...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Volkan']::text[], 8.5, '{"poet":"Ahmet Volkan","poet_slug":"ahmet-volkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ogreti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dava', 'dava-ahmet-volkan-epytf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cansız düşerken bedenim toprağa

Binlerce parça olurum savrularak

Bulutlarda hasretim doğar,

Çimenlerde emeklerim.

Anılarımı denizlerden toplarsın

Vasiyetimi mazlumlardan

Ve tenimi yağmurlardan koklarsın ancak.

O an mahkemeyi kurar şehrim

Cinnetim seni tutuklar.

Hayallerin Avukatın olur,

Davacın gencliğim.

Askım yargıç koltuğunda

Ve kalemi öfkem kırar.

Ardından sensizlik gelir

Seni ipe veren ta kendidir.

Yine de kaybedecek olursam davamı

Gözyaşların şahidimdir! 

(2004 - Viyana)', 'Cansız düşerken bedenim toprağa Binlerce parça olurum savrularak Bulutlarda hasretim doğar, Çimenlerde emeklerim. Anılarımı denizlerden topl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Volkan']::text[], 8.5, '{"poet":"Ahmet Volkan","poet_slug":"ahmet-volkan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dava-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldim Sonunda - Mehmet Fatih''e...', 'geldim-sonunda-mehmet-fatih-e-ahmet-volkan-e65e4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlık yüzlerden geldim sana..

Yorgun mekanlardan, sarhoş umutlardan

Bak, siyah güllerimi getirdim

İhanet güllerimi

Mekanların sancısı, burnumda hala.

Tomurcuk kinlerimden geldim sana..

Çetrefil soğuklardan, hain bakışlardan

İşte madalyonum,

İki yüzüme de bak diye geldim! 

Yangın başımı koyamadan omuzuna.

Gecikmiş pişmanlıklardan geldim sana..

Sair sebepten, ağır bedellerden

Kovulmuş aşkını getirdim

Tükenmiş nefesini

Binbir özrüm basucunda.

Kan çanağı gözlerimi getirdim sana..

Taş kalbimden, yabani nefsimden

Suçluluk duygumu getirdim

Haksız nefretimi

Hayallerim seninleydi oysa.

Kötürüm kalbimden geldim sana..

Doğum gününde, ölüm yıldönümünde

Kesik ve soğuk bileklerini getirdim

İntihar namelerini

İki damla yaş ve bir gül bıraktım mezarına...

(Mehmet Fatih''e ve O''nun ''Mekanı cennet olası''......''na)', 'Karanlık yüzlerden geldim sana.. Yorgun mekanlardan, sarhoş umutlardan Bak, siyah güllerimi getirdim İhanet güllerimi Mekanların sancısı, bu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Volkan']::text[], 8.5, '{"poet":"Ahmet Volkan","poet_slug":"ahmet-volkan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/geldim-sonunda-mehmet-fatih-e-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Didar...', 'didar-i-brahim-ethem-bingul-kzslo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hazan sonrasında bahara geldim

Çiçek açtı aşkım bahar içinde

Mutluluktan azap kabını deldim

Neler duymadım ki o an içinde...

Bakışım parlıyor, yüzüm gülüyor

Açıyor güllerim, bin har içinde

Her zerrem onunla aşka yürüyor

Ağlar kıskananlar bak zâr içinde...

Hasret köprüsünden vuslata geçtim

Varlığım eridi didar içinde

Sevgili elinden muhabbet içtim

Yar ile buluştum ağyâr içinde...

Aşk acısı göstermesin Allah''ım

En büyük kayıp o zarar içinde

Aşk acısı hiç gelmesin Allah''ım

Hiçbir yerde, hiçbir diyar içinde...', 'Hazan sonrasında bahara geldim Çiçek açtı aşkım bahar içinde Mutluluktan azap kabını deldim Neler duymadım ki o an içinde... Bakışım parlıyo...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/didar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '30 Şubat Nikahı', '30-subat-nikahi-adulera-ayza-hhhdu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimseyi suçlamıyorum seni de

Kendimi de

Sana göre bitişimiz kader

Bana göre her an keder

Görüş farklılığı diyelim gelir geçer

Meyhane hesabı yapalım

En fazla meyhaneyeci ye benim 

Üç kuruşum fazladan geçer

Öyle bakma bana zaten her bakışın

Deler geçer

Hesapta yanlışlık var kesin

Hayatımı ben

Meyhanede çürütürken

Sen nerdesin

Eski limanda olmadığından eminim

Uzlaşalım  seninle

Her şeyi itiraf edelim bu gece

Rokçılar ın pop

Arabeskçilerin rock

Televizyonlar da  top 

Yaşam felsefesi nerde zor ise bırak

Olduğu bir ülkede

Benden ne istiyorsun

Ben meyhaneyi de senide sevdim

Haberin yok gülüm ikinizle de

Otuz şubat n i k a h ı y la evlendim', 'Kimseyi suçlamıyorum seni de Kendimi de Sana göre bitişimiz kader Bana göre her an keder Görüş farklılığı diyelim gelir geçer Meyhane hesabı...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/30-subat-nikahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçirgen Aşklar', 'gecirgen-asklar-ahmet-aksoy-jjmed', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir devrimin sırrını saklar gibi

gözyaşları kesilirken 

………..kendini kıran ayna

kaç ulus eskir özgürlük için

…………için yazgısıyla

kaldırımüstlerinde fısıldıyor 

………………yollar

yollar ve ağaçlar

açılan tabut sesleri

düş ardına düşürmüş zamanlar

bir devrimin sırrını taşır gibi

……..taşıdık birbirimizi

kah ben senin 

……kah sen benim sırtımda

devrildik sulara

umut şimdi; elimizde son ayna!', 'bir devrimin sırrını saklar gibi gözyaşları kesilirken  ………..kendini kıran ayna kaç ulus eskir özgürlük için …………için yazgısıyla kaldırımüst...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecirgen-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İronik Teşbih VI', 'i-ronik-tesbih-vi-ahmet-aksoy-nlh2d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zamanı çağlarla ölçen melekler gibi

……..tüketiyoruz yavaşlıklarımızı

neden en çok 

…ölüler sever Tanrı’yı', 'zamanı çağlarla ölçen melekler gibi ……..tüketiyoruz yavaşlıklarımızı neden en çok  …ölüler sever Tanrı’yı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ironik-tesbih-vi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borsa', 'borsa-galip-kemali-gunay-0b9k3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir sen bilirsin,

Söyle.

Borsası mı var gönlün.

Bedelsiz paylar hababam dinleyene

Ağlaşırken biz, kedi yükü sermayeye.', 'Şiir sen bilirsin, Söyle. Borsası mı var gönlün. Bedelsiz paylar hababam dinleyene Ağlaşırken biz, kedi yükü sermayeye....', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/borsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavide Kal...', 'mavide-kal-birsen-ates-yoaap', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mavide kal, 

enginlerde, 

özgür kal / ruhun gibi... 

mavi 

huzurun adresi 

hep mavide kal 

benim için 

yaşam mavi 

neşe mavi 

hüzün mavi 

ölüm mavi 

gözlerin mavi 

mavi de kal 

ruhum gibi 

özgür kal 

sen gidince 

kayboldum 

ruhunda geziniyor 

yüreğim 

sonsuz maviliklerdeyim 

çoktan gitmiştin 

sonsuzluğa 

mavide kal 

sonsuz mavi de', 'mavide kal,  enginlerde,  özgür kal / ruhun gibi...  mavi  huzurun adresi  hep mavide kal  benim için  yaşam mavi  neşe mavi  hüzün mavi  öl...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mavide-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Uykular', 'i-yi-uykular-muhsine-i-pek-vwss9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzunsa gece 

Kısaysa  günler

Bir de anılar toplanıp nöbet tutuyorsa başında

Geceler çekilmez

Sabahlar olmak bilmez

Yengeç kıskacı gibi yüreğini sıkarlar

Ne yıldızları saydırırlar

Ne de mehtabın gizemin gösterirler

Nöbeti biri bırakır biri alır

En iyisi mi sen

Pencereni gecenin karanlığına açıp

Bütün anılarını azad  et

Yoksa çekilmez bu hayat

Bitmez bu geceler

Uzunsa geceler

Kısaysa günler

Sakın nöbetçi bırakma başında

İnan sabahlar olmaz

Güneşi göremeyeceğini sanırsın

Sakın çağırma

Onlar mazide kalsın

Sen yıldızları say

Mehtabın gümüş gümüş aktığını izle

Artık rahat uyuyabilirsin

İyi uykular', 'Uzunsa gece  Kısaysa  günler Bir de anılar toplanıp nöbet tutuyorsa başında Geceler çekilmez Sabahlar olmak bilmez Yengeç kıskacı gibi yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Muhsine İpek']::text[], 8.5, '{"poet":"Muhsine İpek","poet_slug":"muhsine-i-pek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/iyi-uykular-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Dalı', 'bahar-dali-bulent-kalayci-txiiz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bahar dalı gibidir ömür

Dökülür mor çiçekler teker teker

Bir rüzğar eserse

Çiçeklerin uçlarında tomurcuklar

Tek tek yalnız garip

Bir başına kalır

Meyvadır gelecek çiçek uçunda

Gökten insede melekler

Nazlıdır', 'Bir bahar dalı gibidir ömür Dökülür mor çiçekler teker teker Bir rüzğar eserse Çiçeklerin uçlarında tomurcuklar Tek tek yalnız garip Bir baş...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kalaycı']::text[], 8.5, '{"poet":"Bülent Kalaycı","poet_slug":"bulent-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bahar-dali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Mektubu', 'ask-mektubu-bulent-kalayci-gc1fl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üsküdar''da

Güneşin battığı yerde

Alev alev yanan camda

Seni görürüm

Kız kulesine yaslanıp

Tüttürdüğüm

Sigara dumanına

Adını yazarım

Yedikule zindanlarında

Sabahın ilk ışıklarında

Duvarlara

Adını kazırım

Bir ipin ucunda

Yafta boynumda

Son sözün dediklerinde

Yağlı urganda,

Tutturduğum türküde

Seni yakarım', 'Üsküdar''da Güneşin battığı yerde Alev alev yanan camda Seni görürüm Kız kulesine yaslanıp Tüttürdüğüm Sigara dumanına Adını yazarım Yedikule...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kalaycı']::text[], 8.5, '{"poet":"Bülent Kalaycı","poet_slug":"bulent-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-mektubu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek', 'seni-dusunmek-meral-vurgun-kl3hb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'en yoksun günlerimde en az olanım sen

şimdi gül kokan telleri ucunda bıyıklarının 

sakla dokunmamış izini dudaklarımın

şimdi şakaklarına düşen kırağlarda üşüt ellerimi

nefesime uzakken omuzbaşın

boynunu sonbahar rüzgârları okşasın 

gün olur sağ kalır da gelirsem eğer

ve seni o dağlarında bulursam yurdumun

dilimde fazla söz olmayacak

bir çift kahve karası göz 

bakarken ben yüzüne

yarım kalmış bir türküyü tamamlayacak gece

ayışığı serince inerken sulara

dalında çağla nazlı nazlı yeşillenirken

söğüt dalları okşarken ayaklarımız altında toprağı

ilk yaz sarmaşıkları gibi sarılınca kollarımız

biz seninle sabaha kadar susacağız 

seni yazları gibi düşünüyorum ülkemin

sıcak Temmuz günlerinin serin geceleri gibi

ve açlık grevlerinde dilime sürdüğüm 

tuz tadında öpüşlerini düşlüyorum

seni baharları gibi düşünüyorum ülkemin

ve ilk cemresi gibi

menekşe rengi düşler düşüyor serime

seni hasat zamanı, bereketli topraklar gibi

seni kış mevsimi

içimi ısıtan zemheri güneşi düşlüyorum

seni canım, candaşım gibi

seni halkım, sınıf kardeşlerim

yoldaşlarım gibi düşünüyorum

büyüdükçe büyüyor sürgün

ve büyüyorsun sen...

Anlarıma düşenlerden...', 'en yoksun günlerimde en az olanım sen şimdi gül kokan telleri ucunda bıyıklarının  sakla dokunmamış izini dudaklarımın şimdi şakaklarına düş...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/seni-dusunmek-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzde doksan', 'yuzde-doksan-mikdat-bal-4u20k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok gezdim dolaşdım dünya sathında

Kendime dönmeye yol bulamadım

Çok günah işledim  bu hayatımda

Nefsine mukayet kul olamadım

Uyanığım sandım uyudum gezdim

Günah ben işledim şeytana kızım

Nefsime zulmettim herkesi üzdüm

Ben bir diken oldum gül olamadım

Zararla ulaştım dünden bu güne

Utanırım dönüp bakınca düne

Günahı işledim günah üstüne

Sevaplardan yana bol olamadım

Ettiklerime çok pişmanın şimdi

Öyle ağır bir yük sırtıma bindi

Gözyaşımın  çoğu dünya içindi

Damlaya damlaya göl olamadım 

Mikdat der Rabbime ayandır halim

Yüzde doksan dokuz benim misalim

Kendimden kaçardım olsa mecalim

Kendimi atacak çöl bulamadım.', 'Çok gezdim dolaşdım dünya sathında Kendime dönmeye yol bulamadım Çok günah işledim  bu hayatımda Nefsine mukayet kul olamadım Uyanığım sandı...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yuzde-doksan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simdi Yok Olma Zamanidir...', 'simdi-yok-olma-zamanidir-evina-berfin-7k1dc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bilinmezlik 

bilinenle ne yoldas

ince bir cizgi

bicak sirtinda 

col yorgunu

yol bitmiyor 

yurekler tukeniste 

susadim.. 

yok

deme haaa

yasaklandi 

yasak 

tum yanginlara susamislik

yan simdi 

yan... yan ki 

en yakan hasretinle

en acisindan

kutsal sevdanda...

ve

simdi...

yok olma zamanidir....

dil tukendi 

yurek vurmuyor..

soluklar buza kesti

bedenler sustu

sus.. 

sus bilmez dilim 

duymaz yuregim 

sus....

kirma dinginligini 

yok olusun ugultusu kalir

kahrolasi beynimde...

sesler... 

umudun catirtisi 

en sesli sessizliklerde

yitisler

varolmanin inkari

yoksa

var olmak midir

yitislerin yok oldugu

ah

o ince cizgi

o bicak sirti

ve 

simdi

yok olma zamanidir 

vakit gec 

birak da kivrilayim

bir yumak ki

yanarda yanar...

yuregime sarmalasam

yok olusumu

ve 

uyusam

en olumune uykuyu...

ve simdi 

.........................................

15/03/2005

0543 hrs', 'bilinmezlik  bilinenle ne yoldas ince bir cizgi bicak sirtinda  col yorgunu yol bitmiyor  yurekler tukeniste  susadim..  yok deme haaa yasak...', ARRAY['Türk Edebiyatı','Şiir','Evina Berfin']::text[], 8.5, '{"poet":"Evina Berfin","poet_slug":"evina-berfin","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/simdi-yok-olma-zamanidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Af Dilemeli', 'af-dilemeli-hamza-mamas-mljvq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dolaştım bunca dem senin peşinde; 

Dolaştım dolaştım artık yoruldum.

Maharet sandım billur simaları,

Makbere gömülürken şaştım da kaldım.

Kışlar yaşadım, baharlar gördüm; 

Mevsimler sayarak geçti bu ömrüm.

Güzellerde ölürmüş gözümle gördüm,

Ölümü yaşadım inan hak bildim.

Metanın üstünde bir varlık varmış,

Onun yeri ne hanlar; nede saraymış,

Azrail ile kanatlanırmış,

Sırça saraylarda mevtalar gördüm.

Savaşanlar gördüm metalar için,

Af unutulmuş hatalar için,

Dualar kesilmiş mevtalar için,

Türbesi isimsiz ölüler gördüm.

Sanmayın sinemde koca bir his var,

Bende her dem büyüyen bir yeis var.

Hesap ağır, makber yakın ne eylemeli? 

Gün be gün tövbe ile af dilemeli…

05/03/2005         hamza mamaş-kağıthane', 'Dolaştım bunca dem senin peşinde;  Dolaştım dolaştım artık yoruldum. Maharet sandım billur simaları, Makbere gömülürken şaştım da kaldım. Kı...', ARRAY['Türk Edebiyatı','Şiir','Hamza Mamaş']::text[], 8.5, '{"poet":"Hamza Mamaş","poet_slug":"hamza-mamas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ey-canlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayacaksın', 'olmayacaksin-hamza-mamas-ve82c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen olmayacaksın belki yanımda,

Elbette üzüleceğim…

Sere serpe serserice dolaşacağı sokaklarda,

Sen olmayacaksın yanımda…

Yokluğunda hayata küseceğim,

Umurum da olmayacak yangınlar,

Sinemdeki alevlere yenileceğim.

Sen olmayacaksın yanımda.

Devam…

İşte öylesine devam eden,

Yaşam denmeyecek bir hayat süreceğim.

Sen olmayacaksın yanımda.

Sensiz dalacağım ufku süzerken,

Hayallerin en acımasızına.

Sensizliğin ölüm diyeceğim adına,

Sen olmayacaksın yanımda.

 H.MAMAŞ                    13/03/2005-İstanbul', 'Sen olmayacaksın belki yanımda, Elbette üzüleceğim… Sere serpe serserice dolaşacağı sokaklarda, Sen olmayacaksın yanımda… Yokluğunda hayata ...', ARRAY['Türk Edebiyatı','Şiir','Hamza Mamaş']::text[], 8.5, '{"poet":"Hamza Mamaş","poet_slug":"hamza-mamas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olmayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehitlerim', 'sehitlerim-sahin-erturk-8yopx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çanakkale,Sakarya da

Dumlupınar,İnönü de

Canlarıyla tarih yazan

Şehitlerim,şehitlerim

Doğulu su,Batılı sı

Kütahya lı,Afyon lusu

Vatan için toprak olan

Şehitlerim,şehitlerim

Hasan çavuş,Şekip bey le

Fatma bacı,Ayşe teyze

Kanlarıyla destan yazdı

Şehitlerim,şehitlerim

Her karışta kanları var

Alevisi,Sünnisi var

Vatan için şurda yatan

Şehitlerim,şehitlerim

Kent li için,Köylü için

Senin için,benim için

Vatan için burda yatan

Şehitlerim,şehitlerim

Şehitleri anlatmaya

Kelimeler yetmez oldu

Mekanları CENNET olan

Şehitlerim,şehitlerim

(Kütahya/Dumlupınar Şehitliğinde yazılmıştır) 

KARABORSA SEVGİ adlı

5.nci şiir kitabımdan', 'Çanakkale,Sakarya da Dumlupınar,İnönü de Canlarıyla tarih yazan Şehitlerim,şehitlerim Doğulu su,Batılı sı Kütahya lı,Afyon lusu Vatan için t...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sehitlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madenciyiz', 'madenciyiz-sahin-erturk-hi682', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tunçbilek te,Soma da

Seyitömer,Milas ta

Alınteri,akıtan

Madenciyiz,madenci

Elbistan da,Afşin de

Hisarcık ta,Kırka da

Kazma,kürek çalışan

Madenciyiz,madenci

Yağdan,kirden yılmadık

Kardan,kıştan korkmadık

Üç vardiya ürettik

Madenciyiz,madenci

Kömür demek biz demek

Bakır demek biz demek

Gümüş demek biz demek

Madenciyiz,madenci

Yer altında ev tuttuk

Kazmalarla dağ yuttuk

Farelerle dost olduk

Madenciyiz,madenci

Kayabaşı,düzgün le

Eşiyok,Bölükbaşı

Başkanlardan birkacı

Madenciyiz,madenci

Gurbet eli yurt tuttuk

Zarar değil kar ettik

Gönüllerde yer bulduk

Madenciyiz,madenci

Her görüşe aşığız

Çalışmaktır arzumuz

Türkiyedir sevdamız

Madenciyiz,madenci

Akıyor alnımızdan

Emeğin temiz teri

Haram lokma yemeyen

Madenciyiz,madenci

Kelimeler yetersiz

Madenciyi yazmaya

İşimizin ehliyiz

Madenciyiz,MADENCİ

(Ekim-Kasım-2004 Madenci Dergisi) 

KARABORSA SEVGİ adlı

5.nci şiir kitabımdan', 'Tunçbilek te,Soma da Seyitömer,Milas ta Alınteri,akıtan Madenciyiz,madenci Elbistan da,Afşin de Hisarcık ta,Kırka da Kazma,kürek çalışan Mad...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/madenciyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Gibisin Sevdiğim', 'siir-gibisin-sevdigim-huseyin-erdogan-e2ulp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'neden beni

hiç arayıp sormuyorsun? 

oysa seni

çılgınca

sevdiğimi biliyorsun

bir gün uyanınca

bu şehrin sokaklarında

göremezsen beni

sakın benim için

yorma 

o güzel gözlerini

kainatın

en güzel

kadınısın sen

hem de

en çok sevilen

ne de şanslı

bir şairim ben

inan ki

şiir gibisin sevdiğim

sen benim şiirlerimsin

ben de

yalnızca senin şairin

bil ki

bir tek sana yazacağım

hem de ölünceye değin

                  15.03.2005', 'neden beni hiç arayıp sormuyorsun?  oysa seni çılgınca sevdiğimi biliyorsun bir gün uyanınca bu şehrin sokaklarında göremezsen beni sakın be...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/siir-gibisin-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Olmak', 'asik-olmak-abdulhakim-ozturk-4ym1b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşık Olmak

Ey aşıklar aşkı sadık

Cümle olur bunda salik

Ol cananı canda bulduk

Şefaat ya Resulullah

Neler oldu behey şaşkın

Bu can senin emanettin

Ben şaşkınım biçareyim

Şefaat ya Resulellah

Nefsi şeytan geldi bana

Böyle düşman yok dünyada

Kurtulmak için Allah’a

Şefaat ya Resulellah

Ben hastayım biçareyim

Kalp hastadır Allah’ım

Dokturum sensin ya rabbim

Şefaat ya Resulellah

Aşık oldum cemalına 

Deli oldum didarına

İzin ver, geleyim yanına

Şefaat ya Resulellah

Gülüm bu gün bana güldü

Çürük kalbe merhem sürdü

Kalbim zülmet’ten kurtuldu

Şefaat ya Resulellah

Hüküm ettin bütün yana

Şamdan İrana, Türkiye’ye

Kurban olayım ben sana

Şefaat ya Resulellah

İrem bağındaki gülüm

Bülbül öter coşar günlüm	

Sema yapar benim üzüm

Şefaat ya Resulellah

Çaresizim ben bihalım

Çok ağlıyor benim zarım

Ben kulunum günahkarım

Şefaat ya Resulellah

Mahbubumsun sen günlümde

Maşukumsun sen kalbimde

Vaz geçmişim ben ömrümden

Şefaat ya Resulellah

Yetim kaldım dergahında

Bıçareyim günahımdan

İşimiz zor bu zamanda

Şefaat ya Resulellah

	

Yirminci asrın insanları

Kör olmayan kalmaz geri

Kur’an dır günülerlin rehberi

Şefaat ya Resulellah

A.Hakim aşık olmuş

Maşukun sırrına koşmuş

Nergis ve sünbüller solmuş 

Şefaat ya Resulellah

Tabibe gelen boş gitmiyor

Allah ibadeti emir ediyor

Nehiyleri men ediyor

Derde deva alan gelsin

Kurtul dünya dehşetinden

Kalma geri ümmetlerden

Cuda olsan delaletten

Şefaat ya Resulellah

A.Hakim  herdem diyor

Hakkın emrini yapıyor

Bize ölüm hak oluyuor

Şefaat ya Resulellah

			A.Hakim ÖZTÜRK

			  Müküs 1998', 'Aşık Olmak Ey aşıklar aşkı sadık Cümle olur bunda salik Ol cananı canda bulduk Şefaat ya Resulullah Neler oldu behey şaşkın Bu can senin ema...', ARRAY['Türk Edebiyatı','Şiir','Abdulhakim Öztürk']::text[], 8.5, '{"poet":"Abdulhakim Öztürk","poet_slug":"abdulhakim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/asik-olmak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Ademin Evlatları', 'ey-ademin-evlatlari-abdulhakim-ozturk-znol5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey ademin evlatları

Ey İslam’ın sadıkları

Siz dinleyin bu sözleri

Ey Muhammed ümmetleri

Bir elimde tevsir kur’an

Bir elinde Hadis ihvan

Herdem söyler eder beyan

Ey Muhammed ümmetleri

Nefs şeytani def ediyor

Hem giybeti men ediyor

Şeriatı takip ediyor

Ey Muhammed ümmetleri

Yüce rabbim senden nimet

Bize verdin böyle servet

Gelin gürün bütün ümmet

Ey Muhammed ümmetleri

Eğer lezzeti istersen

Güllü amber çiçeklerden

Alın tevhid-i kötülerden

Ey Muhammed ümmetleri

A.Hakim bu bir zevktir

Kur’an İslama direktir

Bu gün bize ne şereftir

Ey Muhammed ümmetleri

			A.Hakim Öztürk

			   Müküs 1995', 'Ey ademin evlatları Ey İslam’ın sadıkları Siz dinleyin bu sözleri Ey Muhammed ümmetleri Bir elimde tevsir kur’an Bir elinde Hadis ihvan Herd...', ARRAY['Türk Edebiyatı','Şiir','Abdulhakim Öztürk']::text[], 8.5, '{"poet":"Abdulhakim Öztürk","poet_slug":"abdulhakim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ey-ademin-evlatlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Malı', 'dunya-mali-abdulhakim-ozturk-dqxym', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'DÜNYA MALI

Akıl noksan kulak sağır göz görmez

Hakka şükür haktan ihsan var iken

Günlünün gördüğü sanma hak görmez

Küfürlere daima iman var iken

Kanaat gibi servet bulunmaz

Dünya malı insana hor görünmez

Faiz alır haramdan korunmaz

Fıkıh, hadis, Kur’an ayeti var iken

Evvellin düşünme ahırın düşün

Hesaba çekilmek mutlaka işin

Tabibe koşarsın ağrısa dişin

Sağlığın bil akıl irfan var iken

Heveslenme dünya malına

Kısmetinmiş geldin bu dünyaya

Hiç mi acımazsın kendi haline

Önünde ilim irfan var iken

Bu sözler doğru söylendi

Cemaatte hazır olan dinledi

Nefs elinde nice alem inledi

Geç dünyada ilim irfan var iken

			A.Hakim ÖZTÜRK

			   Müküs 1995', 'DÜNYA MALI Akıl noksan kulak sağır göz görmez Hakka şükür haktan ihsan var iken Günlünün gördüğü sanma hak görmez Küfürlere daima iman var i...', ARRAY['Türk Edebiyatı','Şiir','Abdulhakim Öztürk']::text[], 8.5, '{"poet":"Abdulhakim Öztürk","poet_slug":"abdulhakim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dunya-mali-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-ferit-yilmaz-q65ie', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgili

Kan sızıyor gülüşünden

Gözlerinde derin burukluk

Kirli bir ahlak kokusu gelirdi

Öpmeye doyamadığım yüzünden.

Sevgili

Saygısızdık birbirimize bir zaman

Ölümü tutardık avuçlarımızda

Ve daha doğmamış çocuklarımızı

Saklardık koynumuzda

Sevgili

Şimdi sen yoksun hayatımda

Hayatımda acı var dolu dolu

Utanıyorum sevgili şimdi

Hem senden hem bu kirli bedenimden.', 'Sevgili Kan sızıyor gülüşünden Gözlerinde derin burukluk Kirli bir ahlak kokusu gelirdi Öpmeye doyamadığım yüzünden. Sevgili Saygısızdık bir...', ARRAY['Türk Edebiyatı','Şiir','Ferit Yılmaz']::text[], 8.5, '{"poet":"Ferit Yılmaz","poet_slug":"ferit-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgili-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BeDeVi HaMaMI', 'bedevi-hamami-mine-ozdemirtas-4om6v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çivileri,

çürümüş olmalı ki buhardan

kahrolası yüksek nalınlar

sabun köpüğüne takıldılar

düşmemek ne mümkün? 

tandona kadar

kıvrıldılar.

önce,

peştemal döküldü yere

sonra da

saklananlar

mermere çakılırken tırnaklar

yıkıldı saltanatlar. 

''söz''den öte (*)  

ıslanınca dudaklar

büyüdü fısıltılar.

yine de,

direndi damlalar

ta ki

çatlayana kadar

aynalar

''girenin terlediği ''yerdir ya hamamlar

sıcağına ancak

göğsünü yüreğine siper edenler

dayanırlar.

bu yüzden

iyi saatte olsunlar

bunaldılar.

şimdi,

boşa doluyor,

boşa taşıyor

kurnalar.

çünkü,

kum fırtınasında doğanlar

hamam tasını alarak

ait oldukları çöle

T a ş ı n d ı l a r

14/03/2005....  (*)    sözler tutulmamak içindir', 'çivileri, çürümüş olmalı ki buhardan kahrolası yüksek nalınlar sabun köpüğüne takıldılar düşmemek ne mümkün?  tandona kadar kıvrıldılar. önc...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bedevi-hamami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhule Giden Yol', 'mechule-giden-yol-ferit-yilmaz-f27qc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yol var önümüzde

Uzun,karanlık kan kızılı

Bir patika

Ahenksiz anlamsız.

Meçhule giden bir yoldayız

Yol ayrımında

Tercih midir adı karar mı

Gerçek mi yolun sonu

Yalan mı.

Şimdi karar senin

Söyle ne olur

Anlat ya da

Ya benimle hep varsın

Ya hiç olmadın.', 'Bir yol var önümüzde Uzun,karanlık kan kızılı Bir patika Ahenksiz anlamsız. Meçhule giden bir yoldayız Yol ayrımında Tercih midir adı karar ...', ARRAY['Türk Edebiyatı','Şiir','Ferit Yılmaz']::text[], 8.5, '{"poet":"Ferit Yılmaz","poet_slug":"ferit-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mechule-giden-yol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delilik', 'delilik-osman-karatas-l89o4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üşür sevdana, sıcak ellerim,

Devşiririm aklımı, şapkam altına.

Geceleri eser başımda, kavak yellerim,

Deliririm işte o zaman sana.

Formülleri can çekişir cebirin,

O son bakışın her açısında.

Çözümü elinde, nerde ellerin,

Deliririm işte her bakışında.

Kurşuni yağmur akşamları,

Bela ararım, boş sokaklarda.

Engel olur anam, duaları,

Deliririm işte, her yağışında.

Belimde son sevdam, yüreğimde sen,

Dikilmişim hayatın tam ortasında.

Ah birde sen söylesen...,

Deliririm işte her defasında.

Engeline bile çok uzaktayım,

Ne kadar yaklaşsam, hep uzağımda.

Sonu siyah başlangıçtayım,

Deliririm işte her aşamada.', 'Üşür sevdana, sıcak ellerim, Devşiririm aklımı, şapkam altına. Geceleri eser başımda, kavak yellerim, Deliririm işte o zaman sana. Formüller...', ARRAY['Türk Edebiyatı','Şiir','Osman Karataş']::text[], 8.5, '{"poet":"Osman Karataş","poet_slug":"osman-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/delilik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı', 'sarki-nizamettin-saltan-0w9v6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Esîri oldum çeşm-i füsûnkârın senin

Sen kendin eyledin sana müptelâ beni

Yok mu biraz vicdânın, yok mu ârın senin

Sen kendin eyledin sana müptelâ beni

Ey sevgili, sen nice cânı cândan edersin

Bazen öldürürsün, bazen handân edersin

Ne hep sözü, vefâsız, hicrândan edersin? 

Sen kendin eyledin sana müptelâ beni

(1983)', 'Esîri oldum çeşm-i füsûnkârın senin Sen kendin eyledin sana müptelâ beni Yok mu biraz vicdânın, yok mu ârın senin Sen kendin eyledin sana mü...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sarki-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'E mi?', 'e-mi-nizamettin-saltan-l3thg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu akan gözümden hicrân yaşıdır,

Sen de benim gibi ağlama e mi? 

Acılar, acımın en yavaşıdır,

Âh edip içimi dağlama e mi? 

Tül tül perdenden açıp da bir ara,

Bakıver rûhumla uçuşan kara.

Ben böyle dalmışken karanlıklara,

Kara yazmaları bağlama e mi? 

Süzülüp mehtâbın hüzmelerinden,

Çâk ettin sînemi en has yerinden.

Bir gün akacaksan bana derinden,

Eriyip eriyip çağlama e mi? 

(1983)', 'Şu akan gözümden hicrân yaşıdır, Sen de benim gibi ağlama e mi?  Acılar, acımın en yavaşıdır, Âh edip içimi dağlama e mi?  Tül tül perdenden...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/e-mi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımda Vefadan Eser Kalmadı', 'askimda-vefadan-eser-kalmadi-nizamettin-saltan-17vhn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gördüğüm rüyalar hepten yalanmış,

Aşkımda vefâdan eser kalmadı.

Hayâller bir ânlık olsa da gerçek,

Aşkımda vefâdan eser kalmadı.

Dünya bu, sevgilim, eder bulursun.

Sevmezsen bak eğer, unutulursun.

Gerçi birgün özler pişmân olusun,

Aşkımda vefâdan eser kalmadı.

(1983)', 'Gördüğüm rüyalar hepten yalanmış, Aşkımda vefâdan eser kalmadı. Hayâller bir ânlık olsa da gerçek, Aşkımda vefâdan eser kalmadı. Dünya bu, s...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/askimda-vefadan-eser-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masum', 'masum-osman-karatas-nn3ji', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık gelip geçmiyor,titrek adımların.

Seni düşünürken, senliğimin önünden.

Ve artık, masum değil, çubuk şekerlerin,

İçimdeki yeşil gözlü çocuktan.', 'Artık gelip geçmiyor,titrek adımların. Seni düşünürken, senliğimin önünden. Ve artık, masum değil, çubuk şekerlerin, İçimdeki yeşil gözlü ço...', ARRAY['Türk Edebiyatı','Şiir','Osman Karataş']::text[], 8.5, '{"poet":"Osman Karataş","poet_slug":"osman-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/masum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usandım Ağlamaktan', 'usandim-aglamaktan-nizamettin-saltan-wo3zm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Meğer sermâyesi aşkın âh-u figânmış,

Usandım gece gündüz âh edip ağlamaktan.

Bu göz, şu gördüğün gönül sevgine kanmış,

Usandım gece gündüz âh edip ağlamaktan.

Ben ırmak olur akardım, sense bir deniz,

Yalanlara karıştı o meşhur sevgimiz.

Kalan, yalnız orta yerde, soluk bir beniz,

Usandım gece gündüz âh edip ağlamaktan.

(1983)', 'Meğer sermâyesi aşkın âh-u figânmış, Usandım gece gündüz âh edip ağlamaktan. Bu göz, şu gördüğün gönül sevgine kanmış, Usandım gece gündüz â...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/usandim-aglamaktan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Duası', 'gece-duasi-nizamettin-saltan-ihqoa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu uzun geceler neden sıkıcı? 

Gam döşeğinde hep kıvranmadayım.

Bir elem ki, yakıcı mı yakıcı,

Ateşten güya koca bir adayım.

Olacaksa eğer affına sebep,

Beni dertten derde sal ey Allah`ım! 

Zulmet vâdisinde kalacaksam hep,

Bu teni toprağa al ey Allah`ım! 

Ezân okunuyor hep yanık yanık,

Sanki seher bülbülleri ötmede.

Allah dostları şimdi çoktan uyanık,

Bir çâre İlahî  ömrüm bitmede.

Seher ki onda kabuldur duâlar,

Açmışım ellerimi huzuruna.

Âfiyetten, hidâyetten şuâlar

Ver Allah`ım, ver şu Nizâm kuluna.

(1984)', 'Şu uzun geceler neden sıkıcı?  Gam döşeğinde hep kıvranmadayım. Bir elem ki, yakıcı mı yakıcı, Ateşten güya koca bir adayım. Olacaksa eğer a...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gece-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamıyorum', 'unutamiyorum-nizamettin-saltan-9a5e9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalmışım ansızın karanlıklara

Hıçkırıklarımı tutamıyorum.

İçerimde yalnızlıktan bir yara

Izdırap vermede, yatamıyorum.

Almayın benim kokladığım gülü

Başka goncaları tutamıyorum.

Deri ve kemikten sanki bir ölü

Olmuş, bir yudum su yutamıyorum.

Nemli gözlerimden düşmede yaşım

Bir kitap üstüne tutamıyorum.

Vermede aklımı yaşıma başım

Göz yaşlarımı kurutamıyorum.

Geceler, ne olur tutun elimden! 

Azgın gönlümü avutamıyorum.

Çıldıracak gibiyim kederimden

Gitti şehlâm, aah unutamıyorum.

(1984)', 'Dalmışım ansızın karanlıklara Hıçkırıklarımı tutamıyorum. İçerimde yalnızlıktan bir yara Izdırap vermede, yatamıyorum. Almayın benim kokladı...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/unutamiyorum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kur´an ki', 'o-kur-an-ki-nizamettin-saltan-10cuw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O Kur’ân ki, bardak bardak sunar Hakk nûrunu

Ufuk ufuk yağdırır rahmetin yağmurunu

O Kur’ân ki, âleme deste deste renk verir

Varlıklara nizâm ve kalplere ahenk verir

O Kur’ân ki, şifâdır, dindirir âhu zârı

Onunla sükun bulur her asrın intizârı.

(1984)', 'O Kur’ân ki, bardak bardak sunar Hakk nûrunu Ufuk ufuk yağdırır rahmetin yağmurunu O Kur’ân ki, âleme deste deste renk verir Varlıklara nizâ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/o-kur-an-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce', 'dusunce-nizamettin-saltan-vzgmn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşünce, düşünce... İksîrli nehir

Kafalar, kafalar... Çift başlı boru.

Birinden ‘Bir’ akar, birinden zehir

Bu işte hayatın çekilmez zoru.

Günahların allı pullu dehlizi

Eylemiş kendine zavallı esir.

Bir canavar gibi hayâl izbesi

Yutuyor insanlığı, yazık, bir bir.

Öyle bir çağ ki “Nâs” etmiş tecelli

Her şey hakikatte, yalanı devir! 

Allah`a kul olmak, bütün teselli,

Mânânın tezâhür ettiği devir.

Çöker kara bulut, ardından azap; 

Oluk oluk çıkarsa kafadan kir.

Oymak oymak nûr gönder bize yâ Rabb! 

Bu azapla hep insanlık ezilir.

Dudaklar açılsın, kırılsın kilit,

Bir gâye uğruna insan misafir.

Bardak bardak insin tılsımlı asit,

Pişirsin hep gönülleri: Allah bir! 

(1985)', 'Düşünce, düşünce... İksîrli nehir Kafalar, kafalar... Çift başlı boru. Birinden ‘Bir’ akar, birinden zehir Bu işte hayatın çekilmez zoru. Gü...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dusunce-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakim Hanım Hele Bir Dinle', 'hakim-hanim-hele-bir-dinle-doner-ozeke-0svx0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ankara''dan geldim pendik garına 

İnşallah çıkarım bende yarına 

Ne yağmur ne çamur nede karına 

Yine geldim hakimim senin yanına 

Oturdum bir parka seyrettim seni

Ne harika ne güzelsin İstanbul 

Soluksuz nefessiz izledim seni 

İnsanı yutarsın sen koca İstanbul

Bir elimde valiz bir elimde dilekçem

Ne edip ne yapıp seni verecem 

Mahkeme kuruldu bülbül olacam 

Bir yol beni dinle Hakime hanım 

Hakim hanım patron hakkımı yedi 

Al maaşına zam işine son dedi 

Bir aylık maaşımı bana vermedi 

Allahtan korkmadı hakkımı yok dedi 

Emekçiyim hakkım kalmasın yerde

Yorgunluğum bitsin kararı verde 

Kalmasın hakimim emeğim yerde 

Ver kararı artık bitsin bu çile 

Bir yıldır gelirim ben hep burdayım 

Ver artık kararı huzur bulayım 

Emekliyim artık bende güleyim 

Verde bu kararı artık gideyim 

Veriver kararı sorunlarım bitsin 

Bu garip emekli yuvasına gitsin

Ankara,İstanbul çilesi yetsin 

Ver artık kararı bitsin hakimim 



              DÖNER ÖZEKE   

                  15.03.2005', 'Ankara''dan geldim pendik garına  İnşallah çıkarım bende yarına  Ne yağmur ne çamur nede karına  Yine geldim hakimim senin yanına  Oturdum bi...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hakim-hanim-hele-bir-dinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıklar II', 'karanliklar-ii-nizamettin-saltan-lf1e5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne bir mum ışığıdır ve ne de bir lamba

Benim istediğim, karanlık mı karanlık...

Bilirim, döşeyin bir mustatil muşamba,

Karanlık mı ışıktır, ışık mı karanlık.

Ne bir kapı aralığı, ne de bir perde

Benim istediğim, zifirî mi zifirî.

Girmesin içeriye ışık denen sergerde,

Çepçevre muhitken karanlığın iksîri.

Oymak oymak nûr inmede, önümde rahlem

Esrârımı göğerttiğim iklim bilinmez

Ne bir melâl kalır bende ne de bir elem

Daldıkça karanlıklara, ümîdim sönmez.

(1986)', 'Ne bir mum ışığıdır ve ne de bir lamba Benim istediğim, karanlık mı karanlık... Bilirim, döşeyin bir mustatil muşamba, Karanlık mı ışıktır, ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karanliklar-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yansıma', 'yansima-zati-erbas-1m62c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'parmaklarım,sessizliğini bozdu 

hüzün silikleşirken.

zaman; 

içinden geçenleri savurdu.

yüzün yansır oldu yüzüme,

hüzün; 

yüzün yüzüme.

kırık bir kuş kanadı ellerim.

yansıdım,

yansıdık gölün üstüne 

karanlık çöktü yuvaya dönen kuşlar gibi.', 'parmaklarım,sessizliğini bozdu  hüzün silikleşirken. zaman;  içinden geçenleri savurdu. yüzün yansır oldu yüzüme, hüzün;  yüzün yüzüme. kırı...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yansima-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yuva İstiyorum', 'bir-yuva-i-stiyorum-nizamettin-saltan-de3y2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yuva ver bize, sıcak mı sıcak

Bir yuva ver bize, kucak be kucak

Bir yuva Allah`ım köşe ve bucak

Rahmet dolu, aşk dolu, nûr dolu olsun.

Bir yuva ver, buram buram kokacak

Bir yuva ver, güneş ordan doğacak

Bir yuva Allah`ım, karanlığı boğacak

Saâdet dolu, aşk dolu, nûr dolu olsun.

Bir yuva ver, mahya mahya yanacak

Bir yuva ver, âlem ordan kanacak

Bir yuva Allah`ım, sevginle yıkanacak

Nimet dolu, aşk dolu, nûr dolu olsun.

Bir yuva ver, dolup dolup taşacak

Bir yuva ver, dalga dalga coşacak

Bir yuva Allah`ım, öteleri aşacak

Vahdet dolu, aşk dolu, nûr dolu olsun.

(1986)', 'Bir yuva ver bize, sıcak mı sıcak Bir yuva ver bize, kucak be kucak Bir yuva Allah`ım köşe ve bucak Rahmet dolu, aşk dolu, nûr dolu olsun. B...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-yuva-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur I', 'yagmur-i-nizamettin-saltan-zccbc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sicim sicim inen bu billur yağmur

İndikçe rûhuma dolmada sürûr.

Dem çekiyor sanki vurdukça cama

Buram buram bahar iner hülyâma.

Bir başka keyf seyretmek yağmurları

Bir başka zevk dinlemek hep onları.

Bir gök gürültüsü, avâre şimşek…

Derken, iner yağmurlar süzülerek.

(1986)', 'Sicim sicim inen bu billur yağmur İndikçe rûhuma dolmada sürûr. Dem çekiyor sanki vurdukça cama Buram buram bahar iner hülyâma. Bir başka ke...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yagmur-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur II', 'yagmur-ii-nizamettin-saltan-wkud8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fânusu kırılmış köhne bir lamba

Alaylı gözlerle bakar sokağa.

Göğe serilmiş siyah muşamba

Bazen su olur akar sokağa.

Pencere, pencere çapkın pencere,

Ne kadar âşıksın inen yağmura! 

Elini sürme ki düşerken yere

Benziyor rûhumu yıkayan nûra.

Ne de hoş oluyor seyri yağmurun

İndikçe sıyrılır rûhumun pası.

Almayın câniler gecemi, durun! 

Gecede şâd olur gönül elması.

(1986)', 'Fânusu kırılmış köhne bir lamba Alaylı gözlerle bakar sokağa. Göğe serilmiş siyah muşamba Bazen su olur akar sokağa. Pencere, pencere çapkın...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yagmur-ii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçeler', 'serceler-nizamettin-saltan-4q0vr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelin de bu sabah hüznümü atın

Cıvıl cıvıl cıvıldaşın serçeler! 

Beni de, beni de araya katın

Hafakan semtini aşın serçeler! 

Düğüm düğüm boğaz, derin hıçkırık

Gönlüm bugün mahzun, kırık mı kırık

Verin neş`enizden elime sırık

Tutunayım ona, koşun serçeler! 

Ne müthiş manzara dalda duruşlar

Gelin pencereme dem çekin kuşlar! 

Odamı kaplamış günahlar, suçlar

Ağlayın, ağlayın, taşın serçeler! 

(1986)', 'Gelin de bu sabah hüznümü atın Cıvıl cıvıl cıvıldaşın serçeler!  Beni de, beni de araya katın Hafakan semtini aşın serçeler!  Düğüm düğüm bo...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/serceler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılan Ömür', 'yikilan-omur-nizamettin-saltan-cyzib', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gençlik yıllarımın gitti baharı

Yaprağı dökülüp hazana döndü.

Yıkıldı ömrümün zerrin duvarı

Enkazdan ibaret virâna döndü.

Neye yaradı, gitti bir ömür

Bükülmez bilek elbet bükülür

Ne adım atsam isyân dökülür

Günahlar, cürümler ummâna döndü.

Yüzerken sandallar denizde mesrur

Tazelen duânla, nefsim, ne olur! 

Ömür, meçhule açılan bir vapur

Bilmedim dümeni ne yana döndü.

Irmaklar denizin, ölümse bizim

Yolcular yollarda hep dizim dizim

Yolcuyum İlâhî, pek nasipsizim

Bu kirli ellerim Rahmân`a döndü.

(1987)', 'Gençlik yıllarımın gitti baharı Yaprağı dökülüp hazana döndü. Yıkıldı ömrümün zerrin duvarı Enkazdan ibaret virâna döndü. Neye yaradı, gitti...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yikilan-omur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk', 'turk-ahmet-kurt-z115z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sayın Nurdane Diken Hanımefendiye 

Kuru bir avuntu değil tarihim,

Dünyada ilmimin emsali yoktur,

En küçük haslette silinir kinim,

Kahramanlık dersen, her soydan çoktur.

Adıma eş gelir adalet benim,

Sömürge, haksızlık ve talan bilmem.

Hakkın ateşiyle kavrulur tenim,

Bu yüzden yok olmam, bu yüzden ölmem.

Sineme çarpınca durur husumet, 

Mazluma kol kanat Türk’te meziyet,

Hukuku tanıdım, yoktur keyfiyet,

Vicdanım sızlamaz, bilmem eziyet,

Zulmete set oldum, şehitler verdim,

Çağlardan beridir böyle vakurum.

Akınları gördüm, bu güne erdim,

İman kalesinde Türklük gururum.

Halde ki temsilcim kaypaktır diye,

Sinemem, korkamam, geri duramam.

Endişem olmadı gelecek diye,

Zayıfa uyarak, hesap kuramam.

Türk oğlu, Atanın tarifi güzel,

Hitabı okuyup, uyarsan yeter.

Ayaklar altında sürünür gazel,

Sürüngen olmaksa ölümden beter.

Titre ki aslını görsün gafiller,

Şahlan ki tarihi baştan yazasın.

Buyruğu anlamaz aslı fosiller,

Kaynaş ki tezgahta oyun bozasın.

Koymasın yolundan kaypak ve ürkek,

Mührünü bekliyor, zamanın hükmü,

Ayıklanır elbet, dökülür tek tek,

Çağlara yön verir Türklüğün hükmü.', 'Sayın Nurdane Diken Hanımefendiye  Kuru bir avuntu değil tarihim, Dünyada ilmimin emsali yoktur, En küçük haslette silinir kinim, Kahramanlı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/turk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaretim Yok', 'cesaretim-yok-i-lknur-cekici-0phye', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cesaretim yok diyemem seviyorum

Cesaretim yok diyemem özlüyorum

Cesaretim yok ama istiyorum

Bak gözlerime anla sevgimi

Tut ellerimi bırakma beni

Cesaretim yok dön geri', 'Cesaretim yok diyemem seviyorum Cesaretim yok diyemem özlüyorum Cesaretim yok ama istiyorum Bak gözlerime anla sevgimi Tut ellerimi bırakma ...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cesaretim-yok-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Himmetin Âli Olsun', 'himmetin-li-olsun-nizamettin-saltan-4mx0k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakışın doruklara doğru

Himmetin âlî olsun

Sözün hak, özün doğru

Yalandan hâlî olsun.

Tut gönlünü dupduru

Duyguların da berrak

Bırak kibri, gurûru

Tevâzuda ol toprak

Bir fecre mührünü bas

Büyülensin tan yeri

Mümin yobaz olamaz

Onu diyen serseri. 

(1999)', 'Bakışın doruklara doğru Himmetin âlî olsun Sözün hak, özün doğru Yalandan hâlî olsun. Tut gönlünü dupduru Duyguların da berrak Bırak kibri, ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/himmetin-ali-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum`a', 'oglum-a-nizamettin-saltan-9tkop', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ötelere âşinâ

Kızgın bakışın olsun

Hep ilmin yokuşuna

Coşkun akışın olsun

Allah olsun vekîlin

Kur`an olsun delîlin

Dostça uzat ki elin

Hayrda yarışın olsun

İhsânın yolu yamaç

İnsan ol, gönlünü aç

İnsanlık sana muhtaç

Dâvânda taşın olsun

Bu yol zorlu, bu yol sarp

Bu yol çile, ıztırap

Bu yolda ol ki turap

Dost`a varışın olsun

Zulmeyleme sakın, haa! 

Zâlim gelmez iflâha

Yerinde kalk ki şâha

Hakk`a kalkışın olsun

Ne sağda kal ne solda

Hak yolda ol, hak yolda

Cihad aşkıyla dol da

Verecek başın olsun

İlim elde kırbacın

Sevkede kardeş, bacın

Yoksa eğer yol harcın

Takvâ yoldaşın olsun

Etme ömrünü heder

Kendini hep ilme ver

Virdin, Allahu Ekber

Tekbîr, alkışın olsun

Yûnusleyin dilde kal

Pişir özün, kalma kal

Deryâlara kendin sal

Her yerde nâşın olsun.

(2000)', 'Ötelere âşinâ Kızgın bakışın olsun Hep ilmin yokuşuna Coşkun akışın olsun Allah olsun vekîlin Kur`an olsun delîlin Dostça uzat ki elin Hayrd...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/oglum-a-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıklar Olsun', 'yaziklar-olsun-sahin-erturk-ieg7i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Devletin malını çalanlara

Haram,helal nedir bilmezlere

Utanmazlara,sıkılmazlara

Yazıklar olsun,yazıklar olsun

Fakir yatıp,zengin kalkanlara

Hırsıza uyanık diyenlere

SAF lığı delilik bilenlere

Yazıklar olsun,yazıklar olsun

Komşusu açken tok yatanlara

Barlarda,paralar saçanlara

Soyluyum diyen görgüsüzlere

Yazıklar olsun,yazıklar olsun

Açılmak,çağdaşlık bilenlere

Kapanmak İRTİCA diyenlere

Din bilmeden FETVA verenlere

Yazıklar olsun,yazıklar olsun

Fakirlerle alay edenlere

YUNAN lıya dostum diyenlere

Müslüman a sırtın dönenlere

Yazıklar olsun,yazıklar olsun

Ahte vefa göstermeyenlere

Osmanlıyı inkar edenlere

Vatan bölmeye çalışanlara

Yazıklar olsun,yazıklar olsun

Çıkar uğruna satılanlara

Aydınlığı SÖYLEV sananlara

Demokrasi tahrip edenlere

Yazıklar olsun,yazıklar olsun

(Kontrolsüz Sevgi adlı Şiir kitabımdan)', 'Devletin malını çalanlara Haram,helal nedir bilmezlere Utanmazlara,sıkılmazlara Yazıklar olsun,yazıklar olsun Fakir yatıp,zengin kalkanlara ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yaziklar-olsun-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşe`ye Mektup', 'ayse-ye-mektup-nizamettin-saltan-351w0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabah aldım gül kokan mektubunu

Pek sevindim Allah` ayan be Ayşe! 

Okudukça yaş değil yanağımdan

Hayâlindi yuvarlanan be Ayşe! 

Mektubunda diyorsun ki ‘can ağbim,

Sen gideli buralarda garibim

Çâre olmaz hasretime tabibim’

Üç yıl kaldı, yettim, dayan be Ayşe! 

Muhtaçsın bilirim paylaşan yâre

Bu yüzden elemin, hüznün yekpâre

Seninçün hayatta en kutlu çâre

Seherde yaptığın duân be Ayşe! 

Bahtına sızlanıp isyânda durma

Mâteme bürünüp gönlünü yorma

Ne kapılar açar garibe, sorma

Kaparsa birini Rahmân be Ayşe! 

Özlemini gömüver kitaplara

Karışma çözümsüz karanlıklara

Sanma daima değişen mâcerâ

Hayat çok çok güzel, inan be Ayşe! 

Başka ömre huzurunu bağlama

Metin ol da vara yoğa ağlama

İnsan âciz, yol, yalçın bir dağ ama

İmtihandır, haydi davran be Ayşe! 

İkimizin duâsıdır Allah`a,

Ayırmasın bizi bizden bir daha 

İstiyorsan bak gelirim sabaha

Koşa koşa yorulmadan be Ayşe! 

Sen sabrını inadına bileğle

Gönülcüğün ilhâmlara yol eyle

Bu ağbinin hatırını gül eyle

Varsa sende ondan kalan be Ayşe! 		

(2002/Nidda)', 'Sabah aldım gül kokan mektubunu Pek sevindim Allah` ayan be Ayşe!  Okudukça yaş değil yanağımdan Hayâlindi yuvarlanan be Ayşe!  Mektubunda d...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ayse-ye-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Gün', 'zor-gun-adnan-mehmet-tufekci-b1ir9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'umutla,

özlemle bekliyorduk,

bir çok kişi,

bir çok kişiyi.

geldiler,

sevgiyle sarılıp gittiler.

ben kaldım sadece,

ben bekleyen,

sen gelmeyen.

binlerce kişi geçti bakışlarımdan,

bir dostu,

eski bir sevgiliyi gördüm.

yalın bir yalnızlık yaşadım

o kadar insan arasında.

avunuyordum birazdan diyerek,

her birazla,

kandıramaz oldum kendimi.

saatlerin ardından sona erdi umutlar.

yürüdüm delicesine.

adımlarım götürdü

beni istediği yerlere.

eski mekanları gezdim,

seni aradım.

düşüncelerimi dağıtmak,

unutmak istedim.,

ama nâfile.

saatler sonra

evde buldum kendimi.

masamda yırtık bir kağıt,

kırık bir kalem ile.', 'umutla, özlemle bekliyorduk, bir çok kişi, bir çok kişiyi. geldiler, sevgiyle sarılıp gittiler. ben kaldım sadece, ben bekleyen, sen gelmeye...', ARRAY['Türk Edebiyatı','Şiir','Adnan Mehmet Tüfekci']::text[], 8.5, '{"poet":"Adnan Mehmet Tüfekci","poet_slug":"adnan-mehmet-tufekci","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/zor-gun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak sesleri', 'ayak-sesleri-zati-erbas-t0zwf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yağmur her şeyi yıkadı,mayıstı.

mavi bir alev gibi yükseldi martılar

her şeyi yakmak geliyor içimden. 

çizgileri artıyor; ellerimin

sesimi esirgedim martılarla konuşurken.

her baktığımda yağmur yağıyor; 

mayıs ve martılar nedenini bilmeden

sahilde dalgalar gibi aklımda kalanlar. 

gözlerimi yumdum; yağmur

içimde bir boşluk

yağmurunmuş ayak sesleri.', 'yağmur her şeyi yıkadı,mayıstı. mavi bir alev gibi yükseldi martılar her şeyi yakmak geliyor içimden.  çizgileri artıyor; ellerimin sesimi e...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayak-sesleri-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutkanlık', 'unutkanlik-zati-erbas-lbgc0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'unuttum 

tencerede pişen kuru fasulyenin 

tahta 

kaşığa çarptığında çıkardığı sesi.

çiçekleri sulamayı 

unutuyorum 

bahar geleli beri

kuşlara yem vermeyi 

unutmuyorum

demir parmaklıkların çerçevelediği

odalarda 

hapis

ektiğin çiçekler 

toprağın 

derinliklerinde büyüyor

kökleri 

bedenimde

karanlığa yakın 

gökyüzündeki bulutlarda

hüzün çiçekleri açıyor 

ben 

yolculuklara hazırlanıyorum sessizce', 'unuttum  tencerede pişen kuru fasulyenin  tahta  kaşığa çarptığında çıkardığı sesi. çiçekleri sulamayı  unutuyorum  bahar geleli beri kuşlar...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/unutkanlik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANİLER (60) ''Mudurnu Havasında...''', 'mani-ler-60-mudurnu-havasinda-abdullah-atay-w0a9o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mudurnu havasında 

mis gibi kekik kokar 

hele kaplıcasında 

şifalı sular akar... 

eli bıçaklı yarim 

salkım saçaklı yarim 

güzeller başı olmuş 

çarpık bacaklı yarim... 

bağımda açtı leylak 

dalından uçtu leylek 

kız ben senin derdinden 

dolaştım aylak aylak... 

yüce dağın başında 

yavru bir maral gezer 

gönül yarin peşinde 

o yarda canım üzer... 

sular gibi durusun yar 

yüreğimin korusun yar 

kem gözlerin nazarından 

tanrım seni korusun yar... 

yare kına yakarım 

takıları takarım 

bana gelin gelince 

kuş sütüyle bakarım... 

bu dünyada ölüm var 

yardan bana zulüm var 

yol verin karlı dağlar 

bağda gonca gülüm var... 

sevdiğim bahar dalı 

yarim bana sevdalı 

aramıza girenler 

dikenli kara çalı... 

abdullah atay der ki; 

sen ölümlü bir kulsun 

sonu olan bir yolsun 

bu dünyada sev sevil 

yüreğin şifa bulsun....', 'mudurnu havasında  mis gibi kekik kokar  hele kaplıcasında  şifalı sular akar...  eli bıçaklı yarim  salkım saçaklı yarim  güzeller başı olm...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/maniler-60-mudurnu-havasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Can Bana Fazla', 'bu-can-bana-fazla-sahin-erturk-jmqm2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Herşeyimi aldın gittin

Duygularım SEN le gitti

Al istersen senin olsun

Bu can bana,artık fazla

Bugünümü,yarınımı

Çaldın güzel,öyle gittin

Doymadıysan al bu canı

Bu can bana,artık fazla

Senden bana neler kaldı

Yaşanacak GÜN mü kaldı

Al istersen senin olsun

Bu can bana,artık fazla

Sensiz soldu umutlarım

Sensiz bitmez sancılarım

Sensiz sersem bicareyim

Bu can bana,artık fazla

(15.03.2005-Yeni)', 'Herşeyimi aldın gittin Duygularım SEN le gitti Al istersen senin olsun Bu can bana,artık fazla Bugünümü,yarınımı Çaldın güzel,öyle gittin Do...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-can-bana-fazla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudağımdan Aşkı Öğren', 'dudagimdan-aski-ogren-sahin-erturk-gbdyf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acılardan kaçıyorsun

Mutluluğu arıyorsun

Açık,seçik durum belli

Uzat bana dudağını

Aşkı öğren dudağımdan

Aşk,istemek dokunmaktır

Hissetmektir,beklemektir

Tek vücutta buluşmaktır

Uzat bana dudağını

Dudağımdan öğren aşkı

Tamam biraz korkuyorsun

Aşk tan yana yaralısın

Korkma benden,yemem seni

Uzat bana dudağını

Dudağımdan öğren aşkı

Gözlerime bakta inan

Kulağınla duyda inan

Tam dengini buldun inan

Uzat bana dudağını

Dudağımdan aşkı öğren

(14.03.2005-Yeni)', 'Acılardan kaçıyorsun Mutluluğu arıyorsun Açık,seçik durum belli Uzat bana dudağını Aşkı öğren dudağımdan Aşk,istemek dokunmaktır Hissetmekti...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dudagimdan-aski-ogren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair', 'aska-dair-senol-ozuturk-3s0je', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbe zarar bekleyişler bıraktım arkada 

Sorgusuz sualsiz ayrılışlar

Yeter artık deligönül sanadır bu haykırışlar

Ankara 2001', 'Kalbe zarar bekleyişler bıraktım arkada  Sorgusuz sualsiz ayrılışlar Yeter artık deligönül sanadır bu haykırışlar Ankara 2001...', ARRAY['Türk Edebiyatı','Şiir','Şenol Özütürk']::text[], 8.5, '{"poet":"Şenol Özütürk","poet_slug":"senol-ozuturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aska-dair-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlanıaşk', 'i-laniask-zafer-mutlu-fez4m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kelebek ömrü misali

baharda kaldı,

iki nefes arası...

göz ucuyla süzerken hayatı

hep o anda kaldı.

kağıt parçasına yazılmış şiir gibi

göreceli,iki nefes arası...', 'kelebek ömrü misali baharda kaldı, iki nefes arası... göz ucuyla süzerken hayatı hep o anda kaldı. kağıt parçasına yazılmış şiir gibi görece...', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ilaniask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklediğim', 'bekledigim-senol-ozuturk-9c90q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen ardına bakmadan giderken 

Yüreğimde param parça hayallerim 

İfadesini hangi sevda verecek

Sensiz gecelerin

İtiraf etsede suçunu elime uzakken ellerin

Ayrılık bu anlamı yok sensiz dökülen kelimelerin

Ankara 2005', 'Sen ardına bakmadan giderken  Yüreğimde param parça hayallerim  İfadesini hangi sevda verecek Sensiz gecelerin İtiraf etsede suçunu elime uz...', ARRAY['Türk Edebiyatı','Şiir','Şenol Özütürk']::text[], 8.5, '{"poet":"Şenol Özütürk","poet_slug":"senol-ozuturk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bekledigim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Hemşerim', 'can-hemserim-doner-ozeke-nxp02', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Can hemşerim meylin aldım sanaldan 

Canım gitti gayri benim bu candan 

Ne aşağıdan ne yukardan nede yabandan 

Anam gitti gelmez canım hemşerim 

Siteme gelmişde beni sormuşsun 

Allah razı olsun yüreğin gülsün 

Dostlarım bugünde yanımda olsun

Gönül istiyor canım hemşerim 

Osman Uçar değil apdal yazmışsın 

Belli ki hemşerim gurbet gezmişsin 

Sakın hemşom dertler seni üzmesin 

Selam olsun hemşo ömrün var olsun 

                  DÖNER ÖZEKE 

                    15.03.2005', 'Can hemşerim meylin aldım sanaldan  Canım gitti gayri benim bu candan  Ne aşağıdan ne yukardan nede yabandan  Anam gitti gelmez canım hemşer...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/can-hemserim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Düşüncelik Zaman', 'bir-dusuncelik-zaman-sitki-gokmen-yx1w2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum gülüm deniz kıyısında,

Doldurdun yine zihnimi.

Bir çay içimlik zamanda,

Denizde seni görüyor,

Dalgaların seslerine karışmış sesini duyuyorum.

Ve martılar haber getiriyor, 

Başımın üstünde uçuşurken,

Seni özlüyor diye.

Martı olmak istiyorum,

Sana uçmak için.

Güneş olmak istiyorum,

Seni ısıtmak için.

Hava olmak istiyorum,

Nefesin olmak için.

Bir el olmak istiyorum,

Sevgimi sana vermek için.

Sevgimi sana vermek istiyorum,

Beni çok sevmen için.

(İZMİR/MENTEŞ 18 TEMMUZ 1985-10 MART 2005)', 'Seni düşünüyorum gülüm deniz kıyısında, Doldurdun yine zihnimi. Bir çay içimlik zamanda, Denizde seni görüyor, Dalgaların seslerine karışmış...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-dusuncelik-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet Bahçelerinde Yaşam', 'cennet-bahcelerinde-yasam-kerem-alay-qmr5t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu dünya yaşamı bir gün bitecek

Allah''a kavuşacak günler yakındır

Ömür sona erip ecel gelecek

Hakka dönülecek cennetler vardır.

İnsanlar bilseydi cenneti eğer

Bu dünya yaşamı bir hiçe değer

Yaradana bak cenneti nasıl öğer

Cennette bahçeler huriler vardır.

Bir tatlı hicret ki dünya değişir

Ruhların cümlesi hakka erişir

İstenen her şey kendi yetişir

Cennette maşakkat, keder yoktur.

cennette yaşlılar 33''lufidana benzer

Eş ve çocukları yanında gezer

İnsanlar kuşlar gibi havada gezer

Cennette ayrılık yorgunluk yoktur.

                      

                                     14,03,2005

                                      Kerem Alay

                                      Van', 'Bu dünya yaşamı bir gün bitecek Allah''a kavuşacak günler yakındır Ömür sona erip ecel gelecek Hakka dönülecek cennetler vardır. İnsanlar bil...', ARRAY['Türk Edebiyatı','Şiir','Kerem Alay']::text[], 8.5, '{"poet":"Kerem Alay","poet_slug":"kerem-alay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cennet-bahcelerinde-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tomurcuk Gül Aşkına', 'bir-tomurcuk-gul-askina-nuri-can-dtakc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni kanayan bütün yaralara sarıyorum ey şiir 

seni kanayan bütün acılara 

kaynağına küsmüş pınarlara 

çatlayan tomurcuklara, baharlara 

çığlıklara, demir parmaklıklara 

seni yarınlara umutla bakıp 

sesini yitirmiş çocuklara adıyorum ey şiir 

ürkütülmüş güvercin kanadına yazıyorum seni 

unutma bizi 

unutma yüreğini kanatanı bir tomurcuk gül aşkına 

Seni yaşanmamış sevdalara adıyorum ey şiir 

tadılmamış sevdalara 

bir rüzgarın nefesine 

bir nehrin akışına

bir ırmağın sesine 

gözü yaşlı analara 

yüreği tekmelenmiş babalara 

savaşlara, dostluklara, arkadaşlıklara 

açılmamış bir goncanın kokusuna 

aşkını gizleyen bir kız çocuğunun soluğuna karıyorum seni ey şiir 

bir çınarın yaprağına yazıyorum seni 

unutma bizı 

unutma yüreğini kanatanı bir tomurcuk gül aşkına 

Seni gül kıyımlarına 

yürekte üşüyen incecik kıpırtılara adıyorum ey şiir 

dillere destan şarkılara., yüreklere mühür aşklara 

ölümsüzlüklere, sonsuzluklara, yoksunluklara yazıyorum seni... 

kirpiklerimizde incinmiş bir damla şiirle 

bir sevda durağında bekliyoruz seni 

unutma 

gül damıtırken ayışığı gül bakışlardan sulara 

Mehtabın ırmağa

damlanın yaprağa

cemrenin toprağa

hasretin dudağa değdiği zaman

dostluklar kanatlandığında güvercin uçuşlarında 

sıcaklığına duyarlı bir defne dalında bekliyoruz seni... 

Acıları sevmek en çok sana yakışır ey şiir 

yüreğinde üşüyen incecik kıpırtılara 

seni kanayan bütün yaralara sarıyorum 

üşüyen bütün yaralara 

apaydınlık yarınlara 

ıpışıl sabahlara

unutma bizı 

unutma yüreğini kanatanı bir tomurcuk gül aşkına 

Öksüz bir çocuk boyun eğdiği zaman

buzun ateşe, acının yüreğe değdiği zaman

küsmeden bahar yağmurları umutlara

boranlar sevinçlere çöreklenmeden 

kirpiklerimizde incinmiş bir damla şiirle 

bin umut durağında bekliyoruz seni 

gül damıtırken ayışığı gül bakışlardan gecelere...! 

unutma bizı 

unutma yüreğini kanatanı bir tomurcuk gül aşkına 

gölgesinde esmer günahlar taşıyan bu çaresizlik bitsin artık 

yağmurlara ve akıp giden hayatın türküsüne adıyorum seni 

yürekte yanan ateşi yalnız hasretin gözyaşları ıslatır unutma 

unutma yüreğini kanatanı bir tomurcuk gül aşkına 

.', 'Seni kanayan bütün yaralara sarıyorum ey şiir  seni kanayan bütün acılara  kaynağına küsmüş pınarlara  çatlayan tomurcuklara, baharlara  çığ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/bir-tomurcuk-gul-askina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal çiçeği', 'masal-cicegi-nuri-can-bdfre', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zaman seni düşünsem

bir kuş ötüşünde bahar gelir dağlara

kanatlarında yüreğimi okşar ellerin

bütün ağaçlar yüregimde tomurcuklanır

bütün çiçekler gözlerimde

bin bahar saflığına bürünür hayat 

Nerede seni görsem

sevinç çığlıkları saçar gözlerim sokaklara

güzelleşir yeryüzü nereye baksam

maviye bulanır sevdaya akan bütün duygular

yüzünün güzelliğiyle yıkarım yüzümü her sabah

ve sen en güzel masal çiçeğim olursun 

nerede sesini duysam

avuçları gül kokan 

çocukların duaları yağar üzerime.

akan pınarlara sesini,

öptüğün çınarlara nefesini taşırım.

ne zaman ışısa vefa gögünde hilal

yıldız gülücükleri dökülür denizlere çağıl çağıl

ne zaman seni ansısam

sevgiye bin çiçek açar yüreğim sen kokan

kötülükler alır gider başını bu şehirde

bir ceylan iner pınarlara

su gibi yudum yudum

hava gibi nefes nefes sevgin dolar her yere 

ellerini hissederim ellerimde sımsıcak 

bilirim ki aşk en güzel masal çiçeğidir gönüllerde

mutlu mavi çiçekler açtıran insan hayatında

bütün dillerde sevgi şiiridir masal çiçeği

bütün dudaklarda sevinç nağmesi

ben ki yalnız seni sevdim bu yalancı dünyada

yalnız senin oldum 

taştıkça aşkın ırmakları

seninle bütünleşti hayatımın tüm renkleri

her hissetiğimde yüreğimde yüreğini sımsıcak

yağmursun sen, gökkuşağısın

rüzgarsın, baharsın, aşksın, hayatsın

tek mümkünüsün ömrümün, tek umudumsun

her güz mavi çiçekler açan bahar çiçeğimsin

gök kuşağından, gün ışığından ayrılırken

ben sana sarılırım yedirenk sevinçlerle her gece

.', 'Ne zaman seni düşünsem bir kuş ötüşünde bahar gelir dağlara kanatlarında yüreğimi okşar ellerin bütün ağaçlar yüregimde tomurcuklanır bütün ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/masal-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötekiler', 'otekiler-emirzad-demirel-pewjn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin bu saatinde seni  uyandırdım, affedersin

Radyolarda şiir  söylüyor, 

Duvar  saati de..

Tutamadım kendimi,

Gene  düştüm.

Bir  kursun beni  ıskalamaya devam ediyor.

Bütün  şehirler  düşmüş kaçıncı  uykusunda,

Baharın en taze  fidanı

En  özgür  nefesini   alıyor.

Evler  şuan  silahsız...

Dünyanın en barbar  ülkesi  uyuyor.

Ve bir  ihtimal senin yerine geçecekler.

Nehirler ve nehirler  tüm  setleri sen  diye geçiyorlar.

Gecenin  bu saatinde tüm yasalar  çiğnenebilir.

En az  cezayı  almak isteyen  kör  şairler

Bu saatte şiir  yazıyorlar.

Işıksız, umutlu...

Birazdan  gazeteler  basılacak; 

Yeni  ölüleri,  zamları

Ve  hortlayan  tüm emperyalistleri  anacaklar  şüphesiz.

Gecenin bu saatinde  seni  uyandırdım,  affedersin

Yüreğin   soğumadan  uyu.

16.04.2002', 'Gecenin bu saatinde seni  uyandırdım, affedersin Radyolarda şiir  söylüyor,  Duvar  saati de.. Tutamadım kendimi, Gene  düştüm. Bir  kursun ...', ARRAY['Türk Edebiyatı','Şiir','Emirzad Demirel']::text[], 8.5, '{"poet":"Emirzad Demirel","poet_slug":"emirzad-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/otekiler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sehpa', 'sehpa-emirzad-demirel-st70b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir  küçük  sehpa,

Dört  bir  yandan  asılmış  hayata.

Üzerinde   bir sayfa,  hiddetle karalanmış.

Cümleler  yorgun yaralı,

Üç nokta...

Dert mi   bu  anlatılmayan? 

Belki  bir  güzel, tanımlanmayan...

Karalanmış  sayfa...

Off   sezleri  duyar  gibiyim.

Cümleleri  küçük  harfle  başlıyor  ama  bitmiyor,

Cümleler  uğraş  veriyor  ama  yetmiyor.

Bu  kalp yangını,  bu  vurulma  sanatı,

Bir  küçük  sehpada  sallanan...

Sonunda ne bir  isim  ne bir  tarih

Her an  herkese  malum olur.

Muhtemelen bitirilmeyen  türden.

Belkide bir kadın,

Bir  küçük  sehpada  sallanan...

Kimin hayatı?', 'Bir  küçük  sehpa, Dört  bir  yandan  asılmış  hayata. Üzerinde   bir sayfa,  hiddetle karalanmış. Cümleler  yorgun yaralı, Üç nokta... Dert...', ARRAY['Türk Edebiyatı','Şiir','Emirzad Demirel']::text[], 8.5, '{"poet":"Emirzad Demirel","poet_slug":"emirzad-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sehpa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah İle', 'ah-i-le-mutlu-colak-46bas', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Deniz maviymiş, gök mavi.

Kızılada''da bir başkaymış mehtap.

Seyre daldık yıldızları, vurunca sahile

Bir derin nefes ah ile

Mevsim yazmış, mevsim sonbahar.

Köhnemiş yol, sonu virane köy

Issız kaldı gönül.

Bir derin nefes ah ile

Dünya faniymiş, insanlar yalan.

Mahalle komşumuz, iki de çocuğu aç yatan

Gözümüz hırstan, kalbimiz kandan; bize ne ondan bundan

Bir derin nefes ah ile

Muhabbet gönülde kalmış, dostlar ayrı.

Sevda masal olmuş, sevenler ayrı.

Dünden bize hasret kalmış gayrı

Bir derin nefes ah ile', 'Deniz maviymiş, gök mavi. Kızılada''da bir başkaymış mehtap. Seyre daldık yıldızları, vurunca sahile Bir derin nefes ah ile Mevsim yazmış, me...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Çolak']::text[], 8.5, '{"poet":"Mutlu Çolak","poet_slug":"mutlu-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ah-ile-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ki;', 'ki-mehmet-lutfu-aydin-dpmja', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sil ki; göz yaşların dönmesin sele

Bil ki; senin için çarpar bu yürek

Gel ki; bu yol gider gülden gönüle

Gül ki; gülsün bu can, candan geçerek', 'Sil ki; göz yaşların dönmesin sele Bil ki; senin için çarpar bu yürek Gel ki; bu yol gider gülden gönüle Gül ki; gülsün bu can, candan geçer...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ki-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunaltı', 'bunalti-emirzad-demirel-lqu02', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boş bu,  sevdan  boş, bunu bil.

Beraber   çırpındığımız  bu  yürek, bizi taşımaz.

Sonunda  loş bir  odada  ağarırı  saçlarım,

Kan  güllerine  döner  herşey.

Akar akar  ömür,  mecnunun  gözyaşlarında.

Geriye  kalan  bir  çizgileri  iki  yüzlü  sevdanın

Ve  üç  beş  nağme  kimsenin  çalmaya cesaret   etmeyeceği.

Boş bu,  gözlerin kayboluyor  içimde.

Tükenen  umutların haykırışıdır  bu  son nefes.

Anlamadığım  bir  öfkeye  sattı  ismini.

Bu  ceset için  ölmek,  geri  getirmez.

Biter  biter  o  güzel  düşler,

Daha  yaşamadan  kırdım kalemi.

Bir  İstiklal  Mahkemesi,  çok  şey  gerekmez.

Kapat kapıları  üstüme,  çiğne  onurumu.

Bir  güzel  kelimeyle  ölmek istemem.

Bensiz  saçların  gene  dalgalı,

Benden  hediye  kapkara  bir  gömlekle  git.

Bana  dair  başka  şeyde  istemem  zaten.

Bundan  ötesi  boş,  anlamadığım bir  bunaltı.', 'Boş bu,  sevdan  boş, bunu bil. Beraber   çırpındığımız  bu  yürek, bizi taşımaz. Sonunda  loş bir  odada  ağarırı  saçlarım, Kan  güllerine...', ARRAY['Türk Edebiyatı','Şiir','Emirzad Demirel']::text[], 8.5, '{"poet":"Emirzad Demirel","poet_slug":"emirzad-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bunalti-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Ölüm Üstüne Tespitler', 'ask-ve-olum-ustune-tespitler-zafer-yazici-a66cz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'biz insanlar

hayatımızda iki defa 

köy değişiriz

bir; 

___evlenince

iki; 

___ölünce! ...', 'biz insanlar hayatımızda iki defa  köy değişiriz bir;  ___evlenince iki;  ___ölünce! ......', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-ve-olum-ustune-tespitler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Adamın Dansı', 'eski-adamin-dansi-sururi-turan-zabcv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kılıçlar çekildi gene bak

binyıllardır hep çekilir

eski adam en vahşi çığlıklarını atar

en sessiz çığlıklarını

beyinlerde

bedenlerde

denizlerde

ülkelerde

savaş meydanlarında

barış masalarında

ve en vahşi dansı sürer

binyıllardır

çocuklar ölsün diye

kılıçlar çekildi gene bak

binyıllardır hep çekilir

eski adamın dansı

umut çayırlarında

eski adamın dansı

umutsuzluk mezarlığında

eski adamın çığlıkları

çın çın

en izbe insaniyet loşluklarında', 'kılıçlar çekildi gene bak binyıllardır hep çekilir eski adam en vahşi çığlıklarını atar en sessiz çığlıklarını beyinlerde bedenlerde denizle...', ARRAY['Türk Edebiyatı','Şiir','Sururi Turan']::text[], 8.5, '{"poet":"Sururi Turan","poet_slug":"sururi-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/eski-adamin-dansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbete Yaşamak', 'gurbete-yasamak-kerem-alay-zhq95', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gurbette olanın kaynamaz aşı

Daima durmaz akar gözünün yaşı

Vade tamam olup bir gün ölünce 

Bir çalıdır üstünde mezarının taşı. 

Gurbet elinin dağlarını bir, bir aşarsa

Bir lokma ekmek için ordan oraya kuşarsa

Anadan, Babadan, Kardeşten ayrı yerse

Oturda düşün o kimsenin halini

                                             15,02,2005

                                              Kerem Alay

                                              Van', 'Gurbette olanın kaynamaz aşı Daima durmaz akar gözünün yaşı Vade tamam olup bir gün ölünce  Bir çalıdır üstünde mezarının taşı.  Gurbet elin...', ARRAY['Türk Edebiyatı','Şiir','Kerem Alay']::text[], 8.5, '{"poet":"Kerem Alay","poet_slug":"kerem-alay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gurbete-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-sururi-turan-ukzv4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uzanıp büküyor boynunu patika

sislerin arasında

kış ıslaklığına bürünmüş

kahverengi bir iğrençlik yapışmış

paçalarımıza

oramıza

buramıza

kurtuluşu olmayan bir lekedir

tüm yaşayacaklarımız

tüm zamanlarda

kahverengi mi

belki de kapkara', 'uzanıp büküyor boynunu patika sislerin arasında kış ıslaklığına bürünmüş kahverengi bir iğrençlik yapışmış paçalarımıza oramıza buramıza kur...', ARRAY['Türk Edebiyatı','Şiir','Sururi Turan']::text[], 8.5, '{"poet":"Sururi Turan","poet_slug":"sururi-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yol-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyuncak', 'oyuncak-nazim-ercan-vt2q5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir peluş oyuncaktı yaşam elimizde

Gözler yarı kapalı

Kırmızıya çalan zamanlarda

Bırakmıştık düşlerimizi

Sevginin tuvalinde iki yansı

Biri sen

Diğeri........? 

Çırak sevgilere terkettik yüreklerimizi

İki kuzgun uçuşu uzakta 

Soytarı sabahlar

Dağınık zamanlarımı

Toplama telaşındayım

Yüreğimin davetsiz misafirine

Bir türlü uyanamadığım sabahlar

Üçgen korkularımı fısıldıyor kulaklarıma

Çırak tutkulara terkettik sevdalarımızı

İki kırlangıç uçuşu uzakta

Zamansız sevdalar

Bir peluş oyuncak artık sevda ellerde

Aynaların yansısında 

Biri sen

Diğeri........? 

Tüm özlemlerin sonuna ulanmış

Sabahlar

Eğreti aşklarin çilingiri şimdi

Bir sessiz filmin kahramanı oldu AŞK

Bir yalnız peluş oyuncak

Ve

Biz

Özlemlerimiz. 

                                 Mart 2005', 'Bir peluş oyuncaktı yaşam elimizde Gözler yarı kapalı Kırmızıya çalan zamanlarda Bırakmıştık düşlerimizi Sevginin tuvalinde iki yansı Biri s...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/oyuncak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslan Mashadov', 'aslan-mashadov-taner-nisanci-at64j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nuru vurulmuş yüzüne,yatıyor

Yürekte acısı,canlar yakıyor

Ardınsıra gözlerden yaş akıyor

Şeyh Şamil torunu Aslan MASHADOV

Hubbül vatan minel iman aşkıyla

Kafkas kartalı düşmana coşkuyla

Yaratan emri dedi,gitti hakkıyla

Şeyh Şamil torunu Aslan MASHADOV

Bıkmadı asla,demedi el aman

Sırtını Hakka yasladı,her zaman

Beyoğlu bey,yiğitti,yahşi yaman

Şeyh Şamil torunu Aslan MASHADOV

Kalleş kurşunu alsada canını

Kim silebilir gönülden şanını

Bir garip benim,unutmam adını

Şeyh Şamil torunu Aslan MASHADOV', 'Nuru vurulmuş yüzüne,yatıyor Yürekte acısı,canlar yakıyor Ardınsıra gözlerden yaş akıyor Şeyh Şamil torunu Aslan MASHADOV Hubbül vatan minel...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aslan-mashadov-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben hem canım hem de şekerim', 'ben-hem-canim-hem-de-sekerim-mehmet-ali-suzen-zpnm5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben hem canım hem de şekerim 

Candan merhaba size 

Öyle ki tene hayat veririm 

Benimle yaşam bulur bedenler 

Beni hissettiğin sürece huzurlusun 

Unuttuğun anında, canım sıkıldı dersin 

Can sıkılmaz… Sıkma canını 

Nede kendini! 

Şekerim dersin 

Çayından, kahvenden eksik etmezsin 

Sabah kalkarsın, eğer ben yoksam sende 

Dilinde tadın kaçmış, bir haldesin 

Eksik etme, sende beni 

Hiç olmazsa, çantanda bir, şekeri 

Takatin kesilir, düşüncelerin bulanırsa 

Bir bakarsın şekerin düşmüş 

Enerjin kaybolmuş, hissedersin 

Al bir tane şeker, tadın gelsin 

Düşüncelerin sadeleşsin 

Gücün yerinde, yüzün neşeyle dolsun 

Ben varsam, tadın var hayatında 

Öyle yerdeyim ki sende 

Bensiz olmak imkânsız 

Ne azım, nede çok olduğum zaman, dayanılmazım 

Eksik etme, beni sende 

Erir giderim, hem çayında ve kahvende 

Hem de dilinde, kana karışır içinde 

Cana can katarım. 

Hem canın olur, tene can katarım 

Hem şekerin olur, tadın olurum hayatta 

Yok, olur giderim, hem teninde canımla 

Yok, olur giderim, hem dilinde tadımla 

Benim yokluğum bende acı tat sa 

Senin varlığında huzur bulmakta 

Mehmet Ali Süzen', 'Ben hem canım hem de şekerim  Candan merhaba size  Öyle ki tene hayat veririm  Benimle yaşam bulur bedenler  Beni hissettiğin sürece huzurlu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Süzen']::text[], 8.5, '{"poet":"Mehmet Ali Süzen","poet_slug":"mehmet-ali-suzen","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ben-hem-canim-hem-de-sekerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay Degil...', 'kolay-degil-mehmet-yilmaz-iu45v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kolay degil seni bir anda unutup,baska gönüllere kendini birakmak,

Kolay degil bunca aciyi sineye cekip, mutluluk hissine kapilmak,

Kolay degil bu kalbi, senden baska birine vermek,

Kolay degil adini yüregimden silip, bu askin sonuna nokta koymak.

Zor olmayacak ''Cekip git! '' demek,

Kolay olmayacak askima ''Dur'' demek,

Dudaklarim elveda sözcüklerini söylerken, yüregim kanayacak,

Kolay olmayacak sevda atesiyle yanan bedenimi, buz gibi kelimelerle sogutmak.

Kolay degil senden sonra beyaz bir sayfa acmak hayata,

Kolay degil sensizlige alisip, yalnizliga ortak olmak,

Kolay degil yoklugunu düsünmenin korkusuyla uykusuz geceler gecirmek,

Kolay degil siir gibi baslayan bir aska, bir cümleyle son vermek.

Bir gün senden benim gibi aydinliktan karanliga adim atacaksin,

O zaman aklina gelmem hic zor olmayacak.

Karanligin adiyim, günesin batisiyim simdi.

Yeniden aydinliga sarilmak ve yeniden günesin dogusuna ortak olmak senden sonra hic kolay olmayacak.

(16/02/05)', 'Kolay degil seni bir anda unutup,baska gönüllere kendini birakmak, Kolay degil bunca aciyi sineye cekip, mutluluk hissine kapilmak, Kolay de...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kolay-degil-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşekkürler', 'tesekkurler-ayhan-isin-i2mmm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhaba dosta, dostluğa, dost olan dostuma

Elimi uzattım; elimden tuttun

Bakmayı, bakıpta görmeyi öğrettin bana

Kayıp olmuş benliğimi buldum seninle

Uyandırdın beni yılların uykusundan

Bir defa daha güneşi gördüm

Aydınlattın beynimi

Benliğimi buldum

Teşekkürler sana

Dostluğuma; dostluğunla karşılık veren DOSTUMA

Bezmiştim, bıkmıştım hayattan

Veripte alamamaktan

Sahte dostlardan

Sevipte sevilmemekten

Sahte gülücüklerden

Yanlızdım, tek başınaydım kaybolmuştum,

Sen gelmeden önce

Bilirmisin? 

Onca insanın içinde yanlızlığı

Gülerken ağlamayı

Söylemek isteyip susmayı

Dolup, dolup anlatamamayı

Beklemeyi aylarca, yıllarca beklemeyi

Anlatamamayı! 

Umutla gerçek dostu beklemeyi

Dostluğu yüreğinde hissetmeyi

Güvenmeyi! 

Teşekkürler sana

Dostluğuma; dostluğunla karşılık veren DOSTUMA

Seninde bir hayatın vardı.

Beni kabul ettin

Yanlızlığıma renk kattın,

Heyecan kattın 

Yeni dostlar kazandırdın

Yol açtın, ufkumu açtın

Korkmadın,

Yılmadın,

Bezmedin. 

Teşekkürler sana

Dostluğuma; dostluğunla karşılık veren DOSTUMA

Çocukları çok severim bilirsin

Senin de sevdiğin gibi

Onlarda sahne yoktur, rol yoktur,

Seveni sever,

Sevmeyeni sevmez.

Dostluk gösterene, dostluk gösterir

Yalındır sevgileri,

Gönüldendir.

Onlar da küser, kırılır

Kırgınlıkları, küslükleri anlıktır

Gelir geçer çabuk affeder

İşte ben de öyleyim

Küsmeyi sevmiyorum

Barışı seviyorum

Sevmeyi,

Sevilmeyi,

Dostluğu seviyorum

Affetmeyi seviyorum

Biliyorum  ki sende öylesin

Teşekkürler sana

Dostluğuma; dostluğunla karşılık veren DOSTUMA

Dostluğun kadını erkeği olmaz,

Bunu bazıları  bilmez

Anlayamaz

Anlamak için eğitim yetmez,

Yaşamak gerek,yaşamak

Gerçek dostlar sonzuza kadadır

Nikah masasında bitmez

İnsan yaşadıkça aşık olur sever

Bunu eşine anlatabilirmisin? 

Yıkmak pahasına sevgileri

Yaşanmışları

Seni anlarmi? 

Söylemek istersin; susarsın! 

Dost öylemidir; ya! 

Sırlar gizemler Dostluğun kardeşidir,

Pekiştirir dostlukları

Seni tek dostun dinler

Tek dostun anlar. 

Teşekkürler sana

Dostluğuma; dostluğunla karşılık veren DOSTUMA

(24-01-2005)', 'Merhaba dosta, dostluğa, dost olan dostuma Elimi uzattım; elimden tuttun Bakmayı, bakıpta görmeyi öğrettin bana Kayıp olmuş benliğimi buldum...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Işın']::text[], 8.5, '{"poet":"Ayhan Işın","poet_slug":"ayhan-isin","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/tesekkurler-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkinda misin?', 'farkinda-misin-mehmet-yilmaz-idjdw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Farkinda misin rüzgarin seni nasil savurdugunun? 

Dua et yagmur baslamasin,

Hele doluya hic dayanamazsin,

Günesi kovduktan sonra.

Farkinda misin hayatin seni nasil sorguladiginin? 

Hazirlikli ol! aydinliktan karanliga adim atacaksin,

Hele yalnizliga hic dayanamazsin,

Isigi söndürdükten sonra.

Farkinda misin hayatin aslinda bir yalan oldugunun ? 

Umutlu olma senden bir yalan olacaksin,

Gercekler en büyük düsmanin olacak,

Dogrulugu kaybettikten sonra.

Farkinda misin benim kim oldugumun? 

Tanidikca, anladikca yikalacak paramparca olacaksin,

Beni kaybettigin icin yüregine haykiracaksin,

Yok oldugunu anladiktan sonra.

Farkinda misin yasadiklarinin ? 

Aslinda yasamayi hakketmediginin farkina varacaksin,

Arkanda gizli, sakli bombos bir ucurum bulacaksin,

Geriye dönüp baktiktan sonra.

Farkina varacaksin artik ''Ben'' diye bir sey oldugunun,

Sevginin ne anlama geldigini ögrendikten sonra,

Sevgi sözcükleri dökülecek dudaklarindan,

Ama cok gec artik ''Ben'' diye bir sey olmayacak hayatinda.

(07/03/05) 

_________________________________________

Farkinda olmak vardi bir de farkinda olmamak,

Farkina vardin farkinda olmamanin farkliligini.', 'Farkinda misin rüzgarin seni nasil savurdugunun?  Dua et yagmur baslamasin, Hele doluya hic dayanamazsin, Günesi kovduktan sonra. Farkinda m...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/farkinda-misin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskisi Gibi Değil', 'eskisi-gibi-degil-sahin-erturk-ze1hp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne sen eski SEN sin? 

Ne ben eski BEN im? 

Kabullenmeliyiz bu gerçeği

Fiziksel değiştik

Ruhsal değiştik

Hiç birşey

Eskisi gibi değil

Beşinci mevsime

Hazan mevsimine

Geleli aylar oldu

Hiçbir şey

Eskisi gibi değil

Bu şehir bile değişti

1970 lerdeki gibi değil

Yaşanası olmaktan çıktı

Hava kirliliği 

Çekilmez boyutlarda

MERKEZ hanı yıkıldı

CUMHURİYET caddesi

Mecburiyet caddesi oldu

HÜLYA lokantası

ŞARK lokantası

Birer,birer kapandı

Çorbacı EMİN in

Saltanatı çoktan bitti

Lokantalar,pastahaneler

Antepliler in eline geçti

Şekiller,simalar değişti

Sevgi erozyona uğradı

Kimse,kimseyi takmıyor

Bu şehirle birlikte

Bizlerde değiştik

Bizlerde yaşlandık

Dündeki bizlerin yerini

Çocuklarımız aldı...? 

Onlarında düşünceleri

Yaşamları değişti? 

Hiçbir şey

Eskisi gibi değil

Değil güzelim değil

Artık hiçbir şey

ESKİSİ GİBİ DEĞİL,DEĞİL

(10.03.2005-Yeni)', 'Ne sen eski SEN sin?  Ne ben eski BEN im?  Kabullenmeliyiz bu gerçeği Fiziksel değiştik Ruhsal değiştik Hiç birşey Eskisi gibi değil Beşinci...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/eskisi-gibi-degil-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-i-smail-sahin-ro2uq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamak; 

Azapta hatırasız balık misali.

Yaşamak; 

Savaşta gaygısızca çocuk misali.', 'Yaşamak;  Azapta hatırasız balık misali. Yaşamak;  Savaşta gaygısızca çocuk misali....', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yasamak-123-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaire Dokunma', 'saire-dokunma-sevinc-basbug-q6lhq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şaire dokunma,

Dokunulmaz şaire..

Tutar kulağından bulduğu yerde ellerini

Ve söylemeden bırakmaz

Sevdasını..

Susar sanma kafasındaki yüreğini,

Okumasını bilirsen alırsın

Ana düşüncesini..

Bir tek bakış,

Tek bir çift göz yeter

Sana sevgisini anlatmaya..

Dokunma sen şaire

Anla tebessümünü

Oku gözlerini..

Cevapsız yollarda yürümeye alışıktır şair

Kendi çözer düğümlerini kimsesiz seyirlerde

İnadına umut eğirirken kasım patı sahillerde..

Şair,

Şairi olacağı yüreği bulana kadar

Yüreklerde yürek aramaya devam eder,

Yorulmaz,

Yaşlanır..

Ve eğer varsa cesaretin

Tutarsın kaleminden 

Çeker çizersin satırlarını 

Ve kendince bir dize eklersin,

Yani şairin şairi olursun,

İşte o zaman

Beklenen şiir yazılınca yani,

Yani

Şiirin kendisi olunca

İşte o zaman

Dokun şaire..

Çünkü, aslında

Dokunulur

Şaire.', 'Şaire dokunma, Dokunulmaz şaire.. Tutar kulağından bulduğu yerde ellerini Ve söylemeden bırakmaz Sevdasını.. Susar sanma kafasındaki yüreğin...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Başbuğ']::text[], 8.5, '{"poet":"Sevinç Başbuğ","poet_slug":"sevinc-basbug","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/saire-dokunma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu', 'anadolu-suleyman-kaya-zu6ql', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çırpınırdı Karadeniz 

azgın dalgalarıyla,

bir sevdaya tutulmuştum

unutulmaz anılarıyla,

Kıvranırdı Güneydoğu Anadolu

güneşli,aydınlık günleriyle

heder oldum,beter oldum

terörle anılan adıyla

Yelpazeler açar martılar

inci gerdanlı istanbul''a

hey ya, hul la! 

marmara bahtın mı kara? 

İç Anadolu için için dolu

geçer sende Mevlana yolu

Hacı bektaş kulu 

dergahın hep deli dolu

Vardım efeler diyarına,ne efelik

ne de mertlik kalmış sende

zeytin dalın kurumuş

barış sözcüğü ağızlarda gemlik

Serin serin rüzgarların esermiş

torosun derin vadilerinden,

Çukurovaların kurumuş

incirlerini başkaları yermiş

Unuturmuyum seni,gün doğumu

ilkin senden uyanır canlar

serhat ellerinden nağmeler var.

o nağmeler ki; sarar vuslatı ruhumu

Hey koca Anadolu! 

bağrında nice millet dolu

dini,dili,sağlı,sollu ne olursa olsun

yer,içer,tapar, yatar toprağında

Yeter ki kardeşçe olsun..! 

her şey beraberce yapılsın,

sen,şu sun,ben,buyum denilmesin

bu topraklar hepimizin olsun!', 'Çırpınırdı Karadeniz  azgın dalgalarıyla, bir sevdaya tutulmuştum unutulmaz anılarıyla, Kıvranırdı Güneydoğu Anadolu güneşli,aydınlık günler...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Kaya']::text[], 8.5, '{"poet":"Süleyman Kaya","poet_slug":"suleyman-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/anadolu-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek Yüzlü', 'melek-yuzlu-abdulhakim-ozturk-m9fv9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'MELEK YÜZLÜ

İnsan gayrı bilinmiyor yüzünden

Yol bilinir görünmekle izinden

Bakarsın bal şeker akar sözünden

İçi fesat dışı melek gibi olur

A.Hakim bu aşkı sen zevkle yaşa

Nice erler olmuş subay paşa

Bilen bilmiş yolu götürmüş başa

Benim gibi nice insanlara

Ferhat gibi dağı taşı delmedim

Kerem gibi aslı diye yanmadım

Seyrettim dünyayı geri dönmedim

Gönül bahçesini burada suladım

Almışız kokusunu mor sünbülün

Koklayıp doymuşuz kokusunu gülün

Eğer cennet ise muradı kulun

Yaradan buyurur zeki kulun.

					A.Hakim ÖZTÜRK

					    Nisan 1995', 'MELEK YÜZLÜ İnsan gayrı bilinmiyor yüzünden Yol bilinir görünmekle izinden Bakarsın bal şeker akar sözünden İçi fesat dışı melek gibi olur A...', ARRAY['Türk Edebiyatı','Şiir','Abdulhakim Öztürk']::text[], 8.5, '{"poet":"Abdulhakim Öztürk","poet_slug":"abdulhakim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/melek-yuzlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimbilir?', 'kimbilir-mehmet-yilmaz-8ql03', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düsünecek cok az sey kalmisti,

Yalan, dogrularin önüne coktan gecmisti,

Sevgiler yok oluyor, askin nesli tükeniyordu,

Gercek olan sahteye dönüsüyordu,

Ve ben bu anlamsizliga bir türlü anlam bulamiyordum.

Yalnizdim artik, yapayalniz tek basima,

Basimi yasliyacak insan coktan gitmisti karanliga,

Unutmak en zor sey olmustu,

Beyaz bir sayfa acamiyordum hayatima.

Ucurumun kenarindaydim sanki,

Biri itse düsecegim ve kolumdan tutacak biride olmayacak biri,

Caresizlik, umutsuzluk pesi sira etrafimda,

Kurtulmam mümkün degildi.

Beni ayakta tutan sevgim gün gectikce degerini yitiriyordu,

Karanliga düsmüstü, aydinligini o da kaybetmisti,

O da hakliydi kime sunacakti benligini,

Dogru olan kimse kalmamisti, yalan ona göre degildi.

_____________________________________

Kim bilecek bendeki sevginin büyüklügünü,

Yüregine güvenen kim kalmisti ki? 

Cesaret ister yüregimin kapilarindan iceriye girmeye,

Korkak bir asik, yüceltemezdi sevgimi.', 'Düsünecek cok az sey kalmisti, Yalan, dogrularin önüne coktan gecmisti, Sevgiler yok oluyor, askin nesli tükeniyordu, Gercek olan sahteye dö...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kimbilir-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefis', 'nefis-abdulhakim-ozturk-w4b7n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'EY NEFİS

Ey nefsim sen nesin söyle bileyim

Kudret olsun defterini göreyim

Semadan mı yoksa yer yüzlümüsün

Bazı kalpte oturan vezir misin

Kayık oldun attın suya küreğin

Gemi oldun yıktın yelken direğin

Yiğitmisin çatalmı dır yüreğin

Sırtları yere vuran pehlivan mısın

Derdim çoktur misli nehri fıratın

Gönül derki geçerim ben sıratın 

Oku gafil hanı senin ber-atın

Cennette girmeye sen emin misin 

İnsanları doğru yoldan şaşırdın

Nefsi isyan başlarından aşırdın

Tırnağın olsa başını kaşırdın     

Zalim nefs tevbeye yeminli misin

	

Evvelin geç ahırın düşün 

Bağlan kur’ana onda nisbet üstün

Teslim ol sen varlığınla büsbütün

Söylesem derler telal mısın

Hak bize göz vermiş bakıp görmek için

Hak yolunda gece gündüz çalışmak için

Ey A.Hakim bunca dertler niçin

Hakkı bil sen, nefs hamalı mısın? 

Gizlice gelir mecliste oturur 

Feyzi muhabbeti alır götürür 

Şeytanı kalbinde gizli getirir

Muhabbeti bozmaya yeminli misin 

			A.Hakim ÖZTÜRK

			   Müküs 1995', 'EY NEFİS Ey nefsim sen nesin söyle bileyim Kudret olsun defterini göreyim Semadan mı yoksa yer yüzlümüsün Bazı kalpte oturan vezir misin Kay...', ARRAY['Türk Edebiyatı','Şiir','Abdulhakim Öztürk']::text[], 8.5, '{"poet":"Abdulhakim Öztürk","poet_slug":"abdulhakim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/nefis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen vardin...', 'sen-vardin-mehmet-yilmaz-hy3k5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gercekleri senden asla saklayamazdim,

Hayatimda sen vardin, seni yok sayamazdim,

Yüregimde besledigim, büyüttügüm sevgi vardi, paylasmak zorundaydim,

Biksanda, usansanda ben yilmayacaktim.

Hayatima seninle yeni bir sayfa acmaliydim,

Her sayfa da seni okumaliydim,

Ictigim su, aldigim nefes yalniz sen olmaliydin,

Seni unutup, bu askin sonuna nokta koyamazdim.

Ben senin gözüne,kasina vurulmamistim,

Yüregindi beni bu sevdaya sürükleyen,

Bedenin degildi beni bu hale düsüren,

Ruhun kanatlandirmisti beni,kirmamaliydin kanadimi.

Bak sevdigim, bütün sevgimi sana bagisladim,

Yok ettim kendimi, senin varligina sakladim,

Buralarda ''Ben'' diye bir sey yoktu artik,

Gercek olan buydu, kendimi daha fazla kandiramazdim.', 'Gercekleri senden asla saklayamazdim, Hayatimda sen vardin, seni yok sayamazdim, Yüregimde besledigim, büyüttügüm sevgi vardi, paylasmak zor...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-vardin-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem', 'deprem-abdulhakim-ozturk-9gxzc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'DEPREM

Bir çocuk ağlıyordu sokakta

Annem annem diye çığlıklar atıyor

Oysa annesini çılgın sular almış götürmüştü

Dünyadan, depremden habersizdi garibim

Ey Allah’ım sen yardım et 

Bizleri yoktan var eden sen….

Başımıza felaketleri getiren sen

Bizi her kötülükten kurtaracak sen

Merhameti ve bereketi çok olan sen

Bizi kereminle sevindir ya rab….

			A.Hakim ÖZTÜRK

                                     Bahçesaray  2005', 'DEPREM Bir çocuk ağlıyordu sokakta Annem annem diye çığlıklar atıyor Oysa annesini çılgın sular almış götürmüştü Dünyadan, depremden habersi...', ARRAY['Türk Edebiyatı','Şiir','Abdulhakim Öztürk']::text[], 8.5, '{"poet":"Abdulhakim Öztürk","poet_slug":"abdulhakim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/deprem-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikkat', 'dikkat-kadir-soyturk-o894p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer iyi gidersen, nice dağlar aşarsın; 

Yürümeyi bilmezsen, düzde bile şaşarsın!', 'Eğer iyi gidersen, nice dağlar aşarsın;  Yürümeyi bilmezsen, düzde bile şaşarsın!...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/dikkat-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fikret', 'fikret-esra-aksu-uto6o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kül de sıcaktır düştüğü yerde

Ateş gibi yakmıyor her nedense

Fikret! sana soruyorum,hadi söyle

Neden tutuşmuyor eşya kül renginde?', 'Kül de sıcaktır düştüğü yerde Ateş gibi yakmıyor her nedense Fikret! sana soruyorum,hadi söyle Neden tutuşmuyor eşya kül renginde?...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/fikret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Dünya Kadınlar Günü *', 'dunya-kadinlar-gunu-gulsen-senderin-56ynj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '*Dünya Kadınlar Günü* sekiz martta kutlanır

En etkin söylemlerle gündem budur her yerde

Dinletiler yayınlar, tüm medya kanatlanır

Kadınlar baş tacımız, saygı görür her yerde! 

Sevgi Hanım mecliste beş lisanlı bir bakan

Evrensel değerlerle topluma sahip çıkan

İnsan sorunlarıyla sistemde denge kuran

Kadınlar baş tacımız, saygı görür her yerde! 

Gece nöbetlerinde olmaz bir endişesi

Çalışan annelerin kreşte büyür bebesi

Doğum izni süt izni, hakların câzibesi

Kadınlar baş tacımız, saygı görür her yerde! 

Bilgisayar ağıyla Fatma köyünde muhtar

Nüfus planlamasına ebe Hatice bakar

Sevda öğretmen ise ekibiyle seferber

Kadınlar baş tacımız, saygı görür her yerde! 

Kültürlü tüm kadınlar el birliği ettiler

Okumayı yazmayı sabırla öğrettiler

Kitap gereç toplayıp, her yere ilettiler

Kadınlar baş tacımız, saygı görür her yerde! 

Örf adet töreler; kadından yana değişti

Mal mülk yasası, gereken düzeye ulaştı

Zorunlu evlilikler, tekelliğini aştı

Kadınlar baş tacımız, saygı görür her yerde! 

Tecavüz kayıt dışı, tarih bunu hep yerdi

Ne dayak ne hakaret, kumalık sona erdi

Başlık parasına son; tüm erkekler söz verdi

Kadınlar baş tacımız, saygı görür her yerde! 

Yaşam bir bölüşümdür, dünya bunu biliyor

Çalışan kadınlara, hakları veriliyor

Dayanışma içinde bütün yüzler gülüyor

Kadınlar baş tacımız, saygı görür her yerde! 

Atatürkçü Düşünce kültürel bir tasarım

Kadına değer vermek, geleceğe yatırım

Yetişecek bireye;  şahsiyette artırım

Kadınlar baş tacımız, saygı görür her yerde! 

Eşitlik yasasıyla kadının bir adı var

Anne baba çocuklar, saygınlığın şadı var

Düzeyli bir toplumda, mutluluğun tadı var

Kadınlar baş tacımız, saygı görür her yerde! 

Kadın hakları; insan haklarının esası

Ayrımcılık yok artık, yürürlükte yasası

Kadın yalnız değildir, kanunlar güvencesi

Kadınlar baş tacımız, saygı görür her yerde! 

Hayatın her dalında kadındır onurumuz

Aile içi düzen, yapısal gururumuz

Birtek gün için değil, ömür boyu varımız

Kadınlar baş tacımız, saygı görür her yerde!', '*Dünya Kadınlar Günü* sekiz martta kutlanır En etkin söylemlerle gündem budur her yerde Dinletiler yayınlar, tüm medya kanatlanır Kadınlar b...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/dunya-kadinlar-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Randevu', 'randevu-esra-aksu-6362q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Herkes ayrılığın vuslata döndüğü 

Yerde bekler sevdiğini

Bense vuslatın ayrılığa döndüğü

Yerde bekliyorum seni...', 'Herkes ayrılığın vuslata döndüğü  Yerde bekler sevdiğini Bense vuslatın ayrılığa döndüğü Yerde bekliyorum seni......', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/randevu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-esra-aksu-qfwgr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen hep rüzgarın saçlarını taradın ellerinle

Bense hep rüzgar oldum düşlerimde...', 'Sen hep rüzgarın saçlarını taradın ellerinle Bense hep rüzgar oldum düşlerimde......', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ruzgar-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lacivert,Yeşil ve Güzel Yürek', 'lacivert-yesil-ve-guzel-yurek-asli-yildiran-j3d7r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana yaşattığın herşey için iyi ve kötü hepsi için teşekkür etmek istiyorum

Yaşanması gereken herşey yaşanır ve yaşanacaktır

Yüreğim değişmez bu oyunun içinde sadece bir oyuncudur

Onun içindir ki ne seni, ne kendimi nede yüreğimi suçlamayacağım 

çektiğim hasret,ağladığım geceler ve sensizlik için

Seni düşünüyorum sık sık

Seni, bana verdiğin herşeyi umudu,sevgiyi,sensizliği hepsini

ve hiç unutmuyorum bol yıldızlı bir temmuz gecesinde mısır ve kağıt helva yediğimizi

Denizde sektirmeye çalışarak fırlattığımız taşları

Yüreğine yüreğine  fırlatmıştık taşları Marmaranın

Cezasız kalmaz hiçbir kötülük yüreğimize yüreğimize saplandı ayrılık şimdi ikimizde yalnızız

Senden ayrıldıktan sonra mevsim hep kış oldu bu yerlerde

ve hep acıklı bir türkü çalınıyor “sağım yalan,solum yalan” diye

Geçenlerde bir anımızı hatırlattı bana, üzerime dökülen vişne suyu

Pantolonuna dökülen vişne suyunu anımsadım tahmin edebileceğin gibi

İyi ki lacivert gömleğine gelmemişti,

Biliyorsun sen lacivertin yeryüzünde en çok yakıştığı insandın 

En azından ben hiç bu kadar yakıştığı başka birini tanımamıştım

Sadece lacivert değildi tabi sana yakışan; gül yaprağından daha yeşil gözlerin, ellerin ve o güzel yüreğin ne çok yakışırdı sana

Bu sebeptendir laciverte,yeşile ve güzel yüreklere olan sevgim

Ve yine bu sebeptendir ki yerine hiçkimseyi getiremeyişim, seni yüreğime hapsedişim.

Bu sana kaçıncı yazıpta yollayamadığım ve hıçkırıklara boğulurken gözyaşlarımda yüzdürdüğüm mektubum bilmiyorum.', 'Bana yaşattığın herşey için iyi ve kötü hepsi için teşekkür etmek istiyorum Yaşanması gereken herşey yaşanır ve yaşanacaktır Yüreğim değişme...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/lacivert-yesil-ve-guzel-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vehim', 'vehim-esra-aksu-l1p02', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elif gibi yaşar yalnızlığını

Elif gibi yaşarken yalnızlığımı

Ahmaktır ki bilmez,

İki elif yan yana gelmez! 

Bana bir he gibi yorulup

Kıvrılmak düşer dizlerinin dibine.

Görülmüş şey midir ah olanın

Tutuşmadığı ateşte,ve yine

Görülmüş şey midir küllerin

Savrulmadığı badın peşinde...

Ve yine görülmüş şey midir vuslatın

Ayrılığı döndüğü yerde beklemek

Görülmüş şey midir ayrılığın

Vuslata döndüğünü vehmetmek 

                                               bir akşam üstü?', 'Elif gibi yaşar yalnızlığını Elif gibi yaşarken yalnızlığımı Ahmaktır ki bilmez, İki elif yan yana gelmez!  Bana bir he gibi yorulup Kıvrılm...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/vehim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-esra-aksu-vkub5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman ki buz diye tutmam

    Bir köşede erir gider

    Zaman ki bir selamı esirger

Sessiz sedasız çekip gider', 'Zaman ki buz diye tutmam     Bir köşede erir gider     Zaman ki bir selamı esirger Sessiz sedasız çekip gider...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zaman-182-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sabır', 'ya-sabir-esra-aksu-e3icn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül yapraklı papatya beklememeyi 

Öğretir hayat,sardunya ekili saksıdan...

Ne sardunya ektim saksılara

Ne de gül dedim papatyaların adına

O yüzden Ya Sabır çekiyor ellerim

Varana dek adaklar adanmış vuslatına.', 'Gül yapraklı papatya beklememeyi  Öğretir hayat,sardunya ekili saksıdan... Ne sardunya ektim saksılara Ne de gül dedim papatyaların adına O ...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ya-sabir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin', 'yemin-esra-aksu-0ffr2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay başıma düşsün

Yıldızlar parçalansın

Seviyorum seni! 

Güneşi tutayım yaz ortası

Karda uyuyayım ki

Seviyorum seni!', 'Ay başıma düşsün Yıldızlar parçalansın Seviyorum seni!  Güneşi tutayım yaz ortası Karda uyuyayım ki Seviyorum seni!...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yemin-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluktan Yetişkinliğe', 'cocukluktan-yetiskinlige-erdogan-ergin-p14v6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk kez o gün ayrıldı annesinden

Elinde tüm ağırlığı ile çantası

Çeşit çeşit kitap, yol gösterici

Kimi fen, kimi hayat bilgisi

Oysa ne hayat

Ne anlatan biliyor kitabı

Ne de dinleyenin var ilgisi

Bir süre taşıdı çocuk, çantasını

Yorulduğunu hissetti

Durmak istiyordu

Durup karar vermek...

Dinlemediler bile

Çantasına bir kaç yük daha

Biraz sosyal, biraz coğrafya

Haydi yavrum yoluna

-zaman geldi.Dedi anne

Ayrılık vakti

Seç kendine birini

Uygula dersten öğrendiklerini

Düş yollara, taşı geleceğini

Seçti çocuk, yetişkinliğini

Şimdi bir yetişkinliktir, çantasında ki yük

Ne zaman başladı bilinmez taşımaya

İçinde ne hayat bilgisi, ne  de fen

Biraz umut, bol bol ümit', 'İlk kez o gün ayrıldı annesinden Elinde tüm ağırlığı ile çantası Çeşit çeşit kitap, yol gösterici Kimi fen, kimi hayat bilgisi Oysa ne hayat...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cocukluktan-yetiskinlige-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-arif-buk-p9cy8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağaçlar yere gölgeler sermiş,

Batar da güneş düşer ayrılık.

Akarak büyür uzar ırmaklar,

Kavuşur denize düşer ayrılık.

Varılır bir yere yakın ve uzak,

Gurbette sineye düşer ayrılık.

Azrail gelir hıçkırır ruhlar,

Alır da birini düşer ayrılık.', 'Ağaçlar yere gölgeler sermiş, Batar da güneş düşer ayrılık. Akarak büyür uzar ırmaklar, Kavuşur denize düşer ayrılık. Varılır bir yere yakın...', ARRAY['Türk Edebiyatı','Şiir','Arif Bük']::text[], 8.5, '{"poet":"Arif Bük","poet_slug":"arif-buk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-229-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğacak Kızıma ''Dokundukça''', 'dogacak-kizima-dokundukca-erdogan-ergin-ylyvg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlk dokunmayı öğrenceksin

İçinden bir şey dokun diyecek 

Dokunacaksın

Bana; babana

Annene

Eşyaya, biberona, suya

Hatta kedi köpeğe bile dokunacaksın

Sonra; 

Neyi tuttuysan fırlatıp atacaksın

Bir bize kıyamayacaksın

Günler geçecek

Sen dokundukça öğreneceksin

Biz ise sen dokundukça sevineceğiz

İyi ki varsın diyeceğiz', 'İlk dokunmayı öğrenceksin İçinden bir şey dokun diyecek  Dokunacaksın Bana; babana Annene Eşyaya, biberona, suya Hatta kedi köpeğe bile doku...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dogacak-kizima-dokundukca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlım', 'daglim-abdurrahman-samyurek-tvwwl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dağlım

kara günlerde sevdalım

dağlarda belalım yürek yangınım

şiiri

yüreğim', 'dağlım kara günlerde sevdalım dağlarda belalım yürek yangınım şiiri yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Samyürek']::text[], 8.5, '{"poet":"Abdurrahman Samyürek","poet_slug":"abdurrahman-samyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/daglim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Duvar Bir Pencere', 'dort-duvar-bir-pencere-esra-aksu-azhse', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kulakların çınlıyor mu? 

Seni konuşuyoruz 

Dört duvar bir pencere

Ha desen yıkılacak kadar üzgün...

Bir o kadar gururlu...

Ayaktayız işte\yaşıyoruz

Kulakların çınlıyor mu? 

Sana susuyoruz

Dört duvar bir pencere

Ha desen ağlayacak kadar sürgün...

Bir o kadar yetim...

Ayaktayız işte\yaşıyoruz', 'Kulakların çınlıyor mu?  Seni konuşuyoruz  Dört duvar bir pencere Ha desen yıkılacak kadar üzgün... Bir o kadar gururlu... Ayaktayız işte\ya...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dort-duvar-bir-pencere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanacak Şehirler', 'yanacak-sehirler-esra-aksu-0dkgy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Titrek bir gariplik sardı her yanımı

Ben duruyorum,o kanat çırpıyor

Alıp kucağına beni,tarihimi gezdiriyor

Bedenimden kopararak canımı

Soğuk şehrin suskun evin havasından 

Sımsıcak göğsüne uzanıyorum anıların

Cevabı yok bu vakit sorulacak soruların

Bir yüreğin amansız kasırgasından

Hiçbir çiçek gülmüyor özünden bulutlara

Hepsi diken taşıyor,dokunamıyorum korkudan

Yeşil diye mi kaçıyorum yoksa yaprağından

Sanki her çiçek mecbur sarmaşık olmaya

Bulamadım düşlerin gardırobundan aşk’

Kurdeleyle süsleyip bırakacaktım kapına

Ak düşmeyecekti hiçbir vahit saçlarına

Çekmeyecektin derinden ah’ları

Karmaşık duygular yaşıyorum senden uzakta

Müptela olmuşum dokunmadığım avuçlarına

Bir kibrit alevi dönüyorsa koskoca yangına

Söyle! Yanacak kaç şehir kaldı daha...', 'Titrek bir gariplik sardı her yanımı Ben duruyorum,o kanat çırpıyor Alıp kucağına beni,tarihimi gezdiriyor Bedenimden kopararak canımı Soğuk...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yanacak-sehirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılgı', 'yanilgi-esra-aksu-ymvhx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğrudur,bir zamanlar yollarımız kesişti

Ama,ben sizin bindiğiniz trene hiç binmedim

Aynı tünelin karanlığında koştuk ışığa

                                              raylar üstünde

Aynı yalnızlığın gürültüsüyle kıvrandık

                               akşamın dar vakitlerinde

Doğrudur,bir zamanlar yollarımız kesişti

Ama,ben sizin bindiğiniz trene hiç binmedim!', 'Doğrudur,bir zamanlar yollarımız kesişti Ama,ben sizin bindiğiniz trene hiç binmedim Aynı tünelin karanlığında koştuk ışığa                 ...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yanilgi-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çeşit Hastalık', 'bir-cesit-hastalik-esra-aksu-lbsxz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalp ağrısı,uykusuzluk...

...şikayetiyle doktora gittim.

Önce muayene,sonra bir dolu tahlil,

Seni bulmuşlar kanımda! 

Tanımıyorum dedim; 

Yediklerimden oldu herhalde...

Bir çeşit hastalıkmışsın.

Öldürmezmişsin lakin

Güldürmek de yokmuş kitabında.

Deniz,ay ışığı,martı sesi yasak,

Taze fasulye elma körüklermiş,

Bir de kahve dediler

İçersem mezara sürüklermiş.

Üsküdar dedim,Çamlıca dedim

İstanbul bile olmaz dediler; 

Yahu tanımasam inanacaktım

Seni sevdiğim teşhis ettiler.

-Sahi öyle misin?', 'Kalp ağrısı,uykusuzluk... ...şikayetiyle doktora gittim. Önce muayene,sonra bir dolu tahlil, Seni bulmuşlar kanımda!  Tanımıyorum dedim;  Ye...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-cesit-hastalik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bismillah', 'bismillah-esra-aksu-ubfcp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarıyla yıkanmış bir cesedin

Mis gibi gül kokusu sızar 

Bembeyaz kefenler arasından.

Gül rayihası yüreğinden gelir

Yüreğindeki sevdaya dair.

Kefen rengini yüreğinden alır

O ki mahşere dek üstünde kalır.

Kara toprak ağır gelmez ona

O ki kara sevdayla yaşadı yıllarca.

Münker sorar:Kimi sevdin,

Nekir sorar:ne kadar sevdin.

Gül kokulu bembeyaz kefenin

Sımsıkı sardığı ruh haykırır:

Onun şahsında Rabbimm’i sevdim! 

Emir gelir Hakk’tan:

Açılsın mü’min kuluma cennetin kapıları

“Allah için birbirlerini sevenlere

Benim sevgim haktır”

Cemalim,rızam o kulumundur artık.

Cümle melek haykırır “Sübhanallah”

Kul haykırır “Elhamdulillah”

Ve yüreğindeki sevdayla girer cennete

                                                            “Bismillah”', 'Gözyaşlarıyla yıkanmış bir cesedin Mis gibi gül kokusu sızar  Bembeyaz kefenler arasından. Gül rayihası yüreğinden gelir Yüreğindeki sevdaya...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bismillah-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaza Vurulan Yüreğin Şarkısı', 'ayaza-vurulan-yuregin-sarkisi-atilla-guler-kve0w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yatağıma kıvrılmış

soğuk bir yılan

yalnızlık

yavşak

kaygan

soğuk bir gün daha

çaldığında bedenimi

düşlerimin sıcak

koynundan

yılgın ayak sesleri

çıldırtan sessizlikte

ne senden eser var

ne güneş doğuyor

bu denli yaşanmışlık

sonrasında yine de

sıcağı vurdu yüreğe

sensizlikte daha da

büyüyen sevdanın

ve ne çok üşüdüm

yanımızda getirdiğimiz

mesafelerin ayazında

kırıntılarını topladığım

tutkularımın alı yakıyor

gönlümü

ellerime aldığımda yüreğini

yüreğim şarkılar söylüyor

sevdaya

…yeniden', 'yatağıma kıvrılmış soğuk bir yılan yalnızlık yavşak kaygan soğuk bir gün daha çaldığında bedenimi düşlerimin sıcak koynundan yılgın ayak ses...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ayaza-vurulan-yuregin-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuhaf Bir Duygu', 'tuhaf-bir-duygu-esra-aksu-dei7b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O gecenin sabahında Ümmü Gülsüm’ü

Dört ay sonrasında Nazım abiyi kaybettik

Tuhaf bir duygu şu kayıp haberi

İnsan kendini beklerken...

Yani şaşırmayan bünyeye şaşkınlık! 

O gece dedim de,fısıldadığın gece gönlünü

Sevdamızın tertemiz mazisini kaybettik

Tuhaf bir duygu şu kayıp haberi

İnsan her şeyi unutmuşken...

Yani sağlam bünyeye hastalık! 

O gecenin sabahında soldu çiçeklerin tümü

Yıldızları,mehtabı o kargaşada kaybettik

Tuhaf bir duygu şu kayıp haberi

İnsan bir tel,bir duvak beklerken...

Yani sevdalı bünyeye bünyeye vefasızlık!', 'O gecenin sabahında Ümmü Gülsüm’ü Dört ay sonrasında Nazım abiyi kaybettik Tuhaf bir duygu şu kayıp haberi İnsan kendini beklerken... Yani ş...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/tuhaf-bir-duygu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birden İki Damla Düşer..Ölüm Ölür.', 'birden-i-ki-damla-duser-olum-olur-tulay-eker-guv20', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tutsam dokunsam dersin yaşamın telleri dokunur parmakların kanar.

 Kan ağlardı 

 Bulaşırdı rengi

 Göz çıban

 Akardı aynı nehirde

 Buluşacaklar gibi

 Vakit sessizlik..İpi kopuk uçurtma avare,yürekte har ölesi tutmuş uçmakta.

 Dudak kıvrımında tebessüm

 Sen olmuş

 Bir buse 

 Tadı anzer balı

 Yanar ciğerin

 Diğer yanı

 Boşluğu dolduran

 Yaşam adı

 Sessizliğin ertesi sensizlik..Saatin tiktakları susmuş vurur çıldırsıya içime ölüm saati

 Ölüm ne ki bedene

 Yazarken,düşünürken 

 Hissetmek

 Gülümserken birden yokluğuna

 Düşmek

 Ölmekten öte 

 Beterdir bilene

 Sen yoksan 

 Ölüm ne ki de hele



 Düşlerken..Düşlerim düş olup seyrederken hayatın sunduğu hediye adın,hediyemle yaşadı adım

 Dokunur titrek ellerim

 Düşerken gözlerime gülüşün

 Serin fırtınalar kopar

 Geçersin bu yoldan 

 İşte derim yaşıyorum

 Ne güzelsin sevdiğim

 Ömrüme ömür bildiğim

 Hoşgeldin der sol yanım..Hoşgeldin...Tutulurum..Seni sana anlatmaya lal olur dilim



 Kelimelere sığdıramağım

 Gülen yanım

 Sımsıkı yumarım gözlerimi

 Gitme kal diye

 Ellerim birleşir ellerinle olur

 Hissederim

 Sevgin Munzur olur Nemruta giderim

 Dicle Fırat sahile vurur 

 Semaya çıkar şavkın

 Ben o zaman nefeslenirim

 Senle verdiğin hediyenle

 Adınla,gururla başım diklenir

 Yaşıyorsun işte derim yaşıyorsun

 Yani senle..

 Seninle adım yaşamak! 

 Birden iki damla düşer kanıma fırtına kopar... soğuk! 

 Uyanırım senli düşlerden

 Uyanıkken kanım ölür

 Ben sensiz hep

 Ölüyüm

 Ölüm

 Ölür', 'Tutsam dokunsam dersin yaşamın telleri dokunur parmakların kanar.  Kan ağlardı   Bulaşırdı rengi  Göz çıban  Akardı aynı nehirde  Buluşacakl...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/birden-iki-damla-duser-olum-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-esra-aksu-giovc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '...ve ansızın bir yağmur başlar gözlerimde

dolaştığımız yerler ıslanır

                  kokladığımız güller

                      sen ıslanırsın baştan ayağa

          koynumda sabahlar geceler 

o melektir avucumda dolanır

ve ansızın bir yağmur başlar gözlerimde...', '...ve ansızın bir yağmur başlar gözlerimde dolaştığımız yerler ıslanır                   kokladığımız güller                       sen ıslan...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yagmur-169-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suikast', 'suikast-esra-aksu-z4dlr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir suikaste kurban gitti

Sevdam ve yaşama sevincim.

Önce vefasızlık kuzey cepheden

Sonra hainlik güney cepheden...

Yangına mahkum kaldı ikizlerim,

Sabırsız aylar geçti üstünden

Ne kedi çıktı ne de umut enkazından.

Gazeteler manşet yapmadı bu vahşeti

Radyolar duyurmadı bu haberi.

Meclis toplanıp da olağanüstü

Acil yardım kararı almadı.

Düşmanım belli silahım yok

Müttefikim Hakk’tır gayrısı yok

Teminat,teselli....hiç haber yok

İkizlerim çöktü omuzlarıma 

Fark edip de ağlayanım yok!', 'Bir suikaste kurban gitti Sevdam ve yaşama sevincim. Önce vefasızlık kuzey cepheden Sonra hainlik güney cepheden... Yangına mahkum kaldı iki...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/suikast-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopsun Yüreğim', 'kopsun-yuregim-esra-aksu-fcg8w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kopsun yüreğim pencerelerden

Kessin ümidi visalinden

O ki yalnız seni sevdi 

O ki yalnız seni dinledi

Sen söyle ki tez elden

Kopsun yüreğim pencerelerden.', 'Kopsun yüreğim pencerelerden Kessin ümidi visalinden O ki yalnız seni sevdi  O ki yalnız seni dinledi Sen söyle ki tez elden Kopsun yüreğim ...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kopsun-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Laf', 'laf-esra-aksu-e11gj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dört ay oldu hesaplasan

Parmakların mı eskir arasan,

Kulakların mı eskir dinlesen,

Yoksa dudakların mı konuşsan

Söyle niye aramıyorsun? 

Kaç kandil,kaç cum’a geçti

Senden ses seda yok! 

Anlamadım derdin mi çok? 

Tabi sırtın pek karnın tok

Benimki de laf; niye aramıyorsun?', 'Dört ay oldu hesaplasan Parmakların mı eskir arasan, Kulakların mı eskir dinlesen, Yoksa dudakların mı konuşsan Söyle niye aramıyorsun?  Kaç...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/laf-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rest', 'rest-esra-aksu-46ack', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi yoksun ve ben belki ölüyorum

Buz gibi hasta yatağımdan yazıyorum

Bu mektubu soluksuz,yorgun kalpli

Elbet üzgünüm sağanak sağanak ağlıyorum

Tutmuyor kolum kanadım yitiğim gayrı

Ne yapsın anam bacım dağlarım karlı

Üşümeyi bilmem donuyorum artık

Kalbimde,ciğerlerimde sonsuz bir ağrı

Dönmeyeceksin acı ama gerçek

İçim parçalanıyor aklımda ölmek

Dilimde Lafzı bir de seni özlüyorum

Tek arzum son bir defa görmek

Hasretin dudaklarımdan kan olup

Korkumdur saçlarımdan ak olup

Ve sonunda kefen-kabir olup

Sarılsa da boynuma seni çok seviyorum!', 'Şimdi yoksun ve ben belki ölüyorum Buz gibi hasta yatağımdan yazıyorum Bu mektubu soluksuz,yorgun kalpli Elbet üzgünüm sağanak sağanak ağlıy...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/rest-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerimizle Tohumunu Attık Sevdamızın', 'ellerimizle-tohumunu-attik-sevdamizin-meral-yagcioglu-bke2a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yavaş, yavaş filizlendi, yeşile boyandı dünyamız

Ve nihayet tomurcuk verdi gönül karanfilimiz

Önce iyi arkadaş olduk ikimiz, sonra iki kuzu sarması sevgili

Cesaretle göğüs gerdik tüm zorluklara

Düzlüğe çıktık dere tepe aşarak

Olsun varsındı dizlerimizde yaralar

Ellerimizde nasırlar 

Umut doluydu her bir hücremiz

Gönül sazımız elimizde,  yoktu çalacak mızrap

Parmaklarımızla  vurduk  tellerine

Türkülerle besledik sevdamızı

Yüreğimizde büyüttük aşkımızı

En olgun çağımızda

Suya değil yıldızlarla semaya yazdık sabit 

Samanyolu kırmızı perdeli evimiz oldu

Gökyüzünün en kadim dostu bizdik 

Dolun ay tek şahidimizdi 

Can canayken birlikte

Ellerim ellerinde seninken 

Başın göğsümde her nefesinde soluklandığım

Yürek atışların bedenimde çalarken en içli türküyü 

Gözlerimizle mühürledik

Bastık parmağımızı bozulmamacasına onayladık

Sonsuzdu ya sevdamız

Solsa da günün birinde karanfiller, yeniden açacaktı 

Daha bir gür olacaktı yaprakları,rengi daha kızıl

Sevgimizle suladığımız bahçemiz daima var olacaktı

Umudumuz vardı,arzuluyduk

Ama niye ayrıyız şimdi ne oldu da sen orada

Bense burada yalnız tek başına

Nefes almaya çalışır dururuz

Kırıldı gönül sazımız yarım kaldı türkümüz

Ellerimizle diktiğimiz,emekle büyüttüğümüz 

Karanfillerin rengini çaldılar 

Bize sadece  nasırları kaldı,birde sızısı

Ölgün yaprakları tarumar olup saçıldı yeryüzüne

Sicim gibi ağlıyor üstüme

Yürüyorum caddelerde bir başıma

Islanan yüreğim yorgun ve çaresiz

			04/12/2003', 'Yavaş, yavaş filizlendi, yeşile boyandı dünyamız Ve nihayet tomurcuk verdi gönül karanfilimiz Önce iyi arkadaş olduk ikimiz, sonra iki kuzu ...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ellerimizle-tohumunu-attik-sevdamizin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskisi Gibi Olmayacak', 'eskisi-gibi-olmayacak-esra-aksu-9bgs6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiçbir şey eskisi gibi olmayacak...

Kimin dudağı değerse dudağıma

Gasil hane kadar soğuk mermer

Kimin saçını okşarsa rüzgar

Yalnızlık kadar anlamsız olacak

Güneş günaydın dediğin sabahlarda gibi

Sıcak,aydınlık ve umut dolu doğmayacak

Çiçeklerin hiç biri bağrından kopmuş gibi

Rengarenk,sevda misali kokmayacak

Kimsenin elleri senin kadar sıcak

Göğsü senin kadar yumuşak

Gözleri sayfalar dokusu şiir olmayacak

Hiçbir gecede ay ışığı yalnızlığıma ortak

Hele ki yıldızlar sen gibi ince olmayacak

Herkes bilecek ki bugün de dün gibi

Yarın da bugün gibi yaşanacak

Oysa ben bileceğim yalnızca

Hiçbir kırlangıç tek başına uçmayacak

Tavşanlar,tavuklar yine insandan kaçacak

Çocuklar maymunlara uzaktan bakacak

Doğmayacak gamzeleri kucak kucak 

Büyütecek umut bebeği

Altına imzamı atacağım mutluluk

Sözlüklerin tozlu sayfasında kalacak

Sonsuz sessizliğe gömüldüğünde

sevda yorgunu kalbim

Bembeyaz  saçlarım buz tutacak

Üşümeyeceğim elbet

Bileceğim ki bu soğukta ağlamak yanlış

Her insanın toprağı bir karış

Ezanlar süzülürken sesine hasret 

Şiirlerine aşina kulaklarımdan

Kurtulamayacağım mahrem-i esrarımdan

Ay yüzünden bahsedecek mısralarım

Hayallerim Kaf Dağında tatildeyken

Sen yine saraylar düşleyeceksin

Dağların,nehirlerin,hayatının ortasında

Ateşin sıcak,karların soğuk olduğunu

Rüzgarın yaprakları savurduğunu

Ve sana ait sarayın çoktandır

Gönlümün gülistanında kurulduğunu bilmeden

Uçakların keşfini,güllerin rengini

Merak edip durduğun her şeyi

Görecek gönlüm dediğin oda

Bir gözlerimi bir de yüreğimi görmeden

Kürek çekeceksin kabrinin yastığına

Kimin dudağı değerse dudağıma

Gasil hane kadar soğuk mermer

Kimin saçını okşarsa rüzgar

Yalnızlık kadar anlamsız olacak

Senden sonra yaşanacak hiçbir gün

Hiçbir saat,hiçbir dakika

Muhabbet üzere olmayacak

Marmara bir umut çalkalanmayacak

Kız Kulesi Salacak’a el sallamayacak

Ve sandığın gibi sevdalın

Surlar gibi dimdik ayakta durmayacak

Dedim ya hiçbir şey

Ama hiçbir şey eskisi gibi olmayacak! ...

Tüm bunlar yaşanırken civarımda

Senin dalgalı şehrinin dudağında

Gönlünün o kilitsiz kapısında

Uzaklarda da olsam yahut yanında

Duymaktan usanmadığım çığlığında

Hangi çiçekler yeşerecek söyle

Gülüm dediğin yasemen tadında!', 'Hiçbir şey eskisi gibi olmayacak... Kimin dudağı değerse dudağıma Gasil hane kadar soğuk mermer Kimin saçını okşarsa rüzgar Yalnızlık kadar ...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/eskisi-gibi-olmayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-esra-aksu-pg9en', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mayıs akşamlarına dönüş...

Gitme...

Gidersen kaybolur güneş,

Itır kokan saçlarım dökülür.

Gidersen peşinden gelir pigmentlerim,

El aleme rezil edersin beni.

Gitme...

Gidersen kafuru kokar ellerim,

Kına serperler alnıma.

Gidersen şekere benzetirler,

Tohum gibi ekerler beni.

Gitme...

Gidersen...gidersen olmaz işte

Olmaz! gitme...', 'Mayıs akşamlarına dönüş... Gitme... Gidersen kaybolur güneş, Itır kokan saçlarım dökülür. Gidersen peşinden gelir pigmentlerim, El aleme rez...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gitme-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sizi', 'ben-sizi-esra-aksu-bgaez', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben sizi olduğunuz gibi sevdim! 

Yaşlı yüzünüz,

Kesik kesik öksürüğünüz

Ve kendinize has sözlüğünüzle.

Ben sizi bulduğunuz gibi sevdim! 

Yalnız,yapayalnız,

Biraz acımasız,biraz tatsız

Ve çoğu zaman kararsızlığımla.', 'Ben sizi olduğunuz gibi sevdim!  Yaşlı yüzünüz, Kesik kesik öksürüğünüz Ve kendinize has sözlüğünüzle. Ben sizi bulduğunuz gibi sevdim!  Yal...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-sizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir de Siz Anlatın', 'bir-de-siz-anlatin-esra-aksu-mbw8k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Islak sabahlar yaşadım 

Güneşli geceler ardında

An oldu hasret kokladım

Yusuf ile Züleyha sabrında

Duymadığım acısı kalmadı

Yaşadığımsa pek az gümüş hayatın

Daha mı yorgun dersiniz kuşun kanadı

Yalansa söylediklerim bir de siz anlatın

Yeşil yaprakları sarı buldum 

Sonbaharın ılık akşamlarında

Halesiz mehtap misali yoruldum

Düşlerimin pespembe sokaklarında

Duymadığım acısı kalmadı

Yaşadığımsa pek az gümüş hayatın

Daha mı yorgun dersiniz kuşun kanadı

Yalansa söylediklerim bir de siz anlatın

Düşmedim balkonlarından bu şehrin

Dost gözüyle bakmadım yılana

Tersine akmadığını bilip nehirlerin

Olmadık duayla yalvarmadım Yaradana

Duymadığım acısı kalmadı

Yaşadığımsa pek az gümüş hayatın

Daha mı yorgun dersiniz kuşun kanadı

Yalansa söylediklerim bir de siz anlatın', 'Islak sabahlar yaşadım  Güneşli geceler ardında An oldu hasret kokladım Yusuf ile Züleyha sabrında Duymadığım acısı kalmadı Yaşadığımsa pek ...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-de-siz-anlatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Lokma', 'bir-lokma-esra-aksu-s89ci', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdikçe seni,seviyorsam Rabbimm’i

Bir lokma sen lazımsın 

Esirgeme Ey sevgili! 

Ve ateşe yanmak değil 

Kül olmak ağır gelir 

Susup susup söndürme beni.', 'Sevdikçe seni,seviyorsam Rabbimm’i Bir lokma sen lazımsın  Esirgeme Ey sevgili!  Ve ateşe yanmak değil  Kül olmak ağır gelir  Susup susup sö...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-lokma-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilık Sevda', 'ilik-sevda-esra-aksu-hddod', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana ılık sevdalar büyüttüm yüreğimde

Rayihası Medine’den yadigar

Sana ılık sevdalar büyüttüm yüreğimde

Şimdi nasıl anlatsın bu mısralar.', 'Sana ılık sevdalar büyüttüm yüreğimde Rayihası Medine’den yadigar Sana ılık sevdalar büyüttüm yüreğimde Şimdi nasıl anlatsın bu mısralar....', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ilik-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hulasa', 'hulasa-esra-aksu-sd75l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün gibisin hulasa...

Yarın olabilirliğin kadar

Düne sevdalıdır bakışların; 

Kimi zaman susarsın

Zindan duvarları gibi

Kimi zaman vazgeçişlere

Denk düşer feryadın...', 'Gün gibisin hulasa... Yarın olabilirliğin kadar Düne sevdalıdır bakışların;  Kimi zaman susarsın Zindan duvarları gibi Kimi zaman vazgeçişle...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hulasa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah İle Zar', 'ah-i-le-zar-esra-aksu-bd7wj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiçbir şeyin rengini sormayın bana

Köpekler gibi aşığım! 

Hangi firarda unuttum gecemi,

Hangi gardiyanın tütün kokulu

Mendebur ellerinde emanettir gündüzüm

Ben neden senden yetim

Kendimden öksüzüm..? 

Hiçbir şeyin resmini sormayın bana

Bırakın kızıl saçlı çocuğun 

Göğe uzanan ellerinde soluklansın

Berat’a yetişmeyen dualarım

Bırakın parçalansın olduğu yerde

Mahiyetini bilmediğim hüzün şarkısı! 

Hiçbir şeyin manasını sormayın bana

Unuttum tatlıca rüyaları nedensiz

Bırakın beni kırık bardaklarda

Ne tadım var ne demim

Son bir bakışla çekin ve gidin; 

Tövbesiz akşamları alın yadigar

Bana bir ah bırakın,bir de zar...

esra aksu/esir düştüm gözlerinde/akis kitap', 'Hiçbir şeyin rengini sormayın bana Köpekler gibi aşığım!  Hangi firarda unuttum gecemi, Hangi gardiyanın tütün kokulu Mendebur ellerinde ema...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ah-ile-zar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cann Dediğim', 'cann-dedigim-esra-aksu-odu7l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cann dediğim aldı başını gitti

Şimdi ben kime söyleneyim

Vefasızlığın ikiye böldü beni

Yemeyi,içmeyi,gezmeyi neyleyim

Bir sen vardın yalnızlığıma ortak

Yıldızları,güneşi,el alemi neyleyim

Şimdi gönül toprağım kurak

Yeni tohumları,gülleri neyleyim

Göster hadi sana benzeyen çiçek

Sen gibi koksun,hemencecik solmasın

Sevdalın koşup öbek öbek

Yaylalardan,bahçalardan toplasın

Soldum avuçlarında susuzluktan

Yitip gittim kararsız bakışlarından

Bir buse almadan dudağından

Kara toprak beni neylesin

-Sıramı savdım azıcık beklesin

Seni son bir defa görüp gideceğim

Son arzumdur son sevdiğimm

Seni benden gayrisi sevmesin!', 'Cann dediğim aldı başını gitti Şimdi ben kime söyleneyim Vefasızlığın ikiye böldü beni Yemeyi,içmeyi,gezmeyi neyleyim Bir sen vardın yalnızl...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cann-dedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fısıltı', 'fisilti-esra-aksu-o8ley', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş yine uykuya daldı

Aklımda sen semaya bakıyorum

Yıldızlardan güneşe bir fısıltı; 

“Ben hala seni bekliyorum”

Yazın da sonu geldi çattı

Herşey suskun,bahçemizi dinliyorum

Bülbülden güle bir fısıltı; 

“Ben hala seni bekliyorum”

Gökyüzü bu gece yine bulutlu

Hava hergün daha da serin,üşüyorum

Topraktan yağmura bir fısıltı; 

“Ben hala seni bekliyorum”

Hayalin burada,yüzünde yine bir karaltı

Ellerin nerede seçemiyorum

Cann’dan cann’a  bir fısıltı; 

“Ben hala...', 'Güneş yine uykuya daldı Aklımda sen semaya bakıyorum Yıldızlardan güneşe bir fısıltı;  “Ben hala seni bekliyorum” Yazın da sonu geldi çattı ...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fisilti-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Hüznü', 'gul-huznu-esra-aksu-8qw8c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Solmuş bir gül hüznüyle

bakıyorum dünyaya

Hiçbir şeyin anlamı yok gözümde 

Bir onu özlüyorum

Yüzünü görmediğim dostu...', 'Solmuş bir gül hüznüyle bakıyorum dünyaya Hiçbir şeyin anlamı yok gözümde  Bir onu özlüyorum Yüzünü görmediğim dostu......', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gul-huznu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Ağacın Altında', 'sessiz-agacin-altinda-esra-aksu-q2csg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ürkek dalgıcımm’a...

Islak sokaklarda ardım sıra

İşittiğim ıslık seninki miydi,

Yalnızken sessiz ağacın altında 

Mırıldandığım ayak sesin miydi? 

O halde sessiz ağacın altında

Özlemle beklediğim; ela gözlerindi!', 'Ürkek dalgıcımm’a... Islak sokaklarda ardım sıra İşittiğim ıslık seninki miydi, Yalnızken sessiz ağacın altında  Mırıldandığım ayak sesin mi...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sessiz-agacin-altinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Gibi', 'adam-gibi-asli-yildiran-bh572', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinde gizli bir hayat hikayesi

Gözlerin de yazıyor aşkın kaç asır süreceği

Yanacağı kaç kişinin ve kimlerin öleceği

Senin avuçlarında gizli sevdamın kaderi

Bakışında duruyor yüreğimin kıyameti

Öleceğim besbelli ve sen gideceksin

Daha önceki gibi.

Kimbilir kimlerin kıyametiydi benim başlangıcım

Söyle sen hiç adam gibi, insan gibi sevmedin mi? 

Gözlerinde can buluyor ve gözlerin de can veriyor

Sevgilerin en güzeli.

Bir yıldız kayıyor, sonra bir serçe kanatsız yaşıyor

Bir gonca gül solup gidiyor

Gözlerinden gözlerime bir hainlik gülümsüyor.

Ben biteceğim besbelli ve sen yine gideceksin

Daha önceki gibi

Söyle sen hiç adam gibi, insan gibi sevmedin mi?', 'Gözlerinde gizli bir hayat hikayesi Gözlerin de yazıyor aşkın kaç asır süreceği Yanacağı kaç kişinin ve kimlerin öleceği Senin avuçlarında g...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/adam-gibi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canı terketmeli bu keşkeler', 'cani-terketmeli-bu-keskeler-evren-dalgic-fis1a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bitti artık,

tükendi sevgim.

Ben senin ile,

Koskoca bir gençliği tükettim.

Ve senden geriye kalan

o lime lime anılarla; 

gözyaşlarıyla süsledim yalnızlığımı.

Sonsuz bir düş gibiydi sevgim senin üstüne,

bir rüya gibiydi yaşanılanlar.

Acılar; 

ah o acılar olmasaydı.

Hep gülseydi senin ile yüzüm

Bir gün ayrılık dolu gözlerin  kapımı çalmasaydı.

Sevmeseydim,

üzmeseydim keşke kendimi.

Ben senin ile,

Hiç olmayacak sevdalara düşmeseydim.

Oy yangınlara daldığım sebep! 

oy hayaline dalıp da,

bomboş hülyalarına kandığım! 

Yaşanılanlar diken gibi batarken yüreğime,

o günleri düşünüp de; 

bende keşke senin gibi

arkamı dönüp de bir boşluğa kaçsaydım.

Sokaklarım gözlerin dolu,

keşke seni hiç değdirmeseydim kaldırımlarıma.

Hiç dokunmasaydı ellerin saçlarıma.

Yıllarımı süzmeseydin,

gözüne kestirmeseydin o çocuk tenli yüreğimi.

Poyrazlarda sürüklenir oldu şimdilerde düşlerim,

keşke bir meltem gibi kendi halimde esseydim.

Hangisine yansam bilmem ki,

hangi keşkeme bin keşke eklesem.

Ben ne yapsam da kendimden seni söksem.

Hangi pişmanlığa bir kılıf uydurabileyim; 

ben hangi yüzle artık yarına gülebileyim.

Artık kim güzel gösterebilir bana yarını.

Anlaşıldı bir kez geldiysem dünyaya,

ve yağmurlara hediye ettiysem bu mazlum hülyayı; 

ben artık terketmeliyim,

bende emanet olan bu canı.

(Ankara 2005)', 'Bitti artık, tükendi sevgim. Ben senin ile, Koskoca bir gençliği tükettim. Ve senden geriye kalan o lime lime anılarla;  gözyaşlarıyla süsle...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/cani-terketmeli-bu-keskeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Gözyaşını Dökünce Güle', 'sevda-gozyasini-dokunce-gule-sadik-softa-d6xi3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevda gözyaşını dökünce güle,

Şebnem güzelliği getirmiş dile,

Sümbül boynun eğip sevgisi ile,

Hasbıhale dalmış, dalış o dalış.

Menekşe gözünde sevgi yeşermiş,

Aşka uzanmayan sevda beşermiş,

Göz ışırsa kalbe sevda düşermiş,

Kalpten sevda almış, alış o alış.

Papatyaya güneş vurmuş çığ gibi,

Sanki mavi koyda, sular sığ gibi,

Bakışların kalpten işler tığ gibi,

Dantel izi kalmış, kalış o kalış.

Türkü mayalanmış duyguya akar,

Gözler birleşende aşk ordan bakar,

Aşkın ateşi var, alevler yakar,

Bağra ateş salmış, salış o salış.

Yürekte aydınlık, mutluluk nerde? 

Sevinç yürek olsun kalmasın yerde,

Gözler de umuttan nezih bir perde,

Gönül sazı çalmış, çalış o çalış.

Çankırı-06.03.2005', 'Sevda gözyaşını dökünce güle, Şebnem güzelliği getirmiş dile, Sümbül boynun eğip sevgisi ile, Hasbıhale dalmış, dalış o dalış. Menekşe gözün...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevda-gozyasini-dokunce-gule-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halk Böyle İstiyor Oğlum', 'halk-boyle-i-stiyor-oglum-ahmet-selcuk-i-lkan-l5yni', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Halk Böyle İstiyor Oğlum! ...

		   ''Bir babanın doğum gününde 

                                   oğluna mektubudur... Görülmüştür''

Sevgili oğlum

Bugün tam on yedi yaşındasın

Görüyorum ki artık

Her şeyin farkındasın

Ama ne zaman ararsam seni

Ya diskoda

Ya barda

Ya da televizyon karşısındasın

Haklısın oğlum

Devir artık bu devir

Sen de çemberini çağına göre çevir

Senin neyine

Resim roman şiir

Senin neyine

Sanat vesair

Ne diyor meşhur televizyon büyükleri

Vur patlasın çal oynasın

Devir artık bu devir

Nasılsa

Son düğmesi de koptu insanlığın

Vefa can çekişiyor arka sokaklarda

Umut mendil sallıyor giden trenlerin ardından

Onur, adres arıyor mezarlıklarda

Dostluklar çöp tenekelerinde sahipsiz

Ve anahtar teslimi aşklar satılık köşe başlarında

Hem de üç kuruş mutluluklara...

Ama sen de haklısın

Sana mı kaldı

Kurtarmak vatanı

Sana mı kaldı

Uyandırmak yatanı

Sana mı kaldı

Duvara yapıştırmak

Bu memleketi satanı

Anasını ağlatanı....

Gel gör ki oğlum

Senin de kurtuluşun yok bu gidişten

Ne etsen- ne yapsan

Bir düğün

Bir bayram

Bir lale devri

Hangi ekrana baksan

Kim kiminle evleniyor

Kim kiminle çıldırıyor

Kim kime daldan dala

Gelinim olur musun diyor

Kimisi sahte gelin

Kimisi zengin bir prens

Kimisi de insanlıktan bir yudum bir nefes

Bekliyor da bekliyor 

Bak her gün ayrı bir kanalda

Bambaşka bir ''ünlüler çiftliği''

Her kanalda şöhret olmanın dayanılmaz hafifliği

Ve işte böyle

Pazara dökülüyor bir bir

Herkesin yumak yumak ipliği

Yıllar var ki oğlum

Birileri işte

Bizi hep böyle gözetliyor...

Ve sen de görüyorsun ki

Bu sahneler 

Bizi ne de güzel özetliyor

Kimin umurunda yarınlar

Kimin umurunda çocuklar

Kimin umurunda bu isyankar çığlıklar

Bir kavgadır

Bir yarıştır

Bir rezalettir gidiyor.

Kime sorsan

Cevaplar dünden hazır

Halk böyle istiyor oğlum

Halk böyle istiyor

Gel gör ki

Bir reyting uğruna

Ne ''güneşler batıyor'' oğlum

Ne  güneşler batıyor....

		Ahmet Selçuk İLKAN

“yeni çıkacak son şiir kitabından”	

www.ahmetselcukilkan.net', 'Halk Böyle İstiyor Oğlum! ... 		   ''Bir babanın doğum gününde                                     oğluna mektubudur... Görülmüştür'' Sevgili ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/halk-boyle-istiyor-oglum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görünen o ki:', 'gorunen-o-ki-mahmut-bugrul-e0fjv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimsede yoktur Allah korkusu,

Gelmeyince burnuna ölüm kokusu.

               15.03.2005

                   Gölbaşı', 'Kimsede yoktur Allah korkusu, Gelmeyince burnuna ölüm kokusu.                15.03.2005                    Gölbaşı...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Buğrul']::text[], 8.5, '{"poet":"Mahmut Buğrul","poet_slug":"mahmut-bugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gorunen-o-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yastayım', 'yastayim-harun-kuscu-ml7od', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tanımsız  meçhule gitti gençliğim 

Yarınsız bir insan olmuşum şimdi

Beyhude zamanda bitti gençliğim

İçi boş  testiye  dolmuşum şimdi

Kendimi kaybettim zayi hükümsüz

Bilinci kaybolan hastayım şimdi

Geçmişe dönmekte artık imkansız

Ömür boşa geçti yastayım şimdi

Gelse de sevdanın  bize baharı

Son deminde ömrün pişmanım şimdi

Beni iyi dinle  gönlümün varı

Gayesiz ömüre  düşmanım şimdi

   			Harun KUŞCU

			15.03.05 / Silifke', 'Tanımsız  meçhule gitti gençliğim  Yarınsız bir insan olmuşum şimdi Beyhude zamanda bitti gençliğim İçi boş  testiye  dolmuşum şimdi Kendimi...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yastayim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Zormuş Efendi', 'ayrilik-zormus-efendi-guner-kaymak-o76c3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yangın var yüreğimde yanıyor 

Ayrılık ölümden zormuş efendi 

Deli gönül sevdiğini arıyor 

Direnip dayanmak zormuş efendi 

Farkında değilim bastığım yerin 

Kalbimde yara var oldukça derin 

Buralarda kalmam çeker giderim 

Maziyle yaşamak zormuş efendi 

Ateşim yükseldi başım dönüyor 

Umut ışığım kararıp sönüyor 

Bilirim gidenler geri dönmüyor 

Bir başına kalmak zormuş efendi 

Yediğim yemeğin yoktur lezzeti 

Ayriliğin hiç olurmu hikmeti 

Nankör inkar eder elbet nimmeti 

Nanköre yar olmak zormuş efendi

Yarı yolda kalmak ar geldi bana 

Zalim olan hiç gelirmi imana 

Duygusal yüreğim dayanmaz buna 

İhanet yarası zormuş efendi 

Uykularım kaçtı sarardı rengim 

Sıfırı tükettim kalmadı sevgim 

Anladım dünyada bulunmaz dengim 

Aşka boyun eğmek zormuş efendi 

Nerdeyse duracak tekliyor kalbim 

Ne idealim kaldı ne hayalim 

Ozan Güner Kalmadı hiç mecalim 

Aşk oduna yanmak zormuş efendi 

Güner Kaymak / Amsterdam 12.03.2005', 'Bir yangın var yüreğimde yanıyor  Ayrılık ölümden zormuş efendi  Deli gönül sevdiğini arıyor  Direnip dayanmak zormuş efendi  Farkında değil...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ayrilik-zormus-efendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Sevemiyorum', 'yeniden-sevemiyorum-guner-kaymak-9il81', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç darılma nolur güzelim bana 

Ben seni yeniden sevemiyorum 

Gayret ettim amma çabam boşuna 

Ben seni yeniden sevemiyorum 

Duyguların zarar görmesin senin 

Çok güzel insansın tertemiz kalbin 

Baglanma bana yıkılmasın hayalin 

Ben seni yeniden sevemiyorum 

Deli gönlüm beni avucuna almıs 

Vefasız birine tiryaki yapmıs 

Demek ki kaderde ayrılık varmıs 

Ben seni yeniden sevemiyorum 

İstenmeyen yemek mideye zarar 

Hatır için birlesmek neye yarar 

Sana sonsuz hürmetim ve saygım var 

Ben seni yeniden sevemiyorum 

Helal et hakkını bagışla beni 

Yeterince bilemedim kadrini 

Yeter artık boşa çekme derdimi 

Ben seni yeniden sevemiyorum 

Akla gelmeyenler geliyor başa 

Bensiz de mutlu ol çok mutlu yaşa 

Güner der kafami vursamda taşa 

Ben seni yeniden sevemiyorum 

Güner Kaymak / Amsterdam 11.03.2005', 'Hiç darılma nolur güzelim bana  Ben seni yeniden sevemiyorum  Gayret ettim amma çabam boşuna  Ben seni yeniden sevemiyorum  Duyguların zarar...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yeniden-sevemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deyiş 9', 'deyis-9-ali-riza-unal-5z142', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan oğlu sonsuz fırkalar.

Kimi arş-ı aşar, ilmi kovalar.

Kimi şaşkın, düzde zırvalar.

Kimine put olmuş, nefsi ile paralar.

Kimi melanete düşmüş zorbalar.

Kimi eli havada, hacete dualar.

Kimine yol oldu, aşk ile sevdalar.

Bizede bir oldu, bülbül ile kargalar.

----alar

Kimi    ---alar

Kimi,   ---alar

Kimine ---alar

Kimi ---alar

Kimi ---alar

Kimine  --- alar

----alar', 'İnsan oğlu sonsuz fırkalar. Kimi arş-ı aşar, ilmi kovalar. Kimi şaşkın, düzde zırvalar. Kimine put olmuş, nefsi ile paralar. Kimi melanete d...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/deyis-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Tuş Edemezsin', 'beni-tus-edemezsin-guner-kaymak-z4seh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne kadar kalleşlik yaparsan yap 

Sen beni ömrünce tuş edemezsin 

İstediğin kadar dünya malına tap 

Sen beni ömrünce tuş edemezsin 

Benki yadellerde ne acılar görmüşüm 

Riyakar dostlardan ne darbeler yemişim 

Zulmün her rengine gögüs germişim 

Sen beni ömrünce tuş edemezsin 

Acılarla yogrulmuş acırmı hic yüregim 

Demır gibi sağlam bükülemez bilegim 

Beni yıkacakmış vay aklına güleyim 

Sen beni ömrünce tuş edemezsin 

Ekin misali ben yatar yatar kalkarım 

Vicdanım el vermez allahımdan korkarım 

Senin gibi daha nicesini haklarım 

Sen beni ömrünce tuş edemezsin 

Bilirim sahte gözyaşındır zalim silahın 

Sadakat dostlukta hiç olmadı merakın 

Yaşayan bir körden hiç yoktu farkın 

Sen beni ömrünce tuş edemezsin 

Nankör olduğunu görmezmiydim 

Duygusuz yaşadığını bilmezmiydim 

Güvenseydim kalbimi vermezmiydim 

Sen beni ömrünce tuş edemezsin 

Terk edip te gidene çekerim cızık 

Soysuz olan birine hiç demem yazık 

Benim başım dik gögsüm kabarık 

Sen beni ömrünce tuş edemezsin 

Çıkardıgım çamura tekrar batarsın 

Çok pişman olur saçlarını yolarsın 

Ozan Güner''i bir daha bulamazsın 

Sen beni ömrünce tuş edemezsin 

Güner Kaymak / Amsterdam 27.02.2005', 'Ne kadar kalleşlik yaparsan yap  Sen beni ömrünce tuş edemezsin  İstediğin kadar dünya malına tap  Sen beni ömrünce tuş edemezsin  Benki yad...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/beni-tus-edemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-meryem-sahin-xstmh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'elini uzattı almak için

boşlukta asılı kaldı

kirli minik parmakları

kokladı uzun uzun

buram buram kokusunu

sıcak taze ekmeğin

bir adım daha attı

açlığın kapısından dışarı

çıkarım diye ümitle

girmemişti ağzından içeriye

günler günler boyu

ne ekmekten bir lokma

ne bir yudum tatlı su

çaldığını duydu zillerin

içinde biryerlerde

beynine ulaştı sonra

susmayan zil sesleri

ısrarlı....arsızca

karardı heryer

masum yüzü gibi kapkara

titredi incecik dizleri

aralandı çatlamış dudağı miniğin

''ver bana'' der gibi baktı

ekmeği uzatan adama

son bir çabayla

belenirken yapışkan çamura

elini uzattı almak için

boşlukta asılı kaldı

kirli minik parmakları', 'elini uzattı almak için boşlukta asılı kaldı kirli minik parmakları kokladı uzun uzun buram buram kokusunu sıcak taze ekmeğin bir adım daha ...', ARRAY['Türk Edebiyatı','Şiir','Meryem Şahin']::text[], 8.5, '{"poet":"Meryem Şahin","poet_slug":"meryem-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cocuk-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana Ve Yar', 'ana-ve-yar-guner-kaymak-6db7f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasıl anlatayım, nasıl söyleyim 

Sag yanım anam, sol yanım yarim 

Kadir kiymetini beyan eyleyim 

Sag yanım anam, sol yanım yarim 

O ana ki cennetlerin hurisi 

o yardır ki meleklerin perisi 

Her ikisi bir elmanın yarısı 

Sag yanım anam, sol yanım yarim 

Yar bakışır özlem ile 

Ana sarılır şevkat ile 

Fark aramak boş nafile 

Sag yanım anam, sol yanım yarim 

Gönül bahçemde ana çiçek 

yar uçuşan güzel kelebek 

Ayrı gayrı da ne demek 

Sag yanım anam, sol yanım yarim 

Anadır ki hep basimin taci 

Gülyüzlü yar yüregimin ilaci 

İkisi de tabiatın agacı 

Sag yanım anam, sol yanım yarim 

O nazlı yar gözlerimin yaşıdır 

O anaki yüregimin başıdır 

Karanlik dünyami ikisi de ışıdır 

Sag yanım anam, sol yanım yarim 

Gülyüzlü yar dilimdeki hecedir 

O anaki yücelerden yücedir 

Her ikisi şu gönlümde cevherdir 

Sag yanım anam, sol yanım yarim 

Ana damarlarımdaki kanım 

Nazli yar tenimde canım 

Ozan Güner ikinize kurbanım 

Sag yanım anam, sol yanım yarim 

Güner Kaymak / Amsterdam 21.02.2005', 'Nasıl anlatayım, nasıl söyleyim  Sag yanım anam, sol yanım yarim  Kadir kiymetini beyan eyleyim  Sag yanım anam, sol yanım yarim  O ana ki c...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ana-ve-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalımın Kızı', 'zalimin-kizi-guner-kaymak-jdkhx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevdigimi herkes bilirdi 

Bir sen anlamazdın zalımın kızı 

Bir çokları benim için ölürdü 

Farkıma varmazdın zalımın kızı 

Zalımın kızı zalımın kızı 

Esti deli poyraz ayırdı bizi 

Görür görmez seni dilim dururdu 

Sararırdı rengim beyaz olurdu 

Şavkın vurur gözlerimi alırdı 

Dönüpte bakmazdın zalımın kızı 

Zalımın kızı zalımın kızı 

Esti deli poyraz ayırdı bizi 

Gönül bahçemin gonca gülüydün 

Suskun yüregimin şen bülbülüydün 

Büyüktü sevdam çoktu ümüdim 

Ümüdimi yıktın zalımın kızı 

Zalımın kızı zalımın kızı 

Esti deli poyraz ayırdı bizi 

Güner Kaymak / Amsterdam 18.02.2005', 'Seni sevdigimi herkes bilirdi  Bir sen anlamazdın zalımın kızı  Bir çokları benim için ölürdü  Farkıma varmazdın zalımın kızı  Zalımın kızı ...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zalimin-kizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmiyorum Diyemem', 'sevmiyorum-diyemem-ahmet-atmaca-oiztw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi yalan desemde, inanmam buna kendim 

Sana nasıl sevmedim, sevmiyorum diyeyim 

Bİr aşk  kırıntısın da ne umutlar besledim 

Nasıl gönül vermedim gidiyorum diyeyim, 

Ne olur birşey söyle beni sen diye düşün 

Yılkıldıysa bir anda taptığın gönül köşkün 

Tiryaki bu ömrümün, ilacı olmuş, yüzün 

Nasıl içmeden yaşıyorum diyeyim.', 'Şimdi yalan desemde, inanmam buna kendim  Sana nasıl sevmedim, sevmiyorum diyeyim  Bİr aşk  kırıntısın da ne umutlar besledim  Nasıl gönül v...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevmiyorum-diyemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerbelada Yastayim', 'kerbelada-yastayim-guner-kaymak-py55l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kerbela da ehlibeyte kast eden 

Insan degildir müslümanda olamaz 

Emanete alçakça ihanet eden 

Insan degildir müslümanda olamaz 

Müslüman olan edermi zulüm 

Kundaktaki bebege revamı ölüm 

Çölde susuz birakan riyakar zalim 

Insan degildir müslümanda olamaz 

Dünya saltanatına gözünü diken 

Fitnenin fesatın tohumun eken 

Ebu süfyanın soyuna çeken 

Insan degildir müslümanda olamaz 

Hazreti Muhammede garez edenler 

Fatimatı Zehraya acı verenler 

Hamza pehlivanın cigerini yiyenler 

Insan degildir müslümanda olamaz 

Kadınların bile çadırına saldıran 

Zeynel abidini hasta yatagında kaldıran 

Hür şehidi parçalara ayiran 

Insan degildir müslümanda olamaz 

Şah Hüseyine yalvarıpta getiren 

Küfe halkıdır sonunda ihanet eden 

Yetmiş iki şehidin kanına giren 

Insan degildir müslümanda olamaz 

Aliekbere mızraklarla saldıran 

Hazreti Abbasın kollarını kırdıran 

Kardeş kavgasına sebebiyet veren 

Insan degildir müslümanda olamaz 

Anadan üryan kadınları gezdiren 

Şam diyarında canlarından bezdiren 

Insanlık tarihine kapkara leke süren 

Insan degildir müslümanda olamaz 

Hazreti Zeyneb’e Feryat ettiren 

Mazlumlara göz yasları döktüren 

Aliyel murtezaya kötülük eden 

Insan degildir müslümanda olamaz 

Simir zülcevsendir seytanı lain 

Ehlibeyt zulmeden en alçak hain 

Yezit alçagıdır en adi zalim 

Insan degildir müslümanda olamaz 

Şehitlerin basını mızraklarda gezdiren 

Mübarek bedenlerini atlar ile ezdiren 

Islam dinine büyük kötülük eden 

Insan degildir müslümanda olamaz 

Ozan Güner kerbelada yaslıyım 

Mazlumun yaninda zalimlere karsıyım 

Kim derseki Ben mervanin soyuyum 

Insan degildir müslümanda olamaz 

Güner Kaymak/ Amsterdam 13.02.2005', 'Kerbela da ehlibeyte kast eden  Insan degildir müslümanda olamaz  Emanete alçakça ihanet eden  Insan degildir müslümanda olamaz  Müslüman ol...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/kerbelada-yastayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süper Lige Çıkacağız', 'super-lige-cikacagiz-guner-kaymak-kzv06', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kurtulus yok artık bizden 

Süper lıge çıkacağız 

Dönmeyiz biz sözümüzden 

Engelleri aşacağız 

Aşacagiz aşacağız 

Sezon boyu coşacağız 

Kırmızı siyah rengimiz 

Uefadır hedefimiz 

Çorumsporlu hepimiz 

Süper lige çıkacağız 

Çıkacağız çıkacağız 

Engelleri yıkacağız 

Çorumlular coşacaktır 

Stadlara koşacaktır 

Rakip bizden korkacaktır 

Süper lige çıkacağız 

Süper lige çıkacagız 

Tabuları yıkacagız 

Güner Kaymak / Amsterdam 11.02.2005', 'Kurtulus yok artık bizden  Süper lıge çıkacağız  Dönmeyiz biz sözümüzden  Engelleri aşacağız  Aşacagiz aşacağız  Sezon boyu coşacağız  Kırmı...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/super-lige-cikacagiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel de Yasa Hollanda’da Gardaşım', 'gel-de-yasa-hollanda-da-gardasim-guner-kaymak-y4hqp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece rüya görüp, gündüz kanun koyuyor 

Gelde yaşa, hollanda’da gardaşım 

Kaşıkla verip, kepçe ile geri alıyor 

Gelde yaşa, hollanda’da gardaşım 

Park polisleri köşelerde saklıdır 

Sırtını dön, araban kilitlidir,baglıdır 

Yorma kendini, onlar hep haklıdır 

Gelde yaşa, hollanda’da gardaşım 

Bakıver postana, yüregin varsa 

Icracılar, pusuda borcun aksarsa 

Yandıgının resmidir programın yoksa 

Gelde yaşa hollanda’da gardasım 

Sadakaya benzedi, sosyal hakları 

Işsiz, güçsüz, perişandır çokları 

Sessiz, sakin, koyun gibi halkları 

Gelde yaşa hollanda’da gardaşım 

Kör kuyuya düştü, çocuk parası 

Canından bezdirmek, zaten çabası 

Mezarda emeklilik, işin cabasi 

Gelde yasa hollanda’da gardasım 

Yangın yeri gibi, her yanı ates 

Binbir çeşit tuzak, kalleşmi kalleş 

Işe gitmelisin, sabah saat beş 

Gelde yaşa hollanda’da gardaşım 

Mafyadan beter, vergi sistemi 

Yapışır bırakmaz, büker enseni 

Nasıl anlatacaksın, kime derdini 

Gelde yaşa hollanda’da gardaşım 

Aile birlesimine, bizans oyunu 

Senelerce sürer, mahkemesi kanunu 

Sonunda derler, uygun degil durumu 

Gelde yaşa hollanda’da gardaşım 

Köpegi olan, iyi kötü yaşıyor 

Evladı olan, sıkıntıya düşüyor 

Gelen kagıtlardan, beynin şişiyor 

Gelde yaşa hollanda’da gardaşım 

Ozan Güner hollanda’yı sevmedim 

Çoluk, çocuk oldu, geri dönemedim 

Bunlar kadar, iki yüzlü görmedim 

Gelde yaşa hollanda’da gardaşım 

Güner Kaymak / Amsterdam 29.01.2005', 'Gece rüya görüp, gündüz kanun koyuyor  Gelde yaşa, hollanda’da gardaşım  Kaşıkla verip, kepçe ile geri alıyor  Gelde yaşa, hollanda’da garda...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gel-de-yasa-hollanda-da-gardasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm Basa Bela Benim', 'gonlum-basa-bela-benim-guner-kaymak-z0pab', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç kimseyle sorunum yok 

Gönlüm basa bela benim 

Daldan dala çok kondum çok 

Gönlüm basa bela benim 

Her güzele meyil verir 

Yanar sevdasiyla erir 

Ömrümü yerde bitirir 

Gönlüm basa bela benim 

Laftan sözden hiç anlamaz 

Gözü kara asla korkmaz 

Güner sevdimi unutmaz 

Gönlüm basa bela benim 

Güner Kaymak / Amsterdam 

20.01.2005', 'Hiç kimseyle sorunum yok  Gönlüm basa bela benim  Daldan dala çok kondum çok  Gönlüm basa bela benim  Her güzele meyil verir  Yanar sevdasiy...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gonlum-basa-bela-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-i-brahim-balci-gnfcp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buraya kadar mıydı hepsi

Sesimi duymamak için mi

Kapalı telefonun,ya gönül kapın

Verdiğin onca söz

Tutulmamak için mi verilmişti

Ben sende buldum aşkı

Böylesine apansız terketsen de beni

Mezarıma taşıyacağım karşılıksız sevgimi

Senin mevcudiyetin nasıl sırrım idiyse

İtirafta zorlandığım kendime bile

Yokluğun da gayb alemine taşınacak

Çürüyen bedenimle birlikte', 'Buraya kadar mıydı hepsi Sesimi duymamak için mi Kapalı telefonun,ya gönül kapın Verdiğin onca söz Tutulmamak için mi verilmişti Ben sende b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/serzenis-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürekli Genç ve Adam', 'yurekli-genc-ve-adam-sinan-dayan-xonq1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gençdi...

Yürekliydi... 

Ve de Adam.

Genç yürekli ve Adam.

Genç yürekli adam...

Kalbidir, sevdayla çarpan,

Sevdayla çırpınır, her an.

Nasılda sever, parlayınca gözler...

Yüreği heyecandan titrer.

Kapatma gözlerini sevdalım,

Delikanlın, yüreğine akmak ister...', 'Gençdi... Yürekliydi...  Ve de Adam. Genç yürekli ve Adam. Genç yürekli adam... Kalbidir, sevdayla çarpan, Sevdayla çırpınır, her an. Nasıld...', ARRAY['Türk Edebiyatı','Şiir','Sinan Dayan']::text[], 8.5, '{"poet":"Sinan Dayan","poet_slug":"sinan-dayan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yurekli-genc-ve-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helak Oldum', 'helak-oldum-guner-kaymak-99x5v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Helak oldum gurbet elde 

Gör halimi övün simdi 

Sen düsürdün beni derde 

Vur dizine dövün simdi 

Seni sevmek ömre zarar 

El aleme de olmadin yar 

Timsah gibi gözyasin var 

Bagir çagir yutkun simdi 

Tiyatrocu bas aktörsün 

Sen bu isi iyi götürürsün 

Herkese güç yetirirsin 

Saga sola saldir simdi 

Her yaptigin dogru senin 

Varmiki esin menendin 

Hiç kimseyle alay etmedin 

Basin dik yüzün ak simdi 

Basa bela hep güzelligin 

Kalmadi ki hiç özelligin 

Bes belliydi sevmedigin 

Oyna zipla eglen simdi 

Dünyayi toz pempe gördün 

Her yanina gurur agi ördün 

Güner''in ömrünü yedin 

Gözün aydin bayramin simdi 

Degerli üstadim Ilhami arslantas agabeyimin tesvikiyle ve verdigi ayakla acele olarak yazmis oldugum bir siirimdir dilerim üstadim begenir 

Güner Kaymak / Amsterdam 09.01.2005', 'Helak oldum gurbet elde  Gör halimi övün simdi  Sen düsürdün beni derde  Vur dizine dövün simdi  Seni sevmek ömre zarar  El aleme de olmadin...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/helak-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Yaylacık', 'canim-yaylacik-guner-kaymak-lezvt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unutmak mümkünmü Yaylacık seni 

Doğup büyüdüğüm şirin köyümsün 

Hep yerinde sayman kahreder beni 

İlçe değil, sen il olmaya layıksın 

Dört mevsim yaşanır ulu yerdesin 

Havan temiz binbir derde devasın 

Tertemiz suların boşa akmasın 

Baraj değil, sen denizlere layıksın 

Dağlarında çiğdem çiçek açılır 

Lale nergis mormenekşe seçilir 

Buz gibi suları afiyetle içilir 

Anlatmaya değil, görülmeye layıksın 

Nice er evliya bağrında senin 

Demirci Baba’dan havan hep serin 

Burcu burcu koku saçar güllerin 

Tabiat harikası denilmeye layıksın 

Tarlalarında ekilir mercimek nohut 

Ormanında dolu meşe palamut 

Yanmış ciğerini kar ile soğut 

Güzel Köyüm denilmeye layıksın 

Kınalı keklikleri çok öter dağında 

Bülbüller şakır bahçesinde bağında 

Tarihi eserler gömülüdür bağrında 

Medeniyet beşiği anılmaya layıksın 

Yankı yapan kayaların çıkmaz aklımdan 

Madımak pancarın, doyulmaz tadından 

Ozan Güner bir ah çeker kahrından 

Türküye, şiire, sen destanlara layıksın 

Güner Kaymak / Amsterdam 14.12.2004', 'Unutmak mümkünmü Yaylacık seni  Doğup büyüdüğüm şirin köyümsün  Hep yerinde sayman kahreder beni  İlçe değil, sen il olmaya layıksın  Dört m...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/canim-yaylacik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melâmi sözleri', 'mel-mi-sozleri-ali-riza-unal-cih26', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fakru fukaraya kör bakma şakir.

Hakka ayan fakir,üryâneler vardır.

  ----------------------

Ne karaya ne sarıya bakma hakir.

Hak indinde halifeyi Kâbeler vardır. 

  -----------------------

Ne ettiyse ezeldendir, ne güzel bize.

Her işinde bir hicabı hikmet vardır.

  -------------------

Bu dünya hakkın ezeli kavlidir.

Sanmaki sonradan zuhurat vardır.

-----------------------', 'Fakru fukaraya kör bakma şakir. Hakka ayan fakir,üryâneler vardır.   ---------------------- Ne karaya ne sarıya bakma hakir. Hak indinde hal...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/melami-sozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışın', 'bakisin-i-brahim-balci-2y64k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaklardaki kadın

Olmadın hiçbir an

Yanıbaşımda

İçimdesin ta içimde

Konuştuğum iç ses

Dinlediğim şu nefes

Benim değil senindir

Değmese de tenin tenime

Bakışını hissederim

Üzerimde gözlerin

Yağmurun hüznünü taşıyan 

O bakışın

Mutluluk mu verir bana

Mutsuzluk mu yoksa

Ulaşamamanın erişememenin

Sızısını mı paylaşır benimle

Yoksa sorgular mı kararsızlığımı

Tutkum mudur paylaştığı

Yoksa alay mıdır o parıltı

Tutkumun tek yanlı bir tutku

Olduğuna ilişkin bir gönderme mi yoksa

Yılankavi bir hançerin saplanışı

Ta içime

Ta içime

Dağlar durmadan eriyen bedenimi

Amacı otamak olsa keşke

Bana hep öyle bak

Öyle derin 

Ve bir okyanus kadar serin', 'Uzaklardaki kadın Olmadın hiçbir an Yanıbaşımda İçimdesin ta içimde Konuştuğum iç ses Dinlediğim şu nefes Benim değil senindir Değmese de te...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bakisin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize Ne', 'bize-ne-guner-kaymak-9mmqa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bayram kutluyoruz dostlar bakın bayram 

Mafyadan hortumcudan anarjiden bize ne 

Varsın yaşasın bize değmeyen yılan 

Haktan, hukuktan, adaletten bize ne 

Katil amerika ırakta kana doymazken 

Israil filistinlileri topragından kovarken 

Kapitalizm halk çirilçiplak soyarken 

Haya, edep, ar, namustan bize ne 

Bu devirde bile halen agalik varsa 

Zalimin zulmu eger yanına karsa 

Terörist alçaklar okul bile basarsa 

Insanlık onuru, haysiyetten bize ne 

Avrupa birligi renkten renge girerken 

Rusya atom bombasına göz dikerken 

Caniler koyun gibi insan keserken 

Feryat,figan,merhametten bize ne 

Varsın ihalelere fesat sokulsun 

Milletin vekili adamını kayırsın 

Orta direk alısık beter sürünsün 

Köylüden, memurdan, emekçiden bize ne 

Faili meçhul cinayetler sürerken 

Ünüversite mezunu işsiz güçsüz gezerken 

Insanımız borç batagında yüzerken 

Yardimlaşmadan, paylaşmadan bize ne 

Eşkiyalık hortlayıp geri gelmişse 

Mazlumun feryadı arsa çikmişsa 

Tek kurtuluşumuz avrupaya kalmişsa 

Dogruluk, dürüstlük, yigitlikten bize ne 

Milyarlar havai fiseklerle patlarken 

Yilbası kutlayacağız insanlar aç yatarken 

Oynayıp gülecegiz canlı savaş izlerken 

Utanma, sıkılma, arlanmadan bize ne 

Ülkemde oynanan oyunlar ince 

Devletin malı satılıyor cömertçe 

Aydın yazarımız vurulurken kalleşce 

Isyandan,aglamaktan,haykırmaktan bize ne 

Ozan Güner duyma görme karişma 

Kemik yiyen ite fazla yanaşma 

Kardeşlik dostluk bariş için ugraşma 

Savaştan, açliktan, Felaketten bize ne 

Güner Kaymak / Amsterdam 10.12.2004', 'Bayram kutluyoruz dostlar bakın bayram  Mafyadan hortumcudan anarjiden bize ne  Varsın yaşasın bize değmeyen yılan  Haktan, hukuktan, adalet...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bize-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güner Kaymak', 'guner-kaymak-guner-kaymak-clvy9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Garip kaldım yad ellerde yıllarca 

Üzerime dertler yıgıldıkça yıgıldı 

Neleri yaşadım senelerce aylarca 

Emeklerim hep yalan oldu dağıldı 

Resimlerimde ne saçlarım varıdı 

Kin nefret nedir asla bilmezdim 

Allah''tan korkar haram yemezdim 

Yoksulu yetimi hakir görmezdim 

Mala mülke ehemmiyet vermezdim 

Alnım ak başım dikti çok zaman 

Kalbimde aşk eksilmedi bir an 

Ozan Güner Kaymak

Amsterdam / 02.01.2004', 'Garip kaldım yad ellerde yıllarca  Üzerime dertler yıgıldıkça yıgıldı  Neleri yaşadım senelerce aylarca  Emeklerim hep yalan oldu dağıldı  R...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/guner-kaymak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicivler-1', 'hicivler-1-ugur-deniz-ulkegul-46onn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu edep konusuna takıldı kafam 

Yavaş gel, arada bi duruvee gaari.. 

Anlattılar seni, ''çok bilen'' mişsin 

Sadakadır yüzüme gülüvee gaari… 

Ben, ona dediydim sana ne oldu? 

Gerildin, depreştin laf mı dokundu, 

Bak, sizin camide selam okundu, 

Cenazeme lütfet, gelivee gaari… 

Amcama sorduydum iyidir dedi, 

Sakınmaz, sözünün eridir dedi, 

Burnu biraz büyüktür iridir dedi, 

Cümüğünden bize de sürüvee gaari.. 

He ya, deliyim ben, kaçıkım biraz, 

Anlamam kıvırmaktan, açıkım biraz, 

Sözü de toplayamam, saçıkım biraz, 

Bi zahmet buyur da, derivee gaari… 

Sola gettik bize, sağı gösterdi, 

Sağa sorduk bizi, sola dönderdi, 

İmam mersedesle yola gönderdi, 

Şu vaazın özünü deyivee gaari.. 

Bizim evde sular, niye akmeyo? 

Hep ıslak kartonlar, soba yakmeyo, 

Kadın pas vermeyo, bize bakmeyo, 

Beyliğin de sırrını, açıvee gaari… 

Kızım var korkuyom, ele vermeye, 

Sazım var korkuyom, dile gelmeye, 

Komşuyuz gelecem, size gelmeye, 

Bi zahmet evinde duruvee gaari.. 

Ödümü patlattın, haşlama beni, 

Kafam kalındır diye, taşlama beni, 

Başkası sanıp da fişleme beni, 

Arada bi gönlüme bakıvee gaari.. 

“Hoş görü” diye diye, boş kaldık beyim, 

Kol getti, bacak getti, baş kaldık beyim, 

Tuzun kuru galiba, yaş kaldık beyim, 

Cebimize üç guruş, koyuvee gari…. 

Arabanın lastiği, üstümden geçti, 

Lastik de patlakmış, yarımdan biçti, 

Namıssızın oğluymuş, e vurdu kaçtı, 

Şoförsün ya, hastaneye atıvee gaari.. 

Aman gelme caydım, acemisin sen, 

Cerrah diye kasaba gotürürsün sen, 

Suya gidip de susuz, getirirsin sen, 

Şöyle yanımdan geçip, gidivee gaari.. 

Söz deyince arifsin, anlarsın beni, 

Bir omuzda devirir, yanlarsın beni, 

İyi düşün boş yere, zan’ larsın beni, 

Git “Merkez Efendiye” soruvee gaari… 

Ukela diyecem, yanlış olacak, 

Büdela diyecem, hep garışacak, 

Meşrebini bilsem, anlaşılacak, 

Deniz, yetişir artık, susuvee gaari…', 'Şu edep konusuna takıldı kafam  Yavaş gel, arada bi duruvee gaari..  Anlattılar seni, ''çok bilen'' mişsin  Sadakadır yüzüme gülüvee gaari…  B...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/hicivler-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Don''t go / Gitme', 'don-t-go-gitme-nuri-can-wyir3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gitme 

figan düşer denizlere sular çekilir 

yağmur yağmaz vahalardan kirpiklerime 

bir rüzgar hıçkırır tenhada, bir dal kırılır 

boynunu büker kır çiçekleri kelebekler ölür 

gitme 

bir yıldız küser göğüne, içini çeker bir çocuk 

şaşırır yönünü rüzgarlar 

bütün pınarların suyu çekilir 

solar nazlı çiçekleri kalbimin, üzülürüm 

gitme 

öksüz kalır içimdeki imge dağları 

saçlarını öpen seher yeli, çoban yıldızı 

bir daha turnalar geçmez, bülbüller ötmez 

çiçekler açmaz bahçemde ah gülüm 

gitme 

acılara mahkum olur yüreğim 

ardında fırtınalar kalır, ayrılıklar, anılar, yanlızlıklar 

boynu bükük aşklar, gözü yaşlı şarkılar 

alışamam yokluğuna, yokluğun ölüm 

gitme 

içimdeki bütün vagonlar devrilir 

bir kar yağar istasyonlara, üşürüm 

gitme kal sevdiğim terketme beni 

umutsuz çaresiz bekletme beni 

bütün ormanlar ateşe verilir 

kuşlarda gider bu kent de, ölürüm 

gitme kal 

menevşeler açsın dağlarda 

sevince dönüşsün gökyüzü 

iki çığlık arasında bırakma beni ah gülüm 

yokluğuna alışamam yokluğun ölüm 

gitme 

bütün ormanlar ateşe verilir 

kuşlarda gider bu kent de, ölürüm

Don''t go

Don''t go 

a cry of lamentation falls onto the seas, water withdraws 

it stops to rain from the oasis onto my eyelashes 

a wind sobs in solitude, a twig is broken 

wild flowers look down, butterflies die 

don''t go 

a star refuses its sky, a child inhales sadly 

winds get confused where to blow 

all springs dry 

the coy flowers of my heart fade, I become sad 

don''t go 

the mountains of imagination inside me, the northern star, 

the early morning wind kissing your hair become orphans 

cranes cease to pass by, nightingales cease to twitter 

flowers cease to grow in my garden, oh my love 

don''t go 

my heart is sentenced to pains 

storms, separations, memories and loneliness is left behind you 

Loves looking down, songs with wet eyes 

I can''t get used to your absence, your absence is death 

don''t go 

the trains inside me turn upside down 

it snows on the stations, I get cold 

don''t go, stay my love, don''t leave me 

don''t make me wait hopeless, helpless 

all forests burn 

the birds go, this city goes, I die 

don''t go, stay 

let violins grow on the mountains 

let the sky turn into happiness 

don''t leave me between two screams, my rose 

I can''t get used to your absence, your absence is death 

don''t go 

all the forests burn 

the birds go, this city goes, I die,

Alıntı.

www.turkishclass.com

http://www.turkishclass.com/poem_109_4_averageVisitor_none_none

.

GEH NICHT

Geh nicht,

Die Trauer fällt in die Meere, das Wasser versickert,

der Regen hört auf zu regnen aus den Tälern auf meine Wimpern,

ein Wind weint verlassen, ein Ast zerbricht,

die Morgenkarawanen beugen das Haupt, 

die Schmetterlinge sterben aus…

geh nicht, 

ein Stern wendet sich ab von seinem Himmel, 

ein Kind seufzt weinerlich, 

der Wind vergisst seine Richtung, 

alle Quellen vertrocknen, 

alle zierlichen Blumen meines Herzen verblühen,

und ich werde mich in Trauer verhüllen…

Geh nicht,

die Berge meiner Vorstellung verwaisen,

der Morgenwind, der dir die Haare streift, der Morgenstern,

die Gänse ziehen sich zurück, 

die Nachtigalle singen nicht mehr

die Blumen wachsen nicht mehr in meinem Garten, 

ach, meine Rose…

Geh nicht,

Mein Herz wird zum Schmerz verurteilt,

Es bleibt ein Sturm, die Erinnerungen, die Trennung

in sich versunkene Lieben, in Tränen fließende Lieder, 

kann deine Abwesenheit nicht ertragen, 

sie gliche dem Sterben…

Geh nicht,

alle Wagons in mir würden entgleisen,

Ein Schnee würde fallen auf die Bahnhöfe, 

ich würde erfrieren… 

Geh nicht,

Die Veilchen sollen blühen auf den Bergen,

Der Himmel soll sich in Freude verwandeln, 

lass mich nicht in Mitten eines Herzensschreies,

ach, meine Rose…

kann deine Abwesenheit nicht ertragen, 

sie gliche dem Sterben…

Geh nicht,

alle Wälder würden brennen, 

Die Vögel würden sich verziehen, 

Von diesem Ort,

Und ich würde sterben… 

Hip pop  Şarkı klibi olarak  dinleyip izleyebilirsiniz.

Şiir olarak izleyip dinleye bilirsiniz.

http://www.youtube.com/watch? v=Qap0fBHUQjg', 'Gitme  figan düşer denizlere sular çekilir  yağmur yağmaz vahalardan kirpiklerime  bir rüzgar hıçkırır tenhada, bir dal kırılır  boynunu bük...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":121,"source_url":"https://www.antoloji.com/don-t-go-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diriliş...', 'dirilis-mehmet-asim-jh4jc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni  uykusuzluğumdaki 

Düşlerim kadar seviyorum,

Ey zamanımın hüzne doğan 

Gecesi.

Mevsimimin gül kurusu rengi

İçine acı çalınan,

Tüm yaşanmışlıklarımın tövbesi! 

Bir kıssadan türettiğim 

Noktamalı yaşayışlarım.

Ağır ağır ve bile bile ilerlediğim,

Hayatımın farkında olduğum yanı.

Yani koklamak gibi,

Yani özümsemek gibi,

Tüketmek gibi,belki bitirememek gibi.

Öylesine benden 

Eksilen bir yanım gibi,

İçimdesin ve çoğalıyorsun.

Çoğalıyorsun ve taşıyorsun

Gölgelerimin sahteliğinden.

Ufukta oynaşan hep o karartılar,

En belirgin anlamlarına

Bürünüyor şimdi.

Ruhum böylesine 

Saydamsı bir  berraklığa bürünmüşken,

Geçirgenliğinden  korkuyor  yaşamın

Zoraki anlarının.

Hep o meydanlarda ilerliyor

Bir süvari ve dakikaları...

Mekan ne kadar tanıdık

Ve zaman ne kadar uzak.

Hüzün bu kadar tazeykeb yüreğimizde,

Ne kadar bayatsı

Üzerimize gelen hayatın 

En tekerrür anları.

Eski rüyalarımdan hatırladığım,

En gerçeksi uyanıklığım.

Seni rüyalarımdaki özlemlerim 

Gibi seviyorum! 

Ve şimdi tam da

Kelimelerim dirilmişken varlığına,

Sana yeniden soruyorum; 

Pardon, sen hayatmısın? ...', 'Seni  uykusuzluğumdaki  Düşlerim kadar seviyorum, Ey zamanımın hüzne doğan  Gecesi. Mevsimimin gül kurusu rengi İçine acı çalınan, Tüm yaşan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/dirilis-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoldaş', 'yoldas-avni-aydin-1xiw4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'artık ne o eski aşklar kaldı 

ne de mutluluklar... 

tadı bile başka artık hayatın; 

gecen gunlere inat 

yaşanamayanlarla yoldaş...', 'artık ne o eski aşklar kaldı  ne de mutluluklar...  tadı bile başka artık hayatın;  gecen gunlere inat  yaşanamayanlarla yoldaş......', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yoldas-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Bir Yapraktır', 'sevgi-bir-yapraktir-nazim-yildiz-b7u3n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi bir yapraktır

Arasıra gözyaşları sulayacak

Elem keder oluşacak zamanla

Hasret toprak misali sevgiyi besleyecek

Bazen boyun büküp naz edecek sevgi

Daha fazla ilgi isteyecek

Mevsimler geçecek aradan iklim sertleşecek

Çabalar sonuç vermez olacak artık

Sevgi yaprak misali gazel olacak', 'Sevgi bir yapraktır Arasıra gözyaşları sulayacak Elem keder oluşacak zamanla Hasret toprak misali sevgiyi besleyecek Bazen boyun büküp naz e...', ARRAY['Türk Edebiyatı','Şiir','Nazım Yıldız']::text[], 8.5, '{"poet":"Nazım Yıldız","poet_slug":"nazim-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevgi-bir-yapraktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabus', 'kabus-mehmet-tan-bucj8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uğursuzluğun çığırından çıktığı,

Çağlayanların kızıl aktığı,

Taunların vurduğu,

Şimşeklerin çaktığı,

Bir Şubat akşamı-

Kutsadım ben ruhumu.

Kan kırmızısı bir kadeh şarap,

Tenha bir lokantada hali harap.

Bir elimde bıçağım,

Diğerinde çatalım.

Kendi kalbimi yedim- 

Yemek niyetine.

Çıktım lokantadan,

Yerde bir damla kan gördüm.

Eğildim usulca.

Kandan bir ayna, 

İçinde benim yüzüm.

Yüzümü kan revan gördüm! 

Yüzümün içinde bir yüz…

Bir çift parlak göz,

Çatlamış dudaklar, 

Ve bir burun,

Düzden daha bir düz! 

Kan etrafa sıçradı ansızın,

Bir göl oldu. 

Bir nehir,

Bir çağlayan oldu.

Yüzmeyi unuttum birden…

Kan günahlarım oldu,

Ve ben günahlarımda boğuldum! 



Sırtıma, hafif bir dokunuşla irkildim.

Başımı çevirdim,

Karşımda duruyordu.

Elinde bir asa beni hedeflemiş…

Saatime baktım birden,

Kadranı tam on ikiyi vuruyordu.

Gözlerimi kıstım, 

Yumruklarımı sıktım.

Yeminler ettim yüz binlerce kere.

Ben bu kabusta boğulmayacaktım.

Bir kabustu bu…

Mutlaka bir kabus olmalıydı.

Uyanmalı,

Gerçekliğin ta böğrüne-

Saplamalıydım mızrağı.

Uyan dedim kendime! 

Bir kez daha,

Uyan! 

Sıçrayarak kalktım yataktan.

Derin bir nefes aldım…

Evet, bir kabustu gördüğüm.

Yalnız çözmek istiyordum,

Neydi bu kördüğüm? 

Neden böyle tutarsız,

Acımasız,

Sisli puslu, 

Kan revan bir kabus? 

Perdeler aralandı birden,

Ve ben gördüm…

Bilinçaltım beni hoyratça hırpalıyordu! 

Çok çektirmiştim vaktinde,

Şimdi, benden intikam alıyordu….', 'Uğursuzluğun çığırından çıktığı, Çağlayanların kızıl aktığı, Taunların vurduğu, Şimşeklerin çaktığı, Bir Şubat akşamı- Kutsadım ben ruhumu. ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/kabus-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Zanaat', 'zor-zanaat-mehmet-tan-naoc9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kan sıçramış ellerime

Ve ben sesim yettiğince bağırabiliyorum

Yetişemiyorum sana ey sevgili

Neden bunca acele

Bekle hele

Azıcık soluklan şuracıkta

Takatim kalmadı bilesin

Nicedir bu ettiğin velvele

Yaşlandım ey sevgili

Elden ayaktan kesildim

Aşk dediğin zor zanaat

Ağırlığı altında ezildim', 'Kan sıçramış ellerime Ve ben sesim yettiğince bağırabiliyorum Yetişemiyorum sana ey sevgili Neden bunca acele Bekle hele Azıcık soluklan şur...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zor-zanaat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Diye', 'sen-yoksun-diye-nazim-yildiz-3kzuj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yoksun diye...

Çaresizlik sardı dörtbir yanımı

Ne güneşin batışını

Nede bir kez doğuşunu gördü gözlerim

Sen yoksun diye...

Kuşlar terketti yuvalarını

Yapraklar sarı sarı açmaya başladı

Çiçekler birer birer soldu bahçelerde

Sen yoksun diye...

Kalem kırdı hakimler

Gönlümü tutsak ettiler

Hep hasreti çileyi koydular önüme

Sen yoksun diye...

Gönlüme bir tutam sevgiyi çok gördüler

Gülmeyi çaldılar dudaklarımdan

Sen yoksun diye alnıma kara yazı yazdılar', 'Sen yoksun diye... Çaresizlik sardı dörtbir yanımı Ne güneşin batışını Nede bir kez doğuşunu gördü gözlerim Sen yoksun diye... Kuşlar terket...', ARRAY['Türk Edebiyatı','Şiir','Nazım Yıldız']::text[], 8.5, '{"poet":"Nazım Yıldız","poet_slug":"nazim-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-yoksun-diye-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle seslenir', 'gule-seslenir-tuncay-akdeniz-pif3a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GÜLE SESLENİR

İçimi yaralar bülbül ötüşü

Figanı zar eder güle seslenir

Derin duyguların sessiz akışı

Gönül çağladıkça sele seslenir

Karanlık geceye hüzün karışır

Ay yıldıza bakar güler konuşur

Sevda alevlenir yanar tutuşur

Kerem yanar aslı küle seslenir

Ferhatlar şirinler aşkın örneği

Gerçek aşıkların yanar yüreği

Dallarda üşürse gülün yaprağı

Titreşir seherde yele seslenir

Kırlardaki çiçek gülün aynısı

Denizdeki rengin sırdır mavisi

Ruhuna işlemiş suların sesi

Ötüşür turnalar göle seslenir

Alemde varlıklar dengi dengine

Gül bürünmüş elvan,elvan rengine

İstersen bülbülü gönder sürgüne

Mecnun Leyla için çöle seslenir

Gönlüme yerleşmiş gam ile keder

Tuncay  elledikçe derine iner

Duygular depreşir şiire döner

Kalem dile gelir ele seslenir        

					13.08.1999', 'GÜLE SESLENİR İçimi yaralar bülbül ötüşü Figanı zar eder güle seslenir Derin duyguların sessiz akışı Gönül çağladıkça sele seslenir Karanlık...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gule-seslenir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nukoza', 'nukoza-akin-akca-e5g1t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dışarı çıkmak için bekliyor.

Tabi bunu akıl edemez.

Ama yine de bilmiyor.

Çünkü bir gün oradan çıkacak.

Ummadığı şeylerle mücadele verecek.

Ama farkında, değer.

Şimdi, parmak emiyor.

Yüzüyor salgı sıvıda.

Çıkınca suya onu atacaklar.

Öğrenecek çırpına çırpına.

Ama şu an farkında.

Susayınca, sudan içecek de.

*

Hayatın amaçları süresiz gibi mi.

İçinde saklı güzel, bu sonsuzun.

Ve ölüm, o da.

Şu halde ayrılamaz ikisi.

Uzay-zaman.

İkisi de ilerler.

Geçtikçe vakit bebek emekler.

Tuhaf görünse de

Garip bir bağ var:

Sonsuzun içinde saklanan ölüm; 

Ölümün içinde barınan, tapınarak işkilli insana

Hiç darağacı olabilir mi

İnsan kestikçe kendi dalını da? 

Çıplak ve net, bu dürüst resmin görüntüsü; 

Çevresi onun yaşadıkları, merkezi de kendisi!', 'Dışarı çıkmak için bekliyor. Tabi bunu akıl edemez. Ama yine de bilmiyor. Çünkü bir gün oradan çıkacak. Ummadığı şeylerle mücadele verecek. ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nukoza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytani Yan Hasadı', 'seytani-yan-hasadi-akin-akca-bvyl2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doğanın şeytani yanı suçlayamaz mı insanı

Ya da cezalandıramaz mı, görüyoruz bunu.

Dünya’ya ya da yarın Güneş’e ne olur bilinmez 

Ama kutsal şey değil böyle suçluluk duygusu

Kendimiz için ektiklerimiz ve alıkoyan biz

Kendinden tabiatı ve onun kendisini de bizden.

Beyaz’ı kastettim sanılabilir ama siyah, kızıl…

Her bölgeden, her mezradan, kütle öbek-pıhtı.

Battı balık yan gider demekteyse, “böyle gelmiş

Böyle gider..” lafı, melek kollarıyla dallandıracağız

Yeşilin coşkusunu, hasadı tarladaki, kainatı.', 'Doğanın şeytani yanı suçlayamaz mı insanı Ya da cezalandıramaz mı, görüyoruz bunu. Dünya’ya ya da yarın Güneş’e ne olur bilinmez  Ama kutsal...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seytani-yan-hasadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veçhe|erde', 'veche-erde-akin-akca-43xyv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kazara

yarım bastığın ''enter'' tuşunun

daha ne olduğunu düşünürken

alıp götürüvermesi gibi seni

başka bir sayfaya yönelmek

internette aniden ilerleyerek', 'kazara yarım bastığın ''enter'' tuşunun daha ne olduğunu düşünürken alıp götürüvermesi gibi seni başka bir sayfaya yönelmek internette aniden ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/veche-erde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atlantis''in Düşü', 'atlantis-in-dusu-akin-akca-1swcp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Devasa sıradağlar kuşatmıştı sanıldığının aksine.

Onlar sarardı bir anda, akkor gibi oldu.

En bariz bir yükselişin en zirve döneminde! 

Devrildiler sıra sıra, hepsi som altından.

Bir iki bölge karlı alandı, 

Bazı çentik küçük alanlarsa çorak toprak.

Abandı külçeler bu yekpare kütleler.

İskenderiye’deki anıt miras bilgilerin

Talan edilişi gibiydi gaz odalarında! 

Verdiği mücadelesinde yılmayarak son nefese; 

Arthur’un düşüşü gibi, adalet uğruna! 

Yüzyıllar bekledi tarih Merlyn’in gelişini,

Taliesin olacaktı, kaptı duvarda serili çocukluk asasını,

Ak sakalı ve kukuletasıyla, çayırları yürümeye başladı.

Çayırların ötesi sisti.

Gözleri sırf ileriye dönük -kaşları çatık; 

Bir o kadar ve belki aynısı, kararlı

- Önündeki yolu süzmekteydi.

(Sonsuz mudur hipotenüsü dikdörtgenin?)

Getirilenlere takrar yaşatılması 

İçin çelişkileriyle Atlantis’in

Bilgi iyidir. Endüstri atığı yığınlar tehlikelidir. Ama faydalılar da en yoğun şekliyle buradan yola çıkar ki çıkar. Belki yaşanmalıdır, ama dizginleyerek olumsuz aşırı uçları. Cehaletin etkin hakim olduğu öbeklerdeyse bu şans yoktur, fark edenlerin dünyayı etkileyebilmesi uğruna.

-

iki resimden esin', 'Devasa sıradağlar kuşatmıştı sanıldığının aksine. Onlar sarardı bir anda, akkor gibi oldu. En bariz bir yükselişin en zirve döneminde!  Devr...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/atlantis-in-dusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Be adam', 'be-adam-tuncay-akdeniz-qor1o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zalim azabını mazlumlar çeker

İkisi de aynı insan be adam

Konuşamaz dili vicdan ter döker

Yaratılmış kuldur hasan be adam

Zaman devir olur biter dönemi

Hicran kalemiyle delme sinemi

İş işten geçince kalmaz önemi

Elden ele geçer asan be adam

Başını kaldırda bir bak yukarı

Ağustosa olma zemheri karı

Çiçeksiz kovana ne yapsın arı

Mart peşinden gelen nisan be adam

Rızasız arsaya temel atıldı

İbret meydanında tören yapıldı

Hatır pazarında ikram satıldı

Kimi kime ettin ihsan be adam

Koyma akıl ile kafa değişti

Alimler yerine cahiller geçti

Emir makasları çok kumaş biçti

Tatlı yiyip zehir kusan be adam

Tuncayım  insandı hiçe sayıldı

Haksızlar korundu haklı kıyıldı

Oturduğun koltuk yetim malıydı

Şimdi kime kalmış masan be adam

					20.09.1997', 'Zalim azabını mazlumlar çeker İkisi de aynı insan be adam Konuşamaz dili vicdan ter döker Yaratılmış kuldur hasan be adam Zaman devir olur b...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/be-adam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Horozum', 'horozum-mehmet-halil-7fxs5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece ile gündüzü bölen horozum,

Yüzyıllarca, insanları uyandırdın.

Güzel sesin, tüylerin, kuyruğunla,

‘’Bekçi Murtaza’’ yı kıskandırdın.

senden erken davrandılar onlar da

Zamanı ikiye bölmeye başladılar…

Anayasa… Muhtıra….  Darbe…

Güzel ötüyoruz diye; anırdılar.

Güzel sesli horuzum benim,

kıskananlar, sana benzemeye çalıştılar.

Buna, çok uğraştılar; ben şahidim,

Ama, bir türlü başaramadılar.

Şimdi, kendilerine benzetmek için,

Özel eğitim veriyorlar sana, 

Döğüşmen için mahmuzlarını bileyip,

Sokuyorlar seni illegal hayatlarına.

Güzel horozum, müjdecim benim,

dışı gibi değil onların içi, baştan sona kir.

Mahmuzlarını, düşmanlık öğretenin,

Kana susamış, kızıl gözlerine geçir.', 'Gece ile gündüzü bölen horozum, Yüzyıllarca, insanları uyandırdın. Güzel sesin, tüylerin, kuyruğunla, ‘’Bekçi Murtaza’’ yı kıskandırdın. sen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/horozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Türkiye', 'guzel-turkiye-tuncay-akdeniz-a7op0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Türkiye’nin Anadolu vatanı

Yaylası ovası güzel Türkiye

Tarih de yazılı Türk’ün destanı

Mimari yapısı güzel Türkiye

Milleti çağırır toplum birliğe

Ayrım yapmaz şehirliye köylüye

Yerel yönetimde var belediye

Şehirli köylüsü güzel Türkiye

Çalışkandır işi ile uğraşır

Milli  gelirini herkes paylaşır

Komşusunu kapı,kapı dolaşır

Dostluğu komşusu güzel Türkiye

Milleti hürmetli güler yüzlüdür

Yalanları sevmez doğru sözlüdür

Dini İslam inancına bağlıdır

Ezanı duası güzel Türkiye

Bağlı kalır anayasa kanuna

Sahip çıkar kültürüne varına

Gelecek hazırlar dede toruna

Kanunu yasası güzel Türkiye

Tuncayım Türkiye benim canımdır

Bayrağının rengi şehit kanıdır

Edirne den Ardahan’a vatandır

Osmanlı mirası, güzel Türkiye           01.10.1998', 'Türkiye’nin Anadolu vatanı Yaylası ovası güzel Türkiye Tarih de yazılı Türk’ün destanı Mimari yapısı güzel Türkiye Milleti çağırır toplum bi...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guzel-turkiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah köyüm', 'ah-koyum-tuncay-akdeniz-lrydb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göç eyledik köyden geldik

Ah köyün işine kurban

Gurbet elde işsiz kaldık

Ah köyün boşuna kurban

Gece kondu var evimiz

Işıksızdır her gecemiz

Boş kaynıyor tenceremiz

Bulgurun taşına kurban

Yorgan mitil yoktur yastık

Soğuktan üşüdü mıstık

Deliklere kağıt bastık

Soğukla kışına kurban

Dayan yavrularım dayan

Halımızı olmaz soran

Günlük yemek acı soğan

Ayrandan aşına kurban

Bayram nedir biz görmedik

Tere yağı et yemedik

Ütülü gömlek giymedik

Çarıkla puşu na kurban

Eğis kanser verem çoktu

Sıra gelmez doktor yoktu

Hep tahliller bozuk çıktı

Ağlama  yaşına kurban

Tuncay in gülmüyor yüzü 

Göç ayırdı köyden bizi

Çoban oldum yaydım kuzu 

Dağların döşüne kurban

				20.07.1998', 'Göç eyledik köyden geldik Ah köyün işine kurban Gurbet elde işsiz kaldık Ah köyün boşuna kurban Gece kondu var evimiz Işıksızdır her gecemiz...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ah-koyum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Sıçan', 'i-ki-sican-ali-kilic-kakiz-teuhy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki sıçan yürürler yol kenarında peş peşe 

Nerden bilecekler, duymazlardı endişe. 

Olmaz deme, hayvanda olsa vardır derdi. 

Çıkmaz mı! önlerine koskoca kara bir kedi. 

Erkeği,  sen geri dur dedi, ben geçeyim öne. 

Pevkirdi, hav hav gibi, sağa sola döne döne. 

O kaçış kaştı bizim kedi, arabul erkeksen. 

Yabancı dil bilmenin faydasını görürmisen? 

Paris / Temmuz 2005', 'İki sıçan yürürler yol kenarında peş peşe  Nerden bilecekler, duymazlardı endişe.  Olmaz deme, hayvanda olsa vardır derdi.  Çıkmaz mı! önler...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iki-sican-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Fazla Bekletme', 'daha-fazla-bekletme-ozkan-gonlum-l3gg3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çektiklerim hep senden

Soldurdun sen gülümü

Göze aldım ölümü	

Çek tetiği vur beni.

Sona ersin bu çilem

Bitsin artık bu derdim

Göz kırparsam namerdim

Çek tetiği vur beni.

Daha fazla bekletme

Senin olsun şerefi

Buldun işte hedefi

Çek tetiği vur beni.

Korkmam asla ölümden

Sanma gözüm yaşarır

Bir tek kurşun başarır

Çek tetiği vur beni.

Çekseler ipe beni

Son sözüm sen’ i derim

Gerisi Allah kerim

Çek tetiği vur beni.', 'Çektiklerim hep senden Soldurdun sen gülümü Göze aldım ölümü	 Çek tetiği vur beni. Sona ersin bu çilem Bitsin artık bu derdim Göz kırparsam ...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/daha-fazla-bekletme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derya (akrostiş)', 'derya-akrostis-serhat-yucel-6n5m2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'D ünya gözü ile seni görmek güzel

E vet içimde bir sevda besledimki sana özel

R üyalarımı süsler oldun hep geceler boyu

Y anlızlığımda düşünüyorum seni koyu,koyu

A LLAH''ım bana neden vermiş bu güzel huyu?', 'D ünya gözü ile seni görmek güzel E vet içimde bir sevda besledimki sana özel R üyalarımı süsler oldun hep geceler boyu Y anlızlığımda düşün...', ARRAY['Türk Edebiyatı','Şiir','Serhat Yücel']::text[], 8.5, '{"poet":"Serhat Yücel","poet_slug":"serhat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/derya-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurdo Namûs e Rabe', 'kurdo-nam-s-e-rabe-cigerxw-n-na7dn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurdo namûs e rabe, 

Ji bo me qet we nabe, 

Li şorişê tên kuştin, 

Li vir vexun şerabe! 

Ji bo fidakariyê, 

Em dernegan vekin zû, 

Da birayên îranî, 

Li me nekin îtabe. 

Mal û çekan verêkin, 

Canbezaran bişênin, 

Li wir birçî dimênin, 

Li vir dixun kebabe! 

Kelaşinkof li milde, 

Wek Erdeşêr û Şêrkoh, 

Ala Kawa tu hilde, 

Guh med li afitabe. 

Eger divê azadî, 

Tu guh mede li sadî, 

Zû derkeve ser şaxan, 

Hetta roja me jî bê! 

Le ger tu jinperestî, 

Welat divê bi sistî, 

Hêvî dikî tu avê, 

Ji leylan û şerabe! 

Zanim tu xweş egîtî, 

Bermayê Mad û Mitî, 

Di serde rengê şêrî, 

Li Baximiz û Hebabe! 

Gel dixwazî tu rabî, 

Weke şêr û gura bî 

Dijmin tu zû dişkênî, 

Eger tu wek bira bî. 

Çil sale dilbirînim, 

Cerg û hinav bi xwînim. 

Welatparêzî lew ez, 

Dixwazim zû tu rabî! 

Cigerxwîn', 'Kurdo namûs e rabe,  Ji bo me qet we nabe,  Li şorişê tên kuştin,  Li vir vexun şerabe!  Ji bo fidakariyê,  Em dernegan vekin zû,  Da birayê...', ARRAY['Türk Edebiyatı','Şiir','Cigerxwîn']::text[], 8.5, '{"poet":"Cigerxwîn","poet_slug":"cigerxw-n","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kurdo-namus-e-rabe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-sair-ahrazi-gevqp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman tâ uzakta; mahşer avlusu bir yerin,

Devâsâ yüküyledir; her parçası yıl tutar.

Geniştir ki,mâziden binlerce defâ derin,

Ve binlerce makberin,yarın ki hizâsı var…

* * *', 'Zaman tâ uzakta; mahşer avlusu bir yerin, Devâsâ yüküyledir; her parçası yıl tutar. Geniştir ki,mâziden binlerce defâ derin, Ve binlerce mak...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zaman-183-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldüm sanacaklar', 'oldum-sanacaklar-galip-kemali-gunay-od6bw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şarkıların seni söylemediği gün,

Sorgu sual taşındayım.

Türküler ve cemaat, oh be kurtulduk....

Diyecek 

Öldüm sanacaklar', 'Şarkıların seni söylemediği gün, Sorgu sual taşındayım. Türküler ve cemaat, oh be kurtulduk.... Diyecek  Öldüm sanacaklar...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/oldum-sanacaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-volkan-yoruc-610zb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyku haram bana

Özlem içimde ateş senden yana

Küller birikmiş yüreğimden bakar olmuşum yakamozuma

Gelde ağlama şu gavur ölüsü yalnızlığıma', 'Uyku haram bana Özlem içimde ateş senden yana Küller birikmiş yüreğimden bakar olmuşum yakamozuma Gelde ağlama şu gavur ölüsü yalnızlığıma...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalnizligim-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Veriniz', 'gul-veriniz-huseyin-kerim-ece-nj1gu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bütün çiçekleri çok severim amma, önce

Candan dostlarıma ve bana gül veriniz

Bilirim yine bayram sevinciyle karşılar 

Birazcık mahzun kalan canâna gül veriniz

Bu hangi fasıldır ki, bağı müzeyyen eder

Muhabbetleri artsın, yârâna gül veriniz

Belki insafa gelir, belki de tevbe eder

Hatta olur ya, eski düşmana gül veriniz

Kalbinizde karartı kalmasın, gün ışısın

Yiğitlik budur; zehir sunana, gül veriniz 

Bitmez bu âlemin gamı, telaşı, yası

Yüreklerde çoğalan tufana gül veriniz

Heyhat, devir değişti, kirlendi coğrafyamız

Evrene gül veriniz, zamana gül veriniz

O Gül ki merhemdir, o ki serâpa kurtuluş

Onun için ğayyâ’da kalana Gül veriniz

4.11.2004

Zaandam', 'Bütün çiçekleri çok severim amma, önce Candan dostlarıma ve bana gül veriniz Bilirim yine bayram sevinciyle karşılar  Birazcık mahzun kalan ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gul-veriniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Oluşun İşe Yarasın', 'yar-olusun-i-se-yarasin-huseyin-kerim-ece-q6enl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dedim; yâr ol ki, yâr oluşun işe yarasın

Yetimce yüreğime bir kaç sevinç damlasın

Sevgili dilinde sen ki tatlı bir yara’sın

Senin yaranı yalnız halden bilen emlesin

Halden anlayan dostum, sana olsun merhaba

Bu öyle bir taddır ki sığmaz hiç bir hesaba

Yakın ol, yakınlaşsın duvar ötesi yüzler

Birbirine bir ayna olsun içteki benler

Neyleyim kahkahayı, ağlıyorken öksüzler

Yanyana duruyorken yaban kalan bedenler

Halden anlayan dostum, sana olsun merhaba

Bu bahçeye su taşı, boşa gitmez bu çaba

Hânen açık kalsın ki, hızır sana uğrasın

Yeşil örtüler kapat yangınların üstüne

Tabiat ana seni aşkla bağrına sarsın

Selâmın yaygın olsun, hem düne hem bugüne

Halden anlayan dostum, sana olsun merhaba

Bak, bizi çağırıyor önden giden bir baba

15.2.2005

Zaandam', 'Dedim; yâr ol ki, yâr oluşun işe yarasın Yetimce yüreğime bir kaç sevinç damlasın Sevgili dilinde sen ki tatlı bir yara’sın Senin yaranı yal...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yar-olusun-ise-yarasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıra Kaldı Zaman', 'hatira-kaldi-zaman-huseyin-kerim-ece-ddu25', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne oldu anlayamadım, günler ve geceler geçti

Bu iklimde bir hayli vaktimi aldı zaman

Ötelere baktım ki sükûttan başka yâr yok

Beni bir ıssızlığa peşinen saldı zaman

Kum saatinde vakit eriyor, görmedin mi? 

Bu yırtık heybemde git gide azaldı zaman

Demek ki ağacın kökü yok, yapı çürük

İşte yaşadık, say ki aynen masaldı zaman

Bir rüya gördüm dostlar, tabirini bilen yok

Sanki bu âlemde bir garip sanaldı zaman

Gün aşıyor ufuktan, kâinat değişiyor

Galiba sır gibi, bir hatıra kaldı zaman

3.12.2004

Zaandam', 'Ne oldu anlayamadım, günler ve geceler geçti Bu iklimde bir hayli vaktimi aldı zaman Ötelere baktım ki sükûttan başka yâr yok Beni bir ıssız...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hatira-kaldi-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güllerden Kına', 'gullerden-kina-huseyin-kerim-ece-rk1rq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mektubuma bir cevap aldım, yandı ışıklar

Bahçemi tezyin etti gül gibi sarmaşıklar

Ötelerden meclise saygın bir sefir geldi

Soframıza melekler yine misafir geldi

Kulağımızda suyun bestesi yankılandı

Ufukta güneş yalnız hayat için uyandı

Mehtabın çizgileri yalarken elimizi

Dolunay aşk rengine boyar mavi denizi

Matemli günleri bu sevinçler savuşturdu

Serçe kendi tüyüyle yüzünü oğuşturdu

*Menzil:

İddialı sevdalar vardı, ama yalandı

Gerçek sevgi yeniden yürekte mayalandı

Bildim aşkın bu yerde ateşten bûsesini

Her avazdan ayırdım tutkunun bu sesini

Gönlüme yerleştirdim goncagül tomurcuğu

Bu da ebediyetin solmaz, ölmez çocuğu

Onun için yürekte sonsuzluk yankılandı

Ruhum ona kendini candan feda kılandı

İstedim ki onunla menzile yürüyeyim

Ağyarla değil, yanlız dost ile yürüyeyim

Ufuk açılsın, ışık doğsun o maveradan

Bana derin bir sevda kalsın bu maceradan

*Vuslat:

Bu sevda ile yürek erecek vuslatına

Onun elleriyle hem varacak beratına

Şiirler yazdım çiçek üstüne, gül aşkına

Yürekte filizlenen güllerle yaktım kına

Efendim dedim, selâm verdim kâinat kadar

Ona bağlandım asır süren bir inat kadar

Zira odur sevginin adresi bu hayatta

Gerisi neye yarar; o yoksa kâinatta

Zamanı şenlendiren sevgiye selâm olsun

Haktan hibe olunan vergiye selâm olsun

Yüreğimiz dinlensin sevgilinin yâdıyla

Şehâdetimiz tamam olsun onun adıyla

Onun gülünde binbir rengin bayramı vardır

Onun yolunda olmak vuslatsa; bu kadardır', 'Mektubuma bir cevap aldım, yandı ışıklar Bahçemi tezyin etti gül gibi sarmaşıklar Ötelerden meclise saygın bir sefir geldi Soframıza melekle...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/gullerden-kina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Mine', 'deli-mine-huseyin-kerim-ece-qcreg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'DELİ MİNE

Üzerine çullanan kabûsları saymadın

Sana korku taşıdı uyandığın şafaklar

Gecenin karardığı ana korkuyla baktın

Sana tekin gelmedi yakınlar ve uzaklar

Yanar gözbebeğinde bu çağdaş tuhaflıklar

Bir kelepçeye benzer sokaktaki ışıklar

Ne kadar uzak kaldı özlenen aydınlıklar

Bir bak, sana benziyor boyun eğen başaklar

Anlam veremiyorsun bu acayip gidişe

Burada hayatın bir adı da; saf endişe 

Nasıl güven duyarsın bin sahtekâr gülüşe

Her bir köşe başında bekliyorken tuzaklar

Anladın deli Mine, işte böyledir dünya

Asla gerçek olmuyor görülen tatlı rüya

Hani yitiğini bir gün bulacaktın; güya

İmkan var mı serseri dolu iken sokaklar? 

Kime şikayet etsin halini deli Mine

Derler ki ‘be kadın git işine; deli mi ne? ’

6.5.2004 

Zaandam', 'DELİ MİNE Üzerine çullanan kabûsları saymadın Sana korku taşıdı uyandığın şafaklar Gecenin karardığı ana korkuyla baktın Sana tekin gelmedi ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/deli-mine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Yok Beni Çağıran Mevsimin', 'adi-yok-beni-cagiran-mevsimin-hatice-kuzu-mn6eq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bahçemde açan çiçekler 

Yalan söylüyor bahar geldi diye. 

Sert bir rüzgar savurur ya yaprakları 

Vurur ceza verircesine yerden yere … 

Ezgisinde bir başka melodi var rüzgarın, 

Kokusu uzaklaştıkça tükeniyor  tadı baharın… 

Yağan yağmur değil ıslaklığımın nedeni, 

Denizden daha mavi gözlerin.. 

Yalpalıyorum ıssız kaldırımlarda, 

Nereye gideceğimi bilmeden, 

Öylesine delice. 

Öylesine biçare.

Adı yok beni çağıran mevsimin 

İçimde bin özlem büyüyor bilinmeyene, 

Depreşiyor sensizliğim, 

Susuyorum… 

Derdimi paylaştığım yıldız kayıyor 

Tüm çığırtkanlığıyla 

Ben yürüyorum,zaman duruyor 

Akmaz oldu gözyaşım, 

Ben çaresizim, 

İm çaresiz …

15.03.2005', 'Bahçemde açan çiçekler  Yalan söylüyor bahar geldi diye.  Sert bir rüzgar savurur ya yaprakları  Vurur ceza verircesine yerden yere …  Ezgis...', ARRAY['Türk Edebiyatı','Şiir','Hatice Kuzu']::text[], 8.5, '{"poet":"Hatice Kuzu","poet_slug":"hatice-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/adi-yok-beni-cagiran-mevsimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekledim Gelmesini', 'bekledim-gelmesini-huseyin-kerim-ece-s3c09', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(Bekledim gelmesini, elinde bir demet gül

Ya da sıcak küllerden arta kalan bir kaç köz 

Kazası gelecek bir zamana kalan öçle

Ya da hiç yaşanmayan bir eylûl sabahıyla) 

Kış bu, perdesini bir yarasa kanadıyla

İndirirken, sen yola bakar durursun yine

Ne seni gören olur, ne de hiç bir okuyan

İçinde bir saatte değişen mevsimleri 

(Bekledim gelmesini, elinde ateşten kor

Ya da asırlarca hiç okunmayan mektupla

Bilirim dilleri lâl âşıkları, anlarım

Ufuklara yazılı hayal ülkesini de)

Kış bu, perdesini bir celladın türküsüyle

İndirirken yoluna, sen avluya çıkarsın

Ne seni duyan olur, sana ait dünyanda

Ne de güvercin döner bu gece, ötelerden

22. 6. 2004 

Zaandam', '(Bekledim gelmesini, elinde bir demet gül Ya da sıcak küllerden arta kalan bir kaç köz  Kazası gelecek bir zamana kalan öçle Ya da hiç yaşan...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bekledim-gelmesini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimin Sen Kıyısı', 'i-cimin-sen-kiyisi-orhun-basat-jefjp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I

gelgit ruh halleri 

git gel kapalı kapılar

beni sensizlikle yetim geceler anlar

bitişleri anlatan

başka baharların insanıyım 

iklimini soluyan 

susmak günahsız değildir çoğu zaman

II

hüznün doğum yeri yazmaz kimliğinde 

ve yoktur mezarı 

nasıl adı yoksa bu  bitişin

celladın şefkati kadarmış sevişin 

sensiz yaşamak rus ruleti 

akşama kurulmuş sofralarda

simsiyah duvarlarımda kalan

buz beyazı gidişin

III

hırçın dağ başısın birebir

kaldır bu gece mehtabı düştüğü yerden 

bir sevgili sanıp da  sokulduğu denizden

yamaçlarına getir...

IV

çıplaklık ayıp olmadı hiç senken

çünkü biz hiç sevişmedik

unutulmuş şiir hayaletleri 

bir suskunun çağrısında

geceyi içerken 

gözlerimizi dinledik

 V

ben / dişi bir ağıza pusu kurmuş 

deli bıçak ışıltısı...

çingene saatlerinde gecenin 

göçtü soğuk iklimlere 

bir yerlerimi acıtıp

içimin sen kıyısı..

nafile beklemek sabahları 

günaydın geceyarısı...', 'I gelgit ruh halleri  git gel kapalı kapılar beni sensizlikle yetim geceler anlar bitişleri anlatan başka baharların insanıyım  iklimini sol...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/icimin-sen-kiyisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelince', 'sen-gelince-abidin-guneyli-eynpl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece                          

İyi geceler diler 

     sen gelince

Sen gelince

Bahar kokusu  yayılır		        		

                 sessizce

Sen gelince gül tadında    			                          yaşam başlar

Anlarım 

Cemrenin suya düştüğünü

          Mimozalar baharı süslerken

          Sevdayı ertelemek olmazdı

          Eridi dağların karı 

                                    yandı yüreğim

                                    sen gelince	

                      			   Abidin GÜNEYLİ', 'Gece                           İyi geceler diler       sen gelince Sen gelince Bahar kokusu  yayılır		        		                  sessizce S...', ARRAY['Türk Edebiyatı','Şiir','Abidin Güneyli']::text[], 8.5, '{"poet":"Abidin Güneyli","poet_slug":"abidin-guneyli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-gelince-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Milletiz Biz', 'tek-milletiz-biz-abidin-guneyli-xq1u0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yer yüzünde eşi dahi olmayan

Yüz yıllardır mavi gözü solmayan

Düşmanından bir an dahi yılmayan

Bir ata’ya sahip tek milletiz biz

Ordusuz savaşa kararı veren

Dağılan milleti gül gibi deren

Kurşun yağmuruna göğsünü geren

Bir ata’ya sahip tek milletiz biz

Asker dağıtılmış izne salınmış

Edirne adana mersin alınmış

Anadolu parça parça bölünmüş

Vatanı kurtaran tek milletiz biz

                                    Abidin GÜNEYLİ', 'Yer yüzünde eşi dahi olmayan Yüz yıllardır mavi gözü solmayan Düşmanından bir an dahi yılmayan Bir ata’ya sahip tek milletiz biz Ordusuz sav...', ARRAY['Türk Edebiyatı','Şiir','Abidin Güneyli']::text[], 8.5, '{"poet":"Abidin Güneyli","poet_slug":"abidin-guneyli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tek-milletiz-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '08-Ellerin Olmuş...', '08-ellerin-olmus-metin-yildirim-an6ph', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Koklamaya bile kıymadığım gül, 

Bir başka iklimde, solmuş dediler… 

Yıllarca kahrını çekti bu gönül, 

Hayırsız, ellerin olmuş dediler… 

İkimiz adına, hayaller kurdum, 

Bu kalbi sadece sevdana yordum, 

Geçen gün dostlara hatırın sordum, 

Sevdiğin vefasız kulmuş dediler… 

Bırakamaz dedim, seven seveni, 

Güldüler üstüme, yerdiler seni, 

Bir daha vurdular yürekten beni, 

Gözünde değerim, pulmuş dediler… 

En güzel çağlarım, uğrunda geçti, 	

Can versem önünde yine de hiçti, 

Tabipler ömrüme bir mühlet biçti, 

Miadım bir hayli, dolmuş dediler… 

Kolumda kelepçe, bağlı bileğim, 

Sırtımda yakasız, beyaz gömleğim, 

Fermana yazılmış yağlı ilmeğim, 

Kararda belâyı, bulmuş dediler… 

Almışlar başından, süslü tacını, 

Duyarım dinmemiş, yürek acını, 

Taramaz olmuşsun artık saçını, 

Kıymazdım teline, yolmuş dediler… 

Bir başka iklimde, solmuş dediler, 

Hayırsız, ellerin olmuş dediler, 

Tabipler miadım, dolmuş dediler, 

Ölürsem, tek çıkar yolmuş dediler…

Ölürsen, tek çıkar yolmuş dediler…

www.adinisiirlerkoysun.com

Adını Şiirler Koysun', 'Koklamaya bile kıymadığım gül,  Bir başka iklimde, solmuş dediler…  Yıllarca kahrını çekti bu gönül,  Hayırsız, ellerin olmuş dediler…  İkim...', ARRAY['Türk Edebiyatı','Şiir','Metin Yıldırım']::text[], 8.5, '{"poet":"Metin Yıldırım","poet_slug":"metin-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/08-ellerin-olmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu baska..', 'bu-baska-evina-berfin-tfy6n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Astim sol yanimi 

baharlari tukenmis

eskici dolabina

hani olur ya 

bir sonraki yasam 

bir sonraki baharlara...

Simdi mevsim kis 

olum uykusu 

kapida 

ha geldi 

ha gelecek...

15/03/2005

1845', 'Astim sol yanimi  baharlari tukenmis eskici dolabina hani olur ya  bir sonraki yasam  bir sonraki baharlara... Simdi mevsim kis  olum uykusu...', ARRAY['Türk Edebiyatı','Şiir','Evina Berfin']::text[], 8.5, '{"poet":"Evina Berfin","poet_slug":"evina-berfin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin Düşünce', 'derin-dusunce-aysun-erat-rxd0m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benden sonra kimseyi sevmeyecektin…

Ellerim….

Saçlarını okşarsa, senden başka baharın,

Taş olsun, tutulsun demiştin…

Çok seviyordun beni, benimdin.

Sadece benim.

Ne bencilce bir sahipleniş! 

Yanılmışım..

Hakkım da yok üstelik buna.

Hadi…

Sen tutmadın sözünü.

Affettim gitti! 

Sevmek de, yasaklanır mı hiç? 

Densizlik işte benimki! 

Ya o yeminler? 

Kafam karıştı iyice.

İşin yoksa, düşün dur.

Eğer varsa…

Neden çarpmadı onu? 

Kolaysa,

Çık işin içinden şimdi.

03/2005', 'Benden sonra kimseyi sevmeyecektin… Ellerim…. Saçlarını okşarsa, senden başka baharın, Taş olsun, tutulsun demiştin… Çok seviyordun beni, be...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/derin-dusunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimden Senfoniler', 'yuregimden-senfoniler-direnc-kose-qg6gy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığı büyütüyordu geceyi gözlerimde, kırlangıç seslerine nispet 

keder dolu sözcükler dökülüyordu dilimden; 

gece karanlığı büyütüyordu, yüreğim, yüreğine hasret çarpıyordu,

uzaktı bahar ve hep zamansızdı ayrılıklar, 

yüreğim titrek bir senfoni oluşturmuştu akıyordu yüreğine sessizce 

Gece yüreğime kurşun sıkarken, yüreğim  sevdaya sarılmıştı

gök yüzünün yedi rengi gözlerime akmıştı 

gece yalnızlığa hüküm sürmekte ve yaşam bütün evrenselliğiyle

akmaktaydı göz pınarlarımdan sessizce ve sebepsizce; 

Hüznüm zamansız yarınlara süzülmekte ve belkide yüreğine

işlemekteydi,

son vapurda limandan ayrılmıştı keder hüznüme yoldaş 

ve ben sensiz yarınlara tutsak gidiyordum

uzaklara,

Uzaklar düşüncemde derin yaralar açmıştı, zamansız 

ölüm çığlıkları beni senden, bedenimi sahipsiz 

yurdumdan alıp, uzak diyarlara sürgün dolu ayrılıklara 

sürükleyip tüketmişti sevdamızı.', 'Gecenin karanlığı büyütüyordu geceyi gözlerimde, kırlangıç seslerine nispet  keder dolu sözcükler dökülüyordu dilimden;  gece karanlığı büyü...', ARRAY['Türk Edebiyatı','Şiir','Direnc Köse']::text[], 8.5, '{"poet":"Direnc Köse","poet_slug":"direnc-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yuregimden-senfoniler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayandim Sinirina Yasamin...', 'dayandim-sinirina-yasamin-evina-berfin-i1plp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Susturdum 

tum soluklanislarimi

yazdim 

sonbahar yapragina 

en karasini sevdanin..

ve 

sundum dicle''ye

solmaya yuz tutmus

hayal - meyal 

yasanmamisliklarimi 

ve

seni

verdim en inceden

kirlangic yuregine

sicak iklimlere

yedi cografya 

.................. bilirim

usursun, 

usursun kucugum 

olmasa yuregini saran 

bu hazana durmus yurek 

ve 

seni 

daglarima birakiyorum

silinmisliginde 

gun batiminin 

........ ve ayak izlerimiz

koynunda 

patikalarinda 

kirk kilide inat 

yasama kosan delicesine 

sana fisildayacak 

en deli,

en ucari ruzgar

son ozgurluk turkumu

sevdasinda tutustugum...

inceden inceye

her bir teline yureginin...

ve

seni

olum uykusuna durdugum

yildizlara sarmaliyorum

sana isik

sana yasam

sana cosku

sana 

kollarimin sicakligini birakiyorum 

yildiz yildiz 

orttugum yuregimde 

ve 

seni.. 

sana...

yuregine

kutsanmisligina sevdamin

yuregimize 

biraktim...

ve 

simdi 

susmaliyim artik....

gozlerime sakladim

soylenmeyecek 

tum 

yetmez sozcuklerimi....

............ yetmeli bu, yetmezligimle...

uyumaliyim.. 

iyi geceler sevdam.. 

iyi geceler....

seni 

sevgime sardim.. 

sen uyurken 

sessizce.....

15/03/2005

1900', 'Susturdum  tum soluklanislarimi yazdim  sonbahar yapragina  en karasini sevdanin.. ve  sundum dicle''ye solmaya yuz tutmus hayal - meyal  yas...', ARRAY['Türk Edebiyatı','Şiir','Evina Berfin']::text[], 8.5, '{"poet":"Evina Berfin","poet_slug":"evina-berfin","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/dayandim-sinirina-yasamin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süveyda...', 'suveyda-i-brahim-ethem-bingul-p28qq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yayılmış İstanbul''dan 

Büyük yalan

Benim seni unuttuğum

Falan filan...

Sen rüyalarımsın

Sensiz uykularım olur haram...

Gecelerin ayazında

Hayalin ısıtır beni

Ateşimsin, güneşimsin

Mahkumum gözlerine

Özlediğim sevgilimsin...

Zehir karası gözlerinin

Zindanlarında

Zamansız esmesin

Ayrılıklara rüzgâr

Bende yeşerttiğin sevdanın

İlkbaharında...

Nedensiz sevdiğimsin

Aklında ayrılık mı var? ...

Ezberlediğim isminde titriyor  sesim

Paramparça gönlümde

Ve

Islanan gözlerimdesin

Süveyda...', 'Yayılmış İstanbul''dan  Büyük yalan Benim seni unuttuğum Falan filan... Sen rüyalarımsın Sensiz uykularım olur haram... Gecelerin ayazında Ha...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/suveyda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Samuel''e', 'samuel-e-meral-vurgun-inem5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'lieber Samy,

alle Nächte sind dunkel

schau dir den Mond an

er strahlt nicht so schön

in unsern Ländern

schau dir den dunklen Himmel an

sammle dir Sterne in deinem Herzen

träume dir den Himmel 

wie dein zu Hause

heute ist der achte März

mit feuchten Augen denk an deine Mutter

ihre Schönheit und ihre Wärme

träume von den Bergen deines Landes

schau dir den Mond an

und denk an

die Wärme der Herzen 

in deinem und meinem Land 

denk an deine erste Liebe

wie an das Wasser, die Erde 

unda das Feuer

die Wärme an ihrer Haut

das Lächeln deiner Schwester 

und die glänzende Farbe der Blumen

du bist in deinem Land

ich bin in meinem Land

alle Nächte sind dunkel

schau dir den Mond an

denk an den Tag

und die Wärme der Sonne...



sevgili Samy

bütün geceler karadır

baksana aya 

güzel parlamıyor ülkelerimizde

karanlık gökyüzüne bak

yıldız topla yüreğine

sılan gibi hayalle gökyüzünü

bu gün sekiz Mart

anneni düşün nemli gözlerle

güzelliğini, sıcaklığını

ülken dağlarını hayal et 

aya bak ve düşün

senin ülkende ve benim ülkemde

sıcaklığını yüreklerin

ilk aşkını düşün

su, ateş, toprak gibi

teninin sıcaklığını

gülüşlerini kızkardeşinin 

ışıldayan renklerini çiçeklerin

sen kendi yurdunda

ben kendi yurdumda

bütün geceler karadır

aya bak, gündüzü düşün

ve sıcaklığını güneşin...

Yazan ve çeviren

Meral Vurgun', 'lieber Samy, alle Nächte sind dunkel schau dir den Mond an er strahlt nicht so schön in unsern Ländern schau dir den dunklen Himmel an samml...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/samuel-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ben', 'sen-ben-asuman-durbin-5ix6z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Veda etmeden çekip giden 

Yaşanmışlıkları bir kalemde çizip atan

Baktığı güzellikleri göremeyen

Geçti o günler buraya kadardı 

Artık yoksun yüreğimde diyen

Yeni sevdalara 

Rüzgâr da yelken açmışçasına koşan 

Sen…….

Döner umuduyla

Günlerce yolunu bekleyen 

Yüreğimdeki sevgiyle yanıp tutuşan

El açıp tanrıya dönmen için yakaran 

Ben.

Acılar yüreğimi kor gibi yakıp kavurunca

Yangınlarda yıllar geçıp de gidince 

Çok geç olacak 

Dönmek istesen de geriye

Giremezsin, 

Sahip olamazsın kül olan yüreğime

Dokunduğunda savrulur uçar 

Geriye kalan sevda külleri

Yok, edemezsin yaşanmışlıklarda ki

 Yangınları……

Getiremezsin eski haline 

Kül olup dağılan kalbimi

Gene de derim ki 

Mutluluğu bulacaksan başka yüreklerde 

Huzura erebileceksen başka gülüşlerde

Sığınabileceksen başka bakışlara 

Rüzgârın ben olur 

Savururum Seni 

Esen yel misali

Yeter ki gittiğinde mutlu olacağını bileyim……...

 20\02\2005', 'Veda etmeden çekip giden  Yaşanmışlıkları bir kalemde çizip atan Baktığı güzellikleri göremeyen Geçti o günler buraya kadardı  Artık yoksun ...', ARRAY['Türk Edebiyatı','Şiir','Asuman Durbin']::text[], 8.5, '{"poet":"Asuman Durbin","poet_slug":"asuman-durbin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sen-ben-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben kadar Isimsiz Kalan Dizeler...', 'ben-kadar-isimsiz-kalan-dizeler-evina-berfin-q0e1r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canimm

icimdeyken ozlemim

yakinimdaki dokunmazligim 

icimin en duru rengi..

ne oldu bize...? 

ozledim....

ayri ruzgarlarmi aldi ucurtmalarimizi...

gokkusagina degmeden..

dileklerimize kimler dokundu..

gunisigi sana,

sen  gun isigina...

gozlerine sardim tum isiklarimi 

kardelenin mavi beyaz bedenine 

sana Berfin''i yolladim 

usulca...

kulaginda bir dag  ezgisi

ozgur mu ozgur 

yureginde gunisiginin Berfin''i..

ozledim...

dokun bana maviyle..

dokun yuregime 

en kuytusuna sessizce...

12/03/2005

1900 hrs', 'Canimm icimdeyken ozlemim yakinimdaki dokunmazligim  icimin en duru rengi.. ne oldu bize...?  ozledim.... ayri ruzgarlarmi aldi ucurtmalarim...', ARRAY['Türk Edebiyatı','Şiir','Evina Berfin']::text[], 8.5, '{"poet":"Evina Berfin","poet_slug":"evina-berfin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-kadar-isimsiz-kalan-dizeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ucu Yanık Mektubum**', 'ucu-yanik-mektubum-hulya-simsek-nhd2x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağır adımları hızlandı zamanın

....................................................

Dallanmış kollarımda konakla yaşam

Ve göçme bedenim soğuyunca

Uzak iklimlere…

Kahrolası bir tutku benimkisi

İlle göreceğim 

Baharın ilk ışıklarını

Bir serçe… 

gözlerimdeki

Küçük su birikintisinde

Yıkanmalı dilediğince…

Ölüm…

Ben seninle uyuyamam 

Aynı yastığa baş koyma benimle

       Kapı aralıklarından süzülüp

        Gülümseme ceset yüzünle…

Soyunduğum bir hatıradır

Ellerin dokunmuştu elime

Sağ elim o yüzden hep soğuktur

Sol elimi sevgilimin yüzüne

Sıcak bir dokunuş için bırak

Yaşam…

Kahrolası bir tutkum var sana

Ucu yanık  mektubumu

Sakla yastığının altında…', 'Ağır adımları hızlandı zamanın .................................................... Dallanmış kollarımda konakla yaşam Ve göçme bedenim soğu...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ucu-yanik-mektubum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O haller', 'o-haller-galip-kemali-gunay-7dfkm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceme girip 

Sarıpsarmaladığında

Çoşar yüreğim.

Kalmazsın sabaha,

Erir yüreğim.', 'Geceme girip  Sarıpsarmaladığında Çoşar yüreğim. Kalmazsın sabaha, Erir yüreğim....', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/o-haller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğime', 'sensizligime-birsen-ates-uyjut', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ruhum da hazan mevsimi

ayrılık rüzgarları yine 

poyrazdan esiyor

ağladım

çok ağladım

zannetme

sana ağladım

akan gözyaşlarım

sana değil

sensizliğime

yoruldum artık

biliyormusun 

gelmek çok zordu

sana geldim

sıcacık

yüreğimle

şimdi ruhum çırılçıplak

kalakaldım ortalarda

canım acıyor

buz gibi

kış ortasındayım,

üşüyorum

sensizim

gelsen de artık

i s t e m i y o r u m', 'ruhum da hazan mevsimi ayrılık rüzgarları yine  poyrazdan esiyor ağladım çok ağladım zannetme sana ağladım akan gözyaşlarım sana değil sensi...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sensizligime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-iki anayol vardır', 'a-iki-anayol-vardir-mikdat-bal-tlfm7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki anayol vardır!

İki anayol vardır biri eğri biri düz

Müminler düzü seçer yol  alır gece gündüz

Gündüzünde güneş var gecesinde ay-yıldız

Onları rehber alan ne sapıtır ne şaşar

Müminin yolu belli nur’a Allah’a koşar

Güneş Allah Kelamı, Ayla yıldız sünnetler

O yolda bulunanda sarihtir alametler

Gaye Allah rızası maksat değil cennetler

Allaha dayananlar öz benliğini aşar

Müminin yolu belli nur’a Allah’a koşar

Allah sevgisi ile sever sevdiklerini

Yine de Allah için yerer yerdiklerini

Kimseye ifşa etmez gizli verdiklerini

İslam’ı tebliğ eden önce nefsinde yaşar

Müminin yolu belli nur’a Allah’a koşar

Doğru yolda bulunmaz gam, kasavet ne keder

O yol nurlu bir yoldur çünkü Allah’a gider

O yolda bulunanlar rıza ile sabreder

Müminde tevazu var ne şımarır ne taşar

Müminin yolu belli nur’a Allah’a koşar

Mümin yalan konuşmaz onun her sözü haktır

Haya imandan gelir her zaman alnı aktır

Asla gevşeklik etmez hedefine müştaktır

Rıza-i Bari için artık yollara düşer

Müminin yolu belli nur’a Allah’a koşar

Mikdadi der arada durup adres soralım!

Eğri bir yolda isek gidişi durduralım

Bu gidiş Hakka gidiş doğru yoldan varalım

İnananlar  yolunu ibadetlerle döşer

Müminin yolu belli nur’a Allah’a koşar

Şair Mikdat Bal', 'İki anayol vardır! İki anayol vardır biri eğri biri düz Müminler düzü seçer yol  alır gece gündüz Gündüzünde güneş var gecesinde ay-yıldız O...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/iki-anayol-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küsüm benim', 'kusum-benim-galip-kemali-gunay-6lwdy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağdı yağacak gözle

Gölgeli dağlar gibi bakma bana.

Ne olur...

Yarım ağız olsun 

Gül.....

Yakma beni

Ne olur.', 'Yağdı yağacak gözle Gölgeli dağlar gibi bakma bana. Ne olur... Yarım ağız olsun  Gül..... Yakma beni Ne olur....', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kusum-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mİ''yi hiç Öpmedim ki.', 'mi-yi-hic-opmedim-ki-ali-osman-yilmaz-bhn5d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kara toprak,

Sana sarılayım,

Sarılayımda nasıl? 

Sen Mİ değilsin ki! 

Halbuki Mi bana,

Kendimi sana saklıyorum,

Demişti.

Şimdi Mİ senin koynunda,

Benim değil.

Ben Mİ nin,

Gül yanaklarından,

Kiraz dudaklarından,

Bir kez olsun,

Doyasıya öpmedim ki.

Toprak oldun ya,

Şimdi sen diye,

Kara toprağa,

Nasıl sarılayım? 

Kara toprak,

Sen gibi kokmuyor ki! 

Gül yanakları,

Kiraz dudakları,

Masmavi okyanus gibi,

Gözleri yok ki! 

Sen diye sarılayım,

Öpeyim.

Ben şimdi sen diye,

Hangi umuda sarılayım? 

Sen yoksun artık,

Ben en iyisi yine,

Bu gece ve her gece,

Sen diye,

Yalnızlığıma sarılarak,

Düş dünyama girip,

Sensizliğe, yada,

Hiçliğe sarılayım.', 'Kara toprak, Sana sarılayım, Sarılayımda nasıl?  Sen Mİ değilsin ki!  Halbuki Mi bana, Kendimi sana saklıyorum, Demişti. Şimdi Mİ senin koyn...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mi-yi-hic-opmedim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Şiirlerimde Ara', 'beni-siirlerimde-ara-huseyin-erdogan-t20e4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kalbimde 

bir heyecan başlar

şiirlerini 

her okuyuşumda

gönlümde 

bir de sızı var şu anda

zaten her şey şiir gibidir 

senin dünyanda

bir gün sen de

beni bulmak istersen

dizelerimde saklıyım ben

beni şiirlerimde ara

her sabah 

gönül bahçemde

bir gonca gül gibi 

açıversen

hasretinle 

dolan kalbimde

bir heyecan olup

atıversen

benim dünyama

mutluluklar saçıversen

ne olur sanki

o güzel yüreğine

beni alıversen

ben de seni

kollarımla sarıversem

                  16.03.2005', 'kalbimde  bir heyecan başlar şiirlerini  her okuyuşumda gönlümde  bir de sızı var şu anda zaten her şey şiir gibidir  senin dünyanda bir gün...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/beni-siirlerimde-ara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlana`dan', 'mevlana-dan-nizamettin-saltan-vrzb3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşka yaban olan eşhâs

Aşkı nefse eyliyor hâs

Aşkı Kâbe addetmeyen

Olur sâde bir boşboğaz

(1996)', 'Aşka yaban olan eşhâs Aşkı nefse eyliyor hâs Aşkı Kâbe addetmeyen Olur sâde bir boşboğaz (1996)...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mevlana-dan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-asli-yildiran-kn98z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '08.01.2004  sen giderken kopan yürek kıyameti sana bu şiiri armağan etti

Gitme, yıldızlar durmaz yerinde dökülür gözyüzünden

Bir yavru ceylan kalbi durur, bir güvercin kana bulanır

Sonra güneş doğmaz, geceler gündüz olmaz

Masalı yarım kalır sevdanın, gidersen yarın olmaz.

Gitme, ayrılık olmasın bu şiirin adı

Ağlamasın yüreğim, ağlatmasın ardından kimseleri, gitme!', '08.01.2004  sen giderken kopan yürek kıyameti sana bu şiiri armağan etti Gitme, yıldızlar durmaz yerinde dökülür gözyüzünden Bir yavru ceyla...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gitme-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükür', 'sukur-nizamettin-saltan-oyvd9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her tad için olsaydı ayrı bir dilim

Her bir dili taşır iken ne olurdu hâlim? 

