INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seven Benim', 'seven-benim-nizamettin-saltan-gzbum', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seven benim asıl seni

Sevdimse de bîgünahım

Ölür isem siteminle

Çıkacaktır bir gün âhım.

(1985)', 'Seven benim asıl seni Sevdimse de bîgünahım Ölür isem siteminle Çıkacaktır bir gün âhım. (1985)...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seven-benim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Ne Zaman', 'kiz-ne-zaman-nizamettin-saltan-7ss8e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni görüp ağlarken ben perişân perişân

Gözden katre değil, sel değil, deryâdır düşen

Eller düğün yaparken cıvıl cıvıl, şen,  şakrak

Kız ne zaman, kız ne zaman şu bizim nişan? 

 (1985)', 'Seni görüp ağlarken ben perişân perişân Gözden katre değil, sel değil, deryâdır düşen Eller düğün yaparken cıvıl cıvıl, şen,  şakrak Kız ne ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kiz-ne-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Düştü', 'ates-dustu-huseyin-sigirtmac-50jzl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ateş düştü yüreğime.

Dağ başında kar olayım.

Senin gibi bir zalime.

Çile çekip yar olayım.

Bir vefa görmedi sevgim.

Sarardı da soldu rengim.

Bozuldu artık ahengim.

Yana yana kor olayım.

Umutlarla hasret güzel.

Meşakatli yaşam rezil.

Dünyada almadım menzil.

Nerelerde kâr olayım.

Sığırtmaç yorgun boşuna.

Sevgisi bela başına.

O yarin beyaz döşüne.

Sarılarak sır olayım.

Bursa 16/03/2005', 'Ateş düştü yüreğime. Dağ başında kar olayım. Senin gibi bir zalime. Çile çekip yar olayım. Bir vefa görmedi sevgim. Sarardı da soldu rengim....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ates-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal perdesi', 'hayal-perdesi-nizamettin-saltan-vmgjp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayal perdesinde biri var yine

Efkar sahnesinde almış rolünü

Dalınca bir an güzelliğine

Üslendi gözleri can kontrolünü

(1984)', 'Hayal perdesinde biri var yine Efkar sahnesinde almış rolünü Dalınca bir an güzelliğine Üslendi gözleri can kontrolünü (1984)...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hayal-perdesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Niyaz', 'hep-niyaz-nizamettin-saltan-35v07', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Almış mızrap eline

Cümle âlem yek avâz

Vurur vahdet teline

Yaptıkları hep niyâz

(1984)', 'Almış mızrap eline Cümle âlem yek avâz Vurur vahdet teline Yaptıkları hep niyâz (1984)...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hep-niyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fahr-i İlim', 'fahr-i-i-lim-nizamettin-saltan-3zfq8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fahr-i ilim âlimlere âr iken

Yumruk olup dost başına inersin

İlim içre haddin bilme var iken

Tafra satıp böbürlenme, sen nesin? 

(1984)', 'Fahr-i ilim âlimlere âr iken Yumruk olup dost başına inersin İlim içre haddin bilme var iken Tafra satıp böbürlenme, sen nesin?  (1984)...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/fahr-i-ilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medeniyet Kur`an`dır', 'medeniyet-kur-an-dir-nizamettin-saltan-4bn0b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tek düstur, tek hakîkat kalmasın bir duymayan,

Medeniyet Kur`ân`dır, medenî, ona uyan! ...

(1984)', 'Tek düstur, tek hakîkat kalmasın bir duymayan, Medeniyet Kur`ân`dır, medenî, ona uyan! ... (1984)...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/medeniyet-kur-an-dir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi', 'simdi-nizamettin-saltan-ugrjc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gittin bu gönlüm bikarar şimdi

Yoksun ya, buralar bir mezar şimdi

Her zerrem sensizlik matemindeler

Bana da kaldı bak intizar şimdi

Şurada Mahmutcuk, şurada Bilal

Tütüyor burnumda balalar şimdi

Öteden gelmiyor Nur Filiz, Fatma

Hep mahzun Dayişman, kauflar şimdi

Caminin önünde çiçekler ölgün

Sizleri arıyor komşular şimdi

Bu Nidda harabe, bu Nidda tenha

Şen değil Mahmutsuz çocuklar şimdi

Önüme çıkıyor Almanı, Rusu

Kızları soruyor hep kızlar şimdi

Bir kuytu bu bahçe, bostanın viran

Sarmış her tarafı ayrıklar şimdi

Havalar gülmüyor, güller perişan

Dostluğa ağlıyor bulutlar şimdi

Yavrular şen olsun hep etrafında

İftarlık sofranda ne yemek var şimdi? 

Bilirim gitmiyor, düğümlenmişler

Hicranla taş olmuş lokmalar şimdi

Hasretin içime köz olup düşer

Kıskanır sevdamı kumrular şimdi

Gömülüp sükuta dalıp da gittim

Gözümde canlanır o anlar şimdi

Hoşça kal meleğim, üzülme sakın

Kendine iyi bak, dönmem pek yakın.

Selamette kalın, saadetle dolun

Hepiniz Allah''a emanet olun.

(Nidda-Ekim 2005/Ramazan)', 'Sen gittin bu gönlüm bikarar şimdi Yoksun ya, buralar bir mezar şimdi Her zerrem sensizlik matemindeler Bana da kaldı bak intizar şimdi Şura...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/simdi-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resmimin Arkasına', 'resmimin-arkasina-nizamettin-saltan-xu76p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gölgem size benden yakın

Cânım hocam hele bakın

Deli dolu, fakat uslu

Hem çelimli hem de süslü

Pek hırçındır, gözü pektir

Ve bir şaşkın kelebektir

Belli olmaz sağı solu

Saygınızla gönlü dolu

Yüksek tutar kadrinizi

Anar her ân isminizi

Şükrân ile muhabbetle

Size bağlı hep hürmetle

Çilelidir garip başı

Rûhu şair, çocuk yaşı

Hep kaygılı, hep mahzundur

Bahtı kara, kalbi hûndur

Günlerini güne ekler

Duâ bekler, himmet bekler

Karanlıkta çığlık atan

Talebeniz Nizam Saltan.

(Foça/1987)', 'Gölgem size benden yakın Cânım hocam hele bakın Deli dolu, fakat uslu Hem çelimli hem de süslü Pek hırçındır, gözü pektir Ve bir şaşkın kele...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/resmimin-arkasina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki', 'celiski-i-lknur-cekici-2h1o0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasıl sevgi bu

Bir gün duyguların en güzeli

Bir gün nefretin en derini

Bir gün güvenle bakan

Kalbimi yakan

Bir gün ateşe atan

Ruhumu karartan

Bu çelişkiler mi

Bizi bir arada tutan

                 (15.03.2005/GÖYNÜK)', 'Nasıl sevgi bu Bir gün duyguların en güzeli Bir gün nefretin en derini Bir gün güvenle bakan Kalbimi yakan Bir gün ateşe atan Ruhumu kararta...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/celiski-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Nesin?', 'sen-nesin-nizamettin-saltan-3pda5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çanta düşmez elinden sahib-i kalem misin? 

Vird-i zeban olmuşsun müfti-i alem misin? 

Kaptırdın kavuğunu şu laik tilkilere

Baş kabak geziyorsun İbrahim Edhem misin? 

Marifeti bilmişsin cübbende sakalında

Ye kürküm sofrasına dahil-i herdem misin? 

Müheykel ü müşekkel hal ve tavırların

Yakmada sineleri ibret-i alem misin? 

Girip çıktığın yerin olmadı nihayeti

Kuzum sen deliğe sefir-i mahrem misin? 

Rengin de renk değil pek bukelamundur tipin

Söyle kimin elinde ipin meçhul-i zalem misin? 

Nizam`ı pek şaşırttı acayip haletlerin

Deli mi, divane mi, hayta mı, sersem misin? 

(1992)', 'Çanta düşmez elinden sahib-i kalem misin?  Vird-i zeban olmuşsun müfti-i alem misin?  Kaptırdın kavuğunu şu laik tilkilere Baş kabak geziyor...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-nesin-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buldum Artık', 'buldum-artik-nizamettin-saltan-7n1oa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gah hoşlandım aşüfteli güzelden

Gönül verdim gah Ayşe`ye, Fatma`ya

Masum kıldı leş kokulu bir selden

Hamd ve şükür O Cenâb-ı Mevlâ`ya

Hep aradım sebil sebil yolları

Çok gözledim uzun saçlı kulları

Buldum artık beni saran kolları

Hamd ve şükür O Cenâb-ı Mevlâ`ya

Buldum artık bena imdâd edeni

Buldum artık ruhumu şâd edeni

Ve yorgun gönlümü âbad edeni

Hamd ve şükür O Cenâb-ı Mevlâ`ya

(5 EKİM 1985)', 'Gah hoşlandım aşüfteli güzelden Gönül verdim gah Ayşe`ye, Fatma`ya Masum kıldı leş kokulu bir selden Hamd ve şükür O Cenâb-ı Mevlâ`ya Hep ar...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/buldum-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zillet Rüzgarı', 'zillet-ruzgari-nizamettin-saltan-yy1so', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olmazsa sînede îmandan eser

Zilletin rüzgarı ne yandan eser? 

Küfrün karanlığı sızmış yüzüne

İçin dışın küf kokuyor serâser

Ettiğin yetişir bâtıl nâmına

Berbâd eder ecel, nefesin keser

Dünya zînetinin sahibi olan

Gâh Nemrut`tu gâh Kaarun`du gâh Kayser

Hepsi yere battı ne kaldı elde? 

Vur küfrünü, al eline bir mavzer.

(1983)', 'Olmazsa sînede îmandan eser Zilletin rüzgarı ne yandan eser?  Küfrün karanlığı sızmış yüzüne İçin dışın küf kokuyor serâser Ettiğin yetişir ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zillet-ruzgari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resmim Dostlara', 'resmim-dostlara-nizamettin-saltan-b7xv5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'RESMİM DOSTLARA

Gurbetin suyunu içmişim gayri

Eşime dostuma dönmem pek yakın

Olmazsa kavuşmak sılaya nasip

Ahbaplar şu buruk resmime bakın

Konan göçer belli, geçer mevsimler

Yermeyin adımı dostlarım sakın

Hâtıradır camekânda resimler

Resmimi, nihayet onu da yakın

Küle dönderin, ırmağa bırakın.

(1987)', 'RESMİM DOSTLARA Gurbetin suyunu içmişim gayri Eşime dostuma dönmem pek yakın Olmazsa kavuşmak sılaya nasip Ahbaplar şu buruk resmime bakın K...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/resmim-dostlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden Bilirdim', 'nereden-bilirdim-i-lknur-cekici-o0dkw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüzün mevsimiydi yaşanan

Bir şey vardı yarım kalan

Yorgun düşmüş yüreklerin

Sevgisiz bedenlerin

Gölgede kalmış rüyaların mevsimi

Hiç beklemiyordum ki ben seni

Nereden bilirdim

Bir gün geleceğini

Yaralarıma merhem olacağını

Kendini sevdirip

Kalbimi çalacağını

Nereden bilirdim

Yaşam verdiğin o günde

Maziye karışacağını

Başka hüzünlü baharların

Koynuna savuracağını

                            (15.03.2005/GÖYNÜK)', 'Hüzün mevsimiydi yaşanan Bir şey vardı yarım kalan Yorgun düşmüş yüreklerin Sevgisiz bedenlerin Gölgede kalmış rüyaların mevsimi Hiç beklemi...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nereden-bilirdim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuğun Cuması', 'cocugun-cumasi-nizamettin-saltan-l4hpi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün Cuma oluyor

İçim neş`e doluyor

Şu ân Eşref Saatı

Çekeriz salavatı

Saf saf olur müminler

Mimberde hutbe dinler

Meleklere karışır

Küsler bugün barışır

Cuma benim bayramım

Kıpır kıpır her yanım

Çocuğuz sürurluyuz

Tevhitle dopdoluyuz

Resul`e salavatlar

Sevabımızı katlar

Sevaptan siz de alın

Her daim hoşça kalın

Cumanız kutlu olsun

Kalbiniz nurla dolsun

Duamızı ederiz

Tekrar döner gideriz

Rahmân, Rahîm ey Rabbim! 

Senden ümit kesmedim

Kabul eyle duamı

Affet ana babamı

Ver bizlere, birlik ver

Ülkemize dirlik ver

Sevdir sevdiklerini

Yerdir yerdiklerini

Yalnız sana kul eyle

Cennetini yol eyle

Yuvamızı nur doldur

Bizi yolunda öldür.

(2001)', 'Bugün Cuma oluyor İçim neş`e doluyor Şu ân Eşref Saatı Çekeriz salavatı Saf saf olur müminler Mimberde hutbe dinler Meleklere karışır Küsler...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cocugun-cumasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zilletler Bitsin', 'zilletler-bitsin-nizamettin-saltan-q3fjp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gark olsun neslim izzetlere bari

Zilletler bitsin

Bitir bu hazin intizarları

Hasretler bitsin

Etme musallat bu iktidarları

Zulmetler bitsin

Ya göster ikbâlimi, ya mezarları

Bu dertler bitsin.

(1992)', 'Gark olsun neslim izzetlere bari Zilletler bitsin Bitir bu hazin intizarları Hasretler bitsin Etme musallat bu iktidarları Zulmetler bitsin ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zilletler-bitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün gece yar hanenizden', 'dun-gece-yar-hanenizden-hasim-koc-0vewc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gece yar hanenizden

Geçtim haneniz şenidi

Benim gönlüm hüzün dolu

Senin gönlün neşeliydi

Aman aman nazlım aman

Bizim dağlar ulu dağlar

Etekleri buzlar bağlar

Biz gurbeti mekan tuttuk

Sılada nazlı yar ağlar

Aman aman nazlım aman

Yazlar geçti güzler geçti

Verdiğimiz sözler hiçti

Benim gönlüm seni seçti

İnan bana nazlı yarim

Aman aman nazlım aman

saygi sevgi dostluk

hasimkoc', 'Dün gece yar hanenizden Geçtim haneniz şenidi Benim gönlüm hüzün dolu Senin gönlün neşeliydi Aman aman nazlım aman Bizim dağlar ulu dağlar E...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dun-gece-yar-hanenizden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birine', 'birine-nizamettin-saltan-sf7bx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Utanıyormuşsun Erzurum adına

Erzurum`lu adına

Utan utan

Demek baktın sen de

Bu âr- u hayânın tadına

Tiksiniyormuşsun

Doğu`nun kadınından, kızından

Belli oluyor kaleminden, yazından

Ürküyormuşsun

Palandökenin doruklarından

Yalımı alçak seni! 

Ürkek olma, erkek ol

Zirveleşen küfründen de kokunç değil

Ejder`in tepeleri

Büyülemiş besbelli

Zât-ı nâşerifini 

Bilmediğin Avrupa

TV kanalları gibi

İfadelerin serâpa

(1993)', 'Utanıyormuşsun Erzurum adına Erzurum`lu adına Utan utan Demek baktın sen de Bu âr- u hayânın tadına Tiksiniyormuşsun Doğu`nun kadınından, kı...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/birine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akif`in Ruhuna', 'akif-in-ruhuna-nizamettin-saltan-hjkzj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Îman seli elbet coşacaktır

Engelleri birgün aşacaktır

Hep nûr olan âlemlere dâim

Koştukça hep aşkla koşacaktır

Millet yeniden düşse de bîtâb

Göğsündeki îman taşacaktır

Bir kükreyen arslan gibi her ân

Devler ile gör savaşacaktır

Türk`ün bu terakkîsine düşman

Parmak ısırıp ta şaşacaktır

İnşâd ederken de şiirler

Rûhum eriyip kaynaşacaktır

Gel dinle şu ebyâtımı bir kez

Rûhunla senin koklaşacaktır

Ahdeylemişim himmetin ister

Şi`rinle Nizam da koşacaktır

(1983)', 'Îman seli elbet coşacaktır Engelleri birgün aşacaktır Hep nûr olan âlemlere dâim Koştukça hep aşkla koşacaktır Millet yeniden düşse de bîtâb...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/akif-in-ruhuna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıraktığın Kadar Düşünüyorum', 'biraktigin-kadar-dusunuyorum-halil-pazarli-asp0r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bıraktığın kadar düşünüyorum

derin bir öpücüğün çalındığı demleri

(sevişmelerimizi saymazsan eğer) 

ve gün doğarken canhıraş

geçmişe caydım

sensiz saydığım göynük öyküleri

Bıraktığın kadar düşünüyorum

ve acilen

müfredatla bacakların uzuyor geceye

seni hesaplıyorum

seni hesaplarken upuzun

hiç bir kadını sevmemişim

en telaşlı yordamla

güzel bir şiir diye

Bıraktığın kadar düşünüyorum

tenime saldığın tırnak izi

bir elmanın kıvrılan kesik kabuğudur

bıraktığın kadar düşünmek

zihnimde yüzen hayalin kuğusudur

ve hiç yoktan

.......... ferasete düşen 

.................... çırılçıplak bir sevda

aşkın camda biriken

.................... sonrada silinen buğusudur', 'Bıraktığın kadar düşünüyorum derin bir öpücüğün çalındığı demleri (sevişmelerimizi saymazsan eğer)  ve gün doğarken canhıraş geçmişe caydım ...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/biraktigin-kadar-dusunuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizgiler', 'cizgiler-nizamettin-saltan-e30jl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünyanın şaşaası yön vermiyor hayata

Bir bilsek gayemizi, kaybolmaz ki hiç rota

İlim tahsil edip de kendimizi tanısak

Reva mı ki insana hata içinde yata

Bir put var ki ortada baş eğmişiz kendine

Tekme atın kurtulun menfaat adlı puta

Kılavuz olmuş bize bu zamanda kargalar

Onun için düşeriz laşe ve kazurata

Kalmadı yuvamızda bir çizgi, bir insicam

Oğlan çapkın ve leylî, kızsa başka kucakta

Düşürdük nâmusları perde ve ekranlara

Bir güzele bin gözü çiviledik sokakta

Baloda doğum yapar, pilajda büyütürler

Edep kalkmış ortadan, ahlaksızlık revaçta

İndirdik sahnemize hep iğrenç perdeleri

Şimdi küfür oyunu en ilerde, ön safta

‘Ferdî hürriyet’ diye nikahsız gezmek niçin? 

Nâmus, iman, haysiyet... ne varsa hepsi rafta

Biz kestik sakalları, kadın da entariyi

Yepyeni bir ülke bak getirmişiz vücuta

Ne ararsın arkadaş topuğu kıllı atı? 

Göğsü kıllı adamlar binip gitti o ata

Ruh çirkef, iman büzük, soysuzlaşmış cemiyet

Kadın, erkek ve gençlik kanser olmuş, hep hasta

İçki içmek modada, iftihar vesielesi

Gören mubah diyecek bu iğrenç kabahata

Doktor devâ bulur da çoğu kez hastalara

Devâ yoktur kendine gösterdiği ilaçta

Günahlar da şayet sarhoş etse şarap gibi

Görürdün hocaları sallanırken mihrapta

Yıkık dökük bir ocak, alev almış bacamız

Kemikleri sızlayan ecdadımız hep yasta

Kimdir balık, kim yılan sular bulanmış sofu

İrşad et irfanınla inzivadan çıkıp ta! 

Bak, nihayet türedi sahtekâr müçtehitler

Uydurdular İslam`a nice nice safsata

Müslümanlık bir közdür müslümanın elinde

Ve çileli boynunda ‘yobaz’ yazılı yafta

‘Uyku hapı’ dediler yazık İslam nûruna

Bu hal ile muhaldir duruşumuz ayakta

Henüz gelmedi mi, yahu, uyanmanın zamanı? 

Anlarsınız gerçeği, uyanınca şafakta. 

(1986)', 'Dünyanın şaşaası yön vermiyor hayata Bir bilsek gayemizi, kaybolmaz ki hiç rota İlim tahsil edip de kendimizi tanısak Reva mı ki insana hata...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/cizgiler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua Edin', 'dua-edin-nizamettin-saltan-lx52n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İhtiyarlık başa belâ

Dua edin a dostlarım

Gel diyor şu musalla

Dua edin a dostlarım! 

Elime aldım kalemi

Öylece gezdim âlemi

Ardım sıra yermen e mi? 

Dua edin a dostlarım! 

Bu dünya fânidir fâni

Hani Sultan Süleymanı

Duyduğum gün o fermanı

Dua edin a dostlarım! 

Dert bitmiyor bu dünyada

Pek aldırdım bu bünyâda

Gelir isem birgün yâda

Dua edin a dostlarım! 

Topraktandır onun aslı

Gözü kara, gönlü paslı

Olur ise ocak yaslı

Dua edin a dostlarım! 

Düşünmedi kara kara

Şöyle geçip bir kenara

Geldiği gün ağzı yara

Dua edin a dostlarım! 

Aşık Nizamî`dir adım

Ah bir derviş olamadım

Arşa çıktıkta feryâdım

Dua edin a dostlarım! 

(1997)', 'İhtiyarlık başa belâ Dua edin a dostlarım Gel diyor şu musalla Dua edin a dostlarım!  Elime aldım kalemi Öylece gezdim âlemi Ardım sıra yerm...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dua-edin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuru Nergise', 'kuru-nergise-nizamettin-saltan-lwzk5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eziksin, büzüksün fakat câzipsin

Bir çiçeksin amma, kurusun Nergis! 

Pas tutmuş kalp içinde muzdaripsin

Kök salan sevginle durusun Nergis! 

Gül, gonca, papatya... çözdüm onları

Bilmecesin, sorusun Nergis! 

Didik didik ettim süzdüm onları

Dertli gönlümün sürurusun Nergis! 

Açmadan solmuşsun, kim bilir nasıl,

Benzim gibi sen de sarısın Nergis! 

Bır müzeyyen gülsün, çiçeksin asıl

İçimde bir senfoni, korosun Nergis! 

(1986)', 'Eziksin, büzüksün fakat câzipsin Bir çiçeksin amma, kurusun Nergis!  Pas tutmuş kalp içinde muzdaripsin Kök salan sevginle durusun Nergis!  ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kuru-nergise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trafik', 'trafik-i-lteris-bilge-kaan-br2n3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yeşil ışıklarda bekliyorum şimdi seni

sana giderken geçtiğim kırmızı ışıklar yerine...', 'yeşil ışıklarda bekliyorum şimdi seni sana giderken geçtiğim kırmızı ışıklar yerine......', ARRAY['Türk Edebiyatı','Şiir','İlteriş Bilge Kaan']::text[], 8.5, '{"poet":"İlteriş Bilge Kaan","poet_slug":"i-lteris-bilge-kaan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/trafik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okunmamış Mektup', 'okunmamis-mektup-ali-gencay-1jszq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Koltukların üzerine atılmış

Rengi solmuş patiska

En köhneye asılmış

Sırı dökülmüş ayna

Eşyalar kaçarcasına toplanmış 

Ağır esans kokuyor oda

Kulpundan kırık maşrapa

Küf düşmüş yarım bırakılmış şaraba

Gıcırtıyla açıldı kapı

Uçuştu masa üzerinden

Yıların şahidi kâğıtlar, sapsarı

Ayakucuma düştü biri

Uçmuş mürekkebi silik yazı

Okudum bir hazin aşkı

Sonuna yazılmış bir şiir

Silinmiş yok sevgilinin adı

Sevgilim …………

Bir gün elbet bende öleceğim

Beklide ölmeden burayı terk edeceğim

Beklide hiç doğmayacak güneşim

Sen okumadan silinecek mürekkebim

Senden bana kalan bir tutam perçem

Ölürsem onunla gömüleceğim', 'Koltukların üzerine atılmış Rengi solmuş patiska En köhneye asılmış Sırı dökülmüş ayna Eşyalar kaçarcasına toplanmış  Ağır esans kokuyor oda...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/okunmamis-mektup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Sevdiğine Dahil Olmakmış', 'ask-sevdigine-dahil-olmakmis-adnan-mehmet-tufekci-vze36', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir yıldız kaysa dileğim sen olursun,

Senden gayrı bir eksiğim yok ki yaşamda.

Ne zaman bir çift görsem gezerken kordonda,

İsyanım olur, yardan ayrı bir ben var sanırım o anda.

Ne zaman bir hayal kursam geleceğe dair,

Senden gayrı bir şey gelmez aklıma.

Beni çıkardım zamirlerden, oldum bize dahil,

Anladımdı ki aşk olmakmış sevdiğine dahil.', 'Ne zaman bir yıldız kaysa dileğim sen olursun, Senden gayrı bir eksiğim yok ki yaşamda. Ne zaman bir çift görsem gezerken kordonda, İsyanım ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Mehmet Tüfekci']::text[], 8.5, '{"poet":"Adnan Mehmet Tüfekci","poet_slug":"adnan-mehmet-tufekci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-sevdigine-dahil-olmakmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbrahim Koçaşlı Hocam`a /Tevhid İlahisi', 'i-brahim-kocasli-hocam-a-tevhid-i-lahisi-nizamettin-saltan-zc9tq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dairen aşk dergahı 

Lâilâhe illellâh

Bunda bulduk felahı

Lâilâhe illellâh

Nakşî`nin nefesi var

Kadirî`nin “hû” su var

Âşıkların nesi var

Lâilâhe illellâh

Bak hepimiz cûştayız

Cûş-u hem hurûştayız

Tevhîdde yarıştayız

Lâilâhe illellâh

Her sabah böyle olsun

Gönül îmanla dolsun

Tevhîd, ne güzel yolsun

Lâilâhe illellâh

Tevhîd, İslâm`ın adı

Adı dillerde kadı

Gel çıksın burda tadı

Lâilâhe illellâh

Tesbîh gönlün cilâsı

Onunla gider pası

Nûr-u İslâm kal`ası

Lâilâhe illellâh

Gönüller doluncusu

Seherlerin incisi

Zikirler birincisi

Lâilâhe illellâh

Lazımdır her bir kula

Gönlüne haşyet dola

Sâlik ol gel bu yola 

Lâilâhe illellâh

Sülûkün necâtındır

Dirimin, memâtındır

Ölmeden vefâtındır

Lâilâhe illellâh

Ben aşkın nâdânıyam

Cühelâ zîşânıyam

Ben tevhîd kurbanıyam

Lâilâhe illellâh

Nazar ber-kadem nedir

Bilmedim senelerdir

Daha neler nelerdir

Lâilâhe illellâh

Halk içinde Hakk`tayım

Hakk için halkadayım

Virdimiz olsun dâim

Lâilâhe illellâh

Mihmân edindin bizi

Aldık irfânı, feyzi

Lezîzlerin elezzi

Lâilâhe illellâh

Nizamuddin`dir adım

Âh, derviş olamadım

Yâdım, tadım ve andım

Lâilâhe illellâh

(1993)', 'Dairen aşk dergahı  Lâilâhe illellâh Bunda bulduk felahı Lâilâhe illellâh Nakşî`nin nefesi var Kadirî`nin “hû” su var Âşıkların nesi var Lâi...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/ibrahim-kocasli-hocam-a-tevhid-ilahisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Penceren', 'penceren-nizamettin-saltan-4huvz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Elif dedim be dedim

Kız ben sana ne dedim''

Kapatıver pencereni

Bakıp durma ona buna

Kız verem ettin sen beni

Getirip de hep oyuna

Kapamadan pencereni

Ceylan gözlüm gel yanıma

Seyretme giden geleni

Ateşler atma canıma

Hadi kapat pencereni

Hiç mi yoktur sende vefâ

Usandırdın yeter beni

Bitsin artık bunca cefâ

(1984)', '''Elif dedim be dedim Kız ben sana ne dedim'' Kapatıver pencereni Bakıp durma ona buna Kız verem ettin sen beni Getirip de hep oyuna Kapamadan...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Saltan']::text[], 8.5, '{"poet":"Nizamettin Saltan","poet_slug":"nizamettin-saltan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/penceren-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANİLER (61) ''Mudurnu''nun Evleri...''', 'mani-ler-61-mudurnu-nun-evleri-abdullah-atay-dp4u0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'mudurnu’nun evleri

tarihi birer müze

gelince görürsünüz

gerek yok fazla söze...

yavru ceylan avlanmaz

gönül yarsız eğlenmez

mudurnu’nun kızları

‘bindallı’sız evlenmez...

uslanmaz yaramaz gönlüm

yerinde duramaz gönlüm

nazlı yarin eller aldı

o sana yaramaz gönlüm...

fidan gibi boyu var

ne de güzel huyu var

benim güzel yarimin

meleklerden soyu var...

kar yağar ayaz olur

her taraf beyaz olur

geçme kapım önünden

eller görür söz olur..

yaylaya varılacak

bal kaymak karılacak

bal kaymak karılınca

nazlı yare verilecek...

kuzusun kaybedince

meler hep garip koyun

yar gurbete gidince

adımı garip koyun...

gurbet yolu sapadır

dağın ardı tepedir

söylediğim maniler

kulaklara küpedir...

bindallı: düğün ve kınalarda giyilen yöresel bayan giysisi...', 'mudurnu’nun evleri tarihi birer müze gelince görürsünüz gerek yok fazla söze... yavru ceylan avlanmaz gönül yarsız eğlenmez mudurnu’nun kızl...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/maniler-61-mudurnu-nun-evleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz seni seviyoruz Jale', 'biz-seni-seviyoruz-jale-hasim-koc-i7ipf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözümüz sende

Gönlümüz sende

Ekran var ara yerde

Ama

Olsun ne fark eder

Biz seni seviyoruz Jale

Duygularin samimi

Güzelligin hakiki

Herkes derki benimki

Paylaşmak zor olsada

Biz seni seviyoruz sevgili Jale

Saati gelir program başlar

Ekrana çevrilir bütün başlar

İşte o an mutluluk başlar

Biz senle mutluyuz sevgili Jale', 'Gözümüz sende Gönlümüz sende Ekran var ara yerde Ama Olsun ne fark eder Biz seni seviyoruz Jale Duygularin samimi Güzelligin hakiki Herkes d...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biz-seni-seviyoruz-jale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arta kalanlar', 'arta-kalanlar-zati-erbas-uaw6u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözlerini kapatmış 

bir 

evin 

önünden 

geçtim

karanlık yağıyor 

yağmur yerine

havada duman kokusu,

yüzümde 

yağmur 

anılar asılı 

yanmış ağaçların dallarında

savruldu küller 

denize doğru

geçmişim 

dalgalar 

özlem; 

ekmek kırıntıları serptiğim 

martı 

kanatları 

dilimin üstünde 

dondurma tadı 

kalmadı 

hayatın

sen gideli beri

yokluğuna alışmak 

çok zor

oradaysan 

bekle 

beni', 'gözlerini kapatmış  bir  evin  önünden  geçtim karanlık yağıyor  yağmur yerine havada duman kokusu, yüzümde  yağmur  anılar asılı  yanmış ağ...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/arta-kalanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-senol-ozuturk-g5nvv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurşun yarası değil bu 

Ayrılık acısı 

Hani gözlerime bakmadan gittiğin 

Vedanın sancısı

Arkada bıraktığım anılar

sana değil aşık olmaya 

Çok meraklılar için

Yazmaktan bıkmadığım şiirler 

Sana değil yanmaya 

Çok meraklılar için

Ankara 10.03.2005', 'Kurşun yarası değil bu  Ayrılık acısı  Hani gözlerime bakmadan gittiğin  Vedanın sancısı Arkada bıraktığım anılar sana değil aşık olmaya  Ço...', ARRAY['Türk Edebiyatı','Şiir','Şenol Özütürk']::text[], 8.5, '{"poet":"Şenol Özütürk","poet_slug":"senol-ozuturk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensizlik-166-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-zati-erbas-f0jmo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buluttan sıyrılabilseydi yüreğim 

aynanın ardındaki seni ısıtmazdı; 

yüzün ne kadar yakınmış yüzüme.

ateş böcekleri gibi uçuşurken geçmiş zamanların

gidişleri

kendimi geceye mahkum buluyorum.

Beni bu geceye mahkum eden

Sendin; 

unuttun mu.', 'Buluttan sıyrılabilseydi yüreğim  aynanın ardındaki seni ısıtmazdı;  yüzün ne kadar yakınmış yüzüme. ateş böcekleri gibi uçuşurken geçmiş za...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayna-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşte Uyumak', 'ateste-uyumak-zati-erbas-qzuhw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kalbi kırılınca 

insan ölmeli, 

binlerce neden var demek 

gitmek için

hangi şehirdesin 

hangi gizli koyda 

hangi yalnızlıkta 

............................bilmiyorum

yıldızların altında yumuyorum gözlerimi 

yangın yerlerinde 

.............................uyanıyorum

ateşte uyumakmış kader

yangınlardan 

arta 

........kalan 

..................gibiyim.', 'kalbi kırılınca  insan ölmeli,  binlerce neden var demek  gitmek için hangi şehirdesin  hangi gizli koyda  hangi yalnızlıkta  .................', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ateste-uyumak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklima o an Jale gelir', 'aklima-o-an-jale-gelir-hasim-koc-gb31o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Açık bir televizyon gördümmü

Aklıma o an Jale gelir

Hayalimden güzel bir yüz geçtimi

Aklıma o an Jale gelir

Işıl ışıl güzel gözü

Çok güzeldir eli yüzü

Sevgi sunan tatlı dili duydummu

Aklıma o an Jale gelir

Bir selvi sanirsın boyu

Övülmeğe değer huyu

Haşim derki ömrüm boyu

Aklıma her an Jale gelir

22-08 2001 çarşamba', 'Açık bir televizyon gördümmü Aklıma o an Jale gelir Hayalimden güzel bir yüz geçtimi Aklıma o an Jale gelir Işıl ışıl güzel gözü Çok güzeldi...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aklima-o-an-jale-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Tango', 'bitmeyen-tango-bekir-gedikoglu-17fvg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimin içinde dans edip duruyorsun

Gözlerin gözlerimde bu piste uyuyorsun

Benimle vals edipte nereye gidiyorsun? 

Bana açıkça söyle sen bana çok vurgunsun

Her derdine çareyim gözbebeğim olursun

Başkasına bakamam göz önümde durursun

Sen benim gözlerimde bitmeyen bir tangosun

Bana açıkça söyle sen bana çok vurgunsun

Her çizgin gözlerimde beni unutur musun? 

Can suyum ellerinde beni kurutur musun? 

İkimizde aynı dert beni anlıyor musun? 

Bana açıkça söyle sen bana çok vurgunsun

Ankara 15.03.2005

Bekir Gedikoğlu', 'Gözlerimin içinde dans edip duruyorsun Gözlerin gözlerimde bu piste uyuyorsun Benimle vals edipte nereye gidiyorsun?  Bana açıkça söyle sen ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bitmeyen-tango-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güler Işık', 'guler-isik-hasim-koc-0o80p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elin güzel yüzün güzel

Dobra sözün huyun güzel

Türkülerin cana değer

Biz seni anlıyoruz

Üzülme sen Güler Işık

Mazin temiz günün temiz

Dünü günü yok hep severiz

Sevgiyle türkülerini dinleriz

Biz seni anlıyoruz

Üzülme sen Güler Işık

Şımarık hoppa değilsin

Eski değil hep yenisin

Türkücülerin gülüsün

Biz seni anlıyoruz

Üzülme sen Güler Işık', 'Elin güzel yüzün güzel Dobra sözün huyun güzel Türkülerin cana değer Biz seni anlıyoruz Üzülme sen Güler Işık Mazin temiz günün temiz Dünü g...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/guler-isik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Gülü', 'guz-gulu-taha-karakoc-sp250', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevsimlerden hazan

Hasret ve hüzün mevsimi

Yüreğimin mevsimiydi hazan

Seni sonbaharda aradım

Baharımda bulacaktım

Gelmeyen baharımda

Bir mezar kazdırmıştım sevdama

Yüreğimdeki seni gömecektim

Baharımda yaşatacaktım

Baharım hiç gelmiyecekmiydi

Seni hazan mevsiminde

Avuçlarımda büyütecektim

Göz yaşımla sulayacaktım

Sevgimle besleyip 

Adına güz gülü diyecektim', 'Mevsimlerden hazan Hasret ve hüzün mevsimi Yüreğimin mevsimiydi hazan Seni sonbaharda aradım Baharımda bulacaktım Gelmeyen baharımda Bir mez...', ARRAY['Türk Edebiyatı','Şiir','Taha Karakoç']::text[], 8.5, '{"poet":"Taha Karakoç","poet_slug":"taha-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/guz-gulu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyoruz Gülben', 'seni-seviyoruz-gulben-hasim-koc-9i3v6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözümüz sende

Gönlümüz sende

Ekran var ara yerde

Ama

Olsun ne fark eder

Biz seni seviyoruz Gülben

Duyguların samimi

kaşın gözün hakiki

Her kes der benimki

Paylaşmak zor olsada

Biz seni seviyoruz Gülben

Saati gelir program başlar

Ekrana çevrilir bütün başlar

Gülbende çok güzel gözler kaşlar

Allah vergisi özelsin

Sen herkesten güzelsin

Biz seni çok seviyoruz  Gülben', 'Gözümüz sende Gönlümüz sende Ekran var ara yerde Ama Olsun ne fark eder Biz seni seviyoruz Gülben Duyguların samimi kaşın gözün hakiki Her k...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-seviyoruz-gulben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostmu Kaldı', 'dostmu-kaldi-taha-karakoc-78z00', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dostmu kaldı kaldı bana

Bir ben birde uzaktan izlediğim

Yaklaşmaya bile korktuğum

Kara toprağım

Kim kaldı bana

Yaralı bir kalp

Buruk bir kalem

Küskün karam sayıfalar

Başka ne kaldı bana', 'Dostmu kaldı kaldı bana Bir ben birde uzaktan izlediğim Yaklaşmaya bile korktuğum Kara toprağım Kim kaldı bana Yaralı bir kalp Buruk bir kal...', ARRAY['Türk Edebiyatı','Şiir','Taha Karakoç']::text[], 8.5, '{"poet":"Taha Karakoç","poet_slug":"taha-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dostmu-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardiyan', 'gardiyan-kamil-boyraz-x8xk4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözümden gönlüne köprü kuruldu

Kalbim sana görür görmez vuruldu

Sevda dedikleri demek''ki bumuyudu

Bir sevdaya mahkumum be gardiyan

Onu tanımazken yaşamamışım

Aldığım nefesten zevk almamışım

Şu kalbimi boş yere taşımışım.

Bir sevda mahkumuyum be gardiyan

Seviyorsun diye idam verseler

Dünyanın dibine beni gömseler

Bedenimi ateşlere verseler

Bir sevda mahkumuyum be gardiyan', 'Gözümden gönlüne köprü kuruldu Kalbim sana görür görmez vuruldu Sevda dedikleri demek''ki bumuyudu Bir sevdaya mahkumum be gardiyan Onu tanım...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gardiyan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut Yüreğimin Bir Köşesinden', 'tut-yuregimin-bir-kosesinden-emine-deniz-fkcu0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ucundan tut yaşanmamış aşklarımın 

Hadi

Tut yüreğimin bir köşesinden...

Oyuncak sevdaların peşinden koştuğuma gülmeden 

Bilmeden

Kimi ne kadar aldım,nereye kadar

Masumdum sevgili

Tek suçum 

Aramaktı yüreği kocaman sevgiliyi

Kimsesiz düşlerin peşinde 

Anlatılan masallar kadar masumdu günahlarım

Ve ahlarım...

Kendime sarılışlarım var saklı gecelerimin  her köşesinde

‘’Saklanmış sevişmeler

Yasaklanmış ‘’

Hadi sevgili

İnandır beni aşka

Aşkla

İhtiyacım var

dokunuşlarına

Kekik koksun baharda  tenim yeniden

Bir kadın deli dolu,bir kadın asi 

Kendi küllerinden aşklar doğuran

____________Dokun ki sevgili

çıksın içimden...', 'Ucundan tut yaşanmamış aşklarımın  Hadi Tut yüreğimin bir köşesinden... Oyuncak sevdaların peşinden koştuğuma gülmeden  Bilmeden Kimi ne kad...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tut-yuregimin-bir-kosesinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çünkü.... Evet Çünkü', 'cunku-evet-cunku-sibel-oner-r673p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çünkü...............Evet Çünkü	

	

Beni ben olarak sevseydin	

Ben,ben olurdum				

Beni aldatıp terketmeseydin				

Ben senin olurdum				

Korkak keçi gibi kaçmasaydın				

Şimdi yanında olurdum				

Sonu gelmez bir boşluk yaratmasaydın				

Sonsuza o boşluğu doldururdum				

Eyy Allah''ın adi kulu				

Şerefsiz,nankör,yalancı				

Bu gidişle sen beni hakedemezsin				

Benim bir gururum var sahiplenmeliyim				

Güçlüydüm seni tanımasaydım				

Coşku doluydum seni görmeseydim				

İradeleydim seni sevmeseydim				

Ama dizginleri yinede bırakmamalıyım				

Hiç mani olmaz senin gibi hainler				

Üzmez kıramaz,hergeleler...				

Canımı yakamaz bu evrendeki insanlar				

Evet.............				

Ben yaşıyorum,çünkü çok güçlüyüm				

Ben ayaktayım,hala yaşıyorum				

Ben çalışıyorum,çünkü mecburum				

Ben rahatım,çünkü mutluyum				

				

				Sibel ÖNER', 'Çünkü...............Evet Çünkü	 	 Beni ben olarak sevseydin	 Ben,ben olurdum				 Beni aldatıp terketmeseydin				 Ben senin olurdum				 Korka...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cunku-evet-cunku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Şiir', 'yeni-siir-banu-aka-3gfr8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eski aşklar 

Eski şiirler gibi 

Yazılıp biten

Saklarsan anısı kalan 

Saklamazsan hatırlanmayan

Belki saklamıştım eski şiirlerimi

Bu zamana kadar

Belki saklamıştım

Beni sana hazırlayan

Anılarımı

Yenisi sen ol şiirlerimin 

Senin gülüşün

Dokunsun gülüşüme

Al yüreğimdeki  senin olsun.

Sen benim

Son şiirim ol.', 'Eski aşklar  Eski şiirler gibi  Yazılıp biten Saklarsan anısı kalan  Saklamazsan hatırlanmayan Belki saklamıştım eski şiirlerimi Bu zamana k...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeni-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Hayaller', 'bos-hayaller-sibel-oner-ur8v3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BOŞ HAYALLER				

					

Öyle bir şey olmalı ki; görünmeden yaşamalıyım

Güçlü kuvvetli olmalıyım ejderhalar gibi		

Bilmeliyim herkesin benim için düşündüklerini		

Ama onlar bilmesin benim varlığımı			

Onları adım adım takip edip				

Hayallerini bir anda gerçekleştirmeli			

Kavuşturmalı onu canından çok sevdiğine		

Oluvermeli hayatı toz pembe			

Bu mutluluğunu önce sevinmeli sonrada		

İçine sarmalı bir merak				

Neydim.ne haldeyim,ne oldun,ne buldum		

İşte artık şansım gülüyor diye sevinmeli		

Hak etmeyenlerin bu mutluluk tablosunu kırmalıyım	

Acımasız duygularında aynı karşılığı vermeliyim		

Cezalandırmalıyım falakaya yatan çocuk gibi		

Boynunu büküp''KADERİMMİŞ''desin			

Nerden kimden geldiğini anlayamasın		

Boşuna ne oldum delisi olmasın			

Bugün kadar yarını da düşünsün			

Bilsin ki; kendinden başka canlılar var			

Adımını hep hesaplı atsın				

Kendini olduğu kadar çevresini de zararı olmasın	

Zindan etmesin garibanların hayatını			

Hor görmesin ufacık bir mutluluğu onlara		

Versinler bir gram bile olsa bir huzur.mutluluk					

					

					

				Sibel ÖNER', 'BOŞ HAYALLER				 					 Öyle bir şey olmalı ki; görünmeden yaşamalıyım Güçlü kuvvetli olmalıyım ejderhalar gibi		 Bilmeliyim herkesin benim i...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bos-hayaller-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Renk', 'bir-renk-taha-karakoc-t3hbc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karlı dağlarımıza çiçeklermi açtı

Senden çalımştım

Kır çiçeklerinin taze kokularını

Baharımızda kışı yaşıyorduk bazen

Bazende kışlarımızda baharı yaşıyorduk

Sevgimiz 

Bir kurşun yarasıydı bağrımızda

Güneş doğmasada gündüzleri yaşıyorduk

Bazen gündüzlerimiz 

Gecelerden beterdi

Bazen kargaların sesi bize ilhamdı

Bazen en güzel melodi

Karmsarlığın sözcüsüydü

En dramatik şarkılara

Kahkaha ile gülerdik

Şimdi

En neşeli şarkıya bile

İçli bir hıçkırık tuturduk

Biz ne anladık şarkıdan

Nedenilir bilmem ama

En güzel sözcükleri senden çalıyorum

Bütün renkleri düşünürdük

Fakat şimdi

Bir renk vardı

Aklımdan çıkmayan bir renk

Siyhmıydı yeşilmiydi blmiyorum ama

Düşlerimizi kaplamıştı', 'Karlı dağlarımıza çiçeklermi açtı Senden çalımştım Kır çiçeklerinin taze kokularını Baharımızda kışı yaşıyorduk bazen Bazende kışlarımızda b...', ARRAY['Türk Edebiyatı','Şiir','Taha Karakoç']::text[], 8.5, '{"poet":"Taha Karakoç","poet_slug":"taha-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-renk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok güzelsin çok özelsin Esra', 'cok-guzelsin-cok-ozelsin-esra-hasim-koc-hfwmi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sırma gibi siyah saçlar

Boncuk boncuk kara gözler

Yalansızdır bütün sözler

Çok özelsin sen esra

Çok güzelsin sen esra

Allahın nuru var yüzünde

Her derde çare var doğru sözünde

Riyaya yer yok senin özünde

Çok özelsin sen esra

Çok güzelsin sen esra

İzlemekten alırım haz

O anlar hem bahar hem yaz

Bazan duygulanir çalarım saz

Şaire ozana ilhamsın sen

Melek olursun dünyaya bir daha gelsen', 'Sırma gibi siyah saçlar Boncuk boncuk kara gözler Yalansızdır bütün sözler Çok özelsin sen esra Çok güzelsin sen esra Allahın nuru var yüzün...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cok-guzelsin-cok-ozelsin-esra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-banu-aka-hh81i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzüme çevirdiğinde 

Çocuk gözlerini

İçimden 

Sevi geçer 

Beraber güldüğümüzde

Her hangi bir şeye

İçimden 

Sevinç  geçer

Yanıma oturduğunda

Ürkekliğinle

Aklımdan

Düşler geçer.

Düşümü seviye

Sevimi 

Sevince çeviren 

Hoş geldin.

Sakın gitme.', 'Yüzüme çevirdiğinde  Çocuk gözlerini İçimden  Sevi geçer  Beraber güldüğümüzde Her hangi bir şeye İçimden  Sevinç  geçer Yanıma oturduğunda ...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dus-111-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keten göynek alalı', 'keten-goynek-alali-hasim-koc-ddtjd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Keten göynek alalı

Sevdiğim malatyalı

Yediğim içtiğim zehir

Sevdan gönle dolalı

Oy oy oy oy  güzelim

Gel kernekte gezelim

Yazı boşa geçirdik

Güze dügün edelim

Al duvağın beyaz tülü

Gülcanım Malatya gülü

Ela gözü ince beli

Deli etti inan beni

Oy oy oy oy güzelim

Gel kernekte gezelim

Yazı boşa geçirdik

Güze dügün edelim', 'Keten göynek alalı Sevdiğim malatyalı Yediğim içtiğim zehir Sevdan gönle dolalı Oy oy oy oy  güzelim Gel kernekte gezelim Yazı boşa geçirdik...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/keten-goynek-alali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Ne?', 'sana-ne-sahin-erturk-3sq23', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En nihayet alıştım

Takmıyorum sözlere

Deniz gözlüm yüzünden

Bakmıyorum gözlere

Şiirkolik olmuşsam

Ona şiir yazmışsam

Başka isim bilmezsem

Ona,buna sana ne? 

Sembol olmuş bir isim

Var mı diye sorsana? 

Bir hayale aşıksam

Ona,buna sana ne? 

On yıldır ağlıyorsam

Bir hayal bekliyorsam

Bir hayal seviyorsam

Ona,buna sana ne? 

(16.03.2005-Yeni)', 'En nihayet alıştım Takmıyorum sözlere Deniz gözlüm yüzünden Bakmıyorum gözlere Şiirkolik olmuşsam Ona şiir yazmışsam Başka isim bilmezsem On...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sana-ne-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyüş', 'yuruyus-banu-aka-494pb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aynı yağmurun altında

Islandığımız o gece 

Öğrendim

Gözlerim kapalı da olsa 

Sen yanımdayken 

Düşmeden 

Yürüyebileceğimi.', 'Aynı yağmurun altında Islandığımız o gece  Öğrendim Gözlerim kapalı da olsa  Sen yanımdayken  Düşmeden  Yürüyebileceğimi....', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yuruyus-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Who Am I? (Kîme Ez?)', 'who-am-i-k-me-ez-cigerxw-n-17pew', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Who am I you ask? 

The Kurd of Kurdistan I am 

In the face of enemy 

Fire and dynamite 

When furious 

Like a volcano 

I shake the mountains 

The sparks of my fury 

Are death to the foe. 

Who am I? ! 

I am in the east 

With forts and castles 

Towns and hamlets 

Rocks and boulders 

I saved the Middle East 

From invading Turks 

And the crusaders. 

Who am I? ! 

Ask the Near East 

Ask the Middle East 

Villages and towns 

Plains and deserts 

They were once all mine 

When by war and knowledge 

I defeated rivals 

To become crowned 

Over an empire 

That reached India. 

Who am I? ! 

I am the proud Kurd 

Of a noble race 

The enemy’s enemy 

To the peaceful friend 

Like my mighty ancestors 

I want to be free 

Not forever oppressed 

By this enemy 

Who won’t leave in peace. 

Who am I? ! 

I want to liberate 

My parks and meadows 

From the tyrants 

From the corrupt Shah 

The Turkish juntas 

So I may live free 

In my own homeland 

Like other nations 

So I can rebuild 

And contribute 

To the good of mankind. 

Who am I? ! 

The one who defeated 

Richard the Lion Heart 

My own blood I shed 

To defend these lands 

A thorn I once was 

In the enemy'' side 

In my shadow lived 

Turk and Persian 

Many a king held 

The halter of my horse 

Yes I am the warrior 

I am Saladin 

The King of Egypt, 

Syria and Palestine. 

Who am I? ! 

I am Ardasher 

I am Noshi Rawan 

In the ancient days 

Rivals feared my kings 

Regretted their wrath. 

I knew no fright 

With adventure in love 

From India to Greece 

They paid me tribute. 

Who am I? ! 

The Kurd of Kurdistan I am 

Now poor and oppressed 

My castles and forts 

Remain demolished 

My name and my fame 

Swindled by assailants 

Who set germs to my body 

To paralyse my being 

And make my nation 

Nameless with no friend. 

Who am I? ! 

The unyielding Kurd 

Who despite it all 

Still formidable 

To his enemies. 

The smell of dynamite 

Is again in my nose 

The desire to erupt 

Is lively in my heart 

I am the fighting valiant 

In my majestic mountains 

Not for the love of death 

But to live free 

In my Kurdistan 

The land of the Medes 

My proud ancestors. 

Who am I? ! 

I am the descendant 

Of Blacksmith Kawa 

Who slayed Dahak 

The notorious tyrant 

To break off chains 

From Kurdish shoulders 

And save many heads 

From his death list 

With his death ended 

The long vicious reign 

And Newroz was born 

To mark a new day 

Replacing darkness 

By the bright sun 

Offered by Ahirman 

God of wisdom and light 

Who defeats Ormazd 

The cruel evil god 

As revealed long ago 

By Zoroastra. 

Who am I? ! 

The maker of Newroz 

Seeking my destiny 

To rule my own land 

Enjoy my orchards 

Relish the sacred wines 

Of my own vineyards 

I shall pursue knowledge 

To again break the chains 

So I can breath 

The wind of liberty 

Who am I? ! 

Khaldaw and Mitan 

Nayri and Sobar 

The son of Lo Lo 

Kardokh and Kodi 

I belong to the Medes 

Hori and Gudi 

Kurmanj and the Gosh 

Kelhor, Lor and Gor. 

Despite oppression 

And the division 

I am on my land 

Kurdish to remain. 

Who am I? 

The son of the Lor 

Kurmanj and Kelhor 

Who lost crown and reign 

When in the name of religion 

They were once betrayed 

To became powerless 

Rosaries in hands 

Duped by the rulers 

Deprived of their wealth 

Fighting each other 

Divided and torn 

In the oppressed land 

My wretched Kurdistan. 

Who am I? 

The child of a nation 

Awaken from deep sleep 

To march once again 

As a proud lion 

To let the world know 

My struggle will go on 

In the path to freedom. 

I shall learn from great men 

of every era 

I shall make a vow 

To my ancestors 

Salar and Sherko 

As well as Daysam 

That this will of mine 

will remain alive. 

Let everyone know 

I announce with no fear 

Liberty is my goal 

I shall never give up. 

Who am I? 

I desire peace 

Not to shed blood 

But I have enemies 

Who deny my rights 

I stretch my hands 

They betray and lie. 

My friendship I offer 

To all the nations 

Death to oppressors 

Long live Kurdistan. 

Who am I? 

A poem by the Kurdish poet Cigerxwîn (1903 - 1984)  

Translated and adapted into English by Shahîn Bekir Sorekli', 'Who am I you ask?  The Kurd of Kurdistan I am  In the face of enemy  Fire and dynamite  When furious  Like a volcano  I shake the mountains ...', ARRAY['Türk Edebiyatı','Şiir','Cigerxwîn']::text[], 8.5, '{"poet":"Cigerxwîn","poet_slug":"cigerxw-n","theme":"Türk Şiiri","is_hero":false,"total_lines":195,"source_url":"https://www.antoloji.com/who-am-i-kime-ez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle...Gel...Dinse...', 'dinle-gel-dinse-bekir-mutlu-gokcesu-djbd7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sessiz ve derin

Şakır ve şavkırlar

Kayar yol boyu

İpini koparmış

Düşe yazar ışıklar...

Sırılsıklam

Kayar diz boyu hasrete

Yalpalar izleri

Duramaz yerinde

Yana yazar yıldızlar...

İmgelerin selinde duygu salım

Dinle sesini yüreğimin yağmura 

Dinle...gel...dinse...

İnsin bulutlarından ruhum

Ersin mevsime...

Yıldız toplayayım gözlerinden

Söyleyeyim yağmura dinsin

Geldinse...', 'Sessiz ve derin Şakır ve şavkırlar Kayar yol boyu İpini koparmış Düşe yazar ışıklar... Sırılsıklam Kayar diz boyu hasrete Yalpalar izleri Du...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dinle-gel-dinse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnatçı', 'i-natci-aysun-erat-tz61s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnin oradan, hey! 

Dağ benim.

Yorgunum.

Bir solukluk yaslanacağım.

Dağın kuvvetini çalıp,

Devam edeceğim.

Yolum uzun, upuzun…

Sevdanın peşinden

Koştum durdum yıllarca,

Ben kovaladıkça…

O kaçıyor, soluksuz.

Ama inatsa,

İnat işte.

İmkanı yok, bırakmam peşini.

Bir yakalarsam….

Gör bak nasıl değiştireceğim,

Sevdanın kaderini…

03/2005', 'İnin oradan, hey!  Dağ benim. Yorgunum. Bir solukluk yaslanacağım. Dağın kuvvetini çalıp, Devam edeceğim. Yolum uzun, upuzun… Sevdanın peşin...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/inatci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Gibi', 'cocuk-gibi-sitki-gokmen-jei1n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocuk olmak istiyorum,

Ağlamak çocuklar gibi.

Neden o zaman ağlamadım sanki? 

Kanarcasına.

Şimdi büyükler ağlamaz diyorlar.

Ağlayamıyorum,

Doyarcasına.

(ANKARA 1987-16 MART 2005)', 'Çocuk olmak istiyorum, Ağlamak çocuklar gibi. Neden o zaman ağlamadım sanki?  Kanarcasına. Şimdi büyükler ağlamaz diyorlar. Ağlayamıyorum, D...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cocuk-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesur ve Korkak', 'cesur-ve-korkak-zafer-yazici-fj8jw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdaya karşı adı konmamış yazılar var! 

içinde aşka dair tek bir kelime bile olmayan..

Kimdir bu bilinç içinde yalnızlık ve gaflete düşen? 

Kimdir, benim gibi, yalnız başına aşık olacak kadar, hayalperest? 

kimdir, bulduğu anda aşka sarılabilecek kadar cesur olan? 

en önemlisi kaybetmeyi göze alamayacak kadar korkak?', 'Sevdaya karşı adı konmamış yazılar var!  içinde aşka dair tek bir kelime bile olmayan.. Kimdir bu bilinç içinde yalnızlık ve gaflete düşen? ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cesur-ve-korkak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senide', 'senide-sibel-oner-phguj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'S e n i d e

Hep böyle gururla gezerim sanma	

				

Seninde boynunu bükenler olur.					

Her zaman ağlatıp gezerim sanma					

Zulmüne karşılık verenler olur.					

					

O taştan kalbin dağılır gider					

Vefasız gözlerin birgün birini sever					

Ne gururun kalır,ne zulmün yeter					

Görürsün senide yakanlar olur.					

					

Bakma ben sevgine çok kıymet verdim.					

Ağlattın kahrettin yinede sevdim					

Kendini bulunmaz ilah zannettin					

Senide boynu bükük bırakanlar olur.					

					Sibel ÖNER', 'S e n i d e Hep böyle gururla gezerim sanma	 				 Seninde boynunu bükenler olur.					 Her zaman ağlatıp gezerim sanma					 Zulmüne karşılık ...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/senide-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski', 'eski-sibel-oner-sgijk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eski

12 mevsimlik ayrılıktan sonra					

Seni anlatmak geldi içimden					

Aldı kalemim					

Yazdı seni birer birer					

Şimdi çok uzaklardadır o					

Mutludur artık dedim					

Gözlerinin rengini hatırlamıyorum					

Simanı unuttum anımsamıyorum					

Gözlerinin içi gülüyordu hep					

Benimle var olurken					

En sinirli anında bile tebessüm ettiriyordum ya					

Hala sinirlenince tebessüm edebiliyormusun					

aşkımız vardı dillerde dolaşan					

Şimdede konuşulan bir aşkın varmı? 					

Her yerde sen ve ben					

Benin yerimde kim... Var					

Mevsimler bir bir geçse bile					

Elimde bir resim					

Resimde de sen					

					

					

			Sibel ÖNER', 'Eski 12 mevsimlik ayrılıktan sonra					 Seni anlatmak geldi içimden					 Aldı kalemim					 Yazdı seni birer birer					 Şimdi çok uzaklardadı...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eski-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-sitki-gokmen-dhenc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel diyorsun bana,

Günlerin karanlığını yararak gel.

Karanlık günler geride kalsın.

Hep el ele mutlu günler bize kalsın.

(ANKARA 1986-16 MART 2005)', 'Gel diyorsun bana, Günlerin karanlığını yararak gel. Karanlık günler geride kalsın. Hep el ele mutlu günler bize kalsın. (ANKARA 1986-16 MAR...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gel-161-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Çocukları', 'dunya-cocuklari-mehmed-sari-pf3ju', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Binlerce çocuk ölüyor her gün

Afrikada açlıktan,

Latin Amerikada

Polinezyada

ve güney Asyada...

Yüzlerce çocuk ölüyor her gün

Kuzey Amerikada

bakımsızlık ve ilaçsızlıktan,

Avrupada

kuzey Asya 

ve Avustralyada...

Onlarca çocuk öldü her gün

gangster devletlerin

hava bombardımanlarından

Sırbistanda, Kosovada,

Irak ve Afganistanda...

Siyah bir kız çocuğu Tanzanyada

on yıldır ellerime bakıyor,

Gözleri kuyular kadar derin,

Umutları yıldızlarca parlak

Büyüyor on yıldır

günde

bir Avustralya dolarıyla...

Oysa,

tüm dünya çocuklarına

ömür boyu yetecek

giysi, ilaç ve yiyecek

çöpe atılıyor her gün

bombacı devletlerin sokaklarında...', 'Binlerce çocuk ölüyor her gün Afrikada açlıktan, Latin Amerikada Polinezyada ve güney Asyada... Yüzlerce çocuk ölüyor her gün Kuzey Amerikad...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Sarı']::text[], 8.5, '{"poet":"Mehmed Sarı","poet_slug":"mehmed-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dunya-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son İstek', 'son-i-stek-sibel-oner-tgmhl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SON İSTEK			

				

				

Yaşayacaksam eğer				

İnsan gibi olayım				

Hayvan gibi değil				

Çimen olacaksam eğer				

Kır çiçekleri olsun üstümde				

Ormanlık değil				

Issız yerde kalacaksam eğer				

Umutları sönmeyenler geçsin üstümden				

Karanlıklar,karamsarlar değil				

Mezara girip toprak olacaksam eğer				

Üstümde çoçuklar koşussun				

Ne kaçan ne kovalayan				

Hırsızlar değil				

Tuğla yapıp örecekseniz beni				

Kerpiç kreşlerde kullanın				

Cezaevlerinde değil				

Soluğum tükenmez ölemezsem eğer				

Şrkı mırıldasınlar				

Aman haa,gazel değil				

Tükenmeyen kalem yapın beni kalem				

Şiirler yazan hayatı üstüne				

Umutsuzluk değil				

Ölümü hissedince ve ölünce				

Yaşamalıyım yıldızlarda				

Nefret dolu bakışlarda değil				

				

				Sibel ÖNER', 'SON İSTEK			 				 				 Yaşayacaksam eğer				 İnsan gibi olayım				 Hayvan gibi değil				 Çimen olacaksam eğer				 Kır çiçekleri olsun üstümd...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/son-istek-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum Seni', 'unuttum-seni-sibel-oner-x1594', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'UNUTTUM SENİ			

				

				

Yıllar boyu kendimizi aldatarak				

Sevdik sandık				

Gecelerce hayale daldık				

Kavuştuk sandık				

Umut dolu yarınlar umduk				

Bulduk sandık				

				

Hep iki yüzlü yalanlarla				

Geçti yıllarımız				

Boş vaadlerle				

Bitti ömrümüz				

				

İnanmıştım sana ben				

Kanmıştım yalanlarına				

Sevmiştim becerisizliğine				

Vurulmuştum saflığına				

Ama neden-niçin? 				

				

Sana şimdi söz veremem				

Yalanlarına affedemem				

Sayfanı kapatıyorum				

Yalan aşkına unutuyorum				

				

Pişmanlığına bağışlayamam				

Sevemem bir daha seni				

Bırak çek git yoluna				

Beni rahat bırak				

Benim gibi sende unut artık				

				

				

			Sibel ÖNER', 'UNUTTUM SENİ			 				 				 Yıllar boyu kendimizi aldatarak				 Sevdik sandık				 Gecelerce hayale daldık				 Kavuştuk sandık				 Umut dolu ya...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/unuttum-seni-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne zaman', 'ne-zaman-sibel-oner-wjm5r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'NE ZAMAN 				

					

					

Ne zaman,yağmur yağsa uzak kentlere					

Islanan saçlarım gelir aklıma,sonra elbisem					

Beyaz badanalı evimizi düşünürüm.					

Derken; sonu gelmez hayallerin					

					

Ne zaman,ağlatan plak çalsa kulaklarımda					

Ayrılığımızı dinlerim,bir falcı kadından					

Anlatmakla bitmez dertler,ben ölürüm.					

Ben ölürüm,yaşadığım hatıralardan					

					

Ne zaman,gün doğudan kendini gösterse					

İnsanlar ölür,bazıları canlanır gözümde					

Biri var şimdi sana,TANRI diye tapan					

Affet der,sonra eğilir,önünde					

					

					

				Sibel ÖNER', 'NE ZAMAN 				 					 					 Ne zaman,yağmur yağsa uzak kentlere					 Islanan saçlarım gelir aklıma,sonra elbisem					 Beyaz badanalı evimizi d...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-zaman-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Sevdam Hiç Bitmeyendir', 'sana-sevdam-hic-bitmeyendir-mehmed-sari-2rhz2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '- E. Nejat''a-

Sesinin kulağıma her gelişinde

çırpınır bütün denizler gözlerimde,

Bütün dağlarda volkanlar patlar

Dalgalanır gökte  yıldızlar...

Her dalganın kaynağı,

ve her yangının ocağı

yaralı yüreğimdir benim,

Sana her dokunamayışta

kahrolur, kanar ellerim...

Yaşamın her anında

seninle olmak,

Suların her damlasında

taşıp, dolmak seninle.

Muhakkak ki sen

evrenin

en güzel verisisin,

Öldürenimsin

ve yeşertensin yeniden beni,

Tatlı bir ağıtsın dilimde

sevdasın  dağlayan yüreğimi...', '- E. Nejat''a- Sesinin kulağıma her gelişinde çırpınır bütün denizler gözlerimde, Bütün dağlarda volkanlar patlar Dalgalanır gökte  yıldızlar...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Sarı']::text[], 8.5, '{"poet":"Mehmed Sarı","poet_slug":"mehmed-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sana-sevdam-hic-bitmeyendir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün ve Sonrası', 'birgun-ve-sonrasi-sibel-oner-m4k38', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BİRGÜN VE SONRASI			

				

				

Soğuk bir kış gecesindeydim				

Camımı yağmur taneleri çarpıyor				

Stresli bir gündeydim				

Camımı kendin bilmezler yakıyor				

Özveriyle çalışmıştım				

Hatalar birbirini kovalıyor				

İyi bir güne başlamıştım				

O iyi bir gün yokoluyor				

Sonu gelmez bir boşluğa düşmüştüm				

Toparlanıp,çıkmayı çalışıyor				

Gün bitip yine geceyi yaşadım				

Körolası yalnızlık kahrediyor				

				

				

				

			Sibel ÖNER', 'BİRGÜN VE SONRASI			 				 				 Soğuk bir kış gecesindeydim				 Camımı yağmur taneleri çarpıyor				 Stresli bir gündeydim				 Camımı kendin b...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/birgun-ve-sonrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak istedim', 'unutmak-istedim-sibel-oner-9apo0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'UNUTMAK İSTEDİM			

				

				

Hep ama hep unutmak istedim seni				

Seni unutnak elimde değil				

Ne yaptımsa olmadı				

Unutamadım seni				

				

Kıskanıyor,çekemiyorum seni				

Kıyamıyor,bakamıyorum sana				

Söyleyemiyorum,seviyorum seni				

Dinliyor,konuşamıyorum seninle				

				

Kendi kendime diyorum ki; 				

Bırak şu münasebetsizi				

Birde gelin bana sorun ki; 				

Unutmak elimde değil onu				

				

				

				

			Sibel ÖNER', 'UNUTMAK İSTEDİM			 				 				 Hep ama hep unutmak istedim seni				 Seni unutnak elimde değil				 Ne yaptımsa olmadı				 Unutamadım seni				 	...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unutmak-istedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam', 'unutamam-sibel-oner-ify5d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'UNUTAMAM				

					

					

Kendimi tanıdım seninle					

Yaşamdan ders aldım varlığınla					

Yaşamayı unutmadım seninle					

Yanlızlığımı teselli buldum gölgenle					

					

Düşlerimdesin her an her gece					

Unutamadım seni günlerce					

Bir değil bin yıl geçsede					

Unutamam seni ömrümce					

					

					

				Sibel ÖNER', 'UNUTAMAM				 					 					 Kendimi tanıdım seninle					 Yaşamdan ders aldım varlığınla					 Yaşamayı unutmadım seninle					 Yanlızlığımı tesel...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/unutamam-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ihlamurlar Çiçek Açtığı Zaman II', 'ihlamurlar-cicek-actigi-zaman-ii-bahaettin-karakoc-fuamr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilirsin ki burda değilim artık

Ihlamurlar çiçek açtığı zaman! ...

Gelir benim yüreğimde toplanır,

Dağların üstünden sıyrılan duman.

Bir yanım mosmordur, bir yanım beyaz,

Bir yanım karakış, bir yanım ilk yaz.

Can evime bakışların saplanır; 

-Ihlamurlar çiçek açtığı zaman! ...

Ihlamurlar çiçek açtığı zaman; 

Ne sen gurbetçisin, ne ben sılacı.

Senden gayrısına bakmam mümkün mü; 

Gözlerimi esir alan dağlardan.

Kapımı üç defa çalan postacı

“Adresinde yok! ” Diye notlar düşer,

Eski adresimde bir hüzün eser; 

-Ihlamurlar çiçek açtığı zaman! ...

Eski adresimse kurumuş bir gül,

Gizemli bir ıtır, domur domur kan,

Yaba yaba yelde savrulur gönül,

Firkatli turnalar geçer uzaktan.

Dalgınlığım debimetre tanımaz,

Başım çarpar bir gemi bordasına

Düşerim bir girdabın ortasına

-Ihlamurlar çiçek açtığı zaman! ...

Birden bezeklenir sevda haritam,

Ihlamurlar çiçek açtığı zaman...

Lâleler toplarım ben tutam tutam,

Bizim için çalar kıvrak bir keman.

Gök papatya, yer ise lâle bahçesi,

Aşka ışık dokur kuşların sesi.

Seninle hep aynı yerde oluruz; 

-Ihlamurlar çiçek açtığı zaman! ...

Kumaşı eprimiş üç mevsim geçer,

İlkyazla uyanır derin uyuyan.

Tan sesine cıvıldaşır serçeler,

Sevdadır anlıma namlu dayayan.

Havuzuma ay ışığı dökülür.

Bilirsin ki burda değilim artık,

Ruhum yağmur yağmur göğe çekilir; 

-Ihlamurlar çiçek açtığı zaman! ...

Gülde çiy damlası... Buzum sırçayım; 

Güneşe çarpınca param parçayım.

Bir gün Emirgân’dayım, bir Kanlıca’da,

Üsküdar’da, Beykoz’da, Çamlıca’da.

Şehir bir hançerken kan burgacında.

Mekâna sığar mı bu deli yürek? 

Bir sevda çeşmesi, bu deli yürek.

Baylanır, beklerken baygın düşerim; 

-Ihlamurlar çiçek açtığı zaman! ...

Ayışığında Serenatlar-Sıla Kitapları', 'Bilirsin ki burda değilim artık Ihlamurlar çiçek açtığı zaman! ... Gelir benim yüreğimde toplanır, Dağların üstünden sıyrılan duman. Bir yan...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/ihlamurlar-cicek-actigi-zaman-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İç İçe', 'i-c-i-ce-gulay-yildiz-esowk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İç içe – I

Her yolu deniyorsun; 

İyi olmayı, kötü olmayı,

İstediğin gibi olmayı...

Bir tek; 

Dilediğim gibi olamadın! 

Ruhun bana yanaşmadı,

Periler kapıp kaçtı....

                                                  İç içe – II

                                                  Dönüyorsun! 

                                                  Geri dönüyorsun

                                                  O dar, kıskaçlarla dolu mahzene! 

                                                  Oysa; 

                                                  Açsan kapılarını

                                                  Ben! 

                                                  Çevireceğim gül bahçelerine, o diken yığınlarını

                                                  Gel! (de)       Yeter! 

Dilediğim gibi olmayı

Ben olmak sanıyorsun.

Oysa ben; 

Seni sen yapacak kadar senim...

                                                 Geliyorsun...

                                                 Nefes kadar yakın olabileceğin halde

                                                 Duruyorsun iki adım ötemde...

                                                 Biliyorsun...

                                                 Yanımda olsan da yanacağım, orda dursan da

                                                 Oysa iki adımsa uzaklık,

                                                 Adımlarım alev topu! 

                                                 Görüyorsun...

                                                 Yanıyorum! 

Tadıyorum her acıyı.

Ağırlığım,

Dengesiz terazinin en olmadık yerinde.

Tartıyorsun.

Aldatıyorsun! 

Aldanıyorum! 

                                                 Nafile!  Kaçıyorsun...

                                                 Yavaşlıyor çaresizce adımlarım. 

                                                 Uzaklaşıyorsun...

                                                 Tek yol alan bende,

                                                 Göz yaşlarım...

                                                 İntihar ediyorlar yanağımdan,

                                                 Islanıyorsun...

Zaman zaman özlüyorsun,

Ellerimin oluşturduğu o minik halkaları

Yüzünde

Hayal ediyorsun...

Gözlerim, dudaklarım, hepsi birer numara oluyor

Arıyorsun! 

                                                 Peşinden bakıyorum; 

                                                 Acıyorsun! 

                                                 Sırtımı dönüyorum; 

                                                 Sen “yine özlüyorsun”

                                                 Biliyorum! 

                                                 Her şeyden Çok! Sevmiyorsun.

Sıradan şeyler diliyorsun.

Ben; 

Seni diliyorum! 

Şimdi de gülüyorsun...

“Egom” diyorsun

“benden ve senden bile büyük”. 

Bilmiyorsun 

                                                    Yalnızca Seviyorsun....

Rüzgarın Efendisi''ne...

Mart,2005', 'İç içe – I Her yolu deniyorsun;  İyi olmayı, kötü olmayı, İstediğin gibi olmayı... Bir tek;  Dilediğim gibi olamadın!  Ruhun bana yanaşmadı,...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/ic-ice-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüver Gitsin', 'guluver-gitsin-dua-ekseni-gncdk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'GÜLÜVER  GİTSİN

Söyle can bu kin,düşmanlık neden? 

Senin mi öfkeyle bu titreyen beden? 

Hüznünüde götürür alıp başını giden

Ahrette de dostuz biz deyiver gitsin.

***

Benimle birlikte şimal yıldızına bak

Hayalinde uzanıp al saçlarıma tak

Tutuştur bir mumu sevda adına yak

Yansın kül olsun kinin özünde bitsin

*** 

Kinin olduğu yerde inan din olmaz

Titizlenilen muhabbet gülleri solmaz

Özveri yoksa hedef menzile varmaz

Gülüver gülünün kalp sızısı dinsin

*** 

Severse gönül, yakın eder ırağı

Küstürür,soldurur güle düşen kırağı

Vurup durma sineme demir tarağı

Özledim seni de GÜL’ ü ver gitsin

(duaekseni)', 'GÜLÜVER  GİTSİN Söyle can bu kin,düşmanlık neden?  Senin mi öfkeyle bu titreyen beden?  Hüznünüde götürür alıp başını giden Ahrette de dostu...', ARRAY['Türk Edebiyatı','Şiir','Dua Ekseni']::text[], 8.5, '{"poet":"Dua Ekseni","poet_slug":"dua-ekseni","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/guluver-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rachel''e', 'rachel-e-dua-ekseni-4ycqj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'RACHEL’e

Kafir tankının önündeki kartal bakışlı göz

Kararlı geri adım atmayan dosdoğru öz

Mazlumun gözyaşına tercüman olan söz

Kara küfrün içinden çıkmış ışık saçan yüz

***

Rachel uzaklardan Filistin’e gelen bir kız

Zulme kalkan başı ezilince sanmayın bahtsız

Semadan düşen değil göğe yükselen yıldız

Ölümsüzleşirken ruhu sadece bedeni cansız

***

Kadınlar gününde umre için Kabe’ye gitmiş

Baş açık,yüzleri makyajın ardında yitmiş

“Aydın Kadınlarmış” görmedikleri tek yermiş

Onlar zaten “Emekçi Aydın” amaç gezmekmiş

*** 

Harem’den aydınlık,çileli ihlaslı gönle yayılır

Sıddıklardan üstün şehitler ölümsüz sayılır

Şahittir kanları öylece İlahi Huzur’a varılır

Şehit değilsin amma aydınlatansın Rachel', 'RACHEL’e Kafir tankının önündeki kartal bakışlı göz Kararlı geri adım atmayan dosdoğru öz Mazlumun gözyaşına tercüman olan söz Kara küfrün i...', ARRAY['Türk Edebiyatı','Şiir','Dua Ekseni']::text[], 8.5, '{"poet":"Dua Ekseni","poet_slug":"dua-ekseni","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/rachel-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığı Paylaşmak Gerek', 'yalnizligi-paylasmak-gerek-huseyin-cayikli-nhjdx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne kadar yalnızsın diyenlere sormam gerek...yalnızlığınızı paylaştınız mı? diyecekler ki bana yalnızlık paylaşılsa adı yalnızlık olmaz...öyle düşünenler yanılıyor oysa...yalnızlık paylaşılabilecek bir olgudur...konuştukça ve paylaştıkça yalnızlığınız akşamları yatağınızda sizi sıkacak terletecek belkide ağlatacak çünkü ona o kadar çok alışmış o kadar çok güvenmiş olacaksınız ve onu kimle paylaşsanız o kıskanç bir sevgili gibi akşamları size hesap soracak çünkü o sizden başkasıyla paylaşılmak istemeyecek... yalnızlık belki baş ağırısı belki öldürücü bir zehirin etkisi yapacak...uyuşacaksınız...bütün anlatılan hikayeler size yalan gelecek...inanmayacaksınız...inananlar aşkın gazabına uğrayıp ömür boyu acı çekecektir...oysa yalnızlığın olumlu bir yönü vardır ve herşeyden ağır basan...yalnızlık kendine aşıktır sadece sizi kendisiyle paylaşır...sizi bir kor gibi yakıp kül etmez...Alışır yüreğiniz...herşeye alışacağınız gibi yalnızlıkta alıştırır sizi...Bir başka kadının kolların da sevişirken sizi bir köşeden izler...tek başınıza kaldığınızda geri dönmek istersiniz ve o size her zaman izin verir...yalnızlık korkulacak birşey değildir...yeterki paylamşamasını bilmelisiniz...', 'ne kadar yalnızsın diyenlere sormam gerek...yalnızlığınızı paylaştınız mı? diyecekler ki bana yalnızlık paylaşılsa adı yalnızlık olmaz...öyl...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/yalnizligi-paylasmak-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'N a s ı l ? ? ?', 'n-a-s-i-l-sibel-oner-94ipr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'N A S I L ? ? ? 			

				

				

Tutunabildiğim tek dal kendim				

Yapabildiğim tek şey çalışmak				

Başarabildiğim tek şey ayakta kalabilmek				

İmkansızı başarmak nasıl? 				

				

Sevebildiğim tek insan benliğim				

Anlatabildiğim tek dost yazılarım				

Dinletebildiğim tek canlı vücudum				

İletişim sağlamak nedir? 				

				

Anlatamadığım tek şey sorunlarım				

Gösteremediğim tek şey duygularım				

Konuşamadığım tek sorun dertlerim				

Ayakta kalmak nasıl? ? ? 				

				

				

				Sibel ÖNER', 'N A S I L ? ? ? 			 				 				 Tutunabildiğim tek dal kendim				 Yapabildiğim tek şey çalışmak				 Başarabildiğim tek şey ayakta kalabilmek		...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/n-a-s-i-l-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk''e Baştan Başlamak', 'turk-e-bastan-baslamak-cazim-gurbuz-if85x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uçsuz bucaksız düşlem

           Siz yakınlaştıkça o sizden uzaklaşan 

           Dolunay suretinde bir Kızılelma.

           Mehtapları büyülü, gel - git''leri deniz oynatan

           Çadır kurmak gibi kurarlardı devletlerini

            Mesajları yay gerginliğinde

            Senaryolar dolu sadaklarında.

            Üç tuğluk şan, bir kişnemelik bildiri 

            Utku mayası buyruklardan doğmuştur

            Onların kırk asırlık destanları

                       

            Turna donunda bir bölük ermiş

             Yekunu Yesi''dendir, sökünü Horasan''dan

             Ya bu yazıt, bu taş kesilmiş define sözler? 

             Onlarda olan, bizde olmayanlar mı? 

             Masallarında az - uz gidilir onların

             Estetik düğümlenir halılarında

             Derken bir bakarsınız şiirler büyütmüşlerdir

                 Çöl yalnızlıklarında

                    Buzul doruklarında

                      Bağ bozumlarında

                          Ceylan ürkekliklerinde

                               Hüma uçuşlarında 

                                    Pınarbaşı buluşmalarında

                                        Ve dilber edalarında

             Dalgayla horon teperler onlar

             Yıldırımla yere iner

             Borayla ayaklanırlar

             Bin dereden su getirirken

             Bir göl büyülemiştir onları

             Hu çekmişlerdir nice çağlayanlar aşkına

                       

             Fermanla buyurgan olurlar

             Düğün, dernek ve şölende ise çağırgandırlar.

             Türküleri sürülerinden çoktur

             Hemi keyiften, hemi zordan

             Zurnaları kaynaştırıcı

                  Kopuzları dertleştirici

                      Meyleri ağıt ağıt

                          Davulları dengi dengine vurur

                               

            Yeri gelir bir erguvan gibi aşka ve hüzne boğarlar

            Gönüllerince engin ve sınırsızdırlar.

            Sonra bir bakmışsınız

            Görkem oluvermişlerdir baharda bezenen çınarlar gibi

            Doruklar bile doyuramamıştır yücelik tutkularını 

                               

            Beşikte ninni mutlusu körpe

            Nene dizinde masal esrisi bala onlarındır.

                Şu oya

                   Şu kök boya

                       Şu ışıkla oynaşan vitray

                          Şu yar mendili

                              Şu gelin bohçası

                                 Şu egemenlik akçası

                                     Şu lale

                                         Şu gül bahçesi

            Bunlar da onlarındır

            Yasin Kur''an''da güldür onlara göre

            Peygamber insanda gül.

            İslam onlarla güldü

            Onlar ki İslam''ın gülü

           Göğün yedi katının vekaleti var kubbelerinde

           Taş''ın miracıdır minareleri

            Kündekâri kapılar ki mabetler yaraşığı

            Ebru ciltlerle görücüye çıkan el yazmaları

            Kendi ayak izlerini aramak coğrafyanın yüzünde

            Ve tarihin gözündeki 

            Nizam-ı alem desenlerinde.

            O desenler ki fetvalar takvaca 

            Hükümler hikmet üzre

            ''Ve ben ki... Ve sen ki...'' diye yazılanlar vardı ki

            ''Muhteşem'' diler

                            

            Onlar dünyanın ilk ordusudurlar

            Tekerleği buldular yüklet için

            Demiri buldular pusat için

            At üstünde çerge taşıdılar

            Savaşta da pak olmak için

           Severler dost ve gönüldaşlarını

           Dost ve gönüldaşlarının sevdiklerini

           Dost ve gönüldaşlarını sevenleri de.

           Üç kıtalık mekanlardan

           Ve zaman içindeki zamanlardan sor onları

                          

           Bir buruk çay

              Bir acı sigara

                  Bir dostun yüzü ve sözü

                     Bir eder

                        Şen eder

                            Şad eder onları.

                                 Tanışır

                                      Danışır

                                           Ve dayanışırlar

                                               Hayırda yarışırlar

            Beş vakit namazda hayır duaları beklenir büyüklerin

            Yüksek bir Türk kızına takdim edilip

            İyi olmanızı Ulu Tanrı''dan dileyen

            Özlem yazıları vardır ki 

            Geçmiştir, bugündür ve yarındır

            Okunur okunur koyunda saklanırlar kaç asırdır

            Onlar ER mektubudurlar GÖRÜLMÜŞLERDİR', 'Uçsuz bucaksız düşlem            Siz yakınlaştıkça o sizden uzaklaşan             Dolunay suretinde bir Kızılelma.            Mehtapları büy...', ARRAY['Türk Edebiyatı','Şiir','Cazim Gürbüz']::text[], 8.5, '{"poet":"Cazim Gürbüz","poet_slug":"cazim-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":96,"source_url":"https://www.antoloji.com/turk-e-bastan-baslamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yine Ben', 'ben-yine-ben-sibel-oner-p31jw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BEN YİNE BEN			

					

Seni sevmekten başka hiçbir şey düşünmeyen					

Aşkına esir olmuş zavallı biriyim ben					

Sevmeyi ezberleyip sevilmeyi bilmeyen					

Eğlenmeyi unutup,ağlayan biriyim ben					

Aşık olduğum günden beri düşünen					

Senden başka düşüncesi olmayan biriyim ben					

Ufak bir tebessümle haftalarca sevinen					

Senden birazcık ümit bekleyen biriyim ben					

Sana olan aşkımda hep hüsrana uğrayan					

Dertleri zevk ederek yaşayan biriyim ben					

Hayalinle avuna canlı bir özlüyüm ben					

					

					

				Sibel ÖNER', 'BEN YİNE BEN			 					 Seni sevmekten başka hiçbir şey düşünmeyen					 Aşkına esir olmuş zavallı biriyim ben					 Sevmeyi ezberleyip sevilmey...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-yine-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-sibel-oner-rrol9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'MUTLULUK							

						

	Çiçekler açarken şarkı söyler lale					

	Tan ağarırken mutlu olur gönüller					

	Kuşlar cıvıldarken huzur dolar insan					

	Aşk sözcükleri mırıldanırken kulağına					

	Bulutlar üzerinde uçarsın yağmur taneleri gibi					

	Buluttan ayrılmış fakat yere düşmemiş					

	Yağmur tanelerini bilirsin ya! 					

	Bende şuan bulutlar üzerinde lakin,					

	Yere düşmemeye çabalayan ruh misali					

	Hep bulutlarda bulutlarda kalmak istiyor gönlüm					

	Bulutlar dolu dizgin koşmakta,					

	Hemde sınırsızca durmaksızın					

	Banada bir yer vermişler.sağolsun derim					

	O yerimi kaybetmek istemiyor gönlüm					

	Bulutlar saf,beyaz ve temiz					

	Dolunay misali birgün onun olsa					

	Yılda bir kerede çıksa zirveye					

	Tatlı hayallerle dolu olsa					

	Yalancıktan bile olsa inandırsa					

	İnanmış görünüp mutlu olsa					

	Kısa bile sürse, işte en büyük mutluluk					

						Sibel ÖNER', 'MUTLULUK							 						 	Çiçekler açarken şarkı söyler lale					 	Tan ağarırken mutlu olur gönüller					 	Kuşlar cıvıldarken huzur dolar insa...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mutluluk-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Yaşasaydım Ben', 'eger-yasasaydim-ben-sibel-oner-gx50e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'EĞER YAŞASAYDIM BEN			

				

Umutlarımın tükendiği bu yolda				

Eriyorum mum gibi				

Damla damla akan kanımda				

Ölüyorum hiç yaşamamış gibi				

Çekiştiriyor dört bir yandan vücudumu				

Titriyor üşüyor her dakika bedenim				

Sorular çakıştırıyor heran kafamı				

Nedensiz,cevapsız sorunlar				

Yaşıyormuyum,diyorum her an aklımda				

Varmıyım bu bedende beynim				

Ne acayip şey,çıldırıyorum yaa				

Aklımı bozacağım bir gün				

O bir gün çok yakın				

Belki birgün belkide bugünden yakın				

Yaşamak anlamsız bu alemde				

Ölmek te çok acı bee				

Bir ohh çekebilseydim ne vardı				

Ohh çekebilmeyi öğrenebilsem eğer				

Vurdumduymaz olabilirsem eğer				

Kendimi hala sevebilirsem eğer				

Ayakta hala dimdik durabilirsem eğer				

Ne isteyebilirim ki BEN				

				

				Sibel ÖNER', 'EĞER YAŞASAYDIM BEN			 				 Umutlarımın tükendiği bu yolda				 Eriyorum mum gibi				 Damla damla akan kanımda				 Ölüyorum hiç yaşamamış gib...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/eger-yasasaydim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılsın Kalem', 'kirilsin-kalem-mesut-alp-z0nj6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yargılıyorlar beni

Seni sevdiğim için

Zorluyorlar beni

Seni bırakmam için

Bilemezler bilemezler

Ruhum sana mahkum

Bilemezler bilemezler

Bedenim sana tutsak

İp gerseler boynuma

Yine vazgeçmem senden

Bedenim ayrı dursa da

Ruhum ayrılmaz senden

Vurulmuşum vurulmuşum

Dönülmez yolda durmuşum

Kırılsın kalem

Kesilsin cezam

Olsa da idam

Gam yemem inan', 'Yargılıyorlar beni Seni sevdiğim için Zorluyorlar beni Seni bırakmam için Bilemezler bilemezler Ruhum sana mahkum Bilemezler bilemezler Bede...', ARRAY['Türk Edebiyatı','Şiir','Mesut Alp']::text[], 8.5, '{"poet":"Mesut Alp","poet_slug":"mesut-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kirilsin-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Bir Kadın', 'yalniz-bir-kadin-sibel-oner-ktxv0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YALNIZ BİR KADIN				

						

						

Bu akşam sokaklarda yapayalnız dolaştım.						

Görenler ''yalnız bir kadın''diyordu.						

İçim nasılda kalabalıktı,kimse bilmiyordu.						

Buz gibi bir ayaz yüzümü kesiyordu.						

Saçlarımı sert rüzgarlar savuruyordu.						

Erkekler gelip geçiyordu yanımdan						

Evde kadınları bekliyordu.						

Ve kadınlar,aceleci telaşlı						

Örtük perdelerin arkasında						

Akşamı bekliyorlardı.						

Ya ayna karşısında						

Ya ocak başında						

Bir ben beklemiyordum kimseyi						

Yemek yapsamda olurdu,yapmasamda						

Çarşafım ütüsüz olsa ne farkeder? 						

Kimse bilmez saçlarımı taramadığımı						

Bu akşam sokaklarda yapayalnız dolaştım.						

Gençliğim cilveli nazlı,						

Bir dul olmuş,yoluma bağdaş kurmuş oturmuştu.						

''Çekil git''diyordum,çekilmiyordu.						

Tutkularım saçımı çekiyordu arkamdan						

Kimse görmüyordu.						

Bu akşam sokaklarda yapayalnız dolaştım.						

Sokaklar yalnızlık şarkıları söylüyordu.						

Ve eteklerim dizlerimi yapışıyordu.						

Ama zaten kimse beni kıskanmıyordu.						

Benim bu şehirde beklediğim kimse yok.						

Kimse yok gösterecek oturup da süslensem.						

Bir sevgilimde yok ellerimi ısıtacak						

Öbür şehirde de yok.						

Hiçbir şehirde yok.						

Bu akşam sokaklarda yapayalnız dolaştım.						

Ellerim çok üşümüştü kimse ısıtmıyordu.						

Görenler ''yalnız bir kadın''diyordu.						

İçim nasılda kalabalıktı,kimse bilmiyordu.						

						

					Sibel ÖNER', 'YALNIZ BİR KADIN				 						 						 Bu akşam sokaklarda yapayalnız dolaştım.						 Görenler ''yalnız bir kadın''diyordu.						 İçim nasılda kal...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yalniz-bir-kadin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın', 'kadin-tuncay-akdeniz-ufm51', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kadınsız dünyada,yaşam olur mu? 

Beşeri alemin,şanıdır kadın,

Kadınsız gönüller,sevgi bulur mu? 

O şah damarın kanı''dır kadın

Gönüller sevgisi kalplerin gülü

Sevenine karşı olmuştur deli

Dört mevsim içinde, kurumaz dalı,

Elvan,elvan rengin,tonu''dur  kadın.

Koymuşlar adı''nı,aşkın kadını

Yaşam senden alır,gerçek tadını

E-nel haktan almış, (Ana)   adını

İnsanın anası, canı''dır   kadın

Ömür boyu bitmez elinde işi

İlk bahar gibidir hep yazı kışı

Başına taç etsin sevdiği kişi

Aile''nin ana yönü''dür  kadın

Kadının önemi,değil sekiz mart. 

İşte beni deli,ediyor bu dert 

Mahşerde kadına,zor değil sırat. 

Cennet ehlinin,ünü''dür kadın. 

Tuncay''ım değişmem,güneşe,aya

Neslime olmuştur en güzel maya.

Hayatıma hayat,kalbime ziya,

Ömür boyu sevgi günü dür kadın.

					

08.03.2004', 'Kadınsız dünyada,yaşam olur mu?  Beşeri alemin,şanıdır kadın, Kadınsız gönüller,sevgi bulur mu?  O şah damarın kanı''dır kadın Gönüller sevgi...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kadin-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vardı', 'vardi-sibel-oner-7ow9u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'VARDI			

				

				

Hayatıma ne baharı tattım,nede yazı				

Hep kışı yaşadım,soğuk kışı				

Bahar geldi diye uyardılar bir kere				

Oda çarçabuk geçti ömrümden				

Doyasıya yaşamak vardı dün içimde				

Sevmek,sevildiğini bilmek vardı yüreğimde				

Yaşamak,aşkı ölümsüzce kalbimde				

Sevmek ve sevilmek vardı dileklerimde				

				

				

				Sibel ÖNER', 'VARDI			 				 				 Hayatıma ne baharı tattım,nede yazı				 Hep kışı yaşadım,soğuk kışı				 Bahar geldi diye uyardılar bir kere				 Oda çarça...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vardi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benmişim Ben Been', 'benmisim-ben-been-sibel-oner-0gx0i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BENMİŞİM BEN BEEN				

					

					

Bir varmış bir yokmuş derken					

Geldi geçti bütün hayat					

Saniye saniye yaşanacakken					

Saat saat tükendik					

Oysa çırpınıyordu kalbim saniyeleri ulaşmak için					

Ve şimdi ulaşamadığımı anladım					

Ulaşmak tı tek amacım,yaşamak için					

Ve şimdi yaşamadığımı anladım					

Güleç yüzlü olduğum söyleniyor yalan					

İyi kalpli olduğum söyleniyor,yalan					

Gamsız.dertsiz,sıkıntısız,OYSA.....					

Ben varya ben ben ben been					

Hep dertli,sıkıntılı,gamlı hatta					

Vurdumduymalı,umursamalı,galeci					

En önemlisi bir çıkmazda					

Eee senin çıkmazının daa....					

Aşacak ben,sadece ben					

Dokuz sülalesinide....					

Yapacak ben,sadece ben					

İyi kalpli olduğumu söyleyenler					

Halt etmişler,ben olmayacağım iyi kalpli					

Güleçyüzlü diyenler,yalan söylüyor					

Olmaya çalışacağım daha					

Ne farkeder,ne kazandırır bilinmez					

Çalışacağım,dedikleri gibi olmayı					

Bu benim içimi sindiremese de					

Göze alacağım mide spazmı olmayı					

Özürlü yaşamak olsada					

Ben ben been olacağım yaşasamda					

				Sibel ÖNER', 'BENMİŞİM BEN BEEN				 					 					 Bir varmış bir yokmuş derken					 Geldi geçti bütün hayat					 Saniye saniye yaşanacakken					 Saat saat t...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/benmisim-ben-been-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat mı bu? - Galiba', 'hayat-mi-bu-galiba-sibel-oner-c8nvt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'HAYAT MI BU? - GALİBA			

				

				

Öyle zor ki yaşamak bu alemde				

Anlatamam				

Öyle yıpratıcı ki bu hayat				

Tarif edemem				

Anlatamam çünkü yaşamdan koptum ben				

Tarif edemem çünkü zindandayım ben				

Örf,adet,denilen tabu yıkılmamış				

İnsancıklar kendi fikirlerini benimsememiş				

Sevmemiş gönüllerince bir dişiyi				

Parmakla gösterilmemiş yaptıkları				

Kırmışlar düşünmeden gururları				

Yıkmışlar insafsızca kalpleri				

Ağlatmışlar gözü yaşlıları				

Avutmamışlar ıslak mendilleriyle				

Hissetmemişler güzel olan temiz duyguları				

Sonsuz sevgi için and içmemişler				

Aldanıp aldatarak intikam almamışlar				

Sevip terkedilerek unutulmamışlar				

Yarasını merhem olacak bir kul bulamamışlar				

Böyle insandan ne hayır beklenir				

Ancak aşk sancısı içinde kıvranır				

Sonu gelmeyen cefalrında yıpranır.				

Ölümsüze doğru yol alır				

Böyle yaşamak yaşamak sa eğer				

Ve kolay yaşamak sa bu hayat				

Yıpranılmıyor mu bu yaşamda				

Bir canlı varmı aksini iddia eden				

Ben bunların içinde eleniyorum inan				

				

				

				Sibel ÖNER', 'HAYAT MI BU? - GALİBA			 				 				 Öyle zor ki yaşamak bu alemde				 Anlatamam				 Öyle yıpratıcı ki bu hayat				 Tarif edemem				 Anlatamam...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hayat-mi-bu-galiba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmazlardayım', 'cikmazlardayim-sibel-oner-pvfsh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ÇIKMAZLARDAYIM		

				

				

İçimde öyle bir sıkıntı varki				

Tarif edilemez,anlatılmaz				

Boğuluyor,nefes alamıyorum ki; 				

Anlatsam anlaşılmaz				

Haykırmak istiyorum öyle ki; 				

Bğırsam duyulmaz.				

Ağlamak istiyorum insan gibi				

Akıtsam yaşlarım görülmez				

Bitap düştüm yorgunum				

Çaresizim,çaresiz				

Hastayım,hemde ölümüne				

İyileşmem imkansız				

				

			Sibel ÖNER', 'ÇIKMAZLARDAYIM		 				 				 İçimde öyle bir sıkıntı varki				 Tarif edilemez,anlatılmaz				 Boğuluyor,nefes alamıyorum ki; 				 Anlatsam anla...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cikmazlardayim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyorum ki;', 'diyorum-ki-sibel-oner-gyaw0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'DİYORUM Kİ; 		

			

Şu dünyayı bakın 			

Kimi beyaz,kimi kara			

Hepsinin yüreğinde 			

Ayrı bir yara			

			

Bende bunlardan biriyim			

Delimiyim neyim			

Hayattan uzakta			

Boşluklardayım			

			

Diyorum ki:			

Her şey toz pembe olsa			

Bulutlar üzerinde uçsak			

Sorunsuz dertsiz gökyüzünde			

Sevdiklerimizle kucaklaşsak			

			

			

			

			Sibel ÖNER', 'DİYORUM Kİ; 		 			 Şu dünyayı bakın 			 Kimi beyaz,kimi kara			 Hepsinin yüreğinde 			 Ayrı bir yara			 			 Bende bunlardan biriyim			 Delim...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/diyorum-ki-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız', 'zamansiz-huseyin-sigirtmac-gnw4t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık varlığını yoka sayarım.

Bitirdin kendini gittin zamansız.

Sorma hatırımı sanma duyarım.

Duyguma kemendi attın zamansız.

Dönüşü olmayan bir yola sürdün.

Ben esirin idim, sen ise hürdün.

Sevgimi günahın, edebin gördün.

Değer yargın ile bittin zamansız.

Hükmeder inadım yener hazımı.

Tel olsan, seninle çalmam sazımı.

Yitirdim bulamam eski arzumu.

Sığırtmaç’ı pula sattın zamansız.', 'Artık varlığını yoka sayarım. Bitirdin kendini gittin zamansız. Sorma hatırımı sanma duyarım. Duyguma kemendi attın zamansız. Dönüşü olmayan...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zamansiz-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın**2', 'kadin-2-tuncay-akdeniz-j6pbi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzellik üstüne cennet kurulmuş

Cennet güzelinden biridir kadın

Melek güzelliği sana verilmiş

Cenneti alada huri dır kadın

Dişi kuştur derler yuvayı yapan

Emeği altındır parasız satan

Erkeğin elinden kadındır tutan

Kalplerde sevgini yeridir kadın

Güller gibi her gönülde sevilen

Gelin olup duvaklara bürünen

Merhem gibi her yaraya sürülen

Lokman hekimlerin piridir kadın

Sen Tuncay a Ana oldun doğurdun

Esen rüzgarlara karşı dururdun

Kol kanat açar yavrun korur dun

Çiçekten bal yapan arıdır kadın

					08.03.2003', 'Güzellik üstüne cennet kurulmuş Cennet güzelinden biridir kadın Melek güzelliği sana verilmiş Cenneti alada huri dır kadın Dişi kuştur derle...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kadin-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş Ahh Geçmişim', 'gecmis-ahh-gecmisim-sibel-oner-9cbk5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GEÇMİŞ  AHH GEÇMİŞİM			

				

				

Ümit dünyam diye bir dünyam kalmadı				

Dert zincirlerimi bitirirken				

Bir yenisi daha eklendi,ancak				

Savaşı ben kazandım yapayalnız ayaktayım				

Oysa şimdi savaşacak bir dünyam kalmadı				

Hayattaki felsefem zoru başarmaktı				

Bir yerlere gelip,arkama dönüp bakmaktı				

Maddiyatta değil,maneviyattan zenginlikti				

Oysa öyle bir dünyam hiç olmadı				

Hayattaki en önemli yeri gururum almıştı				

Ama seviyordum gururumu hiçe sayarak				

Düşünmüyordum kendimi hiç başkası kadar				

Oysa şimdi düşünecek benliğim kalmadı				

Yaşamımın bir parçasıydı acılarım				

Ayakta tutuyordu beni anılarım				

Yaşama bağlıyordu tatlı hayallerim				

Oysa yaşanacak hiçbir şey kalmadı				

Sevmek acı verirmiydi bende				

Seviyorsam eğer seni sende				

Görüyorum seni kendimde				

Ölüyorum bedenimde yavaş yavaş				

İstesemde istemesemde ben hep böyleyim				

Ölüyorum desemde hep yine yaşıyorum				

İsyan etsemde devam ediyorum				

Çıkmazda kör kuyuda boğuluyorum				

				

				

				

				Sibel ÖNER', 'GEÇMİŞ  AHH GEÇMİŞİM			 				 				 Ümit dünyam diye bir dünyam kalmadı				 Dert zincirlerimi bitirirken				 Bir yenisi daha eklendi,ancak				...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gecmis-ahh-gecmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaynana', 'kaynana-refik-recep-pelit-12xk9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürüyecektik hani senin ile yanyana,

Sen yavrum dedikce,bu gönül sana aşina 

Zehir etme hayatı içelim kana kana,

Sığmazsın bu cüsseyle,o minicik kazana. 

Oğluna ister iken,benziyordun Mehtaba,

Köprüden geçmek için,dayı dedin Babama 

Sen''de benim yaşımda olmadın mı acaba? 

Bu tafra ve çalımla layıksın sen kazana.

Namaz''la,Niyaz ile eremezsin Murad''a, 

İnsan olmak gerekli üç günlük bu Dünya''da,

Ömrünü uzun sanma, ne kaldı ki sonuna 

Kazandığın saygıyı,atma kaynar kazana.

Gölge etme yeter,hiç gerek yok ihsanına 

Niyetin iyi olsa, içten derim Amenna,

Gündüz vakti kalınca, senin ile başbaşa

Canım atmak istiyor,seni kaynar kazana.

Yediğim lokmaları,gerek yok ki saymana,

İzin vermem konuşup,izanımı baymana,

En akıllısı Sen''sin, sor istersen aynana

Kuyu kazan kaynana,düşsün kaynar kazana.

Sevip geldim evine, sanmayasın yanaşma,

Bu yaptığın şirretlik, kalmaz senin yanına,

Elbet günün birinde, vurursun taş kafana,

Allah sabırlar versin, gireceğin  kazana.

Sivrisinek saz olur hakkınca anlayana,

Davul,zurna az gelir,Ben''lik hissi sarana,

Hor gördüğün gelinin,merhem olsun yarana,

Cehennem''de kaynıyor,kazan kazan kaynana.

Dünya malı deniz, sığdıramazsın şafula

Mahlukat-ı hüda,tüm yüreklerle yanyana

Mühlet tamam olup da, çıkmak için mihraba

Gönülleri hoş tut sen, Cem-i Cümle Kazan''a.', 'Yürüyecektik hani senin ile yanyana, Sen yavrum dedikce,bu gönül sana aşina  Zehir etme hayatı içelim kana kana, Sığmazsın bu cüsseyle,o min...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kaynana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsteklerim', 'i-steklerim-sibel-oner-0lkts', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İSTEKLERİM			

				

Uyanmak istiyorum artık kabuslu gecelerden				

Silkinmek hemde çarçabuk dertlerimden				

Koşmak istiyorum delicesine cennete				

Arkama dönüp bakmadan koşmak				

Yorulmadan dolu dizgin yol almak				

Düşünmeden pervasızca konuşmak				

Üzülmeden aşkı yaşamak				

Ölmeden mutlulukla tanışmak				

Yılmadan yorulmadan çalışmak				

Bıkmadan bıktırmadan sevmek				

Bir damla mutluluk için				

Durup dinlenmeden beklemek				

Beklemek varya ölümden beter				

İnsan ümitsizce bekleyeceğine				

Bin defa ölsem gam yemem				

İnsan umutlanıp hüsrana uğrayacağına				

Bir dega kırılsam üzülmem				

				

				Sibel ÖNER', 'İSTEKLERİM			 				 Uyanmak istiyorum artık kabuslu gecelerden				 Silkinmek hemde çarçabuk dertlerimden				 Koşmak istiyorum delicesine cenn...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/isteklerim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen? ? ? Ben? ? ?', 'sen-ben-sibel-oner-p9jg1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SEN? ? ? BEN? ? ? 			

				

				

Soğuk kara kışı bilirmisin SEN				

Kara kışım şimdi BEN				

Kuru ayaz gece yaşadınmı SEN				

Buzullar içindeyim BEN				

Baharla hiç tanışmışmıydın SEN				

Gonca güller gibiydim BEN				

Serin bir yaz akşamı yaşadınmı SEN				

Gül kokan nefes gibiydim BEN				

Sevilip hiç sevdinmi SEN				

Sevdim sevildim BEN				

Aşık olup hiç düşündünmü SEN				

Bağlandım delicesine BEN				

Sorguluyorsan kızıyormusun SEN				

Oysa sorulmasını istiyorum BEN				

Yaşıyorsan mennunmusun SEN				

Öldüm yaşamıyorum BEN				

Ağlayınca kan akıtabiliyormusun SEN				

Damla damla eriyorum BEN				

Kızınca bağırabiliyormusun SEN				

Sinirleniyor tıkanıyorum BEN				

Düşüncelerini aktarabiliyormusun SEN				

Dinletemiyor duyuramıyorum BEN				

Düşlerini yaşayabiliyormusun SEN				

Hayallerimi bile kramıyorum BEN				

				

				

				Sibel ÖNER', 'SEN? ? ? BEN? ? ? 			 				 				 Soğuk kara kışı bilirmisin SEN				 Kara kışım şimdi BEN				 Kuru ayaz gece yaşadınmı SEN				 Buzullar içinde...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-ben-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-sibel-oner-yycm8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ANNEM				

					

Bir sen kaldın bir sen! 					

Dizlerine çökülecek					

Elleri öpülecek					

Bir sen varsın bir sen! 					

Can-ı gönülden sevilecek					

					

Bir sen kaldın bir sen! 					

Bu fani dünyada güvenecek					

Sırları emanet edilecek					

Bir sen varsın bir sen! 					

Yokluğuma kahredecek					

					

Bir sen kaldın bir sen! 					

Kutsal ellerine çiçek verilecek					

Ellerinden su içilecek					

Bir sen varsın bir sen! 					

Uğruna kurşunlara dizilecek					

					

					

				Sibel ÖNER', 'ANNEM				 					 Bir sen kaldın bir sen! 					 Dizlerine çökülecek					 Elleri öpülecek					 Bir sen varsın bir sen! 					 Can-ı gönülden sev...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/annem-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanan Yüreğime', 'yanan-yuregime-huseyin-sigirtmac-mi02k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanan yüreğime kar olabilsen.

Şu yalnız gönlüme yar olabilsen.

Her gün zarardayım kar olabilsen.

Bana şu dünyada ölüm olur mu? 

Kimi efkarına neşe katmakta.

Kimi düğün kurup duvak takmakta.

Yelken açtım gemim suya batmakta.

Yar yetişip kanat kolum olur mu? 

Kederime sebep hasret duygusu.

Ölümden korkum yok, yaşam kaygısı.

İnsanın insana bitti saygısı.

Battığım çamurlar yolum olur mu? 

Yorgunum hasretten, zor gelir sevdan.

Fedakarca yanar seven her insan.

Yağmuru üstüme kar etti Nisan.

Sığırtmaç açan bir gülüm olur mu?', 'Yanan yüreğime kar olabilsen. Şu yalnız gönlüme yar olabilsen. Her gün zarardayım kar olabilsen. Bana şu dünyada ölüm olur mu?  Kimi efkarın...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanan-yuregime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dediler', 'dediler-sibel-oner-p9cvz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'DEDİLER				

					

Seversin dediler erkeğini					

SEVDİM					

Sabredersin dediler sıkıntılarını					

SABRETTİM					

Çekersin dediler üzüntülerini					

ÇEKTİM					

Başarırsın dediler yaşamayı					

BAŞARDIM					

Yakalarsın dediler mutluluğu					

YAKALADIM					

Sevilip sayılırsın dediler					

SEVİLDİM					

Unutursun dediler herşeyi					

UNUTAMADIM					

Unutmak mı dediniz					

Unutmayı ne sandınız					

Bu dünyanın girdabında					

Kötülük yapmak mı maksadınız					

					

					

					

				Sibel ÖNER', 'DEDİLER				 					 Seversin dediler erkeğini					 SEVDİM					 Sabredersin dediler sıkıntılarını					 SABRETTİM					 Çekersin dediler üzüntüle...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dediler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evet-Hayır', 'evet-hayir-sibel-oner-cb45k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'EVET-HAYIR			

					

					

Seslensem duyarmısın beni					

Hayır duymanı istemiyorum					

Sevsem bir ömür boyu seni					

Hayır sevmeyi istemiyorum					

Layık olmak istiyorsan bana					

Hayır olamazsın biliyorum					

Unuttum desen inanırmısın beni					

Evet unuttuğumu bilmeni istiyorum					

Unutamadım diyorsan beni					

Evet inanıyorum unutamazsın beni					

Silip kalbimden attım desen beni					

Hayır inanmıyorum sana					

Şimdi başka mekandasın biliyorum seni					

Başka gönüllere taht kurdun biliyorum seni					

Bu tahtını yıkmak istiyorum biliyormusun					

Bilemezsin çektiğim ızdırapları anla beni					

Anyamazsın.düşüncelerimi duy beni					

İhanet edemezsin bil bunu					

Tekrar sevemezsin dönme geri					

Bir ömür boyu sildim seni					

					

					

				Sibel ÖNER', 'EVET-HAYIR			 					 					 Seslensem duyarmısın beni					 Hayır duymanı istemiyorum					 Sevsem bir ömür boyu seni					 Hayır sevmeyi istemiy...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/evet-hayir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basit', 'basit-sibel-oner-v3bxs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BASİT				

					

Bahar gibi taptazeydim daha dün					

Kaçırırcısına koşuyordum yaşamın arkasından					

Çoştukça coşuyordum ölmeyecekmiş gibi					

Sadece bugünü yaşıyordum yarını hiç					

Ölüm kelimesi ile tanışmamıştım daha dün					

Hep sımsıcak akacak sandım damarlarımdaki kanı					

Parlomda ağlamak yok,gülmek vardı					

Hedefim yenmek,yenilmemekti					

Dayanağım,mutluluğum ve kendimdi.					

					

					

					

					

				Sibel ÖNER', 'BASİT				 					 Bahar gibi taptazeydim daha dün					 Kaçırırcısına koşuyordum yaşamın arkasından					 Çoştukça coşuyordum ölmeyecekmiş gibi	...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/basit-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Falcı kadın giderken...', 'falci-kadin-giderken-leyla-isik-5h5cp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşam vakti seninle sensiz indim sahile…bir demet çiçek aldım, uzattım hiç    tanmadığım birine. Önce şaşkın şaşkın  baktı…sonra aldı. Kokusu yayıldı ellerimden çimensi gözlerine. 

Kimbilir…

Beklediği sevgiliye benzetti belkide. Bakıştık. Gülümsedim…gülümsedi. Daha da açtı    çiçekler ellerinde. Bir avuç sevgi bıraktım yüreğine.

 Kızma sevdiğim,

 Kızma…

 Sevgimizi parçalayıp çoğalttım yabancı yüreklerde. Sonra, yürüdüm… yürüdüm sahil boyu,olta atan insanlar gördüm düşlerine…Ben oltasız yemledim denizi.

Sevindi kaya kovuğunda ağlayan bir balık. Süsleyeceği içki sofrasından kurtulunca…

Geceye hazırlanıyordu İzmir,yanıp yanıp sönen elbisesiyle yine.Uzanıyordu ışıklar Karşıyaka’dan Göztepe’ye kavuşmak istercesine…buluşup  ayrılıp,sevişiyorlardı denizin derinliklerinde. Demir atmış yük gemileri,sessiz denizi dinliyorlardı.

Sevdiğim…bu kez  gözlerim denizin derinliğine değil,gözlerimin derinliğine deniz dalıyordu.Çoktan öpmüştü gün giderken denizi o mavi gözlerinden.Gümüş rengi ışığıyla okşarken denizi Ay, gülümsüyordu.Rüzgar tarıyordu saçlarımı…

İki genç sevgiye dolanmış  öpüşüyorlardı soğukta.

Dünya umurlarında değil,

Ne güzel sevdiğim,

Ne güzel! 

Umurlarında değil! …

Ellerinde baklaları…dallı güllü şalvarları…çıplak ayakları… yazgılarını başlarına bağladıkları  yazmalarıyla falcı kadınlar….Dolaşıyorlardı sahili boylu boyunca 

                                               

Boğaziçi’nden? …

Kuruçeşme’den? …

İzmir’in neresinden kimbilir….

Kimbilir neresindendiler.

Biri zorla aldI elimi,kırlarda pıtrak avuçlarının  içine. Bilecekmiş geleceğimi…

         

                                           Abe  falına bakayım güzel kadin! 

                                              İstemem senden metelik…

                                                  Seni sevdim bak ha! 

                                         Rahat bırak elini,avucumun içinde,

                                             Bak nasıl

                                                Geçmişini…geleceğini.

                                                     Döktüreceğim sana…

Göz göze geldik iki kadın…..kıramadım onca ısrarlarını. Rahat bırakınca elimi avucunun içine,döküldü dallı güllü şalvarından güller,sevincinin içine. Sıralıyordu kadın,ezberinden sözcükleri birer birer.Diz çöküp önümde…..

 Dalmışım

Yarı gerçek,yarı yalan sözlerine.

Anlamıştı sanki,

Yaşlarımı göstermeden ağladığımı

Sustu.

Konuşmadan baktı,

Gözlerimin içine bir süre öylece…

Göz göze geldik iki kadın…

Yangınından olsa gerek

Kocasının mühürlediği bağrından

Iki düğme çözmüş….

Yayıyordu kokusunu bağrının baygın baygın.

                                       “Saçların günbatımı gibi

                                       Ne güzel ellerin Hanımım…

                                              Sevdalısın belli

                                        Pırıl pırıl bakıyor gözlerin

                                                     Ama

                                    Biraz kırgınsın…biraz kızgın

                                         Özlüyorsun sevdiceğini

                                          Okuyorum yüreciğinden.”

Bakıştık

Belli belirsiz bir gülümseme geçince dudaklarımdan,bu kez çıkardı baklaları cebinden.

                                                    “Bu sevincin olsun…

                                                           Bu üzüntün…

                                                               Bu sevdiceğin,

                                                                    Bu da sen…

                                                                    Aaa

                                                                Az kalsın unutuyordum

                                                           Nazar var üstünde senin,

                                                       Bu mavi taş ta nazar olsun…”

Bir bir bıraktı adlandırdığı baklaları avucuma. Son anda,eski bir jetonuda okuyup,üfleyip 

                               “Biliyorum

                                     Haber yollamak istersin sevdiceğine,

                                          Haber almak ondan…

                                             Hadi dilek tut” 

                                                  Diyerek,

                                                       Uzattı ellerime.

Zaman nasıl geçmişti anlamamıştık. Fallaşmıştık iki kadın sahilde, dost olmuştuk. Bilinmeyen bir nedenle…

Topladı baklaları  yerden “ nazar değmesin sevdanıza “ deyip mavi taşı verdi.Arkası dönük söyleniyordu hala….

                                           “Ben hep bu saatler buralardayım

                                                  Sıkılırsan gelirsin artık…

                                                     Sağlıcakla kal! ..emi

                                                         Haa bak, Unutmadan söyleyeyim

                                                            Üzülme! 

                                               Üç vadeye kalmadan

                                            Arayacak seni sevdiceğin,

                                         Arayacak….

Geceye karıştı sesi.

   Kaybolurken gözden.

      Sevdasıyla büyüdü gölgesi

          Falcı kadın giderken……..

Az kalsın unutuyordum Sevdiğim...Bu gün hüzünlenip vapurlara iskeleden

                        Ağlamadım…

                            Ağlamadım Sevdiğim.

                                 Koşmadım,

                                       Kaçırdığım son otobüsün peşinden….

                                                                                               Leyla Işık

                                                                                     Warner Robins-Georgia', 'Akşam vakti seninle sensiz indim sahile…bir demet çiçek aldım, uzattım hiç    tanmadığım birine. Önce şaşkın şaşkın  baktı…sonra aldı. Kokus...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/falci-kadin-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüleyicisin', 'buyuleyicisin-sibel-oner-qsb2e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BÜYÜLEYİCİSİN			

				

				

Bak bugünde bitti				

Can çekişmelerle				

Bu can çekişmeler				

Senin bana verdiğin				

Tatlı ''merhaba'' sözün				

				

Bak bugünde geçti				

Doluydu huzursuzluklarla				

Huzursuzluğun kaynağı				

Senin kalbimde yakan				

Tatlı bir bakışın				

				

Bak bugünde sona erdi				

Heyecan doluydu kalbim				

Bu heyecan ki; 				

Senin güleryüzün				

Benimse çaresizliğim				

				

Hep seni düşledim günlerce				

Düşündüm seni ulaşmak zor				

Nelere icat etmedi ki; bu fani dünya				

İki sevgiliyi birleştirmek dışında				

				

				

				Sibel ÖNER', 'BÜYÜLEYİCİSİN			 				 				 Bak bugünde bitti				 Can çekişmelerle				 Bu can çekişmeler				 Senin bana verdiğin				 Tatlı ''merhaba'' sözün			...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/buyuleyicisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluğa Dair', 'dostluga-dair-sibel-oner-4pxzc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'DOSTLUĞA DAİR				

					

					

Bas beni bağrına orada öleyim					

Dosta giden yola kurban olayım					

Sarmaşıklar gibi dostu sarayım					

İnanmazsan bana yol beni beni					

					

Ne güzeldir sevmesi canın bir canı					

Samimi,muhabbet dolu olanı					

Hiçbir zaman sevmem yalanı dolanı					

İnanmazsan taştan taşa çal beni					

					

Dostluğun tadında lezzet tatmadım					

Muhabbetli dile acı katmadım					

Dostmu düşmana atıp tutmadım					

İnanmazsan bana sal beni beni					

					

Gayem tüm dostluğa bir el olmaktır.					

Ne insanı kırmak,nede saymaktır.					

İlhami emelim huzur bulmaktır.					

Kötü bir emel ise kov beni beni					

					

				Sibel ÖNER', 'DOSTLUĞA DAİR				 					 					 Bas beni bağrına orada öleyim					 Dosta giden yola kurban olayım					 Sarmaşıklar gibi dostu sarayım					 İna...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dostluga-dair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tencerem', 'tencerem-tuncay-akdeniz-02eiu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mutlu günler için aldım

Süsün bozdular tencerem

Mutfaklarda esir kaldın

Yüzün çizdiler tencerem

Bir zamanlar vardı havan

Bazen yağlı bazen yavan

İçine yok yemek koyan

Safa dizdiler tencerem

İçinde yemeğin çoktu

Üç öğünde karnım toktu

İkram etmek bize haktı

İçin süzdüler tencerem

Yoksullar adın sayıklar

Yiyin,yiyin doyun toklar

Bizde eşit değil haklar

Dibin kazdılar tencerem

Ne tat kaldı nede lezzet

Yoksulu fakiri gözet

Bayramlarda bir tike et

Seni üzdüler tencerem

Tuncay sesin kim dinliyor

Tok aç halinden bilmiyor

İçi boştur çok çınlıyor

Sana kızdılar tencerem

				07.07.2000

 Not:Bu şiir türkiye gazetesinde yayınlandı 15 ekim 2001', 'Mutlu günler için aldım Süsün bozdular tencerem Mutfaklarda esir kaldın Yüzün çizdiler tencerem Bir zamanlar vardı havan Bazen yağlı bazen y...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tencerem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Kırmızı', 'kan-kirmizi-i-lknur-cekici-7jekc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kan kırmızı benim aşkım

Ne vazgeçilir

Sanki şarap

Durdukça güzelleşir

Ne katlanılır

Çiledir

Dolaşır damarda

Uyuşturur zamanla

Filizlenir olmaz hayaller aklında

Ya beklersin güzelleşir

Ya çeker gider

Yaşarsın doyunca

Sabır ister

Şevkat ister bir gonca

Dayanması zor

Kırılır bir hata''yla

Yürek gerekir

Aşkı yaşatmaya

               (16.03.2005/GÖYNÜK)', 'Kan kırmızı benim aşkım Ne vazgeçilir Sanki şarap Durdukça güzelleşir Ne katlanılır Çiledir Dolaşır damarda Uyuşturur zamanla Filizlenir olm...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kan-kirmizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum Firarda', 'ruhum-firarda-suleyman-kaya-vhxbo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aranıyorum düşlerde

altbilinçte yer edindim,

hülyalı dünyalarda

suçum, sevmek..

Aşka giden yoldan yürümek,

çocukluk benimki,

doğal yaşama biçimi.

İştye...! 

Tercihimi sevgiden yana koymuşum

engelleri aşma saflığı,

sınırsız dünya,sınıfsız toplum! 

İdealim...

Konulan her yasak,

menfaat,çıkar

değil mi? 

kodese konulmuş sevgi ve doğal  yaşama aşkımla! 

Sevdasına kapıldığım her güzele,

''sahipli'' dediler.

Din,töre, örf adet,gelenek görenek,

denilen süni setler koydular.

Ruhum firarda,düşlerde geziniyorum

özgür ruhlara saf tutum,

sınırsız aşklar  içinde,

geziniyorum korkusuzca! 

Gerçek hayattaki bir göz bakışına,

ama sade,bir bakış,

ve derin duygulardan gelen,

aşka,sevgiye bile izin yok dediler.

                    16.03.2005', 'Aranıyorum düşlerde altbilinçte yer edindim, hülyalı dünyalarda suçum, sevmek.. Aşka giden yoldan yürümek, çocukluk benimki, doğal yaşama bi...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Kaya']::text[], 8.5, '{"poet":"Süleyman Kaya","poet_slug":"suleyman-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ruhum-firarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit', 'umit-sibel-oner-h4ar6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ÜMİT			

				

Dostluk,sevgi,aşk				

Yaşamı çekilir kılan				

Anlam veren de bunlar değilmi zaten? 				

Paylaşmak				

Yarınları; umutları; 				

Zamanı geldiğinde acıyı				

İnsanlığa paylaşmak				

Ve gururunla				

Yaşamayı sürdürmek				

Ebediyete ölümsüzleşmek				

				

				

			Sibel ÖNER', 'ÜMİT			 				 Dostluk,sevgi,aşk				 Yaşamı çekilir kılan				 Anlam veren de bunlar değilmi zaten? 				 Paylaşmak				 Yarınları; umutları; 			...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umit-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Zormuş Meğer', 'cok-zormus-meger-murat-demir-ym44j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geceleri sensiz sabahlaması

Çok zormuş birtanem çok zormuş meğer

Andıkça gözlerden yaş damlaması

Çok zormuş sevdiğim çok zormuş meğer

Cansız resimleri karıştırması

Geceyi gündüzle yarıştırması

Sevdayı hasretle barıştırması

Çok zormuş canparçam çok zormuş meğer

Issız duvarlara bakıp durması

Olur olmazlarla hayal kurması

Hele birde seni elden sorması

Çok zormuş narparçam çok zormuş meğer

Gün geçtikçe derde dert eklemesi

Yaralı yüreğin yol beklemesi

Özlemin içimi dürtüklemesi

Çok zormuş ayparçam çok zormuş meğer!', 'Geceleri sensiz sabahlaması Çok zormuş birtanem çok zormuş meğer Andıkça gözlerden yaş damlaması Çok zormuş sevdiğim çok zormuş meğer Cansız...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-zormus-meger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Senden Bana', 'eger-senden-bana-sibel-oner-9tzw7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'EĞER SENDEN BANA					

						

Eğer birgün bir dileğimi sorarlarsa bana						

Sevenleri anlatacağım sana						

Ayrılanları hatırlatacağım sana						

Anıları anımsatacağım sana						

Vaad ettiğim bir ömrü geri alacağım senden						

Eğer bir gün hatırımı sorarsan bana						

Mutlu olduğumu söyleyeceğim sana						

Tatlı tebessümle güleceğim sana						

Dönüp bakmadan gideceğim arkama						

Eğer birgün bir yerlerde karşılaşırsak seninle						

Ak tükürüğü boyayacağım suratına						

Lanetleyeceğim,gelmişine,geçmişine						

Kan kusturacağım imalı bakışlarımla						

Nefret ettğimi anlayacaksın işte o an						

Eğer bir gün seviyorum dersen bana						

Vazgeç bu sevdadan derim sana						

Günün birinde sevmiştim dersen bana						

Unut geçmişi yalancı derim sana						

Hiç unutmayacağım desen bile bana						

Yemin etme çarpılırsın derim sana						

Hiç unutamadım deme sakın bana						

Sadece kendini aldatırsın derim sana						

Eğer çaresizim duy beni diyorsan bana						

Duymuyorum işitme özürlüğüm ben derim sana						

Görüyormusun bitap düştüm desen bana						

Dimdik ayakta durabilen bir amayım derim sana						

Hiç unutmayacağım diye söz versen bile bana						

Yalancı olma derim sana						

Mutlu günler bizi bekliyor gel desen bana						

''Mutlu''kelimesini öğren,içine sindir derim sana						

						

						

					Sibel ÖNER', 'EĞER SENDEN BANA					 						 Eğer birgün bir dileğimi sorarlarsa bana						 Sevenleri anlatacağım sana						 Ayrılanları hatırlatacağım sana...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/eger-senden-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cana Ölüm Yok', 'cana-olum-yok-zulfikar-yapar-kaleli-lsuyo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Dudağında sitem, gözlerinde nem 

Bir garip tepede, kar oluverdin.

Gönlünün varlığı kederle elem

Sonsuzluk yolunda ar oluverdin.

Yollar birbirine düğümlü, ekli

Karar, kararsızlık içinde saklı

Aşkın şevki kırıldıkça sürekli

Yürekte küllenmiş kor oluverdin.

Hayal sahnesinde düşünce kaynar

Teri boncuk boncuk gözleri yanar

Gece gölgesiyle körebe oynar

Gündüz gök yüzünde har oluverdin.

Doğduğundan beri deli divane

Dolaştı, hesapsız kitapsız bu ne

Kafa delidolu bir tımarhane

Yasaklara inat var oluverdin.

Öfke pınarının sadık vurgunu

Çaresiz derenin suya dargını

Günahkâr gözlerin hasret yorgunu

Rütbesiz, payesiz yâr oluverdin.', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Dudağında sitem, gözlerinde nem  Bir garip tepede, kar oluverdin. Gönlünün varlığı kederl...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cana-olum-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Sonu', 'yagmur-sonu-sibel-oner-qi6ff', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YAĞMUR SONU				

					

					

Yağmur sonu gündoğar ya yeniden					

Sende öyle sarıverdin derdinle					

Çağlar özüm yandığında yeniden					

Gamlı gözüm gam içti gözlerinden					

					

Yağmur sonu gündoğar ya yeniden					

Sende öyle doğdun gamlı gönlüme					

Altın oklar yükselirken ufuktan					

Usul usul seher yeli eserken					

Çöreklendin göz yaşımın seline					

Derdin ile bir kez daha yeniden					

					

Yağmur sonu gündoğar ya yeniden					

Yanan gönlüm kaynaştırdı bir bulut					

Derya oldu her damlada bir umut					

Beyhude ömrüme ağladım ancak					

Başımı soran ellerim kar,ocak					

Sözde güldüm,ah u zorla çağladım					

Talan olan baharıma ağladım					

					

Yağmur sonu gündoğar ya yeniden					

Ağlayarak sıkıntıdan arındım					

Hakkın dergahına erip sığındım					

Eren gönül kabesinde arındım					

Yağmur sonu gündoğar ya yeniden					

Acılarla yundum yundum duruldum					

					

					

				Sibel ÖNER', 'YAĞMUR SONU				 					 					 Yağmur sonu gündoğar ya yeniden					 Sende öyle sarıverdin derdinle					 Çağlar özüm yandığında yeniden					 Gam...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yagmur-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Olur', 'gece-olur-i-smail-ozabaci-h7xcm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece olur

Gölgeler uzar sokaklarda

Gitmeye meyleder gönül

Terkedilesi bir sevgili olur

Zaman

Hangi gece vardır ki

Ay yarım kalmasın 

Sevdiğinden ayrılmış bir yürek gibi

Hangi gece vardır ki

Geçmez zaman

Ve 

Hangi gece varsın ki zaten yanımda

Ellerini tutamam', 'Gece olur Gölgeler uzar sokaklarda Gitmeye meyleder gönül Terkedilesi bir sevgili olur Zaman Hangi gece vardır ki Ay yarım kalmasın  Sevdiği...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gece-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzün Geliyor Aklıma', 'yuzun-geliyor-aklima-i-smail-ozabaci-bgrj9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüzün geliyor bir gece, pencereye yaklaşıyorum, şehrin ışıkları mı daha çok yıldızları mı diye geçiriyorum içimden, kime benzetsem seni diye geçiriyorum içimden,

Bir dilek tutuyorum bir yıldız kaysa da olur bir ışık sönse de şehirden

Aklıma yüzün geliyor bir gece, hava soğuk mu soğuk, ellerimde öyle, biliyorum senin ellerinde üşüyor uzaklarda bir yerde, nasıl ısıtsam bilemiyorum, içim çıtırdıyor bir sobanın çıtırtısına karışarak kaloriferli bir yerde

Bir gece yüzün geliyor aklıma, ne yapsam bilemiyorum, elim ayağıma dolaşıyor, bu duyguyu bir yerlerden hatırlıyorum, çıkaramıyorum (16 ocak)

Geliyor...yüzün bir gece aklıma anımsıyorum, sen benim sevdiğim kadınsın, sen benim geçmeyen yıllarımsın, acımsın, sevincimsin, gözyaşım ve tebessümümsün, hıçkırığım ve gülümsememsin, iyi ve kötü yanlarımsın, ışığım ve karanlığımsın,

Uykusuzluğum ve en tatlı rüyamsın, kavgamsın,sözlerimsin,şiirimsin

Bilmem neden kayboluyor yüzün yavaşça benliğimden,anımsıyorum  bir senden çok çektim bir de faranjitimden...', 'Yüzün geliyor bir gece, pencereye yaklaşıyorum, şehrin ışıkları mı daha çok yıldızları mı diye geçiriyorum içimden, kime benzetsem seni diye...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yuzun-geliyor-aklima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Ne Mi Olmalı', 'siir-ne-mi-olmali-fedai-gunaydin-hwre4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şiir şiir mi oluyor imgeyle mimgeyle

yoksa üslup mu deniyor şiire

halkı mı yazacağım halka mı

size ne yahu ben yazıyorsam

ölmemek delirmemek için 

senin ne hakkın var benim

hayat hakkımı eleştirmeye', 'şiir şiir mi oluyor imgeyle mimgeyle yoksa üslup mu deniyor şiire halkı mı yazacağım halka mı size ne yahu ben yazıyorsam ölmemek delirmemek...', ARRAY['Türk Edebiyatı','Şiir','Fedai Günaydın']::text[], 8.5, '{"poet":"Fedai Günaydın","poet_slug":"fedai-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/siir-ne-mi-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Aksın Gözyaşların', 'birak-aksin-gozyaslarin-sahin-erturk-5tlw7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman,mekan tanımayan

Yaşlı,genci ayırmayan

Aşk bulaşmış yüreğine

Bırak aksın gözyaşların

Hiç yerinde duramazsın

Yalvar,yakar kovamazsın

Aşk bulaşmış yüreğine

Bırak aksın gözyaşların

Sıkıntıdan patlıyorsan

İçin,için ağlıyorsan

Boşver,koyver akıp gitsin

Bırak aksın gözyaşların

Hiç saklama ondan,bundan

Adam ölmez ağlamaktan

Seviyorsan içten,kalp ten

Bırak aksın gözyaşların

Oda seni seviyorsa

Hasretinle yanıyorsa

Ağladığın biliyorsa

Bırak aksın gözyaşların

(16.03.2005-Yeni)', 'Zaman,mekan tanımayan Yaşlı,genci ayırmayan Aşk bulaşmış yüreğine Bırak aksın gözyaşların Hiç yerinde duramazsın Yalvar,yakar kovamazsın Aşk...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/birak-aksin-gozyaslarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse seni tanımadı', 'kimse-seni-tanimadi-hasim-koc-ichxf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oturduğun mahalleden

Dün geçerken içim yandı

Kaç kapıyı çaldım sordum

Kimse seni tanımadı

Gözlerini tarif ettim

Adresi bu sokak dedim

Birini sana benzettim

Döndü beni tanımadı

Bütün mahalleyi gezdim

Görüşürüz belki dedim

Kayıp ilanları verdim

Yine seni bulamadim

Gözlerini tarif ettim

Adresi bu sokak dedim

Birini sana benzettim

Döndü beni tanımadı', 'Oturduğun mahalleden Dün geçerken içim yandı Kaç kapıyı çaldım sordum Kimse seni tanımadı Gözlerini tarif ettim Adresi bu sokak dedim Birini...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimse-seni-tanimadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Malum olsun arapgiri özledim', 'malum-olsun-arapgiri-ozledim-hasim-koc-rplxi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arapgirin dağlarında keklikler öter

Mor sümbüllü bizim bağlar burnumda tüter

Çekilecek gibi değil bu hasret yeter

Malum olsun Arapgiri özledim

Kaynarcada gözde soğuk su içem

Öğlelik tepesi yol ver sılama geçem

Güzellerden güzel birde yar seçem

Malum olsun Arapgiri özledim

Şırayı kaynatıp bastık dökende

Dam başında yatarken şafak sökende

Kara gözlerinden yaşlar dökende

Malum olsun Arapgiri özledim

26-10-2001-cuma-saat-11.30-istanbul', 'Arapgirin dağlarında keklikler öter Mor sümbüllü bizim bağlar burnumda tüter Çekilecek gibi değil bu hasret yeter Malum olsun Arapgiri özled...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/malum-olsun-arapgiri-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bölünen Yürek...', 'bolunen-yurek-zulfikar-yapar-kaleli-dszo3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Sırtında süvari  şahlanır atlar

İlahi gelecek benim diyerek

Rahmet yağmayınca yeşermez otlar

Günde bin parçaya bölünür yürek

Aşk olup gönlümü bürüyemiyor

Beni ardı sıra sürüyemiyor

Doğru yol bu diyor yürüyemiyor

Kul menzile ermez kendin överek

Kişi yatmak ile zafer bulamaz

Nasipsizler bu meydanda kalamaz

Sohbetler hevesle, nefisle olmaz

Muhabbet Rahman''a boyun eğerek

Doğru dürüst olmak muratsa şayet

Sözü doğru söyle,  gayet açık  net

Namaz kıl, oruç tut, haccı tamam et

Sonu cennet olmaz haram yiyerek', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Sırtında süvari  şahlanır atlar İlahi gelecek benim diyerek Rahmet yağmayınca yeşermez ot...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bolunen-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huyu güzelim', 'huyu-guzelim-tuncay-akdeniz-35o0o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklımı aldın başımdan

Baktıkça boyu güzelim

Yedi yıl koştum peşinden

Sahili koyu güzelim

İlk bahardır ova düzü

Dört mevsim yaşatır yazı

Sevgi dolu güler yüzü 

Yıldızı ayı güzelim

Gönlümdeki yüce dağsın

Kalbimde solmayan gülsün

Hayat dolu bir ömürsün

Kahvesi çayı güzelim

Candan sadıktır eşine

Hamarattır her  işine

Sanki bal katmış aşına

Çorbası suyu güzelim

İnsanlara ayrım yapmaz

İyilikten geri durmaz

Hürmetinde kusur yapmaz

Yaptıkça huyu güzelim

Çınar gibi açmış dalsın

Sabah esen serin yelsin

Tuncay''ın  sevdiği yarsın

Sevdikçe soyu güzelim

				

				12.11.1978', 'Aklımı aldın başımdan Baktıkça boyu güzelim Yedi yıl koştum peşinden Sahili koyu güzelim İlk bahardır ova düzü Dört mevsim yaşatır yazı Sevg...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/huyu-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok tatlıdır malatyanın mişmişi', 'cok-tatlidir-malatyanin-mismisi-hasim-koc-7sgjl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şekermidir şerbetmidir balmıdır

Ne tatlıdır malatyanın mişmişi

Tadı güzel sanki cennet yemişi

Çok tatlıdır malatyanın mişmişi

Rengi altın reyhasi mis

İster taze ister pişmiş

Tatmış yemiş kim sevmemiş

Çok tatlıdır malatyanın mişmişi

Kaysı deriz mişmiş deriz bal deriz

Gece gündüz yaz kış demez hep yeriz

Nere gitsek kaysımızı överiz

Çok meşhurdur malatyanın mişmişi

Güzele güzellik katar

Yiyenin sıhhati artar

Değerini altınla tartar

Ne değerlidir malatyanın mişmişi

Dalda durur nazlı gelin

Koparmak istemez elin

Yenince şifadır bilin

Ne tatlıdır malatyanın mişmişi

İstanbul-16-10-2001-salı-saat-11.30', 'Şekermidir şerbetmidir balmıdır Ne tatlıdır malatyanın mişmişi Tadı güzel sanki cennet yemişi Çok tatlıdır malatyanın mişmişi Rengi altın re...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cok-tatlidir-malatyanin-mismisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşimiz bu', 'i-simiz-bu-tuncay-akdeniz-4cvm5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Asırlardır insanlığı bilmedik

Biz sıcak yuvayı buza çevirdik

Yalakalık yaptık riya söyledik

Bire sıfır ektik yüze çevirdik

Sevgi dedik kırdık gülün dalını

Çiçekten toplardı arı balını 

Sandıksız beşiksiz koyduk gelini

Yaktık ormanları köze çevirdik

Tabiattır insanlığın aynası

Bak doğanın güzel temiz havası

Toprak mahlûkatın rahmet kapısı

Değiştik rengini boza çevirdik

Sevgi saygı hürmet terbiye bizde

İnsanlık öğretir başkası sözde

Görmeden boyandık rezalet dizde

Oğlanı bezedik kıza çevirdik

Tuncay söyler kimse tutmaz sözünü

Türk olan Türk değişmez ki özünü

Hain gösterir mi gerçek yüzünü

Şaşırdık hedefi öze çevirdik

					10.09.2004', 'Asırlardır insanlığı bilmedik Biz sıcak yuvayı buza çevirdik Yalakalık yaptık riya söyledik Bire sıfır ektik yüze çevirdik Sevgi dedik kırdı...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/isimiz-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğul', 'ogul-tuncay-akdeniz-1vjyz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bağımı bahçemi bıraktım sana

Ben çiçeğim sende arısın oğul

Aylar senin olsun gün yeter bana

Sende muradına eresin oğul

Temelsiz binayı temelden ördüm

Bu temel üstüne binamı kurdum

Esen rüzgarlara ben karşı durdum 

Kendine bir yuva kurasın oğul

Bu dağları deldim taşları söktüm

Elim nasırlaştı belimi büktüm

Varımı yoğumu ben sana döktüm

Sende gerçekleri göresin oğul

Fidan gibi daldan dala aşlandım

İplik gibi tezgahlarda işlendim

Ayaklarım gitmez şimdi yaşlandım

Elime bir baston veresin oğul

Aslından utanma akraban ara

El yamandır seni düşürür dara

Dost kazan şerefin artırmaz para

Dökülen yaşımı silesin oğul

Tuncay im derdimi ben sana açtım

Açıldım ummana gezdim dolaştım

Gemi gibi bir limana yanaştım

Mezarıma bir taş dikesin oğul

						21.01.1998', 'Bağımı bahçemi bıraktım sana Ben çiçeğim sende arısın oğul Aylar senin olsun gün yeter bana Sende muradına eresin oğul Temelsiz binayı temel...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ogul-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Türkçe konuşalım türkçe!', 'a-turkce-konusalim-turkce-mikdat-bal-0yxbo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oynanmasın lisanımla

Oynanmasın insanımla

Gece gündüz her anım la 

Meşgalemdir gündüz gece

Her kelime hece hece

Türkçe konuşalım Türkçe

İki dil iki insanmış

Bazıları böyle sanmış

Biri Hans biri Hasanmış

Biri cüce biri yüce

Adam gibi Türk ol önce

Türkçe konuşalım Türkçe

Türkçe benim anadilim

Yok olmasın dilim dilim

Canım,cananım, sevgilim

Hem manaca hem şekilce

Denebilir hangi dilce? 

Türkçe konuşalım Türkçe

Türkçe benim anadilim

Sahip çıktım sana dilim

Gönlüm senden yana dilim

Dinle, kültürüm iç ice

Kayıp eden hâli nice

Türkçe konuşalım Türkçe

Mikdat der ki sanat dilim

Din, kültüre kanat dilim

Bir çoğuna inat dilim

Önce Türkçe, sonra Türkçe

Savunurum seni Türkçe

Türkçe konuşalım Türkçe! 

Ozan Mikdadi', 'Oynanmasın lisanımla Oynanmasın insanımla Gece gündüz her anım la  Meşgalemdir gündüz gece Her kelime hece hece Türkçe konuşalım Türkçe İki ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/a-turkce-konusalim-turkce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzu Ve İsyan...', 'arzu-ve-i-syan-zulfikar-yapar-kaleli-curt3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çile denen boz kısrağa binmişim

Bir mum ışığına doğru giderim...

Savaşmışım durulmuşum dinmişim

Yüzümü yer gözlerimi diderim...

Karanlık gecenin bilmecesini

Çözdükçe dolaştı ilk hecesini

Yaşattım korkunun en yücesini

Beynimi kemirir, ruhumu yerim...

Zerre ışık verdi gözüne girdim

Şavkında dolandım, şevkine erdim

El aleme baktım, kendimi gördüm

Artık aynalara isyan ederim...

Gündüz hayalimde, gece düşümde

Ecinni güruhu gezer peşimde

Susuz pınarımda, yavan aşımda

Sıkıntıyı mesken tutmuş kaderim...

Ölüm fermanımı kendim yazarım

Kusurlu kendime kendim kızarım

Kendi mezarımı kendim kazarım

‘Ben’ düşmansa işte budur kederim...', 'Çile denen boz kısrağa binmişim Bir mum ışığına doğru giderim... Savaşmışım durulmuşum dinmişim Yüzümü yer gözlerimi diderim... Karanlık gec...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arzu-ve-isyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-i-brahim-kilinc-q34gq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Derin karmaşık duygularla kararsa da ufuklar, 

Ellerinde güzelleşti nice guruplar. 

Nedensiz sıkıştırmasın aşkı gururlar.

İçindeki sevdaya gönlünce bir komut ver,

Zindan olsada sonu kardır yaşanan günler.', 'Derin karmaşık duygularla kararsa da ufuklar,  Ellerinde güzelleşti nice guruplar.  Nedensiz sıkıştırmasın aşkı gururlar. İçindeki sevdaya g...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/deniz-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erit Yüregim.', 'erit-yuregim-i-shak-ozlu-p8ecw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her sevgiye açık kapın,

Sevgi üzerine kurulu yapın.

Acının hamuruda sevgi degil mi,

Var birazda acıya tapın.

Güzeli görür mest olursun,

Kin çeker sevgi solursun.

Nefretde sevgi dogumu degil mi,

Erit yüregim erdem bulursun.

Vakit daraldı durma davran.

Tatlı canım yoluna kurban.

Kötülügü sevgiye döndür,

Olsun,Alem sana hayran.

Yüregimsin bana benden yakın,

Hesap günü açılınca kapın,

Sevgi hamurunda hapsettigin kötülük,

Ruhlar aleminde olsun yüzakın.', 'Her sevgiye açık kapın, Sevgi üzerine kurulu yapın. Acının hamuruda sevgi degil mi, Var birazda acıya tapın. Güzeli görür mest olursun, Kin ...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/erit-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarasalar', 'yarasalar-kemal-cakir-nbqbz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalvara yakara el pençe iş başına geldiler

Önceleri canla başla sahip çıktılar Devlet Malına

Bu uğurda pek çok suçsuz kuzu da yediler

Sonra da dediler “bir Devlete bir bana” 

Ne var ne yok başladılar  zevkle yemeye

Bakmadılar aç milyonların bükmesine boyun

…… derim de dilim varmıyor söylemeye	

Bir türlü kurutamadık köklerini it soyunun.

Silip süpürüyorlar ellerine her geçeni

Biraz artarsa uyuyamıyorlar geceleri

Yok mu bu memleketin başka iş bileni

Nereden bulup getirirler bilmem bu..leri.

Saf- saf inanır büyük bir kısmımız onlara

Pohpohlar şişiririz ki daha fazla yesinler

Bir kısmımız bilerek düşeriz arkalarına

İstediğimiz belli  “ biraz da bize versinler”.

İç çekerek bakar çoğumuz bu olup bitene

Dedikleri, “adalet verecek mutlaka cezalarını”

Bir fırsat verseler önce benim gibi birine

Yediklerine pişman eder yırtarım ağızlarını.

Bilmeyiz çoğumuz ne güçlüdür onlar

Ne kanun, ne ahlaki değerler vız gelir

Bilirler ki çoğu kez lehlerinedir kanıtlar

Ama yine de bir şeyler onları ele verir.

Bitmez bu talan mevsimi güneş kavurmadıkça

Üstelik suç sadece onlarda değil, biraz da bizdedir; 

Çünkü şımarıyorlar  biz onları adamdan saydıkça

Oysa onlar adam değil..konan kara sineklerdir.', 'Yalvara yakara el pençe iş başına geldiler Önceleri canla başla sahip çıktılar Devlet Malına Bu uğurda pek çok suçsuz kuzu da yediler Sonra ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yarasalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gibi..', 'ben-gibi-sibel-oner-gabkx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BEN GİBİ.....			

				

Ben doğdum doğalı çilekeşim				

İstesemde.....				

Kaderimmiş alın yazımmış diye				

Çekemiyorum işte.....				

Biliyorum ki; insanın kaderi kendi elinde				

Birazcık da alın yazısında katkısı varmış				

Bence nasiptir diye bir şey yoktur				

Olan tek şey insanın belleğindedir.				

İnsan eğer iyi bir kişilik kazanmış sa				

Bu ona ömrü boyunca yeter				

Alınması gereken derslerden nasibini almışsa				

Küpe olur kulağına				

Aşktan yana şansı açıksa				

Yaşamayı ölümden daha çok önem verir				

Bir insanın gönlü ferahsa				

Zıttını da kendini de sever sayar				

Kendini ispatlayabildiyse eğer				

Ömrü boyunca kendini korur				

Gerçeklerin iç yüzünü görebiliyorsa				

Algılıyor,yaşıyor,duyuyordur				

Haksızlığa boyun eğiyorsa				

İnsa olmadığını gösterir				

Karşı çıkıyor direnebiliyorsa				

Eski tabuları yıkıyordur				

Hayatın cilvelerine alıştıysa				

Yaşamayı devam ediyordur				

Tıpki BEN GİBİ......				

				

			Sibel ÖNER', 'BEN GİBİ.....			 				 Ben doğdum doğalı çilekeşim				 İstesemde.....				 Kaderimmiş alın yazımmış diye				 Çekemiyorum işte.....				 Biliyor...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ben-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim', 'i-sterdim-sibel-oner-0dini', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İSTERDİM				

					

İsterdim bir evim olsun					

Bahçesinin havuzu dolsun					

Yerler çimlensin					

Renk renk leylaklar açsın					

Oturduğum yeri sarmaşıklar sarsın					

Gökyüzü hep bir ömür bıyu aydınlansın					

Uçsun arılar,kelebekler,kuşlar					

Koşsun özgürce çocuklarım					

Gelsin canımdan çok sevdiğim eşim					

Sevsinler hayatı karınca kaderince					

Mulu olsunlar gönüllerince					

Kucaklasınlar beni ebediyen					

Sarsınlar kollarında sımsıkı					

Bırakmasınlar sonsuza					

Varsınlar yanımda her zaman					

Kelebek dile gelse de konuşsa					

O bari ben yanındayım dese					

Güller eğilip kulağıma fısıldasa					

Bana seninleyim dese					

Arılar görsede anlasa halimi					

Bana teselli verse					

Aşkımın sevgisini verse de					

Seeni seviyorum dese					

					

				Sibel ÖNER', 'İSTERDİM				 					 İsterdim bir evim olsun					 Bahçesinin havuzu dolsun					 Yerler çimlensin					 Renk renk leylaklar açsın					 Oturduğum...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/isterdim-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünüyorum', 'dusunuyorum-sibel-oner-qafhz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'DÜŞÜNÜYORUM				

					

Bir şeye çok ağlamıştım bundan beş ay önce					

Şimdi yine ağlıyorum,beş ay öncesi gibi					

Seviyormuyum ki ben hep ağlamayı					

İster istemez devam ediyor,gözyaşlarım akmaya					

Sanki içimden birşeyler kopup gidiyor					

Ölmek daha iyi olmalı çekmekten					

Sırtımdaki yük,günden güne dahada ağırlaşıyor					

Atamıyorum bu yükü,çırpınmam çaresiz					

Ölümü düşünüyorum,her an her gece					

Ümidim kalmadı,yaşamak için					

Ölümü hissediyorum,canımda kanımda					

Yaşamak haram bana çaresizlik					

Her yanım sızım sızım sızlıyor					

Kulakkarım işitmiyor duymuyor					

Yaram günden güne büyüyor					

Bitmiyor ızdıraplarım,dertlerim					

Sevmiyorum artık hiç birşeyi					

Sevemiyorum yaşamayı,insanları					

Yaşamak zindan oldu bana					

Ölüm baş tacım oldu bundan sonra					

Ne güzel şey şu ölüm					

Sessiz,sakin,çilesiz,beklentisiz					

Kimse seni artık dokunamaz					

Unutulup gidersi anılarınla					

Yılda bir yada birkaç defa					

Adın geçer iyi insanların dilinda					

İşte ÖLÜM					

Olup olacağı bu kadar					

Düşünüyorum da.......					

					

				Sibel ÖNER', 'DÜŞÜNÜYORUM				 					 Bir şeye çok ağlamıştım bundan beş ay önce					 Şimdi yine ağlıyorum,beş ay öncesi gibi					 Seviyormuyum ki ben hep a...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dusunuyorum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünüyorummmmm', 'dusunuyorummmmm-sibel-oner-lhb1l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'DÜŞÜNÜYORUM				

					

Bir yer düşünüyorum çok uzaklarda					

Kimseler olmamalı yanımda					

Açmalıyım eski defterimi					

Ayırmalıyım pozitif,negatifleri					

					

Bir oda düşünüyorum loş yerde					

İçinde sen,ben olmalıyım					

Açıp aşk defterimizi					

Karar vermeliyiz hedefimizi					

					

Bir orman düşünüyorum ıssız yerde					

Sadece uçan kuşlar kelebekler,çiçekler					

Uzanmalıyım onların yanına					

Dertleşmeliyim özgürce					

					

Bir pınar düşünüyorum uzak tepede					

Alsın beni kollarına sürüklese					

Bedenimi buz gibi sarıp					

Hissetmeliyim ölümün soğuk nefesini					

					

				Sibel ÖNER', 'DÜŞÜNÜYORUM				 					 Bir yer düşünüyorum çok uzaklarda					 Kimseler olmamalı yanımda					 Açmalıyım eski defterimi					 Ayırmalıyım poziti...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dusunuyorummmmm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
